insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Psalms', 19, 104, 29, 'When You hide Your face, they are terrified; when You take away their breath, they die and return to dust.'),
  ('BSB', 'Psalms', 19, 104, 30, 'When You send Your Spirit, they are created, and You renew the face of the earth.'),
  ('BSB', 'Psalms', 19, 104, 31, 'May the glory of the LORD endure forever; may the LORD rejoice in His works.'),
  ('BSB', 'Psalms', 19, 104, 32, 'He looks on the earth, and it trembles; He touches the mountains, and they smolder.'),
  ('BSB', 'Psalms', 19, 104, 33, 'I will sing to the LORD all my life; I will sing praise to my God while I have my being.'),
  ('BSB', 'Psalms', 19, 104, 34, 'May my meditation be pleasing to Him, for I rejoice in the LORD.'),
  ('BSB', 'Psalms', 19, 104, 35, 'May sinners vanish from the earth and the wicked be no more. Bless the LORD, O my soul. Hallelujah!'),
  ('BSB', 'Psalms', 19, 105, 1, 'Give thanks to the LORD, call upon His name; make known His deeds among the nations.'),
  ('BSB', 'Psalms', 19, 105, 2, 'Sing to Him, sing praises to Him; tell of all His wonders.'),
  ('BSB', 'Psalms', 19, 105, 3, 'Glory in His holy name; let the hearts of those who seek the LORD rejoice.'),
  ('BSB', 'Psalms', 19, 105, 4, 'Seek out the LORD and His strength; seek His face always.'),
  ('BSB', 'Psalms', 19, 105, 5, 'Remember the wonders He has done, His marvels, and the judgments He has pronounced,'),
  ('BSB', 'Psalms', 19, 105, 6, 'O offspring of His servant Abraham, O sons of Jacob, His chosen ones.'),
  ('BSB', 'Psalms', 19, 105, 7, 'He is the LORD our God; His judgments carry throughout the earth.'),
  ('BSB', 'Psalms', 19, 105, 8, 'He remembers His covenant forever, the word He ordained for a thousand generations—'),
  ('BSB', 'Psalms', 19, 105, 9, 'the covenant He made with Abraham, and the oath He swore to Isaac.'),
  ('BSB', 'Psalms', 19, 105, 10, 'He confirmed it to Jacob as a decree, to Israel as an everlasting covenant:'),
  ('BSB', 'Psalms', 19, 105, 11, '“I will give you the land of Canaan as the portion of your inheritance.”'),
  ('BSB', 'Psalms', 19, 105, 12, 'When they were few in number, few indeed, and strangers in the land,'),
  ('BSB', 'Psalms', 19, 105, 13, 'they wandered from nation to nation, from one kingdom to another.'),
  ('BSB', 'Psalms', 19, 105, 14, 'He let no man oppress them; He rebuked kings on their behalf:'),
  ('BSB', 'Psalms', 19, 105, 15, '“Do not touch My anointed ones! Do no harm to My prophets!”'),
  ('BSB', 'Psalms', 19, 105, 16, 'He called down famine on the land and cut off all their supplies of food.'),
  ('BSB', 'Psalms', 19, 105, 17, 'He sent a man before them— Joseph, sold as a slave.'),
  ('BSB', 'Psalms', 19, 105, 18, 'They bruised his feet with shackles and placed his neck in irons,'),
  ('BSB', 'Psalms', 19, 105, 19, 'until his prediction came true and the word of the LORD proved him right.'),
  ('BSB', 'Psalms', 19, 105, 20, 'The king sent and released him; the ruler of peoples set him free.'),
  ('BSB', 'Psalms', 19, 105, 21, 'He made him master of his household, ruler over all his substance,'),
  ('BSB', 'Psalms', 19, 105, 22, 'to instruct his princes as he pleased and teach his elders wisdom.'),
  ('BSB', 'Psalms', 19, 105, 23, 'Then Israel entered Egypt; Jacob dwelt in the land of Ham.'),
  ('BSB', 'Psalms', 19, 105, 24, 'And the LORD made His people very fruitful, more numerous than their foes,'),
  ('BSB', 'Psalms', 19, 105, 25, 'whose hearts He turned to hate His people, to conspire against His servants.'),
  ('BSB', 'Psalms', 19, 105, 26, 'He sent Moses His servant, and Aaron, whom He had chosen.'),
  ('BSB', 'Psalms', 19, 105, 27, 'They performed His miraculous signs among them, and wonders in the land of Ham.'),
  ('BSB', 'Psalms', 19, 105, 28, 'He sent darkness, and it became dark— yet they defied His words.'),
  ('BSB', 'Psalms', 19, 105, 29, 'He turned their waters to blood and caused their fish to die.'),
  ('BSB', 'Psalms', 19, 105, 30, 'Their land teemed with frogs, even in their royal chambers.'),
  ('BSB', 'Psalms', 19, 105, 31, 'He spoke, and insects swarmed— gnats throughout their country.'),
  ('BSB', 'Psalms', 19, 105, 32, 'He gave them hail for rain, with lightning throughout their land.'),
  ('BSB', 'Psalms', 19, 105, 33, 'He struck their vines and fig trees and shattered the trees of their country.'),
  ('BSB', 'Psalms', 19, 105, 34, 'He spoke, and the locusts came— young locusts without number.'),
  ('BSB', 'Psalms', 19, 105, 35, 'They devoured every plant in their land and consumed the produce of their soil.'),
  ('BSB', 'Psalms', 19, 105, 36, 'Then He struck all the firstborn in their land, the firstfruits of all their vigor.'),
  ('BSB', 'Psalms', 19, 105, 37, 'He brought Israel out with silver and gold, and none among His tribes stumbled.'),
  ('BSB', 'Psalms', 19, 105, 38, 'Egypt was glad when they departed, for the dread of Israel had fallen on them.'),
  ('BSB', 'Psalms', 19, 105, 39, 'He spread a cloud as a covering and a fire to light up the night.'),
  ('BSB', 'Psalms', 19, 105, 40, 'They asked, and He brought quail and satisfied them with the bread of heaven.'),
  ('BSB', 'Psalms', 19, 105, 41, 'He opened a rock, and water gushed out; it flowed like a river in the desert.'),
  ('BSB', 'Psalms', 19, 105, 42, 'For He remembered His holy promise to Abraham His servant.'),
  ('BSB', 'Psalms', 19, 105, 43, 'He brought forth His people with rejoicing, His chosen with shouts of joy.'),
  ('BSB', 'Psalms', 19, 105, 44, 'He gave them the lands of the nations, that they might inherit the fruit of others’ labor,'),
  ('BSB', 'Psalms', 19, 105, 45, 'that they might keep His statutes and obey His laws. Hallelujah!'),
  ('BSB', 'Psalms', 19, 106, 1, 'Hallelujah! Give thanks to the LORD, for He is good; His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 106, 2, 'Who can describe the mighty acts of the LORD or fully proclaim His praise?'),
  ('BSB', 'Psalms', 19, 106, 3, 'Blessed are those who uphold justice, who practice righteousness at all times.'),
  ('BSB', 'Psalms', 19, 106, 4, 'Remember me, O LORD, in Your favor to Your people; visit me with Your salvation,'),
  ('BSB', 'Psalms', 19, 106, 5, 'that I may see the prosperity of Your chosen ones, and rejoice in the gladness of Your nation, and give glory with Your inheritance.'),
  ('BSB', 'Psalms', 19, 106, 6, 'We have sinned like our fathers; we have done wrong and acted wickedly.'),
  ('BSB', 'Psalms', 19, 106, 7, 'Our fathers in Egypt did not grasp Your wonders or remember Your abundant kindness; but they rebelled by the sea, there at the Red Sea.'),
  ('BSB', 'Psalms', 19, 106, 8, 'Yet He saved them for the sake of His name, to make His power known.'),
  ('BSB', 'Psalms', 19, 106, 9, 'He rebuked the Red Sea, and it dried up; He led them through the depths as through a desert.'),
  ('BSB', 'Psalms', 19, 106, 10, 'He saved them from the hand that hated them; He redeemed them from the hand of the enemy.'),
  ('BSB', 'Psalms', 19, 106, 11, 'The waters covered their foes; not one of them remained.'),
  ('BSB', 'Psalms', 19, 106, 12, 'Then they believed His promises and sang His praise.'),
  ('BSB', 'Psalms', 19, 106, 13, 'Yet they soon forgot His works and failed to wait for His counsel.'),
  ('BSB', 'Psalms', 19, 106, 14, 'They craved intensely in the wilderness and tested God in the desert.'),
  ('BSB', 'Psalms', 19, 106, 15, 'So He granted their request, but sent a wasting disease upon them.'),
  ('BSB', 'Psalms', 19, 106, 16, 'In the camp they envied Moses, as well as Aaron, the holy one of the LORD.'),
  ('BSB', 'Psalms', 19, 106, 17, 'The earth opened up and swallowed Dathan; it covered the assembly of Abiram.'),
  ('BSB', 'Psalms', 19, 106, 18, 'Then fire blazed through their company; flames consumed the wicked.'),
  ('BSB', 'Psalms', 19, 106, 19, 'At Horeb they made a calf and worshiped a molten image.'),
  ('BSB', 'Psalms', 19, 106, 20, 'They exchanged their Glory for the image of a grass-eating ox.'),
  ('BSB', 'Psalms', 19, 106, 21, 'They forgot God their Savior, who did great things in Egypt,'),
  ('BSB', 'Psalms', 19, 106, 22, 'wondrous works in the land of Ham, and awesome deeds by the Red Sea.'),
  ('BSB', 'Psalms', 19, 106, 23, 'So He said He would destroy them— had not Moses His chosen one stood before Him in the breach to divert His wrath from destroying them.'),
  ('BSB', 'Psalms', 19, 106, 24, 'They despised the pleasant land; they did not believe His promise.'),
  ('BSB', 'Psalms', 19, 106, 25, 'They grumbled in their tents and did not listen to the voice of the LORD.'),
  ('BSB', 'Psalms', 19, 106, 26, 'So He raised His hand and swore to cast them down in the wilderness,'),
  ('BSB', 'Psalms', 19, 106, 27, 'to disperse their offspring among the nations and scatter them throughout the lands.'),
  ('BSB', 'Psalms', 19, 106, 28, 'They yoked themselves to Baal of Peor and ate sacrifices offered to lifeless gods.'),
  ('BSB', 'Psalms', 19, 106, 29, 'So they provoked the LORD to anger with their deeds, and a plague broke out among them.'),
  ('BSB', 'Psalms', 19, 106, 30, 'But Phinehas stood and intervened, and the plague was restrained.'),
  ('BSB', 'Psalms', 19, 106, 31, 'It was credited to him as righteousness for endless generations to come.'),
  ('BSB', 'Psalms', 19, 106, 32, 'At the waters of Meribah they angered the LORD, and trouble came to Moses because of them.'),
  ('BSB', 'Psalms', 19, 106, 33, 'For they rebelled against His Spirit, and Moses spoke rashly with his lips.'),
  ('BSB', 'Psalms', 19, 106, 34, 'They did not destroy the peoples as the LORD had commanded them,'),
  ('BSB', 'Psalms', 19, 106, 35, 'but they mingled with the nations and adopted their customs.'),
  ('BSB', 'Psalms', 19, 106, 36, 'They worshiped their idols, which became a snare to them.'),
  ('BSB', 'Psalms', 19, 106, 37, 'They sacrificed their sons and their daughters to demons.'),
  ('BSB', 'Psalms', 19, 106, 38, 'They shed innocent blood— the blood of their sons and daughters, whom they sacrificed to the idols of Canaan, and the land was polluted with blood.'),
  ('BSB', 'Psalms', 19, 106, 39, 'They defiled themselves by their actions and prostituted themselves by their deeds.'),
  ('BSB', 'Psalms', 19, 106, 40, 'So the anger of the LORD burned against His people, and He abhorred His own inheritance.'),
  ('BSB', 'Psalms', 19, 106, 41, 'He delivered them into the hand of the nations, and those who hated them ruled over them.'),
  ('BSB', 'Psalms', 19, 106, 42, 'Their enemies oppressed them, and subdued them under their hand.'),
  ('BSB', 'Psalms', 19, 106, 43, 'Many times He rescued them, but they were bent on rebellion and sank down in their iniquity.'),
  ('BSB', 'Psalms', 19, 106, 44, 'Nevertheless He heard their cry; He took note of their distress.'),
  ('BSB', 'Psalms', 19, 106, 45, 'And He remembered His covenant with them, and relented by the abundance of His loving devotion.'),
  ('BSB', 'Psalms', 19, 106, 46, 'He made them objects of compassion to all who held them captive.'),
  ('BSB', 'Psalms', 19, 106, 47, 'Save us, O LORD our God, and gather us from the nations, that we may give thanks to Your holy name, that we may glory in Your praise.'),
  ('BSB', 'Psalms', 19, 106, 48, 'Blessed be the LORD, the God of Israel, from everlasting to everlasting. Let all the people say, “Amen!” Hallelujah!'),
  ('BSB', 'Psalms', 19, 107, 1, 'Give thanks to the LORD, for He is good; His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 107, 2, 'Let the redeemed of the LORD say so, whom He has redeemed from the hand of the enemy'),
  ('BSB', 'Psalms', 19, 107, 3, 'and gathered from the lands, from east and west, from north and south.'),
  ('BSB', 'Psalms', 19, 107, 4, 'Some wandered in desert wastelands, finding no path to a city in which to dwell.'),
  ('BSB', 'Psalms', 19, 107, 5, 'They were hungry and thirsty; their soul fainted within them.'),
  ('BSB', 'Psalms', 19, 107, 6, 'Then they cried out to the LORD in their trouble, and He delivered them from their distress.'),
  ('BSB', 'Psalms', 19, 107, 7, 'He led them on a straight path to reach a city where they could live.'),
  ('BSB', 'Psalms', 19, 107, 8, 'Let them give thanks to the LORD for His loving devotion and His wonders to the sons of men.'),
  ('BSB', 'Psalms', 19, 107, 9, 'For He satisfies the thirsty and fills the hungry with good things.'),
  ('BSB', 'Psalms', 19, 107, 10, 'Some sat in darkness and in the shadow of death, prisoners in affliction and chains,'),
  ('BSB', 'Psalms', 19, 107, 11, 'because they rebelled against the words of God and despised the counsel of the Most High.'),
  ('BSB', 'Psalms', 19, 107, 12, 'He humbled their hearts with hard labor; they stumbled, and there was no one to help.'),
  ('BSB', 'Psalms', 19, 107, 13, 'Then they cried out to the LORD in their trouble, and He saved them from their distress.'),
  ('BSB', 'Psalms', 19, 107, 14, 'He brought them out of darkness and the shadow of death and broke away their chains.'),
  ('BSB', 'Psalms', 19, 107, 15, 'Let them give thanks to the LORD for His loving devotion and His wonders to the sons of men.'),
  ('BSB', 'Psalms', 19, 107, 16, 'For He has broken down the gates of bronze and cut through the bars of iron.'),
  ('BSB', 'Psalms', 19, 107, 17, 'Fools, in their rebellious ways, and through their iniquities, suffered affliction.'),
  ('BSB', 'Psalms', 19, 107, 18, 'They loathed all food and drew near to the gates of death.'),
  ('BSB', 'Psalms', 19, 107, 19, 'Then they cried out to the LORD in their trouble, and He saved them from their distress.'),
  ('BSB', 'Psalms', 19, 107, 20, 'He sent forth His word and healed them; He rescued them from the Pit.'),
  ('BSB', 'Psalms', 19, 107, 21, 'Let them give thanks to the LORD for His loving devotion and His wonders to the sons of men.'),
  ('BSB', 'Psalms', 19, 107, 22, 'Let them offer sacrifices of thanksgiving and declare His works with rejoicing.'),
  ('BSB', 'Psalms', 19, 107, 23, 'Others went out to sea in ships, conducting trade on the mighty waters.'),
  ('BSB', 'Psalms', 19, 107, 24, 'They saw the works of the LORD, and His wonders in the deep.'),
  ('BSB', 'Psalms', 19, 107, 25, 'For He spoke and raised a tempest that lifted the waves of the sea.'),
  ('BSB', 'Psalms', 19, 107, 26, 'They mounted up to the heavens, then sunk to the depths; their courage melted in their anguish.'),
  ('BSB', 'Psalms', 19, 107, 27, 'They reeled and staggered like drunkards, and all their skill was useless.'),
  ('BSB', 'Psalms', 19, 107, 28, 'Then they cried out to the LORD in their trouble, and He brought them out of their distress.'),
  ('BSB', 'Psalms', 19, 107, 29, 'He calmed the storm to a whisper, and the waves of the sea were hushed.'),
  ('BSB', 'Psalms', 19, 107, 30, 'They rejoiced in the silence, and He guided them to the harbor they desired.'),
  ('BSB', 'Psalms', 19, 107, 31, 'Let them give thanks to the LORD for His loving devotion and His wonders to the sons of men.'),
  ('BSB', 'Psalms', 19, 107, 32, 'Let them exalt Him in the assembly of the people and praise Him in the council of the elders.'),
  ('BSB', 'Psalms', 19, 107, 33, 'He turns rivers into deserts, springs of water into thirsty ground,'),
  ('BSB', 'Psalms', 19, 107, 34, 'and fruitful land into fields of salt, because of the wickedness of its dwellers.'),
  ('BSB', 'Psalms', 19, 107, 35, 'He turns a desert into pools of water and a dry land into flowing springs.'),
  ('BSB', 'Psalms', 19, 107, 36, 'He causes the hungry to settle there, that they may establish a city in which to dwell.'),
  ('BSB', 'Psalms', 19, 107, 37, 'They sow fields and plant vineyards that yield a fruitful harvest.'),
  ('BSB', 'Psalms', 19, 107, 38, 'He blesses them, and they multiply greatly; He does not let their herds diminish.'),
  ('BSB', 'Psalms', 19, 107, 39, 'When they are decreased and humbled by oppression, evil, and sorrow,'),
  ('BSB', 'Psalms', 19, 107, 40, 'He pours out contempt on the nobles and makes them wander in a trackless wasteland.'),
  ('BSB', 'Psalms', 19, 107, 41, 'But He lifts the needy from affliction and increases their families like flocks.'),
  ('BSB', 'Psalms', 19, 107, 42, 'The upright see and rejoice, and all iniquity shuts its mouth.'),
  ('BSB', 'Psalms', 19, 107, 43, 'Let him who is wise pay heed to these things and consider the loving devotion of the LORD.'),
  ('BSB', 'Psalms', 19, 108, 1, 'My heart is steadfast, O God; I will sing and make music with all my being.'),
  ('BSB', 'Psalms', 19, 108, 2, 'Awake, O harp and lyre! I will awaken the dawn.'),
  ('BSB', 'Psalms', 19, 108, 3, 'I will praise You, O LORD, among the nations; I will sing Your praises among the peoples.'),
  ('BSB', 'Psalms', 19, 108, 4, 'For Your loving devotion extends beyond the heavens, and Your faithfulness reaches to the clouds.'),
  ('BSB', 'Psalms', 19, 108, 5, 'Be exalted, O God, above the heavens; may Your glory cover all the earth.'),
  ('BSB', 'Psalms', 19, 108, 6, 'Respond and save us with Your right hand, that Your beloved may be delivered.'),
  ('BSB', 'Psalms', 19, 108, 7, 'God has spoken from His sanctuary: “I will triumph! I will parcel out Shechem and apportion the Valley of Succoth.'),
  ('BSB', 'Psalms', 19, 108, 8, 'Gilead is Mine, and Manasseh is Mine; Ephraim is My helmet, Judah is My scepter.'),
  ('BSB', 'Psalms', 19, 108, 9, 'Moab is My washbasin; upon Edom I toss My sandal; over Philistia I shout in triumph.”'),
  ('BSB', 'Psalms', 19, 108, 10, 'Who will bring me to the fortified city? Who will lead me to Edom?'),
  ('BSB', 'Psalms', 19, 108, 11, 'Have You not rejected us, O God? Will You no longer march out, O God, with our armies?'),
  ('BSB', 'Psalms', 19, 108, 12, 'Give us aid against the enemy, for the help of man is worthless.'),
  ('BSB', 'Psalms', 19, 108, 13, 'With God we will perform with valor, and He will trample our enemies.'),
  ('BSB', 'Psalms', 19, 109, 1, 'O God of my praise, be not silent.'),
  ('BSB', 'Psalms', 19, 109, 2, 'For wicked and deceitful mouths open against me; they speak against me with lying tongues.'),
  ('BSB', 'Psalms', 19, 109, 3, 'They surround me with hateful words and attack me without cause.'),
  ('BSB', 'Psalms', 19, 109, 4, 'In return for my love they accuse me, but I am a man of prayer.'),
  ('BSB', 'Psalms', 19, 109, 5, 'They repay me evil for good, and hatred for my love.'),
  ('BSB', 'Psalms', 19, 109, 6, 'Set over him a wicked man; let an accuser stand at his right hand.'),
  ('BSB', 'Psalms', 19, 109, 7, 'When he is tried, let him be found guilty, and may his prayer be regarded as sin.'),
  ('BSB', 'Psalms', 19, 109, 8, 'May his days be few; may another take his position.'),
  ('BSB', 'Psalms', 19, 109, 9, 'May his children be fatherless and his wife a widow.'),
  ('BSB', 'Psalms', 19, 109, 10, 'May his children wander as beggars, seeking sustenance far from their ruined homes.'),
  ('BSB', 'Psalms', 19, 109, 11, 'May the creditor seize all he owns, and strangers plunder the fruits of his labor.'),
  ('BSB', 'Psalms', 19, 109, 12, 'May there be no one to extend kindness to him, and no one to favor his fatherless children.'),
  ('BSB', 'Psalms', 19, 109, 13, 'May his descendants be cut off; may their name be blotted out from the next generation.'),
  ('BSB', 'Psalms', 19, 109, 14, 'May the iniquity of his fathers be remembered before the LORD, and the sin of his mother never be blotted out.'),
  ('BSB', 'Psalms', 19, 109, 15, 'May their sins always remain before the LORD, that He may cut off their memory from the earth.'),
  ('BSB', 'Psalms', 19, 109, 16, 'For he never thought to show kindness, but pursued the poor and needy and brokenhearted, even to their death.'),
  ('BSB', 'Psalms', 19, 109, 17, 'The cursing that he loved, may it fall on him; the blessing in which he refused to delight, may it be far from him.'),
  ('BSB', 'Psalms', 19, 109, 18, 'The cursing that he wore like a coat, may it soak into his body like water, and into his bones like oil.'),
  ('BSB', 'Psalms', 19, 109, 19, 'May it be like a robe wrapped about him, like a belt tied forever around him.'),
  ('BSB', 'Psalms', 19, 109, 20, 'May this be the LORD’s reward to my accusers, to those who speak evil against me.'),
  ('BSB', 'Psalms', 19, 109, 21, 'But You, O GOD, the Lord, deal kindly with me for the sake of Your name; deliver me by the goodness of Your loving devotion.'),
  ('BSB', 'Psalms', 19, 109, 22, 'For I am poor and needy; my heart is wounded within me.'),
  ('BSB', 'Psalms', 19, 109, 23, 'I am fading away like a lengthening shadow; I am shaken off like a locust.'),
  ('BSB', 'Psalms', 19, 109, 24, 'My knees are weak from fasting, and my body grows lean and gaunt.'),
  ('BSB', 'Psalms', 19, 109, 25, 'I am an object of scorn to my accusers; when they see me, they shake their heads.'),
  ('BSB', 'Psalms', 19, 109, 26, 'Help me, O LORD my God; save me according to Your loving devotion.'),
  ('BSB', 'Psalms', 19, 109, 27, 'Let them know that this is Your hand, that You, O LORD, have done it.'),
  ('BSB', 'Psalms', 19, 109, 28, 'Though they curse, You will bless. When they rise up, they will be put to shame, but Your servant will rejoice.'),
  ('BSB', 'Psalms', 19, 109, 29, 'May my accusers be clothed with disgrace; may they wear their shame like a robe.'),
  ('BSB', 'Psalms', 19, 109, 30, 'With my mouth I will thank the LORD profusely; I will praise Him in the presence of many.'),
  ('BSB', 'Psalms', 19, 109, 31, 'For He stands at the right hand of the needy one, to save him from the condemners of his soul.'),
  ('BSB', 'Psalms', 19, 110, 1, 'The LORD said to my Lord: “Sit at My right hand until I make Your enemies a footstool for Your feet.”'),
  ('BSB', 'Psalms', 19, 110, 2, 'The LORD extends Your mighty scepter from Zion: “Rule in the midst of Your enemies.”'),
  ('BSB', 'Psalms', 19, 110, 3, 'Your people shall be willing on Your day of battle. Arrayed in holy splendor, from the womb of the dawn, to You belongs the dew of Your youth.'),
  ('BSB', 'Psalms', 19, 110, 4, 'The LORD has sworn and will not change His mind: “You are a priest forever in the order of Melchizedek.”'),
  ('BSB', 'Psalms', 19, 110, 5, 'The Lord is at Your right hand; He will crush kings in the day of His wrath.'),
  ('BSB', 'Psalms', 19, 110, 6, 'He will judge the nations, heaping up the dead; He will crush the leaders far and wide.'),
  ('BSB', 'Psalms', 19, 110, 7, 'He will drink from the brook by the road; therefore He will lift up His head.'),
  ('BSB', 'Psalms', 19, 111, 1, 'Hallelujah! I will give thanks to the LORD with all my heart in the council of the upright and in the assembly.'),
  ('BSB', 'Psalms', 19, 111, 2, 'Great are the works of the LORD; they are pondered by all who delight in them.'),
  ('BSB', 'Psalms', 19, 111, 3, 'Splendid and majestic is His work; His righteousness endures forever.'),
  ('BSB', 'Psalms', 19, 111, 4, 'He has caused His wonders to be remembered; the LORD is gracious and compassionate.'),
  ('BSB', 'Psalms', 19, 111, 5, 'He provides food for those who fear Him; He remembers His covenant forever.'),
  ('BSB', 'Psalms', 19, 111, 6, 'He has shown His people the power of His works by giving them the inheritance of the nations.'),
  ('BSB', 'Psalms', 19, 111, 7, 'The works of His hands are truth and justice; all His precepts are trustworthy.'),
  ('BSB', 'Psalms', 19, 111, 8, 'They are upheld forever and ever, enacted in truth and uprightness.'),
  ('BSB', 'Psalms', 19, 111, 9, 'He has sent redemption to His people; He has ordained His covenant forever; holy and awesome is His name.'),
  ('BSB', 'Psalms', 19, 111, 10, 'The fear of the LORD is the beginning of wisdom; all who follow His precepts gain rich understanding. His praise endures forever!'),
  ('BSB', 'Psalms', 19, 112, 1, 'Hallelujah! Blessed is the man who fears the LORD, who greatly delights in His commandments.'),
  ('BSB', 'Psalms', 19, 112, 2, 'His descendants will be mighty in the land; the generation of the upright will be blessed.'),
  ('BSB', 'Psalms', 19, 112, 3, 'Wealth and riches are in his house, and his righteousness endures forever.'),
  ('BSB', 'Psalms', 19, 112, 4, 'Light dawns in the darkness for the upright— for the gracious, compassionate, and righteous.'),
  ('BSB', 'Psalms', 19, 112, 5, 'It is well with the man who is generous and lends freely, whose affairs are guided by justice.'),
  ('BSB', 'Psalms', 19, 112, 6, 'Surely he will never be shaken; the righteous man will be remembered forever.'),
  ('BSB', 'Psalms', 19, 112, 7, 'He does not fear bad news; his heart is steadfast, trusting in the LORD.'),
  ('BSB', 'Psalms', 19, 112, 8, 'His heart is assured; he does not fear, until he looks in triumph on his foes.'),
  ('BSB', 'Psalms', 19, 112, 9, 'He has scattered abroad his gifts to the poor; his righteousness endures forever; his horn will be lifted high in honor.'),
  ('BSB', 'Psalms', 19, 112, 10, 'The wicked man will see and be grieved; he will gnash his teeth and waste away; the desires of the wicked will perish.'),
  ('BSB', 'Psalms', 19, 113, 1, 'Hallelujah! Give praise, O servants of the LORD; praise the name of the LORD.'),
  ('BSB', 'Psalms', 19, 113, 2, 'Blessed be the name of the LORD both now and forevermore.'),
  ('BSB', 'Psalms', 19, 113, 3, 'From where the sun rises to where it sets, the name of the LORD is praised.'),
  ('BSB', 'Psalms', 19, 113, 4, 'The LORD is exalted over all the nations, His glory above the heavens.'),
  ('BSB', 'Psalms', 19, 113, 5, 'Who is like the LORD our God, the One enthroned on high?'),
  ('BSB', 'Psalms', 19, 113, 6, 'He humbles Himself to behold the heavens and the earth.'),
  ('BSB', 'Psalms', 19, 113, 7, 'He raises the poor from the dust and lifts the needy from the dump'),
  ('BSB', 'Psalms', 19, 113, 8, 'to seat them with nobles, with the princes of His people.'),
  ('BSB', 'Psalms', 19, 113, 9, 'He settles the barren woman in her home as a joyful mother to her children. Hallelujah!'),
  ('BSB', 'Psalms', 19, 114, 1, 'When Israel departed from Egypt, the house of Jacob from a people of foreign tongue,'),
  ('BSB', 'Psalms', 19, 114, 2, 'Judah became God’s sanctuary, and Israel His dominion.'),
  ('BSB', 'Psalms', 19, 114, 3, 'The sea observed and fled; the Jordan turned back;'),
  ('BSB', 'Psalms', 19, 114, 4, 'the mountains skipped like rams, the hills like lambs.'),
  ('BSB', 'Psalms', 19, 114, 5, 'Why was it, O sea, that you fled, O Jordan, that you turned back,'),
  ('BSB', 'Psalms', 19, 114, 6, 'O mountains, that you skipped like rams, O hills, like lambs?'),
  ('BSB', 'Psalms', 19, 114, 7, 'Tremble, O earth, at the presence of the Lord, at the presence of the God of Jacob,'),
  ('BSB', 'Psalms', 19, 114, 8, 'who turned the rock into a pool, the flint into a fountain of water!'),
  ('BSB', 'Psalms', 19, 115, 1, 'Not to us, O LORD, not to us, but to Your name be the glory, because of Your loving devotion, because of Your faithfulness.'),
  ('BSB', 'Psalms', 19, 115, 2, 'Why should the nations say, “Where is their God?”'),
  ('BSB', 'Psalms', 19, 115, 3, 'Our God is in heaven; He does as He pleases.'),
  ('BSB', 'Psalms', 19, 115, 4, 'Their idols are silver and gold, made by the hands of men.'),
  ('BSB', 'Psalms', 19, 115, 5, 'They have mouths, but cannot speak; they have eyes, but cannot see;'),
  ('BSB', 'Psalms', 19, 115, 6, 'they have ears, but cannot hear; they have noses, but cannot smell;'),
  ('BSB', 'Psalms', 19, 115, 7, 'they have hands, but cannot feel; they have feet, but cannot walk; they cannot even clear their throats.'),
  ('BSB', 'Psalms', 19, 115, 8, 'Those who make them become like them, as do all who trust in them.'),
  ('BSB', 'Psalms', 19, 115, 9, 'O Israel, trust in the LORD! He is their help and shield.'),
  ('BSB', 'Psalms', 19, 115, 10, 'O house of Aaron, trust in the LORD! He is their help and shield.'),
  ('BSB', 'Psalms', 19, 115, 11, 'You who fear the LORD, trust in the LORD! He is their help and shield.'),
  ('BSB', 'Psalms', 19, 115, 12, 'The LORD is mindful of us; He will bless us. He will bless the house of Israel; He will bless the house of Aaron;'),
  ('BSB', 'Psalms', 19, 115, 13, 'He will bless those who fear the LORD— small and great alike.'),
  ('BSB', 'Psalms', 19, 115, 14, 'May the LORD give you increase, both you and your children.'),
  ('BSB', 'Psalms', 19, 115, 15, 'May you be blessed by the LORD, the Maker of heaven and earth.'),
  ('BSB', 'Psalms', 19, 115, 16, 'The highest heavens belong to the LORD, but the earth He has given to mankind.'),
  ('BSB', 'Psalms', 19, 115, 17, 'It is not the dead who praise the LORD, nor any who descend into silence.'),
  ('BSB', 'Psalms', 19, 115, 18, 'But it is we who will bless the LORD, both now and forevermore. Hallelujah!'),
  ('BSB', 'Psalms', 19, 116, 1, 'I love the LORD, for He has heard my voice— my appeal for mercy.'),
  ('BSB', 'Psalms', 19, 116, 2, 'Because He has inclined His ear to me, I will call on Him as long as I live.'),
  ('BSB', 'Psalms', 19, 116, 3, 'The ropes of death entangled me; the anguish of Sheol overcame me; I was confronted by trouble and sorrow.'),
  ('BSB', 'Psalms', 19, 116, 4, 'Then I called on the name of the LORD: “O LORD, deliver my soul!”'),
  ('BSB', 'Psalms', 19, 116, 5, 'The LORD is gracious and righteous; our God is full of compassion.'),
  ('BSB', 'Psalms', 19, 116, 6, 'The LORD preserves the simplehearted; I was helpless, and He saved me.'),
  ('BSB', 'Psalms', 19, 116, 7, 'Return to your rest, O my soul, for the LORD has been good to you.'),
  ('BSB', 'Psalms', 19, 116, 8, 'For You have delivered my soul from death, my eyes from tears, my feet from stumbling.'),
  ('BSB', 'Psalms', 19, 116, 9, 'I will walk before the LORD in the land of the living.'),
  ('BSB', 'Psalms', 19, 116, 10, 'I believed, therefore I said, “I am greatly afflicted.”'),
  ('BSB', 'Psalms', 19, 116, 11, 'In my alarm I said, “All men are liars!”'),
  ('BSB', 'Psalms', 19, 116, 12, 'How can I repay the LORD for all His goodness to me?'),
  ('BSB', 'Psalms', 19, 116, 13, 'I will lift the cup of salvation and call on the name of the LORD.'),
  ('BSB', 'Psalms', 19, 116, 14, 'I will fulfill my vows to the LORD in the presence of all His people.'),
  ('BSB', 'Psalms', 19, 116, 15, 'Precious in the sight of the LORD is the death of His saints.'),
  ('BSB', 'Psalms', 19, 116, 16, 'Truly, O LORD, I am Your servant; I am Your servant, the son of Your maidservant; You have broken my bonds.'),
  ('BSB', 'Psalms', 19, 116, 17, 'I will offer to You a sacrifice of thanksgiving and call on the name of the LORD.'),
  ('BSB', 'Psalms', 19, 116, 18, 'I will fulfill my vows to the LORD in the presence of all His people,'),
  ('BSB', 'Psalms', 19, 116, 19, 'in the courts of the LORD’s house, in your midst, O Jerusalem. Hallelujah!'),
  ('BSB', 'Psalms', 19, 117, 1, 'Praise the LORD, all you nations! Extol Him, all you peoples!'),
  ('BSB', 'Psalms', 19, 117, 2, 'For great is His loving devotion toward us, and the faithfulness of the LORD endures forever. Hallelujah!'),
  ('BSB', 'Psalms', 19, 118, 1, 'Give thanks to the LORD, for He is good; His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 118, 2, 'Let Israel say, “His loving devotion endures forever.”'),
  ('BSB', 'Psalms', 19, 118, 3, 'Let the house of Aaron say, “His loving devotion endures forever.”'),
  ('BSB', 'Psalms', 19, 118, 4, 'Let those who fear the LORD say, “His loving devotion endures forever.”'),
  ('BSB', 'Psalms', 19, 118, 5, 'In my distress I called to the LORD, and He answered and set me free.'),
  ('BSB', 'Psalms', 19, 118, 6, 'The LORD is on my side; I will not be afraid. What can man do to me?'),
  ('BSB', 'Psalms', 19, 118, 7, 'The LORD is on my side; He is my helper. Therefore I will look in triumph on those who hate me.'),
  ('BSB', 'Psalms', 19, 118, 8, 'It is better to take refuge in the LORD than to trust in man.'),
  ('BSB', 'Psalms', 19, 118, 9, 'It is better to take refuge in the LORD than to trust in princes.'),
  ('BSB', 'Psalms', 19, 118, 10, 'All the nations surrounded me, but in the name of the LORD I cut them off.'),
  ('BSB', 'Psalms', 19, 118, 11, 'They surrounded me on every side, but in the name of the LORD I cut them off.'),
  ('BSB', 'Psalms', 19, 118, 12, 'They swarmed around me like bees, but they were extinguished like burning thorns; in the name of the LORD I cut them off.'),
  ('BSB', 'Psalms', 19, 118, 13, 'I was pushed so hard I was falling, but the LORD helped me.'),
  ('BSB', 'Psalms', 19, 118, 14, 'The LORD is my strength and my song, and He has become my salvation.'),
  ('BSB', 'Psalms', 19, 118, 15, 'Shouts of joy and salvation resound in the tents of the righteous: “The right hand of the LORD performs with valor!'),
  ('BSB', 'Psalms', 19, 118, 16, 'The right hand of the LORD is exalted! The right hand of the LORD performs with valor!”'),
  ('BSB', 'Psalms', 19, 118, 17, 'I will not die, but I will live and proclaim what the LORD has done.'),
  ('BSB', 'Psalms', 19, 118, 18, 'The LORD disciplined me severely, but He has not given me over to death.'),
  ('BSB', 'Psalms', 19, 118, 19, 'Open to me the gates of righteousness, that I may enter and give thanks to the LORD.'),
  ('BSB', 'Psalms', 19, 118, 20, 'This is the gate of the LORD; the righteous shall enter through it.'),
  ('BSB', 'Psalms', 19, 118, 21, 'I will give You thanks, for You have answered me, and You have become my salvation.'),
  ('BSB', 'Psalms', 19, 118, 22, 'The stone the builders rejected has become the cornerstone.'),
  ('BSB', 'Psalms', 19, 118, 23, 'This is from the LORD, and it is marvelous in our eyes.'),
  ('BSB', 'Psalms', 19, 118, 24, 'This is the day that the LORD has made; we will rejoice and be glad in it.'),
  ('BSB', 'Psalms', 19, 118, 25, 'O LORD, save us, we pray. We beseech You, O LORD, cause us to prosper!'),
  ('BSB', 'Psalms', 19, 118, 26, 'Blessed is he who comes in the name of the LORD. From the house of the LORD we bless you.'),
  ('BSB', 'Psalms', 19, 118, 27, 'The LORD is God; He has made His light to shine upon us. Bind the festal sacrifice with cords to the horns of the altar.'),
  ('BSB', 'Psalms', 19, 118, 28, 'You are my God, and I will give You thanks. You are my God, and I will exalt You.'),
  ('BSB', 'Psalms', 19, 118, 29, 'Give thanks to the LORD, for He is good; His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 119, 1, 'Blessed are those whose way is blameless, who walk in the Law of the LORD.'),
  ('BSB', 'Psalms', 19, 119, 2, 'Blessed are those who keep His testimonies and seek Him with all their heart.'),
  ('BSB', 'Psalms', 19, 119, 3, 'They do no iniquity; they walk in His ways.'),
  ('BSB', 'Psalms', 19, 119, 4, 'You have ordained Your precepts, that we should keep them diligently.'),
  ('BSB', 'Psalms', 19, 119, 5, 'Oh, that my ways were committed to keeping Your statutes!'),
  ('BSB', 'Psalms', 19, 119, 6, 'Then I would not be ashamed when I consider all Your commandments.'),
  ('BSB', 'Psalms', 19, 119, 7, 'I will praise You with an upright heart when I learn Your righteous judgments.'),
  ('BSB', 'Psalms', 19, 119, 8, 'I will keep Your statutes; do not utterly forsake me.'),
  ('BSB', 'Psalms', 19, 119, 9, 'How can a young man keep his way pure? By guarding it according to Your word.'),
  ('BSB', 'Psalms', 19, 119, 10, 'With all my heart I have sought You; do not let me stray from Your commandments.'),
  ('BSB', 'Psalms', 19, 119, 11, 'I have hidden Your word in my heart that I might not sin against You.'),
  ('BSB', 'Psalms', 19, 119, 12, 'Blessed are You, O LORD; teach me Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 13, 'With my lips I proclaim all the judgments of Your mouth.'),
  ('BSB', 'Psalms', 19, 119, 14, 'I rejoice in the way of Your testimonies as much as in all riches.'),
  ('BSB', 'Psalms', 19, 119, 15, 'I will meditate on Your precepts and regard Your ways.'),
  ('BSB', 'Psalms', 19, 119, 16, 'I will delight in Your statutes; I will not forget Your word.'),
  ('BSB', 'Psalms', 19, 119, 17, 'Deal bountifully with Your servant, that I may live and keep Your word.'),
  ('BSB', 'Psalms', 19, 119, 18, 'Open my eyes that I may see wondrous things from Your law.'),
  ('BSB', 'Psalms', 19, 119, 19, 'I am a stranger on the earth; do not hide Your commandments from me.'),
  ('BSB', 'Psalms', 19, 119, 20, 'My soul is consumed with longing for Your judgments at all times.'),
  ('BSB', 'Psalms', 19, 119, 21, 'You rebuke the arrogant— the cursed who stray from Your commandments.'),
  ('BSB', 'Psalms', 19, 119, 22, 'Remove my scorn and contempt, for I have kept Your testimonies.'),
  ('BSB', 'Psalms', 19, 119, 23, 'Though rulers sit and slander me, Your servant meditates on Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 24, 'Your testimonies are indeed my delight; they are my counselors.'),
  ('BSB', 'Psalms', 19, 119, 25, 'My soul cleaves to the dust; revive me according to Your word.'),
  ('BSB', 'Psalms', 19, 119, 26, 'I recounted my ways, and You answered me; teach me Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 27, 'Make clear to me the way of Your precepts; then I will meditate on Your wonders.'),
  ('BSB', 'Psalms', 19, 119, 28, 'My soul melts with sorrow; strengthen me according to Your word.'),
  ('BSB', 'Psalms', 19, 119, 29, 'Remove me from the path of deceit and graciously grant me Your law.'),
  ('BSB', 'Psalms', 19, 119, 30, 'I have chosen the way of truth; I have set Your ordinances before me.'),
  ('BSB', 'Psalms', 19, 119, 31, 'I cling to Your testimonies, O LORD; let me not be put to shame.'),
  ('BSB', 'Psalms', 19, 119, 32, 'I run in the path of Your commandments, for You will enlarge my heart.'),
  ('BSB', 'Psalms', 19, 119, 33, 'Teach me, O LORD, the way of Your statutes, and I will keep them to the end.'),
  ('BSB', 'Psalms', 19, 119, 34, 'Give me understanding that I may obey Your law, and follow it with all my heart.'),
  ('BSB', 'Psalms', 19, 119, 35, 'Direct me in the path of Your commandments, for there I find delight.'),
  ('BSB', 'Psalms', 19, 119, 36, 'Turn my heart to Your testimonies and not to covetous gain.'),
  ('BSB', 'Psalms', 19, 119, 37, 'Turn my eyes away from worthless things; revive me with Your word.'),
  ('BSB', 'Psalms', 19, 119, 38, 'Establish Your word to Your servant, to produce reverence for You.'),
  ('BSB', 'Psalms', 19, 119, 39, 'Turn away the disgrace I dread, for Your judgments are good.'),
  ('BSB', 'Psalms', 19, 119, 40, 'How I long for Your precepts! Revive me in Your righteousness.'),
  ('BSB', 'Psalms', 19, 119, 41, 'May Your loving devotion come to me, O LORD, Your salvation, according to Your promise.'),
  ('BSB', 'Psalms', 19, 119, 42, 'Then I can answer him who taunts, for I trust in Your word.'),
  ('BSB', 'Psalms', 19, 119, 43, 'Never take Your word of truth from my mouth, for I hope in Your judgments.'),
  ('BSB', 'Psalms', 19, 119, 44, 'I will always obey Your law, forever and ever.'),
  ('BSB', 'Psalms', 19, 119, 45, 'And I will walk in freedom, for I have sought Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 46, 'I will speak of Your testimonies before kings, and I will not be ashamed.'),
  ('BSB', 'Psalms', 19, 119, 47, 'I delight in Your commandments because I love them.'),
  ('BSB', 'Psalms', 19, 119, 48, 'I lift up my hands to Your commandments, which I love, and I meditate on Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 49, 'Remember Your word to Your servant, upon which You have given me hope.'),
  ('BSB', 'Psalms', 19, 119, 50, 'This is my comfort in affliction, that Your promise has given me life.'),
  ('BSB', 'Psalms', 19, 119, 51, 'The arrogant utterly deride me, but I do not turn from Your law.'),
  ('BSB', 'Psalms', 19, 119, 52, 'I remember Your judgments of old, O LORD, and in them I find comfort.'),
  ('BSB', 'Psalms', 19, 119, 53, 'Rage has taken hold of me because of the wicked who reject Your law.'),
  ('BSB', 'Psalms', 19, 119, 54, 'Your statutes are songs to me in the house of my pilgrimage.'),
  ('BSB', 'Psalms', 19, 119, 55, 'In the night, O LORD, I remember Your name, that I may keep Your law.'),
  ('BSB', 'Psalms', 19, 119, 56, 'This is my practice, for I obey Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 57, 'The LORD is my portion; I have promised to keep Your words.'),
  ('BSB', 'Psalms', 19, 119, 58, 'I have sought Your face with all my heart; be gracious to me according to Your promise.'),
  ('BSB', 'Psalms', 19, 119, 59, 'I considered my ways and turned my steps to Your testimonies.'),
  ('BSB', 'Psalms', 19, 119, 60, 'I hurried without hesitating to keep Your commandments.'),
  ('BSB', 'Psalms', 19, 119, 61, 'Though the ropes of the wicked bind me, I do not forget Your law.'),
  ('BSB', 'Psalms', 19, 119, 62, 'At midnight I rise to give You thanks for Your righteous judgments.'),
  ('BSB', 'Psalms', 19, 119, 63, 'I am a friend to all who fear You, and to those who keep Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 64, 'The earth is filled with Your loving devotion, O LORD; teach me Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 65, 'You are good to Your servant, O LORD, according to Your word.'),
  ('BSB', 'Psalms', 19, 119, 66, 'Teach me good judgment and knowledge, for I believe in Your commandments.'),
  ('BSB', 'Psalms', 19, 119, 67, 'Before I was afflicted, I went astray; but now I keep Your word.'),
  ('BSB', 'Psalms', 19, 119, 68, 'You are good, and You do what is good; teach me Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 69, 'Though the arrogant have smeared me with lies, I keep Your precepts with all my heart.'),
  ('BSB', 'Psalms', 19, 119, 70, 'Their hearts are hard and callous, but I delight in Your law.'),
  ('BSB', 'Psalms', 19, 119, 71, 'It was good for me to be afflicted, that I might learn Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 72, 'The law from Your mouth is more precious to me than thousands of pieces of gold and silver.'),
  ('BSB', 'Psalms', 19, 119, 73, 'Your hands have made me and fashioned me; give me understanding to learn Your commandments.'),
  ('BSB', 'Psalms', 19, 119, 74, 'May those who fear You see me and rejoice, for I have hoped in Your word.'),
  ('BSB', 'Psalms', 19, 119, 75, 'I know, O LORD, that Your judgments are righteous, and that in faithfulness You have afflicted me.'),
  ('BSB', 'Psalms', 19, 119, 76, 'May Your loving devotion comfort me, I pray, according to Your promise to Your servant.'),
  ('BSB', 'Psalms', 19, 119, 77, 'May Your compassion come to me, that I may live, for Your law is my delight.'),
  ('BSB', 'Psalms', 19, 119, 78, 'May the arrogant be put to shame for subverting me with a lie; I will meditate on Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 79, 'May those who fear You turn to me, those who know Your testimonies.'),
  ('BSB', 'Psalms', 19, 119, 80, 'May my heart be blameless in Your statutes, that I may not be put to shame.'),
  ('BSB', 'Psalms', 19, 119, 81, 'My soul faints for Your salvation; I wait for Your word.'),
  ('BSB', 'Psalms', 19, 119, 82, 'My eyes fail, looking for Your promise; I ask, “When will You comfort me?”'),
  ('BSB', 'Psalms', 19, 119, 83, 'Though I am like a wineskin dried up by smoke, I do not forget Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 84, 'How many days must Your servant wait? When will You execute judgment on my persecutors?'),
  ('BSB', 'Psalms', 19, 119, 85, 'The arrogant have dug pits for me in violation of Your law.'),
  ('BSB', 'Psalms', 19, 119, 86, 'All Your commandments are faithful; I am persecuted without cause—help me!'),
  ('BSB', 'Psalms', 19, 119, 87, 'They almost wiped me from the earth, but I have not forsaken Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 88, 'Revive me according to Your loving devotion, that I may obey the testimony of Your mouth.'),
  ('BSB', 'Psalms', 19, 119, 89, 'Your word, O LORD, is everlasting; it is firmly fixed in the heavens.'),
  ('BSB', 'Psalms', 19, 119, 90, 'Your faithfulness continues through all generations; You established the earth, and it endures.'),
  ('BSB', 'Psalms', 19, 119, 91, 'Your ordinances stand to this day, for all things are servants to You.'),
  ('BSB', 'Psalms', 19, 119, 92, 'If Your law had not been my delight, then I would have perished in my affliction.'),
  ('BSB', 'Psalms', 19, 119, 93, 'I will never forget Your precepts, for by them You have revived me.'),
  ('BSB', 'Psalms', 19, 119, 94, 'I am Yours; save me, for I have sought Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 95, 'The wicked wait to destroy me, but I will ponder Your testimonies.'),
  ('BSB', 'Psalms', 19, 119, 96, 'I have seen a limit to all perfection, but Your commandment is without limit.'),
  ('BSB', 'Psalms', 19, 119, 97, 'Oh, how I love Your law! All day long it is my meditation.'),
  ('BSB', 'Psalms', 19, 119, 98, 'Your commandments make me wiser than my enemies, for they are always with me.'),
  ('BSB', 'Psalms', 19, 119, 99, 'I have more insight than all my teachers, for Your testimonies are my meditation.'),
  ('BSB', 'Psalms', 19, 119, 100, 'I discern more than the elders, for I obey Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 101, 'I have kept my feet from every evil path, that I may keep Your word.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Psalms', 19, 119, 102, 'I have not departed from Your ordinances, for You Yourself have taught me.'),
  ('BSB', 'Psalms', 19, 119, 103, 'How sweet are Your words to my taste— sweeter than honey in my mouth!'),
  ('BSB', 'Psalms', 19, 119, 104, 'I gain understanding from Your precepts; therefore I hate every false way.'),
  ('BSB', 'Psalms', 19, 119, 105, 'Your word is a lamp to my feet and a light to my path.'),
  ('BSB', 'Psalms', 19, 119, 106, 'I have sworn and confirmed that I will keep Your righteous judgments.'),
  ('BSB', 'Psalms', 19, 119, 107, 'I am severely afflicted, O LORD; revive me through Your word.'),
  ('BSB', 'Psalms', 19, 119, 108, 'Accept the freewill offerings of my mouth, O LORD, and teach me Your judgments.'),
  ('BSB', 'Psalms', 19, 119, 109, 'I constantly take my life in my hands, yet I do not forget Your law.'),
  ('BSB', 'Psalms', 19, 119, 110, 'The wicked have set a snare for me, but I have not strayed from Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 111, 'Your testimonies are my heritage forever, for they are the joy of my heart.'),
  ('BSB', 'Psalms', 19, 119, 112, 'I have inclined my heart to perform Your statutes, even to the very end.'),
  ('BSB', 'Psalms', 19, 119, 113, 'The double-minded I despise, but Your law I love.'),
  ('BSB', 'Psalms', 19, 119, 114, 'You are my hiding place and my shield; I put my hope in Your word.'),
  ('BSB', 'Psalms', 19, 119, 115, 'Depart from me, you evildoers, that I may obey the commandments of my God.'),
  ('BSB', 'Psalms', 19, 119, 116, 'Sustain me as You promised, that I may live; let me not be ashamed of my hope.'),
  ('BSB', 'Psalms', 19, 119, 117, 'Uphold me, and I will be saved, that I may always regard Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 118, 'You reject all who stray from Your statutes, for their deceitfulness is in vain.'),
  ('BSB', 'Psalms', 19, 119, 119, 'All the wicked on earth You discard like dross; therefore I love Your testimonies.'),
  ('BSB', 'Psalms', 19, 119, 120, 'My flesh trembles in awe of You; I stand in fear of Your judgments.'),
  ('BSB', 'Psalms', 19, 119, 121, 'I have done what is just and right; do not leave me to my oppressors.'),
  ('BSB', 'Psalms', 19, 119, 122, 'Ensure Your servant’s well-being; do not let the arrogant oppress me.'),
  ('BSB', 'Psalms', 19, 119, 123, 'My eyes fail, looking for Your salvation, and for Your righteous promise.'),
  ('BSB', 'Psalms', 19, 119, 124, 'Deal with Your servant according to Your loving devotion, and teach me Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 125, 'I am Your servant; give me understanding, that I may know Your testimonies.'),
  ('BSB', 'Psalms', 19, 119, 126, 'It is time for the LORD to act, for they have broken Your law.'),
  ('BSB', 'Psalms', 19, 119, 127, 'Therefore I love Your commandments more than gold, even the purest gold.'),
  ('BSB', 'Psalms', 19, 119, 128, 'Therefore I admire all Your precepts and hate every false way.'),
  ('BSB', 'Psalms', 19, 119, 129, 'Wonderful are Your testimonies; therefore I obey them.'),
  ('BSB', 'Psalms', 19, 119, 130, 'The unfolding of Your words gives light; it informs the simple.'),
  ('BSB', 'Psalms', 19, 119, 131, 'I open my mouth and pant, longing for Your commandments.'),
  ('BSB', 'Psalms', 19, 119, 132, 'Turn to me and show me mercy, as You do to those who love Your name.'),
  ('BSB', 'Psalms', 19, 119, 133, 'Order my steps in Your word; let no sin rule over me.'),
  ('BSB', 'Psalms', 19, 119, 134, 'Redeem me from the oppression of man, that I may keep Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 135, 'Make Your face shine upon Your servant, and teach me Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 136, 'My eyes shed streams of tears because Your law is not obeyed.'),
  ('BSB', 'Psalms', 19, 119, 137, 'Righteous are You, O LORD, and upright are Your judgments.'),
  ('BSB', 'Psalms', 19, 119, 138, 'The testimonies You have laid down are righteous and altogether faithful.'),
  ('BSB', 'Psalms', 19, 119, 139, 'My zeal has consumed me because my foes forget Your words.'),
  ('BSB', 'Psalms', 19, 119, 140, 'Your promise is completely pure; therefore Your servant loves it.'),
  ('BSB', 'Psalms', 19, 119, 141, 'I am lowly and despised, but I do not forget Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 142, 'Your righteousness is everlasting and Your law is true.'),
  ('BSB', 'Psalms', 19, 119, 143, 'Trouble and distress have found me, but Your commandments are my delight.'),
  ('BSB', 'Psalms', 19, 119, 144, 'Your testimonies are righteous forever. Give me understanding, that I may live.'),
  ('BSB', 'Psalms', 19, 119, 145, 'I call with all my heart; answer me, O LORD! I will obey Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 146, 'I call to You; save me, that I may keep Your testimonies.'),
  ('BSB', 'Psalms', 19, 119, 147, 'I rise before dawn and cry for help; in Your word I have put my hope.'),
  ('BSB', 'Psalms', 19, 119, 148, 'My eyes anticipate the watches of night, that I may meditate on Your word.'),
  ('BSB', 'Psalms', 19, 119, 149, 'Hear my voice, O LORD, according to Your loving devotion; give me life according to Your justice.'),
  ('BSB', 'Psalms', 19, 119, 150, 'Those who follow after wickedness draw near; they are far from Your law.'),
  ('BSB', 'Psalms', 19, 119, 151, 'You are near, O LORD, and all Your commandments are true.'),
  ('BSB', 'Psalms', 19, 119, 152, 'Long ago I learned from Your testimonies that You have established them forever.'),
  ('BSB', 'Psalms', 19, 119, 153, 'Look upon my affliction and rescue me, for I have not forgotten Your law.'),
  ('BSB', 'Psalms', 19, 119, 154, 'Defend my cause and redeem me; revive me according to Your word.'),
  ('BSB', 'Psalms', 19, 119, 155, 'Salvation is far from the wicked because they do not seek Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 156, 'Great are Your mercies, O LORD; revive me according to Your ordinances.'),
  ('BSB', 'Psalms', 19, 119, 157, 'Though my persecutors and foes are many, I have not turned from Your testimonies.'),
  ('BSB', 'Psalms', 19, 119, 158, 'I look on the faithless with loathing because they do not keep Your word.'),
  ('BSB', 'Psalms', 19, 119, 159, 'Consider how I love Your precepts, O LORD; give me life according to Your loving devotion.'),
  ('BSB', 'Psalms', 19, 119, 160, 'The entirety of Your word is truth, and all Your righteous judgments endure forever.'),
  ('BSB', 'Psalms', 19, 119, 161, 'Rulers persecute me without cause, but my heart fears only Your word.'),
  ('BSB', 'Psalms', 19, 119, 162, 'I rejoice in Your promise like one who finds great spoil.'),
  ('BSB', 'Psalms', 19, 119, 163, 'I hate and abhor falsehood, but Your law I love.'),
  ('BSB', 'Psalms', 19, 119, 164, 'Seven times a day I praise You for Your righteous judgments.'),
  ('BSB', 'Psalms', 19, 119, 165, 'Abundant peace belongs to those who love Your law; nothing can make them stumble.'),
  ('BSB', 'Psalms', 19, 119, 166, 'I wait for Your salvation, O LORD, and I carry out Your commandments.'),
  ('BSB', 'Psalms', 19, 119, 167, 'I obey Your testimonies and love them greatly.'),
  ('BSB', 'Psalms', 19, 119, 168, 'I obey Your precepts and Your testimonies, for all my ways are before You.'),
  ('BSB', 'Psalms', 19, 119, 169, 'May my cry come before You, O LORD; give me understanding according to Your word.'),
  ('BSB', 'Psalms', 19, 119, 170, 'May my plea come before You; rescue me according to Your promise.'),
  ('BSB', 'Psalms', 19, 119, 171, 'My lips pour forth praise, for You teach me Your statutes.'),
  ('BSB', 'Psalms', 19, 119, 172, 'My tongue sings of Your word, for all Your commandments are righteous.'),
  ('BSB', 'Psalms', 19, 119, 173, 'May Your hand be ready to help me, for I have chosen Your precepts.'),
  ('BSB', 'Psalms', 19, 119, 174, 'I long for Your salvation, O LORD, and Your law is my delight.'),
  ('BSB', 'Psalms', 19, 119, 175, 'Let me live to praise You; may Your judgments sustain me.'),
  ('BSB', 'Psalms', 19, 119, 176, 'I have strayed like a lost sheep; seek Your servant, for I have not forgotten Your commandments.'),
  ('BSB', 'Psalms', 19, 120, 1, 'In my distress I cried to the LORD, and He answered me.'),
  ('BSB', 'Psalms', 19, 120, 2, 'Deliver my soul, O LORD, from lying lips and a deceitful tongue.'),
  ('BSB', 'Psalms', 19, 120, 3, 'What will He do to you, and what will be added to you, O deceitful tongue?'),
  ('BSB', 'Psalms', 19, 120, 4, 'Sharp arrows will come from the warrior, with burning coals of the broom tree!'),
  ('BSB', 'Psalms', 19, 120, 5, 'Woe to me that I dwell in Meshech, that I live among the tents of Kedar!'),
  ('BSB', 'Psalms', 19, 120, 6, 'Too long have I dwelt among those who hate peace.'),
  ('BSB', 'Psalms', 19, 120, 7, 'I am in favor of peace; but when I speak, they want war.'),
  ('BSB', 'Psalms', 19, 121, 1, 'I lift up my eyes to the hills. From where does my help come?'),
  ('BSB', 'Psalms', 19, 121, 2, 'My help comes from the LORD, the Maker of heaven and earth.'),
  ('BSB', 'Psalms', 19, 121, 3, 'He will not allow your foot to slip; your Protector will not slumber.'),
  ('BSB', 'Psalms', 19, 121, 4, 'Behold, the Protector of Israel will neither slumber nor sleep.'),
  ('BSB', 'Psalms', 19, 121, 5, 'The LORD is your keeper; the LORD is the shade on your right hand.'),
  ('BSB', 'Psalms', 19, 121, 6, 'The sun will not strike you by day, nor the moon by night.'),
  ('BSB', 'Psalms', 19, 121, 7, 'The LORD will guard you from all evil; He will preserve your soul.'),
  ('BSB', 'Psalms', 19, 121, 8, 'The LORD will watch over your coming and going, both now and forevermore.'),
  ('BSB', 'Psalms', 19, 122, 1, 'I was glad when they said to me, “Let us go to the house of the LORD.”'),
  ('BSB', 'Psalms', 19, 122, 2, 'Our feet are standing in your gates, O Jerusalem.'),
  ('BSB', 'Psalms', 19, 122, 3, 'Jerusalem is built up as a city united together,'),
  ('BSB', 'Psalms', 19, 122, 4, 'where the tribes go up, the tribes of the LORD, as a testimony for Israel, to give thanks to the name of the LORD.'),
  ('BSB', 'Psalms', 19, 122, 5, 'For there the thrones of judgment stand, the thrones of the house of David.'),
  ('BSB', 'Psalms', 19, 122, 6, 'Pray for the peace of Jerusalem: “May those who love you prosper.'),
  ('BSB', 'Psalms', 19, 122, 7, 'May there be peace within your walls, and prosperity inside your fortresses.”'),
  ('BSB', 'Psalms', 19, 122, 8, 'For the sake of my brothers and friends, I will say, “Peace be within you.”'),
  ('BSB', 'Psalms', 19, 122, 9, 'For the sake of the house of the LORD our God, I will seek your prosperity.'),
  ('BSB', 'Psalms', 19, 123, 1, 'I lift up my eyes to You, the One enthroned in heaven.'),
  ('BSB', 'Psalms', 19, 123, 2, 'As the eyes of servants look to the hand of their master, as the eyes of a maidservant look to the hand of her mistress, so our eyes are on the LORD our God until He shows us mercy.'),
  ('BSB', 'Psalms', 19, 123, 3, 'Have mercy on us, O LORD, have mercy, for we have endured much contempt.'),
  ('BSB', 'Psalms', 19, 123, 4, 'We have endured much scorn from the arrogant, much contempt from the proud.'),
  ('BSB', 'Psalms', 19, 124, 1, 'If the LORD had not been on our side— let Israel now declare—'),
  ('BSB', 'Psalms', 19, 124, 2, 'if the LORD had not been on our side when men attacked us,'),
  ('BSB', 'Psalms', 19, 124, 3, 'when their anger flared against us, then they would have swallowed us alive,'),
  ('BSB', 'Psalms', 19, 124, 4, 'then the floods would have engulfed us, then the torrent would have overwhelmed us,'),
  ('BSB', 'Psalms', 19, 124, 5, 'then the raging waters would have swept us away.'),
  ('BSB', 'Psalms', 19, 124, 6, 'Blessed be the LORD, who has not given us as prey to their teeth.'),
  ('BSB', 'Psalms', 19, 124, 7, 'We have escaped like a bird from the snare of the fowler; the net is torn, and we have slipped away.'),
  ('BSB', 'Psalms', 19, 124, 8, 'Our help is in the name of the LORD, the Maker of heaven and earth.'),
  ('BSB', 'Psalms', 19, 125, 1, 'Those who trust in the LORD are like Mount Zion. It cannot be moved; it abides forever.'),
  ('BSB', 'Psalms', 19, 125, 2, 'As the mountains surround Jerusalem, so the LORD surrounds His people, both now and forevermore.'),
  ('BSB', 'Psalms', 19, 125, 3, 'For the scepter of the wicked will not rest upon the land allotted to the righteous, so that the righteous will not put forth their hands to injustice.'),
  ('BSB', 'Psalms', 19, 125, 4, 'Do good, O LORD, to those who are good, and to the upright in heart.'),
  ('BSB', 'Psalms', 19, 125, 5, 'But those who turn to crooked ways the LORD will banish with the evildoers. Peace be upon Israel.'),
  ('BSB', 'Psalms', 19, 126, 1, 'When the LORD restored the captives of Zion, we were like dreamers.'),
  ('BSB', 'Psalms', 19, 126, 2, 'Then our mouths were filled with laughter, our tongues with shouts of joy. Then it was said among the nations, “The LORD has done great things for them.”'),
  ('BSB', 'Psalms', 19, 126, 3, 'The LORD has done great things for us; we are filled with joy.'),
  ('BSB', 'Psalms', 19, 126, 4, 'Restore our captives, O LORD, like streams in the Negev.'),
  ('BSB', 'Psalms', 19, 126, 5, 'Those who sow in tears will reap with shouts of joy.'),
  ('BSB', 'Psalms', 19, 126, 6, 'He who goes out weeping, bearing a trail of seed, will surely return with shouts of joy, carrying sheaves of grain.'),
  ('BSB', 'Psalms', 19, 127, 1, 'Unless the LORD builds the house, its builders labor in vain; unless the LORD protects the city, its watchmen stand guard in vain.'),
  ('BSB', 'Psalms', 19, 127, 2, 'In vain you rise early and stay up late, toiling for bread to eat— for He gives sleep to His beloved.'),
  ('BSB', 'Psalms', 19, 127, 3, 'Children are indeed a heritage from the LORD, and the fruit of the womb is His reward.'),
  ('BSB', 'Psalms', 19, 127, 4, 'Like arrows in the hand of a warrior, so are children born in one’s youth.'),
  ('BSB', 'Psalms', 19, 127, 5, 'Blessed is the man whose quiver is full of them. He will not be put to shame when he confronts the enemies at the gate.'),
  ('BSB', 'Psalms', 19, 128, 1, 'Blessed are all who fear the LORD, who walk in His ways!'),
  ('BSB', 'Psalms', 19, 128, 2, 'For when you eat the fruit of your labor, blessings and prosperity will be yours.'),
  ('BSB', 'Psalms', 19, 128, 3, 'Your wife will be like a fruitful vine flourishing within your house, your sons like olive shoots sitting around your table.'),
  ('BSB', 'Psalms', 19, 128, 4, 'In this way indeed shall blessing come to the man who fears the LORD.'),
  ('BSB', 'Psalms', 19, 128, 5, 'May the LORD bless you from Zion, that you may see the prosperity of Jerusalem all the days of your life,'),
  ('BSB', 'Psalms', 19, 128, 6, 'that you may see your children’s children. Peace be upon Israel!'),
  ('BSB', 'Psalms', 19, 129, 1, 'Many a time they have persecuted me from my youth— let Israel now declare—'),
  ('BSB', 'Psalms', 19, 129, 2, 'many a time they have persecuted me from my youth, but they have not prevailed against me.'),
  ('BSB', 'Psalms', 19, 129, 3, 'The plowmen plowed over my back; they made their furrows long.'),
  ('BSB', 'Psalms', 19, 129, 4, 'The LORD is righteous; He has cut me from the cords of the wicked.'),
  ('BSB', 'Psalms', 19, 129, 5, 'May all who hate Zion be turned back in shame.'),
  ('BSB', 'Psalms', 19, 129, 6, 'May they be like grass on the rooftops, which withers before it can grow,'),
  ('BSB', 'Psalms', 19, 129, 7, 'unable to fill the hands of the reaper, or the arms of the binder of sheaves.'),
  ('BSB', 'Psalms', 19, 129, 8, 'May none who pass by say to them, “The blessing of the LORD be on you; we bless you in the name of the LORD.”'),
  ('BSB', 'Psalms', 19, 130, 1, 'Out of the depths I cry to You, O LORD!'),
  ('BSB', 'Psalms', 19, 130, 2, 'O Lord, hear my voice; let Your ears be attentive to my plea for mercy.'),
  ('BSB', 'Psalms', 19, 130, 3, 'If You, O LORD, kept track of iniquities, then who, O Lord, could stand?'),
  ('BSB', 'Psalms', 19, 130, 4, 'But with You there is forgiveness, so that You may be feared.'),
  ('BSB', 'Psalms', 19, 130, 5, 'I wait for the LORD; my soul does wait, and in His word I put my hope.'),
  ('BSB', 'Psalms', 19, 130, 6, 'My soul waits for the Lord more than watchmen wait for the morning— more than watchmen wait for the morning.'),
  ('BSB', 'Psalms', 19, 130, 7, 'O Israel, put your hope in the LORD, for with the LORD is loving devotion, and with Him is redemption in abundance.'),
  ('BSB', 'Psalms', 19, 130, 8, 'And He will redeem Israel from all iniquity.'),
  ('BSB', 'Psalms', 19, 131, 1, 'My heart is not proud, O LORD, my eyes are not haughty. I do not aspire to great things or matters too lofty for me.'),
  ('BSB', 'Psalms', 19, 131, 2, 'Surely I have stilled and quieted my soul; like a weaned child with his mother, like a weaned child is my soul within me.'),
  ('BSB', 'Psalms', 19, 131, 3, 'O Israel, put your hope in the LORD, both now and forevermore.'),
  ('BSB', 'Psalms', 19, 132, 1, 'O LORD, remember on behalf of David all the hardships he endured,'),
  ('BSB', 'Psalms', 19, 132, 2, 'how he swore an oath to the LORD, and vowed to the Mighty One of Jacob:'),
  ('BSB', 'Psalms', 19, 132, 3, '“I will not enter my house or get into my bed,'),
  ('BSB', 'Psalms', 19, 132, 4, 'I will not give sleep to my eyes or slumber to my eyelids,'),
  ('BSB', 'Psalms', 19, 132, 5, 'until I find a place for the LORD, a dwelling for the Mighty One of Jacob.”'),
  ('BSB', 'Psalms', 19, 132, 6, 'We heard that the ark was in Ephrathah; we found it in the fields of Jaar.'),
  ('BSB', 'Psalms', 19, 132, 7, 'Let us go to His dwelling place; let us worship at His footstool.'),
  ('BSB', 'Psalms', 19, 132, 8, 'Arise, O LORD, to Your resting place, You and the ark of Your strength.'),
  ('BSB', 'Psalms', 19, 132, 9, 'May Your priests be clothed with righteousness, and Your saints shout for joy.'),
  ('BSB', 'Psalms', 19, 132, 10, 'For the sake of Your servant David, do not reject Your anointed one.'),
  ('BSB', 'Psalms', 19, 132, 11, 'The LORD swore an oath to David, a promise He will not revoke: “One of your descendants I will place on your throne.'),
  ('BSB', 'Psalms', 19, 132, 12, 'If your sons keep My covenant and the testimony I will teach them, then their sons will also sit on your throne forever and ever.”'),
  ('BSB', 'Psalms', 19, 132, 13, 'For the LORD has chosen Zion; He has desired it for His home:'),
  ('BSB', 'Psalms', 19, 132, 14, '“This is My resting place forever and ever; here I will dwell, for I have desired this home.'),
  ('BSB', 'Psalms', 19, 132, 15, 'I will bless her with abundant provisions; I will satisfy her poor with bread.'),
  ('BSB', 'Psalms', 19, 132, 16, 'I will clothe her priests with salvation, and her saints will sing out in joy.'),
  ('BSB', 'Psalms', 19, 132, 17, 'There I will make a horn grow for David; I have prepared a lamp for My anointed one.'),
  ('BSB', 'Psalms', 19, 132, 18, 'I will clothe his enemies with shame, but the crown upon him will gleam.”'),
  ('BSB', 'Psalms', 19, 133, 1, 'Behold, how good and pleasant it is when brothers live together in harmony!'),
  ('BSB', 'Psalms', 19, 133, 2, 'It is like fine oil on the head, running down on the beard, running down Aaron’s beard over the collar of his robes.'),
  ('BSB', 'Psalms', 19, 133, 3, 'It is like the dew of Hermon falling on the mountains of Zion. For there the LORD has bestowed the blessing of life forevermore.'),
  ('BSB', 'Psalms', 19, 134, 1, 'Come, bless the LORD, all you servants of the LORD who serve by night in the house of the LORD!'),
  ('BSB', 'Psalms', 19, 134, 2, 'Lift up your hands to the sanctuary and bless the LORD!'),
  ('BSB', 'Psalms', 19, 134, 3, 'May the LORD, the Maker of heaven and earth, bless you from Zion.'),
  ('BSB', 'Psalms', 19, 135, 1, 'Hallelujah! Praise the name of the LORD. Give praise, O servants of the LORD,'),
  ('BSB', 'Psalms', 19, 135, 2, 'who stand in the house of the LORD, in the courts of the house of our God.'),
  ('BSB', 'Psalms', 19, 135, 3, 'Hallelujah, for the LORD is good; sing praises to His name, for it is lovely.'),
  ('BSB', 'Psalms', 19, 135, 4, 'For the LORD has chosen Jacob as His own, Israel as His treasured possession.'),
  ('BSB', 'Psalms', 19, 135, 5, 'For I know that the LORD is great; our Lord is above all gods.'),
  ('BSB', 'Psalms', 19, 135, 6, 'The LORD does all that pleases Him in the heavens and on the earth, in the seas and in all their depths.'),
  ('BSB', 'Psalms', 19, 135, 7, 'He causes the clouds to rise from the ends of the earth. He generates the lightning with the rain and brings forth the wind from His storehouses.'),
  ('BSB', 'Psalms', 19, 135, 8, 'He struck down the firstborn of Egypt, of both man and beast.'),
  ('BSB', 'Psalms', 19, 135, 9, 'He sent signs and wonders into your midst, O Egypt, against Pharaoh and all his servants.'),
  ('BSB', 'Psalms', 19, 135, 10, 'He struck down many nations and slaughtered mighty kings:'),
  ('BSB', 'Psalms', 19, 135, 11, 'Sihon king of the Amorites, Og king of Bashan, and all the kings of Canaan.'),
  ('BSB', 'Psalms', 19, 135, 12, 'He gave their land as an inheritance, as a heritage to His people Israel.'),
  ('BSB', 'Psalms', 19, 135, 13, 'Your name, O LORD, endures forever, Your renown, O LORD, through all generations.'),
  ('BSB', 'Psalms', 19, 135, 14, 'For the LORD will vindicate His people and will have compassion on His servants.'),
  ('BSB', 'Psalms', 19, 135, 15, 'The idols of the nations are silver and gold, made by the hands of men.'),
  ('BSB', 'Psalms', 19, 135, 16, 'They have mouths, but cannot speak; they have eyes, but cannot see;'),
  ('BSB', 'Psalms', 19, 135, 17, 'they have ears, but cannot hear; nor is there breath in their mouths.'),
  ('BSB', 'Psalms', 19, 135, 18, 'Those who make them become like them, as do all who trust in them.'),
  ('BSB', 'Psalms', 19, 135, 19, 'O house of Israel, bless the LORD; O house of Aaron, bless the LORD;'),
  ('BSB', 'Psalms', 19, 135, 20, 'O house of Levi, bless the LORD; you who fear the LORD, bless the LORD!'),
  ('BSB', 'Psalms', 19, 135, 21, 'Blessed be the LORD from Zion— He who dwells in Jerusalem. Hallelujah!'),
  ('BSB', 'Psalms', 19, 136, 1, 'Give thanks to the LORD, for He is good. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 2, 'Give thanks to the God of gods. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 3, 'Give thanks to the Lord of lords. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 4, 'He alone does great wonders. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 5, 'By His insight He made the heavens. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 6, 'He spread out the earth upon the waters. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 7, 'He made the great lights— His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 8, 'the sun to rule the day, His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 9, 'the moon and stars to govern the night. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 10, 'He struck down the firstborn of Egypt His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 11, 'and brought Israel out from among them His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 12, 'with a mighty hand and an outstretched arm. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 13, 'He divided the Red Sea in two His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 14, 'and led Israel through the midst, His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 15, 'but swept Pharaoh and his army into the Red Sea. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 16, 'He led His people through the wilderness. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 17, 'He struck down great kings His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 18, 'and slaughtered mighty kings— His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 19, 'Sihon king of the Amorites His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 20, 'and Og king of Bashan— His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 21, 'and He gave their land as an inheritance, His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 22, 'a heritage to His servant Israel. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 23, 'He remembered us in our low estate His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 24, 'and freed us from our enemies. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 25, 'He gives food to every creature. His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 136, 26, 'Give thanks to the God of heaven! His loving devotion endures forever.'),
  ('BSB', 'Psalms', 19, 137, 1, 'By the rivers of Babylon we sat and wept when we remembered Zion.'),
  ('BSB', 'Psalms', 19, 137, 2, 'There on the willows we hung our harps,'),
  ('BSB', 'Psalms', 19, 137, 3, 'for there our captors requested a song; our tormentors demanded songs of joy: “Sing us a song of Zion.”'),
  ('BSB', 'Psalms', 19, 137, 4, 'How can we sing a song of the LORD in a foreign land?'),
  ('BSB', 'Psalms', 19, 137, 5, 'If I forget you, O Jerusalem, may my right hand cease to function.'),
  ('BSB', 'Psalms', 19, 137, 6, 'May my tongue cling to the roof of my mouth if I do not remember you, if I do not exalt Jerusalem as my greatest joy!'),
  ('BSB', 'Psalms', 19, 137, 7, 'Remember, O LORD, the sons of Edom on the day Jerusalem fell: “Destroy it,” they said, “tear it down to its foundations!”'),
  ('BSB', 'Psalms', 19, 137, 8, 'O Daughter of Babylon, doomed to destruction, blessed is he who repays you as you have done to us.'),
  ('BSB', 'Psalms', 19, 137, 9, 'Blessed is he who seizes your infants and dashes them against the rocks.'),
  ('BSB', 'Psalms', 19, 138, 1, 'I give You thanks with all my heart; before the gods I sing Your praises.'),
  ('BSB', 'Psalms', 19, 138, 2, 'I bow down toward Your holy temple and give thanks to Your name for Your loving devotion and Your faithfulness; You have exalted Your name and Your word above all else.'),
  ('BSB', 'Psalms', 19, 138, 3, 'On the day I called, You answered me; You emboldened me and strengthened my soul.'),
  ('BSB', 'Psalms', 19, 138, 4, 'All the kings of the earth will give You thanks, O LORD, when they hear the words of Your mouth.'),
  ('BSB', 'Psalms', 19, 138, 5, 'They will sing of the ways of the LORD, for the glory of the LORD is great.'),
  ('BSB', 'Psalms', 19, 138, 6, 'Though the LORD is on high, He attends to the lowly; but the proud He knows from afar.'),
  ('BSB', 'Psalms', 19, 138, 7, 'If I walk in the midst of trouble, You preserve me from the anger of my foes; You extend Your hand, and Your right hand saves me.'),
  ('BSB', 'Psalms', 19, 138, 8, 'The LORD will fulfill His purpose for me. O LORD, Your loving devotion endures forever— do not abandon the works of Your hands.'),
  ('BSB', 'Psalms', 19, 139, 1, 'O LORD, You have searched me and known me.'),
  ('BSB', 'Psalms', 19, 139, 2, 'You know when I sit and when I rise; You understand my thoughts from afar.'),
  ('BSB', 'Psalms', 19, 139, 3, 'You search out my path and my lying down; You are aware of all my ways.'),
  ('BSB', 'Psalms', 19, 139, 4, 'Even before a word is on my tongue, You know all about it, O LORD.'),
  ('BSB', 'Psalms', 19, 139, 5, 'You hem me in behind and before; You have laid Your hand upon me.'),
  ('BSB', 'Psalms', 19, 139, 6, 'Such knowledge is too wonderful for me, too lofty for me to attain.'),
  ('BSB', 'Psalms', 19, 139, 7, 'Where can I go to escape Your Spirit? Where can I flee from Your presence?'),
  ('BSB', 'Psalms', 19, 139, 8, 'If I ascend to the heavens, You are there; if I make my bed in Sheol, You are there.'),
  ('BSB', 'Psalms', 19, 139, 9, 'If I rise on the wings of the dawn, if I settle by the farthest sea,'),
  ('BSB', 'Psalms', 19, 139, 10, 'even there Your hand will guide me; Your right hand will hold me fast.'),
  ('BSB', 'Psalms', 19, 139, 11, 'If I say, “Surely the darkness will hide me, and the light become night around me”—'),
  ('BSB', 'Psalms', 19, 139, 12, 'even the darkness is not dark to You, but the night shines like the day, for darkness is as light to You.'),
  ('BSB', 'Psalms', 19, 139, 13, 'For You formed my inmost being; You knit me together in my mother’s womb.'),
  ('BSB', 'Psalms', 19, 139, 14, 'I praise You, for I am fearfully and wonderfully made. Marvelous are Your works, and I know this very well.'),
  ('BSB', 'Psalms', 19, 139, 15, 'My frame was not hidden from You when I was made in secret, when I was woven together in the depths of the earth.'),
  ('BSB', 'Psalms', 19, 139, 16, 'Your eyes saw my unformed body; all my days were written in Your book and ordained for me before one of them came to be.'),
  ('BSB', 'Psalms', 19, 139, 17, 'How precious to me are Your thoughts, O God, how vast is their sum!'),
  ('BSB', 'Psalms', 19, 139, 18, 'If I were to count them, they would outnumber the grains of sand; and when I awake, I am still with You.'),
  ('BSB', 'Psalms', 19, 139, 19, 'O God, that You would slay the wicked— away from me, you bloodthirsty men—'),
  ('BSB', 'Psalms', 19, 139, 20, 'who speak of You deceitfully; Your enemies take Your name in vain.'),
  ('BSB', 'Psalms', 19, 139, 21, 'Do I not hate those who hate You, O LORD, and detest those who rise against You?'),
  ('BSB', 'Psalms', 19, 139, 22, 'I hate them with perfect hatred; I count them as my enemies.'),
  ('BSB', 'Psalms', 19, 139, 23, 'Search me, O God, and know my heart; test me and know my concerns.'),
  ('BSB', 'Psalms', 19, 139, 24, 'See if there is any offensive way in me; lead me in the way everlasting.'),
  ('BSB', 'Psalms', 19, 140, 1, 'Rescue me, O LORD, from evil men. Protect me from men of violence,'),
  ('BSB', 'Psalms', 19, 140, 2, 'who devise evil in their hearts and stir up war all day long.'),
  ('BSB', 'Psalms', 19, 140, 3, 'They sharpen their tongues like snakes; the venom of vipers is on their lips. Selah'),
  ('BSB', 'Psalms', 19, 140, 4, 'Guard me, O LORD, from the hands of the wicked. Keep me safe from men of violence who scheme to make me stumble.'),
  ('BSB', 'Psalms', 19, 140, 5, 'The proud hide a snare for me; the cords of their net are spread along the path, and lures are set out for me. Selah'),
  ('BSB', 'Psalms', 19, 140, 6, 'I say to the LORD, “You are my God.” Hear, O LORD, my cry for help.'),
  ('BSB', 'Psalms', 19, 140, 7, 'O GOD the Lord, the strength of my salvation, You shield my head in the day of battle.'),
  ('BSB', 'Psalms', 19, 140, 8, 'Grant not, O LORD, the desires of the wicked; do not promote their evil plans, lest they be exalted. Selah'),
  ('BSB', 'Psalms', 19, 140, 9, 'May the heads of those who surround me be covered in the trouble their lips have caused.'),
  ('BSB', 'Psalms', 19, 140, 10, 'May burning coals fall on them; may they be thrown into the fire, into the miry pits, never to rise again.'),
  ('BSB', 'Psalms', 19, 140, 11, 'May no slanderer be established in the land; may calamity hunt down the man of violence.'),
  ('BSB', 'Psalms', 19, 140, 12, 'I know that the LORD upholds justice for the poor and defends the cause of the needy.'),
  ('BSB', 'Psalms', 19, 140, 13, 'Surely the righteous will praise Your name; the upright will dwell in Your presence.'),
  ('BSB', 'Psalms', 19, 141, 1, 'I call upon You, O LORD; come quickly to me. Hear my voice when I call to You.'),
  ('BSB', 'Psalms', 19, 141, 2, 'May my prayer be set before You like incense, my uplifted hands like the evening offering.'),
  ('BSB', 'Psalms', 19, 141, 3, 'Set a guard, O LORD, over my mouth; keep watch at the door of my lips.'),
  ('BSB', 'Psalms', 19, 141, 4, 'Do not let my heart be drawn to any evil thing or take part in works of wickedness with men who do iniquity; let me not feast on their delicacies.'),
  ('BSB', 'Psalms', 19, 141, 5, 'Let the righteous man strike me; let his rebuke be an act of loving devotion. It is oil for my head; let me not refuse it. For my prayer is ever against the deeds of the wicked.'),
  ('BSB', 'Psalms', 19, 141, 6, 'When their rulers are thrown down from the cliffs, the people will listen to my words, for they are pleasant.'),
  ('BSB', 'Psalms', 19, 141, 7, 'As when one plows and breaks up the soil, so our bones have been scattered at the mouth of Sheol.'),
  ('BSB', 'Psalms', 19, 141, 8, 'But my eyes are fixed on You, O GOD the Lord. In You I seek refuge; do not leave my soul defenseless.'),
  ('BSB', 'Psalms', 19, 141, 9, 'Keep me from the snares they have laid for me, and from the lures of evildoers.'),
  ('BSB', 'Psalms', 19, 141, 10, 'Let the wicked fall into their own nets, while I pass by in safety.'),
  ('BSB', 'Psalms', 19, 142, 1, 'I cry aloud to the LORD; I lift my voice to the LORD for mercy.'),
  ('BSB', 'Psalms', 19, 142, 2, 'I pour out my complaint before Him; I reveal my trouble to Him.'),
  ('BSB', 'Psalms', 19, 142, 3, 'Although my spirit grows faint within me, You know my way. Along the path I travel they have hidden a snare for me.'),
  ('BSB', 'Psalms', 19, 142, 4, 'Look to my right and see; no one attends to me. There is no refuge for me; no one cares for my soul.'),
  ('BSB', 'Psalms', 19, 142, 5, 'I cry to You, O LORD: “You are my refuge, my portion in the land of the living.”'),
  ('BSB', 'Psalms', 19, 142, 6, 'Listen to my cry, for I am brought quite low. Rescue me from my pursuers, for they are too strong for me.'),
  ('BSB', 'Psalms', 19, 142, 7, 'Free my soul from prison, that I may praise Your name. The righteous will gather around me because of Your goodness to me.'),
  ('BSB', 'Psalms', 19, 143, 1, 'O LORD, hear my prayer. In Your faithfulness, give ear to my plea; in Your righteousness, answer me.'),
  ('BSB', 'Psalms', 19, 143, 2, 'Do not bring Your servant into judgment, for no one alive is righteous before You.'),
  ('BSB', 'Psalms', 19, 143, 3, 'For the enemy has pursued my soul, crushing my life to the ground, making me dwell in darkness like those long since dead.'),
  ('BSB', 'Psalms', 19, 143, 4, 'My spirit grows faint within me; my heart is dismayed inside me.'),
  ('BSB', 'Psalms', 19, 143, 5, 'I remember the days of old; I meditate on all Your works; I consider the work of Your hands.'),
  ('BSB', 'Psalms', 19, 143, 6, 'I stretch out my hands to You; my soul thirsts for You like a parched land. Selah'),
  ('BSB', 'Psalms', 19, 143, 7, 'Answer me quickly, O LORD; my spirit fails. Do not hide Your face from me, or I will be like those who descend to the Pit.'),
  ('BSB', 'Psalms', 19, 143, 8, 'Let me hear Your loving devotion in the morning, for I have put my trust in You. Teach me the way I should walk, for to You I lift up my soul.'),
  ('BSB', 'Psalms', 19, 143, 9, 'Deliver me from my enemies, O LORD; I flee to You for refuge.'),
  ('BSB', 'Psalms', 19, 143, 10, 'Teach me to do Your will, for You are my God. May Your good Spirit lead me on level ground.'),
  ('BSB', 'Psalms', 19, 143, 11, 'For the sake of Your name, O LORD, revive me. In Your righteousness, bring my soul out of trouble.'),
  ('BSB', 'Psalms', 19, 143, 12, 'And in Your loving devotion, cut off my enemies. Destroy all who afflict me, for I am Your servant.'),
  ('BSB', 'Psalms', 19, 144, 1, 'Blessed be the LORD, my Rock, who trains my hands for war, my fingers for battle.'),
  ('BSB', 'Psalms', 19, 144, 2, 'He is my steadfast love and my fortress, my stronghold and my deliverer. He is my shield, in whom I take refuge, who subdues peoples under me.'),
  ('BSB', 'Psalms', 19, 144, 3, 'O LORD, what is man, that You regard him, the son of man that You think of him?'),
  ('BSB', 'Psalms', 19, 144, 4, 'Man is like a breath; his days are like a passing shadow.'),
  ('BSB', 'Psalms', 19, 144, 5, 'Part Your heavens, O LORD, and come down; touch the mountains, that they may smoke.'),
  ('BSB', 'Psalms', 19, 144, 6, 'Flash forth Your lightning and scatter them; shoot Your arrows and rout them.'),
  ('BSB', 'Psalms', 19, 144, 7, 'Reach down from on high; set me free and rescue me from the deep waters, from the grasp of foreigners,'),
  ('BSB', 'Psalms', 19, 144, 8, 'whose mouths speak falsehood, whose right hands are deceitful.'),
  ('BSB', 'Psalms', 19, 144, 9, 'I will sing to You a new song, O God; on a harp of ten strings I will make music to You—'),
  ('BSB', 'Psalms', 19, 144, 10, 'to Him who gives victory to kings, who frees His servant David from the deadly sword.'),
  ('BSB', 'Psalms', 19, 144, 11, 'Set me free and rescue me from the grasp of foreigners, whose mouths speak falsehood, whose right hands are deceitful.'),
  ('BSB', 'Psalms', 19, 144, 12, 'Then our sons will be like plants nurtured in their youth, our daughters like corner pillars carved to adorn a palace.'),
  ('BSB', 'Psalms', 19, 144, 13, 'Our storehouses will be full, supplying all manner of produce; our flocks will bring forth thousands, tens of thousands in our fields.'),
  ('BSB', 'Psalms', 19, 144, 14, 'Our oxen will bear great loads. There will be no breach in the walls, no going into captivity, and no cry of lament in our streets.'),
  ('BSB', 'Psalms', 19, 144, 15, 'Blessed are the people of whom this is so; blessed are the people whose God is the LORD.'),
  ('BSB', 'Psalms', 19, 145, 1, 'I will exalt You, my God and King; I will bless Your name forever and ever.'),
  ('BSB', 'Psalms', 19, 145, 2, 'Every day I will bless You, and I will praise Your name forever and ever.'),
  ('BSB', 'Psalms', 19, 145, 3, 'Great is the LORD and greatly to be praised; His greatness is unsearchable.'),
  ('BSB', 'Psalms', 19, 145, 4, 'One generation will commend Your works to the next, and will proclaim Your mighty acts—'),
  ('BSB', 'Psalms', 19, 145, 5, 'the glorious splendor of Your majesty. And I will meditate on Your wondrous works.'),
  ('BSB', 'Psalms', 19, 145, 6, 'They will proclaim the power of Your awesome deeds, and I will declare Your greatness.'),
  ('BSB', 'Psalms', 19, 145, 7, 'They will extol the fame of Your abundant goodness and sing joyfully of Your righteousness.'),
  ('BSB', 'Psalms', 19, 145, 8, 'The LORD is gracious and compassionate, slow to anger and abounding in loving devotion.'),
  ('BSB', 'Psalms', 19, 145, 9, 'The LORD is good to all; His compassion rests on all He has made.'),
  ('BSB', 'Psalms', 19, 145, 10, 'All You have made will give You thanks, O LORD, and Your saints will bless You.'),
  ('BSB', 'Psalms', 19, 145, 11, 'They will tell of the glory of Your kingdom and speak of Your might,'),
  ('BSB', 'Psalms', 19, 145, 12, 'to make known to men Your mighty acts and the glorious splendor of Your kingdom.'),
  ('BSB', 'Psalms', 19, 145, 13, 'Your kingdom is an everlasting kingdom, and Your dominion endures through all generations. The LORD is faithful in all His words and kind in all His actions.'),
  ('BSB', 'Psalms', 19, 145, 14, 'The LORD upholds all who fall and lifts up all who are bowed down.'),
  ('BSB', 'Psalms', 19, 145, 15, 'The eyes of all look to You, and You give them their food in season.'),
  ('BSB', 'Psalms', 19, 145, 16, 'You open Your hand and satisfy the desire of every living thing.'),
  ('BSB', 'Psalms', 19, 145, 17, 'The LORD is righteous in all His ways and kind in all His deeds.'),
  ('BSB', 'Psalms', 19, 145, 18, 'The LORD is near to all who call on Him, to all who call out to Him in truth.'),
  ('BSB', 'Psalms', 19, 145, 19, 'He fulfills the desires of those who fear Him; He hears their cry and saves them.'),
  ('BSB', 'Psalms', 19, 145, 20, 'The LORD preserves all who love Him, but all the wicked He will destroy.'),
  ('BSB', 'Psalms', 19, 145, 21, 'My mouth will declare the praise of the LORD; let every creature bless His holy name forever and ever.'),
  ('BSB', 'Psalms', 19, 146, 1, 'Hallelujah! Praise the LORD, O my soul.'),
  ('BSB', 'Psalms', 19, 146, 2, 'I will praise the LORD all my life; I will sing praises to my God while I have my being.'),
  ('BSB', 'Psalms', 19, 146, 3, 'Put not your trust in princes, in mortal man, who cannot save.'),
  ('BSB', 'Psalms', 19, 146, 4, 'When his spirit departs, he returns to the ground; on that very day his plans perish.'),
  ('BSB', 'Psalms', 19, 146, 5, 'Blessed is he whose help is the God of Jacob, whose hope is in the LORD his God,'),
  ('BSB', 'Psalms', 19, 146, 6, 'the Maker of heaven and earth, the sea, and everything in them. He remains faithful forever.'),
  ('BSB', 'Psalms', 19, 146, 7, 'He executes justice for the oppressed and gives food to the hungry. The LORD sets the prisoners free,'),
  ('BSB', 'Psalms', 19, 146, 8, 'the LORD opens the eyes of the blind, the LORD lifts those who are weighed down, the LORD loves the righteous.'),
  ('BSB', 'Psalms', 19, 146, 9, 'The LORD protects foreigners; He sustains the fatherless and the widow, but the ways of the wicked He frustrates.'),
  ('BSB', 'Psalms', 19, 146, 10, 'The LORD reigns forever, your God, O Zion, for all generations. Hallelujah!'),
  ('BSB', 'Psalms', 19, 147, 1, 'Hallelujah! How good it is to sing praises to our God, how pleasant and lovely to praise Him!'),
  ('BSB', 'Psalms', 19, 147, 2, 'The LORD builds up Jerusalem; He gathers the exiles of Israel.'),
  ('BSB', 'Psalms', 19, 147, 3, 'He heals the brokenhearted and binds up their wounds.'),
  ('BSB', 'Psalms', 19, 147, 4, 'He determines the number of the stars; He calls them each by name.'),
  ('BSB', 'Psalms', 19, 147, 5, 'Great is our Lord, and mighty in power; His understanding has no limit.'),
  ('BSB', 'Psalms', 19, 147, 6, 'The LORD sustains the humble, but casts the wicked to the ground.'),
  ('BSB', 'Psalms', 19, 147, 7, 'Sing to the LORD with thanksgiving; make music on the harp to our God,'),
  ('BSB', 'Psalms', 19, 147, 8, 'who covers the sky with clouds, who prepares rain for the earth, who makes grass to grow on the hills.'),
  ('BSB', 'Psalms', 19, 147, 9, 'He provides food for the animals, and for the young ravens when they call.'),
  ('BSB', 'Psalms', 19, 147, 10, 'He does not delight in the strength of the horse; He takes no pleasure in the legpower of the man.'),
  ('BSB', 'Psalms', 19, 147, 11, 'The LORD is pleased with those who fear Him, who hope in His loving devotion.'),
  ('BSB', 'Psalms', 19, 147, 12, 'Exalt the LORD, O Jerusalem; praise your God, O Zion!'),
  ('BSB', 'Psalms', 19, 147, 13, 'For He strengthens the bars of your gates and blesses the children within you.'),
  ('BSB', 'Psalms', 19, 147, 14, 'He makes peace at your borders; He fills you with the finest wheat.'),
  ('BSB', 'Psalms', 19, 147, 15, 'He sends forth His command to the earth; His word runs swiftly.'),
  ('BSB', 'Psalms', 19, 147, 16, 'He spreads the snow like wool; He scatters the frost like ashes;'),
  ('BSB', 'Psalms', 19, 147, 17, 'He casts forth His hail like pebbles. Who can withstand His icy blast?'),
  ('BSB', 'Psalms', 19, 147, 18, 'He sends forth His word and melts them; He unleashes His winds, and the waters flow.'),
  ('BSB', 'Psalms', 19, 147, 19, 'He declares His word to Jacob, His statutes and judgments to Israel.'),
  ('BSB', 'Psalms', 19, 147, 20, 'He has done this for no other nation; they do not know His judgments. Hallelujah!'),
  ('BSB', 'Psalms', 19, 148, 1, 'Hallelujah! Praise the LORD from the heavens; praise Him in the highest places.'),
  ('BSB', 'Psalms', 19, 148, 2, 'Praise Him, all His angels; praise Him, all His heavenly hosts.'),
  ('BSB', 'Psalms', 19, 148, 3, 'Praise Him, O sun and moon; praise Him, all you shining stars.'),
  ('BSB', 'Psalms', 19, 148, 4, 'Praise Him, O highest heavens, and you waters above the skies.'),
  ('BSB', 'Psalms', 19, 148, 5, 'Let them praise the name of the LORD, for He gave the command and they were created.'),
  ('BSB', 'Psalms', 19, 148, 6, 'He established them forever and ever; He issued a decree that will never pass away.'),
  ('BSB', 'Psalms', 19, 148, 7, 'Praise the LORD from the earth, all great sea creatures and ocean depths,'),
  ('BSB', 'Psalms', 19, 148, 8, 'lightning and hail, snow and clouds, powerful wind fulfilling His word,'),
  ('BSB', 'Psalms', 19, 148, 9, 'mountains and all hills, fruit trees and all cedars,'),
  ('BSB', 'Psalms', 19, 148, 10, 'wild animals and all cattle, crawling creatures and flying birds,'),
  ('BSB', 'Psalms', 19, 148, 11, 'kings of the earth and all peoples, princes and all rulers of the earth,'),
  ('BSB', 'Psalms', 19, 148, 12, 'young men and maidens, old and young together.'),
  ('BSB', 'Psalms', 19, 148, 13, 'Let them praise the name of the LORD, for His name alone is exalted; His splendor is above the earth and the heavens.'),
  ('BSB', 'Psalms', 19, 148, 14, 'He has raised up a horn for His people, the praise of all His saints, of Israel, a people near to Him. Hallelujah!'),
  ('BSB', 'Psalms', 19, 149, 1, 'Hallelujah! Sing to the LORD a new song— His praise in the assembly of the godly.'),
  ('BSB', 'Psalms', 19, 149, 2, 'Let Israel rejoice in their Maker; let the children of Zion rejoice in their King.'),
  ('BSB', 'Psalms', 19, 149, 3, 'Let them praise His name with dancing, and make music to Him with tambourine and harp.'),
  ('BSB', 'Psalms', 19, 149, 4, 'For the LORD takes pleasure in His people; He adorns the afflicted with salvation.'),
  ('BSB', 'Psalms', 19, 149, 5, 'Let the saints exult in glory; let them shout for joy upon their beds.'),
  ('BSB', 'Psalms', 19, 149, 6, 'May the high praises of God be in their mouths, and a double-edged sword in their hands,'),
  ('BSB', 'Psalms', 19, 149, 7, 'to inflict vengeance on the nations and punishment on the peoples,'),
  ('BSB', 'Psalms', 19, 149, 8, 'to bind their kings with chains and their nobles with shackles of iron,'),
  ('BSB', 'Psalms', 19, 149, 9, 'to execute the judgment written against them. This honor is for all His saints. Hallelujah!'),
  ('BSB', 'Psalms', 19, 150, 1, 'Hallelujah! Praise God in His sanctuary. Praise Him in His mighty heavens.'),
  ('BSB', 'Psalms', 19, 150, 2, 'Praise Him for His mighty acts; praise Him for His excellent greatness.'),
  ('BSB', 'Psalms', 19, 150, 3, 'Praise Him with the sound of the horn; praise Him with the harp and lyre.'),
  ('BSB', 'Psalms', 19, 150, 4, 'Praise Him with tambourine and dancing; praise Him with strings and flute.'),
  ('BSB', 'Psalms', 19, 150, 5, 'Praise Him with clashing cymbals; praise Him with resounding cymbals.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Psalms', 19, 150, 6, 'Let everything that has breath praise the LORD! Hallelujah!'),
  ('BSB', 'Proverbs', 20, 1, 1, 'These are the proverbs of Solomon son of David, king of Israel,'),
  ('BSB', 'Proverbs', 20, 1, 2, 'for gaining wisdom and discipline, for comprehending words of insight,'),
  ('BSB', 'Proverbs', 20, 1, 3, 'and for receiving instruction in wise living and in righteousness, justice, and equity.'),
  ('BSB', 'Proverbs', 20, 1, 4, 'To impart prudence to the simple and knowledge and discretion to the young,'),
  ('BSB', 'Proverbs', 20, 1, 5, 'let the wise listen and gain instruction, and the discerning acquire wise counsel'),
  ('BSB', 'Proverbs', 20, 1, 6, 'by understanding the proverbs and parables, the sayings and riddles of the wise.'),
  ('BSB', 'Proverbs', 20, 1, 7, 'The fear of the LORD is the beginning of knowledge, but fools despise wisdom and discipline.'),
  ('BSB', 'Proverbs', 20, 1, 8, 'Listen, my son, to your father’s instruction, and do not forsake the teaching of your mother.'),
  ('BSB', 'Proverbs', 20, 1, 9, 'For they are a garland of grace on your head and a pendant around your neck.'),
  ('BSB', 'Proverbs', 20, 1, 10, 'My son, if sinners entice you, do not yield to them.'),
  ('BSB', 'Proverbs', 20, 1, 11, 'If they say, “Come along, let us lie in wait for blood, let us ambush the innocent without cause,'),
  ('BSB', 'Proverbs', 20, 1, 12, 'let us swallow them alive like Sheol, and whole like those descending into the Pit.'),
  ('BSB', 'Proverbs', 20, 1, 13, 'We will find all manner of precious goods; we will fill our houses with plunder.'),
  ('BSB', 'Proverbs', 20, 1, 14, 'Throw in your lot with us; let us all share one purse”—'),
  ('BSB', 'Proverbs', 20, 1, 15, 'my son, do not walk the road with them or set foot upon their path.'),
  ('BSB', 'Proverbs', 20, 1, 16, 'For their feet run to evil, and they are swift to shed blood.'),
  ('BSB', 'Proverbs', 20, 1, 17, 'How futile it is to spread the net where any bird can see it!'),
  ('BSB', 'Proverbs', 20, 1, 18, 'But they lie in wait for their own blood; they ambush their own lives.'),
  ('BSB', 'Proverbs', 20, 1, 19, 'Such is the fate of all who are greedy, whose unjust gain takes the lives of its possessors.'),
  ('BSB', 'Proverbs', 20, 1, 20, 'Wisdom calls out in the street, she lifts her voice in the square;'),
  ('BSB', 'Proverbs', 20, 1, 21, 'in the main concourse she cries aloud, at the city gates she makes her speech:'),
  ('BSB', 'Proverbs', 20, 1, 22, '“How long, O simple ones, will you love your simple ways? How long will scoffers delight in their scorn and fools hate knowledge?'),
  ('BSB', 'Proverbs', 20, 1, 23, 'If you had repented at my rebuke, then surely I would have poured out my spirit on you; I would have made my words known to you.'),
  ('BSB', 'Proverbs', 20, 1, 24, 'Because you refused my call, and no one took my outstretched hand,'),
  ('BSB', 'Proverbs', 20, 1, 25, 'because you neglected all my counsel, and wanted none of my correction,'),
  ('BSB', 'Proverbs', 20, 1, 26, 'in turn I will mock your calamity; I will sneer when terror strikes you,'),
  ('BSB', 'Proverbs', 20, 1, 27, 'when your dread comes like a storm, and your destruction like a whirlwind, when distress and anguish overwhelm you.'),
  ('BSB', 'Proverbs', 20, 1, 28, 'Then they will call on me, but I will not answer; they will earnestly seek me, but will not find me.'),
  ('BSB', 'Proverbs', 20, 1, 29, 'For they hated knowledge and chose not to fear the LORD.'),
  ('BSB', 'Proverbs', 20, 1, 30, 'They accepted none of my counsel; they despised all my reproof.'),
  ('BSB', 'Proverbs', 20, 1, 31, 'So they will eat the fruit of their own way, and be filled with their own devices.'),
  ('BSB', 'Proverbs', 20, 1, 32, 'For the waywardness of the simple will slay them, and the complacency of fools will destroy them.'),
  ('BSB', 'Proverbs', 20, 1, 33, 'But whoever listens to me will dwell in safety, secure from the fear of evil.”'),
  ('BSB', 'Proverbs', 20, 2, 1, 'My son, if you accept my words and hide my commandments within you,'),
  ('BSB', 'Proverbs', 20, 2, 2, 'if you incline your ear to wisdom and direct your heart to understanding,'),
  ('BSB', 'Proverbs', 20, 2, 3, 'if you truly call out to insight and lift your voice to understanding,'),
  ('BSB', 'Proverbs', 20, 2, 4, 'if you seek it like silver and search it out like hidden treasure,'),
  ('BSB', 'Proverbs', 20, 2, 5, 'then you will discern the fear of the LORD and discover the knowledge of God.'),
  ('BSB', 'Proverbs', 20, 2, 6, 'For the LORD gives wisdom; from His mouth come knowledge and understanding.'),
  ('BSB', 'Proverbs', 20, 2, 7, 'He stores up sound wisdom for the upright; He is a shield to those who walk with integrity,'),
  ('BSB', 'Proverbs', 20, 2, 8, 'to guard the paths of justice and protect the way of His saints.'),
  ('BSB', 'Proverbs', 20, 2, 9, 'Then you will discern righteousness and justice and equity—every good path.'),
  ('BSB', 'Proverbs', 20, 2, 10, 'For wisdom will enter your heart, and knowledge will delight your soul.'),
  ('BSB', 'Proverbs', 20, 2, 11, 'Discretion will watch over you, and understanding will guard you,'),
  ('BSB', 'Proverbs', 20, 2, 12, 'to deliver you from the way of evil, from the man who speaks perversity,'),
  ('BSB', 'Proverbs', 20, 2, 13, 'from those who leave the straight paths to walk in the ways of darkness,'),
  ('BSB', 'Proverbs', 20, 2, 14, 'from those who enjoy doing evil and rejoice in the twistedness of evil,'),
  ('BSB', 'Proverbs', 20, 2, 15, 'whose paths are crooked and whose ways are devious.'),
  ('BSB', 'Proverbs', 20, 2, 16, 'It will rescue you from the forbidden woman, from the stranger with seductive words'),
  ('BSB', 'Proverbs', 20, 2, 17, 'who abandons the partner of her youth and forgets the covenant of her God.'),
  ('BSB', 'Proverbs', 20, 2, 18, 'For her house sinks down to death, and her tracks to the departed spirits.'),
  ('BSB', 'Proverbs', 20, 2, 19, 'None who go to her return or negotiate the paths of life.'),
  ('BSB', 'Proverbs', 20, 2, 20, 'So you will follow in the ways of the good, and keep to the paths of the righteous.'),
  ('BSB', 'Proverbs', 20, 2, 21, 'For the upright will inhabit the land, and the blameless will remain in it;'),
  ('BSB', 'Proverbs', 20, 2, 22, 'but the wicked will be cut off from the land, and the unfaithful will be uprooted.'),
  ('BSB', 'Proverbs', 20, 3, 1, 'My son, do not forget my teaching, but let your heart keep my commandments;'),
  ('BSB', 'Proverbs', 20, 3, 2, 'for they will add length to your days, years and peace to your life.'),
  ('BSB', 'Proverbs', 20, 3, 3, 'Never let loving devotion or faithfulness leave you; bind them around your neck, write them on the tablet of your heart.'),
  ('BSB', 'Proverbs', 20, 3, 4, 'Then you will find favor and high regard in the sight of God and man.'),
  ('BSB', 'Proverbs', 20, 3, 5, 'Trust in the LORD with all your heart, and lean not on your own understanding;'),
  ('BSB', 'Proverbs', 20, 3, 6, 'in all your ways acknowledge Him, and He will make your paths straight.'),
  ('BSB', 'Proverbs', 20, 3, 7, 'Be not wise in your own eyes; fear the LORD and turn away from evil.'),
  ('BSB', 'Proverbs', 20, 3, 8, 'This will bring healing to your body and refreshment to your bones.'),
  ('BSB', 'Proverbs', 20, 3, 9, 'Honor the LORD with your wealth and with the firstfruits of all your harvest;'),
  ('BSB', 'Proverbs', 20, 3, 10, 'then your barns will be filled with plenty, and your vats will overflow with new wine.'),
  ('BSB', 'Proverbs', 20, 3, 11, 'My son, do not reject the discipline of the LORD, and do not loathe His rebuke;'),
  ('BSB', 'Proverbs', 20, 3, 12, 'for the LORD disciplines the one He loves, as does a father the son in whom he delights.'),
  ('BSB', 'Proverbs', 20, 3, 13, 'Blessed is the man who finds wisdom, the man who acquires understanding,'),
  ('BSB', 'Proverbs', 20, 3, 14, 'for she is more profitable than silver, and her gain is better than fine gold.'),
  ('BSB', 'Proverbs', 20, 3, 15, 'She is more precious than rubies; nothing you desire compares with her.'),
  ('BSB', 'Proverbs', 20, 3, 16, 'Long life is in her right hand; in her left hand are riches and honor.'),
  ('BSB', 'Proverbs', 20, 3, 17, 'All her ways are pleasant, and all her paths are peaceful.'),
  ('BSB', 'Proverbs', 20, 3, 18, 'She is a tree of life to those who embrace her, and those who lay hold of her are blessed.'),
  ('BSB', 'Proverbs', 20, 3, 19, 'The LORD founded the earth by wisdom and established the heavens by understanding.'),
  ('BSB', 'Proverbs', 20, 3, 20, 'By His knowledge the watery depths were broken open, and the clouds dripped with dew.'),
  ('BSB', 'Proverbs', 20, 3, 21, 'My son, do not lose sight of this: Preserve sound judgment and discernment.'),
  ('BSB', 'Proverbs', 20, 3, 22, 'They will be life to your soul and adornment to your neck.'),
  ('BSB', 'Proverbs', 20, 3, 23, 'Then you will go on your way in safety, and your foot will not stumble.'),
  ('BSB', 'Proverbs', 20, 3, 24, 'When you lie down, you will not be afraid; when you rest, your sleep will be sweet.'),
  ('BSB', 'Proverbs', 20, 3, 25, 'Do not fear sudden danger or the ruin that overtakes the wicked,'),
  ('BSB', 'Proverbs', 20, 3, 26, 'for the LORD will be your confidence and will keep your foot from the snare.'),
  ('BSB', 'Proverbs', 20, 3, 27, 'Do not withhold good from the deserving when it is within your power to act.'),
  ('BSB', 'Proverbs', 20, 3, 28, 'Do not tell your neighbor, “Come back tomorrow and I will provide”— when you already have the means.'),
  ('BSB', 'Proverbs', 20, 3, 29, 'Do not devise evil against your neighbor, for he trustfully dwells beside you.'),
  ('BSB', 'Proverbs', 20, 3, 30, 'Do not accuse a man without cause, when he has done you no harm.'),
  ('BSB', 'Proverbs', 20, 3, 31, 'Do not envy a violent man or choose any of his ways;'),
  ('BSB', 'Proverbs', 20, 3, 32, 'for the LORD detests the perverse, but He is a friend to the upright.'),
  ('BSB', 'Proverbs', 20, 3, 33, 'The curse of the LORD is on the house of the wicked, but He blesses the home of the righteous.'),
  ('BSB', 'Proverbs', 20, 3, 34, 'He mocks the mockers, but gives grace to the humble.'),
  ('BSB', 'Proverbs', 20, 3, 35, 'The wise will inherit honor, but fools are held up to shame.'),
  ('BSB', 'Proverbs', 20, 4, 1, 'Listen, my sons, to a father’s instruction; pay attention and gain understanding.'),
  ('BSB', 'Proverbs', 20, 4, 2, 'For I give you sound teaching; do not abandon my directive.'),
  ('BSB', 'Proverbs', 20, 4, 3, 'When I was a son to my father, tender and the only child of my mother,'),
  ('BSB', 'Proverbs', 20, 4, 4, 'he taught me and said, “Let your heart lay hold of my words; keep my commands and you will live.'),
  ('BSB', 'Proverbs', 20, 4, 5, 'Get wisdom, get understanding; do not forget my words or turn from them.'),
  ('BSB', 'Proverbs', 20, 4, 6, 'Do not forsake wisdom, and she will preserve you; love her, and she will guard you.'),
  ('BSB', 'Proverbs', 20, 4, 7, 'Wisdom is supreme; so acquire wisdom. And whatever you may acquire, gain understanding.'),
  ('BSB', 'Proverbs', 20, 4, 8, 'Prize her, and she will exalt you; if you embrace her, she will honor you.'),
  ('BSB', 'Proverbs', 20, 4, 9, 'She will set a garland of grace on your head; she will present you with a crown of beauty.”'),
  ('BSB', 'Proverbs', 20, 4, 10, 'Listen, my son, and receive my words, and the years of your life will be many.'),
  ('BSB', 'Proverbs', 20, 4, 11, 'I will guide you in the way of wisdom; I will lead you on straight paths.'),
  ('BSB', 'Proverbs', 20, 4, 12, 'When you walk, your steps will not be impeded; when you run, you will not stumble.'),
  ('BSB', 'Proverbs', 20, 4, 13, 'Hold on to instruction; do not let go. Guard it, for it is your life.'),
  ('BSB', 'Proverbs', 20, 4, 14, 'Do not set foot on the path of the wicked or walk in the way of evildoers.'),
  ('BSB', 'Proverbs', 20, 4, 15, 'Avoid it; do not travel on it. Turn from it and pass on by.'),
  ('BSB', 'Proverbs', 20, 4, 16, 'For they cannot sleep unless they do evil; they are deprived of slumber until they make someone fall.'),
  ('BSB', 'Proverbs', 20, 4, 17, 'For they eat the bread of wickedness and drink the wine of violence.'),
  ('BSB', 'Proverbs', 20, 4, 18, 'The path of the righteous is like the first gleam of dawn, shining brighter and brighter until midday.'),
  ('BSB', 'Proverbs', 20, 4, 19, 'But the way of the wicked is like the darkest gloom; they do not know what makes them stumble.'),
  ('BSB', 'Proverbs', 20, 4, 20, 'My son, pay attention to my words; incline your ear to my sayings.'),
  ('BSB', 'Proverbs', 20, 4, 21, 'Do not lose sight of them; keep them within your heart.'),
  ('BSB', 'Proverbs', 20, 4, 22, 'For they are life to those who find them, and health to the whole body.'),
  ('BSB', 'Proverbs', 20, 4, 23, 'Guard your heart with all diligence, for from it flow springs of life.'),
  ('BSB', 'Proverbs', 20, 4, 24, 'Put away deception from your mouth; keep your lips from perverse speech.'),
  ('BSB', 'Proverbs', 20, 4, 25, 'Let your eyes look forward; fix your gaze straight ahead.'),
  ('BSB', 'Proverbs', 20, 4, 26, 'Make a level path for your feet, and all your ways will be sure.'),
  ('BSB', 'Proverbs', 20, 4, 27, 'Do not swerve to the right or to the left; turn your feet away from evil.'),
  ('BSB', 'Proverbs', 20, 5, 1, 'My son, pay attention to my wisdom; incline your ear to my insight,'),
  ('BSB', 'Proverbs', 20, 5, 2, 'that you may maintain discretion and your lips may preserve knowledge.'),
  ('BSB', 'Proverbs', 20, 5, 3, 'Though the lips of the forbidden woman drip honey and her speech is smoother than oil,'),
  ('BSB', 'Proverbs', 20, 5, 4, 'in the end she is bitter as wormwood, sharp as a double-edged sword.'),
  ('BSB', 'Proverbs', 20, 5, 5, 'Her feet go down to death; her steps lead straight to Sheol.'),
  ('BSB', 'Proverbs', 20, 5, 6, 'She does not consider the path of life; she does not know that her ways are unstable.'),
  ('BSB', 'Proverbs', 20, 5, 7, 'So now, my sons, listen to me, and do not turn aside from the words of my mouth.'),
  ('BSB', 'Proverbs', 20, 5, 8, 'Keep your path far from her; do not go near the door of her house,'),
  ('BSB', 'Proverbs', 20, 5, 9, 'lest you concede your vigor to others, and your years to one who is cruel;'),
  ('BSB', 'Proverbs', 20, 5, 10, 'lest strangers feast on your wealth, and your labors enrich the house of a foreigner.'),
  ('BSB', 'Proverbs', 20, 5, 11, 'At the end of your life you will groan when your flesh and your body are spent,'),
  ('BSB', 'Proverbs', 20, 5, 12, 'and you will say, “How I hated discipline, and my heart despised reproof!'),
  ('BSB', 'Proverbs', 20, 5, 13, 'I did not listen to the voice of my teachers or incline my ear to my mentors.'),
  ('BSB', 'Proverbs', 20, 5, 14, 'I am on the brink of utter ruin in the midst of the whole assembly.”'),
  ('BSB', 'Proverbs', 20, 5, 15, 'Drink water from your own cistern, and running water from your own well.'),
  ('BSB', 'Proverbs', 20, 5, 16, 'Why should your springs flow in the streets, your streams of water in the public squares?'),
  ('BSB', 'Proverbs', 20, 5, 17, 'Let them be yours alone, never to be shared with strangers.'),
  ('BSB', 'Proverbs', 20, 5, 18, 'May your fountain be blessed, and may you rejoice in the wife of your youth:'),
  ('BSB', 'Proverbs', 20, 5, 19, 'A loving doe, a graceful fawn— may her breasts satisfy you always; may you be captivated by her love forever.'),
  ('BSB', 'Proverbs', 20, 5, 20, 'Why be captivated, my son, by an adulteress, or embrace the bosom of a stranger?'),
  ('BSB', 'Proverbs', 20, 5, 21, 'For a man’s ways are before the eyes of the LORD, and the LORD examines all his paths.'),
  ('BSB', 'Proverbs', 20, 5, 22, 'The iniquities of a wicked man entrap him; the cords of his sin entangle him.'),
  ('BSB', 'Proverbs', 20, 5, 23, 'He dies for lack of discipline, led astray by his own great folly.'),
  ('BSB', 'Proverbs', 20, 6, 1, 'My son, if you have put up security for your neighbor, if you have struck hands in pledge with a stranger,'),
  ('BSB', 'Proverbs', 20, 6, 2, 'if you have been trapped by the words of your lips, ensnared by the words of your mouth,'),
  ('BSB', 'Proverbs', 20, 6, 3, 'then do this, my son, to free yourself, for you have fallen into your neighbor’s hands: Go, humble yourself, and press your plea with your neighbor.'),
  ('BSB', 'Proverbs', 20, 6, 4, 'Allow no sleep to your eyes or slumber to your eyelids.'),
  ('BSB', 'Proverbs', 20, 6, 5, 'Free yourself, like a gazelle from the hand of the hunter, like a bird from the snare of the fowler.'),
  ('BSB', 'Proverbs', 20, 6, 6, 'Walk in the manner of the ant, O slacker; observe its ways and become wise.'),
  ('BSB', 'Proverbs', 20, 6, 7, 'Without a commander, without an overseer or ruler,'),
  ('BSB', 'Proverbs', 20, 6, 8, 'it prepares its provisions in summer; it gathers its food at harvest.'),
  ('BSB', 'Proverbs', 20, 6, 9, 'How long will you lie there, O slacker? When will you get up from your sleep?'),
  ('BSB', 'Proverbs', 20, 6, 10, 'A little sleep, a little slumber, a little folding of the hands to rest,'),
  ('BSB', 'Proverbs', 20, 6, 11, 'and poverty will come upon you like a robber, and need like a bandit.'),
  ('BSB', 'Proverbs', 20, 6, 12, 'A worthless person, a wicked man, walks with a perverse mouth,'),
  ('BSB', 'Proverbs', 20, 6, 13, 'winking his eyes, speaking with his feet, and pointing with his fingers.'),
  ('BSB', 'Proverbs', 20, 6, 14, 'With deceit in his heart he devises evil; he continually sows discord.'),
  ('BSB', 'Proverbs', 20, 6, 15, 'Therefore calamity will come upon him suddenly; in an instant he will be shattered beyond recovery.'),
  ('BSB', 'Proverbs', 20, 6, 16, 'There are six things that the LORD hates, seven that are detestable to Him:'),
  ('BSB', 'Proverbs', 20, 6, 17, 'haughty eyes, a lying tongue, hands that shed innocent blood,'),
  ('BSB', 'Proverbs', 20, 6, 18, 'a heart that devises wicked schemes, feet that run swiftly to evil,'),
  ('BSB', 'Proverbs', 20, 6, 19, 'a false witness who gives false testimony, and one who stirs up discord among brothers.'),
  ('BSB', 'Proverbs', 20, 6, 20, 'My son, keep your father’s commandment, and do not forsake your mother’s teaching.'),
  ('BSB', 'Proverbs', 20, 6, 21, 'Bind them always upon your heart; tie them around your neck.'),
  ('BSB', 'Proverbs', 20, 6, 22, 'When you walk, they will guide you; when you lie down, they will watch over you; when you awake, they will speak to you.'),
  ('BSB', 'Proverbs', 20, 6, 23, 'For this commandment is a lamp, this teaching is a light, and the reproofs of discipline are the way to life,'),
  ('BSB', 'Proverbs', 20, 6, 24, 'to keep you from the evil woman, from the smooth tongue of the adulteress.'),
  ('BSB', 'Proverbs', 20, 6, 25, 'Do not lust in your heart for her beauty or let her captivate you with her eyes.'),
  ('BSB', 'Proverbs', 20, 6, 26, 'For the levy of the prostitute is poverty, and the adulteress preys upon your very life.'),
  ('BSB', 'Proverbs', 20, 6, 27, 'Can a man embrace fire and his clothes not be burned?'),
  ('BSB', 'Proverbs', 20, 6, 28, 'Can a man walk on hot coals without scorching his feet?'),
  ('BSB', 'Proverbs', 20, 6, 29, 'So is he who sleeps with another man’s wife; no one who touches her will go unpunished.'),
  ('BSB', 'Proverbs', 20, 6, 30, 'Men do not despise the thief if he steals to satisfy his hunger.'),
  ('BSB', 'Proverbs', 20, 6, 31, 'Yet if caught, he must pay sevenfold; he must give up all the wealth of his house.'),
  ('BSB', 'Proverbs', 20, 6, 32, 'He who commits adultery lacks judgment; whoever does so destroys himself.'),
  ('BSB', 'Proverbs', 20, 6, 33, 'Wounds and dishonor will befall him, and his reproach will never be wiped away.'),
  ('BSB', 'Proverbs', 20, 6, 34, 'For jealousy enrages a husband, and he will show no mercy in the day of vengeance.'),
  ('BSB', 'Proverbs', 20, 6, 35, 'He will not be appeased by any ransom, or persuaded by lavish gifts.'),
  ('BSB', 'Proverbs', 20, 7, 1, 'My son, keep my words and treasure my commandments within you.'),
  ('BSB', 'Proverbs', 20, 7, 2, 'Keep my commandments and live; guard my teachings as the apple of your eye.'),
  ('BSB', 'Proverbs', 20, 7, 3, 'Tie them to your fingers; write them on the tablet of your heart.'),
  ('BSB', 'Proverbs', 20, 7, 4, 'Say to wisdom, “You are my sister,” and call understanding your kinsman,'),
  ('BSB', 'Proverbs', 20, 7, 5, 'that they may keep you from the adulteress, from the stranger with seductive words.'),
  ('BSB', 'Proverbs', 20, 7, 6, 'For at the window of my house I looked through the lattice.'),
  ('BSB', 'Proverbs', 20, 7, 7, 'I saw among the simple, I noticed among the youths, a young man lacking judgment,'),
  ('BSB', 'Proverbs', 20, 7, 8, 'crossing the street near her corner, strolling down the road to her house,'),
  ('BSB', 'Proverbs', 20, 7, 9, 'at twilight, as the day was fading into the dark of the night.'),
  ('BSB', 'Proverbs', 20, 7, 10, 'Then a woman came out to meet him, with the attire of a harlot and cunning of heart.'),
  ('BSB', 'Proverbs', 20, 7, 11, 'She is loud and defiant; her feet do not remain at home.'),
  ('BSB', 'Proverbs', 20, 7, 12, 'Now in the street, now in the squares, she lurks at every corner.'),
  ('BSB', 'Proverbs', 20, 7, 13, 'She seizes him and kisses him; she brazenly says to him:'),
  ('BSB', 'Proverbs', 20, 7, 14, '“I have made my peace offerings; today I have paid my vows.'),
  ('BSB', 'Proverbs', 20, 7, 15, 'So I came out to meet you; I sought you, and I have found you.'),
  ('BSB', 'Proverbs', 20, 7, 16, 'I have decked my bed with coverings, with colored linen from Egypt.'),
  ('BSB', 'Proverbs', 20, 7, 17, 'I have perfumed my bed with myrrh, with aloes, and with cinnamon.'),
  ('BSB', 'Proverbs', 20, 7, 18, 'Come, let us take our fill of love till morning. Let us delight in loving caresses!'),
  ('BSB', 'Proverbs', 20, 7, 19, 'For my husband is not at home; he has gone on a long journey.'),
  ('BSB', 'Proverbs', 20, 7, 20, 'He took with him a bag of money and will not return till the moon is full.”'),
  ('BSB', 'Proverbs', 20, 7, 21, 'With her great persuasion she entices him; with her flattering lips she lures him.'),
  ('BSB', 'Proverbs', 20, 7, 22, 'He follows her on impulse, like an ox going to the slaughter, like a deer bounding into a trap,'),
  ('BSB', 'Proverbs', 20, 7, 23, 'until an arrow pierces his liver, like a bird darting into a snare— not knowing it will cost him his life.'),
  ('BSB', 'Proverbs', 20, 7, 24, 'Now, my sons, listen to me, and attend to the words of my mouth.'),
  ('BSB', 'Proverbs', 20, 7, 25, 'Do not let your heart turn aside to her ways; do not stray into her paths.'),
  ('BSB', 'Proverbs', 20, 7, 26, 'For she has brought many down to death; her slain are many in number.'),
  ('BSB', 'Proverbs', 20, 7, 27, 'Her house is the road to Sheol, descending to the chambers of death.'),
  ('BSB', 'Proverbs', 20, 8, 1, 'Does not wisdom call out, and understanding raise her voice?'),
  ('BSB', 'Proverbs', 20, 8, 2, 'On the heights overlooking the road, at the crossroads she takes her stand.'),
  ('BSB', 'Proverbs', 20, 8, 3, 'Beside the gates to the city, at the entrances she cries out:'),
  ('BSB', 'Proverbs', 20, 8, 4, '“To you, O men, I call out, and my cry is to the sons of men.'),
  ('BSB', 'Proverbs', 20, 8, 5, 'O simple ones, learn to be shrewd; O fools, gain understanding.'),
  ('BSB', 'Proverbs', 20, 8, 6, 'Listen, for I speak of noble things, and the opening of my lips will reveal right.'),
  ('BSB', 'Proverbs', 20, 8, 7, 'For my mouth will speak the truth, and wickedness is detestable to my lips.'),
  ('BSB', 'Proverbs', 20, 8, 8, 'All the words of my mouth are righteous; none are crooked or perverse.'),
  ('BSB', 'Proverbs', 20, 8, 9, 'They are all plain to the discerning, and upright to those who find knowledge.'),
  ('BSB', 'Proverbs', 20, 8, 10, 'Receive my instruction instead of silver, and knowledge rather than pure gold.'),
  ('BSB', 'Proverbs', 20, 8, 11, 'For wisdom is more precious than rubies, and nothing you desire compares with her.'),
  ('BSB', 'Proverbs', 20, 8, 12, 'I, wisdom, dwell together with prudence, and I find knowledge and discretion.'),
  ('BSB', 'Proverbs', 20, 8, 13, 'To fear the LORD is to hate evil; I hate arrogant pride, evil conduct, and perverse speech.'),
  ('BSB', 'Proverbs', 20, 8, 14, 'Counsel and sound judgment are mine; I have insight and strength.'),
  ('BSB', 'Proverbs', 20, 8, 15, 'By me kings reign, and rulers enact just laws;'),
  ('BSB', 'Proverbs', 20, 8, 16, 'By me princes rule, and all nobles who govern justly.'),
  ('BSB', 'Proverbs', 20, 8, 17, 'I love those who love me, and those who seek me early shall find me.'),
  ('BSB', 'Proverbs', 20, 8, 18, 'With me are riches and honor, enduring wealth and righteousness.'),
  ('BSB', 'Proverbs', 20, 8, 19, 'My fruit is better than gold, pure gold, and my harvest surpasses choice silver.'),
  ('BSB', 'Proverbs', 20, 8, 20, 'I walk in the way of righteousness, along the paths of justice,'),
  ('BSB', 'Proverbs', 20, 8, 21, 'bestowing wealth on those who love me and making their treasuries full.'),
  ('BSB', 'Proverbs', 20, 8, 22, 'The LORD created me as His first course, before His works of old.'),
  ('BSB', 'Proverbs', 20, 8, 23, 'From everlasting I was established, from the beginning, before the earth began.'),
  ('BSB', 'Proverbs', 20, 8, 24, 'When there were no watery depths, I was brought forth, when no springs were overflowing with water.'),
  ('BSB', 'Proverbs', 20, 8, 25, 'Before the mountains were settled, before the hills, I was brought forth,'),
  ('BSB', 'Proverbs', 20, 8, 26, 'before He made the land or fields, or any of the dust of the earth.'),
  ('BSB', 'Proverbs', 20, 8, 27, 'I was there when He established the heavens, when He inscribed a circle on the face of the deep,'),
  ('BSB', 'Proverbs', 20, 8, 28, 'when He established the clouds above, when the fountains of the deep gushed forth,'),
  ('BSB', 'Proverbs', 20, 8, 29, 'when He set a boundary for the sea, so that the waters would not surpass His command, when He marked out the foundations of the earth.'),
  ('BSB', 'Proverbs', 20, 8, 30, 'Then I was a skilled craftsman at His side, and His delight day by day, rejoicing always in His presence.'),
  ('BSB', 'Proverbs', 20, 8, 31, 'I was rejoicing in His whole world, delighting together in the sons of men.'),
  ('BSB', 'Proverbs', 20, 8, 32, 'Now therefore, my sons, listen to me, for blessed are those who keep my ways.'),
  ('BSB', 'Proverbs', 20, 8, 33, 'Listen to instruction and be wise; do not ignore it.'),
  ('BSB', 'Proverbs', 20, 8, 34, 'Blessed is the man who listens to me, watching daily at my doors, waiting at the posts of my doorway.'),
  ('BSB', 'Proverbs', 20, 8, 35, 'For whoever finds me finds life and obtains the favor of the LORD.'),
  ('BSB', 'Proverbs', 20, 8, 36, 'But he who fails to find me harms himself; all who hate me love death.”'),
  ('BSB', 'Proverbs', 20, 9, 1, 'Wisdom has built her house; she has carved out her seven pillars.'),
  ('BSB', 'Proverbs', 20, 9, 2, 'She has prepared her meat and mixed her wine; she has also set her table.'),
  ('BSB', 'Proverbs', 20, 9, 3, 'She has sent out her maidservants; she calls out from the heights of the city.'),
  ('BSB', 'Proverbs', 20, 9, 4, '“Whoever is simple, let him turn in here!” she says to him who lacks judgment.'),
  ('BSB', 'Proverbs', 20, 9, 5, '“Come, eat my bread and drink the wine I have mixed.'),
  ('BSB', 'Proverbs', 20, 9, 6, 'Leave your folly behind, and you will live; walk in the way of understanding.”'),
  ('BSB', 'Proverbs', 20, 9, 7, 'He who corrects a mocker brings shame on himself; he who rebukes a wicked man taints himself.'),
  ('BSB', 'Proverbs', 20, 9, 8, 'Do not rebuke a mocker, or he will hate you; rebuke a wise man, and he will love you.'),
  ('BSB', 'Proverbs', 20, 9, 9, 'Instruct a wise man, and he will be wiser still; teach a righteous man, and he will increase his learning.'),
  ('BSB', 'Proverbs', 20, 9, 10, 'The fear of the LORD is the beginning of wisdom, and knowledge of the Holy One is understanding.'),
  ('BSB', 'Proverbs', 20, 9, 11, 'For through wisdom your days will be multiplied, and years will be added to your life.'),
  ('BSB', 'Proverbs', 20, 9, 12, 'If you are wise, you are wise to your own advantage; but if you scoff, you alone will bear the consequences.'),
  ('BSB', 'Proverbs', 20, 9, 13, 'The woman named Folly is loud; she is naive and knows nothing.'),
  ('BSB', 'Proverbs', 20, 9, 14, 'She sits at the door of her house, on a seat in the heights of the city,'),
  ('BSB', 'Proverbs', 20, 9, 15, 'calling out to those who pass by, who make their paths straight.'),
  ('BSB', 'Proverbs', 20, 9, 16, '“Whoever is simple, let him turn in here!” she says to him who lacks judgment.'),
  ('BSB', 'Proverbs', 20, 9, 17, '“Stolen water is sweet, and bread eaten in secret is tasty!”'),
  ('BSB', 'Proverbs', 20, 9, 18, 'But they do not know that the dead are there, that her guests are in the depths of Sheol.'),
  ('BSB', 'Proverbs', 20, 10, 1, 'The proverbs of Solomon: A wise son brings joy to his father, but a foolish son grief to his mother.'),
  ('BSB', 'Proverbs', 20, 10, 2, 'Ill-gotten treasures profit nothing, but righteousness brings deliverance from death.'),
  ('BSB', 'Proverbs', 20, 10, 3, 'The LORD does not let the righteous go hungry, but He denies the craving of the wicked.'),
  ('BSB', 'Proverbs', 20, 10, 4, 'Idle hands make one poor, but diligent hands bring wealth.'),
  ('BSB', 'Proverbs', 20, 10, 5, 'He who gathers in summer is a wise son, but he who sleeps during harvest is a disgraceful son.'),
  ('BSB', 'Proverbs', 20, 10, 6, 'Blessings are on the head of the righteous, but the mouth of the wicked conceals violence.'),
  ('BSB', 'Proverbs', 20, 10, 7, 'The memory of the righteous is a blessing, but the name of the wicked will rot.'),
  ('BSB', 'Proverbs', 20, 10, 8, 'A wise heart will receive commandments, but foolish lips will come to ruin.'),
  ('BSB', 'Proverbs', 20, 10, 9, 'He who walks in integrity walks securely, but he who perverts his ways will be found out.'),
  ('BSB', 'Proverbs', 20, 10, 10, 'He who winks the eye causes grief, and foolish lips will come to ruin.'),
  ('BSB', 'Proverbs', 20, 10, 11, 'The mouth of the righteous is a fountain of life, but the mouth of the wicked conceals violence.'),
  ('BSB', 'Proverbs', 20, 10, 12, 'Hatred stirs up dissension, but love covers all transgressions.'),
  ('BSB', 'Proverbs', 20, 10, 13, 'Wisdom is found on the lips of the discerning, but a rod is for the back of him who lacks judgment.'),
  ('BSB', 'Proverbs', 20, 10, 14, 'The wise store up knowledge, but the mouth of the fool invites destruction.'),
  ('BSB', 'Proverbs', 20, 10, 15, 'The wealth of the rich man is his fortified city, but poverty is the ruin of the poor.'),
  ('BSB', 'Proverbs', 20, 10, 16, 'The labor of the righteous leads to life, but the gain of the wicked brings punishment.'),
  ('BSB', 'Proverbs', 20, 10, 17, 'Whoever heeds instruction is on the path to life, but he who ignores reproof goes astray.'),
  ('BSB', 'Proverbs', 20, 10, 18, 'The one who conceals hatred has lying lips, and whoever spreads slander is a fool.'),
  ('BSB', 'Proverbs', 20, 10, 19, 'When words are many, sin is unavoidable, but he who restrains his lips is wise.'),
  ('BSB', 'Proverbs', 20, 10, 20, 'The tongue of the righteous is choice silver, but the heart of the wicked has little worth.'),
  ('BSB', 'Proverbs', 20, 10, 21, 'The lips of the righteous feed many, but fools die for lack of judgment.'),
  ('BSB', 'Proverbs', 20, 10, 22, 'The blessing of the LORD enriches, and He adds no sorrow to it.'),
  ('BSB', 'Proverbs', 20, 10, 23, 'The fool delights in shameful conduct, but a man of understanding has wisdom.'),
  ('BSB', 'Proverbs', 20, 10, 24, 'What the wicked man dreads will overtake him, but the desire of the righteous will be granted.'),
  ('BSB', 'Proverbs', 20, 10, 25, 'When the whirlwind passes, the wicked are no more, but the righteous are secure forever.'),
  ('BSB', 'Proverbs', 20, 10, 26, 'Like vinegar to the teeth and smoke to the eyes, so is the slacker to those who send him.'),
  ('BSB', 'Proverbs', 20, 10, 27, 'The fear of the LORD prolongs life, but the years of the wicked will be cut short.'),
  ('BSB', 'Proverbs', 20, 10, 28, 'The hope of the righteous is joy, but the expectations of the wicked will perish.'),
  ('BSB', 'Proverbs', 20, 10, 29, 'The way of the LORD is a refuge to the upright, but destruction awaits those who do evil.'),
  ('BSB', 'Proverbs', 20, 10, 30, 'The righteous will never be shaken, but the wicked will not inhabit the land.'),
  ('BSB', 'Proverbs', 20, 10, 31, 'The mouth of the righteous brings forth wisdom, but a perverse tongue will be cut out.'),
  ('BSB', 'Proverbs', 20, 10, 32, 'The lips of the righteous know what is fitting, but the mouth of the wicked is perverse.'),
  ('BSB', 'Proverbs', 20, 11, 1, 'Dishonest scales are an abomination to the LORD, but an accurate weight is His delight.'),
  ('BSB', 'Proverbs', 20, 11, 2, 'When pride comes, disgrace follows, but with humility comes wisdom.'),
  ('BSB', 'Proverbs', 20, 11, 3, 'The integrity of the upright guides them, but the perversity of the faithless destroys them.'),
  ('BSB', 'Proverbs', 20, 11, 4, 'Riches are worthless in the day of wrath, but righteousness brings deliverance from death.'),
  ('BSB', 'Proverbs', 20, 11, 5, 'The righteousness of the blameless directs their path, but the wicked fall by their own wickedness.'),
  ('BSB', 'Proverbs', 20, 11, 6, 'The righteousness of the upright delivers them, but the faithless are trapped by their own desires.'),
  ('BSB', 'Proverbs', 20, 11, 7, 'When the wicked man dies, his hope perishes, and the hope of his strength vanishes.'),
  ('BSB', 'Proverbs', 20, 11, 8, 'The righteous man is delivered from trouble; in his place the wicked man goes in.'),
  ('BSB', 'Proverbs', 20, 11, 9, 'With his mouth the ungodly man destroys his neighbor, but through knowledge the righteous are rescued.'),
  ('BSB', 'Proverbs', 20, 11, 10, 'When the righteous thrive, the city rejoices, and when the wicked perish, there are shouts of joy.'),
  ('BSB', 'Proverbs', 20, 11, 11, 'By the blessing of the upright a city is built up, but by the mouth of the wicked it is torn down.'),
  ('BSB', 'Proverbs', 20, 11, 12, 'Whoever shows contempt for his neighbor lacks judgment, but a man of understanding remains silent.'),
  ('BSB', 'Proverbs', 20, 11, 13, 'A gossip reveals a secret, but a trustworthy person keeps a confidence.'),
  ('BSB', 'Proverbs', 20, 11, 14, 'For lack of guidance, a nation falls, but with many counselors comes deliverance.'),
  ('BSB', 'Proverbs', 20, 11, 15, 'He who puts up security for a stranger will surely suffer, but the one who hates indebtedness is secure.'),
  ('BSB', 'Proverbs', 20, 11, 16, 'A gracious woman attains honor, but ruthless men gain only wealth.'),
  ('BSB', 'Proverbs', 20, 11, 17, 'A kind man benefits himself, but a cruel man brings trouble on himself.'),
  ('BSB', 'Proverbs', 20, 11, 18, 'The wicked man earns an empty wage, but he who sows righteousness reaps a true reward.'),
  ('BSB', 'Proverbs', 20, 11, 19, 'Genuine righteousness leads to life, but the pursuit of evil brings death.'),
  ('BSB', 'Proverbs', 20, 11, 20, 'The perverse in heart are an abomination to the LORD, but the blameless in their walk are His delight.'),
  ('BSB', 'Proverbs', 20, 11, 21, 'Be assured that the wicked will not go unpunished, but the offspring of the righteous will escape.'),
  ('BSB', 'Proverbs', 20, 11, 22, 'Like a gold ring in a pig’s snout is a beautiful woman who lacks discretion.'),
  ('BSB', 'Proverbs', 20, 11, 23, 'The desire of the righteous leads only to good, but the hope of the wicked brings wrath.'),
  ('BSB', 'Proverbs', 20, 11, 24, 'One gives freely, yet gains even more; another withholds what is right, only to become poor.'),
  ('BSB', 'Proverbs', 20, 11, 25, 'A generous soul will prosper, and he who refreshes others will himself be refreshed.'),
  ('BSB', 'Proverbs', 20, 11, 26, 'The people will curse the hoarder of grain, but blessing will crown the one who sells it.'),
  ('BSB', 'Proverbs', 20, 11, 27, 'He who searches out good finds favor, but evil will come to him who seeks it.'),
  ('BSB', 'Proverbs', 20, 11, 28, 'He who trusts in his riches will fall, but the righteous will thrive like foliage.'),
  ('BSB', 'Proverbs', 20, 11, 29, 'He who brings trouble on his house will inherit the wind, and the fool will be servant to the wise of heart.'),
  ('BSB', 'Proverbs', 20, 11, 30, 'The fruit of the righteous is a tree of life, and he who wins souls is wise.'),
  ('BSB', 'Proverbs', 20, 11, 31, 'If the righteous receive their due on earth, how much more the ungodly and the sinner!'),
  ('BSB', 'Proverbs', 20, 12, 1, 'Whoever loves discipline loves knowledge, but he who hates correction is stupid.'),
  ('BSB', 'Proverbs', 20, 12, 2, 'The good man obtains favor from the LORD, but the LORD condemns a man who devises evil.'),
  ('BSB', 'Proverbs', 20, 12, 3, 'A man cannot be established through wickedness, but the righteous cannot be uprooted.'),
  ('BSB', 'Proverbs', 20, 12, 4, 'A wife of noble character is her husband’s crown, but she who causes shame is like decay in his bones.'),
  ('BSB', 'Proverbs', 20, 12, 5, 'The plans of the righteous are just, but the counsel of the wicked leads to deceit.'),
  ('BSB', 'Proverbs', 20, 12, 6, 'The words of the wicked lie in wait for blood, but the speech of the upright rescues them.'),
  ('BSB', 'Proverbs', 20, 12, 7, 'The wicked are overthrown and perish, but the house of the righteous will stand.'),
  ('BSB', 'Proverbs', 20, 12, 8, 'A man is praised according to his wisdom, but a twisted mind is despised.'),
  ('BSB', 'Proverbs', 20, 12, 9, 'Better to be lightly esteemed yet have a servant, than to be self-important but lack food.'),
  ('BSB', 'Proverbs', 20, 12, 10, 'A righteous man regards the life of his animal, but the tender mercies of the wicked are only cruelty.'),
  ('BSB', 'Proverbs', 20, 12, 11, 'The one who works his land will have plenty of food, but whoever chases fantasies lacks judgment.'),
  ('BSB', 'Proverbs', 20, 12, 12, 'The wicked desire the plunder of evil men, but the root of the righteous flourishes.'),
  ('BSB', 'Proverbs', 20, 12, 13, 'An evil man is trapped by his rebellious speech, but a righteous man escapes from trouble.'),
  ('BSB', 'Proverbs', 20, 12, 14, 'By fruitful speech a man is filled with good things, and the work of his hands returns to him.'),
  ('BSB', 'Proverbs', 20, 12, 15, 'The way of a fool is right in his own eyes, but a wise man listens to counsel.'),
  ('BSB', 'Proverbs', 20, 12, 16, 'A fool’s anger is known at once, but a prudent man overlooks an insult.'),
  ('BSB', 'Proverbs', 20, 12, 17, 'He who speaks the truth declares what is right, but a false witness speaks deceit.'),
  ('BSB', 'Proverbs', 20, 12, 18, 'Speaking rashly is like a piercing sword, but the tongue of the wise brings healing.'),
  ('BSB', 'Proverbs', 20, 12, 19, 'Truthful lips endure forever, but a lying tongue lasts only a moment.'),
  ('BSB', 'Proverbs', 20, 12, 20, 'Deceit is in the hearts of those who devise evil, but the counselors of peace have joy.'),
  ('BSB', 'Proverbs', 20, 12, 21, 'No harm befalls the righteous, but the wicked are filled with trouble.'),
  ('BSB', 'Proverbs', 20, 12, 22, 'Lying lips are detestable to the LORD, but those who deal faithfully are His delight.'),
  ('BSB', 'Proverbs', 20, 12, 23, 'A shrewd man keeps his knowledge to himself, but a foolish heart proclaims its folly.'),
  ('BSB', 'Proverbs', 20, 12, 24, 'The hand of the diligent will rule, but laziness ends in forced labor.'),
  ('BSB', 'Proverbs', 20, 12, 25, 'Anxiety weighs down the heart of a man, but a good word cheers it up.'),
  ('BSB', 'Proverbs', 20, 12, 26, 'A righteous man is cautious in friendship, but the ways of the wicked lead them astray.'),
  ('BSB', 'Proverbs', 20, 12, 27, 'A lazy man does not roast his game, but a diligent man prizes his possession.'),
  ('BSB', 'Proverbs', 20, 12, 28, 'There is life in the path of righteousness, but another path leads to death.'),
  ('BSB', 'Proverbs', 20, 13, 1, 'A wise son heeds his father’s discipline, but a mocker does not listen to rebuke.'),
  ('BSB', 'Proverbs', 20, 13, 2, 'From the fruit of his lips a man enjoys good things, but the desire of the faithless is violence.'),
  ('BSB', 'Proverbs', 20, 13, 3, 'He who guards his mouth protects his life, but the one who opens his lips invites his own ruin.'),
  ('BSB', 'Proverbs', 20, 13, 4, 'The slacker craves yet has nothing, but the soul of the diligent is fully satisfied.'),
  ('BSB', 'Proverbs', 20, 13, 5, 'The righteous hate falsehood, but the wicked bring shame and disgrace.'),
  ('BSB', 'Proverbs', 20, 13, 6, 'Righteousness guards the man of integrity, but wickedness undermines the sinner.'),
  ('BSB', 'Proverbs', 20, 13, 7, 'One pretends to be rich, but has nothing; another pretends to be poor, yet has great wealth.'),
  ('BSB', 'Proverbs', 20, 13, 8, 'Riches may ransom a man’s life, but a poor man hears no threat.'),
  ('BSB', 'Proverbs', 20, 13, 9, 'The light of the righteous shines brightly, but the lamp of the wicked is extinguished.'),
  ('BSB', 'Proverbs', 20, 13, 10, 'Arrogance leads only to strife, but wisdom is with the well-advised.'),
  ('BSB', 'Proverbs', 20, 13, 11, 'Dishonest wealth will dwindle, but what is earned through hard work will be multiplied.'),
  ('BSB', 'Proverbs', 20, 13, 12, 'Hope deferred makes the heart sick, but desire fulfilled is a tree of life.'),
  ('BSB', 'Proverbs', 20, 13, 13, 'He who despises instruction will pay the penalty, but the one who respects a command will be rewarded.'),
  ('BSB', 'Proverbs', 20, 13, 14, 'The teaching of the wise is a fountain of life, turning one from the snares of death.'),
  ('BSB', 'Proverbs', 20, 13, 15, 'Good understanding wins favor, but the way of the faithless is difficult.'),
  ('BSB', 'Proverbs', 20, 13, 16, 'Every prudent man acts with knowledge, but a fool displays his folly.'),
  ('BSB', 'Proverbs', 20, 13, 17, 'A wicked messenger falls into trouble, but a faithful envoy brings healing.'),
  ('BSB', 'Proverbs', 20, 13, 18, 'Poverty and shame come to him who ignores discipline, but whoever heeds correction is honored.'),
  ('BSB', 'Proverbs', 20, 13, 19, 'Desire fulfilled is sweet to the soul, but turning from evil is detestable to fools.'),
  ('BSB', 'Proverbs', 20, 13, 20, 'He who walks with the wise will become wise, but the companion of fools will be destroyed.'),
  ('BSB', 'Proverbs', 20, 13, 21, 'Disaster pursues sinners, but prosperity is the reward of the righteous.'),
  ('BSB', 'Proverbs', 20, 13, 22, 'A good man leaves an inheritance to his children’s children, but the sinner’s wealth is passed to the righteous.'),
  ('BSB', 'Proverbs', 20, 13, 23, 'Abundant food is in the fallow ground of the poor, but without justice it is swept away.'),
  ('BSB', 'Proverbs', 20, 13, 24, 'He who spares the rod hates his son, but he who loves him disciplines him diligently.'),
  ('BSB', 'Proverbs', 20, 13, 25, 'A righteous man eats to his heart’s content, but the stomach of the wicked is empty.'),
  ('BSB', 'Proverbs', 20, 14, 1, 'Every wise woman builds her house, but a foolish one tears it down with her own hands.'),
  ('BSB', 'Proverbs', 20, 14, 2, 'He who walks in uprightness fears the LORD, but the one who is devious in his ways despises Him.'),
  ('BSB', 'Proverbs', 20, 14, 3, 'The proud speech of a fool brings a rod to his back, but the lips of the wise protect them.'),
  ('BSB', 'Proverbs', 20, 14, 4, 'Where there are no oxen, the manger is empty, but an abundant harvest comes through the strength of the ox.'),
  ('BSB', 'Proverbs', 20, 14, 5, 'An honest witness does not deceive, but a dishonest witness pours forth lies.'),
  ('BSB', 'Proverbs', 20, 14, 6, 'A mocker seeks wisdom and finds none, but knowledge comes easily to the discerning.'),
  ('BSB', 'Proverbs', 20, 14, 7, 'Stay away from a foolish man; you will gain no knowledge from his speech.'),
  ('BSB', 'Proverbs', 20, 14, 8, 'The wisdom of the prudent is to discern his way, but the folly of fools deceives them.'),
  ('BSB', 'Proverbs', 20, 14, 9, 'Fools mock the making of amends, but goodwill is found among the upright.'),
  ('BSB', 'Proverbs', 20, 14, 10, 'The heart knows its own bitterness, and no stranger shares in its joy.'),
  ('BSB', 'Proverbs', 20, 14, 11, 'The house of the wicked will be destroyed, but the tent of the upright will flourish.'),
  ('BSB', 'Proverbs', 20, 14, 12, 'There is a way that seems right to a man, but its end is the way of death.'),
  ('BSB', 'Proverbs', 20, 14, 13, 'Even in laughter the heart may ache, and joy may end in sorrow.'),
  ('BSB', 'Proverbs', 20, 14, 14, 'The backslider in heart receives the fill of his own ways, but a good man is rewarded for his ways.'),
  ('BSB', 'Proverbs', 20, 14, 15, 'The simple man believes every word, but the prudent man watches his steps.'),
  ('BSB', 'Proverbs', 20, 14, 16, 'A wise man fears and turns from evil, but a fool is careless and reckless.'),
  ('BSB', 'Proverbs', 20, 14, 17, 'A quick-tempered man acts foolishly, and a devious man is hated.'),
  ('BSB', 'Proverbs', 20, 14, 18, 'The simple inherit folly, but the prudent are crowned with knowledge.'),
  ('BSB', 'Proverbs', 20, 14, 19, 'The evil bow before the good, and the wicked at the gates of the righteous.'),
  ('BSB', 'Proverbs', 20, 14, 20, 'The poor man is hated even by his neighbor, but many are those who love the rich.'),
  ('BSB', 'Proverbs', 20, 14, 21, 'He who despises his neighbor sins, but blessed is he who shows kindness to the poor.'),
  ('BSB', 'Proverbs', 20, 14, 22, 'Do not those who contrive evil go astray? But those who plan goodness find loving devotion and faithfulness.'),
  ('BSB', 'Proverbs', 20, 14, 23, 'There is profit in all labor, but mere talk leads only to poverty.'),
  ('BSB', 'Proverbs', 20, 14, 24, 'The crown of the wise is their wealth, but the effort of fools is folly.'),
  ('BSB', 'Proverbs', 20, 14, 25, 'A truthful witness saves lives, but one who utters lies is deceitful.'),
  ('BSB', 'Proverbs', 20, 14, 26, 'He who fears the LORD is secure in confidence, and his children shall have a place of refuge.'),
  ('BSB', 'Proverbs', 20, 14, 27, 'The fear of the LORD is a fountain of life, turning a man from the snares of death.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Proverbs', 20, 14, 28, 'A large population is a king’s splendor, but a lack of subjects is a prince’s ruin.'),
  ('BSB', 'Proverbs', 20, 14, 29, 'A patient man has great understanding, but a quick-tempered man promotes folly.'),
  ('BSB', 'Proverbs', 20, 14, 30, 'A tranquil heart is life to the body, but envy rots the bones.'),
  ('BSB', 'Proverbs', 20, 14, 31, 'Whoever oppresses the poor taunts their Maker, but whoever is kind to the needy honors Him.'),
  ('BSB', 'Proverbs', 20, 14, 32, 'The wicked man is thrown down by his own sin, but the righteous man has a refuge even in death.'),
  ('BSB', 'Proverbs', 20, 14, 33, 'Wisdom rests in the heart of the discerning; even among fools she is known.'),
  ('BSB', 'Proverbs', 20, 14, 34, 'Righteousness exalts a nation, but sin is a disgrace to any people.'),
  ('BSB', 'Proverbs', 20, 14, 35, 'A king delights in a wise servant, but his anger falls on the shameful.'),
  ('BSB', 'Proverbs', 20, 15, 1, 'A gentle answer turns away wrath, but a harsh word stirs up anger.'),
  ('BSB', 'Proverbs', 20, 15, 2, 'The tongue of the wise commends knowledge, but the mouth of the fool spouts folly.'),
  ('BSB', 'Proverbs', 20, 15, 3, 'The eyes of the LORD are in every place, observing the evil and the good.'),
  ('BSB', 'Proverbs', 20, 15, 4, 'A soothing tongue is a tree of life, but a perverse tongue crushes the spirit.'),
  ('BSB', 'Proverbs', 20, 15, 5, 'A fool rejects his father’s discipline, but whoever heeds correction is prudent.'),
  ('BSB', 'Proverbs', 20, 15, 6, 'The house of the righteous has great treasure, but the income of the wicked is trouble.'),
  ('BSB', 'Proverbs', 20, 15, 7, 'The lips of the wise spread knowledge, but not so the hearts of fools.'),
  ('BSB', 'Proverbs', 20, 15, 8, 'The sacrifice of the wicked is detestable to the LORD, but the prayer of the upright is His delight.'),
  ('BSB', 'Proverbs', 20, 15, 9, 'The LORD detests the way of the wicked, but He loves those who pursue righteousness.'),
  ('BSB', 'Proverbs', 20, 15, 10, 'Discipline is harsh for him who leaves the path; he who hates correction will die.'),
  ('BSB', 'Proverbs', 20, 15, 11, 'Sheol and Abaddon lie open before the LORD— how much more the hearts of men!'),
  ('BSB', 'Proverbs', 20, 15, 12, 'A mocker does not love to be reproved, nor will he consult the wise.'),
  ('BSB', 'Proverbs', 20, 15, 13, 'A joyful heart makes a cheerful countenance, but sorrow of the heart crushes the spirit.'),
  ('BSB', 'Proverbs', 20, 15, 14, 'A discerning heart seeks knowledge, but the mouth of a fool feeds on folly.'),
  ('BSB', 'Proverbs', 20, 15, 15, 'All the days of the oppressed are bad, but a cheerful heart has a continual feast.'),
  ('BSB', 'Proverbs', 20, 15, 16, 'Better a little with the fear of the LORD than great treasure with turmoil.'),
  ('BSB', 'Proverbs', 20, 15, 17, 'Better a dish of vegetables where there is love than a fattened ox with hatred.'),
  ('BSB', 'Proverbs', 20, 15, 18, 'A hot-tempered man stirs up strife, but he who is slow to anger calms dispute.'),
  ('BSB', 'Proverbs', 20, 15, 19, 'The way of the slacker is like a hedge of thorns, but the path of the upright is a highway.'),
  ('BSB', 'Proverbs', 20, 15, 20, 'A wise son brings joy to his father, but a foolish man despises his mother.'),
  ('BSB', 'Proverbs', 20, 15, 21, 'Folly is joy to one who lacks judgment, but a man of understanding walks a straight path.'),
  ('BSB', 'Proverbs', 20, 15, 22, 'Plans fail for lack of counsel, but with many advisers they succeed.'),
  ('BSB', 'Proverbs', 20, 15, 23, 'A man takes joy in a fitting reply— and how good is a timely word!'),
  ('BSB', 'Proverbs', 20, 15, 24, 'The path of life leads upward for the wise, that he may avoid going down to Sheol.'),
  ('BSB', 'Proverbs', 20, 15, 25, 'The LORD tears down the house of the proud, but He protects the boundaries of the widow.'),
  ('BSB', 'Proverbs', 20, 15, 26, 'The LORD detests the thoughts of the wicked, but the words of the pure are pleasant to Him.'),
  ('BSB', 'Proverbs', 20, 15, 27, 'He who is greedy for unjust gain brings trouble on his household, but he who hates bribes will live.'),
  ('BSB', 'Proverbs', 20, 15, 28, 'The heart of the righteous ponders how to answer, but the mouth of the wicked blurts out evil.'),
  ('BSB', 'Proverbs', 20, 15, 29, 'The LORD is far from the wicked, but He hears the prayer of the righteous.'),
  ('BSB', 'Proverbs', 20, 15, 30, 'The light of the eyes cheers the heart, and good news nourishes the bones.'),
  ('BSB', 'Proverbs', 20, 15, 31, 'He who listens to life-giving reproof will dwell among the wise.'),
  ('BSB', 'Proverbs', 20, 15, 32, 'He who ignores discipline despises himself, but whoever heeds correction gains understanding.'),
  ('BSB', 'Proverbs', 20, 15, 33, 'The fear of the LORD is the instruction of wisdom, and humility comes before honor.'),
  ('BSB', 'Proverbs', 20, 16, 1, 'The plans of the heart belong to man, but the reply of the tongue is from the LORD.'),
  ('BSB', 'Proverbs', 20, 16, 2, 'All a man’s ways are pure in his own eyes, but his motives are weighed out by the LORD.'),
  ('BSB', 'Proverbs', 20, 16, 3, 'Commit your works to the LORD and your plans will be achieved.'),
  ('BSB', 'Proverbs', 20, 16, 4, 'The LORD has made everything for His purpose— even the wicked for the day of disaster.'),
  ('BSB', 'Proverbs', 20, 16, 5, 'Everyone who is proud in heart is detestable to the LORD; be assured that he will not go unpunished.'),
  ('BSB', 'Proverbs', 20, 16, 6, 'By loving devotion and faithfulness iniquity is atoned for, and by the fear of the LORD one turns aside from evil.'),
  ('BSB', 'Proverbs', 20, 16, 7, 'When a man’s ways please the LORD, He makes even the man’s enemies live at peace with him.'),
  ('BSB', 'Proverbs', 20, 16, 8, 'Better a little with righteousness than great gain with injustice.'),
  ('BSB', 'Proverbs', 20, 16, 9, 'A man’s heart plans his course, but the LORD determines his steps.'),
  ('BSB', 'Proverbs', 20, 16, 10, 'A divine verdict is on the lips of a king; his mouth must not betray justice.'),
  ('BSB', 'Proverbs', 20, 16, 11, 'Honest scales and balances are from the LORD; all the weights in the bag are His concern.'),
  ('BSB', 'Proverbs', 20, 16, 12, 'Wicked behavior is detestable to kings, for a throne is established through righteousness.'),
  ('BSB', 'Proverbs', 20, 16, 13, 'Righteous lips are a king’s delight, and he who speaks honestly is beloved.'),
  ('BSB', 'Proverbs', 20, 16, 14, 'The wrath of a king is a messenger of death, but a wise man will pacify it.'),
  ('BSB', 'Proverbs', 20, 16, 15, 'When a king’s face brightens, there is life; his favor is like a rain cloud in spring.'),
  ('BSB', 'Proverbs', 20, 16, 16, 'How much better to acquire wisdom than gold! To gain understanding is more desirable than silver.'),
  ('BSB', 'Proverbs', 20, 16, 17, 'The highway of the upright leads away from evil; he who guards his way protects his life.'),
  ('BSB', 'Proverbs', 20, 16, 18, 'Pride goes before destruction, and a haughty spirit before a fall.'),
  ('BSB', 'Proverbs', 20, 16, 19, 'It is better to be lowly in spirit among the humble than to divide the spoil with the proud.'),
  ('BSB', 'Proverbs', 20, 16, 20, 'Whoever heeds instruction will find success, and blessed is he who trusts in the LORD.'),
  ('BSB', 'Proverbs', 20, 16, 21, 'The wise in heart are called discerning, and pleasant speech promotes instruction.'),
  ('BSB', 'Proverbs', 20, 16, 22, 'Understanding is a fountain of life to its possessor, but the discipline of fools is folly.'),
  ('BSB', 'Proverbs', 20, 16, 23, 'The heart of the wise man instructs his mouth and adds persuasiveness to his lips.'),
  ('BSB', 'Proverbs', 20, 16, 24, 'Pleasant words are a honeycomb, sweet to the soul and healing to the bones.'),
  ('BSB', 'Proverbs', 20, 16, 25, 'There is a way that seems right to a man, but its end is the way of death.'),
  ('BSB', 'Proverbs', 20, 16, 26, 'A worker’s appetite works for him because his hunger drives him onward.'),
  ('BSB', 'Proverbs', 20, 16, 27, 'A worthless man digs up evil, and his speech is like a scorching fire.'),
  ('BSB', 'Proverbs', 20, 16, 28, 'A perverse man spreads dissension, and a gossip divides close friends.'),
  ('BSB', 'Proverbs', 20, 16, 29, 'A violent man entices his neighbor and leads him down a path that is not good.'),
  ('BSB', 'Proverbs', 20, 16, 30, 'He who winks his eye devises perversity; he who purses his lips is bent on evil.'),
  ('BSB', 'Proverbs', 20, 16, 31, 'Gray hair is a crown of glory; it is attained along the path of righteousness.'),
  ('BSB', 'Proverbs', 20, 16, 32, 'He who is slow to anger is better than a warrior, and he who controls his temper is greater than one who captures a city.'),
  ('BSB', 'Proverbs', 20, 16, 33, 'The lot is cast into the lap, but its every decision is from the LORD.'),
  ('BSB', 'Proverbs', 20, 17, 1, 'Better a dry morsel in quietness than a house full of feasting with strife.'),
  ('BSB', 'Proverbs', 20, 17, 2, 'A wise servant will rule over a disgraceful son and share his inheritance as one of the brothers.'),
  ('BSB', 'Proverbs', 20, 17, 3, 'A crucible for silver and a furnace for gold, but the LORD is the tester of hearts.'),
  ('BSB', 'Proverbs', 20, 17, 4, 'A wicked man listens to evil lips; a liar gives ear to a destructive tongue.'),
  ('BSB', 'Proverbs', 20, 17, 5, 'He who mocks the poor insults their Maker; whoever gloats over calamity will not go unpunished.'),
  ('BSB', 'Proverbs', 20, 17, 6, 'Grandchildren are the crown of the aged, and the glory of a son is his father.'),
  ('BSB', 'Proverbs', 20, 17, 7, 'Eloquent words are unfit for a fool; how much worse are lying lips to a ruler!'),
  ('BSB', 'Proverbs', 20, 17, 8, 'A bribe is a charm to its giver; wherever he turns, he succeeds.'),
  ('BSB', 'Proverbs', 20, 17, 9, 'Whoever conceals an offense promotes love, but he who brings it up separates friends.'),
  ('BSB', 'Proverbs', 20, 17, 10, 'A rebuke cuts into a man of discernment deeper than a hundred lashes cut into a fool.'),
  ('BSB', 'Proverbs', 20, 17, 11, 'An evil man seeks only rebellion; a cruel messenger will be sent against him.'),
  ('BSB', 'Proverbs', 20, 17, 12, 'It is better to meet a bear robbed of her cubs than a fool in his folly.'),
  ('BSB', 'Proverbs', 20, 17, 13, 'If anyone returns evil for good, evil will never leave his house.'),
  ('BSB', 'Proverbs', 20, 17, 14, 'To start a quarrel is to release a flood; so abandon the dispute before it breaks out.'),
  ('BSB', 'Proverbs', 20, 17, 15, 'Acquitting the guilty and condemning the righteous— both are detestable to the LORD.'),
  ('BSB', 'Proverbs', 20, 17, 16, 'Why should the fool have money in his hand with no intention of buying wisdom?'),
  ('BSB', 'Proverbs', 20, 17, 17, 'A friend loves at all times, and a brother is born for adversity.'),
  ('BSB', 'Proverbs', 20, 17, 18, 'A man lacking judgment strikes hands in pledge and puts up security for his neighbor.'),
  ('BSB', 'Proverbs', 20, 17, 19, 'He who loves transgression loves strife; he who builds his gate high invites destruction.'),
  ('BSB', 'Proverbs', 20, 17, 20, 'The one with a perverse heart finds no good, and he whose tongue is deceitful falls into trouble.'),
  ('BSB', 'Proverbs', 20, 17, 21, 'A man fathers a fool to his own grief; the father of a fool has no joy.'),
  ('BSB', 'Proverbs', 20, 17, 22, 'A joyful heart is good medicine, but a broken spirit dries up the bones.'),
  ('BSB', 'Proverbs', 20, 17, 23, 'A wicked man takes a covert bribe to subvert the course of justice.'),
  ('BSB', 'Proverbs', 20, 17, 24, 'Wisdom is the focus of the discerning, but the eyes of a fool wander to the ends of the earth.'),
  ('BSB', 'Proverbs', 20, 17, 25, 'A foolish son brings grief to his father and bitterness to her who bore him.'),
  ('BSB', 'Proverbs', 20, 17, 26, 'It is surely not good to punish the innocent or to flog a noble for his honesty.'),
  ('BSB', 'Proverbs', 20, 17, 27, 'A man of knowledge restrains his words, and a man of understanding maintains a calm spirit.'),
  ('BSB', 'Proverbs', 20, 17, 28, 'Even a fool is considered wise if he keeps silent, and discerning when he holds his tongue.'),
  ('BSB', 'Proverbs', 20, 18, 1, 'He who isolates himself pursues selfish desires; he rebels against all sound judgment.'),
  ('BSB', 'Proverbs', 20, 18, 2, 'A fool does not delight in understanding, but only in airing his opinions.'),
  ('BSB', 'Proverbs', 20, 18, 3, 'With a wicked man comes contempt as well, and shame is accompanied by disgrace.'),
  ('BSB', 'Proverbs', 20, 18, 4, 'The words of a man’s mouth are deep waters; the fountain of wisdom is a bubbling brook.'),
  ('BSB', 'Proverbs', 20, 18, 5, 'Showing partiality to the wicked is not good, nor is depriving the innocent of justice.'),
  ('BSB', 'Proverbs', 20, 18, 6, 'A fool’s lips bring him strife, and his mouth invites a beating.'),
  ('BSB', 'Proverbs', 20, 18, 7, 'A fool’s mouth is his ruin, and his lips are a snare to his soul.'),
  ('BSB', 'Proverbs', 20, 18, 8, 'The words of a gossip are like choice morsels that go down into the inmost being.'),
  ('BSB', 'Proverbs', 20, 18, 9, 'Whoever is slothful in his work is brother to him who destroys.'),
  ('BSB', 'Proverbs', 20, 18, 10, 'The name of the LORD is a strong tower; the righteous run to it and are safe.'),
  ('BSB', 'Proverbs', 20, 18, 11, 'A rich man’s wealth is his fortified city; it is like a high wall in his imagination.'),
  ('BSB', 'Proverbs', 20, 18, 12, 'Before his downfall a man’s heart is proud, but humility comes before honor.'),
  ('BSB', 'Proverbs', 20, 18, 13, 'He who answers a matter before he hears it— this is folly and disgrace to him.'),
  ('BSB', 'Proverbs', 20, 18, 14, 'The spirit of a man can endure his sickness, but who can survive a broken spirit?'),
  ('BSB', 'Proverbs', 20, 18, 15, 'The heart of the discerning acquires knowledge, and the ear of the wise seeks it out.'),
  ('BSB', 'Proverbs', 20, 18, 16, 'A man’s gift opens doors for him, and brings him before great men.'),
  ('BSB', 'Proverbs', 20, 18, 17, 'The first to state his case seems right until another comes and cross-examines him.'),
  ('BSB', 'Proverbs', 20, 18, 18, 'Casting the lot ends quarrels and separates strong opponents.'),
  ('BSB', 'Proverbs', 20, 18, 19, 'An offended brother is harder to win than a fortified city, and disputes are like the bars of a castle.'),
  ('BSB', 'Proverbs', 20, 18, 20, 'From the fruit of his mouth a man’s belly is filled; with the harvest from his lips he is satisfied.'),
  ('BSB', 'Proverbs', 20, 18, 21, 'Life and death are in the power of the tongue, and those who love it will eat its fruit.'),
  ('BSB', 'Proverbs', 20, 18, 22, 'He who finds a wife finds a good thing and obtains favor from the LORD.'),
  ('BSB', 'Proverbs', 20, 18, 23, 'The poor man pleads for mercy, but the rich man answers harshly.'),
  ('BSB', 'Proverbs', 20, 18, 24, 'A man of many companions may come to ruin, but there is a friend who stays closer than a brother.'),
  ('BSB', 'Proverbs', 20, 19, 1, 'Better a poor man who walks with integrity than a fool whose lips are perverse.'),
  ('BSB', 'Proverbs', 20, 19, 2, 'Even zeal is no good without knowledge, and he who hurries his footsteps misses the mark.'),
  ('BSB', 'Proverbs', 20, 19, 3, 'A man’s own folly subverts his way, yet his heart rages against the LORD.'),
  ('BSB', 'Proverbs', 20, 19, 4, 'Wealth attracts many friends, but a poor man is deserted by his friend.'),
  ('BSB', 'Proverbs', 20, 19, 5, 'A false witness will not go unpunished, and one who utters lies will not escape.'),
  ('BSB', 'Proverbs', 20, 19, 6, 'Many seek the favor of the prince, and everyone is a friend of the gift giver.'),
  ('BSB', 'Proverbs', 20, 19, 7, 'All the brothers of a poor man hate him— how much more do his friends avoid him! He may pursue them with pleading, but they are nowhere to be found.'),
  ('BSB', 'Proverbs', 20, 19, 8, 'He who acquires wisdom loves himself; one who safeguards understanding will find success.'),
  ('BSB', 'Proverbs', 20, 19, 9, 'A false witness will not go unpunished, and one who pours out lies will perish.'),
  ('BSB', 'Proverbs', 20, 19, 10, 'Luxury is unseemly for a fool— how much worse for a slave to rule over princes!'),
  ('BSB', 'Proverbs', 20, 19, 11, 'A man’s insight gives him patience, and his virtue is to overlook an offense.'),
  ('BSB', 'Proverbs', 20, 19, 12, 'A king’s rage is like the roar of a lion, but his favor is like dew on the grass.'),
  ('BSB', 'Proverbs', 20, 19, 13, 'A foolish son is his father’s ruin, and a quarrelsome wife is like a constant dripping.'),
  ('BSB', 'Proverbs', 20, 19, 14, 'Houses and wealth are inherited from fathers, but a prudent wife is from the LORD.'),
  ('BSB', 'Proverbs', 20, 19, 15, 'Laziness brings on deep sleep, and an idle soul will suffer hunger.'),
  ('BSB', 'Proverbs', 20, 19, 16, 'He who keeps a commandment preserves his soul, but he who is careless in his ways will die.'),
  ('BSB', 'Proverbs', 20, 19, 17, 'Kindness to the poor is a loan to the LORD, and He will repay the lender.'),
  ('BSB', 'Proverbs', 20, 19, 18, 'Discipline your son, for in that there is hope; do not be party to his death.'),
  ('BSB', 'Proverbs', 20, 19, 19, 'A man of great anger must pay the penalty; if you rescue him, you will have to do so again.'),
  ('BSB', 'Proverbs', 20, 19, 20, 'Listen to counsel and accept discipline, that you may be wise the rest of your days.'),
  ('BSB', 'Proverbs', 20, 19, 21, 'Many plans are in a man’s heart, but the purpose of the LORD will prevail.'),
  ('BSB', 'Proverbs', 20, 19, 22, 'The desire of a man is loving devotion; better to be poor than a liar.'),
  ('BSB', 'Proverbs', 20, 19, 23, 'The fear of the LORD leads to life, that one may rest content, without visitation from harm.'),
  ('BSB', 'Proverbs', 20, 19, 24, 'The slacker buries his hand in the dish; he will not even bring it back to his mouth.'),
  ('BSB', 'Proverbs', 20, 19, 25, 'Strike a mocker, and the simple will beware; rebuke the discerning man, and he will gain knowledge.'),
  ('BSB', 'Proverbs', 20, 19, 26, 'He who assaults his father or evicts his mother is a son who brings shame and disgrace.'),
  ('BSB', 'Proverbs', 20, 19, 27, 'If you cease to hear instruction, my son, you will stray from the words of knowledge.'),
  ('BSB', 'Proverbs', 20, 19, 28, 'A corrupt witness mocks justice, and a wicked mouth swallows iniquity.'),
  ('BSB', 'Proverbs', 20, 19, 29, 'Judgments are prepared for mockers, and beatings for the backs of fools.'),
  ('BSB', 'Proverbs', 20, 20, 1, 'Wine is a mocker, strong drink is a brawler, and whoever is led astray by them is not wise.'),
  ('BSB', 'Proverbs', 20, 20, 2, 'The terror of a king is like the roar of a lion; whoever provokes him forfeits his own life.'),
  ('BSB', 'Proverbs', 20, 20, 3, 'It is honorable for a man to resolve a dispute, but any fool will quarrel.'),
  ('BSB', 'Proverbs', 20, 20, 4, 'The slacker does not plow in season; at harvest time he looks, but nothing is there.'),
  ('BSB', 'Proverbs', 20, 20, 5, 'The intentions of a man’s heart are deep waters, but a man of understanding draws them out.'),
  ('BSB', 'Proverbs', 20, 20, 6, 'Many a man proclaims his loving devotion, but who can find a trustworthy man?'),
  ('BSB', 'Proverbs', 20, 20, 7, 'The righteous man walks with integrity; blessed are his children after him.'),
  ('BSB', 'Proverbs', 20, 20, 8, 'A king who sits on a throne to judge sifts out all evil with his eyes.'),
  ('BSB', 'Proverbs', 20, 20, 9, 'Who can say, “I have kept my heart pure; I am cleansed from my sin”?'),
  ('BSB', 'Proverbs', 20, 20, 10, 'Differing weights and unequal measures— both are detestable to the LORD.'),
  ('BSB', 'Proverbs', 20, 20, 11, 'Even a young man is known by his actions— whether his conduct is pure and upright.'),
  ('BSB', 'Proverbs', 20, 20, 12, 'Ears that hear and eyes that see— the LORD has made them both.'),
  ('BSB', 'Proverbs', 20, 20, 13, 'Do not love sleep, or you will grow poor; open your eyes, and you will have plenty of food.'),
  ('BSB', 'Proverbs', 20, 20, 14, '“Worthless, worthless!” says the buyer, but on the way out, he gloats.'),
  ('BSB', 'Proverbs', 20, 20, 15, 'There is an abundance of gold and rubies, but lips of knowledge are a rare treasure.'),
  ('BSB', 'Proverbs', 20, 20, 16, 'Take the garment of the one who posts security for a stranger; get collateral if it is for a foreigner.'),
  ('BSB', 'Proverbs', 20, 20, 17, 'Food gained by fraud is sweet to a man, but later his mouth is full of gravel.'),
  ('BSB', 'Proverbs', 20, 20, 18, 'Set plans by consultation, and wage war under sound guidance.'),
  ('BSB', 'Proverbs', 20, 20, 19, 'He who reveals secrets is a constant gossip; avoid the one who babbles with his lips.'),
  ('BSB', 'Proverbs', 20, 20, 20, 'Whoever curses his father or mother, his lamp will be extinguished in deepest darkness.'),
  ('BSB', 'Proverbs', 20, 20, 21, 'An inheritance gained quickly will not be blessed in the end.'),
  ('BSB', 'Proverbs', 20, 20, 22, 'Do not say, “I will avenge this evil!” Wait on the LORD, and He will save you.'),
  ('BSB', 'Proverbs', 20, 20, 23, 'Unequal weights are detestable to the LORD, and dishonest scales are no good.'),
  ('BSB', 'Proverbs', 20, 20, 24, 'A man’s steps are from the LORD, so how can anyone understand his own way?'),
  ('BSB', 'Proverbs', 20, 20, 25, 'It is a trap for a man to dedicate something rashly, only later to reconsider his vows.'),
  ('BSB', 'Proverbs', 20, 20, 26, 'A wise king separates out the wicked and drives the threshing wheel over them.'),
  ('BSB', 'Proverbs', 20, 20, 27, 'The spirit of a man is the lamp of the LORD, searching out his inmost being.'),
  ('BSB', 'Proverbs', 20, 20, 28, 'Loving devotion and faithfulness preserve a king; by these he maintains his throne.'),
  ('BSB', 'Proverbs', 20, 20, 29, 'The glory of young men is their strength, and gray hair is the splendor of the old.'),
  ('BSB', 'Proverbs', 20, 20, 30, 'Lashes and wounds scour evil, and beatings cleanse the inmost parts.'),
  ('BSB', 'Proverbs', 20, 21, 1, 'The king’s heart is a waterway in the hand of the LORD; He directs it where He pleases.'),
  ('BSB', 'Proverbs', 20, 21, 2, 'All a man’s ways seem right to him, but the LORD weighs the heart.'),
  ('BSB', 'Proverbs', 20, 21, 3, 'To do righteousness and justice is more desirable to the LORD than sacrifice.'),
  ('BSB', 'Proverbs', 20, 21, 4, 'Haughty eyes and a proud heart— the guides of the wicked—are sin.'),
  ('BSB', 'Proverbs', 20, 21, 5, 'The plans of the diligent bring plenty, as surely as haste leads to poverty.'),
  ('BSB', 'Proverbs', 20, 21, 6, 'Making a fortune by a lying tongue is a vanishing mist, a deadly pursuit.'),
  ('BSB', 'Proverbs', 20, 21, 7, 'The violence of the wicked will sweep them away because they refuse to do what is just.'),
  ('BSB', 'Proverbs', 20, 21, 8, 'The way of a guilty man is crooked, but the conduct of the innocent is upright.'),
  ('BSB', 'Proverbs', 20, 21, 9, 'Better to live on a corner of the roof than to share a house with a quarrelsome wife.'),
  ('BSB', 'Proverbs', 20, 21, 10, 'The soul of the wicked man craves evil; his neighbor finds no favor in his eyes.'),
  ('BSB', 'Proverbs', 20, 21, 11, 'When a mocker is punished, the simple gain wisdom; and when a wise man is instructed, he acquires knowledge.'),
  ('BSB', 'Proverbs', 20, 21, 12, 'The Righteous One considers the house of the wicked and brings the wicked to ruin.'),
  ('BSB', 'Proverbs', 20, 21, 13, 'Whoever shuts his ears to the cry of the poor, he too shall cry out and receive no answer.'),
  ('BSB', 'Proverbs', 20, 21, 14, 'A gift in secret soothes anger, and a covert bribe pacifies great wrath.'),
  ('BSB', 'Proverbs', 20, 21, 15, 'Justice executed is a joy to the righteous, but a terror to the workers of iniquity.'),
  ('BSB', 'Proverbs', 20, 21, 16, 'The man who strays from the path of understanding will rest in the assembly of the dead.'),
  ('BSB', 'Proverbs', 20, 21, 17, 'He who loves pleasure will become poor; the one who loves wine and oil will never be rich.'),
  ('BSB', 'Proverbs', 20, 21, 18, 'The wicked become a ransom for the righteous, and the faithless for the upright.'),
  ('BSB', 'Proverbs', 20, 21, 19, 'Better to live in the desert than with a contentious and ill-tempered wife.'),
  ('BSB', 'Proverbs', 20, 21, 20, 'Precious treasures and oil are in the dwelling of the wise, but a foolish man consumes them.'),
  ('BSB', 'Proverbs', 20, 21, 21, 'He who pursues righteousness and loving devotion finds life, righteousness, and honor.'),
  ('BSB', 'Proverbs', 20, 21, 22, 'A wise man scales the city of the mighty and pulls down the stronghold in which they trust.'),
  ('BSB', 'Proverbs', 20, 21, 23, 'He who guards his mouth and tongue keeps his soul from distress.'),
  ('BSB', 'Proverbs', 20, 21, 24, 'Mocker is the name of the proud and arrogant man— of him who acts with excessive pride.'),
  ('BSB', 'Proverbs', 20, 21, 25, 'The craving of the slacker kills him because his hands refuse to work.'),
  ('BSB', 'Proverbs', 20, 21, 26, 'All day long he covets more, but the righteous give without restraint.'),
  ('BSB', 'Proverbs', 20, 21, 27, 'The sacrifice of the wicked is detestable— how much more so when brought with ill intent!'),
  ('BSB', 'Proverbs', 20, 21, 28, 'A lying witness will perish, but the man who listens to truth will speak forever.'),
  ('BSB', 'Proverbs', 20, 21, 29, 'A wicked man hardens his face, but the upright man makes his way sure.'),
  ('BSB', 'Proverbs', 20, 21, 30, 'There is no wisdom, no understanding, no counsel that can prevail against the LORD.'),
  ('BSB', 'Proverbs', 20, 21, 31, 'A horse is prepared for the day of battle, but victory is of the LORD.'),
  ('BSB', 'Proverbs', 20, 22, 1, 'A good name is more desirable than great riches; favor is better than silver and gold.'),
  ('BSB', 'Proverbs', 20, 22, 2, 'The rich and the poor have this in common: The LORD is Maker of them all.'),
  ('BSB', 'Proverbs', 20, 22, 3, 'The prudent see danger and take cover, but the simple keep going and suffer the consequences.'),
  ('BSB', 'Proverbs', 20, 22, 4, 'The rewards of humility and the fear of the LORD are wealth and honor and life.'),
  ('BSB', 'Proverbs', 20, 22, 5, 'Thorns and snares lie on the path of the perverse; he who guards his soul stays far from them.'),
  ('BSB', 'Proverbs', 20, 22, 6, 'Train up a child in the way he should go, and when he is old he will not depart from it.'),
  ('BSB', 'Proverbs', 20, 22, 7, 'The rich rule over the poor, and the borrower is slave to the lender.'),
  ('BSB', 'Proverbs', 20, 22, 8, 'He who sows injustice will reap disaster, and the rod of his fury will be destroyed.'),
  ('BSB', 'Proverbs', 20, 22, 9, 'A generous man will be blessed, for he shares his bread with the poor.'),
  ('BSB', 'Proverbs', 20, 22, 10, 'Drive out the mocker, and conflict will depart; even quarreling and insults will cease.'),
  ('BSB', 'Proverbs', 20, 22, 11, 'He who loves a pure heart and gracious lips will have the king for a friend.'),
  ('BSB', 'Proverbs', 20, 22, 12, 'The LORD’s eyes keep watch over knowledge, but He frustrates the words of the faithless.'),
  ('BSB', 'Proverbs', 20, 22, 13, 'The slacker says, “There is a lion outside! I will be slain in the streets!”'),
  ('BSB', 'Proverbs', 20, 22, 14, 'The mouth of an adulteress is a deep pit; he who is under the wrath of the LORD will fall into it.'),
  ('BSB', 'Proverbs', 20, 22, 15, 'Foolishness is bound up in the heart of a child, but the rod of discipline drives it far from him.'),
  ('BSB', 'Proverbs', 20, 22, 16, 'Oppressing the poor to enrich oneself or giving gifts to the rich will surely lead to poverty.'),
  ('BSB', 'Proverbs', 20, 22, 17, 'Incline your ear and hear the words of the wise— apply your mind to my knowledge—'),
  ('BSB', 'Proverbs', 20, 22, 18, 'for it is pleasing when you keep them within you and they are constantly on your lips.'),
  ('BSB', 'Proverbs', 20, 22, 19, 'So that your trust may be in the LORD, I instruct you today—yes, you.'),
  ('BSB', 'Proverbs', 20, 22, 20, 'Have I not written for you thirty sayings about counsel and knowledge,'),
  ('BSB', 'Proverbs', 20, 22, 21, 'to show you true and reliable words, that you may soundly answer those who sent you?'),
  ('BSB', 'Proverbs', 20, 22, 22, 'Do not rob a poor man because he is poor, and do not crush the afflicted at the gate,'),
  ('BSB', 'Proverbs', 20, 22, 23, 'for the LORD will take up their case and will plunder those who rob them.'),
  ('BSB', 'Proverbs', 20, 22, 24, 'Do not make friends with an angry man, and do not associate with a hot-tempered man,'),
  ('BSB', 'Proverbs', 20, 22, 25, 'or you may learn his ways and entangle yourself in a snare.'),
  ('BSB', 'Proverbs', 20, 22, 26, 'Do not be one who gives pledges, who puts up security for debts.'),
  ('BSB', 'Proverbs', 20, 22, 27, 'If you have nothing with which to pay, why should your bed be taken from under you?'),
  ('BSB', 'Proverbs', 20, 22, 28, 'Do not move an ancient boundary stone which your fathers have placed.'),
  ('BSB', 'Proverbs', 20, 22, 29, 'Do you see a man skilled in his work? He will be stationed in the presence of kings; he will not stand before obscure men.'),
  ('BSB', 'Proverbs', 20, 23, 1, 'When you sit down to dine with a ruler, consider carefully what is set before you,'),
  ('BSB', 'Proverbs', 20, 23, 2, 'and put a knife to your throat if you possess a great appetite.'),
  ('BSB', 'Proverbs', 20, 23, 3, 'Do not crave his delicacies, for that food is deceptive.'),
  ('BSB', 'Proverbs', 20, 23, 4, 'Do not wear yourself out to get rich; be wise enough to restrain yourself.'),
  ('BSB', 'Proverbs', 20, 23, 5, 'When you glance at wealth, it disappears, for it makes wings for itself and flies like an eagle to the sky.'),
  ('BSB', 'Proverbs', 20, 23, 6, 'Do not eat the bread of a stingy man, and do not crave his delicacies;'),
  ('BSB', 'Proverbs', 20, 23, 7, 'for he is keeping track, inwardly counting the cost. “Eat and drink,” he says to you, but his heart is not with you.'),
  ('BSB', 'Proverbs', 20, 23, 8, 'You will vomit up what little you have eaten and waste your pleasant words.'),
  ('BSB', 'Proverbs', 20, 23, 9, 'Do not speak to a fool, for he will despise the wisdom of your words.'),
  ('BSB', 'Proverbs', 20, 23, 10, 'Do not move an ancient boundary stone or encroach on the fields of the fatherless,'),
  ('BSB', 'Proverbs', 20, 23, 11, 'for their Redeemer is strong; He will take up their case against you.'),
  ('BSB', 'Proverbs', 20, 23, 12, 'Apply your heart to instruction and your ears to words of knowledge.'),
  ('BSB', 'Proverbs', 20, 23, 13, 'Do not withhold discipline from a child; although you strike him with a rod, he will not die.'),
  ('BSB', 'Proverbs', 20, 23, 14, 'Strike him with a rod, and you will deliver his soul from Sheol.'),
  ('BSB', 'Proverbs', 20, 23, 15, 'My son, if your heart is wise, my own heart will indeed rejoice.'),
  ('BSB', 'Proverbs', 20, 23, 16, 'My inmost being will rejoice when your lips speak what is right.'),
  ('BSB', 'Proverbs', 20, 23, 17, 'Do not let your heart envy sinners, but always continue in the fear of the LORD.'),
  ('BSB', 'Proverbs', 20, 23, 18, 'For surely there is a future, and your hope will not be cut off.'),
  ('BSB', 'Proverbs', 20, 23, 19, 'Listen, my son, and be wise, and guide your heart on the right course.'),
  ('BSB', 'Proverbs', 20, 23, 20, 'Do not join those who drink too much wine or gorge themselves on meat.'),
  ('BSB', 'Proverbs', 20, 23, 21, 'For the drunkard and the glutton will come to poverty, and drowsiness will clothe them in rags.'),
  ('BSB', 'Proverbs', 20, 23, 22, 'Listen to your father who gave you life, and do not despise your mother when she is old.'),
  ('BSB', 'Proverbs', 20, 23, 23, 'Invest in truth and never sell it— in wisdom and instruction and understanding.'),
  ('BSB', 'Proverbs', 20, 23, 24, 'The father of a righteous man will greatly rejoice, and he who fathers a wise son will delight in him.'),
  ('BSB', 'Proverbs', 20, 23, 25, 'May your father and mother be glad, and may she who gave you birth rejoice!'),
  ('BSB', 'Proverbs', 20, 23, 26, 'My son, give me your heart, and let your eyes delight in my ways.'),
  ('BSB', 'Proverbs', 20, 23, 27, 'For a prostitute is a deep pit, and an adulteress is a narrow well.'),
  ('BSB', 'Proverbs', 20, 23, 28, 'Like a robber she lies in wait and multiplies the faithless among men.'),
  ('BSB', 'Proverbs', 20, 23, 29, 'Who has woe? Who has sorrow? Who has contentions? Who has complaints? Who has needless wounds? Who has bloodshot eyes?'),
  ('BSB', 'Proverbs', 20, 23, 30, 'Those who linger over wine, who go to taste mixed drinks.'),
  ('BSB', 'Proverbs', 20, 23, 31, 'Do not gaze at wine while it is red, when it sparkles in the cup and goes down smoothly.'),
  ('BSB', 'Proverbs', 20, 23, 32, 'In the end it bites like a snake and stings like a viper.'),
  ('BSB', 'Proverbs', 20, 23, 33, 'Your eyes will see strange things, and your mind will utter perversities.'),
  ('BSB', 'Proverbs', 20, 23, 34, 'You will be like one sleeping on the high seas or lying on the top of a mast:'),
  ('BSB', 'Proverbs', 20, 23, 35, '“They struck me, but I feel no pain! They beat me, but I did not know it! When can I wake up to search for another drink?”'),
  ('BSB', 'Proverbs', 20, 24, 1, 'Do not envy wicked men or desire their company;'),
  ('BSB', 'Proverbs', 20, 24, 2, 'for their hearts devise violence, and their lips declare trouble.'),
  ('BSB', 'Proverbs', 20, 24, 3, 'By wisdom a house is built and by understanding it is established;'),
  ('BSB', 'Proverbs', 20, 24, 4, 'through knowledge its rooms are filled with every precious and beautiful treasure.'),
  ('BSB', 'Proverbs', 20, 24, 5, 'A wise man is strong, and a man of knowledge enhances his strength.'),
  ('BSB', 'Proverbs', 20, 24, 6, 'Only with sound guidance should you wage war, and victory lies in a multitude of counselors.'),
  ('BSB', 'Proverbs', 20, 24, 7, 'Wisdom is too high for a fool; he does not open his mouth in the meeting place.'),
  ('BSB', 'Proverbs', 20, 24, 8, 'He who plots evil will be called a schemer.'),
  ('BSB', 'Proverbs', 20, 24, 9, 'A foolish scheme is sin, and a mocker is detestable to men.'),
  ('BSB', 'Proverbs', 20, 24, 10, 'If you faint in the day of distress, how small is your strength!'),
  ('BSB', 'Proverbs', 20, 24, 11, 'Rescue those being led away to death, and restrain those stumbling toward the slaughter.'),
  ('BSB', 'Proverbs', 20, 24, 12, 'If you say, “Behold, we did not know about this,” does not He who weighs hearts consider it? Does not the One who guards your life know? Will He not repay a man according to his deeds?'),
  ('BSB', 'Proverbs', 20, 24, 13, 'Eat honey, my son, for it is good, and the honeycomb is sweet to your taste.'),
  ('BSB', 'Proverbs', 20, 24, 14, 'Know therefore that wisdom is sweet to your soul. If you find it, there is a future for you, and your hope will never be cut off.'),
  ('BSB', 'Proverbs', 20, 24, 15, 'Do not lie in wait, O wicked man, near the dwelling of the righteous; do not destroy his resting place.'),
  ('BSB', 'Proverbs', 20, 24, 16, 'For though a righteous man may fall seven times, he still gets up; but the wicked stumble in bad times.'),
  ('BSB', 'Proverbs', 20, 24, 17, 'Do not gloat when your enemy falls, and do not let your heart rejoice when he stumbles,'),
  ('BSB', 'Proverbs', 20, 24, 18, 'or the LORD will see and disapprove, and turn His wrath away from him.'),
  ('BSB', 'Proverbs', 20, 24, 19, 'Do not fret over evildoers, and do not be envious of the wicked.'),
  ('BSB', 'Proverbs', 20, 24, 20, 'For the evil man has no future; the lamp of the wicked will be extinguished.'),
  ('BSB', 'Proverbs', 20, 24, 21, 'My son, fear the LORD and the king, and do not associate with the rebellious.'),
  ('BSB', 'Proverbs', 20, 24, 22, 'For they will bring sudden destruction. Who knows what ruin they can bring?'),
  ('BSB', 'Proverbs', 20, 24, 23, 'These also are sayings of the wise: To show partiality in judgment is not good.'),
  ('BSB', 'Proverbs', 20, 24, 24, 'Whoever tells the guilty, “You are innocent”— peoples will curse him, and nations will denounce him;'),
  ('BSB', 'Proverbs', 20, 24, 25, 'but it will go well with those who convict the guilty, and rich blessing will come upon them.'),
  ('BSB', 'Proverbs', 20, 24, 26, 'An honest answer given is like a kiss on the lips.'),
  ('BSB', 'Proverbs', 20, 24, 27, 'Complete your outdoor work and prepare your field; after that, you may build your house.'),
  ('BSB', 'Proverbs', 20, 24, 28, 'Do not testify against your neighbor without cause, and do not deceive with your lips.'),
  ('BSB', 'Proverbs', 20, 24, 29, 'Do not say, “I will do to him as he has done to me; I will repay the man according to his work.”'),
  ('BSB', 'Proverbs', 20, 24, 30, 'I went past the field of a slacker and by the vineyard of a man lacking judgment.'),
  ('BSB', 'Proverbs', 20, 24, 31, 'Thorns had grown up everywhere, thistles had covered the ground, and the stone wall was broken down.'),
  ('BSB', 'Proverbs', 20, 24, 32, 'I observed and took it to heart; I looked and received instruction:'),
  ('BSB', 'Proverbs', 20, 24, 33, 'A little sleep, a little slumber, a little folding of the hands to rest,'),
  ('BSB', 'Proverbs', 20, 24, 34, 'and poverty will come upon you like a robber, and need like a bandit.'),
  ('BSB', 'Proverbs', 20, 25, 1, 'These are additional proverbs of Solomon, which were copied by the men of Hezekiah king of Judah:'),
  ('BSB', 'Proverbs', 20, 25, 2, 'It is the glory of God to conceal a matter and the glory of kings to search it out.'),
  ('BSB', 'Proverbs', 20, 25, 3, 'As the heavens are high and the earth is deep, so the hearts of kings cannot be searched.'),
  ('BSB', 'Proverbs', 20, 25, 4, 'Remove the dross from the silver, and a vessel for a silversmith will come forth.'),
  ('BSB', 'Proverbs', 20, 25, 5, 'Remove the wicked from the king’s presence, and his throne will be established in righteousness.'),
  ('BSB', 'Proverbs', 20, 25, 6, 'Do not exalt yourself in the presence of the king, and do not stand in the place of great men;'),
  ('BSB', 'Proverbs', 20, 25, 7, 'for it is better that he says to you, “Come up here!” than that you should be demoted in the presence of the prince. Even what you have seen with your own eyes,'),
  ('BSB', 'Proverbs', 20, 25, 8, 'do not bring hastily to court. Otherwise, what will you do in the end when your neighbor puts you to shame?'),
  ('BSB', 'Proverbs', 20, 25, 9, 'Argue your case with your neighbor without betraying another’s confidence,'),
  ('BSB', 'Proverbs', 20, 25, 10, 'lest the one who hears may disgrace you, and your infamy never go away.'),
  ('BSB', 'Proverbs', 20, 25, 11, 'A word fitly spoken is like apples of gold in settings of silver.'),
  ('BSB', 'Proverbs', 20, 25, 12, 'Like an earring of gold or an ornament of fine gold is a wise man’s rebuke to a listening ear.'),
  ('BSB', 'Proverbs', 20, 25, 13, 'Like the cold of snow in the time of harvest is a trustworthy messenger to those who send him; he refreshes the soul of his masters.'),
  ('BSB', 'Proverbs', 20, 25, 14, 'Like clouds and wind without rain is the man who boasts of gifts never given.'),
  ('BSB', 'Proverbs', 20, 25, 15, 'Through patience a ruler can be persuaded, and a gentle tongue can break a bone.'),
  ('BSB', 'Proverbs', 20, 25, 16, 'If you find honey, eat just what you need, lest you have too much and vomit it up.'),
  ('BSB', 'Proverbs', 20, 25, 17, 'Seldom set foot in your neighbor’s house, lest he grow weary and hate you.'),
  ('BSB', 'Proverbs', 20, 25, 18, 'Like a club or sword or sharp arrow is a man who bears false witness against his neighbor.'),
  ('BSB', 'Proverbs', 20, 25, 19, 'Like a broken tooth or a foot out of joint is confidence in a faithless man in time of trouble.'),
  ('BSB', 'Proverbs', 20, 25, 20, 'Like one who removes a garment on a cold day or vinegar poured on a wound is one who sings songs to a heavy heart.'),
  ('BSB', 'Proverbs', 20, 25, 21, 'If your enemy is hungry, give him food to eat, and if he is thirsty, give him water to drink.'),
  ('BSB', 'Proverbs', 20, 25, 22, 'For in so doing, you will heap burning coals on his head, and the LORD will reward you.'),
  ('BSB', 'Proverbs', 20, 25, 23, 'As the north wind brings forth rain, so a backbiting tongue brings angry looks.'),
  ('BSB', 'Proverbs', 20, 25, 24, 'Better to live on a corner of the roof than to share a house with a quarrelsome wife.'),
  ('BSB', 'Proverbs', 20, 25, 25, 'Like cold water to a weary soul is good news from a distant land.'),
  ('BSB', 'Proverbs', 20, 25, 26, 'Like a muddied spring or a polluted well is a righteous man who gives way to the wicked.'),
  ('BSB', 'Proverbs', 20, 25, 27, 'It is not good to eat too much honey or to search out one’s own glory.'),
  ('BSB', 'Proverbs', 20, 25, 28, 'Like a city whose walls are broken down is a man who does not control his temper.'),
  ('BSB', 'Proverbs', 20, 26, 1, 'Like snow in summer and rain at harvest, honor does not befit a fool.'),
  ('BSB', 'Proverbs', 20, 26, 2, 'Like a fluttering sparrow or darting swallow, an undeserved curse does not come to rest.'),
  ('BSB', 'Proverbs', 20, 26, 3, 'A whip for the horse, a bridle for the donkey, and a rod for the backs of fools!'),
  ('BSB', 'Proverbs', 20, 26, 4, 'Do not answer a fool according to his folly, or you yourself will be like him.'),
  ('BSB', 'Proverbs', 20, 26, 5, 'Answer a fool according to his folly, lest he become wise in his own eyes.'),
  ('BSB', 'Proverbs', 20, 26, 6, 'Like cutting off one’s own feet or drinking violence is the sending of a message by the hand of a fool.'),
  ('BSB', 'Proverbs', 20, 26, 7, 'Like lame legs hanging limp is a proverb in the mouth of a fool.'),
  ('BSB', 'Proverbs', 20, 26, 8, 'Like binding a stone into a sling is the giving of honor to a fool.'),
  ('BSB', 'Proverbs', 20, 26, 9, 'Like a thorn that falls into the hand of a drunkard is a proverb in the mouth of a fool.'),
  ('BSB', 'Proverbs', 20, 26, 10, 'Like an archer who wounds at random is he who hires a fool or passerby.'),
  ('BSB', 'Proverbs', 20, 26, 11, 'As a dog returns to its vomit, so a fool repeats his folly.'),
  ('BSB', 'Proverbs', 20, 26, 12, 'Do you see a man who is wise in his own eyes? There is more hope for a fool than for him.'),
  ('BSB', 'Proverbs', 20, 26, 13, 'The slacker says, “A lion is in the road! A fierce lion roams the public square!”'),
  ('BSB', 'Proverbs', 20, 26, 14, 'As a door turns on its hinges, so the slacker turns on his bed.'),
  ('BSB', 'Proverbs', 20, 26, 15, 'The slacker buries his hand in the dish; it wearies him to bring it back to his mouth.'),
  ('BSB', 'Proverbs', 20, 26, 16, 'The slacker is wiser in his own eyes than seven men who answer discreetly.'),
  ('BSB', 'Proverbs', 20, 26, 17, 'Like one who grabs a dog by the ears is a passerby who meddles in a quarrel not his own.'),
  ('BSB', 'Proverbs', 20, 26, 18, 'Like a madman shooting firebrands and deadly arrows,'),
  ('BSB', 'Proverbs', 20, 26, 19, 'so is the man who deceives his neighbor and says, “I was only joking!”'),
  ('BSB', 'Proverbs', 20, 26, 20, 'Without wood, a fire goes out; without gossip, a conflict ceases.'),
  ('BSB', 'Proverbs', 20, 26, 21, 'Like charcoal for embers and wood for fire, so is a quarrelsome man for kindling strife.'),
  ('BSB', 'Proverbs', 20, 26, 22, 'The words of a gossip are like choice morsels that go down into the inmost being.'),
  ('BSB', 'Proverbs', 20, 26, 23, 'Like glaze covering an earthen vessel are burning lips and a wicked heart.'),
  ('BSB', 'Proverbs', 20, 26, 24, 'A hateful man disguises himself with his speech, but he lays up deceit in his heart.'),
  ('BSB', 'Proverbs', 20, 26, 25, 'When he speaks graciously, do not believe him, for seven abominations fill his heart.'),
  ('BSB', 'Proverbs', 20, 26, 26, 'Though his hatred is concealed by deception, his wickedness will be exposed in the assembly.'),
  ('BSB', 'Proverbs', 20, 26, 27, 'He who digs a pit will fall into it, and he who rolls a stone will have it roll back on him.'),
  ('BSB', 'Proverbs', 20, 26, 28, 'A lying tongue hates those it crushes, and a flattering mouth causes ruin.'),
  ('BSB', 'Proverbs', 20, 27, 1, 'Do not boast about tomorrow, for you do not know what a day may bring.'),
  ('BSB', 'Proverbs', 20, 27, 2, 'Let another praise you, and not your own mouth— a stranger, and not your own lips.'),
  ('BSB', 'Proverbs', 20, 27, 3, 'A stone is heavy and sand is a burden, but aggravation from a fool outweighs them both.'),
  ('BSB', 'Proverbs', 20, 27, 4, 'Wrath is cruel and anger is like a flood, but who can withstand jealousy?'),
  ('BSB', 'Proverbs', 20, 27, 5, 'Better an open rebuke than love that is concealed.'),
  ('BSB', 'Proverbs', 20, 27, 6, 'The wounds of a friend are faithful, but the kisses of an enemy are deceitful.'),
  ('BSB', 'Proverbs', 20, 27, 7, 'The soul that is full loathes honey, but to a hungry soul, any bitter thing is sweet.'),
  ('BSB', 'Proverbs', 20, 27, 8, 'Like a bird that strays from its nest is a man who wanders from his home.'),
  ('BSB', 'Proverbs', 20, 27, 9, 'Oil and incense bring joy to the heart, and the sweetness of a friend is counsel to the soul.'),
  ('BSB', 'Proverbs', 20, 27, 10, 'Do not forsake your friend or your father’s friend, and do not go to your brother’s house in the day of your calamity; better a neighbor nearby than a brother far away.'),
  ('BSB', 'Proverbs', 20, 27, 11, 'Be wise, my son, and bring joy to my heart, so that I can answer him who taunts me.'),
  ('BSB', 'Proverbs', 20, 27, 12, 'The prudent see danger and take cover; but the simple keep going and pay the penalty.'),
  ('BSB', 'Proverbs', 20, 27, 13, 'Take the garment of him who posts security for a stranger; get collateral if it is for a foreigner.'),
  ('BSB', 'Proverbs', 20, 27, 14, 'If one blesses his neighbor with a loud voice early in the morning, it will be counted to him as a curse.'),
  ('BSB', 'Proverbs', 20, 27, 15, 'A constant dripping on a rainy day and a contentious woman are alike—'),
  ('BSB', 'Proverbs', 20, 27, 16, 'restraining her is like holding back the wind or grasping oil with one’s right hand.'),
  ('BSB', 'Proverbs', 20, 27, 17, 'As iron sharpens iron, so one man sharpens another.'),
  ('BSB', 'Proverbs', 20, 27, 18, 'Whoever tends a fig tree will eat its fruit, and he who looks after his master will be honored.'),
  ('BSB', 'Proverbs', 20, 27, 19, 'As water reflects the face, so the heart reflects the true man.'),
  ('BSB', 'Proverbs', 20, 27, 20, 'Sheol and Abaddon are never satisfied; so the eyes of man are never satisfied.'),
  ('BSB', 'Proverbs', 20, 27, 21, 'A crucible for silver and a furnace for gold, but a man is tested by the praise accorded him.'),
  ('BSB', 'Proverbs', 20, 27, 22, 'Though you grind a fool like grain with mortar and a pestle, yet his folly will not depart from him.'),
  ('BSB', 'Proverbs', 20, 27, 23, 'Be sure to know the state of your flocks, and pay close attention to your herds;'),
  ('BSB', 'Proverbs', 20, 27, 24, 'for riches are not forever, nor does a crown endure to every generation.'),
  ('BSB', 'Proverbs', 20, 27, 25, 'When hay is removed and new growth appears and the grain from the hills is gathered,'),
  ('BSB', 'Proverbs', 20, 27, 26, 'the lambs will provide you with clothing, and the goats with the price of a field.'),
  ('BSB', 'Proverbs', 20, 27, 27, 'You will have plenty of goats’ milk to feed you— food for your household and nourishment for your maidservants.'),
  ('BSB', 'Proverbs', 20, 28, 1, 'The wicked flee when no one pursues, but the righteous are as bold as a lion.'),
  ('BSB', 'Proverbs', 20, 28, 2, 'A land in rebellion has many rulers, but a man of understanding and knowledge maintains order.'),
  ('BSB', 'Proverbs', 20, 28, 3, 'A destitute leader who oppresses the poor is like a driving rain that leaves no food.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Proverbs', 20, 28, 4, 'Those who forsake the law praise the wicked, but those who keep the law resist them.'),
  ('BSB', 'Proverbs', 20, 28, 5, 'Evil men do not understand justice, but those who seek the LORD comprehend fully.'),
  ('BSB', 'Proverbs', 20, 28, 6, 'Better a poor man who walks with integrity than a rich man whose ways are perverse.'),
  ('BSB', 'Proverbs', 20, 28, 7, 'A discerning son keeps the law, but a companion of gluttons disgraces his father.'),
  ('BSB', 'Proverbs', 20, 28, 8, 'He who increases his wealth by interest and usury lays it up for one who is kind to the poor.'),
  ('BSB', 'Proverbs', 20, 28, 9, 'Whoever turns his ear away from hearing the law, even his prayer is detestable.'),
  ('BSB', 'Proverbs', 20, 28, 10, 'He who leads the upright along the path of evil will fall into his own pit, but the blameless will inherit what is good.'),
  ('BSB', 'Proverbs', 20, 28, 11, 'A rich man is wise in his own eyes, but a poor man with discernment sees through him.'),
  ('BSB', 'Proverbs', 20, 28, 12, 'When the righteous triumph, there is great glory, but when the wicked rise, men hide themselves.'),
  ('BSB', 'Proverbs', 20, 28, 13, 'He who conceals his sins will not prosper, but whoever confesses and renounces them will find mercy.'),
  ('BSB', 'Proverbs', 20, 28, 14, 'Blessed is the man who is always reverent, but he who hardens his heart falls into trouble.'),
  ('BSB', 'Proverbs', 20, 28, 15, 'Like a roaring lion or a charging bear is a wicked ruler over a helpless people.'),
  ('BSB', 'Proverbs', 20, 28, 16, 'A leader who lacks judgment is also a great oppressor, but he who hates dishonest profit will prolong his days.'),
  ('BSB', 'Proverbs', 20, 28, 17, 'A man burdened by bloodguilt will flee into the Pit; let no one support him.'),
  ('BSB', 'Proverbs', 20, 28, 18, 'He who walks with integrity will be kept safe, but whoever is perverse in his ways will suddenly fall.'),
  ('BSB', 'Proverbs', 20, 28, 19, 'The one who works his land will have plenty of food, but whoever chases fantasies will have his fill of poverty.'),
  ('BSB', 'Proverbs', 20, 28, 20, 'A faithful man will abound with blessings, but one eager to be rich will not go unpunished.'),
  ('BSB', 'Proverbs', 20, 28, 21, 'To show partiality is not good, yet a man will do wrong for a piece of bread.'),
  ('BSB', 'Proverbs', 20, 28, 22, 'A stingy man hastens after wealth and does not know that poverty awaits him.'),
  ('BSB', 'Proverbs', 20, 28, 23, 'He who rebukes a man will later find more favor than one who flatters with his tongue.'),
  ('BSB', 'Proverbs', 20, 28, 24, 'He who robs his father or mother, saying, “It is not wrong,” is a companion to the man who destroys.'),
  ('BSB', 'Proverbs', 20, 28, 25, 'A greedy man stirs up strife, but he who trusts in the LORD will prosper.'),
  ('BSB', 'Proverbs', 20, 28, 26, 'He who trusts in himself is a fool, but one who walks in wisdom will be safe.'),
  ('BSB', 'Proverbs', 20, 28, 27, 'Whoever gives to the poor will not be in need, but he who hides his eyes will receive many curses.'),
  ('BSB', 'Proverbs', 20, 28, 28, 'When the wicked come to power, people hide themselves; but when they perish, the righteous flourish.'),
  ('BSB', 'Proverbs', 20, 29, 1, 'A man who remains stiff-necked after much reproof will suddenly be shattered beyond recovery.'),
  ('BSB', 'Proverbs', 20, 29, 2, 'When the righteous flourish, the people rejoice, but when the wicked rule, the people groan.'),
  ('BSB', 'Proverbs', 20, 29, 3, 'A man who loves wisdom brings joy to his father, but a companion of prostitutes squanders his wealth.'),
  ('BSB', 'Proverbs', 20, 29, 4, 'By justice a king brings stability to the land, but a man who exacts tribute demolishes it.'),
  ('BSB', 'Proverbs', 20, 29, 5, 'A man who flatters his neighbor spreads a net for his feet.'),
  ('BSB', 'Proverbs', 20, 29, 6, 'An evil man is caught by his own sin, but a righteous one sings and rejoices.'),
  ('BSB', 'Proverbs', 20, 29, 7, 'The righteous consider the cause of the poor, but the wicked have no regard for such concerns.'),
  ('BSB', 'Proverbs', 20, 29, 8, 'Mockers inflame a city, but the wise turn away anger.'),
  ('BSB', 'Proverbs', 20, 29, 9, 'If a wise man goes to court with a fool, there will be raving and laughing with no resolution.'),
  ('BSB', 'Proverbs', 20, 29, 10, 'Men of bloodshed hate a blameless man, but the upright care for his life.'),
  ('BSB', 'Proverbs', 20, 29, 11, 'A fool vents all his anger, but a wise man holds it back.'),
  ('BSB', 'Proverbs', 20, 29, 12, 'If a ruler listens to lies, all his officials will be wicked.'),
  ('BSB', 'Proverbs', 20, 29, 13, 'The poor man and the oppressor have this in common: The LORD gives light to the eyes of both.'),
  ('BSB', 'Proverbs', 20, 29, 14, 'A king who judges the poor with fairness— his throne will be established forever.'),
  ('BSB', 'Proverbs', 20, 29, 15, 'A rod of correction imparts wisdom, but a child left to himself disgraces his mother.'),
  ('BSB', 'Proverbs', 20, 29, 16, 'When the wicked thrive, rebellion increases; but the righteous will see their downfall.'),
  ('BSB', 'Proverbs', 20, 29, 17, 'Discipline your son, and he will give you rest; he will bring delight to your soul.'),
  ('BSB', 'Proverbs', 20, 29, 18, 'Where there is no vision, the people cast off restraint; but blessed is he who keeps the Law.'),
  ('BSB', 'Proverbs', 20, 29, 19, 'A servant cannot be corrected by words alone; though he understands, he will not respond.'),
  ('BSB', 'Proverbs', 20, 29, 20, 'Do you see a man who speaks in haste? There is more hope for a fool than for him.'),
  ('BSB', 'Proverbs', 20, 29, 21, 'A servant pampered from his youth will bring grief in the end.'),
  ('BSB', 'Proverbs', 20, 29, 22, 'An angry man stirs up dissension, and a hot-tempered man abounds in transgression.'),
  ('BSB', 'Proverbs', 20, 29, 23, 'A man’s pride will bring him low, but a humble spirit will obtain honor.'),
  ('BSB', 'Proverbs', 20, 29, 24, 'A partner to a thief hates his own soul; he receives the oath, but does not testify.'),
  ('BSB', 'Proverbs', 20, 29, 25, 'The fear of man is a snare, but whoever trusts in the LORD is set securely on high.'),
  ('BSB', 'Proverbs', 20, 29, 26, 'Many seek the ruler’s favor, but a man receives justice from the LORD.'),
  ('BSB', 'Proverbs', 20, 29, 27, 'An unjust man is detestable to the righteous, and one whose way is upright is detestable to the wicked.'),
  ('BSB', 'Proverbs', 20, 30, 1, 'These are the words of Agur son of Jakeh—the burden that this man declared to Ithiel: “I am weary, O God, and worn out.'),
  ('BSB', 'Proverbs', 20, 30, 2, 'Surely I am the most ignorant of men, and I lack the understanding of a man.'),
  ('BSB', 'Proverbs', 20, 30, 3, 'I have not learned wisdom, and I have no knowledge of the Holy One.'),
  ('BSB', 'Proverbs', 20, 30, 4, 'Who has ascended to heaven and come down? Who has gathered the wind in His hands? Who has bound up the waters in His cloak? Who has established all the ends of the earth? What is His name, and what is the name of His Son— surely you know!'),
  ('BSB', 'Proverbs', 20, 30, 5, 'Every word of God is flawless; He is a shield to those who take refuge in Him.'),
  ('BSB', 'Proverbs', 20, 30, 6, 'Do not add to His words, lest He rebuke you and prove you a liar.'),
  ('BSB', 'Proverbs', 20, 30, 7, 'Two things I ask of You— do not refuse me before I die:'),
  ('BSB', 'Proverbs', 20, 30, 8, 'Keep falsehood and deceitful words far from me. Give me neither poverty nor riches; feed me with the bread that is my portion.'),
  ('BSB', 'Proverbs', 20, 30, 9, 'Otherwise, I may have too much and deny You, saying, ‘Who is the LORD?’ Or I may become poor and steal, profaning the name of my God.'),
  ('BSB', 'Proverbs', 20, 30, 10, 'Do not slander a servant to his master, or he will curse you, and you will bear the guilt.'),
  ('BSB', 'Proverbs', 20, 30, 11, 'There is a generation of those who curse their fathers and do not bless their mothers.'),
  ('BSB', 'Proverbs', 20, 30, 12, 'There is a generation of those who are pure in their own eyes and yet unwashed of their filth.'),
  ('BSB', 'Proverbs', 20, 30, 13, 'There is a generation—how haughty are their eyes and pretentious are their glances—'),
  ('BSB', 'Proverbs', 20, 30, 14, 'there is a generation whose teeth are swords and whose jaws are knives, devouring the oppressed from the earth and the needy from among men.'),
  ('BSB', 'Proverbs', 20, 30, 15, 'The leech has two daughters: Give and Give. There are three things that are never satisfied, four that never say, ‘Enough!’:'),
  ('BSB', 'Proverbs', 20, 30, 16, 'Sheol, the barren womb, land never satisfied with water, and fire that never says, ‘Enough!’'),
  ('BSB', 'Proverbs', 20, 30, 17, 'As for the eye that mocks a father and scorns obedience to a mother, may the ravens of the valley pluck it out and young vultures devour it.'),
  ('BSB', 'Proverbs', 20, 30, 18, 'There are three things too wonderful for me, four that I cannot understand:'),
  ('BSB', 'Proverbs', 20, 30, 19, 'the way of an eagle in the sky, the way of a snake on a rock, the way of a ship at sea, and the way of a man with a maiden.'),
  ('BSB', 'Proverbs', 20, 30, 20, 'This is the way of an adulteress: She eats and wipes her mouth and says, ‘I have done nothing wrong.’'),
  ('BSB', 'Proverbs', 20, 30, 21, 'Under three things the earth trembles, under four it cannot bear up:'),
  ('BSB', 'Proverbs', 20, 30, 22, 'a servant who becomes king, a fool who is filled with food,'),
  ('BSB', 'Proverbs', 20, 30, 23, 'an unloved woman who marries, and a maidservant who supplants her mistress.'),
  ('BSB', 'Proverbs', 20, 30, 24, 'Four things on earth are small, yet they are exceedingly wise:'),
  ('BSB', 'Proverbs', 20, 30, 25, 'The ants are creatures of little strength, yet they store up their food in the summer;'),
  ('BSB', 'Proverbs', 20, 30, 26, 'the rock badgers are creatures of little power, yet they make their homes in the rocks;'),
  ('BSB', 'Proverbs', 20, 30, 27, 'the locusts have no king, yet they all advance in formation;'),
  ('BSB', 'Proverbs', 20, 30, 28, 'and the lizard can be caught in one’s hands, yet it is found in the palaces of kings.'),
  ('BSB', 'Proverbs', 20, 30, 29, 'There are three things that are stately in their stride, and four that are impressive in their walk:'),
  ('BSB', 'Proverbs', 20, 30, 30, 'a lion, mighty among beasts, refusing to retreat before anything;'),
  ('BSB', 'Proverbs', 20, 30, 31, 'a strutting rooster; a he-goat; and a king with his army around him.'),
  ('BSB', 'Proverbs', 20, 30, 32, 'If you have foolishly exalted yourself or if you have plotted evil, put your hand over your mouth.'),
  ('BSB', 'Proverbs', 20, 30, 33, 'For as the churning of milk yields butter, and the twisting of the nose draws blood, so the stirring of anger brings forth strife.”'),
  ('BSB', 'Proverbs', 20, 31, 1, 'These are the words of King Lemuel—the burden that his mother taught him:'),
  ('BSB', 'Proverbs', 20, 31, 2, 'What shall I say, O my son? What, O son of my womb? What, O son of my vows?'),
  ('BSB', 'Proverbs', 20, 31, 3, 'Do not spend your strength on women or your vigor on those who ruin kings.'),
  ('BSB', 'Proverbs', 20, 31, 4, 'It is not for kings, O Lemuel, it is not for kings to drink wine, or for rulers to crave strong drink,'),
  ('BSB', 'Proverbs', 20, 31, 5, 'lest they drink and forget what is decreed, depriving all the oppressed of justice.'),
  ('BSB', 'Proverbs', 20, 31, 6, 'Give strong drink to one who is perishing, and wine to the bitter in soul.'),
  ('BSB', 'Proverbs', 20, 31, 7, 'Let him drink and forget his poverty, and remember his misery no more.'),
  ('BSB', 'Proverbs', 20, 31, 8, 'Open your mouth for those with no voice, for the cause of all the dispossessed.'),
  ('BSB', 'Proverbs', 20, 31, 9, 'Open your mouth, judge righteously, and defend the cause of the poor and needy.'),
  ('BSB', 'Proverbs', 20, 31, 10, 'A wife of noble character, who can find? She is far more precious than rubies.'),
  ('BSB', 'Proverbs', 20, 31, 11, 'The heart of her husband trusts in her, and he lacks nothing of value.'),
  ('BSB', 'Proverbs', 20, 31, 12, 'She brings him good and not harm all the days of her life.'),
  ('BSB', 'Proverbs', 20, 31, 13, 'She selects wool and flax and works with eager hands.'),
  ('BSB', 'Proverbs', 20, 31, 14, 'She is like the merchant ships, bringing her food from afar.'),
  ('BSB', 'Proverbs', 20, 31, 15, 'She rises while it is still night to provide food for her household and portions for her maidservants.'),
  ('BSB', 'Proverbs', 20, 31, 16, 'She appraises a field and buys it; from her earnings she plants a vineyard.'),
  ('BSB', 'Proverbs', 20, 31, 17, 'She girds herself with strength and shows that her arms are strong.'),
  ('BSB', 'Proverbs', 20, 31, 18, 'She sees that her gain is good, and her lamp is not extinguished at night.'),
  ('BSB', 'Proverbs', 20, 31, 19, 'She stretches out her hands to the distaff and grasps the spindle with her fingers.'),
  ('BSB', 'Proverbs', 20, 31, 20, 'She opens her arms to the poor and reaches out her hands to the needy.'),
  ('BSB', 'Proverbs', 20, 31, 21, 'When it snows, she has no fear for her household, for they are all clothed in scarlet.'),
  ('BSB', 'Proverbs', 20, 31, 22, 'She makes coverings for her bed; her clothing is fine linen and purple.'),
  ('BSB', 'Proverbs', 20, 31, 23, 'Her husband is known at the city gate, where he sits among the elders of the land.'),
  ('BSB', 'Proverbs', 20, 31, 24, 'She makes linen garments and sells them; she delivers sashes to the merchants.'),
  ('BSB', 'Proverbs', 20, 31, 25, 'Strength and honor are her clothing, and she can laugh at the days to come.'),
  ('BSB', 'Proverbs', 20, 31, 26, 'She opens her mouth with wisdom, and faithful instruction is on her tongue.'),
  ('BSB', 'Proverbs', 20, 31, 27, 'She watches over the affairs of her household and does not eat the bread of idleness.'),
  ('BSB', 'Proverbs', 20, 31, 28, 'Her children rise up and call her blessed; her husband praises her as well:'),
  ('BSB', 'Proverbs', 20, 31, 29, '“Many daughters have done noble things, but you surpass them all!”'),
  ('BSB', 'Proverbs', 20, 31, 30, 'Charm is deceptive and beauty is fleeting, but a woman who fears the LORD is to be praised.'),
  ('BSB', 'Proverbs', 20, 31, 31, 'Give her the fruit of her hands, and let her works praise her at the gates.'),
  ('BSB', 'Ecclesiastes', 21, 1, 1, 'These are the words of the Teacher, the son of David, king in Jerusalem:'),
  ('BSB', 'Ecclesiastes', 21, 1, 2, '“Futility of futilities,” says the Teacher, “futility of futilities! Everything is futile!”'),
  ('BSB', 'Ecclesiastes', 21, 1, 3, 'What does a man gain from all his labor, at which he toils under the sun?'),
  ('BSB', 'Ecclesiastes', 21, 1, 4, 'Generations come and generations go, but the earth remains forever.'),
  ('BSB', 'Ecclesiastes', 21, 1, 5, 'The sun rises and the sun sets; it hurries back to where it rises.'),
  ('BSB', 'Ecclesiastes', 21, 1, 6, 'The wind blows southward, then turns northward; round and round it swirls, ever returning on its course.'),
  ('BSB', 'Ecclesiastes', 21, 1, 7, 'All the rivers flow into the sea, yet the sea is never full; to the place from which the streams come, there again they flow.'),
  ('BSB', 'Ecclesiastes', 21, 1, 8, 'All things are wearisome, more than one can describe; the eye is not satisfied with seeing, nor the ear content with hearing.'),
  ('BSB', 'Ecclesiastes', 21, 1, 9, 'What has been will be again, and what has been done will be done again; there is nothing new under the sun.'),
  ('BSB', 'Ecclesiastes', 21, 1, 10, 'Is there a case where one can say, “Look, this is new”? It has already existed in the ages before us.'),
  ('BSB', 'Ecclesiastes', 21, 1, 11, 'There is no remembrance of those who came before, and those yet to come will not be remembered by those who follow after.'),
  ('BSB', 'Ecclesiastes', 21, 1, 12, 'I, the Teacher, was king over Israel in Jerusalem.'),
  ('BSB', 'Ecclesiastes', 21, 1, 13, 'And I set my mind to seek and explore by wisdom all that is done under heaven. What a heavy burden God has laid upon the sons of men to occupy them!'),
  ('BSB', 'Ecclesiastes', 21, 1, 14, 'I have seen all the things that are done under the sun, and have found them all to be futile, a pursuit of the wind.'),
  ('BSB', 'Ecclesiastes', 21, 1, 15, 'What is crooked cannot be straightened, and what is lacking cannot be counted.'),
  ('BSB', 'Ecclesiastes', 21, 1, 16, 'I said to myself, “Behold, I have grown and increased in wisdom beyond all those before me who were over Jerusalem, and my mind has observed a wealth of wisdom and knowledge.”'),
  ('BSB', 'Ecclesiastes', 21, 1, 17, 'So I set my mind to know wisdom and madness and folly; I learned that this, too, is a pursuit of the wind.'),
  ('BSB', 'Ecclesiastes', 21, 1, 18, 'For with much wisdom comes much sorrow, and as knowledge grows, grief increases.'),
  ('BSB', 'Ecclesiastes', 21, 2, 1, 'I said to myself, “Come now, I will test you with pleasure; enjoy what is good!” But it proved to be futile.'),
  ('BSB', 'Ecclesiastes', 21, 2, 2, 'I said of laughter, “It is folly,” and of pleasure, “What does it accomplish?”'),
  ('BSB', 'Ecclesiastes', 21, 2, 3, 'I sought to cheer my body with wine and to embrace folly—my mind still guiding me with wisdom—until I could see what was worthwhile for men to do under heaven during the few days of their lives.'),
  ('BSB', 'Ecclesiastes', 21, 2, 4, 'I expanded my pursuits. I built houses and planted vineyards for myself.'),
  ('BSB', 'Ecclesiastes', 21, 2, 5, 'I made gardens and parks for myself, where I planted all kinds of fruit trees.'),
  ('BSB', 'Ecclesiastes', 21, 2, 6, 'I built reservoirs to water my groves of flourishing trees.'),
  ('BSB', 'Ecclesiastes', 21, 2, 7, 'I acquired menservants and maidservants, and servants were born in my house. I also owned more herds and flocks than anyone in Jerusalem before me,'),
  ('BSB', 'Ecclesiastes', 21, 2, 8, 'and I accumulated for myself silver and gold and the treasure of kings and provinces. I gathered to myself male and female singers, and the delights of the sons of men—many concubines.'),
  ('BSB', 'Ecclesiastes', 21, 2, 9, 'So I became great and surpassed all in Jerusalem who had preceded me; and my wisdom remained with me.'),
  ('BSB', 'Ecclesiastes', 21, 2, 10, 'Anything my eyes desired, I did not deny myself. I refused my heart no pleasure. For my heart took delight in all my work, and this was the reward for all my labor.'),
  ('BSB', 'Ecclesiastes', 21, 2, 11, 'Yet when I considered all the works that my hands had accomplished and what I had toiled to achieve, I found everything to be futile, a pursuit of the wind; there was nothing to be gained under the sun.'),
  ('BSB', 'Ecclesiastes', 21, 2, 12, 'Then I turned to consider wisdom and madness and folly; for what more can the king’s successor do than what has already been accomplished?'),
  ('BSB', 'Ecclesiastes', 21, 2, 13, 'And I saw that wisdom exceeds folly, just as light exceeds darkness:'),
  ('BSB', 'Ecclesiastes', 21, 2, 14, 'The wise man has eyes in his head, but the fool walks in darkness. Yet I also came to realize that one fate overcomes them both.'),
  ('BSB', 'Ecclesiastes', 21, 2, 15, 'So I said to myself, “The fate of the fool will also befall me. What then have I gained by being wise?” And I said to myself that this too is futile.'),
  ('BSB', 'Ecclesiastes', 21, 2, 16, 'For there is no lasting remembrance of the wise, just as with the fool, seeing that both will be forgotten in the days to come. Alas, the wise man will die just like the fool!'),
  ('BSB', 'Ecclesiastes', 21, 2, 17, 'So I hated life, because the work that is done under the sun was grievous to me. For everything is futile and a pursuit of the wind.'),
  ('BSB', 'Ecclesiastes', 21, 2, 18, 'I hated all for which I had toiled under the sun, because I must leave it to the man who comes after me.'),
  ('BSB', 'Ecclesiastes', 21, 2, 19, 'And who knows whether that man will be wise or foolish? Yet he will take over all the labor at which I have worked skillfully under the sun. This too is futile.'),
  ('BSB', 'Ecclesiastes', 21, 2, 20, 'So my heart began to despair over all the labor that I had done under the sun.'),
  ('BSB', 'Ecclesiastes', 21, 2, 21, 'When there is a man who has labored with wisdom, knowledge, and skill, and he must give his portion to a man who has not worked for it, this too is futile and a great evil.'),
  ('BSB', 'Ecclesiastes', 21, 2, 22, 'For what does a man get for all the toil and striving with which he labors under the sun?'),
  ('BSB', 'Ecclesiastes', 21, 2, 23, 'Indeed, all his days are filled with grief, and his task is sorrowful; even at night, his mind does not rest. This too is futile.'),
  ('BSB', 'Ecclesiastes', 21, 2, 24, 'Nothing is better for a man than to eat and drink and enjoy his work. I have also seen that this is from the hand of God.'),
  ('BSB', 'Ecclesiastes', 21, 2, 25, 'For apart from Him, who can eat and who can find enjoyment?'),
  ('BSB', 'Ecclesiastes', 21, 2, 26, 'To the man who is pleasing in His sight, He gives wisdom and knowledge and joy, but to the sinner He assigns the task of gathering and accumulating that which he will hand over to one who pleases God. This too is futile and a pursuit of the wind.'),
  ('BSB', 'Ecclesiastes', 21, 3, 1, 'To everything there is a season, and a time for every purpose under heaven:'),
  ('BSB', 'Ecclesiastes', 21, 3, 2, 'a time to be born and a time to die, a time to plant and a time to uproot,'),
  ('BSB', 'Ecclesiastes', 21, 3, 3, 'a time to kill and a time to heal, a time to break down and a time to build,'),
  ('BSB', 'Ecclesiastes', 21, 3, 4, 'a time to weep and a time to laugh, a time to mourn and a time to dance,'),
  ('BSB', 'Ecclesiastes', 21, 3, 5, 'a time to cast away stones and a time to gather stones together, a time to embrace and a time to refrain from embracing,'),
  ('BSB', 'Ecclesiastes', 21, 3, 6, 'a time to search and a time to count as lost, a time to keep and a time to discard,'),
  ('BSB', 'Ecclesiastes', 21, 3, 7, 'a time to tear and a time to mend, a time to be silent and a time to speak,'),
  ('BSB', 'Ecclesiastes', 21, 3, 8, 'a time to love and a time to hate, a time for war and a time for peace.'),
  ('BSB', 'Ecclesiastes', 21, 3, 9, 'What does the worker gain from his toil?'),
  ('BSB', 'Ecclesiastes', 21, 3, 10, 'I have seen the burden that God has laid upon the sons of men to occupy them.'),
  ('BSB', 'Ecclesiastes', 21, 3, 11, 'He has made everything beautiful in its time. He has also set eternity in the hearts of men, yet they cannot fathom the work that God has done from beginning to end.'),
  ('BSB', 'Ecclesiastes', 21, 3, 12, 'I know that there is nothing better for them than to rejoice and do good while they live,'),
  ('BSB', 'Ecclesiastes', 21, 3, 13, 'and also that every man should eat and drink and find satisfaction in all his labor—this is the gift of God.'),
  ('BSB', 'Ecclesiastes', 21, 3, 14, 'I know that everything God does endures forever; nothing can be added to it or taken from it. God does it so that they should fear Him.'),
  ('BSB', 'Ecclesiastes', 21, 3, 15, 'What exists has already been, and what will be has already been, for God will call to account what has passed.'),
  ('BSB', 'Ecclesiastes', 21, 3, 16, 'Furthermore, I saw under the sun that in the place of judgment there is wickedness, and in the place of righteousness there is wickedness.'),
  ('BSB', 'Ecclesiastes', 21, 3, 17, 'I said in my heart, “God will judge the righteous and the wicked, since there is a time for every activity and every deed.”'),
  ('BSB', 'Ecclesiastes', 21, 3, 18, 'I said to myself, “As for the sons of men, God tests them so that they may see for themselves that they are but beasts.”'),
  ('BSB', 'Ecclesiastes', 21, 3, 19, 'For the fates of both men and beasts are the same: As one dies, so dies the other—they all have the same breath. Man has no advantage over the animals, since everything is futile.'),
  ('BSB', 'Ecclesiastes', 21, 3, 20, 'All go to one place; all come from dust, and all return to dust.'),
  ('BSB', 'Ecclesiastes', 21, 3, 21, 'Who knows if the spirit of man rises upward and the spirit of the animal descends into the earth?'),
  ('BSB', 'Ecclesiastes', 21, 3, 22, 'I have seen that there is nothing better for a man than to enjoy his work, because that is his lot. For who can bring him to see what will come after him?'),
  ('BSB', 'Ecclesiastes', 21, 4, 1, 'Again I looked, and I considered all the oppression taking place under the sun. I saw the tears of the oppressed, and they had no comforter; the power lay in the hands of their oppressors, and there was no comforter.'),
  ('BSB', 'Ecclesiastes', 21, 4, 2, 'So I admired the dead, who had already died, above the living, who are still alive.'),
  ('BSB', 'Ecclesiastes', 21, 4, 3, 'But better than both is he who has not yet existed, who has not seen the evil that is done under the sun.'),
  ('BSB', 'Ecclesiastes', 21, 4, 4, 'I saw that all labor and success spring from a man’s envy of his neighbor. This too is futile and a pursuit of the wind.'),
  ('BSB', 'Ecclesiastes', 21, 4, 5, 'The fool folds his hands and consumes his own flesh.'),
  ('BSB', 'Ecclesiastes', 21, 4, 6, 'Better one handful with tranquility than two handfuls with toil and pursuit of the wind.'),
  ('BSB', 'Ecclesiastes', 21, 4, 7, 'Again, I saw futility under the sun.'),
  ('BSB', 'Ecclesiastes', 21, 4, 8, 'There is a man all alone, without even a son or brother. And though there is no end to his labor, his eyes are still not content with his wealth: “For whom do I toil and bereave my soul of enjoyment?” This too is futile—a miserable task.'),
  ('BSB', 'Ecclesiastes', 21, 4, 9, 'Two are better than one, because they have a good return for their labor.'),
  ('BSB', 'Ecclesiastes', 21, 4, 10, 'For if one falls down, his companion can lift him up; but pity the one who falls without another to help him up!'),
  ('BSB', 'Ecclesiastes', 21, 4, 11, 'Again, if two lie down together, they will keep warm; but how can one keep warm alone?'),
  ('BSB', 'Ecclesiastes', 21, 4, 12, 'And though one may be overpowered, two can resist. Moreover, a cord of three strands is not quickly broken.'),
  ('BSB', 'Ecclesiastes', 21, 4, 13, 'Better is a poor but wise youth than an old but foolish king who no longer knows how to take a warning.'),
  ('BSB', 'Ecclesiastes', 21, 4, 14, 'For the youth has come from the prison to the kingship, though he was born poor in his own kingdom.'),
  ('BSB', 'Ecclesiastes', 21, 4, 15, 'I saw that all who lived and walked under the sun followed this second one, the youth who succeeded the king.'),
  ('BSB', 'Ecclesiastes', 21, 4, 16, 'There is no limit to all the people who were before them. Yet the successor will not be celebrated by those who come even later. This too is futile and a pursuit of the wind.'),
  ('BSB', 'Ecclesiastes', 21, 5, 1, 'Guard your steps when you go to the house of God. Draw near to listen rather than to offer the sacrifice of fools, who do not know that they do wrong.'),
  ('BSB', 'Ecclesiastes', 21, 5, 2, 'Do not be quick to speak, and do not be hasty in your heart to utter a word before God. After all, God is in heaven and you are on earth. So let your words be few.'),
  ('BSB', 'Ecclesiastes', 21, 5, 3, 'As a dream comes through many cares, so the speech of a fool comes with many words.'),
  ('BSB', 'Ecclesiastes', 21, 5, 4, 'When you make a vow to God, do not delay in fulfilling it, because He takes no pleasure in fools. Fulfill your vow.'),
  ('BSB', 'Ecclesiastes', 21, 5, 5, 'It is better not to vow than to make a vow and not fulfill it.'),
  ('BSB', 'Ecclesiastes', 21, 5, 6, 'Do not let your mouth cause your flesh to sin, and do not tell the messenger that your vow was a mistake. Why should God be angry with your words and destroy the work of your hands?'),
  ('BSB', 'Ecclesiastes', 21, 5, 7, 'For as many dreams bring futility, so do many words. Therefore, fear God.'),
  ('BSB', 'Ecclesiastes', 21, 5, 8, 'If you see the oppression of the poor and the denial of justice and righteousness in the province, do not be astonished at the matter; for one official is watched by a superior, and others higher still are over them.'),
  ('BSB', 'Ecclesiastes', 21, 5, 9, 'The produce of the earth is taken by all; the king himself profits from the fields.'),
  ('BSB', 'Ecclesiastes', 21, 5, 10, 'He who loves money is never satisfied by money, and he who loves wealth is never satisfied by income. This too is futile.'),
  ('BSB', 'Ecclesiastes', 21, 5, 11, 'When good things increase, so do those who consume them; what then is the profit to the owner, except to behold them with his eyes?'),
  ('BSB', 'Ecclesiastes', 21, 5, 12, 'The sleep of the worker is sweet, whether he eats little or much, but the abundance of the rich man permits him no sleep.'),
  ('BSB', 'Ecclesiastes', 21, 5, 13, 'There is a grievous evil I have seen under the sun: wealth hoarded to the harm of its owner,'),
  ('BSB', 'Ecclesiastes', 21, 5, 14, 'or wealth lost in a failed venture, so when that man has a son there is nothing to pass on.'),
  ('BSB', 'Ecclesiastes', 21, 5, 15, 'As a man came from his mother’s womb, so he will depart again, naked as he arrived. He takes nothing for his labor to carry in his hands.'),
  ('BSB', 'Ecclesiastes', 21, 5, 16, 'This too is a grievous evil: Exactly as a man is born, so he will depart. What does he gain as he toils for the wind?'),
  ('BSB', 'Ecclesiastes', 21, 5, 17, 'Moreover, all his days he eats in darkness, with much sorrow, sickness, and anger.'),
  ('BSB', 'Ecclesiastes', 21, 5, 18, 'Here is what I have seen to be good and fitting: to eat and drink, and to find satisfaction in all the labor one does under the sun during the few days of life that God has given him—for this is his lot.'),
  ('BSB', 'Ecclesiastes', 21, 5, 19, 'Furthermore, God has given riches and wealth to every man, and He has enabled him to enjoy them, to accept his lot, and to rejoice in his labor. This is a gift from God.'),
  ('BSB', 'Ecclesiastes', 21, 5, 20, 'For a man seldom considers the days of his life, because God keeps him occupied with the joy of his heart.'),
  ('BSB', 'Ecclesiastes', 21, 6, 1, 'There is another evil I have seen under the sun, and it weighs heavily upon mankind:'),
  ('BSB', 'Ecclesiastes', 21, 6, 2, 'God gives a man riches, wealth, and honor, so that he lacks nothing his heart desires; but God does not allow him to enjoy them. Instead, a stranger will enjoy them. This is futile and a grievous affliction.'),
  ('BSB', 'Ecclesiastes', 21, 6, 3, 'A man may father a hundred children and live for many years; yet no matter how long he lives, if he is unsatisfied with his prosperity and does not even receive a proper burial, I say that a stillborn child is better off than he.'),
  ('BSB', 'Ecclesiastes', 21, 6, 4, 'For a stillborn child enters in futility and departs in darkness, and his name is shrouded in obscurity.'),
  ('BSB', 'Ecclesiastes', 21, 6, 5, 'The child, though neither seeing the sun nor knowing anything, has more rest than that man,'),
  ('BSB', 'Ecclesiastes', 21, 6, 6, 'even if he lives a thousand years twice over but fails to enjoy his prosperity. Do not all go to the same place?'),
  ('BSB', 'Ecclesiastes', 21, 6, 7, 'All a man’s labor is for his mouth, yet his appetite is never satisfied.'),
  ('BSB', 'Ecclesiastes', 21, 6, 8, 'What advantage, then, has the wise man over the fool? What gain comes to the poor man who knows how to conduct himself before others?'),
  ('BSB', 'Ecclesiastes', 21, 6, 9, 'Better what the eye can see than the wandering of desire. This too is futile and a pursuit of the wind.'),
  ('BSB', 'Ecclesiastes', 21, 6, 10, 'Whatever exists was named long ago, and what happens to a man is foreknown; but he cannot contend with one stronger than he.'),
  ('BSB', 'Ecclesiastes', 21, 6, 11, 'For the more words, the more futility—and how does that profit anyone?'),
  ('BSB', 'Ecclesiastes', 21, 6, 12, 'For who knows what is good for a man during the few days in which he passes through his fleeting life like a shadow? Who can tell a man what will come after him under the sun?'),
  ('BSB', 'Ecclesiastes', 21, 7, 1, 'A good name is better than fine perfume, and one’s day of death is better than his day of birth.'),
  ('BSB', 'Ecclesiastes', 21, 7, 2, 'It is better to enter a house of mourning than a house of feasting, since death is the end of every man, and the living should take this to heart.'),
  ('BSB', 'Ecclesiastes', 21, 7, 3, 'Sorrow is better than laughter, for a sad countenance is good for the heart.'),
  ('BSB', 'Ecclesiastes', 21, 7, 4, 'The heart of the wise is in the house of mourning, but the heart of fools is in the house of pleasure.'),
  ('BSB', 'Ecclesiastes', 21, 7, 5, 'It is better to heed a wise man’s rebuke than to listen to the song of fools.'),
  ('BSB', 'Ecclesiastes', 21, 7, 6, 'For like the crackling of thorns under the pot, so is the laughter of the fool. This too is futile.'),
  ('BSB', 'Ecclesiastes', 21, 7, 7, 'Surely extortion turns a wise man into a fool, and a bribe corrupts the heart.'),
  ('BSB', 'Ecclesiastes', 21, 7, 8, 'The end of a matter is better than the beginning, and a patient spirit is better than a proud one.'),
  ('BSB', 'Ecclesiastes', 21, 7, 9, 'Do not be quickly provoked in your spirit, for anger settles in the lap of a fool.'),
  ('BSB', 'Ecclesiastes', 21, 7, 10, 'Do not say, “Why were the old days better than these?” For it is unwise of you to ask about this.'),
  ('BSB', 'Ecclesiastes', 21, 7, 11, 'Wisdom, like an inheritance, is good, and it benefits those who see the sun.'),
  ('BSB', 'Ecclesiastes', 21, 7, 12, 'For wisdom, like money, is a shelter, and the advantage of knowledge is that wisdom preserves the life of its owner.'),
  ('BSB', 'Ecclesiastes', 21, 7, 13, 'Consider the work of God: Who can straighten what He has bent?'),
  ('BSB', 'Ecclesiastes', 21, 7, 14, 'In the day of prosperity, be joyful, but in the day of adversity, consider this: God has made one of these along with the other, so that a man cannot discover anything that will come after him.'),
  ('BSB', 'Ecclesiastes', 21, 7, 15, 'In my futile life I have seen both of these: A righteous man perishing in his righteousness, and a wicked man living long in his wickedness.'),
  ('BSB', 'Ecclesiastes', 21, 7, 16, 'Do not be overly righteous, and do not make yourself too wise. Why should you destroy yourself?'),
  ('BSB', 'Ecclesiastes', 21, 7, 17, 'Do not be excessively wicked, and do not be a fool. Why should you die before your time?'),
  ('BSB', 'Ecclesiastes', 21, 7, 18, 'It is good to grasp the one and not let the other slip from your hand. For he who fears God will follow both warnings.'),
  ('BSB', 'Ecclesiastes', 21, 7, 19, 'Wisdom makes the wise man stronger than ten rulers in a city.'),
  ('BSB', 'Ecclesiastes', 21, 7, 20, 'Surely there is no righteous man on earth who does good and never sins.'),
  ('BSB', 'Ecclesiastes', 21, 7, 21, 'Do not pay attention to every word that is spoken, or you may hear your servant cursing you.'),
  ('BSB', 'Ecclesiastes', 21, 7, 22, 'For you know in your heart that many times you yourself have cursed others.'),
  ('BSB', 'Ecclesiastes', 21, 7, 23, 'All this I tested by wisdom, saying, “I resolve to be wise.” But it was beyond me.'),
  ('BSB', 'Ecclesiastes', 21, 7, 24, 'What exists is out of reach and very deep. Who can fathom it?'),
  ('BSB', 'Ecclesiastes', 21, 7, 25, 'I directed my mind to understand, to explore, to search out wisdom and explanations, and to understand the stupidity of wickedness and the folly of madness.'),
  ('BSB', 'Ecclesiastes', 21, 7, 26, 'And I find more bitter than death the woman who is a snare, whose heart is a net, and whose hands are chains. The man who pleases God escapes her, but the sinner is ensnared.'),
  ('BSB', 'Ecclesiastes', 21, 7, 27, '“Behold,” says the Teacher, “I have discovered this by adding one thing to another to find an explanation.'),
  ('BSB', 'Ecclesiastes', 21, 7, 28, 'While my soul was still searching but not finding, among a thousand I have found one upright man, but among all these I have not found one such woman.'),
  ('BSB', 'Ecclesiastes', 21, 7, 29, 'Only this have I found: I have discovered that God made men upright, but they have sought out many schemes.”'),
  ('BSB', 'Ecclesiastes', 21, 8, 1, 'Who is like the wise man? Who knows the interpretation of a matter? A man’s wisdom brightens his face, and the sternness of his face is changed.'),
  ('BSB', 'Ecclesiastes', 21, 8, 2, 'Keep the king’s command, I say, because of your oath before God.'),
  ('BSB', 'Ecclesiastes', 21, 8, 3, 'Do not hasten to leave his presence, and do not persist in a bad cause, for he will do whatever he pleases.'),
  ('BSB', 'Ecclesiastes', 21, 8, 4, 'For the king’s word is supreme, and who can say to him, “What are you doing?”'),
  ('BSB', 'Ecclesiastes', 21, 8, 5, 'Whoever keeps his command will come to no harm, and a wise heart knows the right time and procedure.'),
  ('BSB', 'Ecclesiastes', 21, 8, 6, 'For there is a right time and procedure to every purpose, though a man’s misery weighs heavily upon him.'),
  ('BSB', 'Ecclesiastes', 21, 8, 7, 'Since no one knows what will happen, who can tell him what is to come?'),
  ('BSB', 'Ecclesiastes', 21, 8, 8, 'As no man has power over the wind to contain it, so no one has authority over his day of death. As no one can be discharged in wartime, so wickedness will not release those who practice it.'),
  ('BSB', 'Ecclesiastes', 21, 8, 9, 'All this I have seen, applying my mind to every deed that is done under the sun; there is a time when one man lords it over another to his own detriment.'),
  ('BSB', 'Ecclesiastes', 21, 8, 10, 'Then too, I saw the burial of the wicked who used to go in and out of the holy place, and they were praised in the city where they had done so. This too is futile.'),
  ('BSB', 'Ecclesiastes', 21, 8, 11, 'When the sentence for a crime is not speedily executed, the hearts of men become fully set on doing evil.'),
  ('BSB', 'Ecclesiastes', 21, 8, 12, 'Although a sinner does evil a hundred times and still lives long, yet I also know that it will go well with those who fear God, who are reverent in His presence.'),
  ('BSB', 'Ecclesiastes', 21, 8, 13, 'Yet because the wicked do not fear God, it will not go well with them, and their days will not lengthen like a shadow.'),
  ('BSB', 'Ecclesiastes', 21, 8, 14, 'There is a futility that is done on the earth: There are righteous men who get what the actions of the wicked deserve, and there are wicked men who get what the actions of the righteous deserve. I say that this too is futile.'),
  ('BSB', 'Ecclesiastes', 21, 8, 15, 'So I commended the enjoyment of life, because there is nothing better for a man under the sun than to eat and drink and be merry. For this joy will accompany him in his labor during the days of his life that God gives him under the sun.'),
  ('BSB', 'Ecclesiastes', 21, 8, 16, 'When I applied my mind to know wisdom and to observe the task that one performs on the earth—though his eyes do not see sleep in the day or even in the night—'),
  ('BSB', 'Ecclesiastes', 21, 8, 17, 'I saw every work of God, and that a man is unable to comprehend the work that is done under the sun. Despite his efforts to search it out, he cannot find its meaning; even if the wise man claims to know, he is unable to comprehend.'),
  ('BSB', 'Ecclesiastes', 21, 9, 1, 'So I took all this to heart and concluded that the righteous and the wise, as well as their deeds, are in God’s hands. Man does not know what lies ahead, whether love or hate.'),
  ('BSB', 'Ecclesiastes', 21, 9, 2, 'It is the same for all: There is a common fate for the righteous and the wicked, for the good and the bad, for the clean and the unclean, for the one who sacrifices and the one who does not. As it is for the good, so it is for the sinner; as it is for the one who makes a vow, so it is for the one who refuses to take a vow.'),
  ('BSB', 'Ecclesiastes', 21, 9, 3, 'This is an evil in everything that is done under the sun: There is one fate for everyone. Furthermore, the hearts of men are full of evil and madness while they are alive, and afterward they join the dead.'),
  ('BSB', 'Ecclesiastes', 21, 9, 4, 'There is hope, however, for anyone who is among the living; for even a live dog is better than a dead lion.'),
  ('BSB', 'Ecclesiastes', 21, 9, 5, 'For the living know that they will die, but the dead know nothing. They have no further reward, because the memory of them is forgotten.'),
  ('BSB', 'Ecclesiastes', 21, 9, 6, 'Their love, their hate, and their envy have already vanished, and they will never again have a share in all that is done under the sun.'),
  ('BSB', 'Ecclesiastes', 21, 9, 7, 'Go, eat your bread with joy, and drink your wine with a cheerful heart, for God has already approved your works:'),
  ('BSB', 'Ecclesiastes', 21, 9, 8, 'Let your garments always be white, and never spare the oil for your head.'),
  ('BSB', 'Ecclesiastes', 21, 9, 9, 'Enjoy life with your beloved wife all the days of the fleeting life that God has given you under the sun—all your fleeting days. For this is your portion in life and in your labor under the sun.'),
  ('BSB', 'Ecclesiastes', 21, 9, 10, 'Whatever you find to do with your hands, do it with all your might, for in Sheol, where you are going, there is no work or planning or knowledge or wisdom.'),
  ('BSB', 'Ecclesiastes', 21, 9, 11, 'I saw something else under the sun: The race is not to the swift, nor the battle to the strong; neither is the bread to the wise, nor the wealth to the intelligent, nor the favor to the skillful. For time and chance happen to all.'),
  ('BSB', 'Ecclesiastes', 21, 9, 12, 'For surely no man knows his time: Like fish caught in a cruel net or birds trapped in a snare, so men are ensnared in an evil time that suddenly falls upon them.'),
  ('BSB', 'Ecclesiastes', 21, 9, 13, 'I have also seen this wisdom under the sun, and it was great to me:'),
  ('BSB', 'Ecclesiastes', 21, 9, 14, 'There was a small city with few men. A mighty king came against it, surrounded it, and built large siege ramps against it.'),
  ('BSB', 'Ecclesiastes', 21, 9, 15, 'Now a poor wise man was found in the city, and he saved the city by his wisdom. Yet no one remembered that poor man.'),
  ('BSB', 'Ecclesiastes', 21, 9, 16, 'And I said, “Wisdom is better than strength, but the wisdom of the poor man is despised, and his words are not heeded.”'),
  ('BSB', 'Ecclesiastes', 21, 9, 17, 'The calm words of the wise are heeded over the shouts of a ruler among fools.'),
  ('BSB', 'Ecclesiastes', 21, 9, 18, 'Wisdom is better than weapons of war, but one sinner destroys much good.'),
  ('BSB', 'Ecclesiastes', 21, 10, 1, 'As dead flies bring a stench to the perfumer’s oil, so a little folly outweighs wisdom and honor.'),
  ('BSB', 'Ecclesiastes', 21, 10, 2, 'A wise man’s heart inclines to the right, but the heart of a fool to the left.'),
  ('BSB', 'Ecclesiastes', 21, 10, 3, 'Even as the fool walks along the road, his sense is lacking, and he shows everyone that he is a fool.'),
  ('BSB', 'Ecclesiastes', 21, 10, 4, 'If the ruler’s temper flares against you, do not abandon your post, for calmness lays great offenses to rest.'),
  ('BSB', 'Ecclesiastes', 21, 10, 5, 'There is an evil I have seen under the sun— an error that proceeds from the ruler:'),
  ('BSB', 'Ecclesiastes', 21, 10, 6, 'Folly is appointed to great heights, but the rich sit in lowly positions.'),
  ('BSB', 'Ecclesiastes', 21, 10, 7, 'I have seen slaves on horseback, while princes go on foot like slaves.'),
  ('BSB', 'Ecclesiastes', 21, 10, 8, 'He who digs a pit may fall into it, and he who breaches a wall may be bitten by a snake.'),
  ('BSB', 'Ecclesiastes', 21, 10, 9, 'The one who quarries stones may be injured by them, and he who splits logs endangers himself.'),
  ('BSB', 'Ecclesiastes', 21, 10, 10, 'If the axe is dull and the blade unsharpened, more strength must be exerted, but skill produces success.'),
  ('BSB', 'Ecclesiastes', 21, 10, 11, 'If the snake bites before it is charmed, there is no profit for the charmer.'),
  ('BSB', 'Ecclesiastes', 21, 10, 12, 'The words of a wise man’s mouth are gracious, but the lips of a fool consume him.'),
  ('BSB', 'Ecclesiastes', 21, 10, 13, 'The beginning of his talk is folly, and the end of his speech is evil madness.'),
  ('BSB', 'Ecclesiastes', 21, 10, 14, 'Yet the fool multiplies words. No one knows what is coming, and who can tell him what will come after him?'),
  ('BSB', 'Ecclesiastes', 21, 10, 15, 'The toil of a fool wearies him, for he does not know the way to the city.'),
  ('BSB', 'Ecclesiastes', 21, 10, 16, 'Woe to you, O land whose king is a youth, and whose princes feast in the morning.'),
  ('BSB', 'Ecclesiastes', 21, 10, 17, 'Blessed are you, O land whose king is a son of nobles, and whose princes feast at the proper time— for strength and not for drunkenness.'),
  ('BSB', 'Ecclesiastes', 21, 10, 18, 'Through laziness the roof caves in, and in the hands of the idle, the house leaks.'),
  ('BSB', 'Ecclesiastes', 21, 10, 19, 'A feast is prepared for laughter, and wine makes life merry, but money is the answer for everything.'),
  ('BSB', 'Ecclesiastes', 21, 10, 20, 'Do not curse the king even in your thoughts, or curse the rich even in your bedroom, for a bird of the air may carry your words, and a winged creature may report your speech.'),
  ('BSB', 'Ecclesiastes', 21, 11, 1, 'Cast your bread upon the waters, for after many days you will find it again.'),
  ('BSB', 'Ecclesiastes', 21, 11, 2, 'Divide your portion among seven, or even eight, for you do not know what disaster may befall the land.'),
  ('BSB', 'Ecclesiastes', 21, 11, 3, 'If the clouds are full, they will pour out rain upon the earth; whether a tree falls to the south or to the north, in the place where it falls, there it will lie.'),
  ('BSB', 'Ecclesiastes', 21, 11, 4, 'He who watches the wind will fail to sow, and he who observes the clouds will fail to reap.'),
  ('BSB', 'Ecclesiastes', 21, 11, 5, 'As you do not know the path of the wind, or how the bones are formed in a mother’s womb, so you cannot understand the work of God, the Maker of all things.'),
  ('BSB', 'Ecclesiastes', 21, 11, 6, 'Sow your seed in the morning, and do not rest your hands in the evening, for you do not know which will succeed, whether this or that, or if both will equally prosper.'),
  ('BSB', 'Ecclesiastes', 21, 11, 7, 'Light is sweet, and it pleases the eyes to see the sun.'),
  ('BSB', 'Ecclesiastes', 21, 11, 8, 'So if a man lives many years, let him rejoice in them all. But let him remember the days of darkness, for they will be many. Everything to come is futile.'),
  ('BSB', 'Ecclesiastes', 21, 11, 9, 'Rejoice, O young man, while you are young, and let your heart be glad in the days of your youth. Walk in the ways of your heart and in the sight of your eyes, but know that for all these things God will bring you to judgment.'),
  ('BSB', 'Ecclesiastes', 21, 11, 10, 'So banish sorrow from your heart, and cast off pain from your body, for youth and vigor are fleeting.'),
  ('BSB', 'Ecclesiastes', 21, 12, 1, 'Remember your Creator in the days of your youth, before the days of adversity come and the years approach of which you will say, “I find no pleasure in them,”'),
  ('BSB', 'Ecclesiastes', 21, 12, 2, 'before the light of the sun, moon, and stars is darkened, and the clouds return after the rain,'),
  ('BSB', 'Ecclesiastes', 21, 12, 3, 'on the day the keepers of the house tremble and the strong men stoop, when those grinding cease because they are few and those watching through windows see dimly,'),
  ('BSB', 'Ecclesiastes', 21, 12, 4, 'when the doors to the street are shut and the sound of the mill fades away, when one rises at the sound of a bird and all the daughters of song grow faint,'),
  ('BSB', 'Ecclesiastes', 21, 12, 5, 'when men fear the heights and dangers of the road, when the almond tree blossoms, the grasshopper loses its spring, and the caper berry shrivels— for then man goes to his eternal home and mourners walk the streets.'),
  ('BSB', 'Ecclesiastes', 21, 12, 6, 'Remember Him before the silver cord is snapped and the golden bowl is crushed, before the pitcher is shattered at the spring and the wheel is broken at the well,'),
  ('BSB', 'Ecclesiastes', 21, 12, 7, 'before the dust returns to the ground from which it came and the spirit returns to God who gave it.'),
  ('BSB', 'Ecclesiastes', 21, 12, 8, '“Futility of futilities,” says the Teacher. “Everything is futile!”'),
  ('BSB', 'Ecclesiastes', 21, 12, 9, 'Not only was the Teacher wise, but he also taught the people knowledge; he pondered, searched out, and arranged many proverbs.'),
  ('BSB', 'Ecclesiastes', 21, 12, 10, 'The Teacher searched to find delightful sayings and to record accurate words of truth.'),
  ('BSB', 'Ecclesiastes', 21, 12, 11, 'The words of the wise are like goads, and the anthologies of the masters are like firmly embedded nails driven by a single Shepherd.'),
  ('BSB', 'Ecclesiastes', 21, 12, 12, 'And by these, my son, be further warned: There is no end to the making of many books, and much study wearies the body.'),
  ('BSB', 'Ecclesiastes', 21, 12, 13, 'When all has been heard, the conclusion of the matter is this: Fear God and keep His commandments, because this is the whole duty of man.'),
  ('BSB', 'Ecclesiastes', 21, 12, 14, 'For God will bring every deed into judgment, along with every hidden thing, whether good or evil.'),
  ('BSB', 'Song of Solomon', 22, 1, 1, 'This is Solomon’s Song of Songs.'),
  ('BSB', 'Song of Solomon', 22, 1, 2, 'Let him kiss me with the kisses of his mouth! For your love is more delightful than wine.'),
  ('BSB', 'Song of Solomon', 22, 1, 3, 'The fragrance of your perfume is pleasing; your name is like perfume poured out. No wonder the maidens adore you.'),
  ('BSB', 'Song of Solomon', 22, 1, 4, 'Take me away with you—let us hurry! May the king bring me to his chambers. We will rejoice and delight in you; we will praise your love more than wine. It is only right that they adore you.'),
  ('BSB', 'Song of Solomon', 22, 1, 5, 'I am dark, yet lovely, O daughters of Jerusalem, like the tents of Kedar, like the curtains of Solomon.'),
  ('BSB', 'Song of Solomon', 22, 1, 6, 'Do not stare because I am dark, for the sun has gazed upon me. My mother’s sons were angry with me; they made me a keeper of the vineyards, but my own vineyard I have neglected.'),
  ('BSB', 'Song of Solomon', 22, 1, 7, 'Tell me, O one I love, where do you pasture your sheep? Where do you rest them at midday? Why should I be like a veiled woman beside the flocks of your companions?'),
  ('BSB', 'Song of Solomon', 22, 1, 8, 'If you do not know, O fairest of women, follow the tracks of the flock, and graze your young goats near the tents of the shepherds.'),
  ('BSB', 'Song of Solomon', 22, 1, 9, 'I compare you, my darling, to a mare among Pharaoh’s chariots.'),
  ('BSB', 'Song of Solomon', 22, 1, 10, 'Your cheeks are beautiful with ornaments, your neck with strings of jewels.'),
  ('BSB', 'Song of Solomon', 22, 1, 11, 'We will make you ornaments of gold, studded with beads of silver.'),
  ('BSB', 'Song of Solomon', 22, 1, 12, 'While the king was at his table, my perfume spread its fragrance.'),
  ('BSB', 'Song of Solomon', 22, 1, 13, 'My beloved is to me a sachet of myrrh resting between my breasts.'),
  ('BSB', 'Song of Solomon', 22, 1, 14, 'My beloved is to me a cluster of henna blossoms in the vineyards of En-gedi.'),
  ('BSB', 'Song of Solomon', 22, 1, 15, 'How beautiful you are, my darling! Oh, how very beautiful! Your eyes are like doves.'),
  ('BSB', 'Song of Solomon', 22, 1, 16, 'How handsome you are, my beloved! Oh, how delightful! The soft grass is our bed.'),
  ('BSB', 'Song of Solomon', 22, 1, 17, 'The beams of our house are cedars; our rafters are fragrant firs.'),
  ('BSB', 'Song of Solomon', 22, 2, 1, 'I am a rose of Sharon, a lily of the valley.'),
  ('BSB', 'Song of Solomon', 22, 2, 2, 'Like a lily among the thorns is my darling among the maidens.'),
  ('BSB', 'Song of Solomon', 22, 2, 3, 'Like an apple tree among the trees of the forest is my beloved among the young men. I delight to sit in his shade, and his fruit is sweet to my taste.'),
  ('BSB', 'Song of Solomon', 22, 2, 4, 'He has brought me to the house of wine, and his banner over me is love.'),
  ('BSB', 'Song of Solomon', 22, 2, 5, 'Sustain me with raisins; refresh me with apples, for I am faint with love.'),
  ('BSB', 'Song of Solomon', 22, 2, 6, 'His left hand is under my head, and his right arm embraces me.'),
  ('BSB', 'Song of Solomon', 22, 2, 7, 'O daughters of Jerusalem, I adjure you by the gazelles and does of the field: Do not arouse or awaken love until the time is right.'),
  ('BSB', 'Song of Solomon', 22, 2, 8, 'Listen! My beloved approaches. Look! Here he comes, leaping across the mountains, bounding over the hills.'),
  ('BSB', 'Song of Solomon', 22, 2, 9, 'My beloved is like a gazelle or a young stag. Look, he stands behind our wall, gazing through the windows, peering through the lattice.'),
  ('BSB', 'Song of Solomon', 22, 2, 10, 'My beloved calls to me, “Arise, my darling. Come away with me, my beautiful one.'),
  ('BSB', 'Song of Solomon', 22, 2, 11, 'For now the winter is past; the rain is over and gone.'),
  ('BSB', 'Song of Solomon', 22, 2, 12, 'The flowers have appeared in the countryside; the season of singing has come, and the cooing of turtledoves is heard in our land.'),
  ('BSB', 'Song of Solomon', 22, 2, 13, 'The fig tree ripens its figs; the blossoming vines spread their fragrance. Arise, come away, my darling; come away with me, my beautiful one.”'),
  ('BSB', 'Song of Solomon', 22, 2, 14, 'O my dove in the clefts of the rock, in the crevices of the cliff, let me see your face, let me hear your voice; for your voice is sweet, and your countenance is lovely.'),
  ('BSB', 'Song of Solomon', 22, 2, 15, 'Catch for us the foxes— the little foxes that ruin the vineyards— for our vineyards are in bloom.'),
  ('BSB', 'Song of Solomon', 22, 2, 16, 'My beloved is mine and I am his; he pastures his flock among the lilies.'),
  ('BSB', 'Song of Solomon', 22, 2, 17, 'Before the day breaks and shadows flee, turn, my beloved, and be like a gazelle or a young stag on the mountains of Bether.'),
  ('BSB', 'Song of Solomon', 22, 3, 1, 'On my bed at night I sought the one I love; I sought him, but did not find him.'),
  ('BSB', 'Song of Solomon', 22, 3, 2, 'I will arise now and go about the city, through the streets and squares. I will seek the one I love. So I sought him but did not find him.'),
  ('BSB', 'Song of Solomon', 22, 3, 3, 'I encountered the watchmen on their rounds of the city: “Have you seen the one I love?”'),
  ('BSB', 'Song of Solomon', 22, 3, 4, 'I had just passed them when I found the one I love. I held him and would not let go until I had brought him to my mother’s house, to the chamber of the one who conceived me.'),
  ('BSB', 'Song of Solomon', 22, 3, 5, 'O daughters of Jerusalem, I adjure you by the gazelles and does of the field: Do not arouse or awaken love until the time is right.'),
  ('BSB', 'Song of Solomon', 22, 3, 6, 'Who is this coming up from the wilderness like a column of smoke, scented with myrrh and frankincense from all the spices of the merchant?'),
  ('BSB', 'Song of Solomon', 22, 3, 7, 'Behold, it is Solomon’s carriage, escorted by sixty of the mightiest men of Israel.'),
  ('BSB', 'Song of Solomon', 22, 3, 8, 'All are skilled with the sword, experienced in warfare. Each has his sword at his side prepared for the terror of the night.'),
  ('BSB', 'Song of Solomon', 22, 3, 9, 'King Solomon has made his carriage out of the timber of Lebanon.'),
  ('BSB', 'Song of Solomon', 22, 3, 10, 'He has made its posts of silver, its base of gold, its seat of purple fabric. Its interior is inlaid with love by the daughters of Jerusalem.'),
  ('BSB', 'Song of Solomon', 22, 3, 11, 'Come out, O daughters of Zion, and gaze at King Solomon, wearing the crown his mother bestowed on the day of his wedding— the day of his heart’s rejoicing.'),
  ('BSB', 'Song of Solomon', 22, 4, 1, 'How beautiful you are, my darling— how very beautiful! Your eyes are like doves behind your veil. Your hair is like a flock of goats streaming down Mount Gilead.'),
  ('BSB', 'Song of Solomon', 22, 4, 2, 'Your teeth are like a flock of newly shorn sheep coming up from the washing; each has its twin, and not one of them is lost.'),
  ('BSB', 'Song of Solomon', 22, 4, 3, 'Your lips are like a scarlet ribbon, and your mouth is lovely. Your brow behind your veil is like a slice of pomegranate.'),
  ('BSB', 'Song of Solomon', 22, 4, 4, 'Your neck is like the tower of David, built with rows of stones; on it hang a thousand shields, all of them shields of warriors.'),
  ('BSB', 'Song of Solomon', 22, 4, 5, 'Your breasts are like two fawns, twins of a gazelle grazing among the lilies.'),
  ('BSB', 'Song of Solomon', 22, 4, 6, 'Before the day breaks and the shadows flee, I will make my way to the mountain of myrrh and to the hill of frankincense.'),
  ('BSB', 'Song of Solomon', 22, 4, 7, 'You are altogether beautiful, my darling; in you there is no flaw.'),
  ('BSB', 'Song of Solomon', 22, 4, 8, 'Come with me from Lebanon, my bride, come with me from Lebanon! Descend from the peak of Amana, from the summits of Senir and Hermon, from the dens of the lions, from the mountains of the leopards.'),
  ('BSB', 'Song of Solomon', 22, 4, 9, 'You have captured my heart, my sister, my bride; you have stolen my heart with one glance of your eyes, with one jewel of your neck.'),
  ('BSB', 'Song of Solomon', 22, 4, 10, 'How delightful is your love, my sister, my bride! Your love is much better than wine, and the fragrance of your perfume than all spices.'),
  ('BSB', 'Song of Solomon', 22, 4, 11, 'Your lips, my bride, drip sweetness like the honeycomb; honey and milk are under your tongue, and the fragrance of your garments is like the aroma of Lebanon.'),
  ('BSB', 'Song of Solomon', 22, 4, 12, 'My sister, my bride, you are a garden locked up, a spring enclosed, a fountain sealed.'),
  ('BSB', 'Song of Solomon', 22, 4, 13, 'Your branches are an orchard of pomegranates with the choicest of fruits, with henna and nard,'),
  ('BSB', 'Song of Solomon', 22, 4, 14, 'with nard and saffron, with calamus and cinnamon, with every kind of frankincense tree, with myrrh and aloes, with all the finest spices.'),
  ('BSB', 'Song of Solomon', 22, 4, 15, 'You are a garden spring, a well of fresh water flowing down from Lebanon.'),
  ('BSB', 'Song of Solomon', 22, 4, 16, 'Awake, O north wind, and come, O south wind. Breathe on my garden and spread the fragrance of its spices. Let my beloved come into his garden and taste its choicest fruits.'),
  ('BSB', 'Song of Solomon', 22, 5, 1, 'I have come to my garden, my sister, my bride; I have gathered my myrrh with my spice. I have eaten my honeycomb with my honey; I have drunk my wine with my milk. Eat, O friends, and drink; drink freely, O beloved.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Song of Solomon', 22, 5, 2, 'I sleep, but my heart is awake. A sound! My beloved is knocking: “Open to me, my sister, my darling, my dove, my flawless one. My head is drenched with dew, my hair with the dampness of the night.”'),
  ('BSB', 'Song of Solomon', 22, 5, 3, 'I have taken off my robe— must I put it back on? I have washed my feet— must I soil them again?'),
  ('BSB', 'Song of Solomon', 22, 5, 4, 'My beloved put his hand to the latch; my heart pounded for him.'),
  ('BSB', 'Song of Solomon', 22, 5, 5, 'I rose up to open for my beloved. My hands dripped with myrrh, my fingers with flowing myrrh on the handles of the bolt.'),
  ('BSB', 'Song of Solomon', 22, 5, 6, 'I opened for my beloved, but he had turned and gone. My heart sank at his departure. I sought him, but did not find him. I called, but he did not answer.'),
  ('BSB', 'Song of Solomon', 22, 5, 7, 'I encountered the watchmen on their rounds of the city. They beat me and bruised me; they took away my cloak, those guardians of the walls.'),
  ('BSB', 'Song of Solomon', 22, 5, 8, 'O daughters of Jerusalem, I adjure you, if you find my beloved, tell him I am sick with love.'),
  ('BSB', 'Song of Solomon', 22, 5, 9, 'How is your beloved better than others, O most beautiful among women? How is your beloved better than another, that you charge us so?'),
  ('BSB', 'Song of Solomon', 22, 5, 10, 'My beloved is dazzling and ruddy, outstanding among ten thousand.'),
  ('BSB', 'Song of Solomon', 22, 5, 11, 'His head is purest gold; his hair is wavy and black as a raven.'),
  ('BSB', 'Song of Solomon', 22, 5, 12, 'His eyes are like doves beside the streams of water, bathed in milk and mounted like jewels.'),
  ('BSB', 'Song of Solomon', 22, 5, 13, 'His cheeks are like beds of spice, towers of perfume. His lips are like lilies, dripping with flowing myrrh.'),
  ('BSB', 'Song of Solomon', 22, 5, 14, 'His arms are rods of gold set with beryl. His body is an ivory panel bedecked with sapphires.'),
  ('BSB', 'Song of Solomon', 22, 5, 15, 'His legs are pillars of marble set on bases of pure gold. His appearance is like Lebanon, as majestic as the cedars.'),
  ('BSB', 'Song of Solomon', 22, 5, 16, 'His mouth is most sweet; he is altogether lovely. This is my beloved, and this is my friend, O daughters of Jerusalem.'),
  ('BSB', 'Song of Solomon', 22, 6, 1, 'Where has your beloved gone, O most beautiful among women? Which way has he turned? We will seek him with you.'),
  ('BSB', 'Song of Solomon', 22, 6, 2, 'My beloved has gone down to his garden, to the beds of spices, to pasture his flock in the gardens and to gather lilies.'),
  ('BSB', 'Song of Solomon', 22, 6, 3, 'I belong to my beloved and he belongs to me; he pastures his flock among the lilies.'),
  ('BSB', 'Song of Solomon', 22, 6, 4, 'You are as beautiful, my darling, as Tirzah, as lovely as Jerusalem, as majestic as troops with banners.'),
  ('BSB', 'Song of Solomon', 22, 6, 5, 'Turn your eyes away from me, for they have overcome me. Your hair is like a flock of goats streaming down from Gilead.'),
  ('BSB', 'Song of Solomon', 22, 6, 6, 'Your teeth are like a flock of sheep coming up from the washing; each has its twin, and not one of them is lost.'),
  ('BSB', 'Song of Solomon', 22, 6, 7, 'Your brow behind your veil is like a slice of pomegranate.'),
  ('BSB', 'Song of Solomon', 22, 6, 8, 'There are sixty queens and eighty concubines, and maidens without number,'),
  ('BSB', 'Song of Solomon', 22, 6, 9, 'but my dove, my perfect one, is unique, the favorite of the mother who bore her. The maidens see her and call her blessed; the queens and concubines sing her praises.'),
  ('BSB', 'Song of Solomon', 22, 6, 10, 'Who is this who shines like the dawn, as fair as the moon, as bright as the sun, as majestic as the stars in procession?'),
  ('BSB', 'Song of Solomon', 22, 6, 11, 'I went down to the walnut grove to see the blossoms of the valley, to see if the vines were budding or the pomegranates were in bloom.'),
  ('BSB', 'Song of Solomon', 22, 6, 12, 'Before I realized it, my desire had set me among the royal chariots of my people.'),
  ('BSB', 'Song of Solomon', 22, 6, 13, 'Come back, come back, O Shulammite! Come back, come back, that we may gaze upon you. Why do you look at the Shulammite, as on the dance of Mahanaim?'),
  ('BSB', 'Song of Solomon', 22, 7, 1, 'How beautiful are your sandaled feet, O daughter of the prince! The curves of your thighs are like jewels, the handiwork of a master.'),
  ('BSB', 'Song of Solomon', 22, 7, 2, 'Your navel is a rounded goblet; it never lacks blended wine. Your waist is a mound of wheat encircled by the lilies.'),
  ('BSB', 'Song of Solomon', 22, 7, 3, 'Your breasts are like two fawns, twins of a gazelle.'),
  ('BSB', 'Song of Solomon', 22, 7, 4, 'Your neck is like a tower made of ivory; your eyes are like the pools of Heshbon by the gate of Bath-rabbim; your nose is like the tower of Lebanon, facing toward Damascus.'),
  ('BSB', 'Song of Solomon', 22, 7, 5, 'Your head crowns you like Mount Carmel, the hair of your head like purple threads; the king is captured in your tresses.'),
  ('BSB', 'Song of Solomon', 22, 7, 6, 'How fair and pleasant you are, O love, with your delights!'),
  ('BSB', 'Song of Solomon', 22, 7, 7, 'Your stature is like a palm tree; your breasts are clusters of fruit.'),
  ('BSB', 'Song of Solomon', 22, 7, 8, 'I said, “I will climb the palm tree; I will take hold of its fruit.” May your breasts be like clusters of the vine, the fragrance of your breath like apples,'),
  ('BSB', 'Song of Solomon', 22, 7, 9, 'and your mouth like the finest wine. May it flow smoothly to my beloved, gliding gently over lips and teeth.'),
  ('BSB', 'Song of Solomon', 22, 7, 10, 'I belong to my beloved, and his desire is for me.'),
  ('BSB', 'Song of Solomon', 22, 7, 11, 'Come, my beloved, let us go to the countryside; let us spend the night among the wildflowers.'),
  ('BSB', 'Song of Solomon', 22, 7, 12, 'Let us go early to the vineyards to see if the vine has budded, if the blossom has opened, if the pomegranates are in bloom— there I will give you my love.'),
  ('BSB', 'Song of Solomon', 22, 7, 13, 'The mandrakes send forth a fragrance, and at our door is every delicacy, new as well as old, that I have treasured up for you, my beloved.'),
  ('BSB', 'Song of Solomon', 22, 8, 1, 'O that you were to me like a brother who nursed at my mother’s breasts! If I found you outdoors, I would kiss you, and no one would despise me.'),
  ('BSB', 'Song of Solomon', 22, 8, 2, 'I would lead you and bring you to the house of my mother who taught me. I would give you spiced wine to drink, the nectar of my pomegranates.'),
  ('BSB', 'Song of Solomon', 22, 8, 3, 'His left hand is under my head, and his right arm embraces me.'),
  ('BSB', 'Song of Solomon', 22, 8, 4, 'O daughters of Jerusalem, I adjure you: Do not arouse or awaken love until the time is right.'),
  ('BSB', 'Song of Solomon', 22, 8, 5, 'Who is this coming up from the wilderness, leaning on her beloved? I roused you under the apple tree; there your mother conceived you; there she travailed and brought you forth.'),
  ('BSB', 'Song of Solomon', 22, 8, 6, 'Set me as a seal over your heart, as a seal upon your arm. For love is as strong as death, its jealousy as unrelenting as Sheol. Its sparks are fiery flames, the fiercest blaze of all.'),
  ('BSB', 'Song of Solomon', 22, 8, 7, 'Mighty waters cannot quench love; rivers cannot sweep it away. If a man were to give all the wealth of his house for love, his offer would be utterly scorned.'),
  ('BSB', 'Song of Solomon', 22, 8, 8, 'We have a little sister, and her breasts are not yet grown. What shall we do for our sister on the day she is spoken for?'),
  ('BSB', 'Song of Solomon', 22, 8, 9, 'If she is a wall, we will build a tower of silver upon her. If she is a door, we will enclose her with panels of cedar.'),
  ('BSB', 'Song of Solomon', 22, 8, 10, 'I am a wall, and my breasts are like towers. So I have become in his eyes like one who brings peace.'),
  ('BSB', 'Song of Solomon', 22, 8, 11, 'Solomon had a vineyard in Baal-hamon. He leased it to the tenants. For its fruit, each was to bring a thousand shekels of silver.'),
  ('BSB', 'Song of Solomon', 22, 8, 12, 'But my own vineyard is mine to give; the thousand shekels are for you, O Solomon, and two hundred are for those who tend its fruit.'),
  ('BSB', 'Song of Solomon', 22, 8, 13, 'You who dwell in the gardens, my companions are listening for your voice. Let me hear it!'),
  ('BSB', 'Song of Solomon', 22, 8, 14, 'Come away, my beloved, and be like a gazelle or a young stag on the mountains of spices.'),
  ('BSB', 'Isaiah', 23, 1, 1, 'This is the vision concerning Judah and Jerusalem that Isaiah son of Amoz saw during the reigns of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah.'),
  ('BSB', 'Isaiah', 23, 1, 2, 'Listen, O heavens, and give ear, O earth, for the LORD has spoken: “I have raised children and brought them up, but they have rebelled against Me.'),
  ('BSB', 'Isaiah', 23, 1, 3, 'The ox knows its owner, and the donkey its master’s manger, but Israel does not know; My people do not understand.”'),
  ('BSB', 'Isaiah', 23, 1, 4, 'Alas, O sinful nation, a people laden with iniquity, a brood of evildoers, children of depravity! They have forsaken the LORD; they have despised the Holy One of Israel and turned their backs on Him.'),
  ('BSB', 'Isaiah', 23, 1, 5, 'Why do you want more beatings? Why do you keep rebelling? Your head has a massive wound, and your whole heart is afflicted.'),
  ('BSB', 'Isaiah', 23, 1, 6, 'From the sole of your foot to the top of your head, there is no soundness— only wounds and welts and festering sores neither cleansed nor bandaged nor soothed with oil.'),
  ('BSB', 'Isaiah', 23, 1, 7, 'Your land is desolate; your cities are burned with fire. Foreigners devour your fields before you— a desolation demolished by strangers.'),
  ('BSB', 'Isaiah', 23, 1, 8, 'And the Daughter of Zion is abandoned like a shelter in a vineyard, like a shack in a cucumber field, like a city besieged.'),
  ('BSB', 'Isaiah', 23, 1, 9, 'Unless the LORD of Hosts had left us a few survivors, we would have become like Sodom, we would have resembled Gomorrah.'),
  ('BSB', 'Isaiah', 23, 1, 10, 'Hear the word of the LORD, you rulers of Sodom; listen to the instruction of our God, you people of Gomorrah!'),
  ('BSB', 'Isaiah', 23, 1, 11, '“What good to Me is your multitude of sacrifices?” says the LORD. “I am full from the burnt offerings of rams and the fat of well-fed cattle; I take no delight in the blood of bulls and lambs and goats.'),
  ('BSB', 'Isaiah', 23, 1, 12, 'When you come to appear before Me, who has required this of you— this trampling of My courts?'),
  ('BSB', 'Isaiah', 23, 1, 13, 'Bring your worthless offerings no more; your incense is detestable to Me— your New Moons, Sabbaths, and convocations. I cannot endure iniquity in a solemn assembly.'),
  ('BSB', 'Isaiah', 23, 1, 14, 'I hate your New Moons and your appointed feasts. They have become a burden to Me; I am weary of bearing them.'),
  ('BSB', 'Isaiah', 23, 1, 15, 'When you spread out your hands in prayer, I will hide My eyes from you; even though you multiply your prayers, I will not listen. Your hands are covered with blood.'),
  ('BSB', 'Isaiah', 23, 1, 16, 'Wash and cleanse yourselves. Remove your evil deeds from My sight. Stop doing evil!'),
  ('BSB', 'Isaiah', 23, 1, 17, 'Learn to do right; seek justice and correct the oppressor. Defend the fatherless and plead the case of the widow.”'),
  ('BSB', 'Isaiah', 23, 1, 18, '“Come now, let us reason together,” says the LORD. “Though your sins are like scarlet, they will be as white as snow; though they are as red as crimson, they will become like wool.'),
  ('BSB', 'Isaiah', 23, 1, 19, 'If you are willing and obedient, you will eat the best of the land.'),
  ('BSB', 'Isaiah', 23, 1, 20, 'But if you resist and rebel, you will be devoured by the sword.” For the mouth of the LORD has spoken.'),
  ('BSB', 'Isaiah', 23, 1, 21, 'See how the faithful city has become a harlot! She once was full of justice; righteousness resided within her, but now only murderers!'),
  ('BSB', 'Isaiah', 23, 1, 22, 'Your silver has become dross; your fine wine is diluted with water.'),
  ('BSB', 'Isaiah', 23, 1, 23, 'Your rulers are rebels, friends of thieves. They all love bribes and chasing after rewards. They do not defend the fatherless, and the plea of the widow never comes before them.'),
  ('BSB', 'Isaiah', 23, 1, 24, 'Therefore the Lord GOD of Hosts, the Mighty One of Israel, declares: “Ah, I will be relieved of My foes and avenge Myself on My enemies.'),
  ('BSB', 'Isaiah', 23, 1, 25, 'I will turn My hand against you; I will thoroughly purge your dross; I will remove all your impurities.'),
  ('BSB', 'Isaiah', 23, 1, 26, 'I will restore your judges as at first, and your counselors as at the beginning. After that you will be called the City of Righteousness, the Faithful City.”'),
  ('BSB', 'Isaiah', 23, 1, 27, 'Zion will be redeemed with justice, her repentant ones with righteousness.'),
  ('BSB', 'Isaiah', 23, 1, 28, 'But rebels and sinners will together be shattered, and those who forsake the LORD will perish.'),
  ('BSB', 'Isaiah', 23, 1, 29, 'Surely you will be ashamed of the sacred oaks in which you have delighted; you will be embarrassed by the gardens that you have chosen.'),
  ('BSB', 'Isaiah', 23, 1, 30, 'For you will become like an oak whose leaves are withered, like a garden without water.'),
  ('BSB', 'Isaiah', 23, 1, 31, 'The strong man will become tinder and his work will be a spark; both will burn together, with no one to quench the flames.'),
  ('BSB', 'Isaiah', 23, 2, 1, 'This is the message that was revealed to Isaiah son of Amoz concerning Judah and Jerusalem:'),
  ('BSB', 'Isaiah', 23, 2, 2, 'In the last days the mountain of the house of the LORD will be established as the chief of the mountains; it will be raised above the hills, and all nations will stream to it.'),
  ('BSB', 'Isaiah', 23, 2, 3, 'And many peoples will come and say: “Come, let us go up to the mountain of the LORD, to the house of the God of Jacob. He will teach us His ways so that we may walk in His paths.” For the law will go forth from Zion, and the word of the LORD from Jerusalem.'),
  ('BSB', 'Isaiah', 23, 2, 4, 'Then He will judge between the nations and arbitrate for many peoples. They will beat their swords into plowshares and their spears into pruning hooks. Nation will no longer take up the sword against nation, nor train anymore for war.'),
  ('BSB', 'Isaiah', 23, 2, 5, 'Come, O house of Jacob, let us walk in the light of the LORD.'),
  ('BSB', 'Isaiah', 23, 2, 6, 'For You have abandoned Your people, the house of Jacob, because they are filled with influences from the east; they are soothsayers like the Philistines; they strike hands with the children of foreigners.'),
  ('BSB', 'Isaiah', 23, 2, 7, 'Their land is full of silver and gold, with no limit to their treasures; their land is full of horses, with no limit to their chariots.'),
  ('BSB', 'Isaiah', 23, 2, 8, 'Their land is full of idols; they bow down to the work of their hands, to what their fingers have made.'),
  ('BSB', 'Isaiah', 23, 2, 9, 'So mankind is brought low, and man is humbled— do not forgive them!'),
  ('BSB', 'Isaiah', 23, 2, 10, 'Go into the rocks and hide in the dust from the terror of the LORD and the splendor of His majesty.'),
  ('BSB', 'Isaiah', 23, 2, 11, 'The proud look of man will be humbled, and the loftiness of men brought low; the LORD alone will be exalted in that day.'),
  ('BSB', 'Isaiah', 23, 2, 12, 'For the Day of the LORD of Hosts will come against all the proud and lofty, against all that is exalted— it will be humbled—'),
  ('BSB', 'Isaiah', 23, 2, 13, 'against all the cedars of Lebanon, lofty and lifted up, against all the oaks of Bashan,'),
  ('BSB', 'Isaiah', 23, 2, 14, 'against all the tall mountains, against all the high hills,'),
  ('BSB', 'Isaiah', 23, 2, 15, 'against every high tower, against every fortified wall,'),
  ('BSB', 'Isaiah', 23, 2, 16, 'against every ship of Tarshish, and against every stately vessel.'),
  ('BSB', 'Isaiah', 23, 2, 17, 'So the pride of man will be brought low, and the loftiness of men will be humbled; the LORD alone will be exalted in that day,'),
  ('BSB', 'Isaiah', 23, 2, 18, 'and the idols will vanish completely.'),
  ('BSB', 'Isaiah', 23, 2, 19, 'Men will flee to caves in the rocks and holes in the ground, away from the terror of the LORD and from the splendor of His majesty, when He rises to shake the earth.'),
  ('BSB', 'Isaiah', 23, 2, 20, 'In that day men will cast away to the moles and bats their idols of silver and gold— the idols they made to worship.'),
  ('BSB', 'Isaiah', 23, 2, 21, 'They will flee to caverns in the rocks and crevices in the cliffs, away from the terror of the LORD and from the splendor of His majesty, when He rises to shake the earth.'),
  ('BSB', 'Isaiah', 23, 2, 22, 'Put no more trust in man, who has only the breath in his nostrils. Of what account is he?'),
  ('BSB', 'Isaiah', 23, 3, 1, 'For behold, the Lord GOD of Hosts is about to remove from Jerusalem and Judah both supply and support: the whole supply of food and water,'),
  ('BSB', 'Isaiah', 23, 3, 2, 'the mighty man and the warrior, the judge and the prophet, the soothsayer and the elder,'),
  ('BSB', 'Isaiah', 23, 3, 3, 'the commander of fifty and the dignitary, the counselor, the cunning magician, and the clever enchanter.'),
  ('BSB', 'Isaiah', 23, 3, 4, '“I will make mere lads their leaders, and children will rule over them.”'),
  ('BSB', 'Isaiah', 23, 3, 5, 'The people will oppress one another, man against man, neighbor against neighbor; the young will rise up against the old, and the base against the honorable.'),
  ('BSB', 'Isaiah', 23, 3, 6, 'A man will seize his brother within his father’s house: “You have a cloak—you be our leader! Take charge of this heap of rubble.”'),
  ('BSB', 'Isaiah', 23, 3, 7, 'On that day he will cry aloud: “I am not a healer. I have no food or clothing in my house. Do not make me leader of the people!”'),
  ('BSB', 'Isaiah', 23, 3, 8, 'For Jerusalem has stumbled and Judah has fallen because they spoke and acted against the LORD, defying His glorious presence.'),
  ('BSB', 'Isaiah', 23, 3, 9, 'The expression on their faces testifies against them, and like Sodom they flaunt their sin; they do not conceal it. Woe to them, for they have brought disaster upon themselves.'),
  ('BSB', 'Isaiah', 23, 3, 10, 'Tell the righteous it will be well with them, for they will enjoy the fruit of their labor.'),
  ('BSB', 'Isaiah', 23, 3, 11, 'Woe to the wicked; disaster is upon them! For they will be repaid with what their hands have done.'),
  ('BSB', 'Isaiah', 23, 3, 12, 'Youths oppress My people, and women rule over them. O My people, your guides mislead you; they turn you from your paths.'),
  ('BSB', 'Isaiah', 23, 3, 13, 'The LORD arises to contend; He stands to judge the people.'),
  ('BSB', 'Isaiah', 23, 3, 14, 'The LORD brings this charge against the elders and leaders of His people: “You have devoured the vineyard; the plunder of the poor is in your houses.'),
  ('BSB', 'Isaiah', 23, 3, 15, 'Why do you crush My people and grind the faces of the poor?” declares the Lord GOD of Hosts.'),
  ('BSB', 'Isaiah', 23, 3, 16, 'The LORD also says: “Because the daughters of Zion are haughty— walking with heads held high and wanton eyes, prancing and skipping as they go, jingling the bracelets on their ankles—'),
  ('BSB', 'Isaiah', 23, 3, 17, 'the Lord will bring sores on the heads of the daughters of Zion, and the LORD will make their foreheads bare.”'),
  ('BSB', 'Isaiah', 23, 3, 18, 'In that day the Lord will take away their finery: their anklets and headbands and crescents;'),
  ('BSB', 'Isaiah', 23, 3, 19, 'their pendants, bracelets, and veils;'),
  ('BSB', 'Isaiah', 23, 3, 20, 'their headdresses, ankle chains, and sashes; their perfume bottles and charms;'),
  ('BSB', 'Isaiah', 23, 3, 21, 'their signet rings and nose rings;'),
  ('BSB', 'Isaiah', 23, 3, 22, 'their festive robes, capes, cloaks, and purses;'),
  ('BSB', 'Isaiah', 23, 3, 23, 'and their mirrors, linen garments, tiaras, and shawls.'),
  ('BSB', 'Isaiah', 23, 3, 24, 'Instead of fragrance there will be a stench; instead of a belt, a rope; instead of styled hair, baldness; instead of fine clothing, sackcloth; instead of beauty, shame.'),
  ('BSB', 'Isaiah', 23, 3, 25, 'Your men will fall by the sword, and your warriors in battle.'),
  ('BSB', 'Isaiah', 23, 3, 26, 'And the gates of Zion will lament and mourn; destitute, she will sit on the ground.'),
  ('BSB', 'Isaiah', 23, 4, 1, 'In that day seven women will take hold of one man and say, “We will eat our own bread and provide our own clothes. Just let us be called by your name. Take away our disgrace!”'),
  ('BSB', 'Isaiah', 23, 4, 2, 'On that day the Branch of the LORD will be beautiful and glorious, and the fruit of the land will be the pride and glory of Israel’s survivors.'),
  ('BSB', 'Isaiah', 23, 4, 3, 'Whoever remains in Zion and whoever is left in Jerusalem will be called holy— all in Jerusalem who are recorded among the living—'),
  ('BSB', 'Isaiah', 23, 4, 4, 'when the Lord has washed away the filth of the daughters of Zion and cleansed the bloodstains from the heart of Jerusalem by a spirit of judgment and a spirit of fire.'),
  ('BSB', 'Isaiah', 23, 4, 5, 'Then the LORD will create over all of Mount Zion and over her assemblies a cloud of smoke by day and a glowing flame of fire by night. For over all the glory there will be a canopy,'),
  ('BSB', 'Isaiah', 23, 4, 6, 'a shelter to give shade from the heat by day, and a refuge and hiding place from the storm and the rain.'),
  ('BSB', 'Isaiah', 23, 5, 1, 'I will sing for my beloved a song of his vineyard: My beloved had a vineyard on a very fertile hill.'),
  ('BSB', 'Isaiah', 23, 5, 2, 'He dug it up and cleared the stones and planted the finest vines. He built a watchtower in the middle and dug out a winepress as well. He waited for the vineyard to yield good grapes, but the fruit it produced was sour!'),
  ('BSB', 'Isaiah', 23, 5, 3, '“And now, O dwellers of Jerusalem and men of Judah, I exhort you to judge between Me and My vineyard.'),
  ('BSB', 'Isaiah', 23, 5, 4, 'What more could I have done for My vineyard than I already did for it? Why, when I expected sweet grapes, did it bring forth sour fruit?'),
  ('BSB', 'Isaiah', 23, 5, 5, 'Now I will tell you what I am about to do to My vineyard: I will take away its hedge, and it will be consumed; I will tear down its wall, and it will be trampled.'),
  ('BSB', 'Isaiah', 23, 5, 6, 'I will make it a wasteland, neither pruned nor cultivated, and thorns and briers will grow up. I will command the clouds that rain shall not fall on it.”'),
  ('BSB', 'Isaiah', 23, 5, 7, 'For the vineyard of the LORD of Hosts is the house of Israel, and the men of Judah are the plant of His delight. He looked for justice, but saw bloodshed; for righteousness, but heard a cry of distress.'),
  ('BSB', 'Isaiah', 23, 5, 8, 'Woe to you who add house to house and join field to field until no place is left and you live alone in the land.'),
  ('BSB', 'Isaiah', 23, 5, 9, 'I heard the LORD of Hosts declare: “Surely many houses will become desolate, great mansions left unoccupied.'),
  ('BSB', 'Isaiah', 23, 5, 10, 'For ten acres of vineyard will yield but a bath of wine, and a homer of seed only an ephah of grain.”'),
  ('BSB', 'Isaiah', 23, 5, 11, 'Woe to those who rise early in the morning in pursuit of strong drink, who linger into the evening, to be inflamed by wine.'),
  ('BSB', 'Isaiah', 23, 5, 12, 'At their feasts are the lyre and harp, tambourines and flutes and wine. They disregard the actions of the LORD and fail to see the work of His hands.'),
  ('BSB', 'Isaiah', 23, 5, 13, 'Therefore My people will go into exile for their lack of understanding; their dignitaries are starving and their masses are parched with thirst.'),
  ('BSB', 'Isaiah', 23, 5, 14, 'Therefore Sheol enlarges its throat and opens wide its enormous jaws, and down go Zion’s nobles and masses, her revelers and carousers!'),
  ('BSB', 'Isaiah', 23, 5, 15, 'So mankind will be brought low, and each man humbled; the arrogant will lower their eyes.'),
  ('BSB', 'Isaiah', 23, 5, 16, 'But the LORD of Hosts will be exalted by His justice, and the holy God will show Himself holy in righteousness.'),
  ('BSB', 'Isaiah', 23, 5, 17, 'Lambs will graze as in their own pastures, and strangers will feed in the ruins of the wealthy.'),
  ('BSB', 'Isaiah', 23, 5, 18, 'Woe to those who draw iniquity with cords of deceit and pull sin along with cart ropes,'),
  ('BSB', 'Isaiah', 23, 5, 19, 'to those who say, “Let Him hurry and hasten His work so that we may see it! Let the plan of the Holy One of Israel come so that we may know it!”'),
  ('BSB', 'Isaiah', 23, 5, 20, 'Woe to those who call evil good and good evil, who turn darkness to light and light to darkness, who replace bitter with sweet and sweet with bitter.'),
  ('BSB', 'Isaiah', 23, 5, 21, 'Woe to those who are wise in their own eyes and clever in their own sight.'),
  ('BSB', 'Isaiah', 23, 5, 22, 'Woe to those who are heroes in drinking wine and champions in mixing strong drink,'),
  ('BSB', 'Isaiah', 23, 5, 23, 'who acquit the guilty for a bribe and deprive the innocent of justice.'),
  ('BSB', 'Isaiah', 23, 5, 24, 'Therefore, as a tongue of fire consumes the straw, and as dry grass shrivels in the flame, so their roots will decay and their blossoms will blow away like dust; for they have rejected the instruction of the LORD of Hosts and despised the word of the Holy One of Israel.'),
  ('BSB', 'Isaiah', 23, 5, 25, 'Therefore the anger of the LORD burns against His people; His hand is raised against them to strike them down. The mountains quake, and the corpses lay like refuse in the streets. Despite all this, His anger is not turned away; His hand is still upraised.'),
  ('BSB', 'Isaiah', 23, 5, 26, 'He lifts a banner for the distant nations and whistles for those at the ends of the earth. Behold—how speedily and swiftly they come!'),
  ('BSB', 'Isaiah', 23, 5, 27, 'None of them grows weary or stumbles; no one slumbers or sleeps. No belt is loose and no sandal strap is broken.'),
  ('BSB', 'Isaiah', 23, 5, 28, 'Their arrows are sharpened, and all their bows are strung. The hooves of their horses are like flint; their chariot wheels are like a whirlwind.'),
  ('BSB', 'Isaiah', 23, 5, 29, 'Their roaring is like that of a lion; they roar like young lions. They growl and seize their prey; they carry it away from deliverance.'),
  ('BSB', 'Isaiah', 23, 5, 30, 'In that day they will roar over it, like the roaring of the sea. If one looks over the land, he will see darkness and distress; even the light will be obscured by clouds.'),
  ('BSB', 'Isaiah', 23, 6, 1, 'In the year that King Uzziah died, I saw the Lord seated on a throne, high and exalted; and the train of His robe filled the temple.'),
  ('BSB', 'Isaiah', 23, 6, 2, 'Above Him stood seraphim, each having six wings: With two wings they covered their faces, with two they covered their feet, and with two they were flying.'),
  ('BSB', 'Isaiah', 23, 6, 3, 'And they were calling out to one another: “Holy, holy, holy is the LORD of Hosts; all the earth is full of His glory.”'),
  ('BSB', 'Isaiah', 23, 6, 4, 'At the sound of their voices the doorposts and thresholds shook, and the temple was filled with smoke.'),
  ('BSB', 'Isaiah', 23, 6, 5, 'Then I said: “Woe is me, for I am ruined, because I am a man of unclean lips dwelling among a people of unclean lips; for my eyes have seen the King, the LORD of Hosts.”'),
  ('BSB', 'Isaiah', 23, 6, 6, 'Then one of the seraphim flew to me, and in his hand was a glowing coal that he had taken with tongs from the altar.'),
  ('BSB', 'Isaiah', 23, 6, 7, 'And with it he touched my mouth and said: “Now that this has touched your lips, your iniquity is removed and your sin is atoned for.”'),
  ('BSB', 'Isaiah', 23, 6, 8, 'Then I heard the voice of the Lord saying: “Whom shall I send? Who will go for Us?” And I said: “Here am I. Send me!”'),
  ('BSB', 'Isaiah', 23, 6, 9, 'And He replied: “Go and tell this people, ‘Be ever hearing, but never understanding; be ever seeing, but never perceiving.’'),
  ('BSB', 'Isaiah', 23, 6, 10, 'Make the hearts of this people calloused; deafen their ears and close their eyes. Otherwise they might see with their eyes, hear with their ears, understand with their hearts, and turn and be healed.”'),
  ('BSB', 'Isaiah', 23, 6, 11, 'Then I asked: “How long, O Lord?” And He replied: “Until the cities lie ruined and without inhabitant, until the houses are left unoccupied and the land is desolate and ravaged,'),
  ('BSB', 'Isaiah', 23, 6, 12, 'until the LORD has driven men far away and the land is utterly forsaken.'),
  ('BSB', 'Isaiah', 23, 6, 13, 'And though a tenth remains in the land, it will be burned again. As the terebinth and oak leave stumps when felled, so the holy seed will be a stump in the land.”'),
  ('BSB', 'Isaiah', 23, 7, 1, 'Now in the days that Ahaz son of Jotham, the son of Uzziah, was king of Judah, Rezin king of Aram marched up to wage war against Jerusalem. He was accompanied by Pekah son of Remaliah the king of Israel, but he could not overpower the city.'),
  ('BSB', 'Isaiah', 23, 7, 2, 'When it was reported to the house of David that Aram was in league with Ephraim, the hearts of Ahaz and his people trembled like trees in the forest shaken by the wind.'),
  ('BSB', 'Isaiah', 23, 7, 3, 'Then the LORD said to Isaiah, “Go out with your son Shear-jashub to meet Ahaz at the end of the aqueduct that feeds the upper pool, on the road to the Launderer’s Field,'),
  ('BSB', 'Isaiah', 23, 7, 4, 'and say to him: Calm down and be quiet. Do not be afraid or disheartened over these two smoldering stubs of firewood—over the fierce anger of Rezin and Aram and of the son of Remaliah.'),
  ('BSB', 'Isaiah', 23, 7, 5, 'For Aram, along with Ephraim and the son of Remaliah, has plotted your ruin, saying:'),
  ('BSB', 'Isaiah', 23, 7, 6, '‘Let us invade Judah, terrorize it, and divide it among ourselves. Then we can install the son of Tabeal over it as king.’'),
  ('BSB', 'Isaiah', 23, 7, 7, 'But this is what the Lord GOD says: ‘It will not arise; it will not happen.'),
  ('BSB', 'Isaiah', 23, 7, 8, 'For the head of Aram is Damascus, and the head of Damascus is Rezin. Within sixty-five years Ephraim will be shattered as a people.'),
  ('BSB', 'Isaiah', 23, 7, 9, 'The head of Ephraim is Samaria, and the head of Samaria is the son of Remaliah. If you do not stand firm in your faith, then you will not stand at all.’”'),
  ('BSB', 'Isaiah', 23, 7, 10, 'Again the LORD spoke to Ahaz, saying,'),
  ('BSB', 'Isaiah', 23, 7, 11, '“Ask for a sign from the LORD your God, whether from the depths of Sheol or the heights of heaven.”'),
  ('BSB', 'Isaiah', 23, 7, 12, 'But Ahaz replied, “I will not ask; I will not test the LORD.”'),
  ('BSB', 'Isaiah', 23, 7, 13, 'Then Isaiah said, “Hear now, O house of David! Is it not enough to try the patience of men? Will you try the patience of my God as well?'),
  ('BSB', 'Isaiah', 23, 7, 14, 'Therefore the Lord Himself will give you a sign: Behold, the virgin will be with child and will give birth to a son, and will call Him Immanuel.'),
  ('BSB', 'Isaiah', 23, 7, 15, 'By the time He knows enough to reject evil and choose good, He will be eating curds and honey.'),
  ('BSB', 'Isaiah', 23, 7, 16, 'For before the boy knows enough to reject evil and choose good, the land of the two kings you dread will be laid waste.'),
  ('BSB', 'Isaiah', 23, 7, 17, 'The LORD will bring on you and on your people and on the house of your father a time unlike any since the day Ephraim separated from Judah—He will bring the king of Assyria.”'),
  ('BSB', 'Isaiah', 23, 7, 18, 'On that day the LORD will whistle to the flies at the farthest streams of the Nile and to the bees in the land of Assyria.'),
  ('BSB', 'Isaiah', 23, 7, 19, 'And they will all come and settle in the steep ravines and clefts of the rocks, in all the thornbushes and watering holes.'),
  ('BSB', 'Isaiah', 23, 7, 20, 'On that day the Lord will use a razor hired from beyond the Euphrates—the king of Assyria—to shave your head and the hair of your legs, and to remove your beard as well.'),
  ('BSB', 'Isaiah', 23, 7, 21, 'On that day a man will raise a young cow and two sheep,'),
  ('BSB', 'Isaiah', 23, 7, 22, 'and from the abundance of milk they give, he will eat curds; for all who remain in the land will eat curds and honey.'),
  ('BSB', 'Isaiah', 23, 7, 23, 'And on that day, in every place that had a thousand vines worth a thousand shekels of silver, only briers and thorns will be found.'),
  ('BSB', 'Isaiah', 23, 7, 24, 'Men will go there with bow and arrow, for the land will be covered with briers and thorns.'),
  ('BSB', 'Isaiah', 23, 7, 25, 'For fear of the briers and thorns, you will no longer traverse the hills once tilled by the hoe; they will become places for oxen to graze and sheep to trample.'),
  ('BSB', 'Isaiah', 23, 8, 1, 'Then the LORD said to me, “Take a large scroll and write on it with an ordinary stylus: Maher-shalal-hash-baz.'),
  ('BSB', 'Isaiah', 23, 8, 2, 'And I will appoint for Myself trustworthy witnesses—Uriah the priest and Zechariah son of Jeberekiah.”'),
  ('BSB', 'Isaiah', 23, 8, 3, 'And I had relations with the prophetess, and she conceived and gave birth to a son. The LORD said to me, “Name him Maher-shalal-hash-baz.'),
  ('BSB', 'Isaiah', 23, 8, 4, 'For before the boy knows how to cry ‘Father’ or ‘Mother,’ the wealth of Damascus and the plunder of Samaria will be carried off by the king of Assyria.”'),
  ('BSB', 'Isaiah', 23, 8, 5, 'And the LORD spoke to me further:'),
  ('BSB', 'Isaiah', 23, 8, 6, '“Because this people has rejected the gently flowing waters of Shiloah and rejoiced in Rezin and the son of Remaliah,'),
  ('BSB', 'Isaiah', 23, 8, 7, 'the Lord will surely bring against them the mighty floodwaters of the Euphrates— the king of Assyria and all his pomp. It will overflow its channels and overrun its banks.'),
  ('BSB', 'Isaiah', 23, 8, 8, 'It will pour into Judah, swirling and sweeping over it, reaching up to the neck; its spreading streams will cover your entire land, O Immanuel!'),
  ('BSB', 'Isaiah', 23, 8, 9, 'Huddle together, O peoples, and be shattered; pay attention, all you distant lands; prepare for battle, and be shattered; prepare for battle, and be shattered!'),
  ('BSB', 'Isaiah', 23, 8, 10, 'Devise a plan, but it will be thwarted; state a proposal, but it will not happen. For God is with us.”'),
  ('BSB', 'Isaiah', 23, 8, 11, 'For this is what the LORD has spoken to me with a strong hand, instructing me not to walk in the way of this people:'),
  ('BSB', 'Isaiah', 23, 8, 12, '“Do not call conspiracy everything these people regard as conspiracy. Do not fear what they fear; do not live in dread.'),
  ('BSB', 'Isaiah', 23, 8, 13, 'The LORD of Hosts is the One you shall regard as holy. Only He should be feared; only He should be dreaded.'),
  ('BSB', 'Isaiah', 23, 8, 14, 'And He will be a sanctuary— but to both houses of Israel a stone of stumbling and a rock of offense, to the dwellers of Jerusalem a trap and a snare.'),
  ('BSB', 'Isaiah', 23, 8, 15, 'Many will stumble over these; they will fall and be broken; they will be ensnared and captured.”'),
  ('BSB', 'Isaiah', 23, 8, 16, 'Bind up the testimony and seal the law among my disciples.'),
  ('BSB', 'Isaiah', 23, 8, 17, 'I will wait for the LORD, who is hiding His face from the house of Jacob. I will put my trust in Him.'),
  ('BSB', 'Isaiah', 23, 8, 18, 'Here am I, and the children the LORD has given me as signs and symbols in Israel from the LORD of Hosts, who dwells on Mount Zion.'),
  ('BSB', 'Isaiah', 23, 8, 19, 'When men tell you to consult the spirits of the dead and the spiritists who whisper and mutter, shouldn’t a people consult their God instead? Why consult the dead on behalf of the living?'),
  ('BSB', 'Isaiah', 23, 8, 20, 'To the law and to the testimony! If they do not speak according to this word, they have no light of dawn.'),
  ('BSB', 'Isaiah', 23, 8, 21, 'They will roam the land, dejected and hungry. When they are famished, they will become enraged; and looking upward, they will curse their king and their God.'),
  ('BSB', 'Isaiah', 23, 8, 22, 'Then they will look to the earth and see only distress and darkness and the gloom of anguish. And they will be driven into utter darkness.'),
  ('BSB', 'Isaiah', 23, 9, 1, 'Nevertheless, there will be no more gloom for those in distress. In the past He humbled the land of Zebulun and the land of Naphtali, but in the future He will honor the Way of the Sea, beyond the Jordan, Galilee of the nations:'),
  ('BSB', 'Isaiah', 23, 9, 2, 'The people walking in darkness have seen a great light; on those living in the land of the shadow of death, a light has dawned.'),
  ('BSB', 'Isaiah', 23, 9, 3, 'You have enlarged the nation and increased its joy. The people rejoice before You as they rejoice at harvest time, as men rejoice in dividing the plunder.'),
  ('BSB', 'Isaiah', 23, 9, 4, 'For as in the day of Midian You have shattered the yoke of their burden, the bar across their shoulders, and the rod of their oppressor.'),
  ('BSB', 'Isaiah', 23, 9, 5, 'For every trampling boot of battle and every garment rolled in blood will be burned as fuel for the fire.'),
  ('BSB', 'Isaiah', 23, 9, 6, 'For unto us a child is born, unto us a son is given, and the government will be upon His shoulders. And He will be called Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace.'),
  ('BSB', 'Isaiah', 23, 9, 7, 'Of the increase of His government and peace there will be no end. He will reign on the throne of David and over his kingdom, to establish and sustain it with justice and righteousness from that time and forevermore. The zeal of the LORD of Hosts will accomplish this.'),
  ('BSB', 'Isaiah', 23, 9, 8, 'The Lord has sent a message against Jacob, and it has fallen upon Israel.'),
  ('BSB', 'Isaiah', 23, 9, 9, 'All the people will know it— Ephraim and the dwellers of Samaria. With pride and arrogance of heart they will say:'),
  ('BSB', 'Isaiah', 23, 9, 10, '“The bricks have fallen, but we will rebuild with finished stone; the sycamores have been felled, but we will replace them with cedars.”'),
  ('BSB', 'Isaiah', 23, 9, 11, 'The LORD has raised up the foes of Rezin against him and joined his enemies together.'),
  ('BSB', 'Isaiah', 23, 9, 12, 'Aram from the east and Philistia from the west have devoured Israel with open mouths. Despite all this, His anger is not turned away; His hand is still upraised.'),
  ('BSB', 'Isaiah', 23, 9, 13, 'But the people did not return to Him who struck them; they did not seek the LORD of Hosts.'),
  ('BSB', 'Isaiah', 23, 9, 14, 'So the LORD will cut off Israel’s head and tail, both palm branch and reed in a single day.'),
  ('BSB', 'Isaiah', 23, 9, 15, 'The head is the elder and honorable man, and the tail is the prophet who teaches lies.'),
  ('BSB', 'Isaiah', 23, 9, 16, 'For those who guide this people mislead them, and those they mislead are swallowed up.'),
  ('BSB', 'Isaiah', 23, 9, 17, 'Therefore the Lord takes no pleasure in their young men; He has no compassion on their fatherless and widows. For every one of them is godless and wicked, and every mouth speaks folly. Despite all this, His anger is not turned away; His hand is still upraised.'),
  ('BSB', 'Isaiah', 23, 9, 18, 'For wickedness burns like a fire that consumes the thorns and briers and kindles the forest thickets which roll upward in billows of smoke.'),
  ('BSB', 'Isaiah', 23, 9, 19, 'By the wrath of the LORD of Hosts the land is scorched, and the people are fuel for the fire. No man even spares his brother.'),
  ('BSB', 'Isaiah', 23, 9, 20, 'They carve out what is on the right, but they are still hungry; they eat what is on the left, but they are still not satisfied. Each one devours the flesh of his own offspring.'),
  ('BSB', 'Isaiah', 23, 9, 21, 'Manasseh devours Ephraim, and Ephraim Manasseh; together they turn against Judah. Despite all this, His anger is not turned away; His hand is still upraised.'),
  ('BSB', 'Isaiah', 23, 10, 1, 'Woe to those who enact unjust statutes and issue oppressive decrees,'),
  ('BSB', 'Isaiah', 23, 10, 2, 'to deprive the poor of fair treatment and withhold justice from the oppressed of My people, to make widows their prey and orphans their plunder.'),
  ('BSB', 'Isaiah', 23, 10, 3, 'What will you do on the day of reckoning when devastation comes from afar? To whom will you flee for help? Where will you leave your wealth?'),
  ('BSB', 'Isaiah', 23, 10, 4, 'Nothing will remain but to crouch among the captives or fall among the slain. Despite all this, His anger is not turned away; His hand is still upraised.'),
  ('BSB', 'Isaiah', 23, 10, 5, 'Woe to Assyria, the rod of My anger; the staff in their hands is My wrath.'),
  ('BSB', 'Isaiah', 23, 10, 6, 'I will send him against a godless nation; I will dispatch him against a people destined for My rage, to take spoils and seize plunder, and to trample them down like clay in the streets.'),
  ('BSB', 'Isaiah', 23, 10, 7, 'But this is not his intention; this is not his plan. For it is in his heart to destroy and cut off many nations.'),
  ('BSB', 'Isaiah', 23, 10, 8, '“Are not all my commanders kings?” he says.'),
  ('BSB', 'Isaiah', 23, 10, 9, '“Is not Calno like Carchemish? Is not Hamath like Arpad? Is not Samaria like Damascus?'),
  ('BSB', 'Isaiah', 23, 10, 10, 'As my hand seized the idolatrous kingdoms whose images surpassed those of Jerusalem and Samaria,'),
  ('BSB', 'Isaiah', 23, 10, 11, 'and as I have done to Samaria and its idols, will I not also do to Jerusalem and her idols?”'),
  ('BSB', 'Isaiah', 23, 10, 12, 'So when the Lord has completed all His work against Mount Zion and Jerusalem, He will say, “I will punish the king of Assyria for the fruit of his arrogant heart and the proud look in his eyes.'),
  ('BSB', 'Isaiah', 23, 10, 13, 'For he says: ‘By the strength of my hand I have done this, and by my wisdom, for I am clever. I have removed the boundaries of nations and plundered their treasures; like a mighty one I subdued their rulers.'),
  ('BSB', 'Isaiah', 23, 10, 14, 'My hand reached as into a nest to seize the wealth of the nations. Like one gathering abandoned eggs, I gathered all the earth. No wing fluttered, no beak opened or chirped.’”'),
  ('BSB', 'Isaiah', 23, 10, 15, 'Does an axe raise itself above the one who swings it? Does a saw boast over him who saws with it? It would be like a rod waving the one who lifts it, or a staff lifting him who is not wood!'),
  ('BSB', 'Isaiah', 23, 10, 16, 'Therefore the Lord GOD of Hosts will send a wasting disease among Assyria’s stout warriors, and under his pomp will be kindled a fire like a burning flame.'),
  ('BSB', 'Isaiah', 23, 10, 17, 'And the Light of Israel will become a fire, and its Holy One a flame. In a single day it will burn and devour Assyria’s thorns and thistles.'),
  ('BSB', 'Isaiah', 23, 10, 18, 'The splendor of its forests and orchards, both soul and body, it will completely destroy, as a sickness consumes a man.'),
  ('BSB', 'Isaiah', 23, 10, 19, 'The remaining trees of its forests will be so few that a child could count them.'),
  ('BSB', 'Isaiah', 23, 10, 20, 'On that day the remnant of Israel and the survivors of the house of Jacob will no longer depend on him who struck them, but they will truly rely on the LORD, the Holy One of Israel.'),
  ('BSB', 'Isaiah', 23, 10, 21, 'A remnant will return—a remnant of Jacob— to the Mighty God.'),
  ('BSB', 'Isaiah', 23, 10, 22, 'Though your people, O Israel, be like the sand of the sea, only a remnant will return. Destruction has been decreed, overflowing with righteousness.'),
  ('BSB', 'Isaiah', 23, 10, 23, 'For the Lord GOD of Hosts will carry out the destruction decreed upon the whole land.'),
  ('BSB', 'Isaiah', 23, 10, 24, 'Therefore this is what the Lord GOD of Hosts says: “O My people who dwell in Zion, do not fear Assyria, who strikes you with a rod and lifts his staff against you as the Egyptians did.'),
  ('BSB', 'Isaiah', 23, 10, 25, 'For in just a little while My fury against you will subside, and My anger will turn to their destruction.”'),
  ('BSB', 'Isaiah', 23, 10, 26, 'And the LORD of Hosts will brandish a whip against them, as when He struck Midian at the rock of Oreb. He will raise His staff over the sea, as He did in Egypt.'),
  ('BSB', 'Isaiah', 23, 10, 27, 'On that day the burden will be lifted from your shoulders, and the yoke from your neck. The yoke will be broken because your neck will be too large.'),
  ('BSB', 'Isaiah', 23, 10, 28, 'Assyria has entered Aiath and passed through Migron, storing their supplies at Michmash.'),
  ('BSB', 'Isaiah', 23, 10, 29, 'They have crossed at the ford: “We will spend the night at Geba.” Ramah trembles; Gibeah of Saul flees.'),
  ('BSB', 'Isaiah', 23, 10, 30, 'Cry aloud, O Daughter of Gallim! Listen, O Laishah! O wretched Anathoth!'),
  ('BSB', 'Isaiah', 23, 10, 31, 'Madmenah flees; the people of Gebim take refuge.'),
  ('BSB', 'Isaiah', 23, 10, 32, 'Yet today they will halt at Nob, shaking a fist at the mount of Daughter Zion, at the hill of Jerusalem.'),
  ('BSB', 'Isaiah', 23, 10, 33, 'Behold, the Lord GOD of Hosts will lop off the branches with terrifying power. The tall trees will be cut down, the lofty ones will be felled.'),
  ('BSB', 'Isaiah', 23, 10, 34, 'He will clear the forest thickets with an axe, and Lebanon will fall before the Mighty One.'),
  ('BSB', 'Isaiah', 23, 11, 1, 'Then a shoot will spring up from the stump of Jesse, and a Branch from his roots will bear fruit.'),
  ('BSB', 'Isaiah', 23, 11, 2, 'The Spirit of the LORD will rest on Him— the Spirit of wisdom and understanding, the Spirit of counsel and strength, the Spirit of knowledge and fear of the LORD.'),
  ('BSB', 'Isaiah', 23, 11, 3, 'And He will delight in the fear of the LORD. He will not judge by what His eyes see, and He will not decide by what His ears hear,'),
  ('BSB', 'Isaiah', 23, 11, 4, 'but with righteousness He will judge the poor, and with equity He will decide for the lowly of the earth. He will strike the earth with the rod of His mouth and slay the wicked with the breath of His lips.'),
  ('BSB', 'Isaiah', 23, 11, 5, 'Righteousness will be the belt around His hips, and faithfulness the sash around His waist.'),
  ('BSB', 'Isaiah', 23, 11, 6, 'The wolf will live with the lamb, and the leopard will lie down with the goat; the calf and young lion and fatling will be together, and a little child will lead them.'),
  ('BSB', 'Isaiah', 23, 11, 7, 'The cow will graze with the bear, their young will lie down together, and the lion will eat straw like the ox.'),
  ('BSB', 'Isaiah', 23, 11, 8, 'The infant will play by the cobra’s den, and the toddler will reach into the viper’s nest.'),
  ('BSB', 'Isaiah', 23, 11, 9, 'They will neither harm nor destroy on all My holy mountain, for the earth will be full of the knowledge of the LORD as the sea is full of water.'),
  ('BSB', 'Isaiah', 23, 11, 10, 'On that day the Root of Jesse will stand as a banner for the peoples. The nations will seek Him, and His place of rest will be glorious.'),
  ('BSB', 'Isaiah', 23, 11, 11, 'On that day the Lord will extend His hand a second time to recover the remnant of His people from Assyria, from Egypt, from Pathros, from Cush, from Elam, from Shinar, from Hamath, and from the islands of the sea.'),
  ('BSB', 'Isaiah', 23, 11, 12, 'He will raise a banner for the nations and gather the exiles of Israel; He will collect the scattered of Judah from the four corners of the earth.'),
  ('BSB', 'Isaiah', 23, 11, 13, 'Then the jealousy of Ephraim will depart, and the adversaries of Judah will be cut off. Ephraim will no longer envy Judah, nor will Judah harass Ephraim.'),
  ('BSB', 'Isaiah', 23, 11, 14, 'They will swoop down on the slopes of the Philistines to the west; together they will plunder the sons of the east. They will lay their hands on Edom and Moab, and the Ammonites will be subject to them.'),
  ('BSB', 'Isaiah', 23, 11, 15, 'The LORD will devote to destruction the gulf of the Sea of Egypt; with a scorching wind He will sweep His hand over the Euphrates. He will split it into seven streams for men to cross with dry sandals.'),
  ('BSB', 'Isaiah', 23, 11, 16, 'There will be a highway for the remnant of His people who remain from Assyria, as there was for Israel when they came up from the land of Egypt.'),
  ('BSB', 'Isaiah', 23, 12, 1, 'In that day you will say: “O LORD, I will praise You. Although You were angry with me, Your anger has turned away, and You have comforted me.'),
  ('BSB', 'Isaiah', 23, 12, 2, 'Surely God is my salvation; I will trust and not be afraid. For the LORD GOD is my strength and my song, and He also has become my salvation.”'),
  ('BSB', 'Isaiah', 23, 12, 3, 'With joy you will draw water from the springs of salvation,'),
  ('BSB', 'Isaiah', 23, 12, 4, 'and on that day you will say: “Give praise to the LORD; proclaim His name! Make His works known among the peoples; declare that His name is exalted.'),
  ('BSB', 'Isaiah', 23, 12, 5, 'Sing to the LORD, for He has done glorious things. Let this be known in all the earth.'),
  ('BSB', 'Isaiah', 23, 12, 6, 'Cry out and sing, O citizen of Zion, for great among you is the Holy One of Israel.”'),
  ('BSB', 'Isaiah', 23, 13, 1, 'This is the burden against Babylon that Isaiah son of Amoz received:'),
  ('BSB', 'Isaiah', 23, 13, 2, 'Raise a banner on a barren hilltop; call aloud to them. Wave your hand, that they may enter the gates of the nobles.'),
  ('BSB', 'Isaiah', 23, 13, 3, 'I have commanded My sanctified ones; I have even summoned My warriors to execute My wrath and exult in My triumph.'),
  ('BSB', 'Isaiah', 23, 13, 4, 'Listen, a tumult on the mountains, like that of a great multitude! Listen, an uproar among the kingdoms, like nations gathered together! The LORD of Hosts is mobilizing an army for war.'),
  ('BSB', 'Isaiah', 23, 13, 5, 'They are coming from faraway lands, from the ends of the heavens— the LORD and the weapons of His wrath— to destroy the whole country.'),
  ('BSB', 'Isaiah', 23, 13, 6, 'Wail, for the Day of the LORD is near; it will come as destruction from the Almighty.'),
  ('BSB', 'Isaiah', 23, 13, 7, 'Therefore all hands will fall limp, and every man’s heart will melt.'),
  ('BSB', 'Isaiah', 23, 13, 8, 'Terror, pain, and anguish will seize them; they will writhe like a woman in labor. They will look at one another, their faces flushed with fear.'),
  ('BSB', 'Isaiah', 23, 13, 9, 'Behold, the Day of the LORD is coming— cruel, with fury and burning anger— to make the earth a desolation and to destroy the sinners within it.'),
  ('BSB', 'Isaiah', 23, 13, 10, 'For the stars of heaven and their constellations will not give their light. The rising sun will be darkened, and the moon will not give its light.'),
  ('BSB', 'Isaiah', 23, 13, 11, 'I will punish the world for its evil and the wicked for their iniquity. I will end the haughtiness of the arrogant and lay low the pride of the ruthless.'),
  ('BSB', 'Isaiah', 23, 13, 12, 'I will make man scarcer than pure gold, and mankind rarer than the gold of Ophir.'),
  ('BSB', 'Isaiah', 23, 13, 13, 'Therefore I will make the heavens tremble, and the earth will be shaken from its place at the wrath of the LORD of Hosts on the day of His burning anger.'),
  ('BSB', 'Isaiah', 23, 13, 14, 'Like a hunted gazelle, like a sheep without a shepherd, each will return to his own people, each will flee to his native land.'),
  ('BSB', 'Isaiah', 23, 13, 15, 'Whoever is caught will be stabbed, and whoever is captured will die by the sword.'),
  ('BSB', 'Isaiah', 23, 13, 16, 'Their infants will be dashed to pieces before their eyes, their houses will be looted, and their wives will be ravished.'),
  ('BSB', 'Isaiah', 23, 13, 17, 'Behold, I will stir up against them the Medes, who have no regard for silver and no desire for gold.'),
  ('BSB', 'Isaiah', 23, 13, 18, 'Their bows will dash young men to pieces; they will have no mercy on the fruit of the womb; they will not look with pity on the children.'),
  ('BSB', 'Isaiah', 23, 13, 19, 'And Babylon, the jewel of the kingdoms, the glory of the pride of the Chaldeans, will be overthrown by God like Sodom and Gomorrah.'),
  ('BSB', 'Isaiah', 23, 13, 20, 'She will never be inhabited or settled from generation to generation; no nomad will pitch his tent there, no shepherd will rest his flock there.'),
  ('BSB', 'Isaiah', 23, 13, 21, 'But desert creatures will lie down there, and howling creatures will fill her houses. Ostriches will dwell there, and wild goats will leap about.'),
  ('BSB', 'Isaiah', 23, 13, 22, 'Hyenas will howl in her fortresses and jackals in her luxurious palaces. Babylon’s time is at hand, and her days will not be prolonged.'),
  ('BSB', 'Isaiah', 23, 14, 1, 'For the LORD will have compassion on Jacob; once again He will choose Israel and settle them in their own land. The foreigner will join them and unite with the house of Jacob.'),
  ('BSB', 'Isaiah', 23, 14, 2, 'The nations will escort Israel and bring it to its homeland. Then the house of Israel will possess the nations as menservants and maidservants in the LORD’s land. They will make captives of their captors and rule over their oppressors.'),
  ('BSB', 'Isaiah', 23, 14, 3, 'On the day that the LORD gives you rest from your pain and torment, and from the hard labor into which you were forced,'),
  ('BSB', 'Isaiah', 23, 14, 4, 'you will sing this song of contempt against the king of Babylon: How the oppressor has ceased, and how his fury has ended!'),
  ('BSB', 'Isaiah', 23, 14, 5, 'The LORD has broken the staff of the wicked, the scepter of the rulers.'),
  ('BSB', 'Isaiah', 23, 14, 6, 'It struck the peoples in anger with unceasing blows; it subdued the nations in rage with relentless persecution.'),
  ('BSB', 'Isaiah', 23, 14, 7, 'All the earth is at peace and at rest; they break out in song.'),
  ('BSB', 'Isaiah', 23, 14, 8, 'Even the cypresses and cedars of Lebanon exult over you: “Since you have been laid low, no woodcutter comes against us.”'),
  ('BSB', 'Isaiah', 23, 14, 9, 'Sheol beneath is eager to meet you upon your arrival. It stirs the spirits of the dead to greet you— all the rulers of the earth. It makes all the kings of the nations rise from their thrones.'),
  ('BSB', 'Isaiah', 23, 14, 10, 'They will all respond to you, saying, “You too have become weak, as we are; you have become like us!”'),
  ('BSB', 'Isaiah', 23, 14, 11, 'Your pomp has been brought down to Sheol, along with the music of your harps. Maggots are your bed and worms your blanket.'),
  ('BSB', 'Isaiah', 23, 14, 12, 'How you have fallen from heaven, O day star, son of the dawn! You have been cut down to the ground, O destroyer of nations.'),
  ('BSB', 'Isaiah', 23, 14, 13, 'You said in your heart: “I will ascend to the heavens; I will raise my throne above the stars of God. I will sit on the mount of assembly, in the far reaches of the north.'),
  ('BSB', 'Isaiah', 23, 14, 14, 'I will ascend above the tops of the clouds; I will make myself like the Most High.”'),
  ('BSB', 'Isaiah', 23, 14, 15, 'But you will be brought down to Sheol, to the lowest depths of the Pit.'),
  ('BSB', 'Isaiah', 23, 14, 16, 'Those who see you will stare; they will ponder your fate: “Is this the man who shook the earth and made the kingdoms tremble,'),
  ('BSB', 'Isaiah', 23, 14, 17, 'who turned the world into a desert and destroyed its cities, who refused to let the captives return to their homes?”'),
  ('BSB', 'Isaiah', 23, 14, 18, 'All the kings of the nations lie in state, each in his own tomb.'),
  ('BSB', 'Isaiah', 23, 14, 19, 'But you are cast out of your grave like a rejected branch, covered by those slain with the sword, and dumped into a rocky pit like a carcass trampled underfoot.'),
  ('BSB', 'Isaiah', 23, 14, 20, 'You will not join them in burial, since you have destroyed your land and slaughtered your own people. The offspring of the wicked will never again be mentioned.'),
  ('BSB', 'Isaiah', 23, 14, 21, 'Prepare a place to slaughter his sons for the iniquities of their forefathers. They will never rise up to possess a land or cover the earth with their cities.'),
  ('BSB', 'Isaiah', 23, 14, 22, '“I will rise up against them,” declares the LORD of Hosts. “I will cut off from Babylon her name and her remnant, her offspring and her posterity,” declares the LORD.'),
  ('BSB', 'Isaiah', 23, 14, 23, '“I will make her a place for owls and for swamplands; I will sweep her away with the broom of destruction,” declares the LORD of Hosts.'),
  ('BSB', 'Isaiah', 23, 14, 24, 'The LORD of Hosts has sworn: “Surely, as I have planned, so will it be; as I have purposed, so will it stand.'),
  ('BSB', 'Isaiah', 23, 14, 25, 'I will break Assyria in My land; I will trample him on My mountain. His yoke will be taken off My people, and his burden removed from their shoulders.”'),
  ('BSB', 'Isaiah', 23, 14, 26, 'This is the plan devised for the whole earth, and this is the hand stretched out over all the nations.'),
  ('BSB', 'Isaiah', 23, 14, 27, 'The LORD of Hosts has purposed, and who can thwart Him? His hand is outstretched, so who can turn it back?'),
  ('BSB', 'Isaiah', 23, 14, 28, 'In the year that King Ahaz died, this burden was received:'),
  ('BSB', 'Isaiah', 23, 14, 29, 'Do not rejoice, all you Philistines, that the rod that struck you is broken. For a viper will spring from the root of the snake, and a flying serpent from its egg.'),
  ('BSB', 'Isaiah', 23, 14, 30, 'Then the firstborn of the poor will find pasture, and the needy will lie down in safety, but I will kill your root by famine, and your remnant will be slain.'),
  ('BSB', 'Isaiah', 23, 14, 31, 'Wail, O gate! Cry out, O city! Melt away, all you Philistines! For a cloud of smoke comes from the north, and there are no stragglers in its ranks.'),
  ('BSB', 'Isaiah', 23, 14, 32, 'What answer will be given to the envoys of that nation? “The LORD has founded Zion, where His afflicted people will find refuge.”'),
  ('BSB', 'Isaiah', 23, 15, 1, 'This is the burden against Moab: Ar in Moab is ruined, destroyed in a night! Kir in Moab is devastated, destroyed in a night!'),
  ('BSB', 'Isaiah', 23, 15, 2, 'Dibon goes up to its temple to weep at its high places. Moab wails over Nebo, as well as over Medeba. Every head is shaved, every beard is cut off.'),
  ('BSB', 'Isaiah', 23, 15, 3, 'In its streets they wear sackcloth; on the rooftops and in the public squares they all wail, falling down weeping.'),
  ('BSB', 'Isaiah', 23, 15, 4, 'Heshbon and Elealeh cry out; their voices are heard as far as Jahaz. Therefore the soldiers of Moab cry out; their souls tremble within.'),
  ('BSB', 'Isaiah', 23, 15, 5, 'My heart cries out over Moab; her fugitives flee as far as Zoar, as far as Eglath-shelishiyah. With weeping they ascend the slope of Luhith; they lament their destruction on the road to Horonaim.'),
  ('BSB', 'Isaiah', 23, 15, 6, 'The waters of Nimrim are dried up, and the grass is withered; the vegetation is gone, and the greenery is no more.'),
  ('BSB', 'Isaiah', 23, 15, 7, 'So they carry their wealth and belongings over the Brook of the Willows.'),
  ('BSB', 'Isaiah', 23, 15, 8, 'For their outcry echoes to the border of Moab. Their wailing reaches Eglaim; it is heard in Beer-elim.'),
  ('BSB', 'Isaiah', 23, 15, 9, 'The waters of Dimon are full of blood, but I will bring more upon Dimon— a lion upon the fugitives of Moab and upon the remnant of the land.'),
  ('BSB', 'Isaiah', 23, 16, 1, 'Send the tribute lambs to the ruler of the land, from Sela in the desert to the mount of Daughter Zion.'),
  ('BSB', 'Isaiah', 23, 16, 2, 'Like fluttering birds pushed out of the nest, so are the daughters of Moab at the fords of the Arnon:'),
  ('BSB', 'Isaiah', 23, 16, 3, '“Give us counsel; render a decision. Shelter us at noonday with shade as dark as night. Hide the refugees; do not betray the one who flees.'),
  ('BSB', 'Isaiah', 23, 16, 4, 'Let my fugitives stay with you; be a refuge for Moab from the destroyer.” When the oppressor has gone, destruction has ceased, and the oppressors have vanished from the land,'),
  ('BSB', 'Isaiah', 23, 16, 5, 'in loving devotion a throne will be established in the tent of David. A judge seeking justice and hastening righteousness will sit on it in faithfulness.'),
  ('BSB', 'Isaiah', 23, 16, 6, 'We have heard of Moab’s pomposity, his exceeding pride and conceit, his overflowing arrogance. But his boasting is empty.'),
  ('BSB', 'Isaiah', 23, 16, 7, 'Therefore let Moab wail; let them wail together for Moab. Moan for the raisin cakes of Kir-hareseth, you who are utterly stricken.'),
  ('BSB', 'Isaiah', 23, 16, 8, 'For the fields of Heshbon have withered, along with the grapevines of Sibmah. The rulers of the nations have trampled its choicest vines, which had reached as far as Jazer and spread toward the desert. Their shoots had spread out and passed over the sea.'),
  ('BSB', 'Isaiah', 23, 16, 9, 'So I weep with Jazer for the vines of Sibmah; I drench Heshbon and Elealeh with my tears. Triumphant shouts have fallen silent over your summer fruit and your harvest.'),
  ('BSB', 'Isaiah', 23, 16, 10, 'Joy and gladness are removed from the orchard; no one sings or shouts in the vineyards. No one tramples the grapes in the winepresses; I have put an end to the cheering.'),
  ('BSB', 'Isaiah', 23, 16, 11, 'Therefore my heart laments for Moab like a harp, my inmost being for Kir-heres.'),
  ('BSB', 'Isaiah', 23, 16, 12, 'When Moab appears on the high place, when he wearies himself and enters his sanctuary to pray, it will do him no good.'),
  ('BSB', 'Isaiah', 23, 16, 13, 'This is the message that the LORD spoke earlier concerning Moab.'),
  ('BSB', 'Isaiah', 23, 16, 14, 'And now the LORD says, “In three years, as a hired worker counts the years, Moab’s splendor will become an object of contempt, with all her many people. And those who are left will be few and feeble.”'),
  ('BSB', 'Isaiah', 23, 17, 1, 'This is the burden against Damascus: “Behold, Damascus is no longer a city; it has become a heap of ruins.'),
  ('BSB', 'Isaiah', 23, 17, 2, 'The cities of Aroer are forsaken; they will be left to the flocks, which will lie down with no one to fear.'),
  ('BSB', 'Isaiah', 23, 17, 3, 'The fortress will disappear from Ephraim, and the sovereignty from Damascus. The remnant of Aram will be like the splendor of the Israelites,” declares the LORD of Hosts.'),
  ('BSB', 'Isaiah', 23, 17, 4, '“In that day the splendor of Jacob will fade, and the fat of his body will waste away,'),
  ('BSB', 'Isaiah', 23, 17, 5, 'as the reaper gathers the standing grain and harvests the ears with his arm, as one gleans heads of grain in the Valley of Rephaim.'),
  ('BSB', 'Isaiah', 23, 17, 6, 'Yet gleanings will remain, like an olive tree that has been beaten— two or three berries atop the tree, four or five on its fruitful branches,” declares the LORD, the God of Israel.'),
  ('BSB', 'Isaiah', 23, 17, 7, 'In that day men will look to their Maker and turn their eyes to the Holy One of Israel.'),
  ('BSB', 'Isaiah', 23, 17, 8, 'They will not look to the altars they have fashioned with their hands or to the Asherahs and incense altars they have made with their fingers.'),
  ('BSB', 'Isaiah', 23, 17, 9, 'In that day their strong cities will be like forsaken thickets and summits, abandoned to the Israelites and to utter desolation.'),
  ('BSB', 'Isaiah', 23, 17, 10, 'For you have forgotten the God of your salvation and failed to remember the Rock of your refuge. Therefore, though you cultivate delightful plots and set out cuttings from exotic vines—'),
  ('BSB', 'Isaiah', 23, 17, 11, 'though on the day you plant you make them grow, and on that morning you help your seed sprout— yet the harvest will vanish on the day of disease and incurable pain.'),
  ('BSB', 'Isaiah', 23, 17, 12, 'Alas, the tumult of many peoples; they rage like the roaring seas and clamoring nations; they rumble like the crashing of mighty waters.'),
  ('BSB', 'Isaiah', 23, 17, 13, 'The nations rage like the rush of many waters. He rebukes them, and they flee far away, driven before the wind like chaff on the hills, like tumbleweeds before a gale.'),
  ('BSB', 'Isaiah', 23, 17, 14, 'In the evening, there is sudden terror! Before morning, they are no more! This is the portion of those who loot us and the lot of those who plunder us.'),
  ('BSB', 'Isaiah', 23, 18, 1, 'Woe to the land of whirring wings, along the rivers of Cush,'),
  ('BSB', 'Isaiah', 23, 18, 2, 'which sends couriers by sea, in papyrus vessels on the waters. Go, swift messengers, to a people tall and smooth-skinned, to a people widely feared, to a powerful nation of strange speech, whose land is divided by rivers.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Isaiah', 23, 18, 3, 'All you people of the world and dwellers of the earth, when a banner is raised on the mountains, you will see it; when a ram’s horn sounds, you will hear it.'),
  ('BSB', 'Isaiah', 23, 18, 4, 'For this is what the LORD has told me: “I will quietly look on from My dwelling place, like shimmering heat in the sunshine, like a cloud of dew in the heat of harvest.”'),
  ('BSB', 'Isaiah', 23, 18, 5, 'For before the harvest, when the blossom is gone and the flower becomes a ripening grape, He will cut off the shoots with a pruning knife and remove and discard the branches.'),
  ('BSB', 'Isaiah', 23, 18, 6, 'They will all be left to the mountain birds of prey, and to the beasts of the land. The birds will feed on them in summer, and all the wild animals in winter.'),
  ('BSB', 'Isaiah', 23, 18, 7, 'At that time gifts will be brought to the LORD of Hosts— from a people tall and smooth-skinned, from a people widely feared, from a powerful nation of strange speech, whose land is divided by rivers— to Mount Zion, the place of the Name of the LORD of Hosts.'),
  ('BSB', 'Isaiah', 23, 19, 1, 'This is the burden against Egypt: Behold, the LORD rides on a swift cloud; He is coming to Egypt. The idols of Egypt will tremble before Him, and the hearts of the Egyptians will melt within them.'),
  ('BSB', 'Isaiah', 23, 19, 2, '“So I will incite Egyptian against Egyptian; brother will fight against brother, neighbor against neighbor, city against city, and kingdom against kingdom.'),
  ('BSB', 'Isaiah', 23, 19, 3, 'Then the spirit of the Egyptians will be emptied out from among them, and I will frustrate their plans, so that they will resort to idols and spirits of the dead, to mediums and spiritists.'),
  ('BSB', 'Isaiah', 23, 19, 4, 'I will deliver the Egyptians into the hands of harsh masters, and a fierce king will rule over them,” declares the Lord GOD of Hosts.'),
  ('BSB', 'Isaiah', 23, 19, 5, 'The waters of the Nile will dry up, and the riverbed will be parched and empty.'),
  ('BSB', 'Isaiah', 23, 19, 6, 'The canals will stink; the streams of Egypt will trickle and dry up; the reeds and rushes will wither.'),
  ('BSB', 'Isaiah', 23, 19, 7, 'The bulrushes by the Nile, by the mouth of the river, and all the fields sown along the Nile, will wither, blow away, and be no more.'),
  ('BSB', 'Isaiah', 23, 19, 8, 'Then the fishermen will mourn, all who cast a hook into the Nile will lament, and those who spread nets on the waters will pine away.'),
  ('BSB', 'Isaiah', 23, 19, 9, 'The workers in flax will be dismayed, and the weavers of fine linen will turn pale.'),
  ('BSB', 'Isaiah', 23, 19, 10, 'The workers in cloth will be dejected, and all the hired workers will be sick at heart.'),
  ('BSB', 'Isaiah', 23, 19, 11, 'The princes of Zoan are mere fools; Pharaoh’s wise counselors give senseless advice. How can you say to Pharaoh, “I am one of the wise, a son of eastern kings”?'),
  ('BSB', 'Isaiah', 23, 19, 12, 'Where are your wise men now? Let them tell you and reveal what the LORD of Hosts has planned against Egypt.'),
  ('BSB', 'Isaiah', 23, 19, 13, 'The princes of Zoan have become fools; the princes of Memphis are deceived. The cornerstones of her tribes have led Egypt astray.'),
  ('BSB', 'Isaiah', 23, 19, 14, 'The LORD has poured into her a spirit of confusion. Egypt has been led astray in all she does, as a drunkard staggers through his own vomit.'),
  ('BSB', 'Isaiah', 23, 19, 15, 'There is nothing Egypt can do— head or tail, palm or reed.'),
  ('BSB', 'Isaiah', 23, 19, 16, 'In that day the Egyptians will be like women. They will tremble with fear beneath the uplifted hand of the LORD of Hosts, when He brandishes it against them.'),
  ('BSB', 'Isaiah', 23, 19, 17, 'The land of Judah will bring terror to Egypt; whenever Judah is mentioned, Egypt will tremble over what the LORD of Hosts has planned against it.'),
  ('BSB', 'Isaiah', 23, 19, 18, 'In that day five cities in the land of Egypt will speak the language of Canaan and swear allegiance to the LORD of Hosts. One of them will be called the City of the Sun.'),
  ('BSB', 'Isaiah', 23, 19, 19, 'In that day there will be an altar to the LORD in the center of the land of Egypt, and a pillar to the LORD near her border.'),
  ('BSB', 'Isaiah', 23, 19, 20, 'It will be a sign and a witness to the LORD of Hosts in the land of Egypt. When they cry out to the LORD because of their oppressors, He will send them a savior and defender to rescue them.'),
  ('BSB', 'Isaiah', 23, 19, 21, 'The LORD will make Himself known to Egypt, and on that day Egypt will acknowledge the LORD. They will worship with sacrifices and offerings; they will make vows to the LORD and fulfill them.'),
  ('BSB', 'Isaiah', 23, 19, 22, 'And the LORD will strike Egypt with a plague; He will strike them but heal them. They will turn to the LORD, and He will hear their prayers and heal them.'),
  ('BSB', 'Isaiah', 23, 19, 23, 'In that day there will be a highway from Egypt to Assyria. The Assyrians will go to Egypt, and the Egyptians to Assyria. The Egyptians and Assyrians will worship together.'),
  ('BSB', 'Isaiah', 23, 19, 24, 'In that day Israel will join a three-party alliance with Egypt and Assyria—a blessing upon the earth.'),
  ('BSB', 'Isaiah', 23, 19, 25, 'The LORD of Hosts will bless them, saying, “Blessed be Egypt My people, Assyria My handiwork, and Israel My inheritance.”'),
  ('BSB', 'Isaiah', 23, 20, 1, 'Before the year that the chief commander, sent by Sargon king of Assyria, came to Ashdod and attacked and captured it,'),
  ('BSB', 'Isaiah', 23, 20, 2, 'the LORD had already spoken through Isaiah son of Amoz, saying, “Go, remove the sackcloth from your waist and the sandals from your feet.” And Isaiah did so, walking around naked and barefoot.'),
  ('BSB', 'Isaiah', 23, 20, 3, 'Then the LORD said, “Just as My servant Isaiah has gone naked and barefoot for three years as a sign and omen against Egypt and Cush,'),
  ('BSB', 'Isaiah', 23, 20, 4, 'so the king of Assyria will lead away the captives of Egypt and the exiles of Cush, young and old alike, naked and barefoot, with bared buttocks—to Egypt’s shame.'),
  ('BSB', 'Isaiah', 23, 20, 5, 'Those who made Cush their hope and Egypt their boast will be dismayed and ashamed.'),
  ('BSB', 'Isaiah', 23, 20, 6, 'And on that day the dwellers of this coastland will say, ‘See what has happened to our source of hope, those to whom we fled for help and deliverance from the king of Assyria! How then can we escape?’”'),
  ('BSB', 'Isaiah', 23, 21, 1, 'This is the burden against the Desert by the Sea: Like whirlwinds sweeping through the Negev, an invader comes from the desert, from a land of terror.'),
  ('BSB', 'Isaiah', 23, 21, 2, 'A dire vision is declared to me: “The traitor still betrays, and the destroyer still destroys. Go up, O Elam! Lay siege, O Media! I will put an end to all her groaning.”'),
  ('BSB', 'Isaiah', 23, 21, 3, 'Therefore my body is filled with anguish. Pain grips me, like the pains of a woman in labor. I am bewildered to hear, I am dismayed to see.'),
  ('BSB', 'Isaiah', 23, 21, 4, 'My heart falters; fear makes me tremble. The twilight of my desire has turned to horror.'),
  ('BSB', 'Isaiah', 23, 21, 5, 'They prepare a table, they lay out a carpet, they eat, they drink! Rise up, O princes, oil the shields!'),
  ('BSB', 'Isaiah', 23, 21, 6, 'For this is what the Lord says to me: “Go, post a lookout and have him report what he sees.'),
  ('BSB', 'Isaiah', 23, 21, 7, 'When he sees chariots with teams of horsemen, riders on donkeys, riders on camels, he must be alert, fully alert.”'),
  ('BSB', 'Isaiah', 23, 21, 8, 'Then the lookout shouted: “Day after day, my lord, I stand on the watchtower; night after night I stay at my post.'),
  ('BSB', 'Isaiah', 23, 21, 9, 'Look, here come the riders, horsemen in pairs.” And one answered, saying: “Fallen, fallen is Babylon! All the images of her gods lie shattered on the ground!”'),
  ('BSB', 'Isaiah', 23, 21, 10, 'O my people, crushed on the threshing floor, I tell you what I have heard from the LORD of Hosts, the God of Israel.'),
  ('BSB', 'Isaiah', 23, 21, 11, 'This is the burden against Dumah: One calls to me from Seir, “Watchman, what is left of the night? Watchman, what is left of the night?”'),
  ('BSB', 'Isaiah', 23, 21, 12, 'The watchman replies, “Morning has come, but also the night. If you would inquire, then inquire. Come back yet again.”'),
  ('BSB', 'Isaiah', 23, 21, 13, 'This is the burden against Arabia: In the thickets of Arabia you must lodge, O caravans of Dedanites.'),
  ('BSB', 'Isaiah', 23, 21, 14, 'Bring water for the thirsty, O dwellers of Tema; meet the refugees with food.'),
  ('BSB', 'Isaiah', 23, 21, 15, 'For they flee from the sword— the sword that is drawn— from the bow that is bent, and from the stress of battle.'),
  ('BSB', 'Isaiah', 23, 21, 16, 'For this is what the Lord says to me: “Within one year, as a hired worker would count it, all the glory of Kedar will be gone.'),
  ('BSB', 'Isaiah', 23, 21, 17, 'The remaining archers, the warriors of Kedar, will be few.” For the LORD, the God of Israel, has spoken.'),
  ('BSB', 'Isaiah', 23, 22, 1, 'This is the burden against the Valley of Vision: What ails you now, that you have all gone up to the rooftops,'),
  ('BSB', 'Isaiah', 23, 22, 2, 'O city of commotion, O town of revelry? Your slain did not die by the sword, nor were they killed in battle.'),
  ('BSB', 'Isaiah', 23, 22, 3, 'All your rulers have fled together, captured without a bow. All your fugitives were captured together, having fled to a distant place.'),
  ('BSB', 'Isaiah', 23, 22, 4, 'Therefore I said, “Turn away from me, let me weep bitterly! Do not try to console me over the destruction of the daughter of my people.”'),
  ('BSB', 'Isaiah', 23, 22, 5, 'For the Lord GOD of Hosts has set a day of tumult and trampling and confusion in the Valley of Vision— of breaking down the walls and crying to the mountains.'),
  ('BSB', 'Isaiah', 23, 22, 6, 'Elam takes up a quiver, with chariots and horsemen, and Kir uncovers the shield.'),
  ('BSB', 'Isaiah', 23, 22, 7, 'Your choicest valleys are full of chariots, and horsemen are posted at the gates.'),
  ('BSB', 'Isaiah', 23, 22, 8, 'He has uncovered the defenses of Judah. On that day you looked to the weapons in the House of the Forest.'),
  ('BSB', 'Isaiah', 23, 22, 9, 'You saw that there were many breaches in the walls of the City of David. You collected water from the lower pool.'),
  ('BSB', 'Isaiah', 23, 22, 10, 'You counted the houses of Jerusalem and tore them down to strengthen the wall.'),
  ('BSB', 'Isaiah', 23, 22, 11, 'You built a reservoir between the walls for the waters of the ancient pool, but you did not look to the One who made it, or consider Him who planned it long ago.'),
  ('BSB', 'Isaiah', 23, 22, 12, 'On that day the Lord GOD of Hosts called for weeping and wailing, for shaven heads and the wearing of sackcloth.'),
  ('BSB', 'Isaiah', 23, 22, 13, 'But look, there is joy and gladness, butchering of cattle and slaughtering of sheep, eating of meat and drinking of wine: “Let us eat and drink, for tomorrow we die!”'),
  ('BSB', 'Isaiah', 23, 22, 14, 'The LORD of Hosts has revealed in my hearing: “Until your dying day, this sin of yours will never be atoned for,” says the Lord GOD of Hosts.'),
  ('BSB', 'Isaiah', 23, 22, 15, 'This is what the Lord GOD of Hosts says: “Go, say to Shebna, the steward in charge of the palace:'),
  ('BSB', 'Isaiah', 23, 22, 16, 'What are you doing here, and who authorized you to carve out a tomb for yourself here—to chisel your tomb in the height and cut your resting place in the rock?'),
  ('BSB', 'Isaiah', 23, 22, 17, 'Look, O mighty man! The LORD is about to shake you violently. He will take hold of you,'),
  ('BSB', 'Isaiah', 23, 22, 18, 'roll you into a ball, and sling you into a wide land. There you will die, and there your glorious chariots will remain—a disgrace to the house of your master.'),
  ('BSB', 'Isaiah', 23, 22, 19, 'I will remove you from office, and you will be ousted from your position.'),
  ('BSB', 'Isaiah', 23, 22, 20, 'On that day I will summon My servant, Eliakim son of Hilkiah.'),
  ('BSB', 'Isaiah', 23, 22, 21, 'I will clothe him with your robe and tie your sash around him. I will put your authority in his hand, and he will be a father to the dwellers of Jerusalem and to the house of Judah.'),
  ('BSB', 'Isaiah', 23, 22, 22, 'I will place on his shoulder the key to the house of David. What he opens no one can shut, and what he shuts no one can open.'),
  ('BSB', 'Isaiah', 23, 22, 23, 'I will drive him like a peg into a firm place, and he will be a throne of glory for the house of his father.'),
  ('BSB', 'Isaiah', 23, 22, 24, 'So they will hang on him all the glory of his father’s house: the descendants and the offshoots—all the lesser vessels, from bowls to every kind of jar.'),
  ('BSB', 'Isaiah', 23, 22, 25, 'In that day, declares the LORD of Hosts, the peg driven into a firm place will give way; it will be sheared off and fall, and the load upon it will be cut down.” Indeed, the LORD has spoken.'),
  ('BSB', 'Isaiah', 23, 23, 1, 'This is the burden against Tyre: Wail, O ships of Tarshish, for Tyre is laid waste, without house or harbor. Word has reached them from the land of Cyprus.'),
  ('BSB', 'Isaiah', 23, 23, 2, 'Be silent, O dwellers of the coastland, you merchants of Sidon, whose traders have crossed the sea.'),
  ('BSB', 'Isaiah', 23, 23, 3, 'On the great waters came the grain of Shihor; the harvest of the Nile was the revenue of Tyre; she was the merchant of the nations.'),
  ('BSB', 'Isaiah', 23, 23, 4, 'Be ashamed, O Sidon, the stronghold of the sea, for the sea has spoken: “I have not been in labor or given birth. I have not raised young men or brought up young women.”'),
  ('BSB', 'Isaiah', 23, 23, 5, 'When the report reaches Egypt, they will writhe in agony over the news of Tyre.'),
  ('BSB', 'Isaiah', 23, 23, 6, 'Cross over to Tarshish; wail, O inhabitants of the coastland!'),
  ('BSB', 'Isaiah', 23, 23, 7, 'Is this your jubilant city, whose origin is from antiquity, whose feet have taken her to settle far away?'),
  ('BSB', 'Isaiah', 23, 23, 8, 'Who planned this against Tyre, the bestower of crowns, whose traders are princes, whose merchants are renowned on the earth?'),
  ('BSB', 'Isaiah', 23, 23, 9, 'The LORD of Hosts planned it, to defile all its glorious beauty, to disgrace all the renowned of the earth.'),
  ('BSB', 'Isaiah', 23, 23, 10, 'Cultivate your land like the Nile, O Daughter of Tarshish; there is no longer a harbor.'),
  ('BSB', 'Isaiah', 23, 23, 11, 'The LORD has stretched out His hand over the sea; He has made kingdoms tremble. He has given a command that the strongholds of Canaan be destroyed.'),
  ('BSB', 'Isaiah', 23, 23, 12, 'He said, “You shall rejoice no more, O oppressed Virgin Daughter of Sidon. Get up and cross over to Cyprus— even there you will find no rest.”'),
  ('BSB', 'Isaiah', 23, 23, 13, 'Look at the land of the Chaldeans— a people now of no account. The Assyrians destined it for the desert creatures; they set up their siege towers and stripped its palaces. They brought it to ruin.'),
  ('BSB', 'Isaiah', 23, 23, 14, 'Wail, O ships of Tarshish, for your harbor has been destroyed!'),
  ('BSB', 'Isaiah', 23, 23, 15, 'At that time Tyre will be forgotten for seventy years—the span of a king’s life. But at the end of seventy years, it will happen to Tyre as in the song of the harlot:'),
  ('BSB', 'Isaiah', 23, 23, 16, '“Take up your harp, stroll through the city, O forgotten harlot. Make sweet melody, sing many a song, so you will be remembered.”'),
  ('BSB', 'Isaiah', 23, 23, 17, 'And at the end of seventy years, the LORD will restore Tyre. Then she will return to hire as a prostitute and sell herself to all the kingdoms on the face of the earth.'),
  ('BSB', 'Isaiah', 23, 23, 18, 'Yet her profits and wages will be set apart to the LORD; they will not be stored or saved, for her profit will go to those who live before the LORD, for abundant food and fine clothing.'),
  ('BSB', 'Isaiah', 23, 24, 1, 'Behold, the LORD lays waste the earth and leaves it in ruins. He will twist its surface and scatter its inhabitants—'),
  ('BSB', 'Isaiah', 23, 24, 2, 'people and priest alike, servant and master, maid and mistress, buyer and seller, lender and borrower, creditor and debtor.'),
  ('BSB', 'Isaiah', 23, 24, 3, 'The earth will be utterly laid waste and thoroughly plundered. For the LORD has spoken this word.'),
  ('BSB', 'Isaiah', 23, 24, 4, 'The earth mourns and withers; the world languishes and fades; the exalted of the earth waste away.'),
  ('BSB', 'Isaiah', 23, 24, 5, 'The earth is defiled by its people; they have transgressed the laws; they have overstepped the decrees and broken the everlasting covenant.'),
  ('BSB', 'Isaiah', 23, 24, 6, 'Therefore a curse has consumed the earth, and its inhabitants must bear the guilt; the earth’s dwellers have been burned, and only a few survive.'),
  ('BSB', 'Isaiah', 23, 24, 7, 'The new wine dries up, the vine withers. All the merrymakers now groan.'),
  ('BSB', 'Isaiah', 23, 24, 8, 'The joyful tambourines have ceased; the noise of revelers has stopped; the joyful harp is silent.'),
  ('BSB', 'Isaiah', 23, 24, 9, 'They no longer sing and drink wine; strong drink is bitter to those who consume it.'),
  ('BSB', 'Isaiah', 23, 24, 10, 'The city of chaos is shattered; every house is closed to entry.'),
  ('BSB', 'Isaiah', 23, 24, 11, 'In the streets they cry out for wine. All joy turns to gloom; rejoicing is exiled from the land.'),
  ('BSB', 'Isaiah', 23, 24, 12, 'The city is left in ruins; its gate is reduced to rubble.'),
  ('BSB', 'Isaiah', 23, 24, 13, 'So will it be on the earth and among the nations, like a harvested olive tree, like a gleaning after a grape harvest.'),
  ('BSB', 'Isaiah', 23, 24, 14, 'They raise their voices, they shout for joy; from the west they proclaim the majesty of the LORD.'),
  ('BSB', 'Isaiah', 23, 24, 15, 'Therefore glorify the LORD in the east. Extol the name of the LORD, the God of Israel in the islands of the sea.'),
  ('BSB', 'Isaiah', 23, 24, 16, 'From the ends of the earth we hear singing: “Glory to the Righteous One.” But I said, “I am wasting away! I am wasting away! Woe is me.” The treacherous betray; the treacherous deal in treachery.'),
  ('BSB', 'Isaiah', 23, 24, 17, 'Terror and pit and snare await you, O dweller of the earth.'),
  ('BSB', 'Isaiah', 23, 24, 18, 'Whoever flees the sound of panic will fall into the pit, and whoever climbs from the pit will be caught in the snare. For the windows of heaven are open, and the foundations of the earth are shaken.'),
  ('BSB', 'Isaiah', 23, 24, 19, 'The earth is utterly broken apart, the earth is split open, the earth is shaken violently.'),
  ('BSB', 'Isaiah', 23, 24, 20, 'The earth staggers like a drunkard and sways like a shack. Earth’s rebellion weighs it down, and it falls, never to rise again.'),
  ('BSB', 'Isaiah', 23, 24, 21, 'In that day the LORD will punish the host of heaven above and the kings of the earth below.'),
  ('BSB', 'Isaiah', 23, 24, 22, 'They will be gathered together like prisoners in a pit. They will be confined to a dungeon and punished after many days.'),
  ('BSB', 'Isaiah', 23, 24, 23, 'The moon will be confounded and the sun will be ashamed; for the LORD of Hosts will reign on Mount Zion and in Jerusalem, and before His elders with great glory.'),
  ('BSB', 'Isaiah', 23, 25, 1, 'O LORD, You are my God! I will exalt You; I will praise Your name. For You have worked wonders— plans formed long ago— in perfect faithfulness.'),
  ('BSB', 'Isaiah', 23, 25, 2, 'Indeed, You have made the city a heap of rubble, the fortified town a ruin. The fortress of strangers is a city no more; it will never be rebuilt.'),
  ('BSB', 'Isaiah', 23, 25, 3, 'Therefore, a strong people will honor You. The cities of ruthless nations will revere You.'),
  ('BSB', 'Isaiah', 23, 25, 4, 'For You have been a refuge for the poor, a stronghold for the needy in distress, a refuge from the storm, a shade from the heat. For the breath of the ruthless is like rain against a wall,'),
  ('BSB', 'Isaiah', 23, 25, 5, 'like heat in a dry land. You subdue the uproar of foreigners. As the shade of a cloud cools the heat, so the song of the ruthless is silenced.'),
  ('BSB', 'Isaiah', 23, 25, 6, 'On this mountain the LORD of Hosts will prepare a banquet for all the peoples, a feast of aged wine, of choice meat, of finely aged wine.'),
  ('BSB', 'Isaiah', 23, 25, 7, 'On this mountain He will swallow up the shroud that enfolds all peoples, the sheet that covers all nations;'),
  ('BSB', 'Isaiah', 23, 25, 8, 'He will swallow up death forever. The Lord GOD will wipe away the tears from every face and remove the disgrace of His people from the whole earth. For the LORD has spoken.'),
  ('BSB', 'Isaiah', 23, 25, 9, 'And in that day it will be said, “Surely this is our God; we have waited for Him, and He has saved us. This is the LORD for whom we have waited. Let us rejoice and be glad in His salvation.”'),
  ('BSB', 'Isaiah', 23, 25, 10, 'For the hand of the LORD will rest on this mountain. But Moab will be trampled in his place as straw is trodden into the dung pile.'),
  ('BSB', 'Isaiah', 23, 25, 11, 'He will spread out his hands within it, as a swimmer spreads his arms to swim. His pride will be brought low, despite the skill of his hands.'),
  ('BSB', 'Isaiah', 23, 25, 12, 'The high-walled fortress will be brought down, cast to the ground, into the dust.'),
  ('BSB', 'Isaiah', 23, 26, 1, 'In that day this song will be sung in the land of Judah: We have a strong city; salvation is established as its walls and ramparts.'),
  ('BSB', 'Isaiah', 23, 26, 2, 'Open the gates so a righteous nation may enter— one that remains faithful.'),
  ('BSB', 'Isaiah', 23, 26, 3, 'You will keep in perfect peace the steadfast of mind, because he trusts in You.'),
  ('BSB', 'Isaiah', 23, 26, 4, 'Trust in the LORD forever, because GOD the LORD is the Rock eternal.'),
  ('BSB', 'Isaiah', 23, 26, 5, 'For He has humbled those who dwell on high; He lays the lofty city low. He brings it down to the ground; He casts it into the dust.'),
  ('BSB', 'Isaiah', 23, 26, 6, 'Feet trample it down— the feet of the oppressed, the steps of the poor.'),
  ('BSB', 'Isaiah', 23, 26, 7, 'The path of the righteous is level; You clear a straight path for the upright.'),
  ('BSB', 'Isaiah', 23, 26, 8, 'Yes, we wait for You, O LORD; we walk in the path of Your judgments. Your name and renown are the desire of our souls.'),
  ('BSB', 'Isaiah', 23, 26, 9, 'My soul longs for You in the night; indeed, my spirit seeks You at dawn. For when Your judgments come upon the earth, the people of the world learn righteousness.'),
  ('BSB', 'Isaiah', 23, 26, 10, 'Though grace is shown to the wicked man, he does not learn righteousness. In the land of righteousness he acts unjustly and fails to see the majesty of the LORD.'),
  ('BSB', 'Isaiah', 23, 26, 11, 'O LORD, Your hand is upraised, but they do not see it. They will see Your zeal for Your people and be put to shame. The fire set for Your enemies will consume them!'),
  ('BSB', 'Isaiah', 23, 26, 12, 'O LORD, You will establish peace for us. For all that we have accomplished, You have done for us.'),
  ('BSB', 'Isaiah', 23, 26, 13, 'O LORD our God, other lords besides You have had dominion, but Your name alone do we confess.'),
  ('BSB', 'Isaiah', 23, 26, 14, 'The dead will not live; the departed spirits will not rise. Therefore You have punished and destroyed them; You have wiped out all memory of them.'),
  ('BSB', 'Isaiah', 23, 26, 15, 'You have enlarged the nation, O LORD; You have enlarged the nation. You have gained glory for Yourself; You have extended all the borders of the land.'),
  ('BSB', 'Isaiah', 23, 26, 16, 'O LORD, they sought You in their distress; when You disciplined them, they poured out a quiet prayer.'),
  ('BSB', 'Isaiah', 23, 26, 17, 'As a woman with child about to give birth writhes and cries out in pain, so were we in Your presence, O LORD.'),
  ('BSB', 'Isaiah', 23, 26, 18, 'We were with child; we writhed in pain; but we gave birth to wind. We have given no salvation to the earth, nor brought any life into the world.'),
  ('BSB', 'Isaiah', 23, 26, 19, 'Your dead will live; their bodies will rise. Awake and sing, you who dwell in the dust! For your dew is like the dew of the morning, and the earth will bring forth her dead.'),
  ('BSB', 'Isaiah', 23, 26, 20, 'Go, my people, enter your rooms and shut your doors behind you. Hide yourselves a little while until the wrath has passed.'),
  ('BSB', 'Isaiah', 23, 26, 21, 'For behold, the LORD is coming out of His dwelling to punish the inhabitants of the earth for their iniquity. The earth will reveal her bloodshed and will no longer conceal her slain.'),
  ('BSB', 'Isaiah', 23, 27, 1, 'In that day the LORD will take His sharp, great, and mighty sword, and bring judgment on Leviathan the fleeing serpent—Leviathan the coiling serpent—and He will slay the dragon of the sea.'),
  ('BSB', 'Isaiah', 23, 27, 2, 'In that day: “Sing about a fruitful vineyard.'),
  ('BSB', 'Isaiah', 23, 27, 3, 'I, the LORD, am its keeper; I water it continually. I guard it night and day so no one can disturb it;'),
  ('BSB', 'Isaiah', 23, 27, 4, 'I am not angry. If only thorns and briers confronted Me, I would march and trample them, I would burn them to the ground.'),
  ('BSB', 'Isaiah', 23, 27, 5, 'Or let them lay claim to My protection; let them make peace with Me— yes, let them make peace with Me.”'),
  ('BSB', 'Isaiah', 23, 27, 6, 'In the days to come, Jacob will take root. Israel will bud and blossom and fill the whole world with fruit.'),
  ('BSB', 'Isaiah', 23, 27, 7, 'Has the LORD struck Israel as He struck her oppressors? Was she killed like those who slayed her?'),
  ('BSB', 'Isaiah', 23, 27, 8, 'By warfare and exile You contended with her and removed her with a fierce wind, as on the day the east wind blows.'),
  ('BSB', 'Isaiah', 23, 27, 9, 'Therefore Jacob’s guilt will be atoned for, and the full fruit of the removal of his sin will be this: When he makes all the altar stones like crushed bits of chalk, no Asherah poles or incense altars will remain standing.'),
  ('BSB', 'Isaiah', 23, 27, 10, 'For the fortified city lies deserted— a homestead abandoned, a wilderness forsaken. There the calves graze, and there they lie down; they strip its branches bare.'),
  ('BSB', 'Isaiah', 23, 27, 11, 'When its limbs are dry, they are broken off. Women come and use them for kindling; for this is a people without understanding. Therefore their Maker has no compassion on them, and their Creator shows them no favor.'),
  ('BSB', 'Isaiah', 23, 27, 12, 'In that day the LORD will thresh from the flowing Euphrates to the Wadi of Egypt, and you, O Israelites, will be gathered one by one.'),
  ('BSB', 'Isaiah', 23, 27, 13, 'And in that day a great ram’s horn will sound, and those who were perishing in Assyria will come forth with those who were exiles in Egypt. And they will worship the LORD on the holy mountain in Jerusalem.'),
  ('BSB', 'Isaiah', 23, 28, 1, 'Woe to the majestic crown of Ephraim’s drunkards, to the fading flower of his glorious splendor, set on the summit above the fertile valley, the pride of those overcome by wine.'),
  ('BSB', 'Isaiah', 23, 28, 2, 'Behold, the Lord has one who is strong and mighty. Like a hailstorm or destructive tempest, like a driving rain or flooding downpour, he will smash that crown to the ground.'),
  ('BSB', 'Isaiah', 23, 28, 3, 'The majestic crown of Ephraim’s drunkards will be trampled underfoot.'),
  ('BSB', 'Isaiah', 23, 28, 4, 'The fading flower of his beautiful splendor, set on the summit above the fertile valley, will be like a ripe fig before the summer harvest: Whoever sees it will take it in his hand and swallow it.'),
  ('BSB', 'Isaiah', 23, 28, 5, 'On that day the LORD of Hosts will be a crown of glory, a diadem of splendor to the remnant of His people,'),
  ('BSB', 'Isaiah', 23, 28, 6, 'a spirit of justice to him who sits in judgment, and a strength to those who repel the onslaught at the gate.'),
  ('BSB', 'Isaiah', 23, 28, 7, 'These also stagger from wine and stumble from strong drink: Priests and prophets reel from strong drink and are befuddled by wine. They stumble because of strong drink, muddled in their visions and stumbling in their judgments.'),
  ('BSB', 'Isaiah', 23, 28, 8, 'For all their tables are covered with vomit; there is not a place without filth.'),
  ('BSB', 'Isaiah', 23, 28, 9, 'Whom is He trying to teach? To whom is He explaining His message? To infants just weaned from milk? To babies removed from the breast?'),
  ('BSB', 'Isaiah', 23, 28, 10, 'For they hear: “Order on order, order on order, line on line, line on line; a little here, a little there.”'),
  ('BSB', 'Isaiah', 23, 28, 11, 'Indeed, with mocking lips and foreign tongues, He will speak to this people'),
  ('BSB', 'Isaiah', 23, 28, 12, 'to whom He has said: “This is the place of rest, let the weary rest; this is the place of repose.” But they would not listen.'),
  ('BSB', 'Isaiah', 23, 28, 13, 'Then the word of the LORD to them will become: “Order on order, order on order, line on line, line on line; a little here, a little there,” so that they will go stumbling backward and will be injured, ensnared, and captured.'),
  ('BSB', 'Isaiah', 23, 28, 14, 'Therefore hear the word of the LORD, O scoffers who rule this people in Jerusalem.'),
  ('BSB', 'Isaiah', 23, 28, 15, 'For you said, “We have made a covenant with death; we have fashioned an agreement with Sheol. When the overwhelming scourge passes through it will not touch us, because we have made lies our refuge and falsehood our hiding place.”'),
  ('BSB', 'Isaiah', 23, 28, 16, 'So this is what the Lord GOD says: “See, I lay a stone in Zion, a tested stone, a precious cornerstone, a sure foundation; the one who believes will never be shaken.'),
  ('BSB', 'Isaiah', 23, 28, 17, 'I will make justice the measuring line and righteousness the level. Hail will sweep away your refuge of lies, and water will flood your hiding place.'),
  ('BSB', 'Isaiah', 23, 28, 18, 'Your covenant with death will be dissolved, and your agreement with Sheol will not stand. When the overwhelming scourge passes through, you will be trampled by it.'),
  ('BSB', 'Isaiah', 23, 28, 19, 'As often as it passes through, it will carry you away; it will sweep through morning after morning, by day and by night.” The understanding of this message will bring sheer terror.'),
  ('BSB', 'Isaiah', 23, 28, 20, 'Indeed, the bed is too short to stretch out on, and the blanket too small to wrap around you.'),
  ('BSB', 'Isaiah', 23, 28, 21, 'For the LORD will rise up as at Mount Perazim. He will rouse Himself as in the Valley of Gibeon, to do His work, His strange work, and to perform His task, His disturbing task.'),
  ('BSB', 'Isaiah', 23, 28, 22, 'So now, do not mock, or your shackles will become heavier. Indeed, I have heard from the Lord GOD of Hosts a decree of destruction against the whole land.'),
  ('BSB', 'Isaiah', 23, 28, 23, 'Listen and hear my voice. Pay attention and hear what I say.'),
  ('BSB', 'Isaiah', 23, 28, 24, 'Does the plowman plow for planting every day? Does he continuously loosen and harrow the soil?'),
  ('BSB', 'Isaiah', 23, 28, 25, 'When he has leveled its surface, does he not sow caraway and scatter cumin? He plants wheat in rows and barley in plots, and rye within its border.'),
  ('BSB', 'Isaiah', 23, 28, 26, 'For his God instructs and teaches him properly.'),
  ('BSB', 'Isaiah', 23, 28, 27, 'Surely caraway is not threshed with a sledge, and the wheel of a cart is not rolled over the cumin. But caraway is beaten out with a stick, and cumin with a rod.'),
  ('BSB', 'Isaiah', 23, 28, 28, 'Grain for bread must be ground, but it is not endlessly threshed. Though the wheels of the cart roll over it, the horses do not crush it.'),
  ('BSB', 'Isaiah', 23, 28, 29, 'This also comes from the LORD of Hosts, who is wonderful in counsel and excellent in wisdom.'),
  ('BSB', 'Isaiah', 23, 29, 1, 'Woe to you, O Ariel, the city of Ariel where David camped! Year upon year let your festivals recur.'),
  ('BSB', 'Isaiah', 23, 29, 2, 'And I will constrain Ariel, and there will be mourning and lamentation; she will be like an altar hearth before Me.'),
  ('BSB', 'Isaiah', 23, 29, 3, 'I will camp in a circle around you; I will besiege you with towers and set up siege works against you.'),
  ('BSB', 'Isaiah', 23, 29, 4, 'You will be brought low, you will speak from the ground, and out of the dust your words will be muffled. Your voice will be like a spirit from the ground; your speech will whisper out of the dust.'),
  ('BSB', 'Isaiah', 23, 29, 5, 'But your many foes will be like fine dust, the multitude of the ruthless like blowing chaff. Then suddenly, in an instant,'),
  ('BSB', 'Isaiah', 23, 29, 6, 'you will be visited by the LORD of Hosts with thunder and earthquake and loud noise, with windstorm and tempest and consuming flame of fire.'),
  ('BSB', 'Isaiah', 23, 29, 7, 'All the many nations going out to battle against Ariel— even all who war against her, laying siege and attacking her— will be like a dream, like a vision in the night,'),
  ('BSB', 'Isaiah', 23, 29, 8, 'as when a hungry man dreams he is eating, then awakens still hungry; as when a thirsty man dreams he is drinking, then awakens faint and parched. So will it be for all the many nations who go to battle against Mount Zion.'),
  ('BSB', 'Isaiah', 23, 29, 9, 'Stop and be astonished; blind yourselves and be sightless; be drunk, but not with wine; stagger, but not from strong drink.'),
  ('BSB', 'Isaiah', 23, 29, 10, 'For the LORD has poured out on you a spirit of deep sleep. He has shut your eyes, O prophets; He has covered your heads, O seers.'),
  ('BSB', 'Isaiah', 23, 29, 11, 'And the entire vision will be to you like the words sealed in a scroll. If it is handed to someone to read, he will say, “I cannot, because it is sealed.”'),
  ('BSB', 'Isaiah', 23, 29, 12, 'Or if the scroll is handed to one unable to read, he will say, “I cannot read.”'),
  ('BSB', 'Isaiah', 23, 29, 13, 'Therefore the Lord said: “These people draw near to Me with their mouths and honor Me with their lips, but their hearts are far from Me. Their worship of Me is but rules taught by men.'),
  ('BSB', 'Isaiah', 23, 29, 14, 'Therefore I will again confound these people with wonder upon wonder. The wisdom of the wise will vanish, and the intelligence of the intelligent will be hidden.”'),
  ('BSB', 'Isaiah', 23, 29, 15, 'Woe to those who dig deep to hide their plans from the LORD. In darkness they do their works and say, “Who sees us, and who will know?”'),
  ('BSB', 'Isaiah', 23, 29, 16, 'You have turned things upside down, as if the potter were regarded as clay. Shall what is formed say to him who formed it, “He did not make me”? Can the pottery say of the potter, “He has no understanding”?'),
  ('BSB', 'Isaiah', 23, 29, 17, 'In a very short time, will not Lebanon become an orchard, and the orchard seem like a forest?'),
  ('BSB', 'Isaiah', 23, 29, 18, 'On that day the deaf will hear the words of the scroll, and out of the deep darkness the eyes of the blind will see.'),
  ('BSB', 'Isaiah', 23, 29, 19, 'The humble will increase their joy in the LORD, and the poor among men will rejoice in the Holy One of Israel.'),
  ('BSB', 'Isaiah', 23, 29, 20, 'For the ruthless will vanish, the mockers will disappear, and all who look for evil will be cut down—'),
  ('BSB', 'Isaiah', 23, 29, 21, 'those who indict a man with a word, who ensnare the mediator at the gate, and who with false charges deprive the innocent of justice.'),
  ('BSB', 'Isaiah', 23, 29, 22, 'Therefore the LORD who redeemed Abraham says of the house of Jacob: “No longer will Jacob be ashamed and no more will his face grow pale.'),
  ('BSB', 'Isaiah', 23, 29, 23, 'For when he sees his children around him, the work of My hands, they will honor My name, they will sanctify the Holy One of Jacob, and they will stand in awe of the God of Israel.'),
  ('BSB', 'Isaiah', 23, 29, 24, 'Then the wayward in spirit will come to understanding, and those who grumble will accept instruction.”'),
  ('BSB', 'Isaiah', 23, 30, 1, '“Woe to the rebellious children,” declares the LORD, “to those who carry out a plan that is not Mine, who form an alliance, but against My will, heaping up sin upon sin.'),
  ('BSB', 'Isaiah', 23, 30, 2, 'They set out to go down to Egypt without asking My advice, to seek shelter under Pharaoh’s protection and take refuge in Egypt’s shade.'),
  ('BSB', 'Isaiah', 23, 30, 3, 'But Pharaoh’s protection will become your shame, and the refuge of Egypt’s shade your disgrace.'),
  ('BSB', 'Isaiah', 23, 30, 4, 'For though their princes are at Zoan and their envoys have arrived in Hanes,'),
  ('BSB', 'Isaiah', 23, 30, 5, 'everyone will be put to shame because of a people useless to them. They cannot be of help; they are good for nothing but shame and reproach.”'),
  ('BSB', 'Isaiah', 23, 30, 6, 'This is the burden against the beasts of the Negev: Through a land of hardship and distress, of lioness and lion, of viper and flying serpent, they carry their wealth on the backs of donkeys and their treasures on the humps of camels, to a people of no profit to them.'),
  ('BSB', 'Isaiah', 23, 30, 7, 'Egypt’s help is futile and empty; therefore I have called her Rahab Who Sits Still.'),
  ('BSB', 'Isaiah', 23, 30, 8, 'Go now, write it on a tablet in their presence and inscribe it on a scroll; it will be for the days to come, a witness forever and ever.'),
  ('BSB', 'Isaiah', 23, 30, 9, 'These are rebellious people, deceitful children, children unwilling to obey the LORD’s instruction.'),
  ('BSB', 'Isaiah', 23, 30, 10, 'They say to the seers, “Stop seeing visions!” and to the prophets, “Do not prophesy to us the truth! Speak to us pleasant words; prophesy illusions.'),
  ('BSB', 'Isaiah', 23, 30, 11, 'Get out of the way; turn off the road. Rid us of the Holy One of Israel!”'),
  ('BSB', 'Isaiah', 23, 30, 12, 'Therefore this is what the Holy One of Israel says: “Because you have rejected this message, trusting in oppression and relying on deceit,'),
  ('BSB', 'Isaiah', 23, 30, 13, 'this iniquity of yours is like a breach about to fail, a bulge in a high wall, whose collapse will come suddenly— in an instant!'),
  ('BSB', 'Isaiah', 23, 30, 14, 'It will break in pieces like a potter’s jar, shattered so that no fragment can be found. Not a shard will be found in the dust large enough to scoop the coals from a hearth or to skim the water from a cistern.”'),
  ('BSB', 'Isaiah', 23, 30, 15, 'For the Lord GOD, the Holy One of Israel, has said: “By repentance and rest you would be saved; your strength would lie in quiet confidence— but you were not willing.”'),
  ('BSB', 'Isaiah', 23, 30, 16, '“No,” you say, “we will flee on horses.” Therefore you will flee! “We will ride swift horses,” but your pursuers will be faster.'),
  ('BSB', 'Isaiah', 23, 30, 17, 'A thousand will flee at the threat of one; at the threat of five you will all flee, until you are left alone like a pole on a mountaintop, like a banner on a hill.'),
  ('BSB', 'Isaiah', 23, 30, 18, 'Therefore the LORD longs to be gracious to you; therefore He rises to show you compassion, for the LORD is a just God. Blessed are all who wait for Him.'),
  ('BSB', 'Isaiah', 23, 30, 19, 'O people in Zion who dwell in Jerusalem, you will weep no more. He will surely be gracious when you cry for help; when He hears, He will answer you.'),
  ('BSB', 'Isaiah', 23, 30, 20, 'The Lord will give you the bread of adversity and the water of affliction, but your Teacher will no longer hide Himself—with your own eyes you will see Him.'),
  ('BSB', 'Isaiah', 23, 30, 21, 'And whether you turn to the right or to the left, your ears will hear this command behind you: “This is the way. Walk in it.”'),
  ('BSB', 'Isaiah', 23, 30, 22, 'So you will desecrate your silver-plated idols and your gold-plated images. You will throw them away like menstrual cloths, saying to them, “Be gone!”'),
  ('BSB', 'Isaiah', 23, 30, 23, 'Then He will send rain for the seed that you have sown in the ground, and the food that comes from your land will be rich and plentiful. On that day your cattle will graze in open pastures.'),
  ('BSB', 'Isaiah', 23, 30, 24, 'The oxen and donkeys that work the ground will eat salted fodder, winnowed with shovel and pitchfork.'),
  ('BSB', 'Isaiah', 23, 30, 25, 'And from every high mountain and every raised hill, streams of water will flow in the day of great slaughter, when the towers fall.'),
  ('BSB', 'Isaiah', 23, 30, 26, 'The light of the moon will be as bright as the sun, and the light of the sun will be seven times brighter—like the light of seven days—on the day that the LORD binds up the brokenness of His people and heals the wounds He has inflicted.'),
  ('BSB', 'Isaiah', 23, 30, 27, 'Behold, the Name of the LORD comes from afar, with burning anger and dense smoke. His lips are full of fury, and His tongue is like a consuming fire.'),
  ('BSB', 'Isaiah', 23, 30, 28, 'His breath is like a rushing torrent that rises to the neck. He comes to sift the nations in a sieve of destruction; He bridles the jaws of the peoples to lead them astray.'),
  ('BSB', 'Isaiah', 23, 30, 29, 'You will sing as on the night of a holy festival, and your heart will rejoice like one who walks to the music of a flute, going up to the mountain of the LORD, to the Rock of Israel.'),
  ('BSB', 'Isaiah', 23, 30, 30, 'And the LORD will cause His majestic voice to be heard and His mighty arm to be revealed, striking in angry wrath with a flame of consuming fire, and with cloudburst, storm, and hailstones.'),
  ('BSB', 'Isaiah', 23, 30, 31, 'For Assyria will be shattered at the voice of the LORD; He will strike them with His scepter.'),
  ('BSB', 'Isaiah', 23, 30, 32, 'And with every stroke of the rod of punishment that the LORD brings down on them, the tambourines and lyres will sound as He battles with weapons brandished.'),
  ('BSB', 'Isaiah', 23, 30, 33, 'For Topheth has long been prepared; it has been made ready for the king. Its funeral pyre is deep and wide, with plenty of fire and wood. The breath of the LORD, like a torrent of burning sulfur, sets it ablaze.'),
  ('BSB', 'Isaiah', 23, 31, 1, 'Woe to those who go down to Egypt for help, who rely on horses, who trust in their abundance of chariots and in their multitude of horsemen. They do not look to the Holy One of Israel; they do not seek the LORD.'),
  ('BSB', 'Isaiah', 23, 31, 2, 'Yet He too is wise and brings disaster; He does not call back His words. He will rise up against the house of the wicked and against the allies of evildoers.'),
  ('BSB', 'Isaiah', 23, 31, 3, 'But the Egyptians are men, not God; their horses are flesh, not spirit. When the LORD stretches out His hand, the helper will stumble, and the one he helps will fall; both will perish together.'),
  ('BSB', 'Isaiah', 23, 31, 4, 'For this is what the LORD has said to me: “Like a lion roaring or a young lion over its prey— and though a band of shepherds is called out against it, it is not terrified by their shouting or subdued by their clamor— so the LORD of Hosts will come down to do battle on Mount Zion and its heights.'),
  ('BSB', 'Isaiah', 23, 31, 5, 'Like birds hovering overhead, so the LORD of Hosts will protect Jerusalem. He will shield it and deliver it; He will pass over it and preserve it.”'),
  ('BSB', 'Isaiah', 23, 31, 6, 'Return to the One against whom you have so blatantly rebelled, O children of Israel.'),
  ('BSB', 'Isaiah', 23, 31, 7, 'For on that day, every one of you will reject the idols of silver and gold that your own hands have sinfully made.'),
  ('BSB', 'Isaiah', 23, 31, 8, '“Then Assyria will fall, but not by the sword of man; a sword will devour them, but not one made by mortals. They will flee before the sword, and their young men will be put to forced labor.'),
  ('BSB', 'Isaiah', 23, 31, 9, 'Their rock will pass away for fear, and their princes will panic at the sight of the battle standard,” declares the LORD, whose fire is in Zion, whose furnace is in Jerusalem.'),
  ('BSB', 'Isaiah', 23, 32, 1, 'Behold, a king will reign in righteousness, and princes will rule with justice.'),
  ('BSB', 'Isaiah', 23, 32, 2, 'Each will be like a shelter from the wind, a refuge from the storm, like streams of water in a dry land, like the shadow of a great rock in an arid land.'),
  ('BSB', 'Isaiah', 23, 32, 3, 'Then the eyes of those who see will no longer be closed, and the ears of those who hear will listen.'),
  ('BSB', 'Isaiah', 23, 32, 4, 'The mind of the rash will know and understand, and the stammering tongue will speak clearly and fluently.'),
  ('BSB', 'Isaiah', 23, 32, 5, 'No longer will a fool be called noble, nor a scoundrel be respected.'),
  ('BSB', 'Isaiah', 23, 32, 6, 'For a fool speaks foolishness; his mind plots iniquity. He practices ungodliness and speaks falsely about the LORD; he leaves the hungry empty and deprives the thirsty of drink.'),
  ('BSB', 'Isaiah', 23, 32, 7, 'The weapons of the scoundrel are destructive; he hatches plots to destroy the poor with lies, even when the plea of the needy is just.'),
  ('BSB', 'Isaiah', 23, 32, 8, 'But a noble man makes honorable plans; he stands up for worthy causes.'),
  ('BSB', 'Isaiah', 23, 32, 9, 'Stand up, you complacent women; listen to me. Give ear to my word, you overconfident daughters.'),
  ('BSB', 'Isaiah', 23, 32, 10, 'In a little more than a year you will tremble, O secure ones. For the grape harvest will fail and the fruit harvest will not arrive.'),
  ('BSB', 'Isaiah', 23, 32, 11, 'Shudder, you ladies of leisure; tremble, you daughters of complacency. Strip yourselves bare and put sackcloth around your waists.'),
  ('BSB', 'Isaiah', 23, 32, 12, 'Beat your breasts for the pleasant fields, for the fruitful vines,'),
  ('BSB', 'Isaiah', 23, 32, 13, 'and for the land of my people, overgrown with thorns and briers— even for every house of merriment in this city of revelry.'),
  ('BSB', 'Isaiah', 23, 32, 14, 'For the palace will be forsaken, the busy city abandoned. The hill and the watchtower will become caves forever— the delight of wild donkeys and a pasture for flocks—'),
  ('BSB', 'Isaiah', 23, 32, 15, 'until the Spirit is poured out upon us from on high. Then the desert will be an orchard, and the orchard will seem like a forest.'),
  ('BSB', 'Isaiah', 23, 32, 16, 'Then justice will inhabit the wilderness, and righteousness will dwell in the fertile field.'),
  ('BSB', 'Isaiah', 23, 32, 17, 'The work of righteousness will be peace; the service of righteousness will be quiet confidence forever.'),
  ('BSB', 'Isaiah', 23, 32, 18, 'Then my people will dwell in a peaceful place, in safe and secure places of rest.'),
  ('BSB', 'Isaiah', 23, 32, 19, 'But hail will level the forest, and the city will sink to the depths.'),
  ('BSB', 'Isaiah', 23, 32, 20, 'Blessed are those who sow beside abundant waters, who let the ox and donkey range freely.'),
  ('BSB', 'Isaiah', 23, 33, 1, 'Woe to you, O destroyer never destroyed, O traitor never betrayed! When you have finished destroying, you will be destroyed. When you have finished betraying, you will be betrayed.'),
  ('BSB', 'Isaiah', 23, 33, 2, 'O LORD, be gracious to us! We wait for You. Be our strength every morning and our salvation in time of trouble.'),
  ('BSB', 'Isaiah', 23, 33, 3, 'The peoples flee the thunder of Your voice; the nations scatter when You rise.'),
  ('BSB', 'Isaiah', 23, 33, 4, 'Your spoil, O nations, is gathered as by locusts; like a swarm of locusts men sweep over it.'),
  ('BSB', 'Isaiah', 23, 33, 5, 'The LORD is exalted, for He dwells on high; He has filled Zion with justice and righteousness.'),
  ('BSB', 'Isaiah', 23, 33, 6, 'He will be the sure foundation for your times, a storehouse of salvation, wisdom, and knowledge. The fear of the LORD is Zion’s treasure.'),
  ('BSB', 'Isaiah', 23, 33, 7, 'Behold, their valiant ones cry aloud in the streets; the envoys of peace weep bitterly.'),
  ('BSB', 'Isaiah', 23, 33, 8, 'The highways are deserted; travel has ceased. The treaty has been broken, the witnesses are despised, and human life is disregarded.'),
  ('BSB', 'Isaiah', 23, 33, 9, 'The land mourns and languishes; Lebanon is ashamed and decayed. Sharon is like a desert; Bashan and Carmel shake off their leaves.'),
  ('BSB', 'Isaiah', 23, 33, 10, '“Now I will arise,” says the LORD. “Now I will lift Myself up. Now I will be exalted.'),
  ('BSB', 'Isaiah', 23, 33, 11, 'You conceive chaff; you give birth to stubble. Your breath is a fire that will consume you.'),
  ('BSB', 'Isaiah', 23, 33, 12, 'The peoples will be burned to ashes, like thorns cut down and set ablaze.'),
  ('BSB', 'Isaiah', 23, 33, 13, 'You who are far off, hear what I have done; you who are near, acknowledge My might.”'),
  ('BSB', 'Isaiah', 23, 33, 14, 'The sinners in Zion are afraid; trembling grips the ungodly: “Who of us can dwell with a consuming fire? Who of us can dwell with everlasting flames?”'),
  ('BSB', 'Isaiah', 23, 33, 15, 'He who walks righteously and speaks with sincerity, who refuses gain from extortion, whose hand never takes a bribe, who stops his ears against murderous plots and shuts his eyes tightly against evil—'),
  ('BSB', 'Isaiah', 23, 33, 16, 'he will dwell on the heights; the mountain fortress will be his refuge; his food will be provided and his water assured.'),
  ('BSB', 'Isaiah', 23, 33, 17, 'Your eyes will see the King in His beauty and behold a land that stretches afar.'),
  ('BSB', 'Isaiah', 23, 33, 18, 'Your mind will ponder the former terror: “Where is he who tallies? Where is he who weighs? Where is he who counts the towers?”'),
  ('BSB', 'Isaiah', 23, 33, 19, 'You will no longer see the insolent, a people whose speech is unintelligible, who stammer in a language you cannot understand.'),
  ('BSB', 'Isaiah', 23, 33, 20, 'Look upon Zion, the city of our appointed feasts. Your eyes will see Jerusalem, a peaceful pasture, a tent that does not wander; its tent pegs will not be pulled up, nor will any of its cords be broken.'),
  ('BSB', 'Isaiah', 23, 33, 21, 'But there the Majestic One, our LORD, will be for us a place of rivers and wide canals, where no galley with oars will row, and no majestic vessel will pass.'),
  ('BSB', 'Isaiah', 23, 33, 22, 'For the LORD is our Judge, the LORD is our lawgiver, the LORD is our King. It is He who will save us.'),
  ('BSB', 'Isaiah', 23, 33, 23, 'Your ropes are slack; they cannot secure the mast or spread the sail. Then an abundance of spoils will be divided, and even the lame will carry off plunder.'),
  ('BSB', 'Isaiah', 23, 33, 24, 'And no resident of Zion will say, “I am sick.” The people who dwell there will be forgiven of iniquity.'),
  ('BSB', 'Isaiah', 23, 34, 1, 'Come near, O nations, to listen; pay attention, O peoples. Let the earth hear, and all that fills it, the world and all that springs from it.'),
  ('BSB', 'Isaiah', 23, 34, 2, 'The LORD is angry with all the nations and furious with all their armies. He will devote them to destruction; He will give them over to slaughter.'),
  ('BSB', 'Isaiah', 23, 34, 3, 'Their slain will be left unburied, and the stench of their corpses will rise; the mountains will flow with their blood.'),
  ('BSB', 'Isaiah', 23, 34, 4, 'All the stars of heaven will be dissolved. The skies will be rolled up like a scroll, and all their stars will fall like withered leaves from the vine, like foliage from the fig tree.'),
  ('BSB', 'Isaiah', 23, 34, 5, 'When My sword has drunk its fill in the heavens, then it will come down upon Edom, upon the people I have devoted to destruction.'),
  ('BSB', 'Isaiah', 23, 34, 6, 'The sword of the LORD is bathed in blood. It drips with fat— with the blood of lambs and goats, with the fat of the kidneys of rams. For the LORD has a sacrifice in Bozrah, a great slaughter in the land of Edom.'),
  ('BSB', 'Isaiah', 23, 34, 7, 'And the wild oxen will fall with them, the young bulls with the strong ones. Their land will be drenched with blood, and their soil will be soaked with fat.'),
  ('BSB', 'Isaiah', 23, 34, 8, 'For the LORD has a day of vengeance, a year of recompense for the cause of Zion.'),
  ('BSB', 'Isaiah', 23, 34, 9, 'Edom’s streams will be turned to tar, and her soil to sulfur; her land will become a blazing pitch.'),
  ('BSB', 'Isaiah', 23, 34, 10, 'It will not be quenched—day or night. Its smoke will ascend forever. From generation to generation it will lie desolate; no one will ever again pass through it.'),
  ('BSB', 'Isaiah', 23, 34, 11, 'The desert owl and screech owl will possess it, and the great owl and raven will dwell in it. The LORD will stretch out over Edom a measuring line of chaos and a plumb line of destruction.'),
  ('BSB', 'Isaiah', 23, 34, 12, 'No nobles will be left to proclaim a king, and all her princes will come to nothing.'),
  ('BSB', 'Isaiah', 23, 34, 13, 'Her towers will be overgrown with thorns, her fortresses with thistles and briers. She will become a haunt for jackals, an abode for ostriches.'),
  ('BSB', 'Isaiah', 23, 34, 14, 'The desert creatures will meet with hyenas, and one wild goat will call to another. There the night creature will settle and find her place of repose.'),
  ('BSB', 'Isaiah', 23, 34, 15, 'There the owl will make her nest; she will lay and hatch her eggs and gather her brood under her shadow. Even there the birds of prey will gather, each with its mate.'),
  ('BSB', 'Isaiah', 23, 34, 16, 'Search and read the scroll of the LORD: Not one of these will go missing, not one will lack her mate, because He has ordered it by His mouth, and He will gather them by His Spirit.'),
  ('BSB', 'Isaiah', 23, 34, 17, 'He has allotted their portion; His hand has distributed it by measure. They will possess it forever; they will dwell in it from generation to generation.'),
  ('BSB', 'Isaiah', 23, 35, 1, 'The wilderness and the land will be glad; the desert will rejoice and blossom like a rose.'),
  ('BSB', 'Isaiah', 23, 35, 2, 'It will bloom profusely and rejoice with joy and singing. The glory of Lebanon will be given to it, the splendor of Carmel and Sharon. They will see the glory of the LORD, the splendor of our God.'),
  ('BSB', 'Isaiah', 23, 35, 3, 'Strengthen the limp hands and steady the feeble knees!'),
  ('BSB', 'Isaiah', 23, 35, 4, 'Say to those with anxious hearts: “Be strong, do not fear! Behold, your God will come with vengeance. With divine retribution He will come to save you.”'),
  ('BSB', 'Isaiah', 23, 35, 5, 'Then the eyes of the blind will be opened and the ears of the deaf unstopped.'),
  ('BSB', 'Isaiah', 23, 35, 6, 'Then the lame will leap like a deer and the mute tongue will shout for joy. For waters will gush forth in the wilderness, and streams in the desert.'),
  ('BSB', 'Isaiah', 23, 35, 7, 'The parched ground will become a pool, the thirsty land springs of water. In the haunt where jackals once lay, there will be grass and reeds and papyrus.'),
  ('BSB', 'Isaiah', 23, 35, 8, 'And there will be a highway called the Way of Holiness. The unclean will not travel it— only those who walk in the Way— and fools will not stray onto it.'),
  ('BSB', 'Isaiah', 23, 35, 9, 'No lion will be there, and no vicious beast will go up on it. Such will not be found there, but the redeemed will walk upon it.'),
  ('BSB', 'Isaiah', 23, 35, 10, 'So the redeemed of the LORD will return and enter Zion with singing, crowned with everlasting joy. Gladness and joy will overtake them, and sorrow and sighing will flee.'),
  ('BSB', 'Isaiah', 23, 36, 1, 'In the fourteenth year of Hezekiah’s reign, Sennacherib king of Assyria attacked and captured all the fortified cities of Judah.'),
  ('BSB', 'Isaiah', 23, 36, 2, 'And the king of Assyria sent the Rabshakeh, with a great army, from Lachish to King Hezekiah at Jerusalem. And he stopped by the aqueduct of the upper pool, on the road to the Launderer’s Field.'),
  ('BSB', 'Isaiah', 23, 36, 3, 'Then Eliakim son of Hilkiah the palace administrator, Shebna the scribe, and Joah son of Asaph the recorder, went out to him.'),
  ('BSB', 'Isaiah', 23, 36, 4, 'The Rabshakeh said to them, “Tell Hezekiah that this is what the great king, the king of Assyria, says: What is the basis of this confidence of yours?'),
  ('BSB', 'Isaiah', 23, 36, 5, 'You claim to have a strategy and strength for war, but these are empty words. In whom are you now trusting, that you have rebelled against me?'),
  ('BSB', 'Isaiah', 23, 36, 6, 'Look now, you are trusting in Egypt, that splintered reed of a staff that will pierce the hand of anyone who leans on it. Such is Pharaoh king of Egypt to all who trust in him.'),
  ('BSB', 'Isaiah', 23, 36, 7, 'But if you say to me, ‘We trust in the LORD our God,’ is He not the One whose high places and altars Hezekiah has removed, saying to Judah and Jerusalem, ‘You must worship before this altar’?'),
  ('BSB', 'Isaiah', 23, 36, 8, 'Now, therefore, make a bargain with my master, the king of Assyria. I will give you two thousand horses—if you can put riders on them!'),
  ('BSB', 'Isaiah', 23, 36, 9, 'For how can you repel a single officer among the least of my master’s servants when you depend on Egypt for chariots and horsemen?'),
  ('BSB', 'Isaiah', 23, 36, 10, 'So now, was it apart from the LORD that I have come up against this land to destroy it? The LORD Himself said to me, ‘Go up against this land and destroy it.’”'),
  ('BSB', 'Isaiah', 23, 36, 11, 'Then Eliakim, Shebna, and Joah said to the Rabshakeh, “Please speak to your servants in Aramaic, since we understand it. Do not speak to us in Hebrew in the hearing of the people on the wall.”'),
  ('BSB', 'Isaiah', 23, 36, 12, 'But the Rabshakeh replied, “Has my master sent me to speak these words only to you and your master, and not to the men sitting on the wall, who are destined with you to eat their own dung and drink their own urine?”'),
  ('BSB', 'Isaiah', 23, 36, 13, 'Then the Rabshakeh stood and called out loudly in Hebrew: “Hear the words of the great king, the king of Assyria!'),
  ('BSB', 'Isaiah', 23, 36, 14, 'This is what the king says: Do not let Hezekiah deceive you, for he cannot deliver you.'),
  ('BSB', 'Isaiah', 23, 36, 15, 'Do not let Hezekiah persuade you to trust in the LORD when he says, ‘The LORD will surely deliver us; this city will not be given into the hand of the king of Assyria.’'),
  ('BSB', 'Isaiah', 23, 36, 16, 'Do not listen to Hezekiah, for this is what the king of Assyria says: Make peace with me and come out to me. Then every one of you will eat from his own vine and his own fig tree, and drink water from his own cistern,'),
  ('BSB', 'Isaiah', 23, 36, 17, 'until I come and take you away to a land like your own—a land of grain and new wine, a land of bread and vineyards.'),
  ('BSB', 'Isaiah', 23, 36, 18, 'Do not let Hezekiah mislead you when he says, ‘The LORD will deliver us.’ Has the god of any nation ever delivered his land from the hand of the king of Assyria?'),
  ('BSB', 'Isaiah', 23, 36, 19, 'Where are the gods of Hamath and Arpad? Where are the gods of Sepharvaim? Have they delivered Samaria from my hand?'),
  ('BSB', 'Isaiah', 23, 36, 20, 'Who among all the gods of these lands has delivered his land from my hand? How then can the LORD deliver Jerusalem from my hand?”'),
  ('BSB', 'Isaiah', 23, 36, 21, 'But the people remained silent and did not answer a word, for Hezekiah had commanded, “Do not answer him.”'),
  ('BSB', 'Isaiah', 23, 36, 22, 'Then Hilkiah’s son Eliakim the palace administrator, Shebna the scribe, and Asaph’s son Joah the recorder came to Hezekiah with their clothes torn, and they relayed to him the words of the Rabshakeh.'),
  ('BSB', 'Isaiah', 23, 37, 1, 'On hearing this report, King Hezekiah tore his clothes, put on sackcloth, and entered the house of the LORD.'),
  ('BSB', 'Isaiah', 23, 37, 2, 'And he sent Eliakim the palace administrator, Shebna the scribe, and the leading priests, all wearing sackcloth, to the prophet Isaiah son of Amoz'),
  ('BSB', 'Isaiah', 23, 37, 3, 'to tell him, “This is what Hezekiah says: Today is a day of distress, rebuke, and disgrace; for children have come to the point of birth, but there is no strength to deliver them.'),
  ('BSB', 'Isaiah', 23, 37, 4, 'Perhaps the LORD your God will hear the words of the Rabshakeh, whom his master the king of Assyria has sent to defy the living God, and He will rebuke him for the words that the LORD your God has heard. Therefore lift up a prayer for the remnant that still survives.”'),
  ('BSB', 'Isaiah', 23, 37, 5, 'So the servants of King Hezekiah went to Isaiah,'),
  ('BSB', 'Isaiah', 23, 37, 6, 'who replied, “Tell your master that this is what the LORD says: ‘Do not be afraid of the words you have heard, with which the servants of the king of Assyria have blasphemed Me.'),
  ('BSB', 'Isaiah', 23, 37, 7, 'Behold, I will put a spirit in him so that he will hear a rumor and return to his own land, where I will cause him to fall by the sword.’”'),
  ('BSB', 'Isaiah', 23, 37, 8, 'When the Rabshakeh heard that the king of Assyria had left Lachish, he withdrew and found the king fighting against Libnah.'),
  ('BSB', 'Isaiah', 23, 37, 9, 'Now Sennacherib had been warned about Tirhakah king of Cush: “He has set out to fight against you.” On hearing this, Sennacherib sent messengers to Hezekiah, saying,'),
  ('BSB', 'Isaiah', 23, 37, 10, '“Give this message to Hezekiah king of Judah: ‘Do not let your God, in whom you trust, deceive you by saying that Jerusalem will not be delivered into the hand of the king of Assyria.'),
  ('BSB', 'Isaiah', 23, 37, 11, 'Surely you have heard what the kings of Assyria have done to all the other countries, devoting them to destruction. Will you then be spared?'),
  ('BSB', 'Isaiah', 23, 37, 12, 'Did the gods of the nations destroyed by my fathers rescue those nations—the gods of Gozan, Haran, and Rezeph, and of the people of Eden in Telassar?'),
  ('BSB', 'Isaiah', 23, 37, 13, 'Where are the kings of Hamath, Arpad, Sepharvaim, Hena, and Ivvah?’”'),
  ('BSB', 'Isaiah', 23, 37, 14, 'So Hezekiah received the letter from the messengers, read it, and went up to the house of the LORD and spread it out before the LORD.'),
  ('BSB', 'Isaiah', 23, 37, 15, 'And Hezekiah prayed to the LORD:'),
  ('BSB', 'Isaiah', 23, 37, 16, '“O LORD of Hosts, God of Israel, enthroned above the cherubim, You alone are God over all the kingdoms of the earth. You made the heavens and the earth.'),
  ('BSB', 'Isaiah', 23, 37, 17, 'Incline Your ear, O LORD, and hear; open Your eyes, O LORD, and see. Listen to all the words that Sennacherib has sent to defy the living God.'),
  ('BSB', 'Isaiah', 23, 37, 18, 'Truly, O LORD, the kings of Assyria have laid waste all these countries and their lands.'),
  ('BSB', 'Isaiah', 23, 37, 19, 'They have cast their gods into the fire and destroyed them, for they were not gods, but only wood and stone—the work of human hands.'),
  ('BSB', 'Isaiah', 23, 37, 20, 'And now, O LORD our God, save us from his hand, so that all the kingdoms of the earth may know that You alone, O LORD, are God.”'),
  ('BSB', 'Isaiah', 23, 37, 21, 'Then Isaiah son of Amoz sent a message to Hezekiah: “This is what the LORD, the God of Israel, says: Because you have prayed to Me concerning Sennacherib king of Assyria,'),
  ('BSB', 'Isaiah', 23, 37, 22, 'this is the word that the LORD has spoken against him: ‘The Virgin Daughter of Zion despises you and mocks you; the Daughter of Jerusalem shakes her head behind you.'),
  ('BSB', 'Isaiah', 23, 37, 23, 'Whom have you taunted and blasphemed? Against whom have you raised your voice and lifted your eyes in pride? Against the Holy One of Israel!'),
  ('BSB', 'Isaiah', 23, 37, 24, 'Through your servants you have taunted the Lord, and you have said: “With my many chariots I have ascended to the heights of the mountains, to the remote peaks of Lebanon. I have cut down its tallest cedars, the finest of its cypresses. I have reached its farthest heights, the densest of its forests.'),
  ('BSB', 'Isaiah', 23, 37, 25, 'I have dug wells and drunk foreign waters. With the soles of my feet I have dried up all the streams of Egypt.”'),
  ('BSB', 'Isaiah', 23, 37, 26, 'Have you not heard? Long ago I ordained it; in days of old I planned it. Now I have brought it to pass, that you should crush fortified cities into piles of rubble.'),
  ('BSB', 'Isaiah', 23, 37, 27, 'Therefore their inhabitants, devoid of power, are dismayed and ashamed. They are like plants in the field, tender green shoots, grass on the rooftops, scorched before it is grown.'),
  ('BSB', 'Isaiah', 23, 37, 28, 'But I know your sitting down, your going out and coming in, and your raging against Me.'),
  ('BSB', 'Isaiah', 23, 37, 29, 'Because your rage and arrogance against Me have reached My ears, I will put My hook in your nose and My bit in your mouth; I will send you back the way you came.’'),
  ('BSB', 'Isaiah', 23, 37, 30, 'And this will be a sign to you, O Hezekiah: This year you will eat what grows on its own, and in the second year what springs from the same. But in the third year you will sow and reap; you will plant vineyards and eat their fruit.'),
  ('BSB', 'Isaiah', 23, 37, 31, 'And the surviving remnant of the house of Judah will again take root below and bear fruit above.'),
  ('BSB', 'Isaiah', 23, 37, 32, 'For a remnant will go forth from Jerusalem, and survivors from Mount Zion. The zeal of the LORD of Hosts will accomplish this.'),
  ('BSB', 'Isaiah', 23, 37, 33, 'So this is what the LORD says about the king of Assyria: ‘He will not enter this city or shoot an arrow into it. He will not come before it with a shield or build up a siege ramp against it.'),
  ('BSB', 'Isaiah', 23, 37, 34, 'He will go back the way he came, and he will not enter this city,’ declares the LORD.'),
  ('BSB', 'Isaiah', 23, 37, 35, '‘I will defend this city and save it for My own sake and for the sake of My servant David.’”'),
  ('BSB', 'Isaiah', 23, 37, 36, 'Then the angel of the LORD went out and struck down 185,000 men in the camp of the Assyrians. When the people got up the next morning, there were all the dead bodies!'),
  ('BSB', 'Isaiah', 23, 37, 37, 'So Sennacherib king of Assyria broke camp and withdrew. He returned to Nineveh and stayed there.'),
  ('BSB', 'Isaiah', 23, 37, 38, 'One day, while he was worshiping in the temple of his god Nisroch, his sons Adrammelech and Sharezer put him to the sword and escaped to the land of Ararat. And his son Esar-haddon reigned in his place.'),
  ('BSB', 'Isaiah', 23, 38, 1, 'In those days Hezekiah became mortally ill. The prophet Isaiah son of Amoz came to him and said, “This is what the LORD says: ‘Put your house in order, for you are about to die; you will not recover.’”'),
  ('BSB', 'Isaiah', 23, 38, 2, 'Then Hezekiah turned his face to the wall and prayed to the LORD,'),
  ('BSB', 'Isaiah', 23, 38, 3, 'saying, “Please, O LORD, remember how I have walked before You faithfully and with wholehearted devotion; I have done what was good in Your sight.” And Hezekiah wept bitterly.'),
  ('BSB', 'Isaiah', 23, 38, 4, 'And the word of the LORD came to Isaiah, saying,'),
  ('BSB', 'Isaiah', 23, 38, 5, '“Go and tell Hezekiah that this is what the LORD, the God of your father David, says: ‘I have heard your prayer; I have seen your tears. Behold, I will add fifteen years to your life.'),
  ('BSB', 'Isaiah', 23, 38, 6, 'And I will deliver you and this city from the hand of the king of Assyria. I will defend this city.'),
  ('BSB', 'Isaiah', 23, 38, 7, 'This will be a sign to you from the LORD that He will do what He has promised:'),
  ('BSB', 'Isaiah', 23, 38, 8, 'I will make the sun’s shadow that falls on the stairway of Ahaz go back ten steps.’” So the sunlight went back the ten steps it had descended.'),
  ('BSB', 'Isaiah', 23, 38, 9, 'This is a writing by Hezekiah king of Judah after his illness and recovery:');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Isaiah', 23, 38, 10, 'I said, “In the prime of my life I must go through the gates of Sheol and be deprived of the remainder of my years.”'),
  ('BSB', 'Isaiah', 23, 38, 11, 'I said, “I will never again see the LORD, even the LORD, in the land of the living; I will no longer look on mankind with those who dwell in this world.'),
  ('BSB', 'Isaiah', 23, 38, 12, 'My dwelling has been picked up and removed from me like a shepherd’s tent. I have rolled up my life like a weaver; He cuts me off from the loom; from day until night You make an end of me.'),
  ('BSB', 'Isaiah', 23, 38, 13, 'I composed myself until the morning. Like a lion He breaks all my bones; from day until night You make an end of me.'),
  ('BSB', 'Isaiah', 23, 38, 14, 'I chirp like a swallow or crane; I moan like a dove. My eyes grow weak as I look upward. O Lord, I am oppressed; be my security.”'),
  ('BSB', 'Isaiah', 23, 38, 15, 'What can I say? He has spoken to me, and He Himself has done this. I will walk slowly all my years because of the anguish of my soul.'),
  ('BSB', 'Isaiah', 23, 38, 16, 'O Lord, by such things men live, and in all of them my spirit finds life. You have restored me to health and have let me live.'),
  ('BSB', 'Isaiah', 23, 38, 17, 'Surely for my own welfare I had such great anguish; but Your love has delivered me from the pit of oblivion, for You have cast all my sins behind Your back.'),
  ('BSB', 'Isaiah', 23, 38, 18, 'For Sheol cannot thank You; Death cannot praise You. Those who descend to the Pit cannot hope for Your faithfulness.'),
  ('BSB', 'Isaiah', 23, 38, 19, 'The living, only the living, can thank You, as I do today; fathers will tell their children about Your faithfulness.'),
  ('BSB', 'Isaiah', 23, 38, 20, 'The LORD will save me; we will play songs on stringed instruments all the days of our lives in the house of the LORD.'),
  ('BSB', 'Isaiah', 23, 38, 21, 'Now Isaiah had said, “Prepare a lump of pressed figs and apply it to the boil, and he will recover.”'),
  ('BSB', 'Isaiah', 23, 38, 22, 'And Hezekiah had asked, “What will be the sign that I will go up to the house of the LORD?”'),
  ('BSB', 'Isaiah', 23, 39, 1, 'At that time Merodach-baladan son of Baladan king of Babylon sent letters and a gift to Hezekiah, for he had heard about Hezekiah’s illness and recovery.'),
  ('BSB', 'Isaiah', 23, 39, 2, 'And Hezekiah welcomed the envoys gladly and showed them what was in his treasure house—the silver, the gold, the spices, and the precious oil, as well as his entire armory—all that was found in his storehouses. There was nothing in his palace or in all his dominion that Hezekiah did not show them.'),
  ('BSB', 'Isaiah', 23, 39, 3, 'Then the prophet Isaiah went to King Hezekiah and asked, “Where did those men come from, and what did they say to you?” “They came to me from a distant land,” Hezekiah replied, “from Babylon.”'),
  ('BSB', 'Isaiah', 23, 39, 4, '“What have they seen in your palace?” Isaiah asked. “They have seen everything in my palace,” answered Hezekiah. “There is nothing among my treasures that I did not show them.”'),
  ('BSB', 'Isaiah', 23, 39, 5, 'Then Isaiah said to Hezekiah, “Hear the word of the LORD of Hosts:'),
  ('BSB', 'Isaiah', 23, 39, 6, 'The time will surely come when everything in your palace and all that your fathers have stored up until this day will be carried off to Babylon. Nothing will be left, says the LORD.'),
  ('BSB', 'Isaiah', 23, 39, 7, 'And some of your descendants, your own flesh and blood, will be taken away to be eunuchs in the palace of the king of Babylon.”'),
  ('BSB', 'Isaiah', 23, 39, 8, 'But Hezekiah said to Isaiah, “The word of the LORD that you have spoken is good.” For he thought, “At least there will be peace and security in my lifetime.”'),
  ('BSB', 'Isaiah', 23, 40, 1, '“Comfort, comfort My people,” says your God.'),
  ('BSB', 'Isaiah', 23, 40, 2, '“Speak tenderly to Jerusalem, and proclaim to her that her forced labor has been completed; her iniquity has been pardoned. For she has received from the hand of the LORD double for all her sins.”'),
  ('BSB', 'Isaiah', 23, 40, 3, 'A voice of one calling: “Prepare the way for the LORD in the wilderness; make a straight highway for our God in the desert.'),
  ('BSB', 'Isaiah', 23, 40, 4, 'Every valley shall be lifted up, and every mountain and hill made low; the uneven ground will become smooth, and the rugged land a plain.'),
  ('BSB', 'Isaiah', 23, 40, 5, 'And the glory of the LORD will be revealed, and all humanity together will see it. For the mouth of the LORD has spoken.”'),
  ('BSB', 'Isaiah', 23, 40, 6, 'A voice says, “Cry out!” And I asked, “What should I cry out?” “All flesh is like grass, and all its glory like the flowers of the field.'),
  ('BSB', 'Isaiah', 23, 40, 7, 'The grass withers and the flowers fall when the breath of the LORD blows on them; indeed, the people are grass.'),
  ('BSB', 'Isaiah', 23, 40, 8, 'The grass withers and the flowers fall, but the word of our God stands forever.”'),
  ('BSB', 'Isaiah', 23, 40, 9, 'Go up on a high mountain, O Zion, herald of good news. Raise your voice loudly, O Jerusalem, herald of good news. Lift it up, do not be afraid! Say to the cities of Judah, “Here is your God!”'),
  ('BSB', 'Isaiah', 23, 40, 10, 'Behold, the Lord GOD comes with might, and His arm establishes His rule. His reward is with Him, and His recompense accompanies Him.'),
  ('BSB', 'Isaiah', 23, 40, 11, 'He tends His flock like a shepherd; He gathers the lambs in His arms and carries them close to His heart. He gently leads the nursing ewes.'),
  ('BSB', 'Isaiah', 23, 40, 12, 'Who has measured the waters in the hollow of his hand, or marked off the heavens with the span of his hand? Who has held the dust of the earth in a basket, or weighed the mountains on a scale and the hills with a balance?'),
  ('BSB', 'Isaiah', 23, 40, 13, 'Who has directed the Spirit of the LORD, or informed Him as His counselor?'),
  ('BSB', 'Isaiah', 23, 40, 14, 'Whom did He consult to enlighten Him, and who taught Him the paths of justice? Who imparted knowledge to Him and showed Him the way of understanding?'),
  ('BSB', 'Isaiah', 23, 40, 15, 'Surely the nations are like a drop in a bucket; they are considered a speck of dust on the scales; He lifts up the islands like fine dust.'),
  ('BSB', 'Isaiah', 23, 40, 16, 'Lebanon is not sufficient for fuel, nor its animals enough for a burnt offering.'),
  ('BSB', 'Isaiah', 23, 40, 17, 'All the nations are as nothing before Him; He regards them as nothingness and emptiness.'),
  ('BSB', 'Isaiah', 23, 40, 18, 'To whom will you liken God? To what image will you compare Him?'),
  ('BSB', 'Isaiah', 23, 40, 19, 'To an idol that a craftsman casts and a metalworker overlays with gold and fits with silver chains?'),
  ('BSB', 'Isaiah', 23, 40, 20, 'To one bereft of an offering who chooses wood that will not rot, who seeks a skilled craftsman to set up an idol that will not topple?'),
  ('BSB', 'Isaiah', 23, 40, 21, 'Do you not know? Have you not heard? Has it not been declared to you from the beginning? Have you not understood since the foundation of the earth?'),
  ('BSB', 'Isaiah', 23, 40, 22, 'He sits enthroned above the circle of the earth; its dwellers are like grasshoppers. He stretches out the heavens like a curtain, and spreads them out like a tent to dwell in.'),
  ('BSB', 'Isaiah', 23, 40, 23, 'He brings the princes to nothing and makes the rulers of the earth meaningless.'),
  ('BSB', 'Isaiah', 23, 40, 24, 'No sooner are they planted, no sooner are they sown, no sooner have their stems taken root in the ground, than He blows on them and they wither, and a whirlwind sweeps them away like stubble.'),
  ('BSB', 'Isaiah', 23, 40, 25, '“To whom will you liken Me, or who is My equal?” asks the Holy One.'),
  ('BSB', 'Isaiah', 23, 40, 26, 'Lift up your eyes on high: Who created all these? He leads forth the starry host by number; He calls each one by name. Because of His great power and mighty strength, not one of them is missing.'),
  ('BSB', 'Isaiah', 23, 40, 27, 'Why do you say, O Jacob, and why do you assert, O Israel, “My way is hidden from the LORD, and my claim is ignored by my God”?'),
  ('BSB', 'Isaiah', 23, 40, 28, 'Do you not know? Have you not heard? The LORD is the everlasting God, the Creator of the ends of the earth. He will not grow tired or weary; His understanding is beyond searching out.'),
  ('BSB', 'Isaiah', 23, 40, 29, 'He gives power to the faint and increases the strength of the weak.'),
  ('BSB', 'Isaiah', 23, 40, 30, 'Even youths grow tired and weary, and young men stumble and fall.'),
  ('BSB', 'Isaiah', 23, 40, 31, 'But those who wait upon the LORD will renew their strength; they will mount up with wings like eagles; they will run and not grow weary, they will walk and not faint.'),
  ('BSB', 'Isaiah', 23, 41, 1, '“Be silent before Me, O islands, and let the peoples renew their strength. Let them come forward and testify; let us together draw near for judgment.'),
  ('BSB', 'Isaiah', 23, 41, 2, 'Who has aroused one from the east and called him to his feet in righteousness? He hands nations over to him and subdues kings before him. He turns them to dust with his sword, to windblown chaff with his bow.'),
  ('BSB', 'Isaiah', 23, 41, 3, 'He pursues them, going on safely, hardly touching the path with his feet.'),
  ('BSB', 'Isaiah', 23, 41, 4, 'Who has performed this and carried it out, calling forth the generations from the beginning? I, the LORD—the first and the last— I am He.”'),
  ('BSB', 'Isaiah', 23, 41, 5, 'The islands see and fear; the ends of the earth tremble. They approach and come forward.'),
  ('BSB', 'Isaiah', 23, 41, 6, 'Each one helps the other and says to his brother, “Be strong!”'),
  ('BSB', 'Isaiah', 23, 41, 7, 'The craftsman encourages the goldsmith, and he who wields the hammer cheers him who strikes the anvil, saying of the welding, “It is good.” He nails it down so it will not be toppled.'),
  ('BSB', 'Isaiah', 23, 41, 8, '“But you, O Israel, My servant, Jacob, whom I have chosen, descendant of Abraham My friend—'),
  ('BSB', 'Isaiah', 23, 41, 9, 'I brought you from the ends of the earth and called you from its farthest corners. I said, ‘You are My servant.’ I have chosen and not rejected you.'),
  ('BSB', 'Isaiah', 23, 41, 10, 'Do not fear, for I am with you; do not be afraid, for I am your God. I will strengthen you; I will surely help you; I will uphold you with My right hand of righteousness.'),
  ('BSB', 'Isaiah', 23, 41, 11, 'Behold, all who rage against you will be ashamed and disgraced; those who contend with you will be reduced to nothing and will perish.'),
  ('BSB', 'Isaiah', 23, 41, 12, 'You will seek them but will not find them. Those who wage war against you will come to nothing.'),
  ('BSB', 'Isaiah', 23, 41, 13, 'For I am the LORD your God, who takes hold of your right hand and tells you: Do not fear, I will help you.'),
  ('BSB', 'Isaiah', 23, 41, 14, 'Do not fear, O worm of Jacob, O few men of Israel. I will help you,” declares the LORD. “Your Redeemer is the Holy One of Israel.'),
  ('BSB', 'Isaiah', 23, 41, 15, 'Behold, I will make you into a threshing sledge, new and sharp, with many teeth. You will thresh the mountains and crush them, and reduce the hills to chaff.'),
  ('BSB', 'Isaiah', 23, 41, 16, 'You will winnow them, and a wind will carry them away; a gale will scatter them. But you will rejoice in the LORD; you will glory in the Holy One of Israel.'),
  ('BSB', 'Isaiah', 23, 41, 17, 'The poor and needy seek water, but there is none; their tongues are parched with thirst. I, the LORD, will answer them; I, the God of Israel, will not forsake them.'),
  ('BSB', 'Isaiah', 23, 41, 18, 'I will open rivers on the barren heights, and fountains in the middle of the valleys. I will turn the desert into a pool of water, and the dry land into flowing springs.'),
  ('BSB', 'Isaiah', 23, 41, 19, 'I will plant cedars in the wilderness, acacias, myrtles, and olive trees. I will set cypresses in the desert, elms and boxwood together,'),
  ('BSB', 'Isaiah', 23, 41, 20, 'so that all may see and know, may consider and understand, that the hand of the LORD has done this and the Holy One of Israel has created it.”'),
  ('BSB', 'Isaiah', 23, 41, 21, '“Present your case,” says the LORD. “Submit your arguments,” says the King of Jacob.'),
  ('BSB', 'Isaiah', 23, 41, 22, '“Let them come and tell us what will happen. Tell the former things, so that we may reflect on them and know the outcome. Or announce to us what is coming.'),
  ('BSB', 'Isaiah', 23, 41, 23, 'Tell us the things that are to come, so that we may know that you are gods. Yes, do something good or evil, that we may look on together in dismay.'),
  ('BSB', 'Isaiah', 23, 41, 24, 'Behold, you are nothing and your work is of no value. Anyone who chooses you is detestable.'),
  ('BSB', 'Isaiah', 23, 41, 25, 'I have raised up one from the north, and he has come— one from the east who calls on My name. He will march over rulers as if they were mortar, like a potter who treads the clay.'),
  ('BSB', 'Isaiah', 23, 41, 26, 'Who has declared this from the beginning, so that we may know, and from times past, so that we may say: ‘He was right’? No one announced it, no one foretold it, no one heard your words.'),
  ('BSB', 'Isaiah', 23, 41, 27, 'I was the first to tell Zion: ‘Look, here they are!’ And I gave to Jerusalem a herald of good news.'),
  ('BSB', 'Isaiah', 23, 41, 28, 'When I look, there is no one; there is no counselor among them; when I ask them, they have nothing to say.'),
  ('BSB', 'Isaiah', 23, 41, 29, 'See, they are all a delusion; their works amount to nothing; their images are as empty as the wind.'),
  ('BSB', 'Isaiah', 23, 42, 1, '“Here is My Servant, whom I uphold, My Chosen One, in whom My soul delights. I will put My Spirit on Him, and He will bring justice to the nations.'),
  ('BSB', 'Isaiah', 23, 42, 2, 'He will not cry out or raise His voice, nor make His voice heard in the streets.'),
  ('BSB', 'Isaiah', 23, 42, 3, 'A bruised reed He will not break and a smoldering wick He will not extinguish; He will faithfully bring forth justice.'),
  ('BSB', 'Isaiah', 23, 42, 4, 'He will not grow weak or discouraged before He has established justice on the earth. In His law the islands will put their hope.”'),
  ('BSB', 'Isaiah', 23, 42, 5, 'This is what God the LORD says— He who created the heavens and stretched them out, who spread out the earth and its offspring, who gives breath to the people on it and life to those who walk in it:'),
  ('BSB', 'Isaiah', 23, 42, 6, '“I, the LORD, have called you for a righteous purpose, and I will take hold of your hand. I will keep you and appoint you to be a covenant for the people and a light to the nations,'),
  ('BSB', 'Isaiah', 23, 42, 7, 'to open the eyes of the blind, to bring prisoners out of the dungeon and those sitting in darkness out from the prison house.'),
  ('BSB', 'Isaiah', 23, 42, 8, 'I am the LORD; that is My name! I will not yield My glory to another or My praise to idols.'),
  ('BSB', 'Isaiah', 23, 42, 9, 'Behold, the former things have happened, and now I declare new things. Before they spring forth I proclaim them to you.”'),
  ('BSB', 'Isaiah', 23, 42, 10, 'Sing to the LORD a new song— His praise from the ends of the earth— you who go down to the sea, and all that is in it, you islands, and all who dwell in them.'),
  ('BSB', 'Isaiah', 23, 42, 11, 'Let the desert and its cities raise their voices; let the villages of Kedar cry aloud. Let the people of Sela sing for joy; let them cry out from the mountaintops.'),
  ('BSB', 'Isaiah', 23, 42, 12, 'Let them give glory to the LORD and declare His praise in the islands.'),
  ('BSB', 'Isaiah', 23, 42, 13, 'The LORD goes forth like a mighty one; He stirs up His zeal like a warrior. He shouts; yes, He roars in triumph over His enemies:'),
  ('BSB', 'Isaiah', 23, 42, 14, '“I have kept silent from ages past; I have remained quiet and restrained. But now I will groan like a woman in labor; I will at once gasp and pant.'),
  ('BSB', 'Isaiah', 23, 42, 15, 'I will lay waste the mountains and hills and dry up all their vegetation. I will turn the rivers into dry land and drain the marshes.'),
  ('BSB', 'Isaiah', 23, 42, 16, 'I will lead the blind by a way they did not know; I will guide them on unfamiliar paths. I will turn darkness into light before them and rough places into level ground. These things I will do for them, and I will not forsake them.'),
  ('BSB', 'Isaiah', 23, 42, 17, 'But those who trust in idols and say to molten images, ‘You are our gods!’ will be turned back in utter shame.'),
  ('BSB', 'Isaiah', 23, 42, 18, 'Listen, you deaf ones; look, you blind ones, that you may see!'),
  ('BSB', 'Isaiah', 23, 42, 19, 'Who is blind but My servant, or deaf like the messenger I am sending? Who is blind like My covenant partner, or blind like the servant of the LORD?'),
  ('BSB', 'Isaiah', 23, 42, 20, 'Though seeing many things, you do not keep watch. Though your ears are open, you do not hear.”'),
  ('BSB', 'Isaiah', 23, 42, 21, 'The LORD was pleased, for the sake of His righteousness, to magnify His law and make it glorious.'),
  ('BSB', 'Isaiah', 23, 42, 22, 'But this is a people plundered and looted, all trapped in caves or imprisoned in dungeons. They have become plunder with no one to rescue them, and loot with no one to say, “Send them back!”'),
  ('BSB', 'Isaiah', 23, 42, 23, 'Who among you will pay attention to this? Who will listen and obey hereafter?'),
  ('BSB', 'Isaiah', 23, 42, 24, 'Who gave Jacob up for spoil, and Israel to the plunderers? Was it not the LORD, against whom we have sinned? They were unwilling to walk in His ways, and they would not obey His law.'),
  ('BSB', 'Isaiah', 23, 42, 25, 'So He poured out on them His furious anger and the fierceness of battle. It enveloped them in flames, but they did not understand; it consumed them, but they did not take it to heart.'),
  ('BSB', 'Isaiah', 23, 43, 1, 'Now this is what the LORD says— He who created you, O Jacob, and He who formed you, O Israel: “Do not fear, for I have redeemed you; I have called you by your name; you are Mine!'),
  ('BSB', 'Isaiah', 23, 43, 2, 'When you pass through the waters, I will be with you; and when you go through the rivers, they will not overwhelm you. When you walk through the fire, you will not be scorched; the flames will not set you ablaze.'),
  ('BSB', 'Isaiah', 23, 43, 3, 'For I am the LORD your God, the Holy One of Israel, your Savior; I give Egypt for your ransom, Cush and Seba in your place.'),
  ('BSB', 'Isaiah', 23, 43, 4, 'Because you are precious and honored in My sight, and because I love you, I will give men in exchange for you and nations in place of your life.'),
  ('BSB', 'Isaiah', 23, 43, 5, 'Do not be afraid, for I am with you; I will bring your offspring from the east and gather you from the west.'),
  ('BSB', 'Isaiah', 23, 43, 6, 'I will say to the north, ‘Give them up!’ and to the south, ‘Do not hold them back!’ Bring My sons from afar, and My daughters from the ends of the earth—'),
  ('BSB', 'Isaiah', 23, 43, 7, 'everyone called by My name and created for My glory, whom I have indeed formed and made.”'),
  ('BSB', 'Isaiah', 23, 43, 8, 'Bring out a people who have eyes but are blind, and who have ears but are deaf.'),
  ('BSB', 'Isaiah', 23, 43, 9, 'All the nations gather together and the peoples assemble. Who among them can declare this, and proclaim to us the former things? Let them present their witnesses to vindicate them, so that others may hear and say, “It is true.”'),
  ('BSB', 'Isaiah', 23, 43, 10, '“You are My witnesses,” declares the LORD, “and My servant whom I have chosen, so that you may consider and believe Me and understand that I am He. Before Me no god was formed, and after Me none will come.'),
  ('BSB', 'Isaiah', 23, 43, 11, 'I, yes I, am the LORD, and there is no Savior but Me.'),
  ('BSB', 'Isaiah', 23, 43, 12, 'I alone decreed and saved and proclaimed— I, and not some foreign god among you. So you are My witnesses,” declares the LORD, “that I am God.'),
  ('BSB', 'Isaiah', 23, 43, 13, 'Even from eternity I am He, and none can deliver out of My hand. When I act, who can reverse it?”'),
  ('BSB', 'Isaiah', 23, 43, 14, 'Thus says the LORD your Redeemer, the Holy One of Israel: “For your sake, I will send to Babylon and bring them all as fugitives, even the Chaldeans, in the ships in which they rejoice.'),
  ('BSB', 'Isaiah', 23, 43, 15, 'I am the LORD, your Holy One, the Creator of Israel, and your King.”'),
  ('BSB', 'Isaiah', 23, 43, 16, 'Thus says the LORD, who makes a way in the sea and a path through the surging waters,'),
  ('BSB', 'Isaiah', 23, 43, 17, 'who brings out the chariots and horses, the armies and warriors together, to lie down, never to rise again; to be extinguished, snuffed out like a wick:'),
  ('BSB', 'Isaiah', 23, 43, 18, '“Do not call to mind the former things; pay no attention to the things of old.'),
  ('BSB', 'Isaiah', 23, 43, 19, 'Behold, I am about to do something new; even now it is coming. Do you not see it? Indeed, I will make a way in the wilderness and streams in the desert.'),
  ('BSB', 'Isaiah', 23, 43, 20, 'The beasts of the field will honor Me, the jackals and the ostriches, because I provide water in the wilderness and rivers in the desert, to give drink to My chosen people.'),
  ('BSB', 'Isaiah', 23, 43, 21, 'The people I formed for Myself will declare My praise.'),
  ('BSB', 'Isaiah', 23, 43, 22, 'But you have not called on Me, O Jacob, because you have grown weary of Me, O Israel.'),
  ('BSB', 'Isaiah', 23, 43, 23, 'You have not brought Me sheep for burnt offerings, nor honored Me with your sacrifices. I have not burdened you with offerings, nor wearied you with frankincense.'),
  ('BSB', 'Isaiah', 23, 43, 24, 'You have not bought Me sweet cane with your silver, nor satisfied Me with the fat of your sacrifices. But you have burdened Me with your sins; you have wearied Me with your iniquities.'),
  ('BSB', 'Isaiah', 23, 43, 25, 'I, yes I, am He who blots out your transgressions for My own sake and remembers your sins no more.'),
  ('BSB', 'Isaiah', 23, 43, 26, 'Remind Me, let us argue the matter together. State your case, so that you may be vindicated.'),
  ('BSB', 'Isaiah', 23, 43, 27, 'Your first father sinned, and your spokesmen rebelled against Me.'),
  ('BSB', 'Isaiah', 23, 43, 28, 'So I will disgrace the princes of your sanctuary, and I will devote Jacob to destruction and Israel to reproach.”'),
  ('BSB', 'Isaiah', 23, 44, 1, 'But now listen, O Jacob My servant, Israel, whom I have chosen.'),
  ('BSB', 'Isaiah', 23, 44, 2, 'This is the word of the LORD, your Maker, who formed you from the womb and who will help you: “Do not be afraid, O Jacob My servant, Jeshurun, whom I have chosen.'),
  ('BSB', 'Isaiah', 23, 44, 3, 'For I will pour water on the thirsty land, and currents on the dry ground. I will pour out My Spirit on your descendants, and My blessing on your offspring.'),
  ('BSB', 'Isaiah', 23, 44, 4, 'They will sprout among the grass like willows by flowing streams.'),
  ('BSB', 'Isaiah', 23, 44, 5, 'One will say, ‘I belong to the LORD,’ another will call himself by the name of Jacob, and still another will write on his hand, ‘The LORD’s,’ and will take the name of Israel.”'),
  ('BSB', 'Isaiah', 23, 44, 6, 'Thus says the LORD, the King and Redeemer of Israel, the LORD of Hosts: “I am the first and I am the last, and there is no God but Me.'),
  ('BSB', 'Isaiah', 23, 44, 7, 'Who then is like Me? Let him say so! Let him declare his case before Me, since I established an ancient people. Let him foretell the things to come, and what is to take place.'),
  ('BSB', 'Isaiah', 23, 44, 8, 'Do not tremble or fear. Have I not told you and declared it long ago? You are My witnesses! Is there any God but Me? There is no other Rock; I know not one.”'),
  ('BSB', 'Isaiah', 23, 44, 9, 'All makers of idols are nothing, and the things they treasure are worthless. Their witnesses fail to see or comprehend, so they are put to shame.'),
  ('BSB', 'Isaiah', 23, 44, 10, 'Who fashions a god or casts an idol which profits him nothing?'),
  ('BSB', 'Isaiah', 23, 44, 11, 'Behold, all his companions will be put to shame, for the craftsmen themselves are only human. Let them all assemble and take their stand; they will all be brought to terror and shame.'),
  ('BSB', 'Isaiah', 23, 44, 12, 'The blacksmith takes a tool and labors over the coals; he fashions an idol with hammers and forges it with his strong arms. Yet he grows hungry and loses his strength; he fails to drink water and grows faint.'),
  ('BSB', 'Isaiah', 23, 44, 13, 'The woodworker extends a measuring line; he marks it out with a stylus; he shapes it with chisels and outlines it with a compass. He fashions it in the likeness of man, like man in all his glory, that it may dwell in a shrine.'),
  ('BSB', 'Isaiah', 23, 44, 14, 'He cuts down cedars or retrieves a cypress or oak. He lets it grow strong among the trees of the forest. He plants a laurel, and the rain makes it grow.'),
  ('BSB', 'Isaiah', 23, 44, 15, 'It serves as fuel for man. He takes some of it to warm himself, and he kindles a fire and bakes his bread; he even fashions it into a god and worships it; he makes an idol and bows down to it.'),
  ('BSB', 'Isaiah', 23, 44, 16, 'He burns half of it in the fire, and he roasts meat on that half. He eats the roast and is satisfied. Indeed, he warms himself and says, “Ah! I am warm; I see the fire.”'),
  ('BSB', 'Isaiah', 23, 44, 17, 'From the rest he makes a god, his graven image. He bows down to it and worships; he prays to it and says, “Save me, for you are my god.”'),
  ('BSB', 'Isaiah', 23, 44, 18, 'They do not comprehend or discern, for He has shut their eyes so they cannot see and closed their minds so they cannot understand.'),
  ('BSB', 'Isaiah', 23, 44, 19, 'And no one considers in his heart, no one has the knowledge or insight to say, “I burned half of it in the fire, and I baked bread on its coals; I roasted meat and I ate. Shall I make something detestable with the rest of it? Shall I bow down to a block of wood?”'),
  ('BSB', 'Isaiah', 23, 44, 20, 'He feeds on ashes. His deluded heart has led him astray, and he cannot deliver himself or say, “Is not this thing in my right hand a lie?”'),
  ('BSB', 'Isaiah', 23, 44, 21, 'Remember these things, O Jacob, for you are My servant, O Israel. I have made you, and you are My servant; O Israel, I will never forget you.'),
  ('BSB', 'Isaiah', 23, 44, 22, 'I have blotted out your transgressions like a cloud, and your sins like a mist. Return to Me, for I have redeemed you.'),
  ('BSB', 'Isaiah', 23, 44, 23, 'Sing for joy, O heavens, for the LORD has done this; shout aloud, O depths of the earth. Break forth in song, O mountains, you forests and all your trees. For the LORD has redeemed Jacob, and revealed His glory in Israel.'),
  ('BSB', 'Isaiah', 23, 44, 24, 'Thus says the LORD, your Redeemer who formed you from the womb: “I am the LORD, who has made all things, who alone stretched out the heavens, who by Myself spread out the earth,'),
  ('BSB', 'Isaiah', 23, 44, 25, 'who foils the signs of false prophets and makes fools of diviners, who confounds the wise and turns their knowledge into nonsense,'),
  ('BSB', 'Isaiah', 23, 44, 26, 'who confirms the message of His servant and fulfills the counsel of His messengers, who says of Jerusalem, ‘She will be inhabited,’ and of the cities of Judah, ‘They will be rebuilt, and I will restore their ruins,’'),
  ('BSB', 'Isaiah', 23, 44, 27, 'who says to the depths of the sea, ‘Be dry, and I will dry up your currents,’'),
  ('BSB', 'Isaiah', 23, 44, 28, 'who says of Cyrus, ‘My shepherd will fulfill all that I desire,’ who says of Jerusalem, ‘She will be rebuilt,’ and of the temple, ‘Let its foundation be laid.’”'),
  ('BSB', 'Isaiah', 23, 45, 1, 'This is what the LORD says to Cyrus His anointed, whose right hand I have grasped to subdue nations before him, to disarm kings, to open the doors before him, so that the gates will not be shut:'),
  ('BSB', 'Isaiah', 23, 45, 2, '“I will go before you and level the mountains; I will break down the gates of bronze and cut through the bars of iron.'),
  ('BSB', 'Isaiah', 23, 45, 3, 'I will give you the treasures of darkness and the riches hidden in secret places, so that you may know that I am the LORD, the God of Israel, who calls you by name.'),
  ('BSB', 'Isaiah', 23, 45, 4, 'For the sake of Jacob My servant and Israel My chosen one, I call you by name; I have given you a title of honor, though you have not known Me.'),
  ('BSB', 'Isaiah', 23, 45, 5, 'I am the LORD, and there is no other; there is no God but Me. I will equip you for battle, though you have not known Me,'),
  ('BSB', 'Isaiah', 23, 45, 6, 'so that all may know, from where the sun rises to where it sets, that there is none but Me; I am the LORD, and there is no other.'),
  ('BSB', 'Isaiah', 23, 45, 7, 'I form the light and create the darkness; I bring prosperity and create calamity. I, the LORD, do all these things.'),
  ('BSB', 'Isaiah', 23, 45, 8, 'Drip down, O heavens, from above, and let the skies pour down righteousness. Let the earth open up that salvation may sprout and righteousness spring up with it; I, the LORD, have created it.'),
  ('BSB', 'Isaiah', 23, 45, 9, 'Woe to him who quarrels with his Maker— one clay pot among many. Does the clay ask the potter, ‘What are you making?’ Does your work say, ‘He has no hands’?'),
  ('BSB', 'Isaiah', 23, 45, 10, 'Woe to him who says to his father, ‘What have you begotten?’ or to his mother, ‘What have you brought forth?’”'),
  ('BSB', 'Isaiah', 23, 45, 11, 'Thus says the LORD, the Holy One of Israel, and its Maker: “How dare you question Me about My sons, or instruct Me in the work of My hands?'),
  ('BSB', 'Isaiah', 23, 45, 12, 'It is I who made the earth and created man upon it. It was My hands that stretched out the heavens, and I ordained all their host.'),
  ('BSB', 'Isaiah', 23, 45, 13, 'I will raise up Cyrus in righteousness, and I will make all his ways straight. He will rebuild My city and set My exiles free, but not for payment or reward, says the LORD of Hosts.”'),
  ('BSB', 'Isaiah', 23, 45, 14, 'This is what the LORD says: “The products of Egypt and the merchandise of Cush, along with the Sabeans, men of stature, will come over to you and will be yours; they will trudge behind you; they will come over in chains and bow down to you. They will confess to you: ‘God is indeed with you, and there is no other; there is no other God.’”'),
  ('BSB', 'Isaiah', 23, 45, 15, 'Truly You are a God who hides Himself, O God of Israel, the Savior.'),
  ('BSB', 'Isaiah', 23, 45, 16, 'They will all be put to shame and humiliated; the makers of idols will depart together in disgrace.'),
  ('BSB', 'Isaiah', 23, 45, 17, 'But Israel will be saved by the LORD with an everlasting salvation; you will not be put to shame or humiliated, to ages everlasting.'),
  ('BSB', 'Isaiah', 23, 45, 18, 'For thus says the LORD, who created the heavens—He is God; He formed the earth and fashioned it; He established it; He did not create it to be empty, but formed it to be inhabited: “I am the LORD, and there is no other.'),
  ('BSB', 'Isaiah', 23, 45, 19, 'I have not spoken in secret, from a place in a land of darkness. I did not say to the descendants of Jacob, ‘Seek Me in a wasteland.’ I, the LORD, speak the truth; I say what is right.'),
  ('BSB', 'Isaiah', 23, 45, 20, 'Come, gather together, and draw near, you fugitives from the nations. Ignorant are those who carry idols of wood and pray to a god that cannot save.'),
  ('BSB', 'Isaiah', 23, 45, 21, 'Speak up and present your case— yes, let them take counsel together. Who foretold this long ago? Who announced it from ancient times? Was it not I, the LORD? There is no other God but Me, a righteous God and Savior; there is none but Me.'),
  ('BSB', 'Isaiah', 23, 45, 22, 'Turn to Me and be saved, all the ends of the earth; for I am God, and there is no other.'),
  ('BSB', 'Isaiah', 23, 45, 23, 'By Myself I have sworn; truth has gone out from My mouth, a word that will not be revoked: Every knee will bow before Me, every tongue will swear allegiance.'),
  ('BSB', 'Isaiah', 23, 45, 24, 'Surely they will say of Me, ‘In the LORD alone are righteousness and strength.’” All who rage against Him will come to Him and be put to shame.'),
  ('BSB', 'Isaiah', 23, 45, 25, 'In the LORD all descendants of Israel will be justified and will exult.'),
  ('BSB', 'Isaiah', 23, 46, 1, 'Bel crouches; Nebo cowers. Their idols weigh down beasts and cattle. The images you carry are burdensome, a load to the weary animal.'),
  ('BSB', 'Isaiah', 23, 46, 2, 'The gods cower; they crouch together, unable to relieve the burden; but they themselves go into captivity.'),
  ('BSB', 'Isaiah', 23, 46, 3, '“Listen to Me, O house of Jacob, all the remnant of the house of Israel, who have been sustained from the womb, carried along since birth.'),
  ('BSB', 'Isaiah', 23, 46, 4, 'Even to your old age, I will be the same, and I will bear you up when you turn gray. I have made you, and I will carry you; I will sustain you and deliver you.'),
  ('BSB', 'Isaiah', 23, 46, 5, 'To whom will you liken Me or count Me equal? To whom will you compare Me, that we should be alike?'),
  ('BSB', 'Isaiah', 23, 46, 6, 'They pour out their bags of gold and weigh out silver on scales; they hire a goldsmith to fashion it into a god, so they can bow down and worship.'),
  ('BSB', 'Isaiah', 23, 46, 7, 'They lift it to their shoulder and carry it along; they set it in its place, and there it stands, not budging from that spot. They cry out to it, but it does not answer; it saves no one from his troubles.'),
  ('BSB', 'Isaiah', 23, 46, 8, 'Remember this and be brave; take it to heart, you transgressors!'),
  ('BSB', 'Isaiah', 23, 46, 9, 'Remember what happened long ago, for I am God, and there is no other; I am God, and there is none like Me.'),
  ('BSB', 'Isaiah', 23, 46, 10, 'I declare the end from the beginning, and ancient times from what is still to come. I say, ‘My purpose will stand, and all My good pleasure I will accomplish.’'),
  ('BSB', 'Isaiah', 23, 46, 11, 'I summon a bird of prey from the east, a man for My purpose from a far-off land. Truly I have spoken, and truly I will bring it to pass. I have planned it, and I will surely do it.'),
  ('BSB', 'Isaiah', 23, 46, 12, 'Listen to Me, you stubborn people, far removed from righteousness:'),
  ('BSB', 'Isaiah', 23, 46, 13, 'I am bringing My righteousness near; it is not far away, and My salvation will not be delayed. I will grant salvation to Zion and adorn Israel with My splendor.'),
  ('BSB', 'Isaiah', 23, 47, 1, '“Go down and sit in the dust, O Virgin Daughter of Babylon. Sit on the ground without a throne, O Daughter of Chaldea! For you will no longer be called tender or delicate.'),
  ('BSB', 'Isaiah', 23, 47, 2, 'Take millstones and grind flour; remove your veil; strip off your skirt, bare your thigh, and wade through the streams.'),
  ('BSB', 'Isaiah', 23, 47, 3, 'Your nakedness will be uncovered and your shame will be exposed. I will take vengeance; I will spare no one.”'),
  ('BSB', 'Isaiah', 23, 47, 4, 'Our Redeemer—the LORD of Hosts is His name— is the Holy One of Israel.'),
  ('BSB', 'Isaiah', 23, 47, 5, '“Sit in silence and go into darkness, O Daughter of Chaldea. For you will no longer be called the queen of kingdoms.'),
  ('BSB', 'Isaiah', 23, 47, 6, 'I was angry with My people; I profaned My heritage, and I placed them under your control. You showed them no mercy; even on the elderly you laid a most heavy yoke.'),
  ('BSB', 'Isaiah', 23, 47, 7, 'You said, ‘I will be queen forever.’ You did not take these things to heart or consider their outcome.'),
  ('BSB', 'Isaiah', 23, 47, 8, 'So now hear this, O lover of luxury who sits securely, who says to herself, ‘I am, and there is none besides me. I will never be a widow or know the loss of children.’'),
  ('BSB', 'Isaiah', 23, 47, 9, 'These two things will overtake you in a moment, in a single day: loss of children, and widowhood. They will come upon you in full measure, in spite of your many sorceries and the potency of your spells.'),
  ('BSB', 'Isaiah', 23, 47, 10, 'You were secure in your wickedness; you said, ‘No one sees me.’ Your wisdom and knowledge led you astray; you told yourself, ‘I am, and there is none besides me.’'),
  ('BSB', 'Isaiah', 23, 47, 11, 'But disaster will come upon you; you will not know how to charm it away. A calamity will befall you that you will be unable to ward off. Devastation will happen to you suddenly and unexpectedly.'),
  ('BSB', 'Isaiah', 23, 47, 12, 'So take your stand with your spells and with your many sorceries, with which you have wearied yourself from your youth. Perhaps you will succeed; perhaps you will inspire terror!'),
  ('BSB', 'Isaiah', 23, 47, 13, 'You are wearied by your many counselors; let them come forward now and save you— your astrologers who observe the stars, who monthly predict your fate.'),
  ('BSB', 'Isaiah', 23, 47, 14, 'Surely they are like stubble; the fire will burn them up. They cannot deliver themselves from the power of the flame. There will be no coals to warm them or fire to sit beside.'),
  ('BSB', 'Isaiah', 23, 47, 15, 'This is what they are to you— those with whom you have labored and traded from youth— each one strays in his own direction; not one of them can save you.'),
  ('BSB', 'Isaiah', 23, 48, 1, '“Listen to this, O house of Jacob, you who are called by the name of Israel, who have descended from the line of Judah, who swear by the name of the LORD, who invoke the God of Israel— but not in truth or righteousness—'),
  ('BSB', 'Isaiah', 23, 48, 2, 'who indeed call yourselves after the holy city and lean on the God of Israel; the LORD of Hosts is His name.'),
  ('BSB', 'Isaiah', 23, 48, 3, 'I foretold the former things long ago; they came out of My mouth and I proclaimed them. Suddenly I acted, and they came to pass.'),
  ('BSB', 'Isaiah', 23, 48, 4, 'For I knew that you are stubborn; your neck is iron and your forehead is bronze.'),
  ('BSB', 'Isaiah', 23, 48, 5, 'Therefore I declared it to you long ago; I announced it before it came to pass, so that you could not claim, ‘My idol has done this; my carved image and molten god has ordained it.’'),
  ('BSB', 'Isaiah', 23, 48, 6, 'You have heard these things; look at them all. Will you not acknowledge them? From now on I will tell you of new things, hidden things unknown to you.'),
  ('BSB', 'Isaiah', 23, 48, 7, 'They are created now, and not long ago; you have not heard of them before today. So you cannot claim, ‘I already knew them!’'),
  ('BSB', 'Isaiah', 23, 48, 8, 'You have never heard; you have never understood; for a long time your ears have not been open. For I knew how deceitful you are; you have been called a rebel from birth.'),
  ('BSB', 'Isaiah', 23, 48, 9, 'For the sake of My name I will delay My wrath; for the sake of My praise I will restrain it, so that you will not be cut off.'),
  ('BSB', 'Isaiah', 23, 48, 10, 'See, I have refined you, but not as silver; I have tested you in the furnace of affliction.'),
  ('BSB', 'Isaiah', 23, 48, 11, 'For My own sake, My very own sake, I will act; for how can I let Myself be defamed? I will not yield My glory to another.'),
  ('BSB', 'Isaiah', 23, 48, 12, 'Listen to Me, O Jacob, and Israel, whom I have called: I am He; I am the first, and I am the last.'),
  ('BSB', 'Isaiah', 23, 48, 13, 'Surely My own hand founded the earth, and My right hand spread out the heavens; when I summon them, they stand up together.'),
  ('BSB', 'Isaiah', 23, 48, 14, 'Come together, all of you, and listen: Which of the idols has foretold these things? The LORD’s chosen ally will carry out His desire against Babylon, and His arm will be against the Chaldeans.'),
  ('BSB', 'Isaiah', 23, 48, 15, 'I, even I, have spoken; yes, I have called him. I have brought him, and he will succeed in his mission.'),
  ('BSB', 'Isaiah', 23, 48, 16, 'Come near to Me and listen to this: From the beginning I have not spoken in secret; from the time it happened, I was there.” And now the Lord GOD has sent me, accompanied by His Spirit.'),
  ('BSB', 'Isaiah', 23, 48, 17, 'Thus says the LORD your Redeemer, the Holy One of Israel: “I am the LORD your God, who teaches you for your benefit, who directs you in the way you should go.'),
  ('BSB', 'Isaiah', 23, 48, 18, 'If only you had paid attention to My commandments, your peace would have been like a river, and your righteousness like waves of the sea.'),
  ('BSB', 'Isaiah', 23, 48, 19, 'Your descendants would have been as countless as the sand, and your offspring as numerous as its grains; their name would never be cut off or eliminated from My presence.”'),
  ('BSB', 'Isaiah', 23, 48, 20, 'Leave Babylon! Flee from the Chaldeans! Declare it with a shout of joy, proclaim it, let it go out to the ends of the earth, saying, “The LORD has redeemed His servant Jacob!”'),
  ('BSB', 'Isaiah', 23, 48, 21, 'They did not thirst when He led them through the deserts; He made water flow for them from the rock; He split the rock, and water gushed out.'),
  ('BSB', 'Isaiah', 23, 48, 22, '“There is no peace,” says the LORD, “for the wicked.”'),
  ('BSB', 'Isaiah', 23, 49, 1, 'Listen to Me, O islands; pay attention, O distant peoples: The LORD called Me from the womb; from the body of My mother He named Me.'),
  ('BSB', 'Isaiah', 23, 49, 2, 'He made My mouth like a sharp sword; He hid Me in the shadow of His hand. He made Me like a polished arrow; He hid Me in His quiver.'),
  ('BSB', 'Isaiah', 23, 49, 3, 'He said to Me, “You are My Servant, Israel, in whom I will display My glory.”'),
  ('BSB', 'Isaiah', 23, 49, 4, 'But I said, “I have labored in vain, I have spent My strength in futility and vanity; yet My vindication is with the LORD, and My reward is with My God.”'),
  ('BSB', 'Isaiah', 23, 49, 5, 'And now says the LORD, who formed Me from the womb to be His Servant, to bring Jacob back to Him, that Israel might be gathered to Him— for I am honored in the sight of the LORD, and My God is My strength—'),
  ('BSB', 'Isaiah', 23, 49, 6, 'He says: “It is not enough for You to be My Servant, to raise up the tribes of Jacob, and to restore the protected ones of Israel. I will also make You a light for the nations, to bring My salvation to the ends of the earth.”'),
  ('BSB', 'Isaiah', 23, 49, 7, 'Thus says the LORD, the Redeemer and Holy One of Israel, to Him who was despised and abhorred by the nation, to the Servant of rulers: “Kings will see You and rise, and princes will bow down, because of the LORD, who is faithful, the Holy One of Israel, who has chosen You.”'),
  ('BSB', 'Isaiah', 23, 49, 8, 'This is what the LORD says: “In the time of favor I will answer You, and in the day of salvation I will help You; I will keep You and appoint You to be a covenant for the people, to restore the land, to apportion its desolate inheritances,'),
  ('BSB', 'Isaiah', 23, 49, 9, 'to say to the prisoners, ‘Come out,’ and to those in darkness, ‘Show yourselves.’ They will feed along the pathways, and find pasture on every barren hill.'),
  ('BSB', 'Isaiah', 23, 49, 10, 'They will not hunger or thirst, nor will scorching heat or sun beat down on them. For He who has compassion on them will guide them and lead them beside springs of water.'),
  ('BSB', 'Isaiah', 23, 49, 11, 'I will turn all My mountains into roads, and My highways will be raised up.'),
  ('BSB', 'Isaiah', 23, 49, 12, 'Behold, they will come from far away, from the north and from the west, and from the land of Aswan.”'),
  ('BSB', 'Isaiah', 23, 49, 13, 'Shout for joy, O heavens; rejoice, O earth; break forth in song, O mountains! For the LORD has comforted His people, and He will have compassion on His afflicted ones.'),
  ('BSB', 'Isaiah', 23, 49, 14, 'But Zion said, “The LORD has forsaken me; the Lord has forgotten me!”'),
  ('BSB', 'Isaiah', 23, 49, 15, '“Can a woman forget her nursing child, or lack compassion for the son of her womb? Even if she could forget, I will not forget you!'),
  ('BSB', 'Isaiah', 23, 49, 16, 'Behold, I have inscribed you on the palms of My hands; your walls are ever before Me.'),
  ('BSB', 'Isaiah', 23, 49, 17, 'Your builders hasten back; your destroyers and wreckers depart from you.'),
  ('BSB', 'Isaiah', 23, 49, 18, 'Lift up your eyes and look around. They all gather together; they come to you. As surely as I live,” declares the LORD, “you will wear them all as jewelry and put them on like a bride.'),
  ('BSB', 'Isaiah', 23, 49, 19, 'For your ruined and desolate places and your ravaged land will now indeed be too small for your people, and those who devoured you will be far away.'),
  ('BSB', 'Isaiah', 23, 49, 20, 'Yet the children of your bereavement will say in your hearing, ‘This place is too small for us; make room for us to live here.’'),
  ('BSB', 'Isaiah', 23, 49, 21, 'Then you will say in your heart, ‘Who has begotten these for me? I was bereaved and barren; I was exiled and rejected. So who has reared them? Look, I was left all alone, so where did they come from?’”'),
  ('BSB', 'Isaiah', 23, 49, 22, 'This is what the Lord GOD says: “Behold, I will lift up My hand to the nations, and raise My banner to the peoples. They will bring your sons in their arms and carry your daughters on their shoulders.'),
  ('BSB', 'Isaiah', 23, 49, 23, 'Kings will be your foster fathers, and their queens your nursing mothers. They will bow to you facedown and lick the dust at your feet. Then you will know that I am the LORD; those who hope in Me will never be put to shame.”'),
  ('BSB', 'Isaiah', 23, 49, 24, 'Can the plunder be snatched from the mighty, or the captives of a tyrant be delivered?'),
  ('BSB', 'Isaiah', 23, 49, 25, 'Indeed, this is what the LORD says: “Even the captives of the mighty will be taken away, and the plunder of the tyrant will be retrieved; I will contend with those who contend with you, and I will save your children.'),
  ('BSB', 'Isaiah', 23, 49, 26, 'I will make your oppressors eat their own flesh; they will be drunk on their own blood, as with wine. Then all mankind will know that I, the LORD, am your Savior and your Redeemer, the Mighty One of Jacob.”'),
  ('BSB', 'Isaiah', 23, 50, 1, 'This is what the LORD says: “Where is your mother’s certificate of divorce with which I sent her away? Or to which of My creditors did I sell you? Look, you were sold for your iniquities, and for your transgressions your mother was sent away.'),
  ('BSB', 'Isaiah', 23, 50, 2, 'Why was no one there when I arrived? Why did no one answer when I called? Is My hand too short to redeem you? Or do I lack the strength to deliver you? Behold, My rebuke dries up the sea; I turn the rivers into a desert; the fish rot for lack of water and die of thirst.'),
  ('BSB', 'Isaiah', 23, 50, 3, 'I clothe the heavens in black and make sackcloth their covering.”'),
  ('BSB', 'Isaiah', 23, 50, 4, 'The Lord GOD has given Me the tongue of discipleship, to sustain the weary with a word. He awakens Me morning by morning; He awakens My ear to listen as a disciple.'),
  ('BSB', 'Isaiah', 23, 50, 5, 'The Lord GOD has opened My ears, and I have not been rebellious, nor have I turned back.'),
  ('BSB', 'Isaiah', 23, 50, 6, 'I offered My back to those who struck Me, and My cheeks to those who tore out My beard. I did not hide My face from scorn and spittle.'),
  ('BSB', 'Isaiah', 23, 50, 7, 'Because the Lord GOD helps Me, I have not been disgraced; therefore I have set My face like flint, and I know that I will not be put to shame.'),
  ('BSB', 'Isaiah', 23, 50, 8, 'The One who vindicates Me is near. Who will dare to contend with Me? Let us confront each other! Who has a case against Me? Let him approach Me!'),
  ('BSB', 'Isaiah', 23, 50, 9, 'Surely the Lord GOD helps Me. Who is there to condemn Me? See, they will all wear out like a garment; the moths will devour them.'),
  ('BSB', 'Isaiah', 23, 50, 10, 'Who among you fears the LORD and obeys the voice of His Servant? Who among you walks in darkness and has no light? Let him trust in the name of the LORD; let him lean on his God.'),
  ('BSB', 'Isaiah', 23, 50, 11, 'Behold, all you who kindle a fire, who array yourselves with firebrands, walk in the light of your fire and of the firebrands you have lit! This is what you will receive from My hand: You will lie down in a place of torment.'),
  ('BSB', 'Isaiah', 23, 51, 1, '“Listen to Me, you who pursue righteousness, you who seek the LORD: Look to the rock from which you were cut, and to the quarry from which you were hewn.'),
  ('BSB', 'Isaiah', 23, 51, 2, 'Look to Abraham your father, and to Sarah who gave you birth. When I called him, he was but one; then I blessed him and multiplied him.'),
  ('BSB', 'Isaiah', 23, 51, 3, 'For the LORD will comfort Zion and will look with compassion on all her ruins; He will make her wilderness like Eden and her desert like the garden of the LORD. Joy and gladness will be found in her, thanksgiving and melodious song.'),
  ('BSB', 'Isaiah', 23, 51, 4, 'Pay attention to Me, My people, and listen to Me, My nation; for a law will go out from Me, and My justice will become a light to the nations; I will bring it about quickly.'),
  ('BSB', 'Isaiah', 23, 51, 5, 'My righteousness draws near, My salvation is on the way, and My arms will bring justice to the nations. The islands will look for Me and wait in hope for My arm.'),
  ('BSB', 'Isaiah', 23, 51, 6, 'Lift up your eyes to the heavens, and look at the earth below; for the heavens will vanish like smoke, the earth will wear out like a garment, and its people will die like gnats. But My salvation will last forever, and My righteousness will never fail.'),
  ('BSB', 'Isaiah', 23, 51, 7, 'Listen to Me, you who know what is right, you people with My law in your hearts: Do not fear the scorn of men; do not be broken by their insults.'),
  ('BSB', 'Isaiah', 23, 51, 8, 'For the moth will devour them like a garment, and the worm will eat them like wool. But My righteousness will last forever, My salvation through all generations.”'),
  ('BSB', 'Isaiah', 23, 51, 9, 'Awake, awake, put on strength, O arm of the LORD. Wake up as in days past, as in generations of old. Was it not You who cut Rahab to pieces, who pierced through the dragon?'),
  ('BSB', 'Isaiah', 23, 51, 10, 'Was it not You who dried up the sea, the waters of the great deep, who made a road in the depths of the sea for the redeemed to cross over?'),
  ('BSB', 'Isaiah', 23, 51, 11, 'So the redeemed of the LORD will return and enter Zion with singing, crowned with everlasting joy. Gladness and joy will overtake them, and sorrow and sighing will flee.'),
  ('BSB', 'Isaiah', 23, 51, 12, '“I, even I, am He who comforts you. Why should you be afraid of mortal man, of a son of man who withers like grass?'),
  ('BSB', 'Isaiah', 23, 51, 13, 'But you have forgotten the LORD, your Maker, who stretched out the heavens and laid the foundations of the earth. You live in terror all day long because of the fury of the oppressor who is bent on destruction. But where is the fury of the oppressor?'),
  ('BSB', 'Isaiah', 23, 51, 14, 'The captive will soon be freed; he will not die in the dungeon, and his bread will not be lacking.'),
  ('BSB', 'Isaiah', 23, 51, 15, 'For I am the LORD your God who stirs up the sea so that its waves roar— the LORD of Hosts is His name.'),
  ('BSB', 'Isaiah', 23, 51, 16, 'I have put My words in your mouth, and covered you with the shadow of My hand, to establish the heavens, to found the earth, and to say to Zion, ‘You are My people.’”'),
  ('BSB', 'Isaiah', 23, 51, 17, 'Awake, awake! Rise up, O Jerusalem, you who have drunk from the hand of the LORD the cup of His fury; you who have drained the goblet to the dregs— the cup that makes men stagger.'),
  ('BSB', 'Isaiah', 23, 51, 18, 'Among all the sons she bore, there is no one to guide her; among all the sons she brought up, there is no one to take her hand.'),
  ('BSB', 'Isaiah', 23, 51, 19, 'These pairs have befallen you: devastation and destruction, famine and sword. Who will grieve for you? Who can comfort you?'),
  ('BSB', 'Isaiah', 23, 51, 20, 'Your sons have fainted; they lie at the head of every street, like an antelope in a net. They are full of the wrath of the LORD, the rebuke of your God.'),
  ('BSB', 'Isaiah', 23, 51, 21, 'Therefore now hear this, you afflicted one, drunken, but not with wine.'),
  ('BSB', 'Isaiah', 23, 51, 22, 'Thus says your Lord, the LORD, even your God, who defends His people: “See, I have removed from your hand the cup of staggering. From that goblet, the cup of My fury, you will never drink again.'),
  ('BSB', 'Isaiah', 23, 51, 23, 'I will place it in the hands of your tormentors, who told you: ‘Lie down, so we can walk over you,’ so that you made your back like the ground, like a street to be traversed.”'),
  ('BSB', 'Isaiah', 23, 52, 1, 'Awake, awake, clothe yourself with strength, O Zion! Put on your garments of splendor, O Jerusalem, holy city! For the uncircumcised and unclean will no longer enter you.'),
  ('BSB', 'Isaiah', 23, 52, 2, 'Shake off your dust! Rise up and sit on your throne, O Jerusalem. Remove the chains from your neck, O captive Daughter of Zion.'),
  ('BSB', 'Isaiah', 23, 52, 3, 'For this is what the LORD says: “You were sold for nothing, and without money you will be redeemed.”'),
  ('BSB', 'Isaiah', 23, 52, 4, 'For this is what the Lord GOD says: “At first My people went down to Egypt to live, then Assyria oppressed them without cause.'),
  ('BSB', 'Isaiah', 23, 52, 5, 'And now what have I here? declares the LORD. For My people have been taken without cause; those who rule them taunt, declares the LORD, and My name is blasphemed continually all day long.'),
  ('BSB', 'Isaiah', 23, 52, 6, 'Therefore My people will know My name; therefore they will know on that day that I am He who speaks. Here I am!”'),
  ('BSB', 'Isaiah', 23, 52, 7, 'How beautiful on the mountains are the feet of those who bring good news, who proclaim peace, who bring good tidings, who proclaim salvation, who say to Zion, “Your God reigns!”'),
  ('BSB', 'Isaiah', 23, 52, 8, 'Listen! Your watchmen lift up their voices, together they shout for joy. For every eye will see when the LORD returns to Zion.'),
  ('BSB', 'Isaiah', 23, 52, 9, 'Break forth in joy, sing together, O ruins of Jerusalem, for the LORD has comforted His people; He has redeemed Jerusalem.'),
  ('BSB', 'Isaiah', 23, 52, 10, 'The LORD has bared His holy arm in the sight of all the nations; all the ends of the earth will see the salvation of our God.'),
  ('BSB', 'Isaiah', 23, 52, 11, 'Depart, depart, go out from there! Touch no unclean thing; come out from it, purify yourselves, you who carry the vessels of the LORD.'),
  ('BSB', 'Isaiah', 23, 52, 12, 'For you will not leave in a hurry nor flee in haste, for the LORD goes before you, and the God of Israel is your rear guard.'),
  ('BSB', 'Isaiah', 23, 52, 13, 'Behold, My Servant will prosper; He will be raised and lifted up and highly exalted.'),
  ('BSB', 'Isaiah', 23, 52, 14, 'Just as many were appalled at Him— His appearance was disfigured beyond that of any man, and His form was marred beyond human likeness—'),
  ('BSB', 'Isaiah', 23, 52, 15, 'so He will sprinkle many nations. Kings will shut their mouths because of Him. For they will see what they have not been told, and they will understand what they have not heard.'),
  ('BSB', 'Isaiah', 23, 53, 1, 'Who has believed our message? And to whom has the arm of the LORD been revealed?'),
  ('BSB', 'Isaiah', 23, 53, 2, 'He grew up before Him like a tender shoot, and like a root out of dry ground. He had no stately form or majesty to attract us, no beauty that we should desire Him.'),
  ('BSB', 'Isaiah', 23, 53, 3, 'He was despised and rejected by men, a man of sorrows, acquainted with grief. Like one from whom men hide their faces, He was despised, and we esteemed Him not.'),
  ('BSB', 'Isaiah', 23, 53, 4, 'Surely He took on our infirmities and carried our sorrows; yet we considered Him stricken by God, struck down and afflicted.'),
  ('BSB', 'Isaiah', 23, 53, 5, 'But He was pierced for our transgressions, He was crushed for our iniquities; the punishment that brought us peace was upon Him, and by His stripes we are healed.'),
  ('BSB', 'Isaiah', 23, 53, 6, 'We all like sheep have gone astray, each one has turned to his own way; and the LORD has laid upon Him the iniquity of us all.'),
  ('BSB', 'Isaiah', 23, 53, 7, 'He was oppressed and afflicted, yet He did not open His mouth. He was led like a lamb to the slaughter, and as a sheep before her shearers is silent, so He did not open His mouth.'),
  ('BSB', 'Isaiah', 23, 53, 8, 'By oppression and judgment He was taken away, and who can recount His descendants? For He was cut off from the land of the living; He was stricken for the transgression of My people.'),
  ('BSB', 'Isaiah', 23, 53, 9, 'He was assigned a grave with the wicked, and with a rich man in His death, although He had done no violence, nor was any deceit in His mouth.'),
  ('BSB', 'Isaiah', 23, 53, 10, 'Yet it was the LORD’s will to crush Him and to cause Him to suffer; and when His soul is made a guilt offering, He will see His offspring, He will prolong His days, and the good pleasure of the LORD will prosper in His hand.'),
  ('BSB', 'Isaiah', 23, 53, 11, 'After the anguish of His soul, He will see the light of life and be satisfied. By His knowledge My righteous Servant will justify many, and He will bear their iniquities.'),
  ('BSB', 'Isaiah', 23, 53, 12, 'Therefore I will allot Him a portion with the great, and He will divide the spoils with the strong, because He has poured out His life unto death, and He was numbered with the transgressors. Yet He bore the sin of many and made intercession for the transgressors.'),
  ('BSB', 'Isaiah', 23, 54, 1, '“Shout for joy, O barren woman, who bears no children; break forth in song and cry aloud, you who have never travailed; because more are the children of the desolate woman than of her who has a husband,” says the LORD.'),
  ('BSB', 'Isaiah', 23, 54, 2, '“Enlarge the site of your tent, stretch out the curtains of your dwellings, do not hold back. Lengthen your ropes and drive your stakes in deep.'),
  ('BSB', 'Isaiah', 23, 54, 3, 'For you will spread out to the right and left; your descendants will dispossess the nations and inhabit the desolate cities.'),
  ('BSB', 'Isaiah', 23, 54, 4, 'Do not be afraid, for you will not be put to shame; do not be intimidated, for you will not be humiliated. For you will forget the shame of your youth and will remember no more the reproach of your widowhood.'),
  ('BSB', 'Isaiah', 23, 54, 5, 'For your husband is your Maker— the LORD of Hosts is His name— the Holy One of Israel is your Redeemer; He is called the God of all the earth.'),
  ('BSB', 'Isaiah', 23, 54, 6, 'For the LORD has called you back, like a wife deserted and wounded in spirit, like the rejected wife of one’s youth,” says your God.'),
  ('BSB', 'Isaiah', 23, 54, 7, '“For a brief moment I forsook you, but with great compassion I will bring you back.'),
  ('BSB', 'Isaiah', 23, 54, 8, 'In a surge of anger I hid My face from you for a moment, but with everlasting kindness I will have compassion on you,” says the LORD your Redeemer.'),
  ('BSB', 'Isaiah', 23, 54, 9, '“For to Me this is like the days of Noah, when I swore that the waters of Noah would never again cover the earth. So I have sworn that I will not be angry with you or rebuke you.'),
  ('BSB', 'Isaiah', 23, 54, 10, 'Though the mountains may be removed and the hills may be shaken, My loving devotion will not depart from you, and My covenant of peace will not be broken,” says the LORD, who has compassion on you.'),
  ('BSB', 'Isaiah', 23, 54, 11, '“O afflicted city, lashed by storms, without solace, surely I will set your stones in antimony and lay your foundations with sapphires.'),
  ('BSB', 'Isaiah', 23, 54, 12, 'I will make your pinnacles of rubies, your gates of sparkling jewels, and all your walls of precious stones.'),
  ('BSB', 'Isaiah', 23, 54, 13, 'Then all your sons will be taught by the LORD, and great will be their prosperity.'),
  ('BSB', 'Isaiah', 23, 54, 14, 'In righteousness you will be established, far from oppression, for you will have no fear. Terror will be far removed, for it will not come near you.'),
  ('BSB', 'Isaiah', 23, 54, 15, 'If anyone attacks you, it is not from Me; whoever assails you will fall before you.'),
  ('BSB', 'Isaiah', 23, 54, 16, 'Behold, I have created the craftsman who fans the coals into flame and forges a weapon fit for its task; and I have created the destroyer to wreak havoc.'),
  ('BSB', 'Isaiah', 23, 54, 17, 'No weapon formed against you shall prosper, and you will refute every tongue that accuses you. This is the heritage of the servants of the LORD, and their vindication is from Me,” declares the LORD.'),
  ('BSB', 'Isaiah', 23, 55, 1, '“Come, all you who are thirsty, come to the waters; and you without money, come, buy, and eat! Come, buy wine and milk without money and without cost!'),
  ('BSB', 'Isaiah', 23, 55, 2, 'Why spend money on that which is not bread, and your labor on that which does not satisfy? Listen carefully to Me, and eat what is good, and your soul will delight in the richest of foods.'),
  ('BSB', 'Isaiah', 23, 55, 3, 'Incline your ear and come to Me; listen, so that your soul may live. I will make with you an everlasting covenant— My loving devotion promised to David.'),
  ('BSB', 'Isaiah', 23, 55, 4, 'Behold, I have made him a witness to the nations, a leader and commander of the peoples.'),
  ('BSB', 'Isaiah', 23, 55, 5, 'Surely you will summon a nation you do not know, and nations who do not know you will run to you. For the LORD your God, the Holy One of Israel, has bestowed glory on you.”'),
  ('BSB', 'Isaiah', 23, 55, 6, 'Seek the LORD while He may be found; call on Him while He is near.'),
  ('BSB', 'Isaiah', 23, 55, 7, 'Let the wicked man forsake his own way and the unrighteous man his own thoughts; let him return to the LORD, that He may have compassion, and to our God, for He will freely pardon.'),
  ('BSB', 'Isaiah', 23, 55, 8, '“For My thoughts are not your thoughts, neither are your ways My ways,” declares the LORD.'),
  ('BSB', 'Isaiah', 23, 55, 9, '“For as the heavens are higher than the earth, so My ways are higher than your ways and My thoughts than your thoughts.'),
  ('BSB', 'Isaiah', 23, 55, 10, 'For just as rain and snow fall from heaven and do not return without watering the earth, making it bud and sprout, and providing seed to sow and food to eat,'),
  ('BSB', 'Isaiah', 23, 55, 11, 'so My word that proceeds from My mouth will not return to Me empty, but it will accomplish what I please, and it will prosper where I send it.'),
  ('BSB', 'Isaiah', 23, 55, 12, 'You will indeed go out with joy and be led forth in peace; the mountains and hills will burst into song before you, and all the trees of the field will clap their hands.'),
  ('BSB', 'Isaiah', 23, 55, 13, 'Instead of the thornbush, a cypress will grow, and instead of the brier, a myrtle will spring up; they will make a name for the LORD, an everlasting sign, never to be destroyed.”'),
  ('BSB', 'Isaiah', 23, 56, 1, 'This is what the LORD says: “Maintain justice and do what is right, for My salvation is coming soon, and My righteousness will be revealed.'),
  ('BSB', 'Isaiah', 23, 56, 2, 'Blessed is the man who does this, and the son of man who holds it fast, who keeps the Sabbath without profaning it and keeps his hand from doing any evil.”'),
  ('BSB', 'Isaiah', 23, 56, 3, 'Let no foreigner who has joined himself to the LORD say, “The LORD will utterly exclude me from His people.” And let the eunuch not say, “I am but a dry tree.”'),
  ('BSB', 'Isaiah', 23, 56, 4, 'For this is what the LORD says: “To the eunuchs who keep My Sabbaths, who choose what pleases Me and hold fast to My covenant—'),
  ('BSB', 'Isaiah', 23, 56, 5, 'I will give them, in My house and within My walls, a memorial and a name better than that of sons and daughters. I will give them an everlasting name that will not be cut off.'),
  ('BSB', 'Isaiah', 23, 56, 6, 'And the foreigners who join themselves to the LORD to minister to Him, to love the name of the LORD, and to be His servants— all who keep the Sabbath without profaning it and who hold fast to My covenant—'),
  ('BSB', 'Isaiah', 23, 56, 7, 'I will bring them to My holy mountain and make them joyful in My house of prayer. Their burnt offerings and sacrifices will be accepted on My altar, for My house will be called a house of prayer for all the nations.”'),
  ('BSB', 'Isaiah', 23, 56, 8, 'Thus declares the Lord GOD, who gathers the dispersed of Israel: “I will gather to them still others besides those already gathered.”'),
  ('BSB', 'Isaiah', 23, 56, 9, 'Come, all you beasts of the field; eat greedily, all you beasts of the forest.'),
  ('BSB', 'Isaiah', 23, 56, 10, 'Israel’s watchmen are blind, they are all oblivious; they are all mute dogs, they cannot bark; they are dreamers lying around, loving to slumber.'),
  ('BSB', 'Isaiah', 23, 56, 11, 'Like ravenous dogs, they are never satisfied. They are shepherds with no discernment; they all turn to their own way, each one seeking his own gain:'),
  ('BSB', 'Isaiah', 23, 56, 12, '“Come, let me get the wine, let us imbibe the strong drink, and tomorrow will be like today, only far better!”'),
  ('BSB', 'Isaiah', 23, 57, 1, 'The righteous perish, and no one takes it to heart; devout men are swept away, while no one considers that the righteous are guided from the presence of evil.'),
  ('BSB', 'Isaiah', 23, 57, 2, 'Those who walk uprightly enter into peace; they find rest, lying down in death.'),
  ('BSB', 'Isaiah', 23, 57, 3, '“But come here, you sons of a sorceress, you offspring of adulterers and prostitutes!'),
  ('BSB', 'Isaiah', 23, 57, 4, 'Whom are you mocking? At whom do you snarl and stick out your tongue? Are you not children of transgression, offspring of deceit,'),
  ('BSB', 'Isaiah', 23, 57, 5, 'who burn with lust among the oaks, under every luxuriant tree, who slaughter your children in the valleys, under the clefts of the rocks?'),
  ('BSB', 'Isaiah', 23, 57, 6, 'Your portion is among the smooth stones of the valley; indeed, they are your lot. Even to them you have poured out a drink offering and offered a grain offering. Should I relent because of these?'),
  ('BSB', 'Isaiah', 23, 57, 7, 'On a high and lofty hill you have made your bed, and there you went up to offer sacrifices.'),
  ('BSB', 'Isaiah', 23, 57, 8, 'Behind the door and doorpost you have set up your memorial. Forsaking Me, you uncovered your bed; you climbed up and opened it wide. And you have made a pact with those whose bed you have loved; you have gazed upon their nakedness.'),
  ('BSB', 'Isaiah', 23, 57, 9, 'You went to Molech with oil and multiplied your perfumes. You have sent your envoys a great distance; you have descended even to Sheol itself.'),
  ('BSB', 'Isaiah', 23, 57, 10, 'You are wearied by your many journeys, but you did not say, “There is no hope!” You found renewal of your strength; therefore you did not grow weak.'),
  ('BSB', 'Isaiah', 23, 57, 11, 'Whom have you dreaded and feared, so that you lied and failed to remember Me or take this to heart? Is it not because I have long been silent that you do not fear Me?'),
  ('BSB', 'Isaiah', 23, 57, 12, 'I will expose your righteousness and your works, and they will not profit you.'),
  ('BSB', 'Isaiah', 23, 57, 13, 'When you cry out, let your companies of idols deliver you! Yet the wind will carry off all of them, a breath will take them away. But he who seeks refuge in Me will inherit the land and possess My holy mountain.”'),
  ('BSB', 'Isaiah', 23, 57, 14, 'And it will be said, “Build it up, build it up, prepare the way, take every obstacle out of the way of My people.”'),
  ('BSB', 'Isaiah', 23, 57, 15, 'For thus says the One who is high and lifted up, who inhabits eternity, whose name is Holy: “I dwell in a high and holy place, and with the oppressed and humble in spirit, to restore the spirit of the lowly and revive the heart of the contrite.'),
  ('BSB', 'Isaiah', 23, 57, 16, 'For I will not accuse you forever, nor will I always be angry; for then the spirit of man would grow weak before Me, with the breath of those I have made.'),
  ('BSB', 'Isaiah', 23, 57, 17, 'I was enraged by his sinful greed, so I struck him and hid My face in anger; yet he kept turning back to the desires of his heart.'),
  ('BSB', 'Isaiah', 23, 57, 18, 'I have seen his ways, but I will heal him; I will guide him and restore comfort to him and his mourners,'),
  ('BSB', 'Isaiah', 23, 57, 19, 'bringing praise to their lips. Peace, peace to those far and near,” says the LORD, “and I will heal them.”'),
  ('BSB', 'Isaiah', 23, 57, 20, 'But the wicked are like the storm-tossed sea, for it cannot be still, and its waves churn up mire and muck.'),
  ('BSB', 'Isaiah', 23, 57, 21, '“There is no peace,” says my God, “for the wicked.”'),
  ('BSB', 'Isaiah', 23, 58, 1, '“Cry aloud, do not hold back! Raise your voice like a ram’s horn. Declare to My people their transgression and to the house of Jacob their sins.'),
  ('BSB', 'Isaiah', 23, 58, 2, 'For day after day they seek Me and delight to know My ways, like a nation that does what is right and does not forsake the justice of their God. They ask Me for righteous judgments; they delight in the nearness of God.”'),
  ('BSB', 'Isaiah', 23, 58, 3, '“Why have we fasted, and You have not seen? Why have we humbled ourselves, and You have not noticed?” “Behold, on the day of your fast, you do as you please, and you oppress all your workers.'),
  ('BSB', 'Isaiah', 23, 58, 4, 'You fast with contention and strife to strike viciously with your fist. You cannot fast as you do today and have your voice be heard on high.'),
  ('BSB', 'Isaiah', 23, 58, 5, 'Is this the fast I have chosen: a day for a man to deny himself, to bow his head like a reed, and to spread out sackcloth and ashes? Will you call this a fast and a day acceptable to the LORD?'),
  ('BSB', 'Isaiah', 23, 58, 6, 'Isn’t this the fast that I have chosen: to break the chains of wickedness, to untie the cords of the yoke, to set the oppressed free and tear off every yoke?'),
  ('BSB', 'Isaiah', 23, 58, 7, 'Isn’t it to share your bread with the hungry, to bring the poor and homeless into your home, to clothe the naked when you see him, and not to turn away from your own flesh and blood?'),
  ('BSB', 'Isaiah', 23, 58, 8, 'Then your light will break forth like the dawn, and your healing will come quickly. Your righteousness will go before you, and the glory of the LORD will be your rear guard.'),
  ('BSB', 'Isaiah', 23, 58, 9, 'Then you will call, and the LORD will answer; you will cry out, and He will say, ‘Here I am.’ If you remove the yoke from your midst, the pointing of the finger and malicious talk,'),
  ('BSB', 'Isaiah', 23, 58, 10, 'and if you give yourself to the hungry and satisfy the afflicted soul, then your light will go forth in the darkness, and your night will be like noonday.'),
  ('BSB', 'Isaiah', 23, 58, 11, 'The LORD will always guide you; He will satisfy you in a sun-scorched land and strengthen your frame. You will be like a well-watered garden, like a spring whose waters never fail.'),
  ('BSB', 'Isaiah', 23, 58, 12, 'Your people will rebuild the ancient ruins; you will restore the age-old foundations; you will be called Repairer of the Breach, Restorer of the Streets of Dwelling.'),
  ('BSB', 'Isaiah', 23, 58, 13, 'If you turn your foot from breaking the Sabbath, from doing as you please on My holy day, if you call the Sabbath a delight, and the LORD’s holy day honorable, if you honor it by not going your own way or seeking your own pleasure or speaking idle words,');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Isaiah', 23, 58, 14, 'then you will delight yourself in the LORD, and I will make you ride on the heights of the land and feed you with the heritage of your father Jacob.” For the mouth of the LORD has spoken.'),
  ('BSB', 'Isaiah', 23, 59, 1, 'Surely the arm of the LORD is not too short to save, nor His ear too dull to hear.'),
  ('BSB', 'Isaiah', 23, 59, 2, 'But your iniquities have built barriers between you and your God, and your sins have hidden His face from you, so that He does not hear.'),
  ('BSB', 'Isaiah', 23, 59, 3, 'For your hands are stained with blood, and your fingers with iniquity; your lips have spoken lies, and your tongue mutters injustice.'),
  ('BSB', 'Isaiah', 23, 59, 4, 'No one calls for justice; no one pleads his case honestly. They rely on empty pleas; they tell lies; they conceive mischief and give birth to iniquity.'),
  ('BSB', 'Isaiah', 23, 59, 5, 'They hatch the eggs of vipers and weave a spider’s web. Whoever eats their eggs will die; crack one open, and a viper is hatched.'),
  ('BSB', 'Isaiah', 23, 59, 6, 'Their cobwebs cannot be made into clothing, and they cannot cover themselves with their works. Their deeds are sinful deeds, and acts of violence are in their hands.'),
  ('BSB', 'Isaiah', 23, 59, 7, 'Their feet run to evil; they are swift to shed innocent blood. Their thoughts are sinful thoughts; ruin and destruction lie in their wake.'),
  ('BSB', 'Isaiah', 23, 59, 8, 'The way of peace they have not known, and there is no justice in their tracks. They have turned them into crooked paths; no one who treads on them will know peace.'),
  ('BSB', 'Isaiah', 23, 59, 9, 'Therefore justice is far from us, and righteousness does not reach us. We hope for light, but there is darkness; for brightness, but we walk in gloom.'),
  ('BSB', 'Isaiah', 23, 59, 10, 'Like the blind, we feel our way along the wall, groping like those without eyes. We stumble at midday as in the twilight; among the vigorous we are like the dead.'),
  ('BSB', 'Isaiah', 23, 59, 11, 'We all growl like bears and moan like doves. We hope for justice, but find none, for salvation, but it is far from us.'),
  ('BSB', 'Isaiah', 23, 59, 12, 'For our transgressions are multiplied before You, and our sins testify against us. Our transgressions are indeed with us, and we know our iniquities:'),
  ('BSB', 'Isaiah', 23, 59, 13, 'rebelling and denying the LORD, turning away from our God, speaking oppression and revolt, conceiving and uttering lies from the heart.'),
  ('BSB', 'Isaiah', 23, 59, 14, 'So justice is turned away, and righteousness stands at a distance. For truth has stumbled in the public square, and honesty cannot enter.'),
  ('BSB', 'Isaiah', 23, 59, 15, 'Truth is missing, and whoever turns from evil becomes prey. The LORD looked and was displeased that there was no justice.'),
  ('BSB', 'Isaiah', 23, 59, 16, 'He saw that there was no man; He was amazed that there was no one to intercede. So His own arm brought salvation, and His own righteousness sustained Him.'),
  ('BSB', 'Isaiah', 23, 59, 17, 'He put on righteousness like a breastplate, and the helmet of salvation on His head; He put on garments of vengeance and wrapped Himself in a cloak of zeal.'),
  ('BSB', 'Isaiah', 23, 59, 18, 'So He will repay according to their deeds: fury to His enemies, retribution to His foes, and recompense to the islands.'),
  ('BSB', 'Isaiah', 23, 59, 19, 'So shall they fear the name of the LORD where the sun sets, and His glory where it rises. For He will come like a raging flood, driven by the breath of the LORD.'),
  ('BSB', 'Isaiah', 23, 59, 20, '“The Redeemer will come to Zion, to those in Jacob who turn from transgression,” declares the LORD.'),
  ('BSB', 'Isaiah', 23, 59, 21, '“As for Me, this is My covenant with them,” says the LORD. “My Spirit will not depart from you, and My words that I have put in your mouth will not depart from your mouth or from the mouths of your children and grandchildren, from now on and forevermore,” says the LORD.'),
  ('BSB', 'Isaiah', 23, 60, 1, 'Arise, shine, for your light has come, and the glory of the LORD rises upon you.'),
  ('BSB', 'Isaiah', 23, 60, 2, 'For behold, darkness covers the earth, and thick darkness is over the peoples; but the LORD will rise upon you, and His glory will appear over you.'),
  ('BSB', 'Isaiah', 23, 60, 3, 'Nations will come to your light, and kings to the brightness of your dawn.'),
  ('BSB', 'Isaiah', 23, 60, 4, 'Lift up your eyes and look around: They all gather and come to you; your sons will come from afar, and your daughters will be carried on the arm.'),
  ('BSB', 'Isaiah', 23, 60, 5, 'Then you will look and be radiant, and your heart will tremble and swell with joy, because the riches of the sea will be brought to you, and the wealth of the nations will come to you.'),
  ('BSB', 'Isaiah', 23, 60, 6, 'Caravans of camels will cover your land, young camels of Midian and Ephah, and all from Sheba will come, bearing gold and frankincense and proclaiming the praises of the LORD.'),
  ('BSB', 'Isaiah', 23, 60, 7, 'All the flocks of Kedar will be gathered to you; the rams of Nebaioth will serve you and go up on My altar with acceptance; I will adorn My glorious house.'),
  ('BSB', 'Isaiah', 23, 60, 8, 'Who are these who fly like clouds, like doves to their shelters?'),
  ('BSB', 'Isaiah', 23, 60, 9, 'Surely the islands will wait for Me, with the ships of Tarshish in the lead, to bring your children from afar, with their silver and gold, to the honor of the LORD your God, the Holy One of Israel, for He has glorified you.'),
  ('BSB', 'Isaiah', 23, 60, 10, 'Foreigners will rebuild your walls, and their kings will serve you. Although I struck you in anger, yet in favor I will show you mercy.'),
  ('BSB', 'Isaiah', 23, 60, 11, 'Your gates will always stand open; they will never be shut, day or night, so that the wealth of the nations may be brought into you, with their kings being led in procession.'),
  ('BSB', 'Isaiah', 23, 60, 12, 'For the nation or kingdom that will not serve you will perish; it will be utterly destroyed.'),
  ('BSB', 'Isaiah', 23, 60, 13, 'The glory of Lebanon will come to you— its cypress, elm, and boxwood together— to adorn the place of My sanctuary, and I will glorify the place of My feet.'),
  ('BSB', 'Isaiah', 23, 60, 14, 'The sons of your oppressors will come and bow down to you; all who reviled you will fall facedown at your feet and call you the City of the LORD, Zion of the Holy One of Israel.'),
  ('BSB', 'Isaiah', 23, 60, 15, 'Whereas you have been forsaken and despised, with no one passing through, I will make you an everlasting pride, a joy from age to age.'),
  ('BSB', 'Isaiah', 23, 60, 16, 'You will drink the milk of nations and nurse at the breasts of royalty; you will know that I, the LORD, am your Savior and your Redeemer, the Mighty One of Jacob.'),
  ('BSB', 'Isaiah', 23, 60, 17, 'Instead of bronze I will bring you gold; I will bring silver in place of iron, bronze instead of wood, and iron instead of stones. I will appoint peace as your governor and righteousness as your ruler.'),
  ('BSB', 'Isaiah', 23, 60, 18, 'No longer will violence be heard in your land, nor ruin or destruction within your borders. But you will name your walls Salvation and your gates Praise.'),
  ('BSB', 'Isaiah', 23, 60, 19, 'No longer will the sun be your light by day, nor the brightness of the moon shine on your night; for the LORD will be your everlasting light, and your God will be your splendor.'),
  ('BSB', 'Isaiah', 23, 60, 20, 'Your sun will no longer set, and your moon will not wane; for the LORD will be your everlasting light, and the days of your sorrow will cease.'),
  ('BSB', 'Isaiah', 23, 60, 21, 'Then all your people will be righteous; they will possess the land forever; they are the branch of My planting, the work of My hands, so that I may be glorified.'),
  ('BSB', 'Isaiah', 23, 60, 22, 'The least of you will become a thousand, and the smallest a mighty nation. I am the LORD; in its time I will accomplish it quickly.'),
  ('BSB', 'Isaiah', 23, 61, 1, 'The Spirit of the Lord GOD is on Me, because the LORD has anointed Me to preach good news to the poor. He has sent Me to bind up the brokenhearted, to proclaim liberty to the captives and freedom to the prisoners,'),
  ('BSB', 'Isaiah', 23, 61, 2, 'to proclaim the year of the LORD’s favor and the day of our God’s vengeance, to comfort all who mourn,'),
  ('BSB', 'Isaiah', 23, 61, 3, 'to console the mourners in Zion— to give them a crown of beauty for ashes, the oil of joy for mourning, and a garment of praise for a spirit of despair. So they will be called oaks of righteousness, the planting of the LORD, that He may be glorified.'),
  ('BSB', 'Isaiah', 23, 61, 4, 'They will rebuild the ancient ruins; they will restore the places long devastated; they will renew the ruined cities, the desolations of many generations.'),
  ('BSB', 'Isaiah', 23, 61, 5, 'Strangers will stand and feed your flocks, and foreigners will be your plowmen and vinedressers.'),
  ('BSB', 'Isaiah', 23, 61, 6, 'But you will be called the priests of the LORD; they will speak of you as ministers of our God; you will feed on the wealth of nations, and you will boast in their riches.'),
  ('BSB', 'Isaiah', 23, 61, 7, 'Instead of shame, My people will have a double portion, and instead of humiliation, they will rejoice in their share; and so they will inherit a double portion in their land, and everlasting joy will be theirs.'),
  ('BSB', 'Isaiah', 23, 61, 8, 'For I, the LORD, love justice; I hate robbery and iniquity; in My faithfulness I will give them their recompense and make an everlasting covenant with them.'),
  ('BSB', 'Isaiah', 23, 61, 9, 'Their descendants will be known among the nations, and their offspring among the peoples. All who see them will acknowledge that they are a people the LORD has blessed.'),
  ('BSB', 'Isaiah', 23, 61, 10, 'I will rejoice greatly in the LORD, my soul will exult in my God; for He has clothed me with garments of salvation and wrapped me in a robe of righteousness, as a bridegroom wears a priestly headdress, as a bride adorns herself with her jewels.'),
  ('BSB', 'Isaiah', 23, 61, 11, 'For as the earth brings forth its growth, and as a garden enables seed to spring up, so the Lord GOD will cause righteousness and praise to spring up before all the nations.'),
  ('BSB', 'Isaiah', 23, 62, 1, 'For Zion’s sake I will not keep silent, and for Jerusalem’s sake I will not keep still, until her righteousness shines like a bright light, her salvation like a blazing torch.'),
  ('BSB', 'Isaiah', 23, 62, 2, 'Nations will see your righteousness, and all kings your glory. You will be called by a new name that the mouth of the LORD will bestow.'),
  ('BSB', 'Isaiah', 23, 62, 3, 'You will be a crown of glory in the hand of the LORD, a royal diadem in the palm of your God.'),
  ('BSB', 'Isaiah', 23, 62, 4, 'No longer will you be called Forsaken, nor your land named Desolate; but you will be called Hephzibah, and your land Beulah; for the LORD will take delight in you, and your land will be His bride.'),
  ('BSB', 'Isaiah', 23, 62, 5, 'For as a young man marries a young woman, so your sons will marry you; and as a bridegroom rejoices over his bride, so your God will rejoice over you.'),
  ('BSB', 'Isaiah', 23, 62, 6, 'On your walls, O Jerusalem, I have posted watchmen; they will never be silent day or night. You who call on the LORD shall take no rest for yourselves,'),
  ('BSB', 'Isaiah', 23, 62, 7, 'nor give Him any rest until He establishes Jerusalem and makes her the praise of the earth.'),
  ('BSB', 'Isaiah', 23, 62, 8, 'The LORD has sworn by His right hand and by His mighty arm: “Never again will I give your grain to your enemies for food, nor will foreigners drink the new wine for which you have toiled.'),
  ('BSB', 'Isaiah', 23, 62, 9, 'For those who harvest grain will eat it and praise the LORD, and those who gather grapes will drink the wine in My holy courts.”'),
  ('BSB', 'Isaiah', 23, 62, 10, 'Go out, go out through the gates; prepare the way for the people! Build it up, build up the highway; clear away the stones; raise a banner for the nations!'),
  ('BSB', 'Isaiah', 23, 62, 11, 'Behold, the LORD has proclaimed to the ends of the earth, “Say to Daughter Zion: See, your Savior comes! Look, His reward is with Him, and His recompense goes before Him.”'),
  ('BSB', 'Isaiah', 23, 62, 12, 'And they will be called the Holy People, the Redeemed of The LORD; and you will be called Sought Out, A City Not Forsaken.'),
  ('BSB', 'Isaiah', 23, 63, 1, 'Who is this coming from Edom, from Bozrah with crimson-stained garments? Who is this robed in splendor, marching in the greatness of His strength? “It is I, proclaiming vindication, mighty to save.”'),
  ('BSB', 'Isaiah', 23, 63, 2, 'Why are Your clothes red, and Your garments like one who treads the winepress?'),
  ('BSB', 'Isaiah', 23, 63, 3, '“I have trodden the winepress alone, and no one from the nations was with Me. I trampled them in My anger and trod them down in My fury; their blood spattered My garments, and all My clothes were stained.'),
  ('BSB', 'Isaiah', 23, 63, 4, 'For the day of vengeance was in My heart, and the year of My redemption had come.'),
  ('BSB', 'Isaiah', 23, 63, 5, 'I looked, but there was no one to help; I was appalled that no one assisted. So My arm brought Me salvation, and My own wrath upheld Me.'),
  ('BSB', 'Isaiah', 23, 63, 6, 'I trampled the nations in My anger; in My wrath I made them drunk and poured out their blood on the ground.”'),
  ('BSB', 'Isaiah', 23, 63, 7, 'I will make known the LORD’s loving devotion and His praiseworthy acts, because of all that the LORD has done for us— the many good things for the house of Israel according to His great compassion and loving devotion.'),
  ('BSB', 'Isaiah', 23, 63, 8, 'For He said, “They are surely My people, sons who will not be disloyal.” So He became their Savior.'),
  ('BSB', 'Isaiah', 23, 63, 9, 'In all their distress, He too was afflicted, and the Angel of His Presence saved them. In His love and compassion He redeemed them; He lifted them up and carried them all the days of old.'),
  ('BSB', 'Isaiah', 23, 63, 10, 'But they rebelled and grieved His Holy Spirit. So He turned and became their enemy, and He Himself fought against them.'),
  ('BSB', 'Isaiah', 23, 63, 11, 'Then His people remembered the days of old, the days of Moses. Where is He who brought them through the sea with the shepherds of His flock? Where is the One who set His Holy Spirit among them,'),
  ('BSB', 'Isaiah', 23, 63, 12, 'who sent His glorious arm to lead them by the right hand of Moses, who divided the waters before them to gain for Himself everlasting renown,'),
  ('BSB', 'Isaiah', 23, 63, 13, 'who led them through the depths like a horse in the wilderness, so that they did not stumble?'),
  ('BSB', 'Isaiah', 23, 63, 14, 'Like cattle going down to the valley, the Spirit of the LORD gave them rest. You led Your people this way to make for Yourself a glorious name.'),
  ('BSB', 'Isaiah', 23, 63, 15, 'Look down from heaven and see, from Your holy and glorious habitation. Where are Your zeal and might? Your yearning and compassion for me are restrained.'),
  ('BSB', 'Isaiah', 23, 63, 16, 'Yet You are our Father, though Abraham does not know us and Israel does not acknowledge us. You, O LORD, are our Father; our Redeemer from Everlasting is Your name.'),
  ('BSB', 'Isaiah', 23, 63, 17, 'Why, O LORD, do You make us stray from Your ways and harden our hearts from fearing You? Return, for the sake of Your servants, the tribes of Your heritage.'),
  ('BSB', 'Isaiah', 23, 63, 18, 'For a short while Your people possessed Your holy place, but our enemies have trampled Your sanctuary.'),
  ('BSB', 'Isaiah', 23, 63, 19, 'We have become like those You never ruled, like those not called by Your name.'),
  ('BSB', 'Isaiah', 23, 64, 1, 'If only You would rend the heavens and come down, so that mountains would quake at Your presence,'),
  ('BSB', 'Isaiah', 23, 64, 2, 'as fire kindles the brushwood and causes the water to boil, to make Your name known to Your enemies, so that the nations will tremble at Your presence!'),
  ('BSB', 'Isaiah', 23, 64, 3, 'When You did awesome works that we did not expect, You came down, and the mountains trembled at Your presence.'),
  ('BSB', 'Isaiah', 23, 64, 4, 'From ancient times no one has heard, no ear has perceived, no eye has seen any God besides You, who acts on behalf of those who wait for Him.'),
  ('BSB', 'Isaiah', 23, 64, 5, 'You welcome those who gladly do right, who remember Your ways. Surely You were angry, for we sinned. How can we be saved if we remain in our sins?'),
  ('BSB', 'Isaiah', 23, 64, 6, 'Each of us has become like something unclean, and all our righteous acts are like filthy rags; we all wither like a leaf, and our iniquities carry us away like the wind.'),
  ('BSB', 'Isaiah', 23, 64, 7, 'No one calls on Your name or strives to take hold of You. For You have hidden Your face from us and delivered us into the hand of our iniquity.'),
  ('BSB', 'Isaiah', 23, 64, 8, 'But now, O LORD, You are our Father; we are the clay, and You are the potter; we are all the work of Your hand.'),
  ('BSB', 'Isaiah', 23, 64, 9, 'Do not be angry, O LORD, beyond measure; do not remember our iniquity forever. Oh, look upon us, we pray; we are all Your people!'),
  ('BSB', 'Isaiah', 23, 64, 10, 'Your holy cities have become a wilderness. Zion has become a wasteland and Jerusalem a desolation.'),
  ('BSB', 'Isaiah', 23, 64, 11, 'Our holy and beautiful temple, where our fathers praised You, has been burned with fire, and all that was dear to us lies in ruins.'),
  ('BSB', 'Isaiah', 23, 64, 12, 'After all this, O LORD, will You restrain Yourself? Will You keep silent and afflict us beyond measure?'),
  ('BSB', 'Isaiah', 23, 65, 1, '“I revealed Myself to those who did not ask for Me; I was found by those who did not seek Me. To a nation that did not call My name, I said, ‘Here I am! Here I am!’'),
  ('BSB', 'Isaiah', 23, 65, 2, 'All day long I have held out My hands to an obstinate people who walk in the wrong path, who follow their own imaginations,'),
  ('BSB', 'Isaiah', 23, 65, 3, 'to a people who continually provoke Me to My face, sacrificing in the gardens and burning incense on altars of brick,'),
  ('BSB', 'Isaiah', 23, 65, 4, 'sitting among the graves, spending nights in secret places, eating the meat of pigs and polluted broth from their bowls.'),
  ('BSB', 'Isaiah', 23, 65, 5, 'They say, ‘Keep to yourself; do not come near me, for I am holier than you!’ Such people are smoke in My nostrils, a fire that burns all day long.'),
  ('BSB', 'Isaiah', 23, 65, 6, 'Behold, it is written before Me: I will not keep silent, but I will repay; I will pay it back into their laps,'),
  ('BSB', 'Isaiah', 23, 65, 7, 'both for your iniquities and for those of your fathers,” says the LORD. “Because they burned incense on the mountains and scorned Me on the hills, I will measure into their laps full payment for their former deeds.”'),
  ('BSB', 'Isaiah', 23, 65, 8, 'This is what the LORD says: “As the new wine is found in a cluster of grapes, and men say, ‘Do not destroy it, for it contains a blessing,’ so I will act on behalf of My servants; I will not destroy them all.'),
  ('BSB', 'Isaiah', 23, 65, 9, 'And I will bring forth descendants from Jacob, and heirs from Judah; My elect will possess My mountains, and My servants will dwell there.'),
  ('BSB', 'Isaiah', 23, 65, 10, 'Sharon will become a pasture for flocks, and the Valley of Achor a resting place for herds, for My people who seek Me.'),
  ('BSB', 'Isaiah', 23, 65, 11, 'But you who forsake the LORD, who forget My holy mountain, who set a table for Fortune and fill bowls of mixed wine for Destiny,'),
  ('BSB', 'Isaiah', 23, 65, 12, 'I will destine you for the sword, and you will all kneel down to be slaughtered, because I called and you did not answer, I spoke and you did not listen; you did evil in My sight and chose that in which I did not delight.”'),
  ('BSB', 'Isaiah', 23, 65, 13, 'Therefore this is what the Lord GOD says: “My servants will eat, but you will go hungry; My servants will drink, but you will go thirsty; My servants will rejoice, but you will be put to shame.'),
  ('BSB', 'Isaiah', 23, 65, 14, 'My servants will shout for joy with a glad heart, but you will cry out with a heavy heart and wail with a broken spirit.'),
  ('BSB', 'Isaiah', 23, 65, 15, 'You will leave behind your name as a curse for My chosen ones, and the Lord GOD will slay you; but to His servants He will give another name.'),
  ('BSB', 'Isaiah', 23, 65, 16, 'Whoever invokes a blessing in the land will do so by the God of truth, and whoever takes an oath in the land will swear by the God of truth. For the former troubles will be forgotten and hidden from My sight.'),
  ('BSB', 'Isaiah', 23, 65, 17, 'For behold, I will create new heavens and a new earth. The former things will not be remembered, nor will they come to mind.'),
  ('BSB', 'Isaiah', 23, 65, 18, 'But be glad and rejoice forever in what I create; for I will create Jerusalem to be a joy and its people to be a delight.'),
  ('BSB', 'Isaiah', 23, 65, 19, 'I will rejoice in Jerusalem and take delight in My people. The sounds of weeping and crying will no longer be heard in her.'),
  ('BSB', 'Isaiah', 23, 65, 20, 'No longer will a nursing infant live but a few days, or an old man fail to live out his years. For the youth will die at a hundred years, and he who fails to reach a hundred will be considered accursed.'),
  ('BSB', 'Isaiah', 23, 65, 21, 'They will build houses and dwell in them; they will plant vineyards and eat their fruit.'),
  ('BSB', 'Isaiah', 23, 65, 22, 'No longer will they build houses for others to inhabit, nor plant for others to eat. For as is the lifetime of a tree, so will be the days of My people, and My chosen ones will fully enjoy the work of their hands.'),
  ('BSB', 'Isaiah', 23, 65, 23, 'They will not labor in vain or bear children doomed to disaster; for they will be a people blessed by the LORD— they and their descendants with them.'),
  ('BSB', 'Isaiah', 23, 65, 24, 'Even before they call, I will answer, and while they are still speaking, I will hear.'),
  ('BSB', 'Isaiah', 23, 65, 25, 'The wolf and the lamb will feed together, and the lion will eat straw like the ox, but the food of the serpent will be dust. They will neither harm nor destroy on all My holy mountain,” says the LORD.'),
  ('BSB', 'Isaiah', 23, 66, 1, 'This is what the LORD says: “Heaven is My throne, and earth is My footstool. What kind of house will you build for Me? Or where will My place of repose be?'),
  ('BSB', 'Isaiah', 23, 66, 2, 'Has not My hand made all these things? And so they came into being,” declares the LORD. “This is the one I will esteem: he who is humble and contrite in spirit, who trembles at My word.'),
  ('BSB', 'Isaiah', 23, 66, 3, 'Whoever slaughters an ox is like one who slays a man; whoever sacrifices a lamb is like one who breaks a dog’s neck; whoever presents a grain offering is like one who offers pig’s blood; whoever offers frankincense is like one who blesses an idol. Indeed, they have chosen their own ways and delighted in their abominations.'),
  ('BSB', 'Isaiah', 23, 66, 4, 'So I will choose their punishment and I will bring terror upon them, because I called and no one answered, I spoke and no one listened. But they did evil in My sight and chose that in which I did not delight.”'),
  ('BSB', 'Isaiah', 23, 66, 5, 'You who tremble at His word, hear the word of the LORD: “Your brothers who hate you and exclude you because of My name have said, ‘Let the LORD be glorified that we may see your joy!’ But they will be put to shame.”'),
  ('BSB', 'Isaiah', 23, 66, 6, 'Hear the uproar from the city; listen to the voice from the temple! It is the voice of the LORD, repaying His enemies what they deserve!'),
  ('BSB', 'Isaiah', 23, 66, 7, '“Before she was in labor, she gave birth; before she was in pain, she delivered a boy.'),
  ('BSB', 'Isaiah', 23, 66, 8, 'Who has heard of such as this? Who has seen such things? Can a country be born in a day or a nation be delivered in an instant? Yet as soon as Zion was in labor, she gave birth to her children.'),
  ('BSB', 'Isaiah', 23, 66, 9, 'Shall I bring a baby to the point of birth and not deliver it?” says the LORD. “Or will I who deliver close the womb?” says your God.'),
  ('BSB', 'Isaiah', 23, 66, 10, 'Be glad for Jerusalem and rejoice over her, all who love her. Rejoice greatly with her, all who mourn over her,'),
  ('BSB', 'Isaiah', 23, 66, 11, 'so that you may nurse and be satisfied at her comforting breasts; you may drink deeply and delight yourselves in her glorious abundance.'),
  ('BSB', 'Isaiah', 23, 66, 12, 'For this is what the LORD says: “I will extend peace to her like a river, and the wealth of nations like a flowing stream; you will nurse and be carried on her arm, and bounced upon her knees.'),
  ('BSB', 'Isaiah', 23, 66, 13, 'As a mother comforts her son, so will I comfort you, and you will be consoled over Jerusalem.”'),
  ('BSB', 'Isaiah', 23, 66, 14, 'When you see, you will rejoice, and you will flourish like grass; then the hand of the LORD will be revealed to His servants, but His wrath will be shown to His enemies.'),
  ('BSB', 'Isaiah', 23, 66, 15, 'For behold, the LORD will come with fire— His chariots are like a whirlwind— to execute His anger with fury and His rebuke with flames of fire.'),
  ('BSB', 'Isaiah', 23, 66, 16, 'For by fire and by His sword, the LORD will execute judgment on all flesh, and many will be slain by the LORD.'),
  ('BSB', 'Isaiah', 23, 66, 17, '“Those who consecrate and purify themselves to enter the groves—to follow one in the center of those who eat the flesh of swine and vermin and rats—will perish together,” declares the LORD.'),
  ('BSB', 'Isaiah', 23, 66, 18, '“And I, knowing their deeds and thoughts, am coming to gather all nations and tongues, and they will come and see My glory.'),
  ('BSB', 'Isaiah', 23, 66, 19, 'I will establish a sign among them, and I will send survivors from among them to the nations—to Tarshish, Put, and the archers of Lud; to Tubal, Javan, and the islands far away who have not heard of My fame or seen My glory. So they will proclaim My glory among the nations.'),
  ('BSB', 'Isaiah', 23, 66, 20, 'And they will bring all your brothers from all the nations as a gift to the LORD on horses and chariots and wagons, on mules and camels, to My holy mountain Jerusalem,” says the LORD, “just as the Israelites bring an offering in a clean vessel to the house of the LORD.”'),
  ('BSB', 'Isaiah', 23, 66, 21, '“And I will select some of them as priests and Levites,” says the LORD.'),
  ('BSB', 'Isaiah', 23, 66, 22, '“For just as the new heavens and the new earth, which I will make, will endure before Me,” declares the LORD, “so your descendants and your name will endure.'),
  ('BSB', 'Isaiah', 23, 66, 23, 'From one New Moon to another and from one Sabbath to another, all mankind will come to worship before Me,” says the LORD.'),
  ('BSB', 'Isaiah', 23, 66, 24, '“As they go forth, they will see the corpses of the men who have rebelled against Me; for their worm will never die, their fire will never be quenched, and they will be a horror to all mankind.”'),
  ('BSB', 'Jeremiah', 24, 1, 1, 'These are the words of Jeremiah son of Hilkiah, one of the priests in Anathoth in the territory of Benjamin.'),
  ('BSB', 'Jeremiah', 24, 1, 2, 'The word of the LORD came to Jeremiah in the thirteenth year of the reign of Josiah son of Amon king of Judah,'),
  ('BSB', 'Jeremiah', 24, 1, 3, 'and through the days of Jehoiakim son of Josiah king of Judah, until the fifth month of the eleventh year of Zedekiah son of Josiah king of Judah, when the people of Jerusalem went into exile.'),
  ('BSB', 'Jeremiah', 24, 1, 4, 'The word of the LORD came to me, saying:'),
  ('BSB', 'Jeremiah', 24, 1, 5, '“Before I formed you in the womb I knew you, and before you were born I set you apart and appointed you as a prophet to the nations.”'),
  ('BSB', 'Jeremiah', 24, 1, 6, '“Ah, Lord GOD,” I said, “I surely do not know how to speak, for I am only a child!”'),
  ('BSB', 'Jeremiah', 24, 1, 7, 'But the LORD told me: “Do not say, ‘I am only a child.’ For to everyone I send you, you must go, and all that I command you, you must speak.'),
  ('BSB', 'Jeremiah', 24, 1, 8, 'Do not be afraid of them, for I am with you to deliver you,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 1, 9, 'Then the LORD reached out His hand, touched my mouth, and said to me: “Behold, I have put My words in your mouth.'),
  ('BSB', 'Jeremiah', 24, 1, 10, 'See, I have appointed you today over nations and kingdoms to uproot and tear down, to destroy and overthrow, to build and plant.”'),
  ('BSB', 'Jeremiah', 24, 1, 11, 'And the word of the LORD came to me, asking, “Jeremiah, what do you see?” “I see a branch of an almond tree,” I replied.'),
  ('BSB', 'Jeremiah', 24, 1, 12, '“You have observed correctly,” said the LORD, “for I am watching over My word to accomplish it.”'),
  ('BSB', 'Jeremiah', 24, 1, 13, 'Again the word of the LORD came to me, asking, “What do you see?” “I see a boiling pot,” I replied, “and it is tilting toward us from the north.”'),
  ('BSB', 'Jeremiah', 24, 1, 14, 'Then the LORD said to me, “Disaster from the north will be poured out on all who live in the land.'),
  ('BSB', 'Jeremiah', 24, 1, 15, 'For I am about to summon all the clans and kingdoms of the north,” declares the LORD. “Their kings will come and set up their thrones at the entrance of the gates of Jerusalem. They will attack all her surrounding walls and all the other cities of Judah.'),
  ('BSB', 'Jeremiah', 24, 1, 16, 'I will pronounce My judgments against them for all their wickedness, because they have forsaken Me to burn incense to other gods and to worship the works of their own hands.'),
  ('BSB', 'Jeremiah', 24, 1, 17, 'Get yourself ready. Stand up and tell them everything that I command you. Do not be intimidated by them, or I will terrify you before them.'),
  ('BSB', 'Jeremiah', 24, 1, 18, 'Now behold, this day I have made you like a fortified city, an iron pillar, and bronze walls against the whole land—against the kings of Judah, its officials, its priests, and the people of the land.'),
  ('BSB', 'Jeremiah', 24, 1, 19, 'They will fight against you but will never overcome you, since I am with you to deliver you,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 2, 1, 'Now the word of the LORD came to me, saying,'),
  ('BSB', 'Jeremiah', 24, 2, 2, '“Go and proclaim in the hearing of Jerusalem that this is what the LORD says: ‘I remember the devotion of your youth, your love as a bride, how you followed Me in the wilderness, in a land not sown.'),
  ('BSB', 'Jeremiah', 24, 2, 3, 'Israel was holy to the LORD, the firstfruits of His harvest. All who devoured her found themselves guilty; disaster came upon them,’” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 2, 4, 'Hear the word of the LORD, O house of Jacob, and all you families of the house of Israel.'),
  ('BSB', 'Jeremiah', 24, 2, 5, 'This is what the LORD says: “What fault did your fathers find in Me that they strayed so far from Me, and followed worthless idols, and became worthless themselves?'),
  ('BSB', 'Jeremiah', 24, 2, 6, 'They did not ask, ‘Where is the LORD who brought us up from the land of Egypt, who led us through the wilderness, through a land of deserts and pits, a land of drought and darkness, a land where no one travels and no one lives?’'),
  ('BSB', 'Jeremiah', 24, 2, 7, 'I brought you into a fertile land to eat its fruit and bounty, but you came and defiled My land, and made My inheritance detestable.'),
  ('BSB', 'Jeremiah', 24, 2, 8, 'The priests did not ask, ‘Where is the LORD?’ The experts in the law no longer knew Me, and the leaders rebelled against Me. The prophets prophesied by Baal and followed useless idols.'),
  ('BSB', 'Jeremiah', 24, 2, 9, 'Therefore, I will contend with you again, declares the LORD, and I will bring a case against your children’s children.'),
  ('BSB', 'Jeremiah', 24, 2, 10, 'Cross over to the coasts of Cyprus and take a look; send to Kedar and consider carefully; see if there has ever been anything like this:'),
  ('BSB', 'Jeremiah', 24, 2, 11, 'Has a nation ever changed its gods, though they are no gods at all? Yet My people have exchanged their Glory for useless idols.'),
  ('BSB', 'Jeremiah', 24, 2, 12, 'Be stunned by this, O heavens; be shocked and utterly appalled,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 2, 13, '“For My people have committed two evils: They have forsaken Me, the fountain of living water, and they have dug their own cisterns— broken cisterns that cannot hold water.'),
  ('BSB', 'Jeremiah', 24, 2, 14, 'Is Israel a slave? Was he born into slavery? Why then has he become prey?'),
  ('BSB', 'Jeremiah', 24, 2, 15, 'The young lions have roared at him; they have growled with a loud voice. They have laid waste his land; his cities lie in ruins, without inhabitant.'),
  ('BSB', 'Jeremiah', 24, 2, 16, 'The men of Memphis and Tahpanhes have shaved the crown of your head.'),
  ('BSB', 'Jeremiah', 24, 2, 17, 'Have you not brought this on yourself by forsaking the LORD your God when He led you in the way?'),
  ('BSB', 'Jeremiah', 24, 2, 18, 'Now what will you gain on your way to Egypt to drink the waters of the Nile? What will you gain on your way to Assyria to drink the waters of the Euphrates?'),
  ('BSB', 'Jeremiah', 24, 2, 19, 'Your own evil will discipline you; your own apostasies will reprimand you. Consider and realize how evil and bitter it is for you to forsake the LORD your God and to have no fear of Me,” declares the Lord GOD of Hosts.'),
  ('BSB', 'Jeremiah', 24, 2, 20, '“For long ago you broke your yoke and tore off your chains, saying, ‘I will not serve!’ Indeed, on every high hill and under every green tree you lay down as a prostitute.'),
  ('BSB', 'Jeremiah', 24, 2, 21, 'I had planted you like a choice vine from the very best seed. How could you turn yourself before Me into a rotten, wild vine?'),
  ('BSB', 'Jeremiah', 24, 2, 22, 'Although you wash with lye and use an abundance of soap, the stain of your guilt is still before Me,” declares the Lord GOD.'),
  ('BSB', 'Jeremiah', 24, 2, 23, '“How can you say, ‘I am not defiled; I have not run after the Baals’? Look at your behavior in the valley; acknowledge what you have done. You are a swift young she-camel galloping here and there,'),
  ('BSB', 'Jeremiah', 24, 2, 24, 'a wild donkey at home in the wilderness, sniffing the wind in the heat of her desire. Who can restrain her passion? All who seek her need not weary themselves; in mating season they will find her.'),
  ('BSB', 'Jeremiah', 24, 2, 25, 'You should have kept your feet from going bare and your throat from being thirsty. But you said, ‘It is hopeless! For I love foreign gods, and I must go after them.’'),
  ('BSB', 'Jeremiah', 24, 2, 26, 'As the thief is ashamed when he is caught, so the house of Israel is disgraced. They, their kings, their officials, their priests, and their prophets'),
  ('BSB', 'Jeremiah', 24, 2, 27, 'say to a tree, ‘You are my father,’ and to a stone, ‘You gave me birth.’ For they have turned their backs to Me and not their faces, yet in the time of trouble they beg, ‘Rise up and save us!’'),
  ('BSB', 'Jeremiah', 24, 2, 28, 'But where are the gods you made for yourselves? Let them rise up in your time of trouble and save you if they can; for your gods are as numerous as your cities, O Judah.'),
  ('BSB', 'Jeremiah', 24, 2, 29, 'Why do you bring a case against Me? You have all rebelled against Me,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 2, 30, '“I have struck your sons in vain; they accepted no discipline. Your own sword has devoured your prophets like a voracious lion.”'),
  ('BSB', 'Jeremiah', 24, 2, 31, 'You people of this generation, consider the word of the LORD: “Have I been a wilderness to Israel or a land of dense darkness? Why do My people say, ‘We are free to roam; we will come to You no more’?'),
  ('BSB', 'Jeremiah', 24, 2, 32, 'Does a maiden forget her jewelry or a bride her wedding sash? Yet My people have forgotten Me for days without number.'),
  ('BSB', 'Jeremiah', 24, 2, 33, 'How skillfully you pursue love! Even the most immoral of women could learn from your ways.'),
  ('BSB', 'Jeremiah', 24, 2, 34, 'Moreover, your skirts are stained with the blood of the innocent poor, though you did not find them breaking in. But in spite of all these things'),
  ('BSB', 'Jeremiah', 24, 2, 35, 'you say, ‘I am innocent. Surely His anger will turn from me.’ Behold, I will judge you, because you say, ‘I have not sinned.’'),
  ('BSB', 'Jeremiah', 24, 2, 36, 'How unstable you are, constantly changing your ways! You will be disappointed by Egypt just as you were by Assyria.'),
  ('BSB', 'Jeremiah', 24, 2, 37, 'Moreover, you will leave that place with your hands on your head, for the LORD has rejected those you trust; you will not prosper by their help.”'),
  ('BSB', 'Jeremiah', 24, 3, 1, '“If a man divorces his wife and she leaves him to marry another, can he ever return to her? Would not such a land be completely defiled? But you have played the harlot with many lovers— and you would return to Me?” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 3, 2, '“Lift up your eyes to the barren heights and see. Is there any place where you have not been violated? You sat beside the highways waiting for your lovers, like a nomad in the desert. You have defiled the land with your prostitution and wickedness.'),
  ('BSB', 'Jeremiah', 24, 3, 3, 'Therefore the showers have been withheld, and no spring rains have fallen. Yet you have the brazen look of a prostitute; you refuse to be ashamed.'),
  ('BSB', 'Jeremiah', 24, 3, 4, 'Have you not just called to Me, ‘My Father, You are my friend from youth.'),
  ('BSB', 'Jeremiah', 24, 3, 5, 'Will He be angry forever? Will He be indignant to the end?’ This you have spoken, but you keep doing all the evil you can.”'),
  ('BSB', 'Jeremiah', 24, 3, 6, 'Now in the days of King Josiah, the LORD said to me, “Have you seen what faithless Israel has done? She has gone up on every high hill and under every green tree to prostitute herself there.'),
  ('BSB', 'Jeremiah', 24, 3, 7, 'I thought that after she had done all these things, she would return to Me. But she did not return, and her unfaithful sister Judah saw it.'),
  ('BSB', 'Jeremiah', 24, 3, 8, 'She saw that because faithless Israel had committed adultery, I gave her a certificate of divorce and sent her away. Yet that unfaithful sister Judah had no fear and prostituted herself as well.'),
  ('BSB', 'Jeremiah', 24, 3, 9, 'Indifferent to her own infidelity, Israel had defiled the land and committed adultery with stones and trees.'),
  ('BSB', 'Jeremiah', 24, 3, 10, 'Yet in spite of all this, her unfaithful sister Judah did not return to Me with all her heart, but only in pretense,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 3, 11, 'And the LORD said to me, “Faithless Israel has shown herself more righteous than unfaithful Judah.'),
  ('BSB', 'Jeremiah', 24, 3, 12, 'Go, proclaim this message toward the north: ‘Return, O faithless Israel,’ declares the LORD. ‘I will no longer look on you with anger, for I am merciful,’ declares the LORD. ‘I will not be angry forever.'),
  ('BSB', 'Jeremiah', 24, 3, 13, 'Only acknowledge your guilt, that you have rebelled against the LORD your God. You have scattered your favors to foreign gods under every green tree and have not obeyed My voice,’” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 3, 14, '“Return, O faithless children,” declares the LORD, “for I am your master, and I will take you—one from a city and two from a family—and bring you to Zion.'),
  ('BSB', 'Jeremiah', 24, 3, 15, 'Then I will give you shepherds after My own heart, who will feed you with knowledge and understanding.”'),
  ('BSB', 'Jeremiah', 24, 3, 16, '“In those days, when you multiply and increase in the land,” declares the LORD, “they will no longer discuss the ark of the covenant of the LORD. It will never come to mind, and no one will remember it or miss it, nor will another one be made.'),
  ('BSB', 'Jeremiah', 24, 3, 17, 'At that time Jerusalem will be called The Throne of the LORD, and all the nations will be gathered in Jerusalem to honor the name of the LORD. They will no longer follow the stubbornness of their evil hearts.'),
  ('BSB', 'Jeremiah', 24, 3, 18, 'In those days the house of Judah will walk with the house of Israel, and they will come together from the land of the north to the land that I gave to your fathers as an inheritance.'),
  ('BSB', 'Jeremiah', 24, 3, 19, 'Then I said, ‘How I long to make you My sons and give you a desirable land, the most beautiful inheritance of all the nations!’ I thought you would call Me ‘Father’ and never turn away from following Me.'),
  ('BSB', 'Jeremiah', 24, 3, 20, 'But as a woman may betray her husband, so you have betrayed Me, O house of Israel,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 3, 21, 'A voice is heard on the barren heights, the children of Israel weeping and begging for mercy, because they have perverted their ways and forgotten the LORD their God.'),
  ('BSB', 'Jeremiah', 24, 3, 22, '“Return, O faithless children, and I will heal your faithlessness.” “Here we are. We come to You, for You are the LORD our God.'),
  ('BSB', 'Jeremiah', 24, 3, 23, 'Surely deception comes from the hills, and commotion from the mountains. Surely the salvation of Israel is in the LORD our God.'),
  ('BSB', 'Jeremiah', 24, 3, 24, 'From our youth, that shameful god has consumed what our fathers have worked for— their flocks and herds, their sons and daughters.'),
  ('BSB', 'Jeremiah', 24, 3, 25, 'Let us lie down in our shame; let our disgrace cover us. We have sinned against the LORD our God, both we and our fathers; from our youth even to this day we have not obeyed the voice of the LORD our God.”'),
  ('BSB', 'Jeremiah', 24, 4, 1, '“If you will return, O Israel, return to Me,” declares the LORD. “If you will remove your detestable idols from My sight and no longer waver,'),
  ('BSB', 'Jeremiah', 24, 4, 2, 'and if you can swear, ‘As surely as the LORD lives,’ in truth, in justice, and in righteousness, then the nations will be blessed by Him, and in Him they will glory.”'),
  ('BSB', 'Jeremiah', 24, 4, 3, 'For this is what the LORD says to the men of Judah and Jerusalem: “Break up your unplowed ground, and do not sow among the thorns.'),
  ('BSB', 'Jeremiah', 24, 4, 4, 'Circumcise yourselves to the LORD, and remove the foreskins of your hearts, O men of Judah and people of Jerusalem. Otherwise, My wrath will break out like fire and burn with no one to extinguish it, because of your evil deeds.”'),
  ('BSB', 'Jeremiah', 24, 4, 5, 'Announce in Judah, proclaim in Jerusalem, and say: “Blow the ram’s horn throughout the land. Cry aloud and say, ‘Assemble yourselves and let us flee to the fortified cities.’'),
  ('BSB', 'Jeremiah', 24, 4, 6, 'Raise a signal flag toward Zion. Seek refuge! Do not delay! For I am bringing disaster from the north, and terrible destruction.'),
  ('BSB', 'Jeremiah', 24, 4, 7, 'A lion has gone up from his thicket, and a destroyer of nations has set out. He has left his lair to lay waste your land. Your cities will be reduced to ruins and lie uninhabited.'),
  ('BSB', 'Jeremiah', 24, 4, 8, 'So put on sackcloth, mourn and wail, for the fierce anger of the LORD has not turned away from us.”'),
  ('BSB', 'Jeremiah', 24, 4, 9, '“In that day,” declares the LORD, “the king and officials will lose their courage. The priests will tremble in fear, and the prophets will be astounded.”'),
  ('BSB', 'Jeremiah', 24, 4, 10, 'Then I said, “Ah, Lord GOD, how completely You have deceived this people and Jerusalem by saying, ‘You will have peace,’ while a sword is at our throats.”'),
  ('BSB', 'Jeremiah', 24, 4, 11, 'At that time it will be said to this people and to Jerusalem, “A searing wind from the barren heights in the desert blows toward the daughter of My people, but not to winnow or to sift;'),
  ('BSB', 'Jeremiah', 24, 4, 12, 'a wind too strong for that comes from Me. Now I also pronounce judgments against them.”'),
  ('BSB', 'Jeremiah', 24, 4, 13, 'Behold, he advances like the clouds, his chariots like the whirlwind. His horses are swifter than eagles. Woe to us, for we are ruined!'),
  ('BSB', 'Jeremiah', 24, 4, 14, 'Wash the evil from your heart, O Jerusalem, so that you may be saved. How long will you harbor wicked thoughts within you?'),
  ('BSB', 'Jeremiah', 24, 4, 15, 'For a voice resounds from Dan, proclaiming disaster from the hills of Ephraim.'),
  ('BSB', 'Jeremiah', 24, 4, 16, 'Warn the nations now! Proclaim to Jerusalem: “A besieging army comes from a distant land; they raise their voices against the cities of Judah.'),
  ('BSB', 'Jeremiah', 24, 4, 17, 'They surround her like men guarding a field, because she has rebelled against Me,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 4, 18, '“Your ways and deeds have brought this upon you. This is your punishment; how bitter it is, because it pierces to the heart!”'),
  ('BSB', 'Jeremiah', 24, 4, 19, 'My anguish, my anguish! I writhe in pain! Oh, the pain in my chest! My heart pounds within me; I cannot be silent. For I have heard the sound of the horn, the alarm of battle.'),
  ('BSB', 'Jeremiah', 24, 4, 20, 'Disaster after disaster is proclaimed, for the whole land is laid waste. My tents are destroyed in an instant, my curtains in a moment.'),
  ('BSB', 'Jeremiah', 24, 4, 21, 'How long must I see the signal flag and hear the sound of the horn?'),
  ('BSB', 'Jeremiah', 24, 4, 22, '“For My people are fools; they have not known Me. They are foolish children, without understanding. They are skilled in doing evil, but they know not how to do good.”'),
  ('BSB', 'Jeremiah', 24, 4, 23, 'I looked at the earth, and it was formless and void; I looked to the heavens, and they had no light.'),
  ('BSB', 'Jeremiah', 24, 4, 24, 'I looked at the mountains, and behold, they were quaking; all the hills were swaying.'),
  ('BSB', 'Jeremiah', 24, 4, 25, 'I looked, and no man was left; all the birds of the air had fled.'),
  ('BSB', 'Jeremiah', 24, 4, 26, 'I looked, and the fruitful land was a desert. All its cities were torn down before the LORD, before His fierce anger.'),
  ('BSB', 'Jeremiah', 24, 4, 27, 'For this is what the LORD says: “The whole land will be desolate, but I will not finish its destruction.'),
  ('BSB', 'Jeremiah', 24, 4, 28, 'Therefore the earth will mourn and the heavens above will grow dark. I have spoken, I have planned, and I will not relent or turn back.”'),
  ('BSB', 'Jeremiah', 24, 4, 29, 'Every city flees at the sound of the horseman and archer. They enter the thickets and climb among the rocks. Every city is abandoned; no inhabitant is left.'),
  ('BSB', 'Jeremiah', 24, 4, 30, 'And you, O devastated one, what will you do, though you dress yourself in scarlet, though you adorn yourself with gold jewelry, though you enlarge your eyes with paint? You adorn yourself in vain; your lovers despise you; they want to take your life.'),
  ('BSB', 'Jeremiah', 24, 4, 31, 'For I hear a cry like a woman in labor, a cry of anguish like one bearing her first child— the cry of the Daughter of Zion gasping for breath, stretching out her hands to say, “Woe is me, for my soul faints before the murderers!”'),
  ('BSB', 'Jeremiah', 24, 5, 1, '“Go up and down the streets of Jerusalem. Look now and take note; search her squares. If you can find a single person, anyone who acts justly, anyone who seeks the truth, then I will forgive the city.'),
  ('BSB', 'Jeremiah', 24, 5, 2, 'Although they say, ‘As surely as the LORD lives,’ they are swearing falsely.”'),
  ('BSB', 'Jeremiah', 24, 5, 3, 'O LORD, do not Your eyes look for truth? You struck them, but they felt no pain. You finished them off, but they refused to accept discipline. They have made their faces harder than stone and refused to repent.'),
  ('BSB', 'Jeremiah', 24, 5, 4, 'Then I said, “They are only the poor; they have played the fool, for they do not know the way of the LORD, the justice of their God.'),
  ('BSB', 'Jeremiah', 24, 5, 5, 'I will go to the powerful and speak to them. Surely they know the way of the LORD, the justice of their God.” But they too, with one accord, had broken the yoke and torn off the chains.'),
  ('BSB', 'Jeremiah', 24, 5, 6, 'Therefore a lion from the forest will strike them down, a wolf from the desert will ravage them. A leopard will lie in wait near their cities, and everyone who ventures out will be torn to pieces. For their rebellious acts are many, and their unfaithful deeds are numerous.'),
  ('BSB', 'Jeremiah', 24, 5, 7, '“Why should I forgive you? Your children have forsaken Me and sworn by gods that are not gods. I satisfied their needs, yet they committed adultery and assembled at the houses of prostitutes.'),
  ('BSB', 'Jeremiah', 24, 5, 8, 'They are well-fed, lusty stallions, each neighing after his neighbor’s wife.'),
  ('BSB', 'Jeremiah', 24, 5, 9, 'Should I not punish them for these things?” declares the LORD. “Should I not avenge Myself on such a nation as this?'),
  ('BSB', 'Jeremiah', 24, 5, 10, 'Go up through her vineyards and ravage them, but do not finish them off. Strip off her branches, for they do not belong to the LORD.'),
  ('BSB', 'Jeremiah', 24, 5, 11, 'For the house of Israel and the house of Judah have been utterly unfaithful to Me,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 5, 12, 'They have lied about the LORD and said: “He will not do anything; harm will not come to us; we will not see sword or famine.'),
  ('BSB', 'Jeremiah', 24, 5, 13, 'The prophets are but wind, for the word is not in them. So let their own predictions befall them.”'),
  ('BSB', 'Jeremiah', 24, 5, 14, 'Therefore this is what the LORD God of Hosts says: “Because you have spoken this word, I will make My words a fire in your mouth and this people the wood it consumes.'),
  ('BSB', 'Jeremiah', 24, 5, 15, 'Behold, I am bringing a distant nation against you, O house of Israel,” declares the LORD. “It is an established nation, an ancient nation, a nation whose language you do not know and whose speech you do not understand.'),
  ('BSB', 'Jeremiah', 24, 5, 16, 'Their quivers are like open graves; they are all mighty men.'),
  ('BSB', 'Jeremiah', 24, 5, 17, 'They will devour your harvest and food; they will consume your sons and daughters; they will eat up your flocks and herds; they will feed on your vines and fig trees. With the sword they will destroy the fortified cities in which you trust.”'),
  ('BSB', 'Jeremiah', 24, 5, 18, '“Yet even in those days,” declares the LORD, “I will not make a full end of you.'),
  ('BSB', 'Jeremiah', 24, 5, 19, 'And when the people ask, ‘For what offense has the LORD our God done all these things to us?’ You are to tell them, ‘Just as you have forsaken Me and served foreign gods in your land, so will you serve foreigners in a land that is not your own.’”'),
  ('BSB', 'Jeremiah', 24, 5, 20, 'Declare this in the house of Jacob and proclaim it in Judah:'),
  ('BSB', 'Jeremiah', 24, 5, 21, '“Hear this, O foolish and senseless people, who have eyes but do not see, who have ears but do not hear.'),
  ('BSB', 'Jeremiah', 24, 5, 22, 'Do you not fear Me?” declares the LORD. “Do you not tremble before Me, the One who set the sand as the boundary for the sea, an enduring barrier it cannot cross? The waves surge, but they cannot prevail. They roar but cannot cross it.'),
  ('BSB', 'Jeremiah', 24, 5, 23, 'But these people have stubborn and rebellious hearts. They have turned aside and gone away.'),
  ('BSB', 'Jeremiah', 24, 5, 24, 'They have not said in their hearts, ‘Let us fear the LORD our God, who gives the rains, both autumn and spring, in season, who keeps for us the appointed weeks of harvest.’'),
  ('BSB', 'Jeremiah', 24, 5, 25, 'Your iniquities have diverted these from you; your sins have deprived you of My bounty.'),
  ('BSB', 'Jeremiah', 24, 5, 26, 'For among My people are wicked men; they watch like fowlers lying in wait; they set a trap to catch men.'),
  ('BSB', 'Jeremiah', 24, 5, 27, 'Like cages full of birds, so their houses are full of deceit. Therefore they have become powerful and rich.'),
  ('BSB', 'Jeremiah', 24, 5, 28, 'They have grown fat and sleek, and have excelled in the deeds of the wicked. They have not taken up the cause of the fatherless, that they might prosper; nor have they defended the rights of the needy.'),
  ('BSB', 'Jeremiah', 24, 5, 29, 'Should I not punish them for these things?” declares the LORD. “Should I not avenge Myself on such a nation as this?'),
  ('BSB', 'Jeremiah', 24, 5, 30, 'A horrible and shocking thing has happened in the land.'),
  ('BSB', 'Jeremiah', 24, 5, 31, 'The prophets prophesy falsely, and the priests rule by their own authority. My people love it so, but what will you do in the end?'),
  ('BSB', 'Jeremiah', 24, 6, 1, '“Run for cover, O sons of Benjamin; flee from Jerusalem! Sound the ram’s horn in Tekoa; send up a signal over Beth-haccherem, for disaster looms from the north, even great destruction.'),
  ('BSB', 'Jeremiah', 24, 6, 2, 'Though she is beautiful and delicate, I will destroy the Daughter of Zion.'),
  ('BSB', 'Jeremiah', 24, 6, 3, 'Shepherds and their flocks will come against her; they will pitch their tents all around her, each tending his own portion:'),
  ('BSB', 'Jeremiah', 24, 6, 4, '‘Prepare for battle against her; rise up, let us attack at noon. Woe to us, for the daylight is fading; the evening shadows grow long.'),
  ('BSB', 'Jeremiah', 24, 6, 5, 'Rise up, let us attack by night and destroy her fortresses!’”'),
  ('BSB', 'Jeremiah', 24, 6, 6, 'For this is what the LORD of Hosts says: “Cut down the trees and raise a siege ramp against Jerusalem. This city must be punished; there is nothing but oppression in her midst.'),
  ('BSB', 'Jeremiah', 24, 6, 7, 'As a well gushes its water, so she pours out her evil. Violence and destruction resound in her; sickness and wounds are ever before Me.'),
  ('BSB', 'Jeremiah', 24, 6, 8, 'Be forewarned, O Jerusalem, or I will turn away from you; I will make you a desolation, a land without inhabitant.”'),
  ('BSB', 'Jeremiah', 24, 6, 9, 'This is what the LORD of Hosts says: “Glean the remnant of Israel as thoroughly as a vine. Pass your hand once more like a grape gatherer over the branches.”'),
  ('BSB', 'Jeremiah', 24, 6, 10, 'To whom can I give this warning? Who will listen to me? Look, their ears are closed, so they cannot hear. See, the word of the LORD has become offensive to them; they find no pleasure in it.'),
  ('BSB', 'Jeremiah', 24, 6, 11, 'But I am full of the LORD’s wrath; I am tired of holding it back. “Pour it out on the children in the street, and on the young men gathered together. For both husband and wife will be captured, the old and the very old alike.'),
  ('BSB', 'Jeremiah', 24, 6, 12, 'Their houses will be turned over to others, their fields and wives as well, for I will stretch out My hand against the inhabitants of the land,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 6, 13, '“For from the least of them to the greatest, all are greedy for gain; from prophet to priest, all practice deceit.'),
  ('BSB', 'Jeremiah', 24, 6, 14, 'They dress the wound of My people with very little care, saying, ‘Peace, peace,’ when there is no peace at all.'),
  ('BSB', 'Jeremiah', 24, 6, 15, 'Are they ashamed of the abomination they have committed? No, they have no shame at all; they do not even know how to blush. So they will fall among the fallen; when I punish them, they will collapse,” says the LORD.'),
  ('BSB', 'Jeremiah', 24, 6, 16, 'This is what the LORD says: “Stand at the crossroads and look. Ask for the ancient paths: ‘Where is the good way?’ Then walk in it, and you will find rest for your souls. But they said, ‘We will not walk in it!’'),
  ('BSB', 'Jeremiah', 24, 6, 17, 'I appointed watchmen over you and said, ‘Listen for the sound of the ram’s horn.’ But they answered, ‘We will not listen!’'),
  ('BSB', 'Jeremiah', 24, 6, 18, 'Therefore hear, O nations, and learn, O congregations, what will happen to them.'),
  ('BSB', 'Jeremiah', 24, 6, 19, 'Hear, O earth! I am bringing disaster on this people, the fruit of their own schemes, because they have paid no attention to My word and have rejected My instruction.'),
  ('BSB', 'Jeremiah', 24, 6, 20, 'What use to Me is frankincense from Sheba or sweet cane from a distant land? Your burnt offerings are not acceptable; your sacrifices do not please Me.”'),
  ('BSB', 'Jeremiah', 24, 6, 21, 'Therefore this is what the LORD says: “I will lay stumbling blocks before this people; fathers and sons alike will be staggered; friends and neighbors will perish.”'),
  ('BSB', 'Jeremiah', 24, 6, 22, 'This is what the LORD says: “Behold, an army is coming from the land of the north; a great nation is stirred up from the ends of the earth.'),
  ('BSB', 'Jeremiah', 24, 6, 23, 'They grasp the bow and spear; they are cruel and merciless. Their voice roars like the sea, and they ride upon horses, lined up like men in formation against you, O Daughter of Zion.”'),
  ('BSB', 'Jeremiah', 24, 6, 24, 'We have heard the report; our hands hang limp. Anguish has gripped us, pain like that of a woman in labor.'),
  ('BSB', 'Jeremiah', 24, 6, 25, 'Do not go out to the fields; do not walk the road. For the enemy has a sword; terror is on every side.'),
  ('BSB', 'Jeremiah', 24, 6, 26, 'O daughter of my people, dress yourselves in sackcloth and roll in ashes. Mourn with bitter wailing, as you would for an only son, for suddenly the destroyer will come upon us.'),
  ('BSB', 'Jeremiah', 24, 6, 27, '“I have appointed you to examine My people like ore, so you may know and try their ways.'),
  ('BSB', 'Jeremiah', 24, 6, 28, 'All are hardened rebels, walking around as slanderers. They are bronze and iron; all of them are corrupt.'),
  ('BSB', 'Jeremiah', 24, 6, 29, 'The bellows blow fiercely, blasting away the lead with fire. The refining proceeds in vain, for the wicked are not purged.'),
  ('BSB', 'Jeremiah', 24, 6, 30, 'They are called rejected silver, because the LORD has rejected them.”'),
  ('BSB', 'Jeremiah', 24, 7, 1, 'This is the word that came to Jeremiah from the LORD, saying,'),
  ('BSB', 'Jeremiah', 24, 7, 2, '“Stand in the gate of the house of the LORD and proclaim this message: Hear the word of the LORD, all you people of Judah who enter through these gates to worship the LORD.'),
  ('BSB', 'Jeremiah', 24, 7, 3, 'Thus says the LORD of Hosts, the God of Israel: Correct your ways and deeds, and I will let you live in this place.'),
  ('BSB', 'Jeremiah', 24, 7, 4, 'Do not trust in deceptive words, chanting: ‘This is the temple of the LORD, the temple of the LORD, the temple of the LORD.’'),
  ('BSB', 'Jeremiah', 24, 7, 5, 'For if you really correct your ways and deeds, if you act justly toward one another,'),
  ('BSB', 'Jeremiah', 24, 7, 6, 'if you no longer oppress the foreigner and the fatherless and the widow, and if you no longer shed innocent blood in this place or follow other gods to your own harm,'),
  ('BSB', 'Jeremiah', 24, 7, 7, 'then I will let you live in this place, in the land that I gave to your fathers forever and ever.'),
  ('BSB', 'Jeremiah', 24, 7, 8, 'But look, you keep trusting in deceptive words to no avail.'),
  ('BSB', 'Jeremiah', 24, 7, 9, 'Will you steal and murder, commit adultery and perjury, burn incense to Baal, and follow other gods that you have not known,'),
  ('BSB', 'Jeremiah', 24, 7, 10, 'and then come and stand before Me in this house, which bears My Name, and say, ‘We are delivered, so we can continue with all these abominations’?'),
  ('BSB', 'Jeremiah', 24, 7, 11, 'Has this house, which bears My Name, become a den of robbers in your sight? Yes, I too have seen it, declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 7, 12, 'But go now to the place in Shiloh where I first made a dwelling for My Name, and see what I did to it because of the wickedness of My people Israel.'),
  ('BSB', 'Jeremiah', 24, 7, 13, 'And now, because you have done all these things, declares the LORD, and because I have spoken to you again and again but you would not listen, and I have called to you but you would not answer,'),
  ('BSB', 'Jeremiah', 24, 7, 14, 'therefore what I did to Shiloh I will now do to the house that bears My Name, the house in which you trust, the place that I gave to you and your fathers.'),
  ('BSB', 'Jeremiah', 24, 7, 15, 'And I will cast you out of My presence, just as I have cast out all your brothers, all the descendants of Ephraim.'),
  ('BSB', 'Jeremiah', 24, 7, 16, 'As for you, do not pray for these people, do not offer a plea or petition on their behalf, and do not beg Me, for I will not listen to you.'),
  ('BSB', 'Jeremiah', 24, 7, 17, 'Do you not see what they are doing in the cities of Judah and in the streets of Jerusalem?'),
  ('BSB', 'Jeremiah', 24, 7, 18, 'The sons gather wood, the fathers light the fire, and the women knead the dough to make cakes for the Queen of Heaven; they pour out drink offerings to other gods to provoke Me to anger.'),
  ('BSB', 'Jeremiah', 24, 7, 19, 'But am I the One they are provoking? declares the LORD. Is it not themselves they spite, to their own shame?'),
  ('BSB', 'Jeremiah', 24, 7, 20, 'Therefore this is what the Lord GOD says: Behold, My anger and My fury will be poured out on this place, on man and beast, on the trees of the field and the produce of the land, and it will burn and not be extinguished.'),
  ('BSB', 'Jeremiah', 24, 7, 21, 'This is what the LORD of Hosts, the God of Israel, says: Add your burnt offerings to your other sacrifices and eat the meat yourselves!'),
  ('BSB', 'Jeremiah', 24, 7, 22, 'For when I brought your fathers out of the land of Egypt, I did not merely command them about burnt offerings and sacrifices,'),
  ('BSB', 'Jeremiah', 24, 7, 23, 'but this is what I commanded them: Obey Me, and I will be your God, and you will be My people. You must walk in all the ways I have commanded you, so that it may go well with you.'),
  ('BSB', 'Jeremiah', 24, 7, 24, 'Yet they did not listen or incline their ear, but they followed the stubborn inclinations of their own evil hearts. They went backward and not forward.'),
  ('BSB', 'Jeremiah', 24, 7, 25, 'From the day your fathers came out of the land of Egypt until this day, I have sent you all My servants the prophets again and again.'),
  ('BSB', 'Jeremiah', 24, 7, 26, 'Yet they would not listen to Me or incline their ear, but they stiffened their necks and did more evil than their fathers.'),
  ('BSB', 'Jeremiah', 24, 7, 27, 'When you tell them all these things, they will not listen to you. When you call to them, they will not answer.'),
  ('BSB', 'Jeremiah', 24, 7, 28, 'Therefore you must say to them, ‘This is the nation that would not listen to the voice of the LORD their God and would not receive correction. Truth has perished; it has disappeared from their lips.'),
  ('BSB', 'Jeremiah', 24, 7, 29, 'Cut off your hair and throw it away. Raise up a lamentation on the barren heights, for the LORD has rejected and forsaken the generation of His wrath.’'),
  ('BSB', 'Jeremiah', 24, 7, 30, 'For the people of Judah have done evil in My sight, declares the LORD. They have set up their abominations in the house that bears My Name, and so have defiled it.'),
  ('BSB', 'Jeremiah', 24, 7, 31, 'They have built the high places of Topheth in the Valley of Hinnom so they could burn their sons and daughters in the fire—something I never commanded, nor did it even enter My mind.'),
  ('BSB', 'Jeremiah', 24, 7, 32, 'So behold, the days are coming, declares the LORD, when this place will no longer be called Topheth and the Valley of Hinnom, but the Valley of Slaughter. For they will bury the dead in Topheth until there is no more room.'),
  ('BSB', 'Jeremiah', 24, 7, 33, 'The corpses of this people will become food for the birds of the air and the beasts of the earth, and there will be no one to scare them away.'),
  ('BSB', 'Jeremiah', 24, 7, 34, 'I will remove from the cities of Judah and the streets of Jerusalem the sounds of joy and gladness and the voices of the bride and bridegroom, for the land will become a wasteland.”'),
  ('BSB', 'Jeremiah', 24, 8, 1, '“At that time,” declares the LORD, “the bones of the kings of Judah, the bones of the officials, the bones of the priests, the bones of the prophets, and the bones of the people of Jerusalem will be removed from their graves.'),
  ('BSB', 'Jeremiah', 24, 8, 2, 'They will be exposed to the sun and moon, and to all the host of heaven which they have loved, served, followed, consulted, and worshiped. Their bones will not be gathered up or buried, but will become like dung lying on the ground.'),
  ('BSB', 'Jeremiah', 24, 8, 3, 'And wherever I have banished them, the remnant of this evil family will choose death over life,” declares the LORD of Hosts.'),
  ('BSB', 'Jeremiah', 24, 8, 4, 'So you are to tell them this is what the LORD says: “Do men fall and not get up again? Does one turn away and not return?'),
  ('BSB', 'Jeremiah', 24, 8, 5, 'Why then have these people turned away? Why does Jerusalem always turn away? They cling to deceit; they refuse to return.'),
  ('BSB', 'Jeremiah', 24, 8, 6, 'I have listened and heard; they do not speak what is right. No one repents of his wickedness, asking, ‘What have I done?’ Everyone has pursued his own course like a horse charging into battle.'),
  ('BSB', 'Jeremiah', 24, 8, 7, 'Even the stork in the sky knows her appointed seasons. The turtledove, the swift, and the thrush keep their time of migration, but My people do not know the requirements of the LORD.'),
  ('BSB', 'Jeremiah', 24, 8, 8, 'How can you say, ‘We are wise, and the Law of the LORD is with us,’ when in fact the lying pen of the scribes has produced a deception?'),
  ('BSB', 'Jeremiah', 24, 8, 9, 'The wise will be put to shame; they will be dismayed and trapped. Since they have rejected the word of the LORD, what wisdom do they really have?'),
  ('BSB', 'Jeremiah', 24, 8, 10, 'Therefore I will give their wives to other men and their fields to new owners. For from the least of them to the greatest, all are greedy for gain; from prophet to priest, all practice deceit.'),
  ('BSB', 'Jeremiah', 24, 8, 11, 'They dress the wound of the daughter of My people with very little care, saying, ‘Peace, peace,’ when there is no peace at all.'),
  ('BSB', 'Jeremiah', 24, 8, 12, 'Are they ashamed of the abomination they have committed? No, they have no shame at all; they do not even know how to blush. So they will fall among the fallen; when I punish them, they will collapse, says the LORD.'),
  ('BSB', 'Jeremiah', 24, 8, 13, 'I will take away their harvest, declares the LORD. There will be no grapes on the vine, nor figs on the tree, and even the leaf will wither. Whatever I have given them will be lost to them.”'),
  ('BSB', 'Jeremiah', 24, 8, 14, 'Why are we just sitting here? Gather together, let us flee to the fortified cities and perish there, for the LORD our God has doomed us. He has given us poisoned water to drink, because we have sinned against the LORD.'),
  ('BSB', 'Jeremiah', 24, 8, 15, 'We hoped for peace, but no good has come, for a time of healing, but there was only terror.'),
  ('BSB', 'Jeremiah', 24, 8, 16, 'The snorting of enemy horses is heard from Dan. At the sound of the neighing of mighty steeds, the whole land quakes. They come to devour the land and everything in it, the city and all who dwell in it.'),
  ('BSB', 'Jeremiah', 24, 8, 17, '“For behold, I will send snakes among you, vipers that cannot be charmed, and they will bite you,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 8, 18, 'My sorrow is beyond healing; my heart is faint within me.'),
  ('BSB', 'Jeremiah', 24, 8, 19, 'Listen to the cry of the daughter of my people from a land far away: “Is the LORD no longer in Zion? Is her King no longer there?” “Why have they provoked Me to anger with their carved images, with their worthless foreign idols?”'),
  ('BSB', 'Jeremiah', 24, 8, 20, '“The harvest has passed, the summer has ended, but we have not been saved.”'),
  ('BSB', 'Jeremiah', 24, 8, 21, 'For the brokenness of the daughter of my people I am crushed. I mourn; horror has gripped me.'),
  ('BSB', 'Jeremiah', 24, 8, 22, 'Is there no balm in Gilead? Is no physician there? Why then has the health of the daughter of my people not been restored?'),
  ('BSB', 'Jeremiah', 24, 9, 1, 'Oh, that my head were a spring of water, and my eyes a fountain of tears! I would weep day and night over the slain daughter of my people.'),
  ('BSB', 'Jeremiah', 24, 9, 2, 'If only I had a traveler’s lodge in the wilderness, I would abandon my people and depart from them, for they are all adulterers, a crowd of faithless people.'),
  ('BSB', 'Jeremiah', 24, 9, 3, '“They bend their tongues like bows; lies prevail over truth in the land. For they proceed from evil to evil, and they do not take Me into account,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 9, 4, '“Let everyone guard against his neighbor; do not trust any brother, for every brother deals craftily, and every friend spreads slander.'),
  ('BSB', 'Jeremiah', 24, 9, 5, 'Each one betrays his friend; no one tells the truth. They have taught their tongues to lie; they wear themselves out committing iniquity.'),
  ('BSB', 'Jeremiah', 24, 9, 6, 'You dwell in the midst of deception; in their deceit they refuse to know Me,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 9, 7, 'Therefore this is what the LORD of Hosts says: “Behold, I will refine them and test them, for what else can I do because of the daughter of My people?'),
  ('BSB', 'Jeremiah', 24, 9, 8, 'Their tongues are deadly arrows; they speak deception. With his mouth a man speaks peace to his neighbor, but in his heart he sets a trap for him.'),
  ('BSB', 'Jeremiah', 24, 9, 9, 'Should I not punish them for these things? declares the LORD. Should I not avenge Myself on such a nation as this?”'),
  ('BSB', 'Jeremiah', 24, 9, 10, 'I will take up a weeping and wailing for the mountains, a dirge over the wilderness pasture, for they have been scorched so no one passes through, and the lowing of cattle is not heard. Both the birds of the air and the beasts have fled; they have gone away.'),
  ('BSB', 'Jeremiah', 24, 9, 11, '“And I will make Jerusalem a heap of rubble, a haunt for jackals; and I will make the cities of Judah a desolation, without inhabitant.”'),
  ('BSB', 'Jeremiah', 24, 9, 12, 'Who is the man wise enough to understand this? To whom has the mouth of the LORD spoken, that he may explain it? Why is the land destroyed and scorched like a desert, so no one can pass through it?'),
  ('BSB', 'Jeremiah', 24, 9, 13, 'And the LORD answered, “It is because they have forsaken My law, which I set before them; they have not walked in it or obeyed My voice.'),
  ('BSB', 'Jeremiah', 24, 9, 14, 'Instead, they have followed the stubbornness of their hearts and gone after the Baals, as their fathers taught them.”'),
  ('BSB', 'Jeremiah', 24, 9, 15, 'Therefore this is what the LORD of Hosts, the God of Israel, says: “Behold, I will feed this people wormwood and give them poisoned water to drink.'),
  ('BSB', 'Jeremiah', 24, 9, 16, 'I will scatter them among the nations that neither they nor their fathers have known, and I will send a sword after them until I have finished them off.”'),
  ('BSB', 'Jeremiah', 24, 9, 17, 'This is what the LORD of Hosts says: “Take note, and summon the wailing women; send for the most skillful among them.'),
  ('BSB', 'Jeremiah', 24, 9, 18, 'Let them come quickly and take up a lament over us, that our eyes may overflow with tears, and our eyelids may gush with water.'),
  ('BSB', 'Jeremiah', 24, 9, 19, 'For the sound of wailing is heard from Zion: ‘How devastated we are! How great is our shame! For we have abandoned the land because our dwellings have been torn down.’”'),
  ('BSB', 'Jeremiah', 24, 9, 20, 'Now, O women, hear the word of the LORD. Open your ears to the word of His mouth. Teach your daughters to wail, and one another to lament.'),
  ('BSB', 'Jeremiah', 24, 9, 21, 'For death has climbed in through our windows; it has entered our fortresses to cut off the children from the streets, the young men from the town squares.'),
  ('BSB', 'Jeremiah', 24, 9, 22, 'Declare that this is what the LORD says: “The corpses of men will fall like dung upon the open field, like newly cut grain behind the reaper, with no one to gather it.”'),
  ('BSB', 'Jeremiah', 24, 9, 23, 'This is what the LORD says: “Let not the wise man boast in his wisdom, nor the strong man in his strength, nor the wealthy man in his riches.'),
  ('BSB', 'Jeremiah', 24, 9, 24, 'But let him who boasts boast in this, that he understands and knows Me, that I am the LORD, who exercises loving devotion, justice and righteousness on the earth— for I delight in these things,” declares the LORD.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Jeremiah', 24, 9, 25, '“Behold, the days are coming,” declares the LORD, “when I will punish all who are circumcised yet uncircumcised:'),
  ('BSB', 'Jeremiah', 24, 9, 26, 'Egypt, Judah, Edom, Ammon, Moab, and all the inhabitants of the desert who clip the hair of their temples. For all these nations are uncircumcised, and the whole house of Israel is uncircumcised in heart.”'),
  ('BSB', 'Jeremiah', 24, 10, 1, 'Hear the word that the LORD speaks to you, O house of Israel.'),
  ('BSB', 'Jeremiah', 24, 10, 2, 'This is what the LORD says: “Do not learn the ways of the nations or be terrified by the signs in the heavens, though the nations themselves are terrified by them.'),
  ('BSB', 'Jeremiah', 24, 10, 3, 'For the customs of the peoples are worthless; they cut down a tree from the forest; it is shaped with a chisel by the hands of a craftsman.'),
  ('BSB', 'Jeremiah', 24, 10, 4, 'They adorn it with silver and gold and fasten it with hammer and nails, so that it will not totter.'),
  ('BSB', 'Jeremiah', 24, 10, 5, 'Like scarecrows in a cucumber patch, their idols cannot speak. They must be carried because they cannot walk. Do not fear them, for they can do no harm, and neither can they do any good.”'),
  ('BSB', 'Jeremiah', 24, 10, 6, 'There is none like You, O LORD. You are great, and Your name is mighty in power.'),
  ('BSB', 'Jeremiah', 24, 10, 7, 'Who would not fear You, O King of nations? This is Your due. For among all the wise men of the nations, and in all their kingdoms, there is none like You.'),
  ('BSB', 'Jeremiah', 24, 10, 8, 'But they are altogether senseless and foolish, instructed by worthless idols made of wood!'),
  ('BSB', 'Jeremiah', 24, 10, 9, 'Hammered silver is brought from Tarshish, and gold from Uphaz— the work of a craftsman from the hands of a goldsmith. Their clothes are blue and purple, all fashioned by skilled workers.'),
  ('BSB', 'Jeremiah', 24, 10, 10, 'But the LORD is the true God; He is the living God and eternal King. The earth quakes at His wrath, and the nations cannot endure His indignation.'),
  ('BSB', 'Jeremiah', 24, 10, 11, 'Thus you are to tell them: “These gods, who have made neither the heavens nor the earth, will perish from this earth and from under these heavens.”'),
  ('BSB', 'Jeremiah', 24, 10, 12, 'The LORD made the earth by His power; He established the world by His wisdom and stretched out the heavens by His understanding.'),
  ('BSB', 'Jeremiah', 24, 10, 13, 'When He thunders, the waters in the heavens roar; He causes the clouds to rise from the ends of the earth. He generates the lightning with the rain and brings forth the wind from His storehouses.'),
  ('BSB', 'Jeremiah', 24, 10, 14, 'Every man is senseless and devoid of knowledge; every goldsmith is put to shame by his idols. For his molten images are a fraud, and there is no breath in them.'),
  ('BSB', 'Jeremiah', 24, 10, 15, 'They are worthless, a work to be mocked. In the time of their punishment they will perish.'),
  ('BSB', 'Jeremiah', 24, 10, 16, 'The Portion of Jacob is not like these, for He is the Maker of all things, and Israel is the tribe of His inheritance— the LORD of Hosts is His name.'),
  ('BSB', 'Jeremiah', 24, 10, 17, 'Gather up your belongings from this land, you who live under siege.'),
  ('BSB', 'Jeremiah', 24, 10, 18, 'For this is what the LORD says: “Behold, at this time I will sling out the inhabitants of the land and bring distress upon them so that they may be captured.”'),
  ('BSB', 'Jeremiah', 24, 10, 19, 'Woe to me because of my brokenness; my wound is grievous! But I said, “This is truly my sickness, and I must bear it.”'),
  ('BSB', 'Jeremiah', 24, 10, 20, 'My tent is destroyed, and all its ropes are snapped. My sons have departed from me and are no more. I have no one left to pitch my tent or set up my curtains.'),
  ('BSB', 'Jeremiah', 24, 10, 21, 'For the shepherds have become senseless; they do not seek the LORD. Therefore they have not prospered, and all their flock is scattered.'),
  ('BSB', 'Jeremiah', 24, 10, 22, 'Listen! The sound of a report is coming— a great commotion from the land to the north. The cities of Judah will be made a desolation, a haunt for jackals.'),
  ('BSB', 'Jeremiah', 24, 10, 23, 'I know, O LORD, that a man’s way is not his own; no one who walks directs his own steps.'),
  ('BSB', 'Jeremiah', 24, 10, 24, 'Correct me, O LORD, but only with justice— not in Your anger, or You will bring me to nothing.'),
  ('BSB', 'Jeremiah', 24, 10, 25, 'Pour out Your wrath on the nations that do not acknowledge You, and on the families that do not call on Your name. For they have devoured Jacob; they have consumed him and finished him off; they have devastated his homeland.'),
  ('BSB', 'Jeremiah', 24, 11, 1, 'This is the word that came to Jeremiah from the LORD:'),
  ('BSB', 'Jeremiah', 24, 11, 2, '“Listen to the words of this covenant and tell them to the men of Judah and the residents of Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 11, 3, 'You must tell them that this is what the LORD, the God of Israel, says: Cursed is the man who does not obey the words of this covenant,'),
  ('BSB', 'Jeremiah', 24, 11, 4, 'which I commanded your forefathers when I brought them out of the land of Egypt, out of the iron furnace, saying, ‘Obey Me, and do everything I command you, and you will be My people, and I will be your God.’'),
  ('BSB', 'Jeremiah', 24, 11, 5, 'This was in order to establish the oath I swore to your forefathers, to give them a land flowing with milk and honey, as it is to this day.” “Amen, LORD,” I answered.'),
  ('BSB', 'Jeremiah', 24, 11, 6, 'Then the LORD said to me, “Proclaim all these words in the cities of Judah and in the streets of Jerusalem, saying: Hear the words of this covenant and carry them out.'),
  ('BSB', 'Jeremiah', 24, 11, 7, 'For from the time I brought your fathers out of the land of Egypt until today, I strongly warned them again and again, saying, ‘Obey My voice.’'),
  ('BSB', 'Jeremiah', 24, 11, 8, 'Yet they would not obey or incline their ears, but each one followed the stubbornness of his evil heart. So I brought on them all the curses of this covenant I had commanded them to follow but they did not keep.”'),
  ('BSB', 'Jeremiah', 24, 11, 9, 'And the LORD told me, “There is a conspiracy among the men of Judah and the residents of Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 11, 10, 'They have returned to the sins of their forefathers who refused to obey My words. They have followed other gods to serve them. The house of Israel and the house of Judah have broken the covenant I made with their fathers.'),
  ('BSB', 'Jeremiah', 24, 11, 11, 'Therefore this is what the LORD says: ‘I am about to bring upon them a disaster that they cannot escape. They will cry out to Me, but I will not listen to them.'),
  ('BSB', 'Jeremiah', 24, 11, 12, 'Then the cities of Judah and the residents of Jerusalem will go and cry out to the gods to which they have been burning incense, but these gods certainly will not save them in their time of disaster.'),
  ('BSB', 'Jeremiah', 24, 11, 13, 'Your gods are indeed as numerous as your cities, O Judah; the altars of shame you have set up—the altars to burn incense to Baal—are as many as the streets of Jerusalem.’'),
  ('BSB', 'Jeremiah', 24, 11, 14, 'As for you, do not pray for these people. Do not raise up a cry or a prayer on their behalf, for I will not be listening when they call out to Me in their time of disaster.'),
  ('BSB', 'Jeremiah', 24, 11, 15, 'What right has My beloved in My house, having carried out so many evil schemes? Can consecrated meat avert your doom, so that you can rejoice?'),
  ('BSB', 'Jeremiah', 24, 11, 16, 'The LORD once called you a flourishing olive tree, beautiful with well-formed fruit. But with a mighty roar He will set it on fire, and its branches will be consumed.'),
  ('BSB', 'Jeremiah', 24, 11, 17, 'The LORD of Hosts, who planted you, has decreed disaster against you on account of the evil that the house of Israel and the house of Judah have brought upon themselves, provoking Me to anger by burning incense to Baal.”'),
  ('BSB', 'Jeremiah', 24, 11, 18, 'And the LORD informed me, so I knew. Then You showed me their deeds.'),
  ('BSB', 'Jeremiah', 24, 11, 19, 'For I was like a gentle lamb led to slaughter; I did not know that they had plotted against me: “Let us destroy the tree with its fruit; let us cut him off from the land of the living, that his name may be remembered no more.”'),
  ('BSB', 'Jeremiah', 24, 11, 20, 'O LORD of Hosts, who judges righteously, who examines the heart and mind, let me see Your vengeance upon them, for to You I have committed my cause.'),
  ('BSB', 'Jeremiah', 24, 11, 21, 'Therefore this is what the LORD says concerning the people of Anathoth who are seeking your life and saying, “You must not prophesy in the name of the LORD, or you will die by our hand.”'),
  ('BSB', 'Jeremiah', 24, 11, 22, 'So this is what the LORD of Hosts says: “I will punish them. Their young men will die by the sword, their sons and daughters by famine.'),
  ('BSB', 'Jeremiah', 24, 11, 23, 'There will be no remnant, for I will bring disaster on the people of Anathoth in the year of their punishment.”'),
  ('BSB', 'Jeremiah', 24, 12, 1, 'Righteous are You, O LORD, when I plead before You. Yet about Your judgments I wish to contend with You: Why does the way of the wicked prosper? Why do all the faithless live at ease?'),
  ('BSB', 'Jeremiah', 24, 12, 2, 'You planted them, and they have taken root. They have grown and produced fruit. You are ever on their lips, but far from their hearts.'),
  ('BSB', 'Jeremiah', 24, 12, 3, 'But You know me, O LORD; You see me and test my heart toward You. Drag away the wicked like sheep to the slaughter and set them apart for the day of carnage.'),
  ('BSB', 'Jeremiah', 24, 12, 4, 'How long will the land mourn and the grass of every field be withered? Because of the evil of its residents, the animals and birds have been swept away, for the people have said, “He cannot see what our end will be.”'),
  ('BSB', 'Jeremiah', 24, 12, 5, '“If you have raced with men on foot and they have worn you out, how can you compete with horses? If you stumble in a peaceful land, how will you do in the thickets of the Jordan?'),
  ('BSB', 'Jeremiah', 24, 12, 6, 'Even your brothers— your own father’s household— even they have betrayed you; even they have cried aloud against you. Do not trust them, though they speak well of you.'),
  ('BSB', 'Jeremiah', 24, 12, 7, 'I have forsaken My house; I have abandoned My inheritance. I have given the love of My life into the hands of her enemies.'),
  ('BSB', 'Jeremiah', 24, 12, 8, 'My inheritance has become to Me like a lion in the forest. She has roared against Me; therefore I hate her.'),
  ('BSB', 'Jeremiah', 24, 12, 9, 'Is not My inheritance to Me like a speckled bird of prey with other birds of prey circling against her? Go, gather all the beasts of the field; bring them to devour her.'),
  ('BSB', 'Jeremiah', 24, 12, 10, 'Many shepherds have destroyed My vineyard; they have trampled My plot of ground. They have turned My pleasant field into a desolate wasteland.'),
  ('BSB', 'Jeremiah', 24, 12, 11, 'They have made it a desolation; desolate before Me, it mourns. All the land is laid waste, but no man takes it to heart.'),
  ('BSB', 'Jeremiah', 24, 12, 12, 'Over all the barren heights in the wilderness the destroyers have come, for the sword of the LORD devours from one end of the earth to the other. No flesh has peace.'),
  ('BSB', 'Jeremiah', 24, 12, 13, 'They have sown wheat but harvested thorns. They have exhausted themselves to no avail. Bear the shame of your harvest because of the fierce anger of the LORD.”'),
  ('BSB', 'Jeremiah', 24, 12, 14, 'This is what the LORD says: “As for all My evil neighbors who attack the inheritance that I bequeathed to My people Israel, I am about to uproot them from their land, and I will uproot the house of Judah from among them.'),
  ('BSB', 'Jeremiah', 24, 12, 15, 'But after I have uprooted them, I will once again have compassion on them and return each one to his inheritance and to his land.'),
  ('BSB', 'Jeremiah', 24, 12, 16, 'And if they will diligently learn the ways of My people and swear by My name, saying, ‘As surely as the LORD lives’—just as they once taught My people to swear by Baal—then they will be established among My people.'),
  ('BSB', 'Jeremiah', 24, 12, 17, 'But if they will not obey, then I will uproot that nation; I will uproot it and destroy it, declares the LORD.”'),
  ('BSB', 'Jeremiah', 24, 13, 1, 'This is what the LORD said to me: “Go and buy yourself a linen loincloth and put it around your waist, but do not let it touch water.”'),
  ('BSB', 'Jeremiah', 24, 13, 2, 'So I bought a loincloth as the LORD had instructed me, and I put it around my waist.'),
  ('BSB', 'Jeremiah', 24, 13, 3, 'Then the word of the LORD came to me a second time:'),
  ('BSB', 'Jeremiah', 24, 13, 4, '“Take the loincloth that you bought and are wearing, and go at once to Perath and hide it there in a crevice of the rocks.”'),
  ('BSB', 'Jeremiah', 24, 13, 5, 'So I went and hid it at Perath, as the LORD had commanded me.'),
  ('BSB', 'Jeremiah', 24, 13, 6, 'Many days later the LORD said to me, “Arise, go to Perath, and get the loincloth that I commanded you to hide there.”'),
  ('BSB', 'Jeremiah', 24, 13, 7, 'So I went to Perath and dug up the loincloth, and I took it from the place where I had hidden it. But now it was ruined—of no use at all.'),
  ('BSB', 'Jeremiah', 24, 13, 8, 'Then the word of the LORD came to me:'),
  ('BSB', 'Jeremiah', 24, 13, 9, '“This is what the LORD says: In the same way I will ruin the pride of Judah and the great pride of Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 13, 10, 'These evil people, who refuse to listen to My words, who follow the stubbornness of their own hearts, and who go after other gods to serve and worship them, they will be like this loincloth—of no use at all.'),
  ('BSB', 'Jeremiah', 24, 13, 11, 'For just as a loincloth clings to a man’s waist, so I have made the whole house of Israel and the whole house of Judah cling to Me, declares the LORD, so that they might be My people for My renown and praise and glory. But they did not listen.'),
  ('BSB', 'Jeremiah', 24, 13, 12, 'Therefore you are to tell them that this is what the LORD, the God of Israel, says: ‘Every wineskin shall be filled with wine.’ And when they reply, ‘Don’t we surely know that every wineskin should be filled with wine?’'),
  ('BSB', 'Jeremiah', 24, 13, 13, 'then you are to tell them that this is what the LORD says: ‘I am going to fill with drunkenness all who live in this land—the kings who sit on David’s throne, the priests, the prophets, and all the people of Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 13, 14, 'I will smash them against one another, fathers and sons alike, declares the LORD. I will allow no mercy or pity or compassion to keep Me from destroying them.’”'),
  ('BSB', 'Jeremiah', 24, 13, 15, 'Listen and give heed. Do not be arrogant, for the LORD has spoken.'),
  ('BSB', 'Jeremiah', 24, 13, 16, 'Give glory to the LORD your God before He brings darkness, before your feet stumble on the dusky mountains. You wait for light, but He turns it into deep gloom and thick darkness.'),
  ('BSB', 'Jeremiah', 24, 13, 17, 'But if you do not listen, I will weep in secret because of your pride. My eyes will overflow with tears, because the LORD’s flock has been taken captive.'),
  ('BSB', 'Jeremiah', 24, 13, 18, 'Say to the king and to the queen mother: “Take a lowly seat, for your glorious crowns have fallen from your heads.”'),
  ('BSB', 'Jeremiah', 24, 13, 19, 'The cities of the Negev have been shut tight, and no one can open them. All Judah has been carried into exile, wholly taken captive.'),
  ('BSB', 'Jeremiah', 24, 13, 20, 'Lift up your eyes and see those coming from the north. Where is the flock entrusted to you, the sheep that were your pride?'),
  ('BSB', 'Jeremiah', 24, 13, 21, 'What will you say when He sets over you close allies whom you yourself trained? Will not pangs of anguish grip you, as they do a woman in labor?'),
  ('BSB', 'Jeremiah', 24, 13, 22, 'And if you ask yourself, “Why has this happened to me?” It is because of the magnitude of your iniquity that your skirts have been stripped off and your body has been exposed.'),
  ('BSB', 'Jeremiah', 24, 13, 23, 'Can the Ethiopian change his skin, or the leopard his spots? Neither are you able to do good— you who are accustomed to doing evil.'),
  ('BSB', 'Jeremiah', 24, 13, 24, '“I will scatter you like chaff driven by the desert wind.'),
  ('BSB', 'Jeremiah', 24, 13, 25, 'This is your lot, the portion I have measured to you,” declares the LORD, “because you have forgotten Me and trusted in falsehood.'),
  ('BSB', 'Jeremiah', 24, 13, 26, 'So I will pull your skirts up over your face, that your shame may be seen.'),
  ('BSB', 'Jeremiah', 24, 13, 27, 'Your adulteries and lustful neighings, your shameless prostitution on the hills and in the fields— I have seen your detestable acts. Woe to you, O Jerusalem! How long will you remain unclean?”'),
  ('BSB', 'Jeremiah', 24, 14, 1, 'This is the word of the LORD that came to Jeremiah concerning the drought:'),
  ('BSB', 'Jeremiah', 24, 14, 2, '“Judah mourns and her gates languish. Her people wail for the land, and a cry goes up from Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 14, 3, 'The nobles send their servants for water; they go to the cisterns, but find no water; their jars return empty. They are ashamed and humiliated; they cover their heads.'),
  ('BSB', 'Jeremiah', 24, 14, 4, 'The ground is cracked because no rain has fallen on the land. The farmers are ashamed; they cover their heads.'),
  ('BSB', 'Jeremiah', 24, 14, 5, 'Even the doe in the field deserts her newborn fawn because there is no grass.'),
  ('BSB', 'Jeremiah', 24, 14, 6, 'Wild donkeys stand on barren heights; they pant for air like jackals; their eyes fail for lack of pasture.”'),
  ('BSB', 'Jeremiah', 24, 14, 7, 'Although our iniquities testify against us, O LORD, act for the sake of Your name. Indeed, our rebellions are many; we have sinned against You.'),
  ('BSB', 'Jeremiah', 24, 14, 8, 'O Hope of Israel, its Savior in times of distress, why are You like a stranger in the land, like a traveler who stays but a night?'),
  ('BSB', 'Jeremiah', 24, 14, 9, 'Why are You like a man taken by surprise, like a warrior powerless to save? Yet You are among us, O LORD, and we are called by Your name. Do not forsake us!'),
  ('BSB', 'Jeremiah', 24, 14, 10, 'This is what the LORD says about this people: “Truly they love to wander; they have not restrained their feet. So the LORD does not accept them; He will now remember their guilt and call their sins to account.”'),
  ('BSB', 'Jeremiah', 24, 14, 11, 'Then the LORD said to me, “Do not pray for the well-being of this people.'),
  ('BSB', 'Jeremiah', 24, 14, 12, 'Although they may fast, I will not listen to their cry; although they may offer burnt offerings and grain offerings, I will not accept them. Instead, I will finish them off by sword and famine and plague.”'),
  ('BSB', 'Jeremiah', 24, 14, 13, '“Ah, Lord GOD!” I replied, “Look, the prophets are telling them, ‘You will not see the sword or suffer famine, but I will give you lasting peace in this place.’”'),
  ('BSB', 'Jeremiah', 24, 14, 14, '“The prophets are prophesying lies in My name,” replied the LORD. “I did not send them or appoint them or speak to them. They are prophesying to you a false vision, a worthless divination, the futility and delusion of their own minds.'),
  ('BSB', 'Jeremiah', 24, 14, 15, 'Therefore this is what the LORD says about the prophets who prophesy in My name: I did not send them, yet they say, ‘No sword or famine will touch this land.’ By sword and famine these very prophets will meet their end!'),
  ('BSB', 'Jeremiah', 24, 14, 16, 'And the people to whom they prophesy will be thrown into the streets of Jerusalem because of famine and sword. There will be no one to bury them or their wives, their sons or their daughters. I will pour out their own evil upon them.'),
  ('BSB', 'Jeremiah', 24, 14, 17, 'You are to speak this word to them: ‘My eyes overflow with tears; day and night they do not cease, for the virgin daughter of my people has been shattered by a crushing blow, a severely grievous wound.'),
  ('BSB', 'Jeremiah', 24, 14, 18, 'If I go out to the country, I see those slain by the sword; if I enter the city, I see those ravaged by famine! For both prophet and priest travel to a land they do not know.’”'),
  ('BSB', 'Jeremiah', 24, 14, 19, 'Have You rejected Judah completely? Do You despise Zion? Why have You stricken us so that we are beyond healing? We hoped for peace, but no good has come, and for the time of healing, but there was only terror.'),
  ('BSB', 'Jeremiah', 24, 14, 20, 'We acknowledge our wickedness, O LORD, the guilt of our fathers; indeed, we have sinned against You.'),
  ('BSB', 'Jeremiah', 24, 14, 21, 'For the sake of Your name do not despise us; do not disgrace Your glorious throne. Remember Your covenant with us; do not break it.'),
  ('BSB', 'Jeremiah', 24, 14, 22, 'Can the worthless idols of the nations bring rain? Do the skies alone send showers? Is this not by You, O LORD our God? So we put our hope in You, for You have done all these things.'),
  ('BSB', 'Jeremiah', 24, 15, 1, 'Then the LORD said to me: “Even if Moses and Samuel should stand before Me, My heart would not go out to this people. Send them from My presence, and let them go.'),
  ('BSB', 'Jeremiah', 24, 15, 2, 'If they ask you, ‘Where shall we go?’ you are to tell them that this is what the LORD says: ‘Those destined for death, to death; those destined for the sword, to the sword; those destined for famine, to famine; and those destined for captivity, to captivity.’'),
  ('BSB', 'Jeremiah', 24, 15, 3, 'I will appoint over them four kinds of destroyers, declares the LORD: the sword to kill, the dogs to drag away, and the birds of the air and beasts of the earth to devour and destroy.'),
  ('BSB', 'Jeremiah', 24, 15, 4, 'I will make them a horror to all the kingdoms of the earth because of what Manasseh son of Hezekiah king of Judah did in Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 15, 5, 'Who will have pity on you, O Jerusalem? Who will mourn for you? Who will turn aside to ask about your welfare?'),
  ('BSB', 'Jeremiah', 24, 15, 6, 'You have forsaken Me, declares the LORD. You have turned your back. So I will stretch out My hand against you and I will destroy you; I am weary of showing compassion.'),
  ('BSB', 'Jeremiah', 24, 15, 7, 'I will scatter them with a winnowing fork at the gates of the land. I will bereave and destroy My people who have not turned from their ways.'),
  ('BSB', 'Jeremiah', 24, 15, 8, 'I will make their widows more numerous than the sand of the sea. I will bring a destroyer at noon against the mothers of young men. I will suddenly bring upon them anguish and dismay.'),
  ('BSB', 'Jeremiah', 24, 15, 9, 'The mother of seven will grow faint; she will breathe her last breath. Her sun will set while it is still day; she will be disgraced and humiliated. And the rest I will put to the sword in the presence of their enemies,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 15, 10, 'Woe to me, my mother, that you have borne me, a man of strife and conflict in all the land. I have neither lent nor borrowed, yet everyone curses me.'),
  ('BSB', 'Jeremiah', 24, 15, 11, 'The LORD said: “Surely I will deliver you for a good purpose; surely I will intercede with your enemy in your time of trouble, in your time of distress.'),
  ('BSB', 'Jeremiah', 24, 15, 12, 'Can anyone smash iron— iron from the north—or bronze?'),
  ('BSB', 'Jeremiah', 24, 15, 13, 'Your wealth and your treasures I will give up as plunder, without charge for all your sins within all your borders.'),
  ('BSB', 'Jeremiah', 24, 15, 14, 'Then I will enslave you to your enemies in a land you do not know, for My anger will kindle a fire that will burn against you.”'),
  ('BSB', 'Jeremiah', 24, 15, 15, 'You understand, O LORD; remember me and attend to me. Avenge me against my persecutors. In Your patience, do not take me away. Know that I endure reproach for Your honor.'),
  ('BSB', 'Jeremiah', 24, 15, 16, 'Your words were found, and I ate them. Your words became my joy and my heart’s delight. For I bear Your name, O LORD God of Hosts.'),
  ('BSB', 'Jeremiah', 24, 15, 17, 'I never sat with the band of revelers, nor did I celebrate with them. Because Your hand was on me, I sat alone, for You have filled me with indignation.'),
  ('BSB', 'Jeremiah', 24, 15, 18, 'Why is my pain unending, and my wound incurable, refusing to be healed? You have indeed become like a mirage to me— water that is not there.'),
  ('BSB', 'Jeremiah', 24, 15, 19, 'Therefore this is what the LORD says: “If you return, I will restore you; you will stand in My presence. And if you speak words that are noble instead of worthless, you will be My spokesman. It is they who must turn to you, but you must not turn to them.'),
  ('BSB', 'Jeremiah', 24, 15, 20, 'Then I will make you a wall to this people, a fortified wall of bronze; they will fight against you but will not overcome you, for I am with you to save and deliver you, declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 15, 21, 'I will deliver you from the hand of the wicked and redeem you from the grasp of the ruthless.”'),
  ('BSB', 'Jeremiah', 24, 16, 1, 'Then the word of the LORD came to me, saying,'),
  ('BSB', 'Jeremiah', 24, 16, 2, '“You must not marry or have sons or daughters in this place.”'),
  ('BSB', 'Jeremiah', 24, 16, 3, 'For this is what the LORD says concerning the sons and daughters born in this place, and the mothers who bore them, and the fathers who fathered them in this land:'),
  ('BSB', 'Jeremiah', 24, 16, 4, '“They will die from deadly diseases. They will not be mourned or buried, but will lie like dung on the ground. They will be finished off by sword and famine, and their corpses will become food for the birds of the air and beasts of the earth.”'),
  ('BSB', 'Jeremiah', 24, 16, 5, 'Indeed, this is what the LORD says: “Do not enter a house where there is a funeral meal. Do not go to mourn or show sympathy, for I have removed from this people My peace, My loving devotion, and My compassion,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 16, 6, '“Both great and small will die in this land. They will not be buried or mourned, nor will anyone cut himself or shave his head for them.'),
  ('BSB', 'Jeremiah', 24, 16, 7, 'No food will be offered to comfort those who mourn the dead; not even a cup of consolation will be given for the loss of a father or mother.'),
  ('BSB', 'Jeremiah', 24, 16, 8, 'You must not enter a house where there is feasting and sit down with them to eat and drink.'),
  ('BSB', 'Jeremiah', 24, 16, 9, 'For this is what the LORD of Hosts, the God of Israel, says: I am going to remove from this place, before your very eyes and in your days, the sounds of joy and gladness, the voices of the bride and bridegroom.'),
  ('BSB', 'Jeremiah', 24, 16, 10, 'When you tell these people all these things, they will ask you, ‘Why has the LORD pronounced all this great disaster against us? What is our guilt? What is the sin that we have committed against the LORD our God?’'),
  ('BSB', 'Jeremiah', 24, 16, 11, 'Then you are to answer them: ‘It is because your fathers have forsaken Me, declares the LORD, and followed other gods, and served and worshiped them. They abandoned Me and did not keep My instruction.'),
  ('BSB', 'Jeremiah', 24, 16, 12, 'And you have done more evil than your fathers. See how each of you follows the stubbornness of his evil heart instead of obeying Me.'),
  ('BSB', 'Jeremiah', 24, 16, 13, 'So I will cast you out of this land into a land that neither you nor your fathers have known. There you will serve other gods day and night, for I will show you no favor.’'),
  ('BSB', 'Jeremiah', 24, 16, 14, 'Yet behold, the days are coming, declares the LORD, when they will no longer say, ‘As surely as the LORD lives, who brought the Israelites up out of the land of Egypt.’'),
  ('BSB', 'Jeremiah', 24, 16, 15, 'Instead they will say, ‘As surely as the LORD lives, who brought the Israelites up out of the land of the north and all the other lands to which He had banished them.’ For I will return them to their land that I gave to their forefathers.'),
  ('BSB', 'Jeremiah', 24, 16, 16, 'But for now I will send for many fishermen, declares the LORD, and they will catch them. After that I will send for many hunters, and they will hunt them down on every mountain and hill, even from the clefts of the rocks.'),
  ('BSB', 'Jeremiah', 24, 16, 17, 'For My eyes are on all their ways. They are not hidden from My face, and their guilt is not concealed from My eyes.'),
  ('BSB', 'Jeremiah', 24, 16, 18, 'And I will first repay them double their iniquity and their sin, because they have defiled My land with the carcasses of their detestable idols, and they have filled My inheritance with their abominations.”'),
  ('BSB', 'Jeremiah', 24, 16, 19, 'O LORD, my strength and my fortress, my refuge in the day of distress, the nations will come to You from the ends of the earth, and they will say, “Our fathers inherited nothing but lies, worthless idols of no benefit at all.'),
  ('BSB', 'Jeremiah', 24, 16, 20, 'Can man make gods for himself? Such are not gods!”'),
  ('BSB', 'Jeremiah', 24, 16, 21, '“Therefore behold, I will inform them, and this time I will make them know My power and My might; then they will know that My name is the LORD.'),
  ('BSB', 'Jeremiah', 24, 17, 1, '“The sin of Judah is written with an iron stylus, engraved with a diamond point on the tablets of their hearts and on the horns of their altars.'),
  ('BSB', 'Jeremiah', 24, 17, 2, 'Even their children remember their altars and Asherah poles by the green trees and on the high hills.'),
  ('BSB', 'Jeremiah', 24, 17, 3, 'O My mountain in the countryside, I will give over your wealth and all your treasures as plunder, because of the sin of your high places, within all your borders.'),
  ('BSB', 'Jeremiah', 24, 17, 4, 'And you yourself will relinquish the inheritance that I gave you. I will enslave you to your enemies in a land that you do not know, for you have kindled My anger; it will burn forever.”'),
  ('BSB', 'Jeremiah', 24, 17, 5, 'This is what the LORD says: “Cursed is the man who trusts in mankind, who makes the flesh his strength and turns his heart from the LORD.'),
  ('BSB', 'Jeremiah', 24, 17, 6, 'He will be like a shrub in the desert; he will not see when prosperity comes. He will dwell in the parched places of the desert, in a salt land where no one lives.'),
  ('BSB', 'Jeremiah', 24, 17, 7, 'But blessed is the man who trusts in the LORD, whose confidence is in Him.'),
  ('BSB', 'Jeremiah', 24, 17, 8, 'He is like a tree planted by the waters that sends out its roots toward the stream. It does not fear when the heat comes, and its leaves are always green. It does not worry in a year of drought, nor does it cease to produce fruit.'),
  ('BSB', 'Jeremiah', 24, 17, 9, 'The heart is deceitful above all things and beyond cure. Who can understand it?'),
  ('BSB', 'Jeremiah', 24, 17, 10, 'I, the LORD, search the heart; I examine the mind to reward a man according to his way, by what his deeds deserve.'),
  ('BSB', 'Jeremiah', 24, 17, 11, 'Like a partridge hatching eggs it did not lay is the man who makes a fortune unjustly. In the middle of his days his riches will desert him, and in the end he will be the fool.”'),
  ('BSB', 'Jeremiah', 24, 17, 12, 'A glorious throne, exalted from the beginning, is the place of our sanctuary.'),
  ('BSB', 'Jeremiah', 24, 17, 13, 'O LORD, the hope of Israel, all who abandon You will be put to shame. All who turn away will be written in the dust, for they have abandoned the LORD, the fountain of living water.'),
  ('BSB', 'Jeremiah', 24, 17, 14, 'Heal me, O LORD, and I will be healed; save me, and I will be saved, for You are my praise.'),
  ('BSB', 'Jeremiah', 24, 17, 15, 'Behold, they keep saying to me, “Where is the word of the LORD? Let it come now!”'),
  ('BSB', 'Jeremiah', 24, 17, 16, 'But I have not run away from being Your shepherd; I have not desired the day of despair. You know that the utterance of my lips was spoken in Your presence.'),
  ('BSB', 'Jeremiah', 24, 17, 17, 'Do not become a terror to me; You are my refuge in the day of disaster.'),
  ('BSB', 'Jeremiah', 24, 17, 18, 'Let my persecutors be put to shame, but do not let me be put to shame. Let them be terrified, but do not let me be terrified. Bring upon them the day of disaster and shatter them with double destruction.'),
  ('BSB', 'Jeremiah', 24, 17, 19, 'This is what the LORD said to me: “Go and stand at the gate of the people, through which the kings of Judah go in and out; and stand at all the other gates of Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 17, 20, 'Say to them, ‘Hear the word of the LORD, O kings of Judah, all people of Judah and Jerusalem who enter through these gates.'),
  ('BSB', 'Jeremiah', 24, 17, 21, 'This is what the LORD says: Take heed for yourselves; do not carry a load or bring it through the gates of Jerusalem on the Sabbath day.'),
  ('BSB', 'Jeremiah', 24, 17, 22, 'You must not carry a load out of your houses or do any work on the Sabbath day, but you must keep the Sabbath day holy, just as I commanded your forefathers.'),
  ('BSB', 'Jeremiah', 24, 17, 23, 'Yet they would not listen or incline their ear, but they stiffened their necks and would not listen or receive My discipline.'),
  ('BSB', 'Jeremiah', 24, 17, 24, 'If, however, you listen carefully to Me, says the LORD, and bring no load through the gates of this city on the Sabbath day, and keep the Sabbath day holy, and do no work on it,'),
  ('BSB', 'Jeremiah', 24, 17, 25, 'then kings and princes will enter through the gates of this city. They will sit on the throne of David, riding in chariots and on horses with their officials, along with the men of Judah and the residents of Jerusalem, and this city will be inhabited forever.'),
  ('BSB', 'Jeremiah', 24, 17, 26, 'And people will come from the cities of Judah and the places around Jerusalem, from the land of Benjamin, and from the foothills, the hill country, and the Negev, bringing burnt offerings and sacrifices, grain offerings and frankincense, and thank offerings to the house of the LORD.'),
  ('BSB', 'Jeremiah', 24, 17, 27, 'But if you do not listen to Me to keep the Sabbath day holy by not carrying a load while entering the gates of Jerusalem on the Sabbath day, then I will kindle an unquenchable fire in its gates to consume the citadels of Jerusalem.’”'),
  ('BSB', 'Jeremiah', 24, 18, 1, 'This is the word that came to Jeremiah from the LORD:'),
  ('BSB', 'Jeremiah', 24, 18, 2, '“Go down at once to the potter’s house, and there I will reveal My message to you.”'),
  ('BSB', 'Jeremiah', 24, 18, 3, 'So I went down to the potter’s house and saw him working at the wheel.'),
  ('BSB', 'Jeremiah', 24, 18, 4, 'But the vessel that he was shaping from the clay became flawed in his hand; so he formed it into another vessel, as it seemed best for him to do.'),
  ('BSB', 'Jeremiah', 24, 18, 5, 'Then the word of the LORD came to me, saying,'),
  ('BSB', 'Jeremiah', 24, 18, 6, '“O house of Israel, declares the LORD, can I not treat you as this potter treats his clay? Just like clay in the potter’s hand, so are you in My hand, O house of Israel.'),
  ('BSB', 'Jeremiah', 24, 18, 7, 'At any time I might announce that a nation or kingdom will be uprooted, torn down, and destroyed.'),
  ('BSB', 'Jeremiah', 24, 18, 8, 'But if that nation I warned turns from its evil, then I will relent of the disaster I had planned to bring.'),
  ('BSB', 'Jeremiah', 24, 18, 9, 'And if at another time I announce that I will build up and establish a nation or kingdom,'),
  ('BSB', 'Jeremiah', 24, 18, 10, 'and if it does evil in My sight and does not listen to My voice, then I will relent of the good I had intended for it.'),
  ('BSB', 'Jeremiah', 24, 18, 11, 'Now therefore, tell the men of Judah and the residents of Jerusalem that this is what the LORD says: ‘Behold, I am planning a disaster for you and devising a plan against you. Turn now, each of you, from your evil ways, and correct your ways and deeds.’'),
  ('BSB', 'Jeremiah', 24, 18, 12, 'But they will reply, ‘It is hopeless. We will follow our own plans, and each of us will act according to the stubbornness of his evil heart.’”'),
  ('BSB', 'Jeremiah', 24, 18, 13, 'Therefore this is what the LORD says: “Inquire among the nations: Who has ever heard things like these? Virgin Israel has done a most terrible thing.'),
  ('BSB', 'Jeremiah', 24, 18, 14, 'Does the snow of Lebanon ever leave its rocky slopes? Or do its cool waters flowing from a distance ever run dry?'),
  ('BSB', 'Jeremiah', 24, 18, 15, 'Yet My people have forgotten Me. They burn incense to worthless idols that make them stumble in their ways, leaving the ancient roads to walk on rutted bypaths instead of on the highway.'),
  ('BSB', 'Jeremiah', 24, 18, 16, 'They have made their land a desolation, a perpetual object of scorn; all who pass by will be appalled and shake their heads.'),
  ('BSB', 'Jeremiah', 24, 18, 17, 'I will scatter them before the enemy like the east wind. I will show them My back and not My face in the day of their calamity.”'),
  ('BSB', 'Jeremiah', 24, 18, 18, 'Then some said, “Come, let us make plans against Jeremiah, for the law will never be lost to the priest, nor counsel to the wise, nor an oracle to the prophet. Come, let us denounce him and pay no heed to any of his words.”'),
  ('BSB', 'Jeremiah', 24, 18, 19, 'Attend to me, O LORD. Hear what my accusers are saying!'),
  ('BSB', 'Jeremiah', 24, 18, 20, 'Should good be repaid with evil? Yet they have dug a pit for me. Remember how I stood before You to speak good on their behalf, to turn Your wrath from them.'),
  ('BSB', 'Jeremiah', 24, 18, 21, 'Therefore, hand their children over to famine; pour out the power of the sword upon them. Let their wives become childless and widowed; let their husbands be slain by disease, their young men struck down by the sword in battle.'),
  ('BSB', 'Jeremiah', 24, 18, 22, 'Let a cry be heard from their houses when You suddenly bring raiders against them, for they have dug a pit to capture me and have hidden snares for my feet.'),
  ('BSB', 'Jeremiah', 24, 18, 23, 'But You, O LORD, know all their deadly plots against me. Do not wipe out their guilt or blot out their sin from Your sight. Let them be overthrown before You; deal with them in the time of Your anger.'),
  ('BSB', 'Jeremiah', 24, 19, 1, 'This is what the LORD says: “Go and buy a clay jar from a potter. Take some of the elders of the people and leaders of the priests,'),
  ('BSB', 'Jeremiah', 24, 19, 2, 'and go out to the Valley of Ben-hinnom near the entrance of the Potsherd Gate. Proclaim there the words I speak to you,'),
  ('BSB', 'Jeremiah', 24, 19, 3, 'saying, ‘Hear the word of the LORD, O kings of Judah and residents of Jerusalem. This is what the LORD of Hosts, the God of Israel, says: I am going to bring such disaster on this place that the ears of all who hear of it will ring,'),
  ('BSB', 'Jeremiah', 24, 19, 4, 'because they have abandoned Me and made this a foreign place. They have burned incense in this place to other gods that neither they nor their fathers nor the kings of Judah have ever known. They have filled this place with the blood of the innocent.'),
  ('BSB', 'Jeremiah', 24, 19, 5, 'They have built high places to Baal on which to burn their children in the fire as offerings to Baal—something I never commanded or mentioned, nor did it even enter My mind.'),
  ('BSB', 'Jeremiah', 24, 19, 6, 'So behold, the days are coming, declares the LORD, when this place will no longer be called Topheth or the Valley of Ben-hinnom, but the Valley of Slaughter.'),
  ('BSB', 'Jeremiah', 24, 19, 7, 'And in this place I will ruin the plans of Judah and Jerusalem. I will make them fall by the sword before their enemies, by the hands of those who seek their lives, and I will give their carcasses as food to the birds of the air and the beasts of the earth.'),
  ('BSB', 'Jeremiah', 24, 19, 8, 'I will make this city a desolation and an object of scorn. All who pass by will be appalled and will scoff at all her wounds.'),
  ('BSB', 'Jeremiah', 24, 19, 9, 'I will make them eat the flesh of their sons and daughters, and they will eat one another’s flesh in the siege and distress inflicted on them by their enemies who seek their lives.’'),
  ('BSB', 'Jeremiah', 24, 19, 10, 'Then you are to shatter the jar in the presence of the men who accompany you,'),
  ('BSB', 'Jeremiah', 24, 19, 11, 'and you are to proclaim to them that this is what the LORD of Hosts says: I will shatter this nation and this city, like one shatters a potter’s jar that can never again be repaired. They will bury the dead in Topheth until there is no more room to bury them.'),
  ('BSB', 'Jeremiah', 24, 19, 12, 'This is what I will do to this place and to its residents, declares the LORD. I will make this city like Topheth.'),
  ('BSB', 'Jeremiah', 24, 19, 13, 'The houses of Jerusalem and the houses of the kings of Judah will be defiled like that place, Topheth—all the houses on whose rooftops they burned incense to all the host of heaven and poured out drink offerings to other gods.”'),
  ('BSB', 'Jeremiah', 24, 19, 14, 'Then Jeremiah returned from Topheth, where the LORD had sent him to prophesy, and he stood in the courtyard of the house of the LORD and proclaimed to all the people,'),
  ('BSB', 'Jeremiah', 24, 19, 15, '“This is what the LORD of Hosts, the God of Israel, says: ‘Behold, I am about to bring on this city and on all the villages around it every disaster I have pronounced against them, because they have stiffened their necks so as not to heed My words.’”'),
  ('BSB', 'Jeremiah', 24, 20, 1, 'When Pashhur the priest, the son of Immer and the chief official in the house of the LORD, heard Jeremiah prophesying these things,'),
  ('BSB', 'Jeremiah', 24, 20, 2, 'he had Jeremiah the prophet beaten and put in the stocks at the Upper Gate of Benjamin, which was by the house of the LORD.'),
  ('BSB', 'Jeremiah', 24, 20, 3, 'The next day, when Pashhur released Jeremiah from the stocks, Jeremiah said to him, “The LORD does not call you Pashhur, but Magor-missabib.'),
  ('BSB', 'Jeremiah', 24, 20, 4, 'For this is what the LORD says: ‘I will make you a terror to yourself and to all your friends. They will fall by the sword of their enemies before your very eyes. And I will hand Judah over to the king of Babylon, and he will carry them away to Babylon and put them to the sword.'),
  ('BSB', 'Jeremiah', 24, 20, 5, 'I will give away all the wealth of this city—all its products and valuables, and all the treasures of the kings of Judah—to their enemies. They will plunder them, seize them, and carry them off to Babylon.'),
  ('BSB', 'Jeremiah', 24, 20, 6, 'And you, Pashhur, and all who live in your house, will go into captivity. You will go to Babylon, and there you will die and be buried—you and all your friends to whom you have prophesied these lies.’”'),
  ('BSB', 'Jeremiah', 24, 20, 7, 'You have deceived me, O LORD, and I was deceived. You have overcome me and prevailed. I am a laughingstock all day long; everyone mocks me.'),
  ('BSB', 'Jeremiah', 24, 20, 8, 'For whenever I speak, I cry out; I proclaim violence and destruction. For the word of the LORD has become to me a reproach and derision all day long.'),
  ('BSB', 'Jeremiah', 24, 20, 9, 'If I say, “I will not mention Him or speak any more in His name,” His message becomes a fire burning in my heart, shut up in my bones, and I become weary of holding it in, and I cannot prevail.'),
  ('BSB', 'Jeremiah', 24, 20, 10, 'For I have heard the whispering of many: “Terror is on every side! Report him; let us report him!” All my trusted friends watch for my fall: “Perhaps he will be deceived so that we may prevail against him and take our vengeance upon him.”'),
  ('BSB', 'Jeremiah', 24, 20, 11, 'But the LORD is with me like a fearsome warrior. Therefore, my persecutors will stumble and will not prevail. Since they have not succeeded, they will be utterly put to shame, with an everlasting disgrace that will never be forgotten.'),
  ('BSB', 'Jeremiah', 24, 20, 12, 'O LORD of Hosts, who examines the righteous, who sees the heart and mind, let me see Your vengeance upon them, for to You I have committed my cause.'),
  ('BSB', 'Jeremiah', 24, 20, 13, 'Sing to the LORD! Praise the LORD! For He rescues the life of the needy from the hands of evildoers.'),
  ('BSB', 'Jeremiah', 24, 20, 14, 'Cursed be the day I was born! May the day my mother bore me never be blessed.'),
  ('BSB', 'Jeremiah', 24, 20, 15, 'Cursed be the man who brought my father the news, saying, “A son is born to you,” bringing him great joy.'),
  ('BSB', 'Jeremiah', 24, 20, 16, 'May that man be like the cities that the LORD overthrew without compassion. May he hear an outcry in the morning and a battle cry at noon,'),
  ('BSB', 'Jeremiah', 24, 20, 17, 'because he did not kill me in the womb so that my mother might have been my grave, and her womb forever enlarged.'),
  ('BSB', 'Jeremiah', 24, 20, 18, 'Why did I come out of the womb to see only trouble and sorrow, and to end my days in shame?'),
  ('BSB', 'Jeremiah', 24, 21, 1, 'This is the word that came to Jeremiah from the LORD when King Zedekiah sent to him Pashhur son of Malchijah and the priest Zephaniah son of Maaseiah. They said,'),
  ('BSB', 'Jeremiah', 24, 21, 2, '“Please inquire of the LORD on our behalf, since Nebuchadnezzar king of Babylon is waging war against us. Perhaps the LORD will perform for us something like all His past wonders, so that Nebuchadnezzar will withdraw from us.”'),
  ('BSB', 'Jeremiah', 24, 21, 3, 'But Jeremiah answered, “You are to tell Zedekiah that'),
  ('BSB', 'Jeremiah', 24, 21, 4, 'this is what the LORD, the God of Israel, says: ‘I will turn against you the weapons of war in your hands, with which you are fighting the king of Babylon and the Chaldeans who besiege you outside the wall, and I will assemble their forces in the center of this city.'),
  ('BSB', 'Jeremiah', 24, 21, 5, 'And I Myself will fight against you with an outstretched hand and a mighty arm, with anger, fury, and great wrath.'),
  ('BSB', 'Jeremiah', 24, 21, 6, 'I will strike down the residents of this city, both man and beast. They will die in a terrible plague.’'),
  ('BSB', 'Jeremiah', 24, 21, 7, '‘After that,’ declares the LORD, ‘I will hand over Zedekiah king of Judah, his officers, and the people in this city who survive the plague and sword and famine, to Nebuchadnezzar king of Babylon and to their enemies who seek their lives. He will put them to the sword; he will not spare them or show pity or compassion.’'),
  ('BSB', 'Jeremiah', 24, 21, 8, 'Furthermore, you are to tell this people that this is what the LORD says: ‘Behold, I set before you the way of life and the way of death.'),
  ('BSB', 'Jeremiah', 24, 21, 9, 'Whoever stays in this city will die by sword and famine and plague, but whoever goes out and surrenders to the Chaldeans who besiege you will live; he will retain his life like a spoil of war.'),
  ('BSB', 'Jeremiah', 24, 21, 10, 'For I have set My face against this city to bring disaster and not good, declares the LORD. It will be delivered into the hand of the king of Babylon, who will destroy it with fire.’'),
  ('BSB', 'Jeremiah', 24, 21, 11, 'Moreover, tell the house of the king of Judah to hear the word of the LORD.'),
  ('BSB', 'Jeremiah', 24, 21, 12, 'O house of David, this is what the LORD says: ‘Administer justice every morning, and rescue the victim of robbery from the hand of his oppressor, or My wrath will go forth like fire and burn with no one to extinguish it because of their evil deeds.'),
  ('BSB', 'Jeremiah', 24, 21, 13, 'Behold, I am against you who dwell above the valley, atop the rocky plateau— declares the LORD— you who say, “Who can come against us? Who can enter our dwellings?”'),
  ('BSB', 'Jeremiah', 24, 21, 14, 'I will punish you as your deeds deserve, declares the LORD. I will kindle a fire in your forest that will consume everything around you.’”'),
  ('BSB', 'Jeremiah', 24, 22, 1, 'This is what the LORD says: “Go down to the palace of the king of Judah and proclaim this message there,'),
  ('BSB', 'Jeremiah', 24, 22, 2, 'saying, ‘Hear the word of the LORD, O king of Judah, who sits on the throne of David—you and your officials and your people who enter these gates.'),
  ('BSB', 'Jeremiah', 24, 22, 3, 'This is what the LORD says: Administer justice and righteousness. Rescue the victim of robbery from the hand of his oppressor. Do no wrong or violence to the foreigner, the fatherless, or the widow. Do not shed innocent blood in this place.'),
  ('BSB', 'Jeremiah', 24, 22, 4, 'For if you will indeed carry out these commands, then kings who sit on David’s throne will enter through the gates of this palace riding on chariots and horses—they and their officials and their people.'),
  ('BSB', 'Jeremiah', 24, 22, 5, 'But if you do not obey these words, then I swear by Myself, declares the LORD, that this house will become a pile of rubble.’”'),
  ('BSB', 'Jeremiah', 24, 22, 6, 'For this is what the LORD says concerning the house of the king of Judah: “You are like Gilead to Me, like the summit of Lebanon; but I will surely turn you into a desert, like cities that are uninhabited.'),
  ('BSB', 'Jeremiah', 24, 22, 7, 'I will appoint destroyers against you, each man with his weapons, and they will cut down the choicest of your cedars and throw them into the fire.'),
  ('BSB', 'Jeremiah', 24, 22, 8, 'And many nations will pass by this city and ask one another, ‘Why has the LORD done such a thing to this great city?’'),
  ('BSB', 'Jeremiah', 24, 22, 9, 'Then people will reply, ‘Because they have forsaken the covenant of the LORD their God and have worshiped and served other gods.’”'),
  ('BSB', 'Jeremiah', 24, 22, 10, 'Do not weep for the dead king; do not mourn his loss. Weep bitterly for the one who is exiled, for he will never return to see his native land.'),
  ('BSB', 'Jeremiah', 24, 22, 11, 'For this is what the LORD says concerning Shallum son of Josiah, king of Judah, who succeeded his father Josiah but has gone forth from this place: “He will never return,'),
  ('BSB', 'Jeremiah', 24, 22, 12, 'but he will die in the place to which he was exiled; he will never see this land again.”'),
  ('BSB', 'Jeremiah', 24, 22, 13, '“Woe to him who builds his palace by unrighteousness, and his upper rooms without justice, who makes his countrymen serve without pay, and fails to pay their wages,'),
  ('BSB', 'Jeremiah', 24, 22, 14, 'who says, ‘I will build myself a great palace, with spacious upper rooms.’ So he cuts windows in it, panels it with cedar, and paints it with vermilion.'),
  ('BSB', 'Jeremiah', 24, 22, 15, 'Does it make you a king to excel in cedar? Did not your father have food and drink? He administered justice and righteousness, and so it went well with him.'),
  ('BSB', 'Jeremiah', 24, 22, 16, 'He took up the cause of the poor and needy, and so it went well with him. Is this not what it means to know Me?” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 22, 17, '“But your eyes and heart are set on nothing except your own dishonest gain, on shedding innocent blood, on practicing extortion and oppression.”'),
  ('BSB', 'Jeremiah', 24, 22, 18, 'Therefore this is what the LORD says concerning Jehoiakim son of Josiah king of Judah: “They will not mourn for him: ‘Alas, my brother! Alas, my sister!’ They will not mourn for him: ‘Alas, my master! Alas, his splendor!’'),
  ('BSB', 'Jeremiah', 24, 22, 19, 'He will be buried like a donkey, dragged away and thrown outside the gates of Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 22, 20, 'Go up to Lebanon and cry out; raise your voice in Bashan; cry out from Abarim, for all your lovers have been crushed.'),
  ('BSB', 'Jeremiah', 24, 22, 21, 'I warned you when you were secure. You said, ‘I will not listen.’ This has been your way from youth, that you have not obeyed My voice.'),
  ('BSB', 'Jeremiah', 24, 22, 22, 'The wind will drive away all your shepherds, and your lovers will go into captivity. Then you will be ashamed and humiliated because of all your wickedness.'),
  ('BSB', 'Jeremiah', 24, 22, 23, 'O inhabitant of Lebanon, nestled in the cedars, how you will groan when pangs of anguish come upon you, agony like a woman in labor.”'),
  ('BSB', 'Jeremiah', 24, 22, 24, '“As surely as I live,” declares the LORD, “even if you, Coniah son of Jehoiakim king of Judah, were a signet ring on My right hand, I would pull you off.'),
  ('BSB', 'Jeremiah', 24, 22, 25, 'In fact, I will hand you over to those you dread, who want to take your life—to Nebuchadnezzar king of Babylon and to the Chaldeans.'),
  ('BSB', 'Jeremiah', 24, 22, 26, 'I will hurl you and the mother who gave you birth into another land, where neither of you were born—and there you both will die.'),
  ('BSB', 'Jeremiah', 24, 22, 27, 'You will never return to the land for which you long.”'),
  ('BSB', 'Jeremiah', 24, 22, 28, 'Is this man Coniah a despised and shattered pot, a jar that no one wants? Why are he and his descendants hurled out and cast into a land they do not know?'),
  ('BSB', 'Jeremiah', 24, 22, 29, 'O land, land, land, hear the word of the LORD!'),
  ('BSB', 'Jeremiah', 24, 22, 30, 'This is what the LORD says: “Enroll this man as childless, a man who will not prosper in his lifetime. None of his descendants will prosper to sit on the throne of David or to rule again in Judah.”'),
  ('BSB', 'Jeremiah', 24, 23, 1, '“Woe to the shepherds who destroy and scatter the sheep of My pasture!” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 2, 'Therefore this is what the LORD, the God of Israel, says about the shepherds who tend My people: “You have scattered My flock and driven them away, and have not attended to them. Behold, I will attend to you for the evil of your deeds, declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 3, 'Then I Myself will gather the remnant of My flock from all the lands to which I have banished them, and I will return them to their pasture, where they will be fruitful and multiply.'),
  ('BSB', 'Jeremiah', 24, 23, 4, 'I will raise up shepherds over them who will tend them, and they will no longer be afraid or dismayed, nor will any go missing, declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 5, 'Behold, the days are coming, declares the LORD, when I will raise up for David a righteous Branch, and He will reign wisely as King and will administer justice and righteousness in the land.'),
  ('BSB', 'Jeremiah', 24, 23, 6, 'In His days Judah will be saved, and Israel will dwell securely. And this is His name by which He will be called: The LORD Our Righteousness.'),
  ('BSB', 'Jeremiah', 24, 23, 7, 'So behold, the days are coming, declares the LORD, when they will no longer say, ‘As surely as the LORD lives, who brought the Israelites up out of the land of Egypt.’'),
  ('BSB', 'Jeremiah', 24, 23, 8, 'Instead they will say, ‘As surely as the LORD lives, who brought and led the descendants of the house of Israel up out of the land of the north and all the other lands to which He had banished them.’ Then they will dwell once more in their own land.”'),
  ('BSB', 'Jeremiah', 24, 23, 9, 'As for the prophets: My heart is broken within me, and all my bones tremble. I have become like a drunkard, like a man overcome by wine, because of the LORD, because of His holy words.'),
  ('BSB', 'Jeremiah', 24, 23, 10, 'For the land is full of adulterers— because of the curse, the land mourns and the pastures of the wilderness have dried up— their course is evil and their power is misused.'),
  ('BSB', 'Jeremiah', 24, 23, 11, '“For both prophet and priest are ungodly; even in My house I have found their wickedness,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 12, '“Therefore their path will become slick; they will be driven away into the darkness and fall into it. For I will bring disaster upon them in the year of their punishment,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 13, '“Among the prophets of Samaria I saw an offensive thing: They prophesied by Baal and led My people Israel astray.'),
  ('BSB', 'Jeremiah', 24, 23, 14, 'And among the prophets of Jerusalem I have seen a horrible thing: They commit adultery and walk in lies. They strengthen the hands of evildoers, so that no one turns his back on wickedness. They are all like Sodom to Me; the people of Jerusalem are like Gomorrah.”'),
  ('BSB', 'Jeremiah', 24, 23, 15, 'Therefore this is what the LORD of Hosts says concerning the prophets: “I will feed them wormwood and give them poisoned water to drink, for from the prophets of Jerusalem ungodliness has spread throughout the land.”'),
  ('BSB', 'Jeremiah', 24, 23, 16, 'This is what the LORD of Hosts says: “Do not listen to the words of the prophets who prophesy to you. They are filling you with false hopes. They speak visions from their own minds, not from the mouth of the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 17, 'They keep saying to those who despise Me, ‘The LORD says that you will have peace,’ and to everyone who walks in the stubbornness of his own heart, ‘No harm will come to you.’'),
  ('BSB', 'Jeremiah', 24, 23, 18, 'But which of them has stood in the council of the LORD to see and hear His word? Who has given heed to His word and obeyed it?'),
  ('BSB', 'Jeremiah', 24, 23, 19, 'Behold, the storm of the LORD has gone out with fury, a whirlwind swirling down upon the heads of the wicked.'),
  ('BSB', 'Jeremiah', 24, 23, 20, 'The anger of the LORD will not turn back until He has fully accomplished the purposes of His heart. In the days to come you will understand this clearly.'),
  ('BSB', 'Jeremiah', 24, 23, 21, 'I did not send these prophets, yet they have run with their message; I did not speak to them, yet they have prophesied.'),
  ('BSB', 'Jeremiah', 24, 23, 22, 'But if they had stood in My council, they would have proclaimed My words to My people and turned them back from their evil ways and deeds.”'),
  ('BSB', 'Jeremiah', 24, 23, 23, '“Am I only a God nearby,” declares the LORD, “and not a God far away?”'),
  ('BSB', 'Jeremiah', 24, 23, 24, '“Can a man hide in secret places where I cannot see him?” declares the LORD. “Do I not fill the heavens and the earth?” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 25, '“I have heard the sayings of the prophets who prophesy lies in My name: ‘I had a dream! I had a dream!’'),
  ('BSB', 'Jeremiah', 24, 23, 26, 'How long will this continue in the hearts of these prophets who prophesy falsehood, these prophets of the delusion of their own minds?'),
  ('BSB', 'Jeremiah', 24, 23, 27, 'They suppose the dreams that they tell one another will make My people forget My name, just as their fathers forgot My name through the worship of Baal.'),
  ('BSB', 'Jeremiah', 24, 23, 28, 'Let the prophet who has a dream retell it, but let him who has My word speak it truthfully. For what is straw compared to grain?” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 29, '“Is not My word like fire,” declares the LORD, “and like a hammer that smashes a rock?”'),
  ('BSB', 'Jeremiah', 24, 23, 30, '“Therefore behold,” declares the LORD, “I am against the prophets who steal from one another words they attribute to Me.”'),
  ('BSB', 'Jeremiah', 24, 23, 31, '“Yes,” declares the LORD, “I am against the prophets who wag their own tongues and proclaim, ‘The LORD declares it.’”'),
  ('BSB', 'Jeremiah', 24, 23, 32, '“Indeed,” declares the LORD, “I am against those who prophesy false dreams and retell them to lead My people astray with their reckless lies. It was not I who sent them or commanded them, and they are of no benefit at all to these people,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 23, 33, '“Now when this people or a prophet or priest asks you, ‘What is the burden of the LORD?’ you are to say to them, ‘What burden? I will forsake you, declares the LORD.’'),
  ('BSB', 'Jeremiah', 24, 23, 34, 'As for the prophet or priest or anyone who claims, ‘This is the burden of the LORD,’ I will punish that man and his household.'),
  ('BSB', 'Jeremiah', 24, 23, 35, 'This is what each man is to say to his friend and to his brother: ‘What has the LORD answered?’ or ‘What has the LORD spoken?’'),
  ('BSB', 'Jeremiah', 24, 23, 36, 'But refer no more to the burden of the LORD, for each man’s word becomes the burden, so that you pervert the words of the living God, the LORD of Hosts, our God.'),
  ('BSB', 'Jeremiah', 24, 23, 37, 'Thus you are to say to the prophet: ‘What has the LORD answered you?’ and ‘What has the LORD spoken?’'),
  ('BSB', 'Jeremiah', 24, 23, 38, 'But if you claim, ‘This is the burden of the LORD,’ then this is what the LORD says: Because you have said, ‘This is the burden of the LORD,’ and I specifically told you not to make this claim,'),
  ('BSB', 'Jeremiah', 24, 23, 39, 'therefore I will surely forget you and will cast you out of My presence, both you and the city that I gave to you and your fathers.'),
  ('BSB', 'Jeremiah', 24, 23, 40, 'And I will bring upon you everlasting shame and perpetual humiliation that will never be forgotten.”'),
  ('BSB', 'Jeremiah', 24, 24, 1, 'After Nebuchadnezzar king of Babylon had carried away Jeconiah son of Jehoiakim king of Judah, as well as the officials of Judah and the craftsmen and metalsmiths from Jerusalem, and had brought them to Babylon, the LORD showed me two baskets of figs placed in front of the temple of the LORD.'),
  ('BSB', 'Jeremiah', 24, 24, 2, 'One basket had very good figs, like those that ripen early, but the other basket contained very poor figs, so bad they could not be eaten.'),
  ('BSB', 'Jeremiah', 24, 24, 3, '“Jeremiah,” the LORD asked, “what do you see?” “Figs!” I replied. “The good figs are very good, but the bad figs are very bad, so bad they cannot be eaten.”'),
  ('BSB', 'Jeremiah', 24, 24, 4, 'Then the word of the LORD came to me, saying,'),
  ('BSB', 'Jeremiah', 24, 24, 5, '“This is what the LORD, the God of Israel, says: ‘Like these good figs, so I regard as good the exiles from Judah, whom I have sent away from this place to the land of the Chaldeans.'),
  ('BSB', 'Jeremiah', 24, 24, 6, 'I will keep My eyes on them for good and will return them to this land. I will build them up and not tear them down; I will plant them and not uproot them.'),
  ('BSB', 'Jeremiah', 24, 24, 7, 'I will give them a heart to know Me, that I am the LORD. They will be My people, and I will be their God, for they will return to Me with all their heart.'),
  ('BSB', 'Jeremiah', 24, 24, 8, 'But like the bad figs, so bad they cannot be eaten,’ says the LORD, ‘so will I deal with Zedekiah king of Judah, his officials, and the remnant of Jerusalem—those remaining in this land and those living in the land of Egypt.'),
  ('BSB', 'Jeremiah', 24, 24, 9, 'I will make them a horror and an offense to all the kingdoms of the earth, a disgrace and an object of scorn, ridicule, and cursing wherever I have banished them.'),
  ('BSB', 'Jeremiah', 24, 24, 10, 'And I will send against them sword and famine and plague, until they have perished from the land that I gave to them and their fathers.’”'),
  ('BSB', 'Jeremiah', 24, 25, 1, 'This is the word that came to Jeremiah concerning all the people of Judah in the fourth year of Jehoiakim son of Josiah king of Judah, which was the first year of Nebuchadnezzar king of Babylon.'),
  ('BSB', 'Jeremiah', 24, 25, 2, 'So the prophet Jeremiah spoke to all the people of Judah and all the residents of Jerusalem as follows:'),
  ('BSB', 'Jeremiah', 24, 25, 3, '“From the thirteenth year of Josiah son of Amon king of Judah until this very day—twenty-three years—the word of the LORD has come to me, and I have spoken to you again and again, but you have not listened.'),
  ('BSB', 'Jeremiah', 24, 25, 4, 'And the LORD has sent all His servants the prophets to you again and again, but you have not listened or inclined your ear to hear.'),
  ('BSB', 'Jeremiah', 24, 25, 5, 'The prophets told you, ‘Turn now, each of you, from your evil ways and deeds, and you can dwell in the land that the LORD has given to you and your fathers forever and ever.'),
  ('BSB', 'Jeremiah', 24, 25, 6, 'Do not follow other gods to serve and worship them, and do not provoke Me to anger with the works of your hands. Then I will do you no harm.’'),
  ('BSB', 'Jeremiah', 24, 25, 7, '‘But to your own harm, you have not listened to Me,’ declares the LORD, ‘so you have provoked Me to anger with the works of your hands.’'),
  ('BSB', 'Jeremiah', 24, 25, 8, 'Therefore this is what the LORD of Hosts says: ‘Because you have not obeyed My words,'),
  ('BSB', 'Jeremiah', 24, 25, 9, 'behold, I will summon all the families of the north, declares the LORD, and I will send for My servant Nebuchadnezzar king of Babylon, whom I will bring against this land, against its residents, and against all the surrounding nations. So I will devote them to destruction and make them an object of horror and contempt, an everlasting desolation.'),
  ('BSB', 'Jeremiah', 24, 25, 10, 'Moreover, I will banish from them the sounds of joy and gladness, the voices of the bride and bridegroom, the sound of the millstones, and the light of the lamp.'),
  ('BSB', 'Jeremiah', 24, 25, 11, 'And this whole land will become a desolate wasteland, and these nations will serve the king of Babylon for seventy years.'),
  ('BSB', 'Jeremiah', 24, 25, 12, 'But when seventy years are complete, I will punish the king of Babylon and that nation, the land of the Chaldeans, for their guilt, declares the LORD, and I will make it an everlasting desolation.'),
  ('BSB', 'Jeremiah', 24, 25, 13, 'I will bring upon that land all the words I have pronounced against it, all that is written in this book, which Jeremiah has prophesied against all the nations.'),
  ('BSB', 'Jeremiah', 24, 25, 14, 'For many nations and great kings will enslave them, and I will repay them according to their deeds and according to the work of their hands.’”'),
  ('BSB', 'Jeremiah', 24, 25, 15, 'This is what the LORD, the God of Israel, said to me: “Take from My hand this cup of the wine of wrath, and make all the nations to whom I send you drink from it.'),
  ('BSB', 'Jeremiah', 24, 25, 16, 'And they will drink and stagger and go out of their minds, because of the sword that I will send among them.”'),
  ('BSB', 'Jeremiah', 24, 25, 17, 'So I took the cup from the LORD’s hand and made all the nations drink from it, each one to whom the LORD had sent me,'),
  ('BSB', 'Jeremiah', 24, 25, 18, 'to make them a ruin, an object of horror and contempt and cursing, as they are to this day—Jerusalem and the cities of Judah, its kings and officials;'),
  ('BSB', 'Jeremiah', 24, 25, 19, 'Pharaoh king of Egypt, his officials, his leaders, and all his people;'),
  ('BSB', 'Jeremiah', 24, 25, 20, 'all the mixed tribes; all the kings of Uz; all the kings of the Philistines: Ashkelon, Gaza, Ekron, and the remnant of Ashdod;'),
  ('BSB', 'Jeremiah', 24, 25, 21, 'Edom, Moab, and the Ammonites;'),
  ('BSB', 'Jeremiah', 24, 25, 22, 'all the kings of Tyre and Sidon; the kings of the coastlands across the sea;'),
  ('BSB', 'Jeremiah', 24, 25, 23, 'Dedan, Tema, Buz, and all who cut the corners of their hair;'),
  ('BSB', 'Jeremiah', 24, 25, 24, 'all the kings of Arabia, and all the kings of the mixed tribes who dwell in the desert;'),
  ('BSB', 'Jeremiah', 24, 25, 25, 'all the kings of Zimri, Elam, and Media;'),
  ('BSB', 'Jeremiah', 24, 25, 26, 'all the kings of the north, both near and far, one after another—all the kingdoms on the face of the earth. And after all of them, the king of Sheshach will drink it too.'),
  ('BSB', 'Jeremiah', 24, 25, 27, '“Then you are to tell them that this is what the LORD of Hosts, the God of Israel, says: ‘Drink, get drunk, and vomit. Fall down and never get up again, because of the sword I will send among you.’'),
  ('BSB', 'Jeremiah', 24, 25, 28, 'If they refuse to take the cup from your hand and drink it, you are to tell them that this is what the LORD of Hosts says: ‘You most certainly must drink it!'),
  ('BSB', 'Jeremiah', 24, 25, 29, 'For behold, I am beginning to bring disaster on the city that bears My Name, so how could you possibly go unpunished? You will not go unpunished, for I am calling down a sword upon all the inhabitants of the earth, declares the LORD of Hosts.’'),
  ('BSB', 'Jeremiah', 24, 25, 30, 'So you are to prophesy all these words against them and say to them: ‘The LORD will roar from on high; He will raise His voice from His holy habitation. He will roar loudly over His pasture; like those who tread the grapes, He will call out with a shout against all the inhabitants of the earth.'),
  ('BSB', 'Jeremiah', 24, 25, 31, 'The tumult will resound to the ends of the earth because the LORD brings a charge against the nations. He brings judgment on all mankind and puts the wicked to the sword,’” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 25, 32, 'This is what the LORD of Hosts says: “Behold! Disaster is spreading from nation to nation; a mighty storm is rising from the ends of the earth.”'),
  ('BSB', 'Jeremiah', 24, 25, 33, 'Those slain by the LORD on that day will be spread from one end of the earth to the other. They will not be mourned, gathered, or buried. They will be like dung lying on the ground.'),
  ('BSB', 'Jeremiah', 24, 25, 34, 'Wail, you shepherds, and cry out; roll in the dust, you leaders of the flock. For the days of your slaughter have come; you will fall and be shattered like fine pottery.'),
  ('BSB', 'Jeremiah', 24, 25, 35, 'Flight will evade the shepherds, and escape will elude the leaders of the flock.'),
  ('BSB', 'Jeremiah', 24, 25, 36, 'Hear the cry of the shepherds, the wailing of the leaders of the flock, for the LORD is destroying their pasture.'),
  ('BSB', 'Jeremiah', 24, 25, 37, 'The peaceful meadows have been silenced because of the LORD’s burning anger.'),
  ('BSB', 'Jeremiah', 24, 25, 38, 'He has left His den like a lion, for their land has been made a desolation by the sword of the oppressor, and because of the fierce anger of the LORD.'),
  ('BSB', 'Jeremiah', 24, 26, 1, 'At the beginning of the reign of Jehoiakim son of Josiah king of Judah, this word came from the LORD:'),
  ('BSB', 'Jeremiah', 24, 26, 2, '“This is what the LORD says: Stand in the courtyard of the house of the LORD and speak all the words I have commanded you to speak to all the cities of Judah who come to worship there. Do not omit a word.'),
  ('BSB', 'Jeremiah', 24, 26, 3, 'Perhaps they will listen and turn—each from his evil way of life—so that I may relent of the disaster I am planning to bring upon them because of the evil of their deeds.'),
  ('BSB', 'Jeremiah', 24, 26, 4, 'And you are to tell them that this is what the LORD says: ‘If you do not listen to Me and walk in My law, which I have set before you,'),
  ('BSB', 'Jeremiah', 24, 26, 5, 'and if you do not listen to the words of My servants the prophets, whom I have sent you again and again even though you did not listen,'),
  ('BSB', 'Jeremiah', 24, 26, 6, 'then I will make this house like Shiloh, and I will make this city an object of cursing among all the nations of the earth.’”'),
  ('BSB', 'Jeremiah', 24, 26, 7, 'Now the priests and prophets and all the people heard Jeremiah speaking these words in the house of the LORD,'),
  ('BSB', 'Jeremiah', 24, 26, 8, 'and as soon as he had finished telling all the people everything the LORD had commanded him to say, the priests and prophets and all the people seized him, shouting, “You must surely die!'),
  ('BSB', 'Jeremiah', 24, 26, 9, 'How dare you prophesy in the name of the LORD that this house will become like Shiloh and this city will be desolate and deserted!” And all the people assembled against Jeremiah in the house of the LORD.'),
  ('BSB', 'Jeremiah', 24, 26, 10, 'When the officials of Judah heard these things, they went up from the king’s palace to the house of the LORD and sat there at the entrance of the New Gate.'),
  ('BSB', 'Jeremiah', 24, 26, 11, 'Then the priests and prophets said to the officials and all the people, “This man is worthy of death, for he has prophesied against this city, as you have heard with your own ears!”'),
  ('BSB', 'Jeremiah', 24, 26, 12, 'But Jeremiah said to all the officials and all the people, “The LORD sent me to prophesy against this house and against this city all the words that you have heard.'),
  ('BSB', 'Jeremiah', 24, 26, 13, 'So now, correct your ways and deeds, and obey the voice of the LORD your God, so that He might relent of the disaster He has pronounced against you.'),
  ('BSB', 'Jeremiah', 24, 26, 14, 'As for me, here I am in your hands; do to me what you think is good and right.'),
  ('BSB', 'Jeremiah', 24, 26, 15, 'But know for certain that if you put me to death, you will bring innocent blood upon yourselves, upon this city, and upon its residents; for truly the LORD has sent me to speak all these words in your hearing.”'),
  ('BSB', 'Jeremiah', 24, 26, 16, 'Then the officials and all the people told the priests and prophets, “This man is not worthy of death, for he has spoken to us in the name of the LORD our God!”'),
  ('BSB', 'Jeremiah', 24, 26, 17, 'Some of the elders of the land stood up and said to the whole assembly of the people,'),
  ('BSB', 'Jeremiah', 24, 26, 18, '“Micah the Moreshite prophesied in the days of Hezekiah king of Judah and told all the people of Judah that this is what the LORD of Hosts says: ‘Zion will be plowed like a field, Jerusalem will become a heap of rubble, and the temple mount a wooded ridge.’'),
  ('BSB', 'Jeremiah', 24, 26, 19, 'Did Hezekiah king of Judah or anyone else in Judah put him to death? Did Hezekiah not fear the LORD and seek His favor, and did not the LORD relent of the disaster He had pronounced against them? But we are about to bring great harm on ourselves!”'),
  ('BSB', 'Jeremiah', 24, 26, 20, 'Now there was another man prophesying in the name of the LORD, Uriah son of Shemaiah from Kiriath-jearim. He prophesied against this city and against this land the same things that Jeremiah did.'),
  ('BSB', 'Jeremiah', 24, 26, 21, 'King Jehoiakim and all his mighty men and officials heard his words, and the king sought to put him to death. But when Uriah found out about it, he fled in fear and went to Egypt.'),
  ('BSB', 'Jeremiah', 24, 26, 22, 'Then King Jehoiakim sent men to Egypt: Elnathan son of Achbor along with some other men.'),
  ('BSB', 'Jeremiah', 24, 26, 23, 'They brought Uriah out of Egypt and took him to King Jehoiakim, who had him put to the sword and his body thrown into the burial place of the common people.'),
  ('BSB', 'Jeremiah', 24, 26, 24, 'Nevertheless, Ahikam son of Shaphan supported Jeremiah, so he was not handed over to the people to be put to death.'),
  ('BSB', 'Jeremiah', 24, 27, 1, 'At the beginning of the reign of Zedekiah son of Josiah king of Judah, this word came to Jeremiah from the LORD.'),
  ('BSB', 'Jeremiah', 24, 27, 2, 'This is what the LORD said to me: “Make for yourself a yoke out of leather straps and put it on your neck.'),
  ('BSB', 'Jeremiah', 24, 27, 3, 'Send word to the kings of Edom, Moab, Ammon, Tyre, and Sidon through the envoys who have come to Jerusalem to Zedekiah king of Judah.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Jeremiah', 24, 27, 4, 'Give them a message from the LORD of Hosts, the God of Israel, to relay to their masters:'),
  ('BSB', 'Jeremiah', 24, 27, 5, 'By My great power and outstretched arm, I made the earth and the men and beasts on the face of it, and I give it to whom I please.'),
  ('BSB', 'Jeremiah', 24, 27, 6, 'So now I have placed all these lands under the authority of My servant Nebuchadnezzar king of Babylon. I have even made the beasts of the field subject to him.'),
  ('BSB', 'Jeremiah', 24, 27, 7, 'All nations will serve him and his son and grandson, until the time of his own land comes; then many nations and great kings will enslave him.'),
  ('BSB', 'Jeremiah', 24, 27, 8, 'As for the nation or kingdom that does not serve Nebuchadnezzar king of Babylon and does not place its neck under his yoke, I will punish that nation by sword and famine and plague, declares the LORD, until I have destroyed it by his hand.'),
  ('BSB', 'Jeremiah', 24, 27, 9, 'But as for you, do not listen to your prophets, your diviners, your interpreters of dreams, your mediums, or your sorcerers who declare, ‘You will not serve the king of Babylon.’'),
  ('BSB', 'Jeremiah', 24, 27, 10, 'For they prophesy to you a lie that will serve to remove you from your land; I will banish you and you will perish.'),
  ('BSB', 'Jeremiah', 24, 27, 11, 'But the nation that will put its neck under the yoke of the king of Babylon and serve him, I will leave in its own land, to cultivate it and reside in it, declares the LORD.”'),
  ('BSB', 'Jeremiah', 24, 27, 12, 'And to Zedekiah king of Judah I spoke the same message: “Put your necks under the yoke of the king of Babylon; serve him and his people, and live!'),
  ('BSB', 'Jeremiah', 24, 27, 13, 'Why should you and your people die by sword and famine and plague, as the LORD has decreed against any nation that does not serve the king of Babylon?'),
  ('BSB', 'Jeremiah', 24, 27, 14, 'Do not listen to the words of the prophets who say, ‘You must not serve the king of Babylon,’ for they are prophesying to you a lie.'),
  ('BSB', 'Jeremiah', 24, 27, 15, 'For I have not sent them, declares the LORD, and yet they are prophesying falsely in My name; therefore I will banish you, and you will perish—you and the prophets who prophesy to you.”'),
  ('BSB', 'Jeremiah', 24, 27, 16, 'Then I said to the priests and to all this people, “This is what the LORD says: Do not listen to the words of your prophets who prophesy to you, saying, ‘Look, very soon now the articles from the house of the LORD will be brought back from Babylon.’ They are prophesying to you a lie.'),
  ('BSB', 'Jeremiah', 24, 27, 17, 'Do not listen to them. Serve the king of Babylon and live! Why should this city become a ruin?'),
  ('BSB', 'Jeremiah', 24, 27, 18, 'If they are indeed prophets and the word of the LORD is with them, let them now plead with the LORD of Hosts that the articles remaining in the house of the LORD, in the palace of the king of Judah, and in Jerusalem, not be taken to Babylon.'),
  ('BSB', 'Jeremiah', 24, 27, 19, 'For this is what the LORD of Hosts says about the pillars, the sea, the bases, and the rest of the articles that remain in this city,'),
  ('BSB', 'Jeremiah', 24, 27, 20, 'which Nebuchadnezzar king of Babylon did not take when he carried Jeconiah son of Jehoiakim king of Judah into exile from Jerusalem to Babylon, along with all the nobles of Judah and Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 27, 21, 'Yes, this is what the LORD of Hosts, the God of Israel, says about the articles that remain in the house of the LORD, in the palace of the king of Judah, and in Jerusalem:'),
  ('BSB', 'Jeremiah', 24, 27, 22, '‘They will be carried to Babylon and will remain there until the day I attend to them again,’ declares the LORD. ‘Then I will bring them back and restore them to this place.’”'),
  ('BSB', 'Jeremiah', 24, 28, 1, 'In the fifth month of that same year, the fourth year, near the beginning of the reign of King Zedekiah of Judah, the prophet Hananiah son of Azzur, who was from Gibeon, said to me in the house of the LORD in the presence of the priests and all the people:'),
  ('BSB', 'Jeremiah', 24, 28, 2, '“This is what the LORD of Hosts, the God of Israel, says: ‘I have broken the yoke of the king of Babylon.'),
  ('BSB', 'Jeremiah', 24, 28, 3, 'Within two years I will restore to this place all the articles of the house of the LORD that Nebuchadnezzar king of Babylon removed from here and carried to Babylon.'),
  ('BSB', 'Jeremiah', 24, 28, 4, 'And I will restore to this place Jeconiah son of Jehoiakim king of Judah, along with all the exiles from Judah who went to Babylon,’ declares the LORD, ‘for I will break the yoke of the king of Babylon.’”'),
  ('BSB', 'Jeremiah', 24, 28, 5, 'Then the prophet Jeremiah replied to the prophet Hananiah in the presence of the priests and all the people who were standing in the house of the LORD.'),
  ('BSB', 'Jeremiah', 24, 28, 6, '“Amen!” Jeremiah said. “May the LORD do so! May the LORD fulfill the words you have prophesied, and may He restore the articles of His house and all the exiles back to this place from Babylon.'),
  ('BSB', 'Jeremiah', 24, 28, 7, 'Nevertheless, listen now to this message I am speaking in your hearing and in the hearing of all the people.'),
  ('BSB', 'Jeremiah', 24, 28, 8, 'The prophets of old who preceded you and me prophesied war, disaster, and plague against many lands and great kingdoms.'),
  ('BSB', 'Jeremiah', 24, 28, 9, 'As for the prophet who prophesies peace, only if the word of the prophet comes true will the prophet be recognized as one the LORD has truly sent.”'),
  ('BSB', 'Jeremiah', 24, 28, 10, 'Then the prophet Hananiah took the yoke off the neck of Jeremiah the prophet and broke it.'),
  ('BSB', 'Jeremiah', 24, 28, 11, 'And in the presence of all the people Hananiah proclaimed, “This is what the LORD says: ‘In this way, within two years I will break the yoke of Nebuchadnezzar king of Babylon off the neck of all the nations.’” At this, Jeremiah the prophet went on his way.'),
  ('BSB', 'Jeremiah', 24, 28, 12, 'But shortly after Hananiah the prophet had broken the yoke off his neck, the word of the LORD came to Jeremiah:'),
  ('BSB', 'Jeremiah', 24, 28, 13, '“Go and tell Hananiah that this is what the LORD says: ‘You have broken a yoke of wood, but in its place you have fashioned a yoke of iron.’'),
  ('BSB', 'Jeremiah', 24, 28, 14, 'For this is what the LORD of Hosts, the God of Israel, says: ‘I have put a yoke of iron on the neck of all these nations to make them serve Nebuchadnezzar king of Babylon, and they will serve him. I have even given him control of the beasts of the field.’”'),
  ('BSB', 'Jeremiah', 24, 28, 15, 'Then the prophet Jeremiah said to the prophet Hananiah, “Listen, Hananiah! The LORD did not send you, but you have persuaded this people to trust in a lie.'),
  ('BSB', 'Jeremiah', 24, 28, 16, 'Therefore this is what the LORD says: ‘I am about to remove you from the face of the earth. You will die this year because you have preached rebellion against the LORD.’”'),
  ('BSB', 'Jeremiah', 24, 28, 17, 'And in the seventh month of that very year, the prophet Hananiah died.'),
  ('BSB', 'Jeremiah', 24, 29, 1, 'This is the text of the letter that Jeremiah the prophet sent from Jerusalem to the surviving elders among the exiles and to the priests, the prophets, and all the others Nebuchadnezzar had carried into exile from Jerusalem to Babylon.'),
  ('BSB', 'Jeremiah', 24, 29, 2, '(This was after King Jeconiah, the queen mother, the court officials, the officials of Judah and Jerusalem, the craftsmen, and the metalsmiths had been exiled from Jerusalem.)'),
  ('BSB', 'Jeremiah', 24, 29, 3, 'The letter was entrusted to Elasah son of Shaphan and Gemariah son of Hilkiah, whom Zedekiah king of Judah sent to King Nebuchadnezzar in Babylon. It stated:'),
  ('BSB', 'Jeremiah', 24, 29, 4, 'This is what the LORD of Hosts, the God of Israel, says to all the exiles who were carried away from Jerusalem to Babylon:'),
  ('BSB', 'Jeremiah', 24, 29, 5, '“Build houses and settle down. Plant gardens and eat their produce.'),
  ('BSB', 'Jeremiah', 24, 29, 6, 'Take wives and have sons and daughters. Take wives for your sons and give your daughters in marriage, so that they too may have sons and daughters. Multiply there; do not decrease.'),
  ('BSB', 'Jeremiah', 24, 29, 7, 'Seek the prosperity of the city to which I have sent you as exiles. Pray to the LORD on its behalf, for if it prospers, you too will prosper.”'),
  ('BSB', 'Jeremiah', 24, 29, 8, 'For this is what the LORD of Hosts, the God of Israel, says: “Do not be deceived by the prophets and diviners among you, and do not listen to the dreams you elicit from them.'),
  ('BSB', 'Jeremiah', 24, 29, 9, 'For they are falsely prophesying to you in My name; I have not sent them, declares the LORD.”'),
  ('BSB', 'Jeremiah', 24, 29, 10, 'For this is what the LORD says: “When Babylon’s seventy years are complete, I will attend to you and confirm My promise to restore you to this place.'),
  ('BSB', 'Jeremiah', 24, 29, 11, 'For I know the plans I have for you, declares the LORD, plans to prosper you and not to harm you, to give you a future and a hope.'),
  ('BSB', 'Jeremiah', 24, 29, 12, 'Then you will call upon Me and come and pray to Me, and I will listen to you.'),
  ('BSB', 'Jeremiah', 24, 29, 13, 'You will seek Me and find Me when you search for Me with all your heart.'),
  ('BSB', 'Jeremiah', 24, 29, 14, 'I will be found by you, declares the LORD, and I will restore you from captivity and gather you from all the nations and places to which I have banished you, declares the LORD. I will restore you to the place from which I sent you into exile.”'),
  ('BSB', 'Jeremiah', 24, 29, 15, 'Because you may say, “The LORD has raised up for us prophets in Babylon,”'),
  ('BSB', 'Jeremiah', 24, 29, 16, 'this is what the LORD says about the king who sits on David’s throne and all the people who remain in this city, your brothers who did not go with you into exile—'),
  ('BSB', 'Jeremiah', 24, 29, 17, 'this is what the LORD of Hosts says: “I will send against them sword and famine and plague, and I will make them like rotten figs, so bad they cannot be eaten.'),
  ('BSB', 'Jeremiah', 24, 29, 18, 'I will pursue them with sword and famine and plague. I will make them a horror to all the kingdoms of the earth—a curse, a desolation, and an object of scorn and reproach among all the nations to which I banish them.'),
  ('BSB', 'Jeremiah', 24, 29, 19, 'I will do this because they have not listened to My words, declares the LORD, which I sent to them again and again through My servants the prophets. And neither have you exiles listened, declares the LORD.”'),
  ('BSB', 'Jeremiah', 24, 29, 20, 'So hear the word of the LORD, all you exiles I have sent away from Jerusalem to Babylon.'),
  ('BSB', 'Jeremiah', 24, 29, 21, 'This is what the LORD of Hosts, the God of Israel, says about Ahab son of Kolaiah and Zedekiah son of Maaseiah, who are prophesying to you lies in My name: “I will deliver them to Nebuchadnezzar king of Babylon, and he will kill them before your very eyes.'),
  ('BSB', 'Jeremiah', 24, 29, 22, 'Because of them, all the exiles of Judah who are in Babylon will use this curse: ‘May the LORD make you like Zedekiah and Ahab, whom the king of Babylon roasted in the fire!’'),
  ('BSB', 'Jeremiah', 24, 29, 23, 'For they have committed an outrage in Israel by committing adultery with the wives of their neighbors and speaking lies in My name, which I did not command them to do. I am He who knows, and I am a witness, declares the LORD.”'),
  ('BSB', 'Jeremiah', 24, 29, 24, 'You are to tell Shemaiah the Nehelamite that'),
  ('BSB', 'Jeremiah', 24, 29, 25, 'this is what the LORD of Hosts, the God of Israel, says: “In your own name you have sent out letters to all the people of Jerusalem, to the priest Zephaniah son of Maaseiah, and to all the priests. You said to Zephaniah:'),
  ('BSB', 'Jeremiah', 24, 29, 26, '‘The LORD has appointed you priest in place of Jehoiada, to be the chief officer in the house of the LORD, responsible for any madman who acts like a prophet—you must put him in stocks and neck irons.'),
  ('BSB', 'Jeremiah', 24, 29, 27, 'So now, why have you not rebuked Jeremiah of Anathoth, who poses as a prophet among you?'),
  ('BSB', 'Jeremiah', 24, 29, 28, 'For he has sent to us in Babylon, claiming: Since the exile will be lengthy, build houses and settle down; plant gardens and eat their produce.’”'),
  ('BSB', 'Jeremiah', 24, 29, 29, '(Zephaniah the priest, however, had read this letter to Jeremiah the prophet.)'),
  ('BSB', 'Jeremiah', 24, 29, 30, 'Then the word of the LORD came to Jeremiah:'),
  ('BSB', 'Jeremiah', 24, 29, 31, '“Send a message telling all the exiles what the LORD says concerning Shemaiah the Nehelamite. Because Shemaiah has prophesied to you—though I did not send him—and has made you trust in a lie,'),
  ('BSB', 'Jeremiah', 24, 29, 32, 'this is what the LORD says: ‘I will surely punish Shemaiah the Nehelamite and his descendants. He will have no one left among this people, nor will he see the good that I will bring to My people, declares the LORD, for he has preached rebellion against the LORD.’”'),
  ('BSB', 'Jeremiah', 24, 30, 1, 'This is the word that came to Jeremiah from the LORD:'),
  ('BSB', 'Jeremiah', 24, 30, 2, '“This is what the LORD, the God of Israel, says: ‘Write in a book all the words that I have spoken to you.'),
  ('BSB', 'Jeremiah', 24, 30, 3, 'For behold, the days are coming, declares the LORD, when I will restore from captivity My people Israel and Judah, declares the LORD. I will restore them to the land that I gave to their fathers, and they will possess it.’”'),
  ('BSB', 'Jeremiah', 24, 30, 4, 'These are the words that the LORD spoke concerning Israel and Judah.'),
  ('BSB', 'Jeremiah', 24, 30, 5, 'Yes, this is what the LORD says: “A cry of panic is heard— a cry of terror, not of peace.'),
  ('BSB', 'Jeremiah', 24, 30, 6, 'Ask now, and see: Can a male give birth? Why then do I see every man with his hands on his stomach like a woman in labor and every face turned pale?'),
  ('BSB', 'Jeremiah', 24, 30, 7, 'How awful that day will be! None will be like it! It is the time of Jacob’s distress, but he will be saved out of it.'),
  ('BSB', 'Jeremiah', 24, 30, 8, 'On that day, declares the LORD of Hosts, I will break the yoke off their necks and tear off their bonds, and no longer will strangers enslave them.'),
  ('BSB', 'Jeremiah', 24, 30, 9, 'Instead, they will serve the LORD their God and David their king, whom I will raise up for them.'),
  ('BSB', 'Jeremiah', 24, 30, 10, 'As for you, O Jacob My servant, do not be afraid, declares the LORD, and do not be dismayed, O Israel. For I will surely save you out of a distant place, your descendants from the land of their captivity! Jacob will return to quiet and ease, with no one to make him afraid.'),
  ('BSB', 'Jeremiah', 24, 30, 11, 'For I am with you to save you, declares the LORD. Though I will completely destroy all the nations to which I have scattered you, I will not completely destroy you. Yet I will discipline you justly, and will by no means leave you unpunished.”'),
  ('BSB', 'Jeremiah', 24, 30, 12, 'For this is what the LORD says: “Your injury is incurable; your wound is grievous.'),
  ('BSB', 'Jeremiah', 24, 30, 13, 'There is no one to plead your cause, no remedy for your sores, no recovery for you.'),
  ('BSB', 'Jeremiah', 24, 30, 14, 'All your lovers have forgotten you; they no longer seek you, for I have struck you as an enemy would, with the discipline of someone cruel, because of your great iniquity and your numerous sins.'),
  ('BSB', 'Jeremiah', 24, 30, 15, 'Why do you cry out over your wound? Your pain has no cure! Because of your great iniquity and your numerous sins I have done these things to you.'),
  ('BSB', 'Jeremiah', 24, 30, 16, 'Nevertheless, all who devour you will be devoured, and all your adversaries—every one of them— will go off into exile. Those who plundered you will be plundered, and all who raided you will be raided.'),
  ('BSB', 'Jeremiah', 24, 30, 17, 'But I will restore your health and heal your wounds, declares the LORD, because they call you an outcast, Zion, for whom no one cares.”'),
  ('BSB', 'Jeremiah', 24, 30, 18, 'This is what the LORD says: “I will restore the fortunes of Jacob’s tents and have compassion on his dwellings. And the city will be rebuilt on her own ruins, and the palace will stand in its rightful place.'),
  ('BSB', 'Jeremiah', 24, 30, 19, 'Thanksgiving will proceed from them, a sound of celebration. I will multiply them, and they will not be decreased; I will honor them, and they will not be belittled.'),
  ('BSB', 'Jeremiah', 24, 30, 20, 'Their children will be as in days of old, and their congregation will be established before Me; and I will punish all their oppressors.'),
  ('BSB', 'Jeremiah', 24, 30, 21, 'Their leader will be one of their own, and their ruler will arise from their midst. And I will bring him near, and he will approach Me, for who would dare on his own to approach Me?” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 30, 22, '“And you will be My people, and I will be your God.”'),
  ('BSB', 'Jeremiah', 24, 30, 23, 'Behold, the storm of the LORD has gone out with fury, a whirlwind swirling down upon the heads of the wicked.'),
  ('BSB', 'Jeremiah', 24, 30, 24, 'The fierce anger of the LORD will not turn back until He has fully accomplished the purposes of His heart. In the days to come you will understand this.'),
  ('BSB', 'Jeremiah', 24, 31, 1, '“At that time,” declares the LORD, “I will be the God of all the families of Israel, and they will be My people.”'),
  ('BSB', 'Jeremiah', 24, 31, 2, 'This is what the LORD says: “The people who survived the sword found favor in the wilderness when Israel went to find rest.”'),
  ('BSB', 'Jeremiah', 24, 31, 3, 'The LORD appeared to us in the past, saying: “I have loved you with an everlasting love; therefore I have drawn you with loving devotion.'),
  ('BSB', 'Jeremiah', 24, 31, 4, 'Again I will build you, and you will be rebuilt, O Virgin Israel. Again you will take up your tambourines and go out in joyful dancing.'),
  ('BSB', 'Jeremiah', 24, 31, 5, 'Again you will plant vineyards on the hills of Samaria; the farmers will plant and enjoy the fruit.'),
  ('BSB', 'Jeremiah', 24, 31, 6, 'For there will be a day when watchmen will call out on the hills of Ephraim, ‘Arise, let us go up to Zion, to the LORD our God!’”'),
  ('BSB', 'Jeremiah', 24, 31, 7, 'For this is what the LORD says: “Sing with joy for Jacob; shout for the foremost of the nations! Make your praises heard, and say, ‘O LORD, save Your people, the remnant of Israel!’'),
  ('BSB', 'Jeremiah', 24, 31, 8, 'Behold, I will bring them from the land of the north and gather them from the farthest parts of the earth, including the blind and the lame, expectant mothers and women in labor. They will return as a great assembly!'),
  ('BSB', 'Jeremiah', 24, 31, 9, 'They will come with weeping, and by their supplication I will lead them; I will make them walk beside streams of waters, on a level path where they will not stumble. For I am Israel’s Father, and Ephraim is My firstborn.”'),
  ('BSB', 'Jeremiah', 24, 31, 10, 'Hear, O nations, the word of the LORD, and proclaim it in distant coastlands: “The One who scattered Israel will gather them and keep them as a shepherd keeps his flock.'),
  ('BSB', 'Jeremiah', 24, 31, 11, 'For the LORD has ransomed Jacob and redeemed him from the hand that had overpowered him.'),
  ('BSB', 'Jeremiah', 24, 31, 12, 'They will come and shout for joy on the heights of Zion; they will be radiant over the bounty of the LORD— the grain, new wine, and oil, and the young of the flocks and herds. Their life will be like a well-watered garden, and never again will they languish.'),
  ('BSB', 'Jeremiah', 24, 31, 13, 'Then the maidens will rejoice with dancing, young men and old as well. I will turn their mourning into joy, and give them comfort and joy for their sorrow.'),
  ('BSB', 'Jeremiah', 24, 31, 14, 'I will fill the souls of the priests abundantly, and will fill My people with My goodness,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 31, 15, 'This is what the LORD says: “A voice is heard in Ramah, mourning and great weeping, Rachel weeping for her children, and refusing to be comforted, because they are no more.”'),
  ('BSB', 'Jeremiah', 24, 31, 16, 'This is what the LORD says: “Keep your voice from weeping and your eyes from tears, for the reward for your work will come, declares the LORD. Then your children will return from the land of the enemy.'),
  ('BSB', 'Jeremiah', 24, 31, 17, 'So there is hope for your future, declares the LORD, and your children will return to their own land.'),
  ('BSB', 'Jeremiah', 24, 31, 18, 'I have surely heard Ephraim’s moaning: ‘You disciplined me severely, like an untrained calf. Restore me, that I may return, for You are the LORD my God.'),
  ('BSB', 'Jeremiah', 24, 31, 19, 'After I returned, I repented; and after I was instructed, I struck my thigh in grief. I was ashamed and humiliated because I bore the disgrace of my youth.’'),
  ('BSB', 'Jeremiah', 24, 31, 20, 'Is not Ephraim a precious son to Me, a delightful child? Though I often speak against him, I still remember him. Therefore My heart yearns for him; I have great compassion for him,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 31, 21, '“Set up the roadmarks, establish the signposts. Keep the highway in mind, the road you have traveled. Return, O Virgin Israel, return to these cities of yours.'),
  ('BSB', 'Jeremiah', 24, 31, 22, 'How long will you wander, O faithless daughter? For the LORD has created a new thing in the land— a woman will shelter a man.”'),
  ('BSB', 'Jeremiah', 24, 31, 23, 'This is what the LORD of Hosts, the God of Israel, says: “When I restore them from captivity, they will once again speak this word in the land of Judah and in its cities: ‘May the LORD bless you, O righteous dwelling place, O holy mountain.’'),
  ('BSB', 'Jeremiah', 24, 31, 24, 'And Judah and all its cities will dwell together in the land, the farmers and those who move with the flocks,'),
  ('BSB', 'Jeremiah', 24, 31, 25, 'for I will refresh the weary soul and replenish all who are weak.”'),
  ('BSB', 'Jeremiah', 24, 31, 26, 'At this I awoke and looked around. My sleep had been most pleasant to me.'),
  ('BSB', 'Jeremiah', 24, 31, 27, '“The days are coming,” declares the LORD, “when I will sow the house of Israel and the house of Judah with the seed of man and of beast.'),
  ('BSB', 'Jeremiah', 24, 31, 28, 'Just as I watched over them to uproot and tear down, to demolish, destroy, and bring disaster, so I will watch over them to build and to plant,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 31, 29, '“In those days, it will no longer be said: ‘The fathers have eaten sour grapes, and the teeth of the children are set on edge.’'),
  ('BSB', 'Jeremiah', 24, 31, 30, 'Instead, each will die for his own iniquity. If anyone eats the sour grapes, his own teeth will be set on edge.'),
  ('BSB', 'Jeremiah', 24, 31, 31, 'Behold, the days are coming, declares the LORD, when I will make a new covenant with the house of Israel and with the house of Judah.'),
  ('BSB', 'Jeremiah', 24, 31, 32, 'It will not be like the covenant I made with their fathers when I took them by the hand to lead them out of the land of Egypt— a covenant they broke, though I was a husband to them,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 31, 33, '“But this is the covenant I will make with the house of Israel after those days, declares the LORD. I will put My law in their minds and inscribe it on their hearts. And I will be their God, and they will be My people.'),
  ('BSB', 'Jeremiah', 24, 31, 34, 'No longer will each man teach his neighbor or his brother, saying, ‘Know the LORD,’ because they will all know Me, from the least of them to the greatest, declares the LORD. For I will forgive their iniquities and will remember their sins no more.”'),
  ('BSB', 'Jeremiah', 24, 31, 35, 'Thus says the LORD, who gives the sun for light by day, who sets in order the moon and stars for light by night, who stirs up the sea so that its waves roar—the LORD of Hosts is His name:'),
  ('BSB', 'Jeremiah', 24, 31, 36, '“Only if this fixed order departed from My presence, declares the LORD, would Israel’s descendants ever cease to be a nation before Me.”'),
  ('BSB', 'Jeremiah', 24, 31, 37, 'This is what the LORD says: “Only if the heavens above could be measured and the foundations of the earth below searched out would I reject all of Israel’s descendants because of all they have done,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 31, 38, '“The days are coming,” declares the LORD, “when this city will be rebuilt for Me, from the tower of Hananel to the Corner Gate.'),
  ('BSB', 'Jeremiah', 24, 31, 39, 'The measuring line will once again stretch out straight to the hill of Gareb and then turn toward Goah.'),
  ('BSB', 'Jeremiah', 24, 31, 40, 'The whole valley of the dead bodies and ashes, and all the fields as far as the Kidron Valley, to the corner of the Horse Gate to the east, will be holy to the LORD. It will never again be uprooted or demolished.”'),
  ('BSB', 'Jeremiah', 24, 32, 1, 'This is the word that came to Jeremiah from the LORD in the tenth year of Zedekiah king of Judah, which was the eighteenth year of Nebuchadnezzar.'),
  ('BSB', 'Jeremiah', 24, 32, 2, 'At that time the army of the king of Babylon was besieging Jerusalem, and Jeremiah the prophet was imprisoned in the courtyard of the guard, which was in the palace of the king of Judah.'),
  ('BSB', 'Jeremiah', 24, 32, 3, 'For Zedekiah king of Judah had imprisoned him, saying: “Why are you prophesying like this? You claim that the LORD says, ‘Behold, I am about to deliver this city into the hand of the king of Babylon, and he will capture it.'),
  ('BSB', 'Jeremiah', 24, 32, 4, 'Zedekiah king of Judah will not escape from the hands of the Chaldeans, but he will surely be delivered into the hand of the king of Babylon, and will speak with him face to face and see him eye to eye.'),
  ('BSB', 'Jeremiah', 24, 32, 5, 'He will take Zedekiah to Babylon, where he will stay until I attend to him, declares the LORD. If you fight against the Chaldeans, you will not succeed.’”'),
  ('BSB', 'Jeremiah', 24, 32, 6, 'Jeremiah replied, “The word of the LORD came to me, saying:'),
  ('BSB', 'Jeremiah', 24, 32, 7, 'Behold! Hanamel, the son of your uncle Shallum, is coming to you to say, ‘Buy for yourself my field in Anathoth, for you have the right of redemption to buy it.’'),
  ('BSB', 'Jeremiah', 24, 32, 8, 'Then, as the LORD had said, my cousin Hanamel came to me in the courtyard of the guard and urged me, ‘Please buy my field in Anathoth in the land of Benjamin, for you own the right of inheritance and redemption. Buy it for yourself.’” Then I knew that this was the word of the LORD.'),
  ('BSB', 'Jeremiah', 24, 32, 9, 'So I bought the field in Anathoth from my cousin Hanamel, and I weighed out seventeen shekels of silver.'),
  ('BSB', 'Jeremiah', 24, 32, 10, 'I signed and sealed the deed, called in witnesses, and weighed out the silver on the scales.'),
  ('BSB', 'Jeremiah', 24, 32, 11, 'Then I took the deed of purchase—the sealed copy with its terms and conditions, as well as the open copy—'),
  ('BSB', 'Jeremiah', 24, 32, 12, 'and I gave this deed to Baruch son of Neriah, the son of Mahseiah, in the sight of my cousin Hanamel and the witnesses who were signing the purchase agreement and all the Jews sitting in the courtyard of the guard.'),
  ('BSB', 'Jeremiah', 24, 32, 13, 'In their sight I instructed Baruch,'),
  ('BSB', 'Jeremiah', 24, 32, 14, '“This is what the LORD of Hosts, the God of Israel, says: Take these deeds—both the sealed copy and the open copy of the deed of purchase—and put them in a clay jar to preserve them for a long time.'),
  ('BSB', 'Jeremiah', 24, 32, 15, 'For this is what the LORD of Hosts, the God of Israel, says: Houses, fields, and vineyards will again be bought in this land.”'),
  ('BSB', 'Jeremiah', 24, 32, 16, 'After I had given the deed of purchase to Baruch son of Neriah, I prayed to the LORD:'),
  ('BSB', 'Jeremiah', 24, 32, 17, '“Oh, Lord GOD! You have made the heavens and the earth by Your great power and outstretched arm. Nothing is too difficult for You!'),
  ('BSB', 'Jeremiah', 24, 32, 18, 'You show loving devotion to thousands but lay the iniquity of the fathers into the laps of their children after them, O great and mighty God whose name is the LORD of Hosts,'),
  ('BSB', 'Jeremiah', 24, 32, 19, 'the One great in counsel and mighty in deed, whose eyes are on all the ways of the sons of men, to reward each one according to his ways and according to the fruit of his deeds.'),
  ('BSB', 'Jeremiah', 24, 32, 20, 'You performed signs and wonders in the land of Egypt, and You do so to this very day, both in Israel and among all mankind. And You have made a name for Yourself, as is the case to this day.'),
  ('BSB', 'Jeremiah', 24, 32, 21, 'You brought Your people Israel out of the land of Egypt with signs and wonders, with a strong hand and an outstretched arm, and with great terror.'),
  ('BSB', 'Jeremiah', 24, 32, 22, 'You gave them this land that You had sworn to give their fathers, a land flowing with milk and honey.'),
  ('BSB', 'Jeremiah', 24, 32, 23, 'They came in and possessed it, but they did not obey Your voice or walk in Your law. They failed to perform all that You commanded them to do, and so You have brought upon them all this disaster.'),
  ('BSB', 'Jeremiah', 24, 32, 24, 'See how the siege ramps are mounted against the city to capture it. And by sword and famine and plague, the city has been given into the hands of the Chaldeans who are fighting against it. What You have spoken has happened, as You now see!'),
  ('BSB', 'Jeremiah', 24, 32, 25, 'Yet You, O Lord GOD, have said to me, ‘Buy for yourself the field with silver and call in witnesses, even though the city has been delivered into the hands of the Chaldeans!’”'),
  ('BSB', 'Jeremiah', 24, 32, 26, 'Then the word of the LORD came to Jeremiah:'),
  ('BSB', 'Jeremiah', 24, 32, 27, '“Behold, I am the LORD, the God of all flesh. Is anything too difficult for Me?'),
  ('BSB', 'Jeremiah', 24, 32, 28, 'Therefore this is what the LORD says: Behold, I am about to deliver this city into the hands of the Chaldeans and of Nebuchadnezzar king of Babylon, who will capture it.'),
  ('BSB', 'Jeremiah', 24, 32, 29, 'And the Chaldeans who are fighting against this city will come in, set it on fire, and burn it, along with the houses of those who provoked Me to anger by burning incense to Baal on their rooftops and by pouring out drink offerings to other gods.'),
  ('BSB', 'Jeremiah', 24, 32, 30, 'For the children of Israel and of Judah have done nothing but evil in My sight from their youth; indeed, they have done nothing but provoke Me to anger by the work of their hands, declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 32, 31, 'For this city has aroused My wrath and fury from the day it was built until now. Therefore I will remove it from My presence'),
  ('BSB', 'Jeremiah', 24, 32, 32, 'because of all the evil the children of Israel and of Judah have done to provoke Me to anger—they, their kings, their officials, their priests and prophets, the men of Judah, and the residents of Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 32, 33, 'They have turned their backs to Me and not their faces. Though I taught them again and again, they would not listen or respond to discipline.'),
  ('BSB', 'Jeremiah', 24, 32, 34, 'They have placed their abominations in the house that bears My Name, and so have defiled it.'),
  ('BSB', 'Jeremiah', 24, 32, 35, 'They have built the high places of Baal in the Valley of Hinnom to make their sons and daughters pass through the fire to Molech—something I never commanded them, nor had it ever entered My mind, that they should commit such an abomination and cause Judah to sin.'),
  ('BSB', 'Jeremiah', 24, 32, 36, 'Now therefore, about this city of which you say, ‘It will be delivered into the hand of the king of Babylon by sword and famine and plague,’ this is what the LORD, the God of Israel, says:'),
  ('BSB', 'Jeremiah', 24, 32, 37, 'I will surely gather My people from all the lands to which I have banished them in My furious anger and great wrath, and I will return them to this place and make them dwell in safety.'),
  ('BSB', 'Jeremiah', 24, 32, 38, 'They will be My people, and I will be their God.'),
  ('BSB', 'Jeremiah', 24, 32, 39, 'I will give them one heart and one way, so that they will always fear Me for their own good and for the good of their children after them.'),
  ('BSB', 'Jeremiah', 24, 32, 40, 'I will make an everlasting covenant with them: I will never turn away from doing good to them, and I will put My fear in their hearts, so that they will never turn away from Me.'),
  ('BSB', 'Jeremiah', 24, 32, 41, 'Yes, I will rejoice in doing them good, and I will faithfully plant them in this land with all My heart and with all My soul.'),
  ('BSB', 'Jeremiah', 24, 32, 42, 'For this is what the LORD says: Just as I have brought all this great disaster on this people, so I will bring on them all the good I have promised them.'),
  ('BSB', 'Jeremiah', 24, 32, 43, 'And fields will be bought in this land about which you are saying, ‘It is a desolation, without man or beast; it has been delivered into the hands of the Chaldeans.’'),
  ('BSB', 'Jeremiah', 24, 32, 44, 'Fields will be purchased with silver, and deeds will be signed, sealed, and witnessed in the land of Benjamin, in the areas surrounding Jerusalem, and in the cities of Judah—the cities of the hill country, the foothills, and the Negev—because I will restore them from captivity, declares the LORD.”'),
  ('BSB', 'Jeremiah', 24, 33, 1, 'While Jeremiah was still confined in the courtyard of the guard, the word of the LORD came to him a second time:'),
  ('BSB', 'Jeremiah', 24, 33, 2, '“Thus says the LORD who made the earth, the LORD who formed it and established it, the LORD is His name:'),
  ('BSB', 'Jeremiah', 24, 33, 3, 'Call to Me, and I will answer and show you great and unsearchable things you do not know.'),
  ('BSB', 'Jeremiah', 24, 33, 4, 'For this is what the LORD, the God of Israel, says about the houses of this city and the palaces of the kings of Judah that have been torn down for defense against the siege ramps and the sword:'),
  ('BSB', 'Jeremiah', 24, 33, 5, 'The Chaldeans are coming to fight and to fill those places with the corpses of the men I will strike down in My anger and in My wrath. I have hidden My face from this city because of all its wickedness.'),
  ('BSB', 'Jeremiah', 24, 33, 6, 'Nevertheless, I will bring to it health and healing, and I will heal its people and reveal to them the abundance of peace and truth.'),
  ('BSB', 'Jeremiah', 24, 33, 7, 'I will restore Judah and Israel from captivity and will rebuild them as in former times.'),
  ('BSB', 'Jeremiah', 24, 33, 8, 'And I will cleanse them from all the iniquity they have committed against Me, and will forgive all their sins of rebellion against Me.'),
  ('BSB', 'Jeremiah', 24, 33, 9, 'So this city will bring Me renown, joy, praise, and glory before all the nations of the earth, who will hear of all the good I do for it. They will tremble in awe because of all the goodness and prosperity that I will provide for it.'),
  ('BSB', 'Jeremiah', 24, 33, 10, 'This is what the LORD says: In this place you say is a wasteland without man or beast, in the cities of Judah and in the streets of Jerusalem that are deserted—inhabited by neither man nor beast—there will be heard again'),
  ('BSB', 'Jeremiah', 24, 33, 11, 'the sounds of joy and gladness, the voices of the bride and bridegroom, and the voices of those bringing thank offerings into the house of the LORD, saying: ‘Give thanks to the LORD of Hosts, for the LORD is good; His loving devotion endures forever.’ For I will restore the land from captivity as in former times, says the LORD.'),
  ('BSB', 'Jeremiah', 24, 33, 12, 'This is what the LORD of Hosts says: In this desolate place, without man or beast, and in all its cities, there will once more be pastures for shepherds to rest their flocks.'),
  ('BSB', 'Jeremiah', 24, 33, 13, 'In the cities of the hill country, the foothills, and the Negev, in the land of Benjamin and the cities surrounding Jerusalem, and in the cities of Judah, the flocks will again pass under the hands of the one who counts them, says the LORD.'),
  ('BSB', 'Jeremiah', 24, 33, 14, 'Behold, the days are coming, declares the LORD, when I will fulfill the gracious promise that I have spoken to the house of Israel and the house of Judah.'),
  ('BSB', 'Jeremiah', 24, 33, 15, 'In those days and at that time I will cause to sprout for David a righteous Branch, and He will administer justice and righteousness in the land.'),
  ('BSB', 'Jeremiah', 24, 33, 16, 'In those days Judah will be saved, and Jerusalem will dwell securely, and this is the name by which it will be called: The LORD Our Righteousness.'),
  ('BSB', 'Jeremiah', 24, 33, 17, 'For this is what the LORD says: David will never lack a man to sit on the throne of the house of Israel,'),
  ('BSB', 'Jeremiah', 24, 33, 18, 'nor will the priests who are Levites ever fail to have a man before Me to offer burnt offerings, to burn grain offerings, and to present sacrifices.”'),
  ('BSB', 'Jeremiah', 24, 33, 19, 'And the word of the LORD came to Jeremiah:'),
  ('BSB', 'Jeremiah', 24, 33, 20, '“This is what the LORD says: If you can break My covenant with the day and My covenant with the night, so that day and night cease to occupy their appointed time,'),
  ('BSB', 'Jeremiah', 24, 33, 21, 'then My covenant may also be broken with David My servant and with My ministers the Levites who are priests, so that David will not have a son to reign on his throne.'),
  ('BSB', 'Jeremiah', 24, 33, 22, 'As the hosts of heaven cannot be counted and as the sand on the seashore cannot be measured, so too will I multiply the descendants of My servant David and the Levites who minister before Me.”'),
  ('BSB', 'Jeremiah', 24, 33, 23, 'Moreover, the word of the LORD came to Jeremiah:'),
  ('BSB', 'Jeremiah', 24, 33, 24, '“Have you not noticed what these people are saying: ‘The LORD has rejected the two families He had chosen’? So they despise My people and no longer regard them as a nation.'),
  ('BSB', 'Jeremiah', 24, 33, 25, 'This is what the LORD says: If I have not established My covenant with the day and the night and the fixed order of heaven and earth,'),
  ('BSB', 'Jeremiah', 24, 33, 26, 'then I would also reject the descendants of Jacob and of My servant David, so as not to take from his descendants rulers over the descendants of Abraham, Isaac, and Jacob. For I will restore them from captivity and will have compassion on them.”'),
  ('BSB', 'Jeremiah', 24, 34, 1, 'This is the word that came to Jeremiah from the LORD when Nebuchadnezzar king of Babylon, all his army, all the earthly kingdoms under his control, and all the other nations were fighting against Jerusalem and all its surrounding cities.'),
  ('BSB', 'Jeremiah', 24, 34, 2, 'The LORD, the God of Israel, told Jeremiah to go and speak to Zedekiah king of Judah and tell him that this is what the LORD says: “Behold, I am about to deliver this city into the hand of the king of Babylon, and he will burn it down.'),
  ('BSB', 'Jeremiah', 24, 34, 3, 'And you yourself will not escape his grasp, but will surely be captured and delivered into his hand. You will see the king of Babylon eye to eye and speak with him face to face; and you will go to Babylon.'),
  ('BSB', 'Jeremiah', 24, 34, 4, 'Yet hear the word of the LORD, O Zedekiah king of Judah. This is what the LORD says concerning you: You will not die by the sword;'),
  ('BSB', 'Jeremiah', 24, 34, 5, 'you will die in peace. As spices were burned for your fathers, the former kings who preceded you, so people will burn spices for you and lament, ‘Alas, O master!’ For I Myself have spoken this word, declares the LORD.”'),
  ('BSB', 'Jeremiah', 24, 34, 6, 'In Jerusalem, then, Jeremiah the prophet relayed all these words to Zedekiah king of Judah'),
  ('BSB', 'Jeremiah', 24, 34, 7, 'as the army of the king of Babylon was fighting against Jerusalem and the remaining cities of Judah—against Lachish and Azekah. For these were the only fortified cities remaining in Judah.'),
  ('BSB', 'Jeremiah', 24, 34, 8, 'After King Zedekiah had made a covenant with all the people in Jerusalem to proclaim liberty, the word came to Jeremiah from the LORD'),
  ('BSB', 'Jeremiah', 24, 34, 9, 'that each man should free his Hebrew slaves, both male and female, and no one should hold his fellow Jew in bondage.'),
  ('BSB', 'Jeremiah', 24, 34, 10, 'So all the officials and all the people who entered into this covenant agreed that they would free their menservants and maidservants and no longer hold them in bondage. They obeyed and released them,'),
  ('BSB', 'Jeremiah', 24, 34, 11, 'but later they changed their minds and took back the menservants and maidservants they had freed, and they forced them to become slaves again.'),
  ('BSB', 'Jeremiah', 24, 34, 12, 'Then the word of the LORD came to Jeremiah from the LORD, saying,'),
  ('BSB', 'Jeremiah', 24, 34, 13, '“This is what the LORD, the God of Israel, says: I made a covenant with your forefathers when I brought them out of the land of Egypt, out of the house of slavery, saying:'),
  ('BSB', 'Jeremiah', 24, 34, 14, 'Every seventh year, each of you must free his Hebrew brother who has sold himself to you. He may serve you six years, but then you must let him go free. But your fathers did not listen or incline their ear.'),
  ('BSB', 'Jeremiah', 24, 34, 15, 'Recently you repented and did what pleased Me; each of you proclaimed freedom for his neighbor. You made a covenant before Me in the house that bears My Name.'),
  ('BSB', 'Jeremiah', 24, 34, 16, 'But now you have changed your minds and profaned My name. Each of you has taken back the menservants and maidservants whom you had set at liberty to go wherever they wanted, and you have again forced them to be your slaves.'),
  ('BSB', 'Jeremiah', 24, 34, 17, 'Therefore this is what the LORD says: You have not obeyed Me; you have not proclaimed freedom, each man for his brother and for his neighbor. So now I proclaim freedom for you, declares the LORD—freedom to fall by sword, by plague, and by famine! I will make you a horror to all the kingdoms of the earth.'),
  ('BSB', 'Jeremiah', 24, 34, 18, 'And those who have transgressed My covenant and have not fulfilled the terms of the covenant they made before Me, I will treat like the calf they cut in two in order to pass between its pieces.'),
  ('BSB', 'Jeremiah', 24, 34, 19, 'The officials of Judah and Jerusalem, the court officials, the priests, and all the people of the land who passed between the pieces of the calf,'),
  ('BSB', 'Jeremiah', 24, 34, 20, 'I will deliver into the hands of their enemies who seek their lives. Their corpses will become food for the birds of the air and the beasts of the earth.'),
  ('BSB', 'Jeremiah', 24, 34, 21, 'And I will deliver Zedekiah king of Judah and his officials into the hands of their enemies who seek their lives, to the army of the king of Babylon that had withdrawn from you.'),
  ('BSB', 'Jeremiah', 24, 34, 22, 'Behold, I am going to give the command, declares the LORD, and I will bring them back to this city. They will fight against it, capture it, and burn it down. And I will make the cities of Judah a desolation, without inhabitant.”'),
  ('BSB', 'Jeremiah', 24, 35, 1, 'This is the word that came to Jeremiah from the LORD in the days of Jehoiakim son of Josiah king of Judah:'),
  ('BSB', 'Jeremiah', 24, 35, 2, '“Go to the house of the Rechabites, speak to them, and bring them to one of the chambers of the house of the LORD to offer them a drink of wine.”'),
  ('BSB', 'Jeremiah', 24, 35, 3, 'So I took Jaazaniah son of Jeremiah, the son of Habazziniah, and his brothers and all his sons—the entire house of the Rechabites—'),
  ('BSB', 'Jeremiah', 24, 35, 4, 'and I brought them into the house of the LORD, to a chamber occupied by the sons of Hanan son of Igdaliah, a man of God. This room was near the chamber of the officials, which was above the chamber of Maaseiah son of Shallum the doorkeeper.'),
  ('BSB', 'Jeremiah', 24, 35, 5, 'Then I set pitchers full of wine and some cups before the men of the house of the Rechabites, and I said to them, “Drink some wine.”'),
  ('BSB', 'Jeremiah', 24, 35, 6, '“We do not drink wine,” they replied, “for our forefather Jonadab son of Rechab commanded us, ‘Neither you nor your descendants are ever to drink wine.'),
  ('BSB', 'Jeremiah', 24, 35, 7, 'Nor are you ever to build a house or sow seed or plant a vineyard. Those things are not for you. Instead, you must live in tents all your lives, so that you may live a long time in the land where you wander.’'),
  ('BSB', 'Jeremiah', 24, 35, 8, 'And we have obeyed the voice of our forefather Jonadab son of Rechab in all he commanded us. So we have not drunk wine all our lives—neither we nor our wives nor our sons and daughters.'),
  ('BSB', 'Jeremiah', 24, 35, 9, 'Nor have we built houses in which to live, and we have not owned any vineyards or fields or crops.'),
  ('BSB', 'Jeremiah', 24, 35, 10, 'But we have lived in tents and have obeyed and done exactly as our forefather Jonadab commanded us.'),
  ('BSB', 'Jeremiah', 24, 35, 11, 'So when Nebuchadnezzar king of Babylon marched into the land, we said: ‘Come, let us go into Jerusalem to escape the armies of the Chaldeans and the Arameans.’ So we have remained in Jerusalem.”'),
  ('BSB', 'Jeremiah', 24, 35, 12, 'Then the word of the LORD came to Jeremiah:'),
  ('BSB', 'Jeremiah', 24, 35, 13, '“This is what the LORD of Hosts, the God of Israel, says: Go and tell the men of Judah and the residents of Jerusalem: ‘Will you not accept discipline and obey My words?’ declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 35, 14, 'The words of Jonadab son of Rechab have been carried out. He commanded his sons not to drink wine, and they have not drunk it to this very day because they have obeyed the command of their forefather. But I have spoken to you again and again, and you have not obeyed Me!'),
  ('BSB', 'Jeremiah', 24, 35, 15, 'Again and again I have sent you all My servants the prophets, proclaiming: ‘Turn now, each of you, from your wicked ways, and correct your actions. Do not go after other gods to serve them. Live in the land that I have given to you and your fathers.’ But you have not inclined your ear or listened to Me.'),
  ('BSB', 'Jeremiah', 24, 35, 16, 'Yes, the sons of Jonadab son of Rechab carried out the command their forefather gave them, but these people have not listened to Me.'),
  ('BSB', 'Jeremiah', 24, 35, 17, 'Therefore this is what the LORD God of Hosts, the God of Israel, says: ‘Behold, I will bring to Judah and to all the residents of Jerusalem all the disaster I have pronounced against them, because I have spoken to them but they have not obeyed, and I have called to them but they have not answered.’”'),
  ('BSB', 'Jeremiah', 24, 35, 18, 'Then Jeremiah said to the house of the Rechabites: “This is what the LORD of Hosts, the God of Israel, says: ‘Because you have obeyed the command of your forefather Jonadab and have kept all his commandments and have done all that he charged you to do,'),
  ('BSB', 'Jeremiah', 24, 35, 19, 'this is what the LORD of Hosts, the God of Israel, says: Jonadab son of Rechab will never fail to have a man to stand before Me.’”'),
  ('BSB', 'Jeremiah', 24, 36, 1, 'In the fourth year of Jehoiakim son of Josiah king of Judah, this word came to Jeremiah from the LORD:'),
  ('BSB', 'Jeremiah', 24, 36, 2, '“Take a scroll and write on it all the words I have spoken to you concerning Israel, Judah, and all the nations, from the day I first spoke to you during the reign of Josiah until today.'),
  ('BSB', 'Jeremiah', 24, 36, 3, 'Perhaps when the people of Judah hear about all the calamity I plan to bring upon them, each of them will turn from his wicked way. Then I will forgive their iniquity and their sin.”'),
  ('BSB', 'Jeremiah', 24, 36, 4, 'So Jeremiah called Baruch son of Neriah, and at the dictation of Jeremiah, Baruch wrote on a scroll all the words that the LORD had spoken to Jeremiah.'),
  ('BSB', 'Jeremiah', 24, 36, 5, 'Then Jeremiah commanded Baruch, “I am restricted; I cannot enter the house of the LORD;'),
  ('BSB', 'Jeremiah', 24, 36, 6, 'so you are to go to the house of the LORD on a day of fasting, and in the hearing of the people you are to read the words of the LORD from the scroll you have written at my dictation. Read them in the hearing of all the people of Judah who are coming from their cities.'),
  ('BSB', 'Jeremiah', 24, 36, 7, 'Perhaps they will bring their petition before the LORD, and each one will turn from his wicked way; for great are the anger and fury that the LORD has pronounced against this people.”'),
  ('BSB', 'Jeremiah', 24, 36, 8, 'So Baruch son of Neriah did everything that Jeremiah the prophet had commanded him. In the house of the LORD he read the words of the LORD from the scroll.'),
  ('BSB', 'Jeremiah', 24, 36, 9, 'Now in the ninth month of the fifth year of Jehoiakim son of Josiah king of Judah, a fast before the LORD was proclaimed to all the people of Jerusalem and all who had come there from the cities of Judah.'),
  ('BSB', 'Jeremiah', 24, 36, 10, 'From the chamber of Gemariah son of Shaphan the scribe, which was in the upper courtyard at the opening of the New Gate of the house of the LORD, Baruch read from the scroll the words of Jeremiah in the hearing of all the people.'),
  ('BSB', 'Jeremiah', 24, 36, 11, 'When Micaiah son of Gemariah, the son of Shaphan, heard all the words of the LORD from the scroll,'),
  ('BSB', 'Jeremiah', 24, 36, 12, 'he went down to the scribe’s chamber in the king’s palace, where all the officials were sitting: Elishama the scribe, Delaiah son of Shemaiah, Elnathan son of Achbor, Gemariah son of Shaphan, Zedekiah son of Hananiah, and all the other officials.'),
  ('BSB', 'Jeremiah', 24, 36, 13, 'And Micaiah reported to them all the words he had heard Baruch read from the scroll in the hearing of the people.'),
  ('BSB', 'Jeremiah', 24, 36, 14, 'Then all the officials sent word to Baruch through Jehudi son of Nethaniah, the son of Shelemiah, the son of Cushi, saying, “Bring the scroll that you read in the hearing of the people, and come here.” So Baruch son of Neriah took the scroll and went to them.'),
  ('BSB', 'Jeremiah', 24, 36, 15, '“Please sit down,” they said, “and read it in our hearing.” So Baruch read it in their hearing.'),
  ('BSB', 'Jeremiah', 24, 36, 16, 'When they had heard all these words, they turned to one another in fear and said to Baruch, “Surely we must report all these words to the king.”'),
  ('BSB', 'Jeremiah', 24, 36, 17, '“Tell us now,” they asked Baruch, “how did you write all these words? Was it at Jeremiah’s dictation?”'),
  ('BSB', 'Jeremiah', 24, 36, 18, '“It was at his dictation,” Baruch replied. “He recited all these words to me and I wrote them in ink on the scroll.”'),
  ('BSB', 'Jeremiah', 24, 36, 19, 'Then the officials said to Baruch, “You and Jeremiah must hide yourselves and tell no one where you are.”'),
  ('BSB', 'Jeremiah', 24, 36, 20, 'So the officials went to the king in the courtyard. And having stored the scroll in the chamber of Elishama the scribe, they reported everything to the king.'),
  ('BSB', 'Jeremiah', 24, 36, 21, 'Then the king sent Jehudi to get the scroll, and he took it from the chamber of Elishama the scribe. And Jehudi read it in the hearing of the king and all the officials who were standing beside him.'),
  ('BSB', 'Jeremiah', 24, 36, 22, 'Since it was the ninth month, the king was sitting in his winter quarters with a fire burning before him.'),
  ('BSB', 'Jeremiah', 24, 36, 23, 'And as soon as Jehudi had read three or four columns, Jehoiakim would cut them off with a scribe’s knife and throw them into the firepot, until the entire scroll had been consumed by the fire.'),
  ('BSB', 'Jeremiah', 24, 36, 24, 'Yet in hearing all these words, the king and his servants did not become frightened or tear their garments.'),
  ('BSB', 'Jeremiah', 24, 36, 25, 'Even though Elnathan, Delaiah, and Gemariah urged the king not to burn the scroll, he would not listen to them.'),
  ('BSB', 'Jeremiah', 24, 36, 26, 'Instead, the king commanded Jerahmeel, a son of the king, as well as Seraiah son of Azriel and Shelemiah son of Abdeel, to seize Baruch the scribe and Jeremiah the prophet. But the LORD had hidden them.'),
  ('BSB', 'Jeremiah', 24, 36, 27, 'After the king had burned the scroll containing the words that Baruch had written at Jeremiah’s dictation, the word of the LORD came to Jeremiah:'),
  ('BSB', 'Jeremiah', 24, 36, 28, '“Take another scroll and rewrite on it the very words that were on the original scroll, which Jehoiakim king of Judah has burned.'),
  ('BSB', 'Jeremiah', 24, 36, 29, 'You are to proclaim concerning Jehoiakim king of Judah that this is what the LORD says: You have burned the scroll and said, ‘Why have you written on it that the king of Babylon would surely come and destroy this land and deprive it of man and beast?’'),
  ('BSB', 'Jeremiah', 24, 36, 30, 'Therefore this is what the LORD says about Jehoiakim king of Judah: He will have no one to sit on David’s throne, and his body will be thrown out and exposed to heat by day and frost by night.'),
  ('BSB', 'Jeremiah', 24, 36, 31, 'I will punish him and his descendants and servants for their iniquity. I will bring on them, on the residents of Jerusalem, and on the men of Judah, all the calamity about which I warned them but they did not listen.”'),
  ('BSB', 'Jeremiah', 24, 36, 32, 'Then Jeremiah took another scroll and gave it to the scribe Baruch son of Neriah, and at Jeremiah’s dictation he wrote on it all the words of the scroll that Jehoiakim king of Judah had burned in the fire. And many similar words were added to them.'),
  ('BSB', 'Jeremiah', 24, 37, 1, 'Nebuchadnezzar king of Babylon made Zedekiah son of Josiah the king of Judah, and he reigned in place of Coniah son of Jehoiakim.'),
  ('BSB', 'Jeremiah', 24, 37, 2, 'But he and his officers and the people of the land refused to obey the words that the LORD had spoken through Jeremiah the prophet.'),
  ('BSB', 'Jeremiah', 24, 37, 3, 'Yet King Zedekiah sent Jehucal son of Shelemiah and Zephaniah the priest, the son of Maaseiah, to Jeremiah the prophet with the message, “Please pray to the LORD our God for us!”'),
  ('BSB', 'Jeremiah', 24, 37, 4, 'Now Jeremiah was free to come and go among the people, for they had not yet put him in prison.'),
  ('BSB', 'Jeremiah', 24, 37, 5, 'Pharaoh’s army had left Egypt, and when the Chaldeans who were besieging Jerusalem heard the report, they withdrew from Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 37, 6, 'Then the word of the LORD came to Jeremiah the prophet:'),
  ('BSB', 'Jeremiah', 24, 37, 7, '“This is what the LORD, the God of Israel, says that you are to tell the king of Judah, who sent you to Me: Behold, Pharaoh’s army, which has marched out to help you, will go back to its own land of Egypt.'),
  ('BSB', 'Jeremiah', 24, 37, 8, 'Then the Chaldeans will return and fight against this city. They will capture it and burn it down.'),
  ('BSB', 'Jeremiah', 24, 37, 9, 'This is what the LORD says: Do not deceive yourselves by saying, ‘The Chaldeans will go away for good,’ for they will not!'),
  ('BSB', 'Jeremiah', 24, 37, 10, 'Indeed, if you were to strike down the entire army of the Chaldeans that is fighting against you, and only wounded men remained in their tents, they would still get up and burn this city down.”'),
  ('BSB', 'Jeremiah', 24, 37, 11, 'When the Chaldean army withdrew from Jerusalem for fear of Pharaoh’s army,'),
  ('BSB', 'Jeremiah', 24, 37, 12, 'Jeremiah started to leave Jerusalem to go to the land of Benjamin to claim his portion there among the people.'),
  ('BSB', 'Jeremiah', 24, 37, 13, 'But when he reached the Gate of Benjamin, the captain of the guard, whose name was Irijah son of Shelemiah, the son of Hananiah, seized him and said, “You are deserting to the Chaldeans!”'),
  ('BSB', 'Jeremiah', 24, 37, 14, '“That is a lie,” Jeremiah replied. “I am not deserting to the Chaldeans!” But Irijah would not listen to him; instead, he arrested Jeremiah and took him to the officials.'),
  ('BSB', 'Jeremiah', 24, 37, 15, 'The officials were angry with Jeremiah, and they beat him and placed him in jail in the house of Jonathan the scribe, for it had been made into a prison.'),
  ('BSB', 'Jeremiah', 24, 37, 16, 'So Jeremiah went into a cell in the dungeon and remained there a long time.'),
  ('BSB', 'Jeremiah', 24, 37, 17, 'Later, King Zedekiah sent for Jeremiah and received him in his palace, where he asked him privately, “Is there a word from the LORD?” “There is,” Jeremiah replied. “You will be delivered into the hand of the king of Babylon.”'),
  ('BSB', 'Jeremiah', 24, 37, 18, 'Then Jeremiah asked King Zedekiah, “How have I sinned against you or your servants or these people, that you have put me in prison?'),
  ('BSB', 'Jeremiah', 24, 37, 19, 'Where are your prophets who prophesied to you, claiming, ‘The king of Babylon will not come against you or this land’?'),
  ('BSB', 'Jeremiah', 24, 37, 20, 'But now please listen, O my lord the king. May my petition come before you. Do not send me back to the house of Jonathan the scribe, or I will die there.”'),
  ('BSB', 'Jeremiah', 24, 37, 21, 'So King Zedekiah gave orders for Jeremiah to be placed in the courtyard of the guard and given a loaf of bread daily from the street of the bakers, until all the bread in the city was gone. So Jeremiah remained in the courtyard of the guard.'),
  ('BSB', 'Jeremiah', 24, 38, 1, 'Now Shephatiah son of Mattan, Gedaliah son of Pashhur, Jucal son of Shelemiah, and Pashhur son of Malchijah heard that Jeremiah had been telling all the people:'),
  ('BSB', 'Jeremiah', 24, 38, 2, '“This is what the LORD says: Whoever stays in this city will die by sword and famine and plague, but whoever surrenders to the Chaldeans will live; he will retain his life like a spoil of war, and he will live.'),
  ('BSB', 'Jeremiah', 24, 38, 3, 'This is what the LORD says: This city will surely be delivered into the hands of the army of the king of Babylon, and he will capture it.”'),
  ('BSB', 'Jeremiah', 24, 38, 4, 'Then the officials said to the king, “This man ought to die, for he is discouraging the warriors who remain in this city, as well as all the people, by speaking such words to them; this man is not seeking the well-being of these people, but their ruin.”'),
  ('BSB', 'Jeremiah', 24, 38, 5, '“Here he is,” replied King Zedekiah. “He is in your hands, since the king can do nothing to stop you.”'),
  ('BSB', 'Jeremiah', 24, 38, 6, 'So they took Jeremiah and dropped him into the cistern of Malchiah, the king’s son, which was in the courtyard of the guard. They lowered Jeremiah with ropes into the cistern, which had no water but only mud, and Jeremiah sank down into the mud.'),
  ('BSB', 'Jeremiah', 24, 38, 7, 'Now Ebed-melech the Cushite, a court official in the royal palace, heard that Jeremiah had been put into the cistern. While the king was sitting at the Gate of Benjamin,'),
  ('BSB', 'Jeremiah', 24, 38, 8, 'Ebed-melech went out from the king’s palace and said to the king,'),
  ('BSB', 'Jeremiah', 24, 38, 9, '“My lord the king, these men have acted wickedly in all that they have done to Jeremiah the prophet. They have dropped him into the cistern, where he will starve to death, for there is no more bread in the city.”'),
  ('BSB', 'Jeremiah', 24, 38, 10, 'So the king commanded Ebed-melech the Cushite, “Take thirty men from here with you and pull Jeremiah the prophet out of the cistern before he dies.”'),
  ('BSB', 'Jeremiah', 24, 38, 11, 'Then Ebed-melech took the men with him and went to the king’s palace, to a place below the storehouse. From there he took old rags and worn-out clothes and lowered them with ropes to Jeremiah in the cistern.'),
  ('BSB', 'Jeremiah', 24, 38, 12, 'Ebed-melech the Cushite cried out to Jeremiah, “Put these worn-out rags and clothes under your arms to pad the ropes.” Jeremiah did so,'),
  ('BSB', 'Jeremiah', 24, 38, 13, 'and they pulled him up with the ropes and lifted him out of the cistern. And Jeremiah remained in the courtyard of the guard.'),
  ('BSB', 'Jeremiah', 24, 38, 14, 'Then King Zedekiah sent for Jeremiah the prophet and received him at the third entrance to the house of the LORD. “I am going to ask you something,” said the king to Jeremiah. “Do not hide anything from me.”'),
  ('BSB', 'Jeremiah', 24, 38, 15, '“If I tell you,” Jeremiah replied, “you will surely put me to death. And even if I give you advice, you will not listen to me.”'),
  ('BSB', 'Jeremiah', 24, 38, 16, 'But King Zedekiah swore secretly to Jeremiah, “As surely as the LORD lives, who has given us this life, I will not kill you, nor will I deliver you into the hands of these men who are seeking your life.”'),
  ('BSB', 'Jeremiah', 24, 38, 17, 'Then Jeremiah said to Zedekiah, “This is what the LORD God of Hosts, the God of Israel, says: ‘If you indeed surrender to the officers of the king of Babylon, then you will live, this city will not be burned down, and you and your household will survive.'),
  ('BSB', 'Jeremiah', 24, 38, 18, 'But if you do not surrender to the officers of the king of Babylon, then this city will be delivered into the hands of the Chaldeans. They will burn it down, and you yourself will not escape their grasp.’”'),
  ('BSB', 'Jeremiah', 24, 38, 19, 'But King Zedekiah said to Jeremiah, “I am afraid of the Jews who have deserted to the Chaldeans, for the Chaldeans may deliver me into their hands to abuse me.”'),
  ('BSB', 'Jeremiah', 24, 38, 20, '“They will not hand you over,” Jeremiah replied. “Obey the voice of the LORD in what I am telling you, that it may go well with you and you may live.'),
  ('BSB', 'Jeremiah', 24, 38, 21, 'But if you refuse to surrender, this is the word that the LORD has shown me:'),
  ('BSB', 'Jeremiah', 24, 38, 22, 'All the women who remain in the palace of the king of Judah will be brought out to the officials of the king of Babylon, and those women will say: ‘They misled you and overcame you— those trusted friends of yours. Your feet sank into the mire, and they deserted you.’'),
  ('BSB', 'Jeremiah', 24, 38, 23, 'All your wives and children will be brought out to the Chaldeans. And you yourself will not escape their grasp, for you will be seized by the king of Babylon, and this city will be burned down.”'),
  ('BSB', 'Jeremiah', 24, 38, 24, 'Then Zedekiah warned Jeremiah, “Do not let anyone know about this conversation, or you will die.'),
  ('BSB', 'Jeremiah', 24, 38, 25, 'If the officials hear that I have spoken with you, and they come and demand of you, ‘Tell us what you said to the king and what he said to you; do not hide it from us, or we will kill you,’'),
  ('BSB', 'Jeremiah', 24, 38, 26, 'then tell them, ‘I was presenting to the king my petition that he not return me to the house of Jonathan to die there.’”'),
  ('BSB', 'Jeremiah', 24, 38, 27, 'When all the officials came to Jeremiah and questioned him, he relayed to them the exact words the king had commanded him to say. So they said no more to him, for no one had overheard the conversation.'),
  ('BSB', 'Jeremiah', 24, 38, 28, 'And Jeremiah remained in the courtyard of the guard until the day Jerusalem was captured.'),
  ('BSB', 'Jeremiah', 24, 39, 1, 'In the ninth year of Zedekiah king of Judah, in the tenth month, Nebuchadnezzar king of Babylon marched against Jerusalem with his entire army and laid siege to the city.'),
  ('BSB', 'Jeremiah', 24, 39, 2, 'And on the ninth day of the fourth month of Zedekiah’s eleventh year, the city was breached.'),
  ('BSB', 'Jeremiah', 24, 39, 3, 'Then all the officials of the king of Babylon entered and sat in the Middle Gate: Nergal-sharezer of Samgar, Nebo-sarsekim the Rabsaris, Nergal-sharezer the Rabmag, and all the rest of the officials of the king of Babylon.'),
  ('BSB', 'Jeremiah', 24, 39, 4, 'When Zedekiah king of Judah and all the soldiers saw them, they fled. They left the city at night by way of the king’s garden, through the gate between the two walls, and they went out along the route to the Arabah.'),
  ('BSB', 'Jeremiah', 24, 39, 5, 'But the army of the Chaldeans pursued them and overtook Zedekiah in the plains of Jericho. They seized him and brought him up to Nebuchadnezzar king of Babylon at Riblah in the land of Hamath, where he pronounced judgment on him.'),
  ('BSB', 'Jeremiah', 24, 39, 6, 'There at Riblah the king of Babylon slaughtered the sons of Zedekiah before his eyes, and he also killed all the nobles of Judah.'),
  ('BSB', 'Jeremiah', 24, 39, 7, 'Then he put out Zedekiah’s eyes and bound him with bronze chains to take him to Babylon.'),
  ('BSB', 'Jeremiah', 24, 39, 8, 'The Chaldeans set fire to the palace of the king and to the houses of the people, and they broke down the walls of Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 39, 9, 'Then Nebuzaradan captain of the guard carried away to Babylon the remnant of the people who had remained in the city, along with the deserters who had defected to him.'),
  ('BSB', 'Jeremiah', 24, 39, 10, 'But Nebuzaradan left behind in the land of Judah some of the poor people who had no property, and at that time he gave them vineyards and fields.'),
  ('BSB', 'Jeremiah', 24, 39, 11, 'Now Nebuchadnezzar king of Babylon had given orders about Jeremiah through Nebuzaradan captain of the guard, saying,'),
  ('BSB', 'Jeremiah', 24, 39, 12, '“Take him, look after him, and do not let any harm come to him; do for him whatever he says.”'),
  ('BSB', 'Jeremiah', 24, 39, 13, 'So Nebuzaradan captain of the guard, Nebushazban the Rabsaris, Nergal-sharezer the Rabmag, and all the captains of the king of Babylon'),
  ('BSB', 'Jeremiah', 24, 39, 14, 'had Jeremiah brought from the courtyard of the guard, and they turned him over to Gedaliah son of Ahikam, the son of Shaphan, to take him home. So Jeremiah remained among his own people.'),
  ('BSB', 'Jeremiah', 24, 39, 15, 'And while Jeremiah had been confined in the courtyard of the guard, the word of the LORD had come to him:'),
  ('BSB', 'Jeremiah', 24, 39, 16, '“Go and tell Ebed-melech the Cushite that this is what the LORD of Hosts, the God of Israel, says: ‘I am about to fulfill My words against this city for harm and not for good, and on that day they will be fulfilled before your eyes.'),
  ('BSB', 'Jeremiah', 24, 39, 17, 'But I will deliver you on that day, declares the LORD, and you will not be delivered into the hands of the men whom you fear.'),
  ('BSB', 'Jeremiah', 24, 39, 18, 'For I will surely rescue you so that you do not fall by the sword. Because you have trusted in Me, you will escape with your life like a spoil of war, declares the LORD.’”'),
  ('BSB', 'Jeremiah', 24, 40, 1, 'This is the word that came to Jeremiah from the LORD after Nebuzaradan captain of the guard had released him at Ramah, having found him bound in chains among all the captives of Jerusalem and Judah who were being exiled to Babylon.'),
  ('BSB', 'Jeremiah', 24, 40, 2, 'The captain of the guard found Jeremiah and said to him, “The LORD your God decreed this disaster on this place,'),
  ('BSB', 'Jeremiah', 24, 40, 3, 'and now the LORD has fulfilled it; He has done just as He said. Because you people have sinned against the LORD and have not obeyed His voice, this thing has happened to you.'),
  ('BSB', 'Jeremiah', 24, 40, 4, 'But now, behold, I am freeing you today from the chains that were on your wrists. If it pleases you to come with me to Babylon, then come, and I will take care of you. But if it seems wrong to you to come with me to Babylon, go no farther. Look, the whole land is before you. Wherever it seems good and right to you, go there.”'),
  ('BSB', 'Jeremiah', 24, 40, 5, 'But before Jeremiah turned to go, Nebuzaradan added, “Return to Gedaliah son of Ahikam, the son of Shaphan, whom the king of Babylon has appointed over the cities of Judah, and stay with him among the people, or go anywhere else that seems right.” Then the captain of the guard gave him a ration and a gift and released him.'),
  ('BSB', 'Jeremiah', 24, 40, 6, 'So Jeremiah went to Gedaliah son of Ahikam at Mizpah and stayed with him among the people who were left in the land.'),
  ('BSB', 'Jeremiah', 24, 40, 7, 'When all the commanders and men of the armies in the field heard that the king of Babylon had appointed Gedaliah son of Ahikam over the land and that he had put him in charge of the men, women, and children who were the poorest of the land and had not been exiled to Babylon,'),
  ('BSB', 'Jeremiah', 24, 40, 8, 'they came to Gedaliah at Mizpah—Ishmael son of Nethaniah, Johanan and Jonathan the sons of Kareah, Seraiah son of Tanhumeth, the sons of Ephai the Netophathite, and Jezaniah son of the Maacathite—they and their men.'),
  ('BSB', 'Jeremiah', 24, 40, 9, 'Gedaliah son of Ahikam, the son of Shaphan, swore an oath to them and their men, assuring them, “Do not be afraid to serve the Chaldeans. Live in the land and serve the king of Babylon, and it will go well with you.'),
  ('BSB', 'Jeremiah', 24, 40, 10, 'As for me, I will stay in Mizpah to represent you before the Chaldeans who come to us. As for you, gather wine grapes, summer fruit, and oil, place them in your storage jars, and live in the cities you have taken.”'),
  ('BSB', 'Jeremiah', 24, 40, 11, 'When all the Jews in Moab, Ammon, Edom, and all the other lands heard that the king of Babylon had left a remnant in Judah and had appointed Gedaliah son of Ahikam, the son of Shaphan, over them,'),
  ('BSB', 'Jeremiah', 24, 40, 12, 'they all returned from all the places to which they had been banished and came to the land of Judah, to Gedaliah at Mizpah. And they gathered an abundance of wine grapes and summer fruit.'),
  ('BSB', 'Jeremiah', 24, 40, 13, 'Meanwhile, Johanan son of Kareah and all the commanders of the armies in the field came to Gedaliah at Mizpah'),
  ('BSB', 'Jeremiah', 24, 40, 14, 'and said to him, “Are you aware that Baalis king of the Ammonites has sent Ishmael son of Nethaniah to take your life?” But Gedaliah son of Ahikam did not believe them.'),
  ('BSB', 'Jeremiah', 24, 40, 15, 'Then Johanan son of Kareah spoke privately to Gedaliah at Mizpah. “Let me go and kill Ishmael son of Nethaniah,” he said. “No one will know it. Why should he take your life and scatter all the people of Judah who have gathered to you, so that the remnant of Judah would perish?”'),
  ('BSB', 'Jeremiah', 24, 40, 16, 'But Gedaliah son of Ahikam said to Johanan son of Kareah, “Do not do such a thing! What you are saying about Ishmael is a lie.”'),
  ('BSB', 'Jeremiah', 24, 41, 1, 'In the seventh month, Ishmael son of Nethaniah, the son of Elishama, who was a member of the royal family and one of the king’s chief officers, came with ten men to Gedaliah son of Ahikam at Mizpah, and they ate a meal together there.'),
  ('BSB', 'Jeremiah', 24, 41, 2, 'Then Ishmael son of Nethaniah and the ten men who were with him got up and struck down Gedaliah son of Ahikam, the son of Shaphan, with the sword, killing the one whom the king of Babylon had appointed to govern the land.'),
  ('BSB', 'Jeremiah', 24, 41, 3, 'Ishmael also killed all the Jews who were with Gedaliah at Mizpah, as well as the Chaldean soldiers who were there.'),
  ('BSB', 'Jeremiah', 24, 41, 4, 'On the second day after the murder of Gedaliah, when no one yet knew about it,'),
  ('BSB', 'Jeremiah', 24, 41, 5, 'eighty men who had shaved off their beards, torn their garments, and cut themselves came from Shechem, Shiloh, and Samaria, carrying grain offerings and frankincense for the house of the LORD.'),
  ('BSB', 'Jeremiah', 24, 41, 6, 'And Ishmael son of Nethaniah went out from Mizpah to meet them, weeping as he went. When Ishmael encountered the men, he said, “Come to Gedaliah son of Ahikam.”'),
  ('BSB', 'Jeremiah', 24, 41, 7, 'And when they came into the city, Ishmael son of Nethaniah and the men with him slaughtered them and threw them into a cistern.'),
  ('BSB', 'Jeremiah', 24, 41, 8, 'But ten of the men among them said to Ishmael, “Do not kill us, for we have hidden treasure in the field—wheat, barley, oil, and honey!” So he refrained from killing them with the others.'),
  ('BSB', 'Jeremiah', 24, 41, 9, 'Now the cistern into which Ishmael had thrown all the bodies of the men he had struck down along with Gedaliah was a large one that King Asa had made for fear of Baasha king of Israel. Ishmael son of Nethaniah filled it with the slain.'),
  ('BSB', 'Jeremiah', 24, 41, 10, 'Then Ishmael took captive all the remnant of the people of Mizpah—the daughters of the king along with all the others who remained in Mizpah—over whom Nebuzaradan captain of the guard had appointed Gedaliah son of Ahikam. Ishmael son of Nethaniah took them captive and set off to cross over to the Ammonites.'),
  ('BSB', 'Jeremiah', 24, 41, 11, 'When Johanan son of Kareah and all the commanders of the armies with him heard of all the crimes that Ishmael son of Nethaniah had committed,'),
  ('BSB', 'Jeremiah', 24, 41, 12, 'they took all their men and went to fight Ishmael son of Nethaniah. And they found him near the great pool in Gibeon.'),
  ('BSB', 'Jeremiah', 24, 41, 13, 'When all the people with Ishmael saw Johanan son of Kareah and all the commanders of the army with him, they rejoiced,'),
  ('BSB', 'Jeremiah', 24, 41, 14, 'and all the people whom Ishmael had taken captive at Mizpah turned and went over to Johanan son of Kareah.'),
  ('BSB', 'Jeremiah', 24, 41, 15, 'But Ishmael son of Nethaniah and eight of his men escaped from Johanan and went to the Ammonites.'),
  ('BSB', 'Jeremiah', 24, 41, 16, 'Then Johanan son of Kareah and all the commanders of the armies with him took the whole remnant of the people from Mizpah whom he had recovered from Ishmael son of Nethaniah after Ishmael had killed Gedaliah son of Ahikam: the soldiers, women, children, and court officials he had brought back from Gibeon.'),
  ('BSB', 'Jeremiah', 24, 41, 17, 'And they went and stayed in Geruth Chimham, near Bethlehem, in order to proceed into Egypt'),
  ('BSB', 'Jeremiah', 24, 41, 18, 'to escape the Chaldeans. For they were afraid of the Chaldeans because Ishmael son of Nethaniah had struck down Gedaliah son of Ahikam, whom the king of Babylon had appointed over the land.'),
  ('BSB', 'Jeremiah', 24, 42, 1, 'Then all the commanders of the forces, along with Johanan son of Kareah, Jezaniah son of Hoshaiah, and all the people from the least to the greatest, approached'),
  ('BSB', 'Jeremiah', 24, 42, 2, 'Jeremiah the prophet and said, “May our petition come before you; pray to the LORD your God on behalf of this entire remnant. For few of us remain of the many, as you can see with your own eyes.'),
  ('BSB', 'Jeremiah', 24, 42, 3, 'Pray that the LORD your God will tell us the way we should walk and the thing we should do.”'),
  ('BSB', 'Jeremiah', 24, 42, 4, '“I have heard you,” replied Jeremiah the prophet. “I will surely pray to the LORD your God as you request, and I will tell you everything that the LORD answers; I will not withhold a word from you.”'),
  ('BSB', 'Jeremiah', 24, 42, 5, 'Then they said to Jeremiah, “May the LORD be a true and faithful witness against us if we do not act upon every word that the LORD your God sends you to tell us.'),
  ('BSB', 'Jeremiah', 24, 42, 6, 'Whether it is pleasant or unpleasant, we will obey the voice of the LORD our God to whom we are sending you, so that it may go well with us, for we will obey the voice of the LORD our God!”'),
  ('BSB', 'Jeremiah', 24, 42, 7, 'After ten days the word of the LORD came to Jeremiah,'),
  ('BSB', 'Jeremiah', 24, 42, 8, 'and he summoned Johanan son of Kareah, all the commanders of the forces who were with him, and all the people from the least to the greatest.'),
  ('BSB', 'Jeremiah', 24, 42, 9, 'Jeremiah told them, “Thus says the LORD, the God of Israel, to whom you sent me to present your petition:'),
  ('BSB', 'Jeremiah', 24, 42, 10, '‘If you will indeed stay in this land, then I will build you up and not tear you down; I will plant you and not uproot you, for I will relent of the disaster I have brought upon you.'),
  ('BSB', 'Jeremiah', 24, 42, 11, 'Do not be afraid of the king of Babylon, whom you now fear; do not be afraid of him, declares the LORD, for I am with you to save you and deliver you from him.'),
  ('BSB', 'Jeremiah', 24, 42, 12, 'And I will show you compassion, and he will have compassion on you and restore you to your own land.’'),
  ('BSB', 'Jeremiah', 24, 42, 13, 'But if you say, ‘We will not stay in this land,’ and you thus disobey the voice of the LORD your God,'),
  ('BSB', 'Jeremiah', 24, 42, 14, 'and if you say, ‘No, but we will go to the land of Egypt and live there, where we will not see war or hear the sound of the ram’s horn or hunger for bread,’'),
  ('BSB', 'Jeremiah', 24, 42, 15, 'then hear the word of the LORD, O remnant of Judah! This is what the LORD of Hosts, the God of Israel, says: ‘If you are determined to go to Egypt and reside there,'),
  ('BSB', 'Jeremiah', 24, 42, 16, 'then the sword you fear will overtake you there, and the famine you dread will follow on your heels into Egypt, and you will die there.'),
  ('BSB', 'Jeremiah', 24, 42, 17, 'So all who resolve to go to Egypt to reside there will die by sword and famine and plague. Not one of them will survive or escape the disaster I will bring upon them.’'),
  ('BSB', 'Jeremiah', 24, 42, 18, 'For this is what the LORD of Hosts, the God of Israel, says: ‘Just as My anger and wrath were poured out on the residents of Jerusalem, so will My wrath be poured out on you if you go to Egypt. You will become an object of cursing and horror, of vilification and disgrace, and you will never see this place again.’'),
  ('BSB', 'Jeremiah', 24, 42, 19, 'The LORD has told you, O remnant of Judah, ‘Do not go to Egypt.’ Know for sure that I have warned you today!'),
  ('BSB', 'Jeremiah', 24, 42, 20, 'For you have deceived yourselves by sending me to the LORD your God, saying, ‘Pray to the LORD our God on our behalf, and as for all that the LORD our God says, tell it to us and we will do it.’'),
  ('BSB', 'Jeremiah', 24, 42, 21, 'For I have told you today, but you have not obeyed the voice of the LORD your God in all He has sent me to tell you.'),
  ('BSB', 'Jeremiah', 24, 42, 22, 'Now therefore, know for sure that by sword and famine and plague you will die in the place where you desire to go to reside.”'),
  ('BSB', 'Jeremiah', 24, 43, 1, 'When Jeremiah had finished telling all the people all the words of the LORD their God—everything that the LORD had sent him to say—'),
  ('BSB', 'Jeremiah', 24, 43, 2, 'Azariah son of Hoshaiah, Johanan son of Kareah, and all the arrogant men said to Jeremiah, “You are lying! The LORD our God has not sent you to say, ‘You must not go to Egypt to reside there.’');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Jeremiah', 24, 43, 3, 'Rather, Baruch son of Neriah is inciting you against us to deliver us into the hands of the Chaldeans, so that they may put us to death or exile us to Babylon!”'),
  ('BSB', 'Jeremiah', 24, 43, 4, 'So Johanan son of Kareah and all the commanders of the forces disobeyed the command of the LORD to stay in the land of Judah.'),
  ('BSB', 'Jeremiah', 24, 43, 5, 'Instead, Johanan son of Kareah and all the commanders of the forces took the whole remnant of Judah, those who had returned to the land of Judah from all the nations to which they had been scattered,'),
  ('BSB', 'Jeremiah', 24, 43, 6, 'the men, the women, the children, the king’s daughters, and everyone whom Nebuzaradan captain of the guard had allowed to remain with Gedaliah son of Ahikam, the son of Shaphan, as well as Jeremiah the prophet and Baruch son of Neriah.'),
  ('BSB', 'Jeremiah', 24, 43, 7, 'So they entered the land of Egypt because they did not obey the voice of the LORD, and they went as far as Tahpanhes.'),
  ('BSB', 'Jeremiah', 24, 43, 8, 'Then the word of the LORD came to Jeremiah at Tahpanhes:'),
  ('BSB', 'Jeremiah', 24, 43, 9, '“In the sight of the Jews, pick up some large stones and bury them in the clay of the brick pavement at the entrance to Pharaoh’s palace at Tahpanhes.'),
  ('BSB', 'Jeremiah', 24, 43, 10, 'Then tell them that this is what the LORD of Hosts, the God of Israel, says: ‘I will send for My servant Nebuchadnezzar king of Babylon, and I will set his throne over these stones that I have embedded, and he will spread his royal pavilion over them.'),
  ('BSB', 'Jeremiah', 24, 43, 11, 'He will come and strike down the land of Egypt, bringing death to those destined for death, captivity to those destined for captivity, and the sword to those destined for the sword.'),
  ('BSB', 'Jeremiah', 24, 43, 12, 'I will kindle a fire in the temples of the gods of Egypt, and Nebuchadnezzar will burn those temples and take their gods as captives. So he will wrap himself with the land of Egypt as a shepherd wraps himself in his garment, and he will depart from there unscathed.'),
  ('BSB', 'Jeremiah', 24, 43, 13, 'He will demolish the sacred pillars of the temple of the sun in the land of Egypt, and he will burn down the temples of the gods of Egypt.’”'),
  ('BSB', 'Jeremiah', 24, 44, 1, 'This is the word that came to Jeremiah concerning all the Jews living in the land of Egypt—in Migdol, Tahpanhes, and Memphis—and in the land of Pathros:'),
  ('BSB', 'Jeremiah', 24, 44, 2, '“This is what the LORD of Hosts, the God of Israel, says: You have seen all the disaster that I brought against Jerusalem and all the cities of Judah; and behold, they lie today in ruins and desolation'),
  ('BSB', 'Jeremiah', 24, 44, 3, 'because of the evil they have done. They provoked Me to anger by continuing to burn incense and to serve other gods that neither they nor you nor your fathers ever knew.'),
  ('BSB', 'Jeremiah', 24, 44, 4, 'Yet I sent you all My servants the prophets again and again, saying: ‘Do not do this detestable thing that I hate.’'),
  ('BSB', 'Jeremiah', 24, 44, 5, 'But they did not listen or incline their ears; they did not turn from their wickedness or stop burning incense to other gods.'),
  ('BSB', 'Jeremiah', 24, 44, 6, 'Therefore My wrath and anger poured out and burned in the cities of Judah and in the streets of Jerusalem, so that they have become the desolate ruin they are today.'),
  ('BSB', 'Jeremiah', 24, 44, 7, 'So now, this is what the LORD God of Hosts, the God of Israel, says: Why are you doing such great harm to yourselves by cutting off from Judah man and woman, child and infant, leaving yourselves without a remnant?'),
  ('BSB', 'Jeremiah', 24, 44, 8, 'Why are you provoking Me to anger by the work of your hands by burning incense to other gods in the land of Egypt, where you have gone to reside? As a result, you will be cut off and will become an object of cursing and reproach among all the nations of the earth.'),
  ('BSB', 'Jeremiah', 24, 44, 9, 'Have you forgotten the wickedness of your fathers and of the kings of Judah and their wives, as well as the wickedness that you and your wives committed in the land of Judah and in the streets of Jerusalem?'),
  ('BSB', 'Jeremiah', 24, 44, 10, 'To this day they have not humbled themselves or shown reverence, nor have they followed My instruction or the statutes that I set before you and your fathers.'),
  ('BSB', 'Jeremiah', 24, 44, 11, 'Therefore this is what the LORD of Hosts, the God of Israel, says: I will set My face to bring disaster and to cut off all Judah.'),
  ('BSB', 'Jeremiah', 24, 44, 12, 'And I will take away the remnant of Judah who have resolved to go to the land of Egypt to reside there; they will meet their end. They will all fall by the sword or be consumed by famine. From the least to the greatest, they will die by sword or famine; and they will become an object of cursing and horror, of vilification and reproach.'),
  ('BSB', 'Jeremiah', 24, 44, 13, 'I will punish those who live in the land of Egypt, just as I punished Jerusalem, by sword and famine and plague,'),
  ('BSB', 'Jeremiah', 24, 44, 14, 'so that none of the remnant of Judah who have gone to reside in Egypt will escape or survive to return to the land of Judah, where they long to return and live; for none will return except a few fugitives.”'),
  ('BSB', 'Jeremiah', 24, 44, 15, 'Then all the men who knew that their wives were burning incense to other gods, and all the women standing by—a great assembly—along with all the people living in the land of Egypt and in Pathros, said to Jeremiah,'),
  ('BSB', 'Jeremiah', 24, 44, 16, '“As for the word you have spoken to us in the name of the LORD, we will not listen to you!'),
  ('BSB', 'Jeremiah', 24, 44, 17, 'Instead, we will do everything we vowed to do: We will burn incense to the Queen of Heaven and offer drink offerings to her, just as we, our fathers, our kings, and our officials did in the cities of Judah and in the streets of Jerusalem. At that time we had plenty of food and good things, and we saw no disaster.'),
  ('BSB', 'Jeremiah', 24, 44, 18, 'But from the time we stopped burning incense to the Queen of Heaven and pouring out drink offerings to her, we have lacked everything and have been perishing by sword and famine.”'),
  ('BSB', 'Jeremiah', 24, 44, 19, '“Moreover,” said the women, “when we burned incense to the Queen of Heaven and poured out drink offerings to her, was it without our husbands’ knowledge that we made sacrificial cakes in her image and poured out drink offerings to her?”'),
  ('BSB', 'Jeremiah', 24, 44, 20, 'Then Jeremiah said to all the people, both men and women, who were answering him,'),
  ('BSB', 'Jeremiah', 24, 44, 21, '“As for the incense you burned in the cities of Judah and in the streets of Jerusalem—you, your fathers, your kings, your officials, and the people of the land—did the LORD not remember and bring this to mind?'),
  ('BSB', 'Jeremiah', 24, 44, 22, 'So the LORD could no longer endure the evil deeds and detestable acts you committed, and your land became a desolation, a horror, and an object of cursing, without inhabitant, as it is this day.'),
  ('BSB', 'Jeremiah', 24, 44, 23, 'Because you burned incense and sinned against the LORD, and did not obey the voice of the LORD or walk in His instruction, His statutes, and His testimonies, this disaster has befallen you, as you see today.”'),
  ('BSB', 'Jeremiah', 24, 44, 24, 'Then Jeremiah said to all the people, including all the women, “Hear the word of the LORD, all those of Judah who are in the land of Egypt.'),
  ('BSB', 'Jeremiah', 24, 44, 25, 'This is what the LORD of Hosts, the God of Israel, says: As for you and your wives, you have spoken with your mouths and fulfilled with your hands your words: ‘We will surely perform our vows that we have made to burn incense to the Queen of Heaven and to pour out drink offerings to her.’ Go ahead, then, do what you have promised! Keep your vows!'),
  ('BSB', 'Jeremiah', 24, 44, 26, 'Nevertheless, hear the word of the LORD, all you people of Judah living in Egypt: Behold, I have sworn by My great name, says the LORD, that never again will any man of Judah living in the land of Egypt invoke My name or say, ‘As surely as the Lord GOD lives.’'),
  ('BSB', 'Jeremiah', 24, 44, 27, 'I am watching over them for harm and not for good, and every man of Judah who is in the land of Egypt will meet his end by sword or famine, until they are finished off.'),
  ('BSB', 'Jeremiah', 24, 44, 28, 'Those who escape the sword will return from Egypt to Judah, few in number, and the whole remnant of Judah who went to dwell in the land of Egypt will know whose word will stand, Mine or theirs!'),
  ('BSB', 'Jeremiah', 24, 44, 29, 'This will be a sign to you that I will punish you in this place, declares the LORD, so that you may know that My threats of harm against you will surely stand.'),
  ('BSB', 'Jeremiah', 24, 44, 30, 'This is what the LORD says: Behold, I will deliver Pharaoh Hophra king of Egypt into the hands of his enemies who seek his life, just as I delivered Zedekiah king of Judah into the hand of Nebuchadnezzar king of Babylon, the enemy who was seeking his life.”'),
  ('BSB', 'Jeremiah', 24, 45, 1, 'This is the word that Jeremiah the prophet spoke to Baruch son of Neriah when he wrote these words on a scroll at the dictation of Jeremiah in the fourth year of Jehoiakim son of Josiah, king of Judah:'),
  ('BSB', 'Jeremiah', 24, 45, 2, '“This is what the LORD, the God of Israel, says to you, Baruch:'),
  ('BSB', 'Jeremiah', 24, 45, 3, 'You have said, ‘Woe is me because the LORD has added sorrow to my pain! I am worn out with groaning and have found no rest.’”'),
  ('BSB', 'Jeremiah', 24, 45, 4, 'Thus Jeremiah was to say to Baruch: “This is what the LORD says: Throughout the land I will demolish what I have built and uproot what I have planted.'),
  ('BSB', 'Jeremiah', 24, 45, 5, 'But as for you, do you seek great things for yourself? Stop seeking! For I will bring disaster on every living creature, declares the LORD, but wherever you go, I will grant your life as a spoil of war.”'),
  ('BSB', 'Jeremiah', 24, 46, 1, 'This is the word of the LORD about the nations—the word that came to Jeremiah the prophet'),
  ('BSB', 'Jeremiah', 24, 46, 2, 'concerning Egypt and the army of Pharaoh Neco king of Egypt, which was defeated at Carchemish on the Euphrates River by Nebuchadnezzar king of Babylon in the fourth year of Jehoiakim the son of Josiah king of Judah:'),
  ('BSB', 'Jeremiah', 24, 46, 3, '“Deploy your shields, small and large; advance for battle!'),
  ('BSB', 'Jeremiah', 24, 46, 4, 'Harness the horses; mount the steeds; take your positions with helmets on! Polish your spears; put on armor!'),
  ('BSB', 'Jeremiah', 24, 46, 5, 'Why am I seeing this? They are terrified, they are retreating; their warriors are defeated, they flee in haste without looking back; terror is on every side!” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 46, 6, '“The swift cannot flee, and the warrior cannot escape! In the north by the River Euphrates they stumble and fall.'),
  ('BSB', 'Jeremiah', 24, 46, 7, 'Who is this, rising like the Nile, like rivers whose waters churn?'),
  ('BSB', 'Jeremiah', 24, 46, 8, 'Egypt rises like the Nile, and its waters churn like rivers, boasting, ‘I will rise and cover the earth; I will destroy the cities and their people.’'),
  ('BSB', 'Jeremiah', 24, 46, 9, 'Advance, O horses! Race furiously, O chariots! Let the warriors come forth— Cush and Put carrying their shields, men of Lydia drawing the bow.'),
  ('BSB', 'Jeremiah', 24, 46, 10, 'For that day belongs to the Lord GOD of Hosts, a day of vengeance against His foes. The sword will devour until it is satisfied, until it is quenched with their blood. For the Lord GOD of Hosts will hold a sacrifice in the land of the north by the River Euphrates.'),
  ('BSB', 'Jeremiah', 24, 46, 11, 'Go up to Gilead for balm, O Virgin Daughter of Egypt! In vain you try many remedies, but for you there is no healing.'),
  ('BSB', 'Jeremiah', 24, 46, 12, 'The nations have heard of your shame, and your outcry fills the earth, because warrior stumbles over warrior and both of them have fallen together.”'),
  ('BSB', 'Jeremiah', 24, 46, 13, 'This is the word that the LORD spoke to Jeremiah the prophet about the coming of Nebuchadnezzar king of Babylon to strike the land of Egypt:'),
  ('BSB', 'Jeremiah', 24, 46, 14, '“Announce it in Egypt, and proclaim it in Migdol; proclaim it in Memphis and Tahpanhes: ‘Take your positions and prepare yourself, for the sword devours those around you.’'),
  ('BSB', 'Jeremiah', 24, 46, 15, 'Why have your warriors been laid low? They cannot stand, for the LORD has thrust them down.'),
  ('BSB', 'Jeremiah', 24, 46, 16, 'They continue to stumble; indeed, they have fallen over one another. They say, ‘Get up! Let us return to our people and to the land of our birth, away from the sword of the oppressor.’'),
  ('BSB', 'Jeremiah', 24, 46, 17, 'There they will cry out: ‘Pharaoh king of Egypt was all noise; he has let the appointed time pass him by.’'),
  ('BSB', 'Jeremiah', 24, 46, 18, 'As surely as I live, declares the King, whose name is the LORD of Hosts, there will come one who is like Tabor among the mountains and like Carmel by the sea.'),
  ('BSB', 'Jeremiah', 24, 46, 19, 'Pack your bags for exile, O daughter dwelling in Egypt! For Memphis will be laid waste, destroyed and uninhabited.'),
  ('BSB', 'Jeremiah', 24, 46, 20, 'Egypt is a beautiful heifer, but a gadfly from the north is coming against her.'),
  ('BSB', 'Jeremiah', 24, 46, 21, 'Even the mercenaries among her are like fattened calves. They too will turn back; together they will flee, they will not stand their ground, for the day of calamity is coming upon them— the time of their punishment.'),
  ('BSB', 'Jeremiah', 24, 46, 22, 'Egypt will hiss like a fleeing serpent, for the enemy will advance in force; with axes they will come against her like woodsmen cutting down trees.'),
  ('BSB', 'Jeremiah', 24, 46, 23, 'They will chop down her forest, declares the LORD, dense though it may be, for they are more numerous than locusts; they cannot be counted.'),
  ('BSB', 'Jeremiah', 24, 46, 24, 'The Daughter of Egypt will be put to shame; she will be delivered into the hands of the people of the north.”'),
  ('BSB', 'Jeremiah', 24, 46, 25, 'The LORD of Hosts, the God of Israel, says: “Behold, I am about to punish Amon god of Thebes, along with Pharaoh, Egypt with her gods and kings, and those who trust in Pharaoh.'),
  ('BSB', 'Jeremiah', 24, 46, 26, 'I will deliver them into the hands of those who seek their lives—of Nebuchadnezzar king of Babylon and his officers. But after this, Egypt will be inhabited as in days of old, declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 46, 27, 'But you, O Jacob My servant, do not be afraid, and do not be dismayed, O Israel. For I will surely save you out of a distant place, your descendants from the land of their captivity! Jacob will return to quiet and ease, with no one to make him afraid.'),
  ('BSB', 'Jeremiah', 24, 46, 28, 'And you, My servant Jacob, do not be afraid, declares the LORD, for I am with you. Though I will completely destroy all the nations to which I have banished you, I will not completely destroy you. Yet I will discipline you justly, and will by no means leave you unpunished.”'),
  ('BSB', 'Jeremiah', 24, 47, 1, 'This is the word of the LORD that came to Jeremiah the prophet about the Philistines before Pharaoh struck down Gaza.'),
  ('BSB', 'Jeremiah', 24, 47, 2, 'This is what the LORD says: “See how the waters are rising from the north and becoming an overflowing torrent. They will overflow the land and its fullness, the cities and their inhabitants. The people will cry out, and all who dwell in the land will wail'),
  ('BSB', 'Jeremiah', 24, 47, 3, 'at the sound of the galloping hooves of stallions, the rumbling of chariots, and the clatter of their wheels. The fathers will not turn back for their sons; their hands will hang limp.'),
  ('BSB', 'Jeremiah', 24, 47, 4, 'For the day has come to destroy all the Philistines, to cut off from Tyre and Sidon every remaining ally. Indeed, the LORD is about to destroy the Philistines, the remnant from the coasts of Caphtor.'),
  ('BSB', 'Jeremiah', 24, 47, 5, 'The people of Gaza will shave their heads in mourning; Ashkelon will be silenced. O remnant of their valley, how long will you gash yourself?'),
  ('BSB', 'Jeremiah', 24, 47, 6, '‘Alas, O sword of the LORD, how long until you rest? Return to your sheath; cease and be still!’'),
  ('BSB', 'Jeremiah', 24, 47, 7, 'How can it rest when the LORD has commanded it? He has appointed it against Ashkelon and the shore of its coastland.”'),
  ('BSB', 'Jeremiah', 24, 48, 1, 'Concerning Moab, this is what the LORD of Hosts, the God of Israel, says: “Woe to Nebo, for it will be devastated. Kiriathaim will be captured and disgraced; the fortress will be shattered and dismantled.'),
  ('BSB', 'Jeremiah', 24, 48, 2, 'There is no longer praise for Moab; in Heshbon they devise evil against her: ‘Come, let us cut her off from nationhood.’ You too, O people of Madmen, will be silenced; the sword will pursue you.'),
  ('BSB', 'Jeremiah', 24, 48, 3, 'A voice cries out from Horonaim: ‘Devastation and great destruction!’'),
  ('BSB', 'Jeremiah', 24, 48, 4, 'Moab will be shattered; her little ones will cry out.'),
  ('BSB', 'Jeremiah', 24, 48, 5, 'For on the ascent to Luhith they weep bitterly as they go, and on the descent to Horonaim cries of distress resound over the destruction:'),
  ('BSB', 'Jeremiah', 24, 48, 6, '‘Flee! Run for your lives! Become like a juniper in the desert.’'),
  ('BSB', 'Jeremiah', 24, 48, 7, 'Because you trust in your works and treasures, you too will be captured, and Chemosh will go into exile with his priests and officials.'),
  ('BSB', 'Jeremiah', 24, 48, 8, 'The destroyer will move against every city, and not one town will escape. The valley will also be ruined, and the high plain will be destroyed, as the LORD has said.'),
  ('BSB', 'Jeremiah', 24, 48, 9, 'Put salt on Moab, for she will be laid waste; her cities will become desolate, with no one to dwell in them.'),
  ('BSB', 'Jeremiah', 24, 48, 10, 'Cursed is the one who is remiss in doing the work of the LORD, and cursed is he who withholds his sword from bloodshed.'),
  ('BSB', 'Jeremiah', 24, 48, 11, 'Moab has been at ease from youth, settled like wine on its dregs; he has not been poured from vessel to vessel or gone into exile. So his flavor has remained the same, and his aroma is unchanged.'),
  ('BSB', 'Jeremiah', 24, 48, 12, 'Therefore behold, the days are coming, declares the LORD, when I will send to him wanderers, who will pour him out. They will empty his vessels and shatter his jars.'),
  ('BSB', 'Jeremiah', 24, 48, 13, 'Then Moab will be ashamed of Chemosh, just as the house of Israel was ashamed when they trusted in Bethel.'),
  ('BSB', 'Jeremiah', 24, 48, 14, 'How can you say, ‘We are warriors, mighty men ready for battle’?'),
  ('BSB', 'Jeremiah', 24, 48, 15, 'Moab has been destroyed and its towns have been invaded; the best of its young men have gone down in the slaughter, declares the King, whose name is the LORD of Hosts.'),
  ('BSB', 'Jeremiah', 24, 48, 16, 'Moab’s calamity is at hand, and his affliction is rushing swiftly.'),
  ('BSB', 'Jeremiah', 24, 48, 17, 'Mourn for him, all you who surround him, everyone who knows his name; tell how the mighty scepter is shattered— the glorious staff!'),
  ('BSB', 'Jeremiah', 24, 48, 18, 'Come down from your glory; sit on parched ground, O daughter dwelling in Dibon, for the destroyer of Moab has come against you; he has destroyed your fortresses.'),
  ('BSB', 'Jeremiah', 24, 48, 19, 'Stand by the road and watch, O dweller of Aroer! Ask the man fleeing or the woman escaping, ‘What has happened?’'),
  ('BSB', 'Jeremiah', 24, 48, 20, 'Moab is put to shame, for it has been shattered. Wail and cry out! Declare by the Arnon that Moab is destroyed.'),
  ('BSB', 'Jeremiah', 24, 48, 21, 'Judgment has come upon the high plain— upon Holon, Jahzah, and Mephaath,'),
  ('BSB', 'Jeremiah', 24, 48, 22, 'upon Dibon, Nebo, and Beth-diblathaim,'),
  ('BSB', 'Jeremiah', 24, 48, 23, 'upon Kiriathaim, Beth-gamul, and Beth-meon,'),
  ('BSB', 'Jeremiah', 24, 48, 24, 'upon Kerioth, Bozrah, and all the towns of Moab, those far and near.'),
  ('BSB', 'Jeremiah', 24, 48, 25, 'The horn of Moab has been cut off, and his arm is broken,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 48, 26, '“Make him drunk, because he has magnified himself against the LORD; so Moab will wallow in his own vomit, and he will also become a laughingstock.'),
  ('BSB', 'Jeremiah', 24, 48, 27, 'Was not Israel your object of ridicule? Was he ever found among thieves? For whenever you speak of him you shake your head.'),
  ('BSB', 'Jeremiah', 24, 48, 28, 'Abandon the towns and settle among the rocks, O dwellers of Moab! Be like a dove that nests at the mouth of a cave.'),
  ('BSB', 'Jeremiah', 24, 48, 29, 'We have heard of Moab’s pomposity, his exceeding pride and conceit, his proud arrogance and haughtiness of heart.'),
  ('BSB', 'Jeremiah', 24, 48, 30, 'I know his insolence,” declares the LORD, “but it is futile. His boasting is as empty as his deeds.'),
  ('BSB', 'Jeremiah', 24, 48, 31, 'Therefore I will wail for Moab; I will cry out for all of Moab; I will moan for the men of Kir-heres.'),
  ('BSB', 'Jeremiah', 24, 48, 32, 'I will weep for you, O vine of Sibmah, more than I weep for Jazer. Your tendrils have extended to the sea; they reach even to Jazer. The destroyer has descended on your summer fruit and grape harvest.'),
  ('BSB', 'Jeremiah', 24, 48, 33, 'Joy and gladness are removed from the orchard and from the fields of Moab. I have stopped the flow of wine from the presses; no one treads them with shouts of joy; their shouts are not for joy.'),
  ('BSB', 'Jeremiah', 24, 48, 34, 'There is a cry from Heshbon to Elealeh; they raise their voices to Jahaz, from Zoar to Horonaim and Eglath-shelishiyah; for even the waters of Nimrim have dried up.'),
  ('BSB', 'Jeremiah', 24, 48, 35, 'In Moab, declares the LORD, I will bring an end to those who make offerings on the high places and burn incense to their gods.'),
  ('BSB', 'Jeremiah', 24, 48, 36, 'Therefore My heart laments like a flute for Moab; it laments like a flute for the men of Kir-heres, because the wealth they acquired has perished.'),
  ('BSB', 'Jeremiah', 24, 48, 37, 'For every head is shaved and every beard is clipped; on every hand is a gash, and around every waist is sackcloth.'),
  ('BSB', 'Jeremiah', 24, 48, 38, 'On all the rooftops of Moab and in the public squares, everyone is mourning; for I have shattered Moab like an unwanted jar,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 48, 39, '“How shattered it is! How they wail! How Moab has turned his back in shame! Moab has become an object of ridicule and horror to all those around him.”'),
  ('BSB', 'Jeremiah', 24, 48, 40, 'For this is what the LORD says: “Behold, an eagle swoops down and spreads his wings against Moab.'),
  ('BSB', 'Jeremiah', 24, 48, 41, 'Kirioth has been taken, and the strongholds seized. In that day the heart of Moab’s warriors will be like the heart of a woman in labor.'),
  ('BSB', 'Jeremiah', 24, 48, 42, 'Moab will be destroyed as a nation because he vaunted himself against the LORD.'),
  ('BSB', 'Jeremiah', 24, 48, 43, 'Terror and pit and snare await you, O dweller of Moab,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 48, 44, '“Whoever flees the panic will fall into the pit, and whoever climbs from the pit will be caught in the snare. For I will bring upon Moab the year of their punishment,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 48, 45, '“Those who flee will stand helpless in Heshbon’s shadow, because fire has gone forth from Heshbon and a flame from within Sihon. It devours the foreheads of Moab and the skulls of the sons of tumult.'),
  ('BSB', 'Jeremiah', 24, 48, 46, 'Woe to you, O Moab! The people of Chemosh have perished; for your sons have been taken into exile and your daughters have gone into captivity.'),
  ('BSB', 'Jeremiah', 24, 48, 47, 'Yet in the latter days I will restore Moab from captivity,” declares the LORD. Here ends the judgment on Moab.'),
  ('BSB', 'Jeremiah', 24, 49, 1, 'Concerning the Ammonites, this is what the LORD says: “Has Israel no sons? Is he without heir? Why then has Milcom taken possession of Gad? Why have his people settled in their cities?'),
  ('BSB', 'Jeremiah', 24, 49, 2, 'Therefore, behold, the days are coming, declares the LORD, when I will sound the battle cry against Rabbah of the Ammonites. It will become a heap of ruins, and its villages will be burned. Then Israel will drive out their dispossessors, says the LORD.'),
  ('BSB', 'Jeremiah', 24, 49, 3, 'Wail, O Heshbon, for Ai has been destroyed; cry out, O daughters of Rabbah! Put on sackcloth and mourn; run back and forth within your walls, for Milcom will go into exile together with his priests and officials.'),
  ('BSB', 'Jeremiah', 24, 49, 4, 'Why do you boast of your valleys— your valleys so fruitful, O faithless daughter? You trust in your riches and say, ‘Who can come against me?’'),
  ('BSB', 'Jeremiah', 24, 49, 5, 'Behold, I am about to bring terror upon you, declares the Lord GOD of Hosts, from all those around you. You will each be driven headlong, with no one to regather the fugitives.'),
  ('BSB', 'Jeremiah', 24, 49, 6, 'Yet afterward I will restore the Ammonites from captivity,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 49, 7, 'Concerning Edom, this is what the LORD of Hosts says: “Is there no longer wisdom in Teman? Has counsel perished from the prudent? Has their wisdom decayed?'),
  ('BSB', 'Jeremiah', 24, 49, 8, 'Turn and run! Lie low, O dwellers of Dedan, for I will bring disaster on Esau at the time I punish him.'),
  ('BSB', 'Jeremiah', 24, 49, 9, 'If grape gatherers came to you, would they not leave some gleanings? Were thieves to come in the night, would they not steal only what they wanted?'),
  ('BSB', 'Jeremiah', 24, 49, 10, 'But I will strip Esau bare; I will uncover his hiding places, and he will be unable to conceal himself. His descendants will be destroyed along with his relatives and neighbors, and he will be no more.'),
  ('BSB', 'Jeremiah', 24, 49, 11, 'Abandon your orphans; I will preserve their lives. Let your widows trust in Me.”'),
  ('BSB', 'Jeremiah', 24, 49, 12, 'For this is what the LORD says: “If those who do not deserve to drink the cup must drink it, can you possibly remain unpunished? You will not go unpunished, for you must drink it too.'),
  ('BSB', 'Jeremiah', 24, 49, 13, 'For by Myself I have sworn, declares the LORD, that Bozrah will become a desolation, a disgrace, a ruin, and a curse, and all her cities will be in ruins forever.”'),
  ('BSB', 'Jeremiah', 24, 49, 14, 'I have heard a message from the LORD; an envoy has been sent to the nations: “Assemble yourselves to march against her! Rise up for battle!”'),
  ('BSB', 'Jeremiah', 24, 49, 15, '“For behold, I will make you small among nations, despised among men.'),
  ('BSB', 'Jeremiah', 24, 49, 16, 'The terror you cause and the pride of your heart have deceived you, O dwellers in the clefts of the rocks, O occupiers of the mountain summit. Though you elevate your nest like the eagle, even from there I will bring you down,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 49, 17, '“Edom will become an object of horror. All who pass by will be appalled and will scoff at all her wounds.'),
  ('BSB', 'Jeremiah', 24, 49, 18, 'As Sodom and Gomorrah were overthrown along with their neighbors,” says the LORD, “no one will dwell there; no man will abide there.'),
  ('BSB', 'Jeremiah', 24, 49, 19, 'Behold, one will come up like a lion from the thickets of the Jordan to the watered pasture. For in an instant I will chase Edom from her land. Who is the chosen one I will appoint for this? For who is like Me, and who can challenge Me? What shepherd can stand against Me?”'),
  ('BSB', 'Jeremiah', 24, 49, 20, 'Therefore hear the plans that the LORD has drawn up against Edom and the strategies He has devised against the people of Teman: Surely the little ones of the flock will be dragged away; certainly their pasture will be made desolate because of them.'),
  ('BSB', 'Jeremiah', 24, 49, 21, 'At the sound of their fall the earth will quake; their cry will resound to the Red Sea.'),
  ('BSB', 'Jeremiah', 24, 49, 22, 'Look! An eagle will soar and swoop down, spreading its wings over Bozrah. In that day the hearts of Edom’s mighty men will be like the heart of a woman in labor.'),
  ('BSB', 'Jeremiah', 24, 49, 23, 'Concerning Damascus: “Hamath and Arpad are put to shame, for they have heard a bad report; they are agitated like the sea; their anxiety cannot be calmed.'),
  ('BSB', 'Jeremiah', 24, 49, 24, 'Damascus has become feeble; she has turned to flee. Panic has gripped her; anguish and pain have seized her like a woman in labor.'),
  ('BSB', 'Jeremiah', 24, 49, 25, 'How is the city of praise not forsaken, the town that brings Me joy?'),
  ('BSB', 'Jeremiah', 24, 49, 26, 'For her young men will fall in the streets, and all her warriors will be silenced in that day,” declares the LORD of Hosts.'),
  ('BSB', 'Jeremiah', 24, 49, 27, '“I will set fire to the walls of Damascus; it will consume the fortresses of Ben-hadad.”'),
  ('BSB', 'Jeremiah', 24, 49, 28, 'Concerning Kedar and the kingdoms of Hazor, which Nebuchadnezzar king of Babylon defeated, this is what the LORD says: “Rise up, advance against Kedar, and destroy the people of the east!'),
  ('BSB', 'Jeremiah', 24, 49, 29, 'They will take their tents and flocks, their tent curtains and all their goods. They will take their camels for themselves. They will shout to them: ‘Terror is on every side!’'),
  ('BSB', 'Jeremiah', 24, 49, 30, 'Run! Escape quickly! Lie low, O residents of Hazor,” declares the LORD, “for Nebuchadnezzar king of Babylon has drawn up a plan against you; he has devised a strategy against you.'),
  ('BSB', 'Jeremiah', 24, 49, 31, 'Rise up, advance against a nation at ease, one that dwells securely,” declares the LORD. “They have no gates or bars; they live alone.'),
  ('BSB', 'Jeremiah', 24, 49, 32, 'Their camels will become plunder, and their large herds will be spoil. I will scatter to the wind in every direction those who shave their temples; I will bring calamity on them from all sides,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 49, 33, '“Hazor will become a haunt for jackals, a desolation forever. No one will dwell there; no man will abide there.”'),
  ('BSB', 'Jeremiah', 24, 49, 34, 'This is the word of the LORD that came to Jeremiah the prophet concerning Elam at the beginning of the reign of Zedekiah king of Judah.'),
  ('BSB', 'Jeremiah', 24, 49, 35, 'This is what the LORD of Hosts says: “Behold, I will shatter Elam’s bow, the mainstay of their might.'),
  ('BSB', 'Jeremiah', 24, 49, 36, 'I will bring the four winds against Elam from the four corners of the heavens, and I will scatter them to all these winds. There will not be a nation to which Elam’s exiles will not go.'),
  ('BSB', 'Jeremiah', 24, 49, 37, 'So I will shatter Elam before their foes, before those who seek their lives. I will bring disaster upon them, even My fierce anger,” declares the LORD. “I will send out the sword after them until I finish them off.'),
  ('BSB', 'Jeremiah', 24, 49, 38, 'I will set My throne in Elam, and destroy its king and officials,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 49, 39, '“Yet in the last days, I will restore Elam from captivity,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 50, 1, 'This is the word that the LORD spoke through Jeremiah the prophet concerning Babylon and the land of the Chaldeans:'),
  ('BSB', 'Jeremiah', 24, 50, 2, '“Announce and declare to the nations; lift up a banner and proclaim it; hold nothing back when you say, ‘Babylon is captured; Bel is put to shame; Marduk is shattered, her images are disgraced, her idols are broken in pieces.’'),
  ('BSB', 'Jeremiah', 24, 50, 3, 'For a nation from the north will come against her; it will make her land a desolation. No one will live in it; both man and beast will flee.”'),
  ('BSB', 'Jeremiah', 24, 50, 4, '“In those days and at that time, declares the LORD, the children of Israel and the children of Judah will come together, weeping as they come, and will seek the LORD their God.'),
  ('BSB', 'Jeremiah', 24, 50, 5, 'They will ask the way to Zion and turn their faces toward it. They will come and join themselves to the LORD in an everlasting covenant that will never be forgotten.'),
  ('BSB', 'Jeremiah', 24, 50, 6, 'My people are lost sheep; their shepherds have led them astray, causing them to roam the mountains. They have wandered from mountain to hill; they have forgotten their resting place.'),
  ('BSB', 'Jeremiah', 24, 50, 7, 'All who found them devoured them, and their enemies said, ‘We are not guilty, for they have sinned against the LORD, their true pasture, the LORD, the hope of their fathers.’'),
  ('BSB', 'Jeremiah', 24, 50, 8, 'Flee from the midst of Babylon; depart from the land of the Chaldeans; be like the he-goats that lead the flock.'),
  ('BSB', 'Jeremiah', 24, 50, 9, 'For behold, I stir up and bring against Babylon an assembly of great nations from the land of the north. They will line up against her; from the north she will be captured. Their arrows will be like skilled warriors who do not return empty-handed.'),
  ('BSB', 'Jeremiah', 24, 50, 10, 'Chaldea will be plundered; all who plunder her will have their fill,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 50, 11, '“Because you rejoice, because you sing in triumph— you who plunder My inheritance— because you frolic like a heifer treading grain and neigh like stallions,'),
  ('BSB', 'Jeremiah', 24, 50, 12, 'your mother will be greatly ashamed; she who bore you will be disgraced. Behold, she will be the least of the nations, a wilderness, a dry land, and a desert.'),
  ('BSB', 'Jeremiah', 24, 50, 13, 'Because of the wrath of the LORD, she will not be inhabited; she will become completely desolate. All who pass through Babylon will be horrified and will hiss at all her wounds.'),
  ('BSB', 'Jeremiah', 24, 50, 14, 'Line up in formation around Babylon, all you who draw the bow! Shoot at her! Spare no arrows! For she has sinned against the LORD.'),
  ('BSB', 'Jeremiah', 24, 50, 15, 'Raise a war cry against her on every side! She has thrown up her hands in surrender; her towers have fallen; her walls are torn down. Since this is the vengeance of the LORD, take out your vengeance upon her; as she has done, do the same to her.'),
  ('BSB', 'Jeremiah', 24, 50, 16, 'Cut off the sower from Babylon, and the one who wields the sickle at harvest time. In the face of the oppressor’s sword, each will turn to his own people, each will flee to his own land.'),
  ('BSB', 'Jeremiah', 24, 50, 17, 'Israel is a scattered flock, chased away by lions. The first to devour him was the king of Assyria; the last to crush his bones was Nebuchadnezzar king of Babylon.”'),
  ('BSB', 'Jeremiah', 24, 50, 18, 'Therefore this is what the LORD of Hosts, the God of Israel, says: “I will punish the king of Babylon and his land as I punished the king of Assyria.'),
  ('BSB', 'Jeremiah', 24, 50, 19, 'I will return Israel to his pasture, and he will graze on Carmel and Bashan; his soul will be satisfied on the hills of Ephraim and Gilead.'),
  ('BSB', 'Jeremiah', 24, 50, 20, 'In those days and at that time, declares the LORD, a search will be made for Israel’s guilt, but there will be none, and for Judah’s sins, but they will not be found; for I will forgive the remnant I preserve.'),
  ('BSB', 'Jeremiah', 24, 50, 21, 'Go up against the land of Merathaim, and against the residents of Pekod. Kill them and devote them to destruction. Do all that I have commanded you,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 50, 22, '“The noise of battle is in the land— the noise of great destruction.'),
  ('BSB', 'Jeremiah', 24, 50, 23, 'How the hammer of the whole earth lies broken and shattered! What a horror Babylon has become among the nations!'),
  ('BSB', 'Jeremiah', 24, 50, 24, 'I laid a snare for you, O Babylon, and you were caught before you knew it. You were found and captured because you challenged the LORD.'),
  ('BSB', 'Jeremiah', 24, 50, 25, 'The LORD has opened His armory and brought out His weapons of wrath, for this is the work of the Lord GOD of Hosts in the land of the Chaldeans.'),
  ('BSB', 'Jeremiah', 24, 50, 26, 'Come against her from the farthest border. Break open her granaries; pile her up like mounds of grain. Devote her to destruction; leave her no survivors.'),
  ('BSB', 'Jeremiah', 24, 50, 27, 'Kill all her young bulls; let them go down to the slaughter. Woe to them, for their day has come— the time of their punishment.'),
  ('BSB', 'Jeremiah', 24, 50, 28, 'Listen to the fugitives and refugees from the land of Babylon, declaring in Zion the vengeance of the LORD our God, the vengeance for His temple.'),
  ('BSB', 'Jeremiah', 24, 50, 29, 'Summon the archers against Babylon, all who string the bow. Encamp all around her; let no one escape. Repay her according to her deeds; do to her as she has done. For she has defied the LORD, the Holy One of Israel.'),
  ('BSB', 'Jeremiah', 24, 50, 30, 'Therefore, her young men will fall in the streets, and all her warriors will be silenced in that day,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 50, 31, '“Behold, I am against you, O arrogant one,” declares the Lord GOD of Hosts, “for your day has come, the time when I will punish you.'),
  ('BSB', 'Jeremiah', 24, 50, 32, 'The arrogant one will stumble and fall with no one to pick him up. And I will kindle a fire in his cities to consume all those around him.”'),
  ('BSB', 'Jeremiah', 24, 50, 33, 'This is what the LORD of Hosts says: “The sons of Israel are oppressed, and the sons of Judah as well. All their captors hold them fast, refusing to release them.'),
  ('BSB', 'Jeremiah', 24, 50, 34, 'Their Redeemer is strong; the LORD of Hosts is His name. He will fervently plead their case so that He may bring rest to the earth, but turmoil to those who live in Babylon.'),
  ('BSB', 'Jeremiah', 24, 50, 35, 'A sword is against the Chaldeans, declares the LORD, against those who live in Babylon, and against her officials and wise men.'),
  ('BSB', 'Jeremiah', 24, 50, 36, 'A sword is against her false prophets, and they will become fools. A sword is against her warriors, and they will be filled with terror.'),
  ('BSB', 'Jeremiah', 24, 50, 37, 'A sword is against her horses and chariots and against all the foreigners in her midst, and they will become like women. A sword is against her treasuries, and they will be plundered.'),
  ('BSB', 'Jeremiah', 24, 50, 38, 'A drought is upon her waters, and they will be dried up. For it is a land of graven images, and the people go mad over idols.'),
  ('BSB', 'Jeremiah', 24, 50, 39, 'So the desert creatures and hyenas will live there and ostriches will dwell there. It will never again be inhabited or lived in from generation to generation.'),
  ('BSB', 'Jeremiah', 24, 50, 40, 'As God overthrew Sodom and Gomorrah along with their neighbors,” declares the LORD, “no one will dwell there; no man will abide there.'),
  ('BSB', 'Jeremiah', 24, 50, 41, 'Behold, an army is coming from the north; a great nation and many kings are stirred up from the ends of the earth.'),
  ('BSB', 'Jeremiah', 24, 50, 42, 'They grasp the bow and spear; they are cruel and merciless. Their voice roars like the sea, and they ride upon horses, lined up like men in formation against you, O Daughter of Babylon.'),
  ('BSB', 'Jeremiah', 24, 50, 43, 'The king of Babylon has heard the report, and his hands hang limp. Anguish has gripped him, pain like that of a woman in labor.'),
  ('BSB', 'Jeremiah', 24, 50, 44, 'Behold, one will come up like a lion from the thickets of the Jordan to the watered pasture. For in an instant I will chase Babylon from her land. Who is the chosen one I will appoint for this? For who is like Me, and who can challenge Me? What shepherd can stand against Me?”'),
  ('BSB', 'Jeremiah', 24, 50, 45, 'Therefore hear the plans that the LORD has drawn up against Babylon and the strategies He has devised against the land of the Chaldeans: Surely the little ones of the flock will be dragged away; certainly their pasture will be made desolate because of them.'),
  ('BSB', 'Jeremiah', 24, 50, 46, 'At the sound of Babylon’s capture the earth will quake; a cry will be heard among the nations.'),
  ('BSB', 'Jeremiah', 24, 51, 1, 'This is what the LORD says: “Behold, I will stir up against Babylon and against the people of Leb-kamai the spirit of a destroyer.'),
  ('BSB', 'Jeremiah', 24, 51, 2, 'I will send strangers to Babylon to winnow her and empty her land; for they will come against her from every side in her day of disaster.'),
  ('BSB', 'Jeremiah', 24, 51, 3, 'Do not let the archer bend his bow or put on his armor. Do not spare her young men; devote all her army to destruction!'),
  ('BSB', 'Jeremiah', 24, 51, 4, 'And they will fall slain in the land of the Chaldeans, and pierced through in her streets.'),
  ('BSB', 'Jeremiah', 24, 51, 5, 'For Israel and Judah have not been abandoned by their God, the LORD of Hosts, though their land is full of guilt before the Holy One of Israel.”'),
  ('BSB', 'Jeremiah', 24, 51, 6, 'Flee from Babylon! Escape with your lives! Do not be destroyed in her punishment. For this is the time of the LORD’s vengeance; He will pay her what she deserves.'),
  ('BSB', 'Jeremiah', 24, 51, 7, 'Babylon was a gold cup in the hand of the LORD, making the whole earth drunk. The nations drank her wine; therefore the nations have gone mad.'),
  ('BSB', 'Jeremiah', 24, 51, 8, 'Suddenly Babylon has fallen and been shattered. Wail for her; get her balm for her pain; perhaps she can be healed.'),
  ('BSB', 'Jeremiah', 24, 51, 9, '“We tried to heal Babylon, but she could not be healed. Abandon her! Let each of us go to his own land, for her judgment extends to the sky and reaches to the clouds.”'),
  ('BSB', 'Jeremiah', 24, 51, 10, '“The LORD has brought forth our vindication; come, let us tell in Zion what the LORD our God has accomplished.”'),
  ('BSB', 'Jeremiah', 24, 51, 11, 'Sharpen the arrows! Fill the quivers! The LORD has aroused the spirit of the kings of the Medes, because His plan is aimed at Babylon to destroy her, for it is the vengeance of the LORD— vengeance for His temple.'),
  ('BSB', 'Jeremiah', 24, 51, 12, 'Raise a banner against the walls of Babylon; post the guard; station the watchmen; prepare the ambush. For the LORD has both devised and accomplished what He spoke against the people of Babylon.'),
  ('BSB', 'Jeremiah', 24, 51, 13, 'You who dwell by many waters, rich in treasures, your end has come; the thread of your life is cut.'),
  ('BSB', 'Jeremiah', 24, 51, 14, 'The LORD of Hosts has sworn by Himself: “Surely I will fill you up with men as with locusts, and they will shout in triumph over you.”'),
  ('BSB', 'Jeremiah', 24, 51, 15, 'The LORD made the earth by His power; He established the world by His wisdom and stretched out the heavens by His understanding.'),
  ('BSB', 'Jeremiah', 24, 51, 16, 'When He thunders, the waters in the heavens roar; He causes the clouds to rise from the ends of the earth. He generates the lightning with the rain and brings forth the wind from His storehouses.'),
  ('BSB', 'Jeremiah', 24, 51, 17, 'Every man is senseless and devoid of knowledge; every goldsmith is put to shame by his idols. For his molten images are a fraud, and there is no breath in them.'),
  ('BSB', 'Jeremiah', 24, 51, 18, 'They are worthless, a work to be mocked. In the time of their punishment they will perish.'),
  ('BSB', 'Jeremiah', 24, 51, 19, 'The Portion of Jacob is not like these, for He is the Maker of all things, and of the tribe of His inheritance— the LORD of Hosts is His name.'),
  ('BSB', 'Jeremiah', 24, 51, 20, '“You are My war club, My weapon for battle. With you I shatter nations; with you I bring kingdoms to ruin.'),
  ('BSB', 'Jeremiah', 24, 51, 21, 'With you I shatter the horse and rider; with you I shatter the chariot and driver.'),
  ('BSB', 'Jeremiah', 24, 51, 22, 'With you I shatter man and woman; with you I shatter the old man and the youth; with you I shatter the young man and the maiden.'),
  ('BSB', 'Jeremiah', 24, 51, 23, 'With you I shatter the shepherd and his flock; with you I shatter the farmer and his oxen; with you I shatter the governors and officials.'),
  ('BSB', 'Jeremiah', 24, 51, 24, 'Before your very eyes I will repay Babylon and all the dwellers of Chaldea for all the evil they have done in Zion,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 51, 25, '“Behold, I am against you, O destroying mountain, you who devastate the whole earth, declares the LORD. I will stretch out My hand against you; I will roll you over the cliffs and turn you into a charred mountain.'),
  ('BSB', 'Jeremiah', 24, 51, 26, 'No one shall retrieve from you a cornerstone or a foundation stone, because you will become desolate forever,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 51, 27, '“Raise a banner in the land! Blow the ram’s horn among the nations! Prepare the nations against her. Summon the kingdoms against her— Ararat, Minni, and Ashkenaz. Appoint a captain against her; bring up horses like swarming locusts.'),
  ('BSB', 'Jeremiah', 24, 51, 28, 'Prepare the nations for battle against her— the kings of the Medes, their governors and all their officials, and all the lands they rule.'),
  ('BSB', 'Jeremiah', 24, 51, 29, 'The earth quakes and writhes because the LORD’s intentions against Babylon stand: to make the land of Babylon a desolation, without inhabitant.'),
  ('BSB', 'Jeremiah', 24, 51, 30, 'The warriors of Babylon have stopped fighting; they sit in their strongholds. Their strength is exhausted; they have become like women. Babylon’s homes have been set ablaze, the bars of her gates are broken.'),
  ('BSB', 'Jeremiah', 24, 51, 31, 'One courier races to meet another, and messenger follows messenger, to announce to the king of Babylon that his city has been captured from end to end.'),
  ('BSB', 'Jeremiah', 24, 51, 32, 'The fords have been seized, the marshes set on fire, and the soldiers are terrified.”'),
  ('BSB', 'Jeremiah', 24, 51, 33, 'For this is what the LORD of Hosts, the God of Israel, says: “The Daughter of Babylon is like a threshing floor at the time it is trampled. In just a little while her harvest time will come.”'),
  ('BSB', 'Jeremiah', 24, 51, 34, '“Nebuchadnezzar king of Babylon has devoured me; he has crushed me. He has set me aside like an empty vessel; he has swallowed me like a monster; he filled his belly with my delicacies and vomited me out.'),
  ('BSB', 'Jeremiah', 24, 51, 35, 'May the violence done to me and to my flesh be upon Babylon,” says the dweller of Zion. “May my blood be on the dwellers of Chaldea,” says Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 51, 36, 'Therefore this is what the LORD says: “Behold, I will plead your case and take vengeance on your behalf; I will dry up her sea and make her springs run dry.'),
  ('BSB', 'Jeremiah', 24, 51, 37, 'Babylon will become a heap of rubble, a haunt for jackals, an object of horror and scorn, without inhabitant.'),
  ('BSB', 'Jeremiah', 24, 51, 38, 'They will roar together like young lions; they will growl like lion cubs.'),
  ('BSB', 'Jeremiah', 24, 51, 39, 'While they are flushed with heat, I will serve them a feast, and I will make them drunk so that they may revel; then they will fall asleep forever and never wake up, declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 51, 40, 'I will bring them down like lambs to the slaughter, like rams with male goats.'),
  ('BSB', 'Jeremiah', 24, 51, 41, 'How Sheshach has been captured! The praise of all the earth has been seized. What a horror Babylon has become among the nations!'),
  ('BSB', 'Jeremiah', 24, 51, 42, 'The sea has come up over Babylon; she is covered in turbulent waves.'),
  ('BSB', 'Jeremiah', 24, 51, 43, 'Her cities have become a desolation, a dry and arid land, a land where no one lives, where no son of man passes through.'),
  ('BSB', 'Jeremiah', 24, 51, 44, 'I will punish Bel in Babylon. I will make him spew out what he swallowed. The nations will no longer stream to him; even the wall of Babylon will fall.'),
  ('BSB', 'Jeremiah', 24, 51, 45, 'Come out of her, My people! Save your lives, each of you, from the fierce anger of the LORD.'),
  ('BSB', 'Jeremiah', 24, 51, 46, 'Do not let your heart grow faint, and do not be afraid when the rumor is heard in the land; for a rumor will come one year— and then another the next year— of violence in the land and of ruler against ruler.'),
  ('BSB', 'Jeremiah', 24, 51, 47, 'Therefore, behold, the days are coming when I will punish the idols of Babylon. Her entire land will suffer shame, and all her slain will lie fallen within her.'),
  ('BSB', 'Jeremiah', 24, 51, 48, 'Then heaven and earth and all that is in them will shout for joy over Babylon because the destroyers from the north will come against her,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 51, 49, '“Babylon must fall on account of the slain of Israel, just as the slain of all the earth have fallen because of Babylon.'),
  ('BSB', 'Jeremiah', 24, 51, 50, 'You who have escaped the sword, depart and do not linger! Remember the LORD from far away, and let Jerusalem come to mind.”'),
  ('BSB', 'Jeremiah', 24, 51, 51, '“We are ashamed because we have heard reproach; disgrace has covered our faces, because foreigners have entered the holy places of the LORD’s house.”'),
  ('BSB', 'Jeremiah', 24, 51, 52, '“Therefore, behold, the days are coming,” declares the LORD, “when I will punish her idols, and throughout her land the wounded will groan.'),
  ('BSB', 'Jeremiah', 24, 51, 53, 'Even if Babylon ascends to the heavens and fortifies her lofty stronghold, the destroyers I send will come against her,” declares the LORD.'),
  ('BSB', 'Jeremiah', 24, 51, 54, '“The sound of a cry comes from Babylon, the sound of great destruction from the land of the Chaldeans!'),
  ('BSB', 'Jeremiah', 24, 51, 55, 'For the LORD will destroy Babylon; He will silence her mighty voice. The waves will roar like great waters; the tumult of their voices will resound.'),
  ('BSB', 'Jeremiah', 24, 51, 56, 'For a destroyer is coming against her— against Babylon. Her warriors will be captured, and their bows will be broken, for the LORD is a God of retribution; He will repay in full.'),
  ('BSB', 'Jeremiah', 24, 51, 57, 'I will make her princes and wise men drunk, along with her governors, officials, and warriors. Then they will fall asleep forever and not wake up,” declares the King, whose name is the LORD of Hosts.'),
  ('BSB', 'Jeremiah', 24, 51, 58, 'This is what the LORD of Hosts says: “Babylon’s thick walls will be leveled, and her high gates consumed by fire. So the labor of the people will be for nothing; the nations will exhaust themselves to fuel the flames.”'),
  ('BSB', 'Jeremiah', 24, 51, 59, 'This is the message that Jeremiah the prophet gave to the quartermaster Seraiah son of Neriah, the son of Mahseiah, when he went to Babylon with King Zedekiah of Judah in the fourth year of Zedekiah’s reign.'),
  ('BSB', 'Jeremiah', 24, 51, 60, 'Jeremiah had written on a single scroll about all the disaster that would come upon Babylon—all these words that had been written concerning Babylon.'),
  ('BSB', 'Jeremiah', 24, 51, 61, 'And Jeremiah said to Seraiah, “When you get to Babylon, see that you read all these words aloud,'),
  ('BSB', 'Jeremiah', 24, 51, 62, 'and say, ‘O LORD, You have promised to cut off this place so that no one will remain—neither man nor beast. Indeed, it will be desolate forever.’'),
  ('BSB', 'Jeremiah', 24, 51, 63, 'When you finish reading this scroll, tie a stone to it and cast it into the Euphrates.'),
  ('BSB', 'Jeremiah', 24, 51, 64, 'Then you are to say, ‘In the same way Babylon will sink and never rise again, because of the disaster I will bring upon her. And her people will grow weary.’” Here end the words of Jeremiah.'),
  ('BSB', 'Jeremiah', 24, 52, 1, 'Zedekiah was twenty-one years old when he became king, and he reigned in Jerusalem eleven years. His mother’s name was Hamutal daughter of Jeremiah; she was from Libnah.'),
  ('BSB', 'Jeremiah', 24, 52, 2, 'And Zedekiah did evil in the sight of the LORD, just as Jehoiakim had done.'),
  ('BSB', 'Jeremiah', 24, 52, 3, 'For because of the anger of the LORD, all this happened in Jerusalem and Judah, until He finally banished them from His presence. And Zedekiah also rebelled against the king of Babylon.'),
  ('BSB', 'Jeremiah', 24, 52, 4, 'So in the ninth year of Zedekiah’s reign, on the tenth day of the tenth month, Nebuchadnezzar king of Babylon marched against Jerusalem with his entire army. They encamped outside the city and built a siege wall all around it.'),
  ('BSB', 'Jeremiah', 24, 52, 5, 'And the city was kept under siege until King Zedekiah’s eleventh year.'),
  ('BSB', 'Jeremiah', 24, 52, 6, 'By the ninth day of the fourth month, the famine in the city was so severe that the people of the land had no food.'),
  ('BSB', 'Jeremiah', 24, 52, 7, 'Then the city was breached; and though the Chaldeans had surrounded the city, all the men of war fled the city by night by way of the gate between the two walls near the king’s garden. They headed toward the Arabah,'),
  ('BSB', 'Jeremiah', 24, 52, 8, 'but the army of the Chaldeans pursued the king and overtook Zedekiah in the plains of Jericho, and all his army was separated from him.'),
  ('BSB', 'Jeremiah', 24, 52, 9, 'The Chaldeans seized the king and brought him up to the king of Babylon at Riblah in the land of Hamath, where he pronounced judgment on Zedekiah.'),
  ('BSB', 'Jeremiah', 24, 52, 10, 'There at Riblah the king of Babylon slaughtered the sons of Zedekiah before his eyes, and he also killed all the officials of Judah.'),
  ('BSB', 'Jeremiah', 24, 52, 11, 'Then he put out Zedekiah’s eyes, bound him with bronze shackles, and took him to Babylon, where he kept him in custody until his dying day.'),
  ('BSB', 'Jeremiah', 24, 52, 12, 'On the tenth day of the fifth month, in the nineteenth year of Nebuchadnezzar’s reign over Babylon, Nebuzaradan captain of the guard, a servant of the king of Babylon, entered Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 52, 13, 'He burned down the house of the LORD, the royal palace, and all the houses of Jerusalem—every significant building.'),
  ('BSB', 'Jeremiah', 24, 52, 14, 'And the whole army of the Chaldeans under the captain of the guard broke down all the walls around Jerusalem.'),
  ('BSB', 'Jeremiah', 24, 52, 15, 'Then Nebuzaradan captain of the guard carried into exile some of the poorest people and those who remained in the city, along with the deserters who had defected to the king of Babylon and the rest of the craftsmen.'),
  ('BSB', 'Jeremiah', 24, 52, 16, 'But Nebuzaradan captain of the guard left behind some of the poorest of the land to tend the vineyards and fields.'),
  ('BSB', 'Jeremiah', 24, 52, 17, 'Moreover, the Chaldeans broke up the bronze pillars and stands and the bronze Sea in the house of the LORD, and they carried all the bronze to Babylon.'),
  ('BSB', 'Jeremiah', 24, 52, 18, 'They also took away the pots, shovels, wick trimmers, sprinkling bowls, dishes, and all the articles of bronze used in the temple service.'),
  ('BSB', 'Jeremiah', 24, 52, 19, 'The captain of the guard also took away the basins, censers, sprinkling bowls, pots, lampstands, pans, and drink offering bowls—anything made of pure gold or fine silver.'),
  ('BSB', 'Jeremiah', 24, 52, 20, 'As for the two pillars, the Sea, the twelve bronze bulls under it, and the movable stands that King Solomon had made for the house of the LORD, the weight of the bronze from all these articles was beyond measure.'),
  ('BSB', 'Jeremiah', 24, 52, 21, 'Each pillar was eighteen cubits tall and twelve cubits in circumference; each was hollow, four fingers thick.'),
  ('BSB', 'Jeremiah', 24, 52, 22, 'The bronze capital atop one pillar was five cubits high, with a network of bronze pomegranates all around. The second pillar, with its pomegranates, was similar.'),
  ('BSB', 'Jeremiah', 24, 52, 23, 'Each capital had ninety-six pomegranates on the sides, and a total of a hundred pomegranates were above the surrounding network.'),
  ('BSB', 'Jeremiah', 24, 52, 24, 'The captain of the guard also took away Seraiah the chief priest, Zephaniah the priest of second rank, and the three doorkeepers.'),
  ('BSB', 'Jeremiah', 24, 52, 25, 'Of those still in the city, he took a court official who had been appointed over the men of war, as well as seven trusted royal advisers. He also took the scribe of the captain of the army, who had enlisted the people of the land, and sixty men who were found in the city.'),
  ('BSB', 'Jeremiah', 24, 52, 26, 'Nebuzaradan captain of the guard took them and brought them to the king of Babylon at Riblah.'),
  ('BSB', 'Jeremiah', 24, 52, 27, 'There at Riblah in the land of Hamath, the king of Babylon struck them down and put them to death. So Judah was taken into exile, away from its own land.'),
  ('BSB', 'Jeremiah', 24, 52, 28, 'These are the people Nebuchadnezzar carried away: in the seventh year, 3,023 Jews;'),
  ('BSB', 'Jeremiah', 24, 52, 29, 'in Nebuchadnezzar’s eighteenth year, 832 people from Jerusalem;'),
  ('BSB', 'Jeremiah', 24, 52, 30, 'in Nebuchadnezzar’s twenty-third year, Nebuzaradan captain of the guard carried away 745 Jews. So in all, 4,600 people were taken away.'),
  ('BSB', 'Jeremiah', 24, 52, 31, 'On the twenty-fifth day of the twelfth month of the thirty-seventh year of the exile of Jehoiachin king of Judah, in the first year of the reign of Evil-merodach king of Babylon, he pardoned Jehoiachin king of Judah and released him from prison.'),
  ('BSB', 'Jeremiah', 24, 52, 32, 'And he spoke kindly to Jehoiachin and set his throne above the thrones of the other kings who were with him in Babylon.'),
  ('BSB', 'Jeremiah', 24, 52, 33, 'So Jehoiachin changed out of his prison clothes, and he dined regularly at the king’s table for the rest of his life.'),
  ('BSB', 'Jeremiah', 24, 52, 34, 'And the king of Babylon provided Jehoiachin a daily portion for the rest of his life, until the day of his death.'),
  ('BSB', 'Lamentations', 25, 1, 1, 'How lonely lies the city, once so full of people! She who was great among the nations has become a widow. The princess of the provinces has become a slave.'),
  ('BSB', 'Lamentations', 25, 1, 2, 'She weeps aloud in the night, with tears upon her cheeks. Among all her lovers there is no one to comfort her. All her friends have betrayed her; they have become her enemies.'),
  ('BSB', 'Lamentations', 25, 1, 3, 'Judah has gone into exile under affliction and harsh slavery; she dwells among the nations but finds no place to rest. All her pursuers have overtaken her in the midst of her distress.'),
  ('BSB', 'Lamentations', 25, 1, 4, 'The roads to Zion mourn, because no one comes to her appointed feasts. All her gates are deserted; her priests groan, her maidens grieve, and she herself is bitter with anguish.'),
  ('BSB', 'Lamentations', 25, 1, 5, 'Her foes have become her masters; her enemies are at ease. For the LORD has brought her grief because of her many transgressions. Her children have gone away as captives before the enemy.'),
  ('BSB', 'Lamentations', 25, 1, 6, 'All the splendor has departed from the Daughter of Zion. Her princes are like deer that find no pasture; they lack the strength to flee in the face of the hunter.'),
  ('BSB', 'Lamentations', 25, 1, 7, 'In the days of her affliction and wandering Jerusalem remembers all the treasures that were hers in days of old. When her people fell into enemy hands she received no help. Her enemies looked upon her, laughing at her downfall.'),
  ('BSB', 'Lamentations', 25, 1, 8, 'Jerusalem has sinned greatly; therefore she has become an object of scorn. All who honored her now despise her, for they have seen her nakedness; she herself groans and turns away.'),
  ('BSB', 'Lamentations', 25, 1, 9, 'Her uncleanness stains her skirts; she did not consider her end. Her downfall was astounding; there was no one to comfort her. Look, O LORD, on my affliction, for the enemy has triumphed!'),
  ('BSB', 'Lamentations', 25, 1, 10, 'The adversary has seized all her treasures. For she has seen the nations enter her sanctuary— those You had forbidden to enter Your assembly.'),
  ('BSB', 'Lamentations', 25, 1, 11, 'All her people groan as they search for bread. They have traded their treasures for food to keep themselves alive. Look, O LORD, and consider, for I have become despised.'),
  ('BSB', 'Lamentations', 25, 1, 12, 'Is this nothing to you, all you who pass by? Look around and see! Is there any sorrow like mine, which was inflicted on me, which the LORD made me suffer on the day of His fierce anger?'),
  ('BSB', 'Lamentations', 25, 1, 13, 'He sent fire from on high, and it overpowered my bones. He spread a net for my feet and turned me back. He made me desolate, faint all the day long.'),
  ('BSB', 'Lamentations', 25, 1, 14, 'My transgressions are bound into a yoke, knit together by His hand; they are draped over my neck, and the Lord has broken my strength. He has delivered me into the hands of those I cannot withstand.'),
  ('BSB', 'Lamentations', 25, 1, 15, 'The Lord has rejected all the mighty men in my midst; He has summoned an army against me to crush my young warriors. Like grapes in a winepress, the Lord has trampled the Virgin Daughter of Judah.'),
  ('BSB', 'Lamentations', 25, 1, 16, 'For these things I weep; my eyes flow with tears. For there is no one nearby to comfort me, no one to revive my soul. My children are destitute because the enemy has prevailed.'),
  ('BSB', 'Lamentations', 25, 1, 17, 'Zion stretches out her hands, but there is no one to comfort her. The LORD has decreed against Jacob that his neighbors become his foes. Jerusalem has become an unclean thing among them.'),
  ('BSB', 'Lamentations', 25, 1, 18, 'The LORD is righteous, for I have rebelled against His command. Listen, all you people; look upon my suffering. My young men and maidens have gone into captivity.'),
  ('BSB', 'Lamentations', 25, 1, 19, 'I called out to my lovers, but they have betrayed me. My priests and elders perished in the city while they searched for food to keep themselves alive.'),
  ('BSB', 'Lamentations', 25, 1, 20, 'See, O LORD, how distressed I am! I am churning within; my heart is pounding within me, for I have been most rebellious. Outside, the sword bereaves; inside, there is death.'),
  ('BSB', 'Lamentations', 25, 1, 21, 'People have heard my groaning, but there is no one to comfort me. All my enemies have heard of my trouble; they are glad that You have caused it. May You bring the day You have announced, so that they may become like me.'),
  ('BSB', 'Lamentations', 25, 1, 22, 'Let all their wickedness come before You, and deal with them as You have dealt with me because of all my transgressions. For my groans are many, and my heart is faint.'),
  ('BSB', 'Lamentations', 25, 2, 1, 'How the Lord has covered the Daughter of Zion with the cloud of His anger! He has cast the glory of Israel from heaven to earth. He has abandoned His footstool in the day of His anger.'),
  ('BSB', 'Lamentations', 25, 2, 2, 'Without pity the Lord has swallowed up all the dwellings of Jacob. In His wrath He has demolished the fortified cities of the Daughter of Judah. He brought to the ground and defiled her kingdom and its princes.'),
  ('BSB', 'Lamentations', 25, 2, 3, 'In fierce anger He has cut off every horn of Israel and withdrawn His right hand at the approach of the enemy. He has burned in Jacob like a flaming fire that consumes everything around it.'),
  ('BSB', 'Lamentations', 25, 2, 4, 'He has bent His bow like an enemy; His right hand is positioned. Like a foe He has killed all who were pleasing to the eye; He has poured out His wrath like fire on the tent of the Daughter of Zion.'),
  ('BSB', 'Lamentations', 25, 2, 5, 'The Lord is like an enemy; He has swallowed up Israel. He has swallowed up all her palaces and destroyed her strongholds. He has multiplied mourning and lamentation for the Daughter of Judah.'),
  ('BSB', 'Lamentations', 25, 2, 6, 'He has laid waste His tabernacle like a garden booth; He has destroyed His place of meeting. The LORD has made Zion forget her appointed feasts and Sabbaths. In His fierce anger He has despised both king and priest.'),
  ('BSB', 'Lamentations', 25, 2, 7, 'The Lord has rejected His altar; He has abandoned His sanctuary; He has delivered the walls of her palaces into the hand of the enemy. They have raised a shout in the house of the LORD as on the day of an appointed feast.'),
  ('BSB', 'Lamentations', 25, 2, 8, 'The LORD determined to destroy the wall of the Daughter of Zion. He stretched out a measuring line and did not withdraw His hand from destroying. He made the ramparts and walls lament; together they waste away.'),
  ('BSB', 'Lamentations', 25, 2, 9, 'Her gates have sunk into the ground; He has destroyed and shattered their bars. Her king and her princes are exiled among the nations, the law is no more, and even her prophets find no vision from the LORD.'),
  ('BSB', 'Lamentations', 25, 2, 10, 'The elders of the Daughter of Zion sit on the ground in silence. They have thrown dust on their heads and put on sackcloth. The young women of Jerusalem have bowed their heads to the ground.'),
  ('BSB', 'Lamentations', 25, 2, 11, 'My eyes fail from weeping; I am churning within. My heart is poured out in grief over the destruction of the daughter of my people, because children and infants faint in the streets of the city.'),
  ('BSB', 'Lamentations', 25, 2, 12, 'They cry out to their mothers: “Where is the grain and wine?” as they faint like the wounded in the streets of the city, as their lives fade away in the arms of their mothers.'),
  ('BSB', 'Lamentations', 25, 2, 13, 'What can I say for you? To what can I compare you, O Daughter of Jerusalem? To what can I liken you, that I may console you, O Virgin Daughter of Zion? For your wound is as deep as the sea. Who can ever heal you?'),
  ('BSB', 'Lamentations', 25, 2, 14, 'The visions of your prophets were empty and deceptive; they did not expose your guilt to ward off your captivity. The burdens they envisioned for you were empty and misleading.'),
  ('BSB', 'Lamentations', 25, 2, 15, 'All who pass by clap their hands at you in scorn. They hiss and shake their heads at the Daughter of Jerusalem: “Is this the city that was called the perfection of beauty, the joy of all the earth?”'),
  ('BSB', 'Lamentations', 25, 2, 16, 'All your enemies open their mouths against you. They hiss and gnash their teeth, saying, “We have swallowed her up. This is the day for which we have waited. We have lived to see it!”'),
  ('BSB', 'Lamentations', 25, 2, 17, 'The LORD has done what He planned; He has accomplished His decree, which He ordained in days of old; He has overthrown you without pity. He has let the enemy gloat over you and exalted the horn of your foes.'),
  ('BSB', 'Lamentations', 25, 2, 18, 'The hearts of the people cry out to the Lord. O wall of the Daughter of Zion, let your tears run down like a river day and night. Give yourself no relief, and your eyes no rest.'),
  ('BSB', 'Lamentations', 25, 2, 19, 'Arise, cry out in the night from the first watch of the night. Pour out your heart like water in the presence of the Lord. Lift up your hands to Him for the lives of your children who are fainting from hunger on the corner of every street.'),
  ('BSB', 'Lamentations', 25, 2, 20, 'Look, O LORD, and consider: Whom have You ever treated like this? Should women eat their offspring, the infants they have nurtured? Should priests and prophets be killed in the sanctuary of the Lord?'),
  ('BSB', 'Lamentations', 25, 2, 21, 'Both young and old lie together in the dust of the streets. My young men and maidens have fallen by the sword. You have slain them in the day of Your anger; You have slaughtered them without compassion.'),
  ('BSB', 'Lamentations', 25, 2, 22, 'You summoned my attackers on every side, as for the day of an appointed feast. In the day of the LORD’s anger no one escaped or survived; my enemy has destroyed those I nurtured and reared.'),
  ('BSB', 'Lamentations', 25, 3, 1, 'I am the man who has seen affliction under the rod of God’s wrath.'),
  ('BSB', 'Lamentations', 25, 3, 2, 'He has driven me away and made me walk in darkness instead of light.'),
  ('BSB', 'Lamentations', 25, 3, 3, 'Indeed, He keeps turning His hand against me all day long.'),
  ('BSB', 'Lamentations', 25, 3, 4, 'He has worn away my flesh and skin; He has shattered my bones.'),
  ('BSB', 'Lamentations', 25, 3, 5, 'He has besieged me and surrounded me with bitterness and hardship.'),
  ('BSB', 'Lamentations', 25, 3, 6, 'He has made me dwell in darkness like those dead for ages.'),
  ('BSB', 'Lamentations', 25, 3, 7, 'He has walled me in so I cannot escape; He has weighed me down with chains.'),
  ('BSB', 'Lamentations', 25, 3, 8, 'Even when I cry out and plead for help, He shuts out my prayer.'),
  ('BSB', 'Lamentations', 25, 3, 9, 'He has barred my ways with cut stones; He has made my paths crooked.'),
  ('BSB', 'Lamentations', 25, 3, 10, 'He is a bear lying in wait, a lion hiding in ambush.'),
  ('BSB', 'Lamentations', 25, 3, 11, 'He forced me off my path and tore me to pieces; He left me without help.'),
  ('BSB', 'Lamentations', 25, 3, 12, 'He bent His bow and set me as the target for His arrow.'),
  ('BSB', 'Lamentations', 25, 3, 13, 'He pierced my kidneys with His arrows.'),
  ('BSB', 'Lamentations', 25, 3, 14, 'I am a laughingstock to all my people; they mock me in song all day long.'),
  ('BSB', 'Lamentations', 25, 3, 15, 'He has filled me with bitterness; He has intoxicated me with wormwood.'),
  ('BSB', 'Lamentations', 25, 3, 16, 'He has ground my teeth with gravel and trampled me in the dust.'),
  ('BSB', 'Lamentations', 25, 3, 17, 'My soul has been deprived of peace; I have forgotten what prosperity is.'),
  ('BSB', 'Lamentations', 25, 3, 18, 'So I say, “My strength has perished, along with my hope from the LORD.”'),
  ('BSB', 'Lamentations', 25, 3, 19, 'Remember my affliction and wandering, the wormwood and the gall.'),
  ('BSB', 'Lamentations', 25, 3, 20, 'Surely my soul remembers and is humbled within me.'),
  ('BSB', 'Lamentations', 25, 3, 21, 'Yet I call this to mind, and therefore I have hope:'),
  ('BSB', 'Lamentations', 25, 3, 22, 'Because of the loving devotion of the LORD we are not consumed, for His mercies never fail.'),
  ('BSB', 'Lamentations', 25, 3, 23, 'They are new every morning; great is Your faithfulness!'),
  ('BSB', 'Lamentations', 25, 3, 24, '“The LORD is my portion,” says my soul, “therefore I will hope in Him.”'),
  ('BSB', 'Lamentations', 25, 3, 25, 'The LORD is good to those who wait for Him, to the soul who seeks Him.'),
  ('BSB', 'Lamentations', 25, 3, 26, 'It is good to wait quietly for the salvation of the LORD.'),
  ('BSB', 'Lamentations', 25, 3, 27, 'It is good for a man to bear the yoke while he is still young.'),
  ('BSB', 'Lamentations', 25, 3, 28, 'Let him sit alone in silence, for God has disciplined him.'),
  ('BSB', 'Lamentations', 25, 3, 29, 'Let him bury his face in the dust— perhaps there is still hope.'),
  ('BSB', 'Lamentations', 25, 3, 30, 'Let him offer his cheek to the one who would strike him; let him be filled with reproach.'),
  ('BSB', 'Lamentations', 25, 3, 31, 'For the Lord will not cast us off forever.'),
  ('BSB', 'Lamentations', 25, 3, 32, 'Even if He causes grief, He will show compassion according to His abundant loving devotion.'),
  ('BSB', 'Lamentations', 25, 3, 33, 'For He does not willingly afflict or grieve the sons of men.'),
  ('BSB', 'Lamentations', 25, 3, 34, 'To crush underfoot all the prisoners of the land,'),
  ('BSB', 'Lamentations', 25, 3, 35, 'to deny a man justice before the Most High,'),
  ('BSB', 'Lamentations', 25, 3, 36, 'to subvert a man in his lawsuit— of these the Lord does not approve.'),
  ('BSB', 'Lamentations', 25, 3, 37, 'Who has spoken and it came to pass, unless the Lord has ordained it?'),
  ('BSB', 'Lamentations', 25, 3, 38, 'Do not both adversity and good come from the mouth of the Most High?'),
  ('BSB', 'Lamentations', 25, 3, 39, 'Why should any mortal man complain, in view of his sins?'),
  ('BSB', 'Lamentations', 25, 3, 40, 'Let us examine and test our ways, and turn back to the LORD.'),
  ('BSB', 'Lamentations', 25, 3, 41, 'Let us lift up our hearts and hands to God in heaven:'),
  ('BSB', 'Lamentations', 25, 3, 42, '“We have sinned and rebelled; You have not forgiven.”'),
  ('BSB', 'Lamentations', 25, 3, 43, 'You have covered Yourself in anger and pursued us; You have killed without pity.'),
  ('BSB', 'Lamentations', 25, 3, 44, 'You have covered Yourself with a cloud that no prayer can pass through.'),
  ('BSB', 'Lamentations', 25, 3, 45, 'You have made us scum and refuse among the nations.');
insert into control_room_bible (version, book, book_num, chapter, verse, text) values
  ('BSB', 'Lamentations', 25, 3, 46, 'All our enemies open their mouths against us.'),
  ('BSB', 'Lamentations', 25, 3, 47, 'Panic and pitfall have come upon us— devastation and destruction.'),
  ('BSB', 'Lamentations', 25, 3, 48, 'Streams of tears flow from my eyes over the destruction of the daughter of my people.'),
  ('BSB', 'Lamentations', 25, 3, 49, 'My eyes overflow unceasingly, without relief,'),
  ('BSB', 'Lamentations', 25, 3, 50, 'until the LORD looks down from heaven and sees.'),
  ('BSB', 'Lamentations', 25, 3, 51, 'My eyes bring grief to my soul because of all the daughters of my city.'),
  ('BSB', 'Lamentations', 25, 3, 52, 'Without cause my enemies hunted me like a bird.'),
  ('BSB', 'Lamentations', 25, 3, 53, 'They dropped me alive into a pit and cast stones upon me.'),
  ('BSB', 'Lamentations', 25, 3, 54, 'The waters flowed over my head, and I thought I was going to die.'),
  ('BSB', 'Lamentations', 25, 3, 55, 'I called on Your name, O LORD, out of the depths of the Pit.'),
  ('BSB', 'Lamentations', 25, 3, 56, 'You heard my plea: “Do not ignore my cry for relief.”'),
  ('BSB', 'Lamentations', 25, 3, 57, 'You drew near when I called on You; You said, “Do not be afraid.”'),
  ('BSB', 'Lamentations', 25, 3, 58, 'You defend my cause, O Lord; You redeem my life.'),
  ('BSB', 'Lamentations', 25, 3, 59, 'You have seen, O LORD, the wrong done to me; vindicate my cause!'),
  ('BSB', 'Lamentations', 25, 3, 60, 'You have seen all their malice, all their plots against me.'),
  ('BSB', 'Lamentations', 25, 3, 61, 'O LORD, You have heard their insults, all their plots against me—'),
  ('BSB', 'Lamentations', 25, 3, 62, 'the slander and murmuring of my assailants against me all day long.'),
  ('BSB', 'Lamentations', 25, 3, 63, 'When they sit and when they rise, see how they mock me in song.'),
  ('BSB', 'Lamentations', 25, 3, 64, 'You will pay them back what they deserve, O LORD, according to the work of their hands.'),
  ('BSB', 'Lamentations', 25, 3, 65, 'Put a veil of anguish over their hearts; may Your curse be upon them!'),
  ('BSB', 'Lamentations', 25, 3, 66, 'You will pursue them in anger and exterminate them from under Your heavens, O LORD.'),
  ('BSB', 'Lamentations', 25, 4, 1, 'How the gold has become tarnished, the pure gold has become dull! The gems of the temple lie scattered on every street corner.'),
  ('BSB', 'Lamentations', 25, 4, 2, 'How the precious sons of Zion, once worth their weight in pure gold, are now esteemed as jars of clay, the work of a potter’s hands!'),
  ('BSB', 'Lamentations', 25, 4, 3, 'Even jackals offer their breasts to nurse their young, but the daughter of my people has become cruel, like an ostrich in the wilderness.'),
  ('BSB', 'Lamentations', 25, 4, 4, 'The nursing infant’s tongue clings in thirst to the roof of his mouth. Little children beg for bread, but no one gives them any.'),
  ('BSB', 'Lamentations', 25, 4, 5, 'Those who once ate delicacies are destitute in the streets; those brought up in crimson huddle in ash heaps.'),
  ('BSB', 'Lamentations', 25, 4, 6, 'The punishment of the daughter of my people is greater than that of Sodom, which was overthrown in an instant without a hand turned to help her.'),
  ('BSB', 'Lamentations', 25, 4, 7, 'Her dignitaries were brighter than snow, whiter than milk; their bodies were more ruddy than rubies, their appearance like sapphires.'),
  ('BSB', 'Lamentations', 25, 4, 8, 'But now their appearance is blacker than soot; they are not recognized in the streets. Their skin has shriveled on their bones; it has become as dry as a stick.'),
  ('BSB', 'Lamentations', 25, 4, 9, 'Those slain by the sword are better off than those who die of hunger, who waste away, pierced with pain because the fields lack produce.'),
  ('BSB', 'Lamentations', 25, 4, 10, 'The hands of compassionate women have cooked their own children, who became their food in the destruction of the daughter of my people.'),
  ('BSB', 'Lamentations', 25, 4, 11, 'The LORD has exhausted His wrath; He has poured out His fierce anger; He has kindled a fire in Zion, and it has consumed her foundations.'),
  ('BSB', 'Lamentations', 25, 4, 12, 'The kings of the earth did not believe, nor any people of the world, that an enemy or a foe could enter the gates of Jerusalem.'),
  ('BSB', 'Lamentations', 25, 4, 13, 'But this was for the sins of her prophets and the guilt of her priests, who shed the blood of the righteous in her midst.'),
  ('BSB', 'Lamentations', 25, 4, 14, 'They wandered blind in the streets, defiled by this blood, so that no one dared to touch their garments.'),
  ('BSB', 'Lamentations', 25, 4, 15, '“Go away! Unclean!” men shouted at them. “Away, away! Do not touch us!” So they fled and wandered. Among the nations it was said, “They can stay here no longer.”'),
  ('BSB', 'Lamentations', 25, 4, 16, 'The presence of the LORD has scattered them; He regards them no more. The priests are shown no honor; the elders find no favor.'),
  ('BSB', 'Lamentations', 25, 4, 17, 'All the while our eyes were failing as we looked in vain for help. We watched from our towers for a nation that could not save us.'),
  ('BSB', 'Lamentations', 25, 4, 18, 'They stalked our every step, so that we could not walk in our streets. Our end drew near, our time ran out, for our end had come!'),
  ('BSB', 'Lamentations', 25, 4, 19, 'Those who chased us were swifter than the eagles in the sky; they pursued us over the mountains and ambushed us in the wilderness.'),
  ('BSB', 'Lamentations', 25, 4, 20, 'The LORD’s anointed, the breath of our life, was captured in their pits. We had said of him, “Under his shadow we will live among the nations.”'),
  ('BSB', 'Lamentations', 25, 4, 21, 'So rejoice and be glad, O Daughter of Edom, you who dwell in the land of Uz. Yet the cup will pass to you as well; you will get drunk and expose yourself.'),
  ('BSB', 'Lamentations', 25, 4, 22, 'O Daughter of Zion, your punishment is complete; He will not prolong your exile. But He will punish your iniquity, O Daughter of Edom; He will expose your sins.'),
  ('BSB', 'Lamentations', 25, 5, 1, 'Remember, O LORD, what has happened to us. Look and see our disgrace!'),
  ('BSB', 'Lamentations', 25, 5, 2, 'Our inheritance has been turned over to strangers, our houses to foreigners.'),
  ('BSB', 'Lamentations', 25, 5, 3, 'We have become fatherless orphans; our mothers are widows.'),
  ('BSB', 'Lamentations', 25, 5, 4, 'We must buy the water we drink; our wood comes at a price.'),
  ('BSB', 'Lamentations', 25, 5, 5, 'We are closely pursued; we are weary and find no rest.'),
  ('BSB', 'Lamentations', 25, 5, 6, 'We submitted to Egypt and Assyria to get enough bread.'),
  ('BSB', 'Lamentations', 25, 5, 7, 'Our fathers sinned and are no more, but we bear their punishment.'),
  ('BSB', 'Lamentations', 25, 5, 8, 'Slaves rule over us; there is no one to deliver us from their hands.'),
  ('BSB', 'Lamentations', 25, 5, 9, 'We get our bread at the risk of our lives because of the sword in the wilderness.'),
  ('BSB', 'Lamentations', 25, 5, 10, 'Our skin is as hot as an oven with fever from our hunger.'),
  ('BSB', 'Lamentations', 25, 5, 11, 'Women have been ravished in Zion, virgins in the cities of Judah.'),
  ('BSB', 'Lamentations', 25, 5, 12, 'Princes have been hung up by their hands; elders receive no respect.'),
  ('BSB', 'Lamentations', 25, 5, 13, 'Young men toil at millstones; boys stagger under loads of wood.'),
  ('BSB', 'Lamentations', 25, 5, 14, 'The elders have left the city gate; the young men have stopped their music.'),
  ('BSB', 'Lamentations', 25, 5, 15, 'Joy has left our hearts; our dancing has turned to mourning.'),
  ('BSB', 'Lamentations', 25, 5, 16, 'The crown has fallen from our head. Woe to us, for we have sinned!'),
  ('BSB', 'Lamentations', 25, 5, 17, 'Because of this, our hearts are faint; because of these, our eyes grow dim—'),
  ('BSB', 'Lamentations', 25, 5, 18, 'because of Mount Zion, which lies desolate, patrolled by foxes.'),
  ('BSB', 'Lamentations', 25, 5, 19, 'You, O LORD, reign forever; Your throne endures from generation to generation.'),
  ('BSB', 'Lamentations', 25, 5, 20, 'Why have You forgotten us forever? Why have You forsaken us for so long?'),
  ('BSB', 'Lamentations', 25, 5, 21, 'Restore us to Yourself, O LORD, so we may return; renew our days as of old,'),
  ('BSB', 'Lamentations', 25, 5, 22, 'unless You have utterly rejected us and remain angry with us beyond measure.'),
  ('BSB', 'Ezekiel', 26, 1, 1, 'In the thirtieth year, on the fifth day of the fourth month, while I was among the exiles by the River Kebar, the heavens opened and I saw visions of God.'),
  ('BSB', 'Ezekiel', 26, 1, 2, 'On the fifth day of the month—it was the fifth year of the exile of King Jehoiachin—'),
  ('BSB', 'Ezekiel', 26, 1, 3, 'the word of the LORD came directly to Ezekiel the priest, the son of Buzi, in the land of the Chaldeans by the River Kebar. And there the LORD’s hand was upon him.'),
  ('BSB', 'Ezekiel', 26, 1, 4, 'I looked and saw a whirlwind coming from the north, a great cloud with fire flashing back and forth and brilliant light all around it. In the center of the fire was a gleam like amber,'),
  ('BSB', 'Ezekiel', 26, 1, 5, 'and within it was the form of four living creatures. And this was their appearance: They had a human form,'),
  ('BSB', 'Ezekiel', 26, 1, 6, 'but each had four faces and four wings.'),
  ('BSB', 'Ezekiel', 26, 1, 7, 'Their legs were straight, and the soles of their feet were like the hooves of a calf, gleaming like polished bronze.'),
  ('BSB', 'Ezekiel', 26, 1, 8, 'Under their wings on their four sides they had human hands. All four living creatures had faces and wings,'),
  ('BSB', 'Ezekiel', 26, 1, 9, 'and their wings were touching one another. They did not turn as they moved; each one went straight ahead.'),
  ('BSB', 'Ezekiel', 26, 1, 10, 'The form of their faces was that of a man, and each of the four had the face of a lion on the right side, the face of an ox on the left side, and also the face of an eagle.'),
  ('BSB', 'Ezekiel', 26, 1, 11, 'Such were their faces. Their wings were spread upward; each had two wings touching the wings of the creature on either side, and two wings covering its body.'),
  ('BSB', 'Ezekiel', 26, 1, 12, 'Each creature went straight ahead. Wherever the spirit would go, they would go, without turning as they moved.'),
  ('BSB', 'Ezekiel', 26, 1, 13, 'In the midst of the living creatures was the appearance of glowing coals of fire, or of torches. Fire moved back and forth between the living creatures; it was bright, and lightning flashed out of it.'),
  ('BSB', 'Ezekiel', 26, 1, 14, 'The creatures were darting back and forth as quickly as flashes of lightning.'),
  ('BSB', 'Ezekiel', 26, 1, 15, 'When I looked at the living creatures, I saw a wheel on the ground beside each creature with its four faces.'),
  ('BSB', 'Ezekiel', 26, 1, 16, 'The workmanship of the wheels looked like the gleam of beryl, and all four had the same likeness. Their workmanship looked like a wheel within a wheel.'),
  ('BSB', 'Ezekiel', 26, 1, 17, 'As they moved, they went in any of the four directions, without pivoting as they moved.'),
  ('BSB', 'Ezekiel', 26, 1, 18, 'Their rims were high and awesome, and all four rims were full of eyes all around.'),
  ('BSB', 'Ezekiel', 26, 1, 19, 'So as the living creatures moved, the wheels moved beside them, and when the creatures rose from the ground, the wheels also rose.'),
  ('BSB', 'Ezekiel', 26, 1, 20, 'Wherever the spirit would go, they would go, and the wheels would rise alongside them, because the spirit of the living creatures was in the wheels.'),
  ('BSB', 'Ezekiel', 26, 1, 21, 'When the creatures moved, the wheels moved; when the creatures stood still, the wheels stood still; and when the creatures rose from the ground, the wheels rose alongside them, because the spirit of the living creatures was in the wheels.'),
  ('BSB', 'Ezekiel', 26, 1, 22, 'Spread out above the heads of the living creatures was the likeness of an awesome expanse, gleaming like crystal.'),
  ('BSB', 'Ezekiel', 26, 1, 23, 'And under the expanse, their wings stretched out toward one another. Each one also had two wings covering its body.'),
  ('BSB', 'Ezekiel', 26, 1, 24, 'When the creatures moved, I heard the sound of their wings like the roar of many waters, like the voice of the Almighty, like the tumult of an army. When they stood still, they lowered their wings.'),
  ('BSB', 'Ezekiel', 26, 1, 25, 'And there came a voice from above the expanse over their heads as they stood still with their wings lowered.'),
  ('BSB', 'Ezekiel', 26, 1, 26, 'Above the expanse over their heads was the likeness of a throne with the appearance of sapphire, and on the throne high above was a figure like that of a man.'),
  ('BSB', 'Ezekiel', 26, 1, 27, 'From what seemed to be His waist up, I saw a gleam like amber, with what looked like fire within it all around. And from what seemed to be His waist down, I saw what looked like fire; and brilliant light surrounded Him.'),
  ('BSB', 'Ezekiel', 26, 1, 28, 'The appearance of the brilliant light all around Him was like that of a rainbow in a cloud on a rainy day. This was the appearance of the likeness of the glory of the LORD. And when I saw it, I fell facedown and heard a voice speaking.'),
  ('BSB', 'Ezekiel', 26, 2, 1, '“Son of man,” He said to me, “stand up on your feet and I will speak to you.”'),
  ('BSB', 'Ezekiel', 26, 2, 2, 'And as He spoke to me, the Spirit entered me and set me on my feet, and I heard Him speaking to me.'),
  ('BSB', 'Ezekiel', 26, 2, 3, '“Son of man,” He said to me, “I am sending you to the Israelites, to a rebellious nation that has rebelled against Me. To this very day they and their fathers have rebelled against Me.'),
  ('BSB', 'Ezekiel', 26, 2, 4, 'They are obstinate and stubborn children. I am sending you to them, and you are to say to them, ‘This is what the Lord GOD says.’'),
  ('BSB', 'Ezekiel', 26, 2, 5, 'And whether they listen or refuse to listen—for they are a rebellious house—they will know that a prophet has been among them.'),
  ('BSB', 'Ezekiel', 26, 2, 6, 'But you, son of man, do not be afraid of them or their words. Do not be afraid, though briers and thorns surround you, and you dwell among scorpions. Do not be afraid of their words or dismayed by their presence, though they are a rebellious house.'),
  ('BSB', 'Ezekiel', 26, 2, 7, 'But speak My words to them, whether they listen or refuse to listen, for they are rebellious.'),
  ('BSB', 'Ezekiel', 26, 2, 8, 'And you, son of man, listen to what I tell you. Do not be rebellious like that rebellious house. Open your mouth and eat what I give you.”'),
  ('BSB', 'Ezekiel', 26, 2, 9, 'Then I looked and saw a hand reaching out to me, and in it was a scroll,'),
  ('BSB', 'Ezekiel', 26, 2, 10, 'which He unrolled before me. And written on the front and back of it were words of lamentation, mourning, and woe.'),
  ('BSB', 'Ezekiel', 26, 3, 1, '“Son of man,” He said to me, “eat what you find here. Eat this scroll, then go and speak to the house of Israel.”'),
  ('BSB', 'Ezekiel', 26, 3, 2, 'So I opened my mouth, and He fed me the scroll.'),
  ('BSB', 'Ezekiel', 26, 3, 3, '“Son of man,” He said to me, “eat and fill your stomach with this scroll I am giving you.” So I ate, and it was as sweet as honey in my mouth.'),
  ('BSB', 'Ezekiel', 26, 3, 4, 'Then He said to me, “Son of man, go now to the house of Israel and speak My words to them.'),
  ('BSB', 'Ezekiel', 26, 3, 5, 'For you are not being sent to a people of unfamiliar speech or difficult language, but to the house of Israel—'),
  ('BSB', 'Ezekiel', 26, 3, 6, 'not to the many peoples of unfamiliar speech and difficult language whose words you cannot understand. Surely if I had sent you to them, they would have listened to you.'),
  ('BSB', 'Ezekiel', 26, 3, 7, 'But the house of Israel will be unwilling to listen to you, since they are unwilling to listen to Me. For the whole house of Israel is hard-headed and hard-hearted.'),
  ('BSB', 'Ezekiel', 26, 3, 8, 'Behold, I will make your face as hard as their faces, and your forehead as hard as their foreheads.'),
  ('BSB', 'Ezekiel', 26, 3, 9, 'I will make your forehead like a diamond, harder than flint. Do not be afraid of them or dismayed at their presence, even though they are a rebellious house.”'),
  ('BSB', 'Ezekiel', 26, 3, 10, '“Son of man,” He added, “listen carefully to all the words I speak to you, and take them to heart.'),
  ('BSB', 'Ezekiel', 26, 3, 11, 'Go to your people, the exiles; speak to them and tell them, ‘This is what the Lord GOD says,’ whether they listen or refuse to listen.”'),
  ('BSB', 'Ezekiel', 26, 3, 12, 'Then the Spirit lifted me up, and I heard a great rumbling sound behind me: ‘Blessed be the glory of the LORD in His dwelling place!’'),
  ('BSB', 'Ezekiel', 26, 3, 13, 'It was the sound of the wings of the living creatures brushing against one another and the sound of the wheels beside them, a great rumbling sound.'),
  ('BSB', 'Ezekiel', 26, 3, 14, 'So the Spirit lifted me up and took me away, and I went in bitterness and in the anger of my spirit, with the strong hand of the LORD upon me.'),
  ('BSB', 'Ezekiel', 26, 3, 15, 'I came to the exiles at Tel-abib who dwelt by the River Kebar. And for seven days I sat where they sat and remained there among them, overwhelmed.'),
  ('BSB', 'Ezekiel', 26, 3, 16, 'At the end of seven days the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 3, 17, '“Son of man, I have made you a watchman for the house of Israel. Whenever you hear a word from My mouth, give them a warning from Me.'),
  ('BSB', 'Ezekiel', 26, 3, 18, 'If I say to the wicked man, ‘You will surely die,’ but you do not warn him or speak out to warn him from his wicked way to save his life, that wicked man will die in his iniquity, and I will hold you responsible for his blood.'),
  ('BSB', 'Ezekiel', 26, 3, 19, 'But if you warn a wicked man and he does not turn from his wickedness and his wicked way, he will die in his iniquity, but you will have saved yourself.'),
  ('BSB', 'Ezekiel', 26, 3, 20, 'Now if a righteous man turns from his righteousness and commits iniquity, and I put a stumbling block before him, he will die. If you did not warn him, he will die in his sin, and the righteous acts he did will not be remembered. And I will hold you responsible for his blood.'),
  ('BSB', 'Ezekiel', 26, 3, 21, 'But if you warn the righteous man not to sin, and he does not sin, he will indeed live because he heeded your warning, and you will have saved yourself.”'),
  ('BSB', 'Ezekiel', 26, 3, 22, 'And there the hand of the LORD was upon me, and He said to me, “Get up, go out to the plain, and there I will speak with you.”'),
  ('BSB', 'Ezekiel', 26, 3, 23, 'So I got up and went out to the plain, and behold, the glory of the LORD was present there, like the glory I had seen by the River Kebar, and I fell facedown.'),
  ('BSB', 'Ezekiel', 26, 3, 24, 'Then the Spirit entered me and set me on my feet. He spoke with me and said, “Go, shut yourself inside your house.'),
  ('BSB', 'Ezekiel', 26, 3, 25, 'And you, son of man, they will tie with ropes, and you will be bound so that you cannot go out among the people.'),
  ('BSB', 'Ezekiel', 26, 3, 26, 'I will make your tongue stick to the roof of your mouth, and you will be silent and unable to rebuke them, though they are a rebellious house.'),
  ('BSB', 'Ezekiel', 26, 3, 27, 'But when I speak with you, I will open your mouth, and you are to tell them, ‘This is what the Lord GOD says.’ Whoever listens, let him listen; and whoever refuses, let him refuse, for they are a rebellious house.'),
  ('BSB', 'Ezekiel', 26, 4, 1, '“Now you, son of man, take a brick, place it before you, and draw on it the city of Jerusalem.'),
  ('BSB', 'Ezekiel', 26, 4, 2, 'Then lay siege against it: Construct a siege wall, build a ramp to it, set up camps against it, and place battering rams around it on all sides.'),
  ('BSB', 'Ezekiel', 26, 4, 3, 'Then take an iron plate and set it up as an iron wall between yourself and the city. Turn your face toward it so that it is under siege, and besiege it. This will be a sign to the house of Israel.'),
  ('BSB', 'Ezekiel', 26, 4, 4, 'Then lie down on your left side and place the iniquity of the house of Israel upon yourself. You are to bear their iniquity for the number of days you lie on your side.'),
  ('BSB', 'Ezekiel', 26, 4, 5, 'For I have assigned to you 390 days, according to the number of years of their iniquity. So you shall bear the iniquity of the house of Israel.'),
  ('BSB', 'Ezekiel', 26, 4, 6, 'When you have completed these days, lie down again, but on your right side, and bear the iniquity of the house of Judah. I have assigned to you 40 days, a day for each year.'),
  ('BSB', 'Ezekiel', 26, 4, 7, 'You must turn your face toward the siege of Jerusalem with your arm bared, and prophesy against it.'),
  ('BSB', 'Ezekiel', 26, 4, 8, 'Now behold, I will tie you up with ropes so you cannot turn from side to side until you have finished the days of your siege.'),
  ('BSB', 'Ezekiel', 26, 4, 9, 'But take wheat, barley, beans, lentils, millet, and spelt; put them in a single container and make them into bread for yourself. This is what you are to eat during the 390 days you lie on your side.'),
  ('BSB', 'Ezekiel', 26, 4, 10, 'You are to weigh out twenty shekels of food to eat each day, and you are to eat it at set times.'),
  ('BSB', 'Ezekiel', 26, 4, 11, 'You are also to measure out a sixth of a hin of water to drink, and you are to drink it at set times.'),
  ('BSB', 'Ezekiel', 26, 4, 12, 'And you shall eat the food as you would a barley cake, after you bake it over dried human excrement in the sight of the people.”'),
  ('BSB', 'Ezekiel', 26, 4, 13, 'Then the LORD said, “This is how the Israelites will eat their defiled bread among the nations to which I will banish them.”'),
  ('BSB', 'Ezekiel', 26, 4, 14, '“Ah, Lord GOD,” I said, “I have never defiled myself. From my youth until now I have not eaten anything found dead or mauled by wild beasts. No unclean meat has ever entered my mouth.”'),
  ('BSB', 'Ezekiel', 26, 4, 15, '“Look,” He replied, “I will let you use cow dung instead of human excrement, and you may bake your bread over that.”'),
  ('BSB', 'Ezekiel', 26, 4, 16, 'Then He told me, “Son of man, I am going to cut off the supply of food in Jerusalem. They will anxiously eat bread rationed by weight, and in despair they will drink water by measure.'),
  ('BSB', 'Ezekiel', 26, 4, 17, 'So they will lack food and water; they will be appalled at the sight of one another wasting away in their iniquity.'),
  ('BSB', 'Ezekiel', 26, 5, 1, '“As for you, son of man, take a sharp sword, use it as a barber’s razor, and shave your head and beard. Then take a set of scales and divide the hair.'),
  ('BSB', 'Ezekiel', 26, 5, 2, 'When the days of the siege have ended, you are to burn up a third of the hair inside the city; you are also to take a third and slash it with the sword all around the city; and you are to scatter a third to the wind. For I will unleash a sword behind them.'),
  ('BSB', 'Ezekiel', 26, 5, 3, 'But you are to take a few strands of hair and secure them in the folds of your garment.'),
  ('BSB', 'Ezekiel', 26, 5, 4, 'Again, take a few of these, throw them into the fire, and burn them. From there a fire will spread to the whole house of Israel.'),
  ('BSB', 'Ezekiel', 26, 5, 5, 'This is what the Lord GOD says: ‘This is Jerusalem, which I have set in the center of the nations, with countries all around her.'),
  ('BSB', 'Ezekiel', 26, 5, 6, 'But she has rebelled against My ordinances more wickedly than the nations, and against My statutes worse than the countries around her. For her people have rejected My ordinances and have not walked in My statutes.’'),
  ('BSB', 'Ezekiel', 26, 5, 7, 'Therefore this is what the Lord GOD says: ‘You have been more insubordinate than the nations around you; you have not walked in My statutes or kept My ordinances, nor have you even conformed to the ordinances of the nations around you.’'),
  ('BSB', 'Ezekiel', 26, 5, 8, 'Therefore this is what the Lord GOD says: ‘Behold, I Myself am against you, Jerusalem, and I will execute judgments among you in the sight of the nations.'),
  ('BSB', 'Ezekiel', 26, 5, 9, 'Because of all your abominations, I will do to you what I have never done before and will never do again.'),
  ('BSB', 'Ezekiel', 26, 5, 10, 'As a result, fathers among you will eat their sons, and sons will eat their fathers. I will execute judgments against you and scatter all your remnant to every wind.’'),
  ('BSB', 'Ezekiel', 26, 5, 11, 'Therefore as surely as I live, declares the Lord GOD, because you have defiled My sanctuary with all your detestable idols and abominations, I Myself will withdraw My favor; I will not look upon you with pity, nor will I spare you.'),
  ('BSB', 'Ezekiel', 26, 5, 12, 'A third of your people will die by plague or be consumed by famine within you, a third will fall by the sword outside your walls, and a third I will scatter to every wind and unleash a sword behind them.'),
  ('BSB', 'Ezekiel', 26, 5, 13, 'And when My anger is spent and I have vented My wrath against them, I will be appeased. And when I have spent My wrath on them, they will know that I, the LORD, in My zeal have spoken.'),
  ('BSB', 'Ezekiel', 26, 5, 14, 'I will make you a ruin and a disgrace among the nations around you, in the sight of all who pass by.'),
  ('BSB', 'Ezekiel', 26, 5, 15, 'So you will be a reproach and a taunt, a warning and a horror to the nations around you, when I execute judgments against you in anger, wrath, and raging fury. I, the LORD, have spoken.'),
  ('BSB', 'Ezekiel', 26, 5, 16, 'When I shower you with the deadly arrows of famine and destruction that I will send to destroy you, I will intensify the famine against you and cut off your supply of food.'),
  ('BSB', 'Ezekiel', 26, 5, 17, 'I will send famine and wild beasts against you, and they will leave you childless. Plague and bloodshed will sweep through you, and I will bring a sword against you. I, the LORD, have spoken.”'),
  ('BSB', 'Ezekiel', 26, 6, 1, 'And the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 6, 2, '“Son of man, set your face against the mountains of Israel and prophesy against them.'),
  ('BSB', 'Ezekiel', 26, 6, 3, 'You are to say: ‘O mountains of Israel, hear the word of the Lord GOD! This is what the Lord GOD says to the mountains and hills, to the ravines and valleys: I am about to bring a sword against you, and I will destroy your high places.'),
  ('BSB', 'Ezekiel', 26, 6, 4, 'Your altars will be demolished and your incense altars will be smashed; and I will cast down your slain before your idols.'),
  ('BSB', 'Ezekiel', 26, 6, 5, 'I will lay the corpses of the Israelites before their idols and scatter your bones around your altars.'),
  ('BSB', 'Ezekiel', 26, 6, 6, 'Wherever you live, the cities will be laid waste and the high places will be demolished, so that your altars will be laid waste and desecrated, your idols smashed and obliterated, your incense altars cut down, and your works blotted out.'),
  ('BSB', 'Ezekiel', 26, 6, 7, 'The slain will fall among you, and you will know that I am the LORD.'),
  ('BSB', 'Ezekiel', 26, 6, 8, 'Yet I will leave a remnant, for some of you will escape the sword when you are scattered among the nations and throughout the lands.'),
  ('BSB', 'Ezekiel', 26, 6, 9, 'Then in the nations to which they have been carried captive, your survivors will remember Me—how I have been grieved by their adulterous hearts that turned away from Me, and by their eyes that lusted after idols. So they will loathe themselves for the evil they have done and for all their abominations.'),
  ('BSB', 'Ezekiel', 26, 6, 10, 'And they will know that I am the LORD; I did not declare in vain that I would bring this calamity upon them.'),
  ('BSB', 'Ezekiel', 26, 6, 11, 'This is what the Lord GOD says: Clap your hands, stomp your feet, and cry out “Alas!” because of all the wicked abominations of the house of Israel, who will fall by sword and famine and plague.'),
  ('BSB', 'Ezekiel', 26, 6, 12, 'He who is far off will die by the plague, he who is near will fall by the sword, and he who remains will die by famine. So I will vent My fury upon them.'),
  ('BSB', 'Ezekiel', 26, 6, 13, 'Then you will know that I am the LORD, when their slain lie among their idols around their altars, on every high hill, on all the mountaintops, and under every green tree and leafy oak—the places where they offered fragrant incense to all their idols.'),
  ('BSB', 'Ezekiel', 26, 6, 14, 'I will stretch out My hand against them, and wherever they live I will make the land a desolate waste, from the wilderness to Diblah. Then they will know that I am the LORD.’”'),
  ('BSB', 'Ezekiel', 26, 7, 1, 'And the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 7, 2, '“O son of man, this is what the Lord GOD says to the land of Israel: ‘The end! The end has come upon the four corners of the land.'),
  ('BSB', 'Ezekiel', 26, 7, 3, 'The end is now upon you, and I will unleash My anger against you. I will judge you according to your ways and repay you for all your abominations.'),
  ('BSB', 'Ezekiel', 26, 7, 4, 'I will not look on you with pity, nor will I spare you, but I will punish you for your ways and for the abominations among you. Then you will know that I am the LORD.’'),
  ('BSB', 'Ezekiel', 26, 7, 5, 'This is what the Lord GOD says: ‘Disaster! An unprecedented disaster— behold, it is coming!'),
  ('BSB', 'Ezekiel', 26, 7, 6, 'The end has come! The end has come! It has roused itself against you. Behold, it has come!'),
  ('BSB', 'Ezekiel', 26, 7, 7, 'Doom has come to you, O inhabitants of the land. The time has come; the day is near; there is panic on the mountains instead of shouts of joy.'),
  ('BSB', 'Ezekiel', 26, 7, 8, 'Very soon I will pour out My wrath upon you and vent My anger against you; I will judge you according to your ways and repay you for all your abominations.'),
  ('BSB', 'Ezekiel', 26, 7, 9, 'I will not look on you with pity, nor will I spare you, but I will punish you for your ways and for the abominations among you. Then you will know that it is I, the LORD, who strikes the blow.'),
  ('BSB', 'Ezekiel', 26, 7, 10, 'Behold, the day is here! It has come! Doom has gone out, the rod has budded, arrogance has bloomed.'),
  ('BSB', 'Ezekiel', 26, 7, 11, 'Their violence has grown into a rod to punish their wickedness. None of them will remain: none of their multitude, none of their wealth, and nothing of value.'),
  ('BSB', 'Ezekiel', 26, 7, 12, 'The time has come; the day has arrived. Let the buyer not rejoice and the seller not mourn, for wrath is upon the whole multitude.'),
  ('BSB', 'Ezekiel', 26, 7, 13, 'The seller will surely not recover what he sold while both remain alive. For the vision concerning the whole multitude will not be revoked, and because of their iniquity, not one of them will preserve his life.'),
  ('BSB', 'Ezekiel', 26, 7, 14, 'They have blown the trumpet and made everything ready, but no one goes to war, for My wrath is upon the whole multitude.'),
  ('BSB', 'Ezekiel', 26, 7, 15, 'The sword is outside; plague and famine are within. Those in the country will die by the sword, and those in the city will be devoured by famine and plague.'),
  ('BSB', 'Ezekiel', 26, 7, 16, 'The survivors will escape and live in the mountains, moaning like doves of the valley, each for his own iniquity.'),
  ('BSB', 'Ezekiel', 26, 7, 17, 'Every hand will go limp, and every knee will turn to water.'),
  ('BSB', 'Ezekiel', 26, 7, 18, 'They will put on sackcloth, and terror will overwhelm them. Shame will cover all their faces, and all their heads will be shaved.'),
  ('BSB', 'Ezekiel', 26, 7, 19, 'They will throw their silver into the streets, and their gold will seem unclean. Their silver and gold cannot save them in the day of the wrath of the LORD. They cannot satisfy their appetites or fill their stomachs with wealth, for it became the stumbling block that brought their iniquity.'),
  ('BSB', 'Ezekiel', 26, 7, 20, 'His beautiful ornaments they transformed into pride and used them to fashion their vile images and detestable idols. Therefore I will make these into something unclean for them.'),
  ('BSB', 'Ezekiel', 26, 7, 21, 'And I will hand these things over as plunder to foreigners and loot to the wicked of the earth, who will defile them.'),
  ('BSB', 'Ezekiel', 26, 7, 22, 'I will turn My face away from them, and they will defile My treasured place. Violent men will enter it, and they will defile it.'),
  ('BSB', 'Ezekiel', 26, 7, 23, 'Forge the chain, for the land is full of crimes of bloodshed, and the city is full of violence.'),
  ('BSB', 'Ezekiel', 26, 7, 24, 'So I will bring the most wicked of nations to take possession of their houses. I will end the pride of the mighty, and their holy places will be profaned.'),
  ('BSB', 'Ezekiel', 26, 7, 25, 'Anguish is coming! They will seek peace, but find none.'),
  ('BSB', 'Ezekiel', 26, 7, 26, 'Disaster upon disaster will come, and rumor after rumor. Then they will seek a vision from a prophet, but instruction from the priests will perish, as will counsel from the elders.'),
  ('BSB', 'Ezekiel', 26, 7, 27, 'The king will mourn, the prince will be clothed with despair, and the hands of the people of the land will tremble. I will deal with them according to their conduct, and I will judge them by their own standards. Then they will know that I am the LORD.’”'),
  ('BSB', 'Ezekiel', 26, 8, 1, 'In the sixth year, on the fifth day of the sixth month, I was sitting in my house, and the elders of Judah were sitting before me; and there the hand of the Lord GOD fell upon me.'),
  ('BSB', 'Ezekiel', 26, 8, 2, 'Then I looked and saw a figure like that of a man. From His waist down His appearance was like fire, and from His waist up He was as bright as the gleam of amber.'),
  ('BSB', 'Ezekiel', 26, 8, 3, 'He stretched out what looked like a hand and took me by the hair of my head. Then the Spirit lifted me up between earth and heaven and carried me in visions of God to Jerusalem, to the entrance of the north gate of the inner court, where the idol that provokes jealousy was seated.'),
  ('BSB', 'Ezekiel', 26, 8, 4, 'And there I saw the glory of the God of Israel, like the vision I had seen in the plain.'),
  ('BSB', 'Ezekiel', 26, 8, 5, '“Son of man,” He said to me, “now lift up your eyes to the north.” So I lifted up my eyes to the north, and in the entrance north of the Altar Gate I saw this idol of jealousy.'),
  ('BSB', 'Ezekiel', 26, 8, 6, '“Son of man,” He said to me, “do you see what they are doing—the great abominations that the house of Israel is committing—to drive Me far from My sanctuary? Yet you will see even greater abominations.”'),
  ('BSB', 'Ezekiel', 26, 8, 7, 'Then He brought me to the entrance to the court, and I looked and saw a hole in the wall.'),
  ('BSB', 'Ezekiel', 26, 8, 8, '“Son of man,” He told me, “dig through the wall.” So I dug through the wall and discovered a doorway.'),
  ('BSB', 'Ezekiel', 26, 8, 9, 'Then He said to me, “Go in and see the wicked abominations they are committing here.”'),
  ('BSB', 'Ezekiel', 26, 8, 10, 'So I went in and looked, and engraved all around the wall was every kind of crawling creature and detestable beast, along with all the idols of the house of Israel.'),
  ('BSB', 'Ezekiel', 26, 8, 11, 'Before them stood seventy elders of the house of Israel, with Jaazaniah son of Shaphan standing among them. Each had a censer in his hand, and a fragrant cloud of incense was rising.'),
  ('BSB', 'Ezekiel', 26, 8, 12, '“Son of man,” He said to me, “do you see what the elders of the house of Israel are doing in the darkness, each at the shrine of his own idol? For they are saying, ‘The LORD does not see us; the LORD has forsaken the land.’”'),
  ('BSB', 'Ezekiel', 26, 8, 13, 'Again, He told me, “You will see them committing even greater abominations.”'),
  ('BSB', 'Ezekiel', 26, 8, 14, 'Then He brought me to the entrance of the north gate of the house of the LORD, and I saw women sitting there, weeping for Tammuz.'),
  ('BSB', 'Ezekiel', 26, 8, 15, '“Son of man,” He said to me, “do you see this? Yet you will see even greater abominations than these.”'),
  ('BSB', 'Ezekiel', 26, 8, 16, 'So He brought me to the inner court of the house of the LORD, and there at the entrance to the temple of the LORD, between the portico and the altar, were about twenty-five men with their backs to the temple of the LORD and their faces toward the east; and they were bowing to the east in worship of the sun.'),
  ('BSB', 'Ezekiel', 26, 8, 17, '“Son of man,” He said to me, “do you see this? Is it not enough for the house of Judah to commit the abominations they are practicing here, that they must also fill the land with violence and continually provoke Me to anger? Look, they are even putting the branch to their nose!'),
  ('BSB', 'Ezekiel', 26, 8, 18, 'Therefore I will respond with wrath. I will not look on them with pity, nor will I spare them. Although they shout loudly in My ears, I will not listen to them.”'),
  ('BSB', 'Ezekiel', 26, 9, 1, 'Then I heard Him call out in a loud voice, saying, “Draw near, O executioners of the city, each with a weapon of destruction in hand.”'),
  ('BSB', 'Ezekiel', 26, 9, 2, 'And I saw six men coming from the direction of the Upper Gate, which faces north, each with a weapon of slaughter in his hand. With them was another man clothed in linen who had a writing kit at his side. And they came in and stood beside the bronze altar.'),
  ('BSB', 'Ezekiel', 26, 9, 3, 'Then the glory of the God of Israel rose from above the cherubim, where it had been, and moved to the threshold of the temple. And He called to the man clothed in linen who had the writing kit at his side.'),
  ('BSB', 'Ezekiel', 26, 9, 4, '“Go throughout the city of Jerusalem,” said the LORD, “and put a mark on the foreheads of the men sighing and groaning over all the abominations committed there.”'),
  ('BSB', 'Ezekiel', 26, 9, 5, 'And as I listened, He said to the others, “Follow him through the city and start killing; do not show pity or spare anyone!'),
  ('BSB', 'Ezekiel', 26, 9, 6, 'Slaughter the old men, the young men and maidens, the women and children; but do not go near anyone who has the mark. Now begin at My sanctuary.” So they began with the elders who were before the temple.'),
  ('BSB', 'Ezekiel', 26, 9, 7, 'Then He told them, “Defile the temple and fill the courts with the slain. Go forth!” So they went out and began killing throughout the city.'),
  ('BSB', 'Ezekiel', 26, 9, 8, 'While they were killing, I was left alone. And I fell facedown and cried out, “Oh, Lord GOD, when You pour out Your wrath on Jerusalem, will You destroy the entire remnant of Israel?”'),
  ('BSB', 'Ezekiel', 26, 9, 9, 'He replied, “The iniquity of the house of Israel and Judah is exceedingly great. The land is full of bloodshed, and the city is full of perversity. For they say, ‘The LORD has forsaken the land; the LORD does not see.’'),
  ('BSB', 'Ezekiel', 26, 9, 10, 'But as for Me, I will not look on them with pity, nor will I spare them. I will bring their deeds down upon their own heads.”'),
  ('BSB', 'Ezekiel', 26, 9, 11, 'Then the man clothed in linen with the writing kit at his side reported back, “I have done as You commanded.”'),
  ('BSB', 'Ezekiel', 26, 10, 1, 'And I looked and saw above the expanse, above the heads of the cherubim, the likeness of a throne of sapphire.'),
  ('BSB', 'Ezekiel', 26, 10, 2, 'And the LORD said to the man clothed in linen, “Go inside the wheelwork beneath the cherubim. Fill your hands with burning coals from among the cherubim and scatter them over the city.” And as I watched, he went in.'),
  ('BSB', 'Ezekiel', 26, 10, 3, 'Now when the man went in, the cherubim were standing on the south side of the temple, and a cloud filled the inner court.'),
  ('BSB', 'Ezekiel', 26, 10, 4, 'Then the glory of the LORD rose from above the cherubim and stood over the threshold of the temple. The temple was filled with the cloud, and the court was filled with the brightness of the glory of the LORD.'),
  ('BSB', 'Ezekiel', 26, 10, 5, 'The sound of the wings of the cherubim could be heard as far as the outer court, like the voice of God Almighty when He speaks.'),
  ('BSB', 'Ezekiel', 26, 10, 6, 'When the LORD commanded the man clothed in linen, saying, “Take fire from within the wheelwork, from among the cherubim,” the man went in and stood beside a wheel.'),
  ('BSB', 'Ezekiel', 26, 10, 7, 'Then one of the cherubim reached out his hand and took some of the fire that was among them. And he put it into the hands of the man clothed in linen, who received it and went out.'),
  ('BSB', 'Ezekiel', 26, 10, 8, '(The cherubim appeared to have the form of human hands under their wings.)'),
  ('BSB', 'Ezekiel', 26, 10, 9, 'Then I looked and saw four wheels beside the cherubim, one wheel beside each cherub. And the wheels gleamed like a beryl stone.'),
  ('BSB', 'Ezekiel', 26, 10, 10, 'As for their appearance, all four had the same form, like a wheel within a wheel.'),
  ('BSB', 'Ezekiel', 26, 10, 11, 'When they moved, they would go in any of the four directions, without turning as they moved. For wherever the head faced, the cherubim would go in that direction, without turning as they moved.'),
  ('BSB', 'Ezekiel', 26, 10, 12, 'Their entire bodies, including their backs, hands, and wings, were full of eyes all around, as were their four wheels.'),
  ('BSB', 'Ezekiel', 26, 10, 13, 'I heard the wheels being called “the whirling wheels.”'),
  ('BSB', 'Ezekiel', 26, 10, 14, 'Each of the cherubim had four faces: the first face was that of a cherub, the second that of a man, the third that of a lion, and the fourth that of an eagle.'),
  ('BSB', 'Ezekiel', 26, 10, 15, 'Then the cherubim rose upward. These were the living creatures I had seen by the River Kebar.'),
  ('BSB', 'Ezekiel', 26, 10, 16, 'When the cherubim moved, the wheels moved beside them, and even when they spread their wings to rise from the ground, the wheels did not veer away from their side.'),
  ('BSB', 'Ezekiel', 26, 10, 17, 'When the cherubim stood still, the wheels also stood still, and when they ascended, the wheels ascended with them, for the spirit of the living creatures was in the wheels.'),
  ('BSB', 'Ezekiel', 26, 10, 18, 'Then the glory of the LORD moved away from the threshold of the temple and stood above the cherubim.'),
  ('BSB', 'Ezekiel', 26, 10, 19, 'As I watched, the cherubim lifted their wings and rose up from the ground, with the wheels beside them as they went. And they stopped at the entrance of the east gate of the house of the LORD, with the glory of the God of Israel above them.'),
  ('BSB', 'Ezekiel', 26, 10, 20, 'These were the living creatures I had seen beneath the God of Israel by the River Kebar, and I knew that they were cherubim.'),
  ('BSB', 'Ezekiel', 26, 10, 21, 'Each had four faces and four wings, with what looked like human hands under their wings.'),
  ('BSB', 'Ezekiel', 26, 10, 22, 'Their faces looked like the faces I had seen by the River Kebar. Each creature went straight ahead.'),
  ('BSB', 'Ezekiel', 26, 11, 1, 'Then the Spirit lifted me up and brought me to the gate of the house of the LORD that faces east. And there at the entrance of the gate were twenty-five men. Among them I saw Jaazaniah son of Azzur and Pelatiah son of Benaiah, who were leaders of the people.'),
  ('BSB', 'Ezekiel', 26, 11, 2, 'And the LORD said to me, “Son of man, these are the men who plot evil and give wicked counsel in this city.'),
  ('BSB', 'Ezekiel', 26, 11, 3, 'They are saying, ‘Is not the time near to build houses? The city is the cooking pot, and we are the meat.’'),
  ('BSB', 'Ezekiel', 26, 11, 4, 'Therefore prophesy against them; prophesy, O son of man!”'),
  ('BSB', 'Ezekiel', 26, 11, 5, 'And the Spirit of the LORD fell upon me and told me to declare that this is what the LORD says: “That is what you are thinking, O house of Israel; and I know the thoughts that arise in your minds.'),
  ('BSB', 'Ezekiel', 26, 11, 6, 'You have multiplied those you killed in this city and filled its streets with the dead.'),
  ('BSB', 'Ezekiel', 26, 11, 7, 'Therefore this is what the Lord GOD says: The slain you have laid within this city are the meat, and the city is the pot; but I will remove you from it.'),
  ('BSB', 'Ezekiel', 26, 11, 8, 'You fear the sword, so I will bring the sword against you, declares the Lord GOD.'),
  ('BSB', 'Ezekiel', 26, 11, 9, 'I will bring you out of the city and deliver you into the hands of foreigners, and I will execute judgments against you.'),
  ('BSB', 'Ezekiel', 26, 11, 10, 'You will fall by the sword, and I will judge you even to the borders of Israel. Then you will know that I am the LORD.'),
  ('BSB', 'Ezekiel', 26, 11, 11, 'The city will not be a pot for you, nor will you be the meat within it. I will judge you even to the borders of Israel.'),
  ('BSB', 'Ezekiel', 26, 11, 12, 'Then you will know that I am the LORD. For you have neither followed My statutes nor practiced My ordinances, but you have conformed to the ordinances of the nations around you.”'),
  ('BSB', 'Ezekiel', 26, 11, 13, 'Now as I was prophesying, Pelatiah son of Benaiah died. Then I fell facedown and cried out in a loud voice, “Oh, Lord GOD, will You bring the remnant of Israel to a complete end?”'),
  ('BSB', 'Ezekiel', 26, 11, 14, 'Then the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 11, 15, '“Son of man, your brothers—your relatives, your fellow exiles, and the whole house of Israel—are those of whom the people of Jerusalem have said, ‘They are far away from the LORD; this land has been given to us as a possession.’'),
  ('BSB', 'Ezekiel', 26, 11, 16, 'Therefore declare that this is what the Lord GOD says: ‘Although I sent them far away among the nations and scattered them among the countries, yet for a little while I have been a sanctuary for them in the countries to which they have gone.’'),
  ('BSB', 'Ezekiel', 26, 11, 17, 'Therefore declare that this is what the Lord GOD says: ‘I will gather you from the peoples and assemble you from the countries to which you have been scattered, and I will give back to you the land of Israel.’'),
  ('BSB', 'Ezekiel', 26, 11, 18, 'When they return to it, they will remove all its detestable things and all its abominations.'),
  ('BSB', 'Ezekiel', 26, 11, 19, 'And I will give them singleness of heart and put a new spirit within them; I will remove their heart of stone and give them a heart of flesh,'),
  ('BSB', 'Ezekiel', 26, 11, 20, 'so that they may follow My statutes, keep My ordinances, and practice them. Then they will be My people, and I will be their God.'),
  ('BSB', 'Ezekiel', 26, 11, 21, 'But as for those whose hearts pursue detestable things and abominations, I will bring their conduct down upon their own heads, declares the Lord GOD.”'),
  ('BSB', 'Ezekiel', 26, 11, 22, 'Then the cherubim, with the wheels beside them, spread their wings, and the glory of the God of Israel was above them.'),
  ('BSB', 'Ezekiel', 26, 11, 23, 'And the glory of the LORD rose up from within the city and stood over the mountain east of the city.'),
  ('BSB', 'Ezekiel', 26, 11, 24, 'And the Spirit lifted me up and carried me back to Chaldea, to the exiles in the vision given by the Spirit of God. After the vision had gone up from me,'),
  ('BSB', 'Ezekiel', 26, 11, 25, 'I told the exiles everything the LORD had shown me.'),
  ('BSB', 'Ezekiel', 26, 12, 1, 'Then the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 12, 2, '“Son of man, you are living in a rebellious house. They have eyes to see but do not see, and ears to hear but do not hear, for they are a rebellious house.'),
  ('BSB', 'Ezekiel', 26, 12, 3, 'Therefore, son of man, pack your bags for exile. In broad daylight, set out from your place and go to another as they watch. Perhaps they will understand, though they are a rebellious house.'),
  ('BSB', 'Ezekiel', 26, 12, 4, 'Bring out your baggage for exile by day, as they watch. Then in the evening, as they watch, go out like those who go into exile.'),
  ('BSB', 'Ezekiel', 26, 12, 5, 'As they watch, dig through the wall and carry your belongings out through it.'),
  ('BSB', 'Ezekiel', 26, 12, 6, 'And as they watch, lift your bags to your shoulder and take them out at dusk; cover your face so that you cannot see the land. For I have made you a sign to the house of Israel.”'),
  ('BSB', 'Ezekiel', 26, 12, 7, 'So I did as I was commanded. I brought out my bags for exile by day, and in the evening I dug through the wall by hand. I took my belongings out at dusk, carrying them on my shoulder as they watched.'),
  ('BSB', 'Ezekiel', 26, 12, 8, 'And in the morning the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 12, 9, '“Son of man, hasn’t the rebellious house of Israel asked you, ‘What are you doing?’'),
  ('BSB', 'Ezekiel', 26, 12, 10, 'Tell them that this is what the Lord GOD says: ‘This burden concerns the prince in Jerusalem and all the house of Israel who are there.’'),
  ('BSB', 'Ezekiel', 26, 12, 11, 'You are to say, ‘I am a sign to you.’ Just as it happened here, so will it be done to them; they will go into exile as captives.'),
  ('BSB', 'Ezekiel', 26, 12, 12, 'And at dusk the prince among them will lift his bags to his shoulder and go out. They will dig through the wall to bring him out. He will cover his face so he cannot see the land.'),
  ('BSB', 'Ezekiel', 26, 12, 13, 'But I will spread My net over him, and he will be caught in My snare. I will bring him to Babylon, the land of the Chaldeans; yet he will not see it, and there he will die.'),
  ('BSB', 'Ezekiel', 26, 12, 14, 'And I will scatter to every wind all the attendants around him and all his troops, and I will draw a sword to chase after them.'),
  ('BSB', 'Ezekiel', 26, 12, 15, 'And they will know that I am the LORD, when I disperse them among the nations and scatter them throughout the countries.'),
  ('BSB', 'Ezekiel', 26, 12, 16, 'But I will spare a few of them from sword and famine and plague, so that in the nations to which they go, they can recount all their abominations. Then they will know that I am the LORD.”'),
  ('BSB', 'Ezekiel', 26, 12, 17, 'Moreover, the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 12, 18, '“Son of man, eat your bread with trembling, and drink your water with quivering and anxiety.'),
  ('BSB', 'Ezekiel', 26, 12, 19, 'Then tell the people of the land that this is what the Lord GOD says about those living in Jerusalem and in the land of Israel: ‘They will eat their bread with anxiety and drink their water in dread, for their land will be stripped of everything in it because of the violence of all who dwell in it.'),
  ('BSB', 'Ezekiel', 26, 12, 20, 'The inhabited cities will be laid waste, and the land will become desolate. Then you will know that I am the LORD.’”'),
  ('BSB', 'Ezekiel', 26, 12, 21, 'Again the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 12, 22, '“Son of man, what is this proverb that you have in the land of Israel: ‘The days go by, and every vision fails’?'),
  ('BSB', 'Ezekiel', 26, 12, 23, 'Therefore tell them that this is what the Lord GOD says: ‘I will put an end to this proverb, and in Israel they will no longer recite it.’ But say to them: ‘The days are at hand when every vision will be fulfilled.'),
  ('BSB', 'Ezekiel', 26, 12, 24, 'For there will be no more false visions or flattering divinations within the house of Israel,'),
  ('BSB', 'Ezekiel', 26, 12, 25, 'because I, the LORD, will speak whatever word I speak, and it will be fulfilled without delay. For in your days, O rebellious house, I will speak a message and bring it to pass, declares the Lord GOD.’”'),
  ('BSB', 'Ezekiel', 26, 12, 26, 'Furthermore, the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 12, 27, '“Son of man, take note that the house of Israel is saying, ‘The vision that he sees is for many years from now; he prophesies about the distant future.’'),
  ('BSB', 'Ezekiel', 26, 12, 28, 'Therefore tell them that this is what the Lord GOD says: ‘None of My words will be delayed any longer. The message I speak will be fulfilled, declares the Lord GOD.’”'),
  ('BSB', 'Ezekiel', 26, 13, 1, 'Then the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 13, 2, '“Son of man, prophesy against the prophets of Israel who are now prophesying. Tell those who prophesy out of their own imagination: Hear the word of the LORD!'),
  ('BSB', 'Ezekiel', 26, 13, 3, 'This is what the Lord GOD says: Woe to the foolish prophets who follow their own spirit, yet have seen nothing.'),
  ('BSB', 'Ezekiel', 26, 13, 4, 'Your prophets, O Israel, are like foxes among the ruins.'),
  ('BSB', 'Ezekiel', 26, 13, 5, 'You did not go up to the gaps or restore the wall around the house of Israel so that it would stand in the battle on the Day of the LORD.'),
  ('BSB', 'Ezekiel', 26, 13, 6, 'They see false visions and speak lying divinations. They claim, ‘Thus declares the LORD,’ when the LORD did not send them; yet they wait for the fulfillment of their message.'),
  ('BSB', 'Ezekiel', 26, 13, 7, 'Haven’t you seen a false vision and spoken a lying divination when you proclaim, ‘Thus declares the LORD,’ even though I have not spoken?'),
  ('BSB', 'Ezekiel', 26, 13, 8, 'Therefore this is what the Lord GOD says: Because you have uttered vain words and seen false visions, I am against you, declares the Lord GOD.'),
  ('BSB', 'Ezekiel', 26, 13, 9, 'My hand will be against the prophets who see false visions and speak lying divinations. They will not belong to the council of My people or be recorded in the register of the house of Israel, nor will they enter the land of Israel. Then you will know that I am the Lord GOD.'),
  ('BSB', 'Ezekiel', 26, 13, 10, 'Because they have led My people astray, saying, ‘Peace,’ when there is no peace, and whitewashing any flimsy wall that is built,'),
  ('BSB', 'Ezekiel', 26, 13, 11, 'tell those whitewashing the wall that it will fall. Rain will come in torrents, I will send hailstones plunging down, and a windstorm will burst forth.'),
  ('BSB', 'Ezekiel', 26, 13, 12, 'Surely when the wall has fallen, you will not be asked, ‘Where is the whitewash with which you covered it?’'),
  ('BSB', 'Ezekiel', 26, 13, 13, 'Therefore this is what the Lord GOD says: In My wrath I will release a windstorm, and in My anger torrents of rain and hail will fall with destructive fury.'),
  ('BSB', 'Ezekiel', 26, 13, 14, 'I will tear down the wall you whitewashed and level it to the ground, so that its foundation is exposed. The city will fall, and you will be destroyed within it. Then you will know that I am the LORD.'),
  ('BSB', 'Ezekiel', 26, 13, 15, 'And after I have vented My wrath against the wall and against those who whitewashed it, I will say to you: ‘The wall is gone, and so are those who whitewashed it—'),
  ('BSB', 'Ezekiel', 26, 13, 16, 'those prophets of Israel who prophesied to Jerusalem and saw a vision of peace for her when there was no peace, declares the Lord GOD.’'),
  ('BSB', 'Ezekiel', 26, 13, 17, 'Now, O son of man, set your face against the daughters of your people who prophesy out of their own imagination. Prophesy against them'),
  ('BSB', 'Ezekiel', 26, 13, 18, 'and tell them that this is what the Lord GOD says: Woe to the women who sew magic charms on their wrists and make veils for the heads of people of every height, in order to ensnare their souls. Will you ensnare the souls of My people but preserve your own?'),
  ('BSB', 'Ezekiel', 26, 13, 19, 'You have profaned Me among My people for handfuls of barley and scraps of bread. By lying to My people who would listen, you have killed those who should not have died and spared those who should not have lived.'),
  ('BSB', 'Ezekiel', 26, 13, 20, 'Therefore this is what the Lord GOD says: See, I am against the magic charms with which you ensnare souls like birds, and I will tear them from your arms. So I will free the souls you have ensnared like birds.'),
  ('BSB', 'Ezekiel', 26, 13, 21, 'I will also tear off your veils and deliver My people from your hands, so that they will no longer be prey in your hands. Then you will know that I am the LORD.'),
  ('BSB', 'Ezekiel', 26, 13, 22, 'Because you have disheartened the righteous with your lies, even though I have caused them no grief, and because you have encouraged the wicked not to turn from their evil ways to save their lives,'),
  ('BSB', 'Ezekiel', 26, 13, 23, 'therefore you will no longer see false visions or practice divination. I will deliver My people from your hands. Then you will know that I am the LORD.”'),
  ('BSB', 'Ezekiel', 26, 14, 1, 'Then some of the elders of Israel came and sat down before me.'),
  ('BSB', 'Ezekiel', 26, 14, 2, 'And the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 14, 3, '“Son of man, these men have set up idols in their hearts and put wicked stumbling blocks before their faces. Should I consult with them in any way?'),
  ('BSB', 'Ezekiel', 26, 14, 4, 'Therefore speak to them and tell them that this is what the Lord GOD says: ‘When any Israelite sets up idols in his heart and puts a wicked stumbling block before his face, and then comes to the prophet, I the LORD will answer him according to his great idolatry,'),
  ('BSB', 'Ezekiel', 26, 14, 5, 'so that I may take hold of the hearts of the people of Israel. For because of their idols, they are all estranged from Me.’'),
  ('BSB', 'Ezekiel', 26, 14, 6, 'Therefore tell the house of Israel that this is what the Lord GOD says: ‘Repent and turn away from your idols; turn your faces away from all your abominations.'),
  ('BSB', 'Ezekiel', 26, 14, 7, 'For when any Israelite or any foreigner dwelling in Israel separates himself from Me, sets up idols in his heart, and puts a wicked stumbling block before his face, and then comes to the prophet to inquire of Me, I the LORD will answer him Myself.'),
  ('BSB', 'Ezekiel', 26, 14, 8, 'I will set My face against that man and make him a sign and a proverb; I will cut him off from among My people. Then you will know that I am the LORD.'),
  ('BSB', 'Ezekiel', 26, 14, 9, 'But if the prophet is enticed to speak a message, then it was I the LORD who enticed him, and I will stretch out My hand against him and destroy him from among My people Israel.'),
  ('BSB', 'Ezekiel', 26, 14, 10, 'They will bear their punishment—the punishment of the inquirer will be the same as that of the prophet—'),
  ('BSB', 'Ezekiel', 26, 14, 11, 'in order that the house of Israel may no longer stray from Me and no longer defile themselves with all their transgressions. Then they will be My people and I will be their God, declares the Lord GOD.’”'),
  ('BSB', 'Ezekiel', 26, 14, 12, 'And the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 14, 13, '“Son of man, if a land sins against Me by acting unfaithfully, and I stretch out My hand against it to cut off its supply of food, to send famine upon it, and to cut off from it both man and beast,'),
  ('BSB', 'Ezekiel', 26, 14, 14, 'then even if these three men—Noah, Daniel, and Job—were in it, their righteousness could deliver only themselves, declares the Lord GOD.'),
  ('BSB', 'Ezekiel', 26, 14, 15, 'Or if I send wild beasts through the land to leave it childless and desolate, with no man passing through it for fear of the beasts,'),
  ('BSB', 'Ezekiel', 26, 14, 16, 'then as surely as I live, declares the Lord GOD, even if these three men were in it, they could not deliver their own sons or daughters. They alone would be delivered, but the land would be desolate.'),
  ('BSB', 'Ezekiel', 26, 14, 17, 'Or if I bring a sword against that land and say, ‘Let a sword pass through it,’ so that I cut off from it both man and beast,'),
  ('BSB', 'Ezekiel', 26, 14, 18, 'then as surely as I live, declares the Lord GOD, even if these three men were in it, they could not deliver their own sons or daughters. They alone would be delivered.'),
  ('BSB', 'Ezekiel', 26, 14, 19, 'Or if I send a plague into that land and pour out My wrath upon it through bloodshed, cutting off from it both man and beast,'),
  ('BSB', 'Ezekiel', 26, 14, 20, 'then as surely as I live, declares the Lord GOD, even if Noah, Daniel, and Job were in it, they could not deliver their own sons or daughters. Their righteousness could deliver only themselves.'),
  ('BSB', 'Ezekiel', 26, 14, 21, 'For this is what the Lord GOD says: ‘How much worse will it be when I send against Jerusalem My four dire judgments—sword, famine, wild beasts, and plague—in order to cut off from it both man and beast?'),
  ('BSB', 'Ezekiel', 26, 14, 22, 'Yet, behold, some survivors will be left in it—sons and daughters who will be brought out. They will come out to you, and when you see their conduct and actions, you will be comforted regarding the disaster I have brought upon Jerusalem—all that I have brought upon it.'),
  ('BSB', 'Ezekiel', 26, 14, 23, 'They will bring you consolation when you see their conduct and actions, and you will know that it was not without cause that I have done all these things within it,’ declares the Lord GOD.”'),
  ('BSB', 'Ezekiel', 26, 15, 1, 'Then the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 15, 2, '“Son of man, how does the wood of the vine surpass any other branch among the trees in the forest?'),
  ('BSB', 'Ezekiel', 26, 15, 3, 'Can wood be taken from it to make something useful? Or can one make from it a peg on which to hang utensils?'),
  ('BSB', 'Ezekiel', 26, 15, 4, 'No, it is cast into the fire for fuel. The fire devours both ends, and the middle is charred. Can it be useful for anything?'),
  ('BSB', 'Ezekiel', 26, 15, 5, 'Even when it was whole, it could not be made useful. How much less can it ever be useful when the fire has consumed it and charred it!'),
  ('BSB', 'Ezekiel', 26, 15, 6, 'Therefore this is what the Lord GOD says: ‘Like the wood of the vine among the trees of the forest, which I have given to the fire for fuel, so I will give up the people of Jerusalem.'),
  ('BSB', 'Ezekiel', 26, 15, 7, 'And I will set My face against them. Though they may have escaped the fire, yet another fire will consume them. And when I set My face against them, you will know that I am the LORD.'),
  ('BSB', 'Ezekiel', 26, 15, 8, 'Thus I will make the land desolate, because they have acted unfaithfully,’ declares the Lord GOD.”'),
  ('BSB', 'Ezekiel', 26, 16, 1, 'Again the word of the LORD came to me, saying,'),
  ('BSB', 'Ezekiel', 26, 16, 2, '“Son of man, confront Jerusalem with her abominations'),
  ('BSB', 'Ezekiel', 26, 16, 3, 'and tell her that this is what the Lord GOD says to Jerusalem: Your origin and your birth were in the land of the Canaanites. Your father was an Amorite and your mother a Hittite.'),
  ('BSB', 'Ezekiel', 26, 16, 4, 'On the day of your birth your cord was not cut, nor were you washed with water for cleansing. You were not rubbed with salt or wrapped in cloths.'),
  ('BSB', 'Ezekiel', 26, 16, 5, 'No one cared enough for you to do even one of these things out of compassion for you. Instead, you were thrown out into the open field, because you were despised on the day of your birth.'),
  ('BSB', 'Ezekiel', 26, 16, 6, 'Then I passed by and saw you wallowing in your blood, and as you lay there in your blood I said to you, ‘Live!’ There I said to you, ‘Live!’'),
  ('BSB', 'Ezekiel', 26, 16, 7, 'I made you thrive like a plant of the field. You grew up and matured and became very beautiful. Your breasts were formed and your hair grew, but you were naked and bare.'),
  ('BSB', 'Ezekiel', 26, 16, 8, 'Then I passed by and saw you, and you were indeed old enough for love. So I spread My cloak over you and covered your nakedness. I pledged Myself to you, entered into a covenant with you, and you became Mine, declares the Lord GOD.'),
  ('BSB', 'Ezekiel', 26, 16, 9, 'Then I bathed you with water, rinsed off your blood, and anointed you with oil.'),
  ('BSB', 'Ezekiel', 26, 16, 10, 'I clothed you in embroidered cloth and gave you sandals of fine leather. I wrapped you in fine linen and covered you with silk.'),
  ('BSB', 'Ezekiel', 26, 16, 11, 'I adorned you with jewelry, and I put bracelets on your wrists and a chain around your neck.'),
  ('BSB', 'Ezekiel', 26, 16, 12, 'I put a ring in your nose, earrings on your ears, and a beautiful crown upon your head.'),
  ('BSB', 'Ezekiel', 26, 16, 13, 'So you were adorned with gold and silver, and your clothing was made of fine linen, silk, and embroidered cloth. You ate fine flour, honey, and oil. You became very beautiful and rose to be queen.'),
  ('BSB', 'Ezekiel', 26, 16, 14, 'Your fame spread among the nations on account of your beauty, for it was perfect in the splendor I bestowed on you, declares the Lord GOD.'),
  ('BSB', 'Ezekiel', 26, 16, 15, 'But because of your fame, you trusted in your beauty and played the harlot. You lavished your favors on everyone who passed by, and your beauty was theirs for the asking.'),
  ('BSB', 'Ezekiel', 26, 16, 16, 'You took some of your garments and made colorful high places for yourself, and on them you prostituted yourself. Such things should not have happened; never should they have occurred!'),
  ('BSB', 'Ezekiel', 26, 16, 17, 'You also took the fine jewelry of gold and silver I had given you, and you made male idols with which to prostitute yourself.'),
  ('BSB', 'Ezekiel', 26, 16, 18, 'You took your embroidered garments to cover them, and you set My oil and incense before them.'),
  ('BSB', 'Ezekiel', 26, 16, 19, 'And you set before them as a pleasing aroma the food I had given you—the fine flour, oil, and honey that I had fed you. That is what happened, declares the Lord GOD.'),
  ('BSB', 'Ezekiel', 26, 16, 20, 'You even took the sons and daughters you bore to Me and sacrificed them as food to idols. Was your prostitution not enough?'),
  ('BSB', 'Ezekiel', 26, 16, 21, 'You slaughtered My children and delivered them up through the fire to idols.'),
  ('BSB', 'Ezekiel', 26, 16, 22, 'And in all your abominations and acts of prostitution, you did not remember the days of your youth when you were naked and bare, wallowing in your own blood.'),
  ('BSB', 'Ezekiel', 26, 16, 23, 'Woe! Woe to you, declares the Lord GOD. And in addition to all your other wickedness,'),
  ('BSB', 'Ezekiel', 26, 16, 24, 'you built yourself a mound and made yourself a lofty shrine in every public square.'),
  ('BSB', 'Ezekiel', 26, 16, 25, 'At the head of every street you built your lofty shrines and degraded your beauty. With increasing promiscuity, you spread your legs to all who passed by.'),
  ('BSB', 'Ezekiel', 26, 16, 26, 'You prostituted yourself with your lustful neighbors, the Egyptians, and increased your promiscuity to provoke Me to anger.'),
  ('BSB', 'Ezekiel', 26, 16, 27, 'Therefore I stretched out My hand against you and reduced your portion. I gave you over to the desire of those who hate you, the daughters of the Philistines, who were ashamed of your lewd conduct.'),
  ('BSB', 'Ezekiel', 26, 16, 28, 'Then you prostituted yourself with the Assyrians, because you were not yet satisfied. Even after that, you were still not satisfied.'),
  ('BSB', 'Ezekiel', 26, 16, 29, 'So you extended your promiscuity to Chaldea, the land of merchants—but even with this you were not satisfied!'),
  ('BSB', 'Ezekiel', 26, 16, 30, 'How weak-willed is your heart, declares the Lord GOD, while you do all these things, the acts of a shameless prostitute!'),
  ('BSB', 'Ezekiel', 26, 16, 31, 'But when you built your mounds at the head of every street and made your lofty shrines in every public square, you were not even like a prostitute, because you scorned payment.'),
  ('BSB', 'Ezekiel', 26, 16, 32, 'You adulterous wife! You receive strangers instead of your own husband!'),
  ('BSB', 'Ezekiel', 26, 16, 33, 'Men give gifts to all their prostitutes, but you gave gifts to all your lovers. You bribed them to come to you from everywhere for your illicit favors.'),
  ('BSB', 'Ezekiel', 26, 16, 34, 'So your prostitution is the opposite of that of other women: No one solicited your favors, and you paid a fee instead of receiving one; so you are the very opposite!'),
  ('BSB', 'Ezekiel', 26, 16, 35, 'Therefore, O prostitute, hear the word of the LORD!'),
  ('BSB', 'Ezekiel', 26, 16, 36, 'This is what the Lord GOD says: Because you poured out your wealth and exposed your nakedness in your promiscuity with your lovers and with all your detestable idols, and because of the blood of your children which you gave to them,'),
  ('BSB', 'Ezekiel', 26, 16, 37, 'therefore I will surely gather all the lovers with whom you found pleasure, all those you loved and all those you hated. I will gather them against you from all around and expose you before them, and they will see you completely naked.');
